/*
 * MLX91219 Hall-Effect Current Sensor Reader via ADS1115 ADC
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: MLX91219 (ADDR pin tied to GND)
 * ADC:    ADS1115 (ADDR pin tied to GND)
 *
 * Wiring:
 *   MLX91219 VCC  -> 3.3 V
 *   MLX91219 GND  -> GND
 *   MLX91219 OUT  -> ADS1115 AIN0
 *   ADS1115 VDD  -> 3.3 V
 *   ADS1115 GND  -> GND
 *   ADS1115 SDA  -> GPIO2 (BCM)
 *   ADS1115 SCL  -> GPIO3 (BCM)
 *   ADS1115 ADDR -> GND (I2C address 0x48)
 *
 * Build:  gcc -O2 -Wall -o mlx91219_reader mlx91219_reader.c -lpigpio -lrt
 * Run:    sudo ./mlx91219_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADS1115 constants ---- */
#define I2C_BUS            1
#define ADS1115_ADDR       0x48          /* ADDR pin tied to GND */

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bit fields (16-bit, big-endian on the wire) */
#define ADS1115_CFG_OS_BEGIN   (1u << 15)   /* Write 1 to start a single conversion */
#define ADS1115_CFG_MUX_AIN0  (4u << 12)   /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4_096 (1u << 9)    /* ±4.096 V range */
#define ADS1115_CFG_MODE_SS   (1u << 8)    /* Single-shot mode */
#define ADS1115_CFG_DR_128    (4u << 5)    /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE (3u << 0)    /* Disable comparator */

#define ADS1115_PGA_4_096_V   4.096f
#define ADS1115_MAX_COUNT     32767.0f     /* 16-bit signed positive full-scale */

/* ---- MLX91219 calibration (example values) ---- */
#define MLX91219_SENSITIVITY  0.001f       /* Amperes per volt */
#define MLX91219_OFFSET       0.0f         /* Volts */

/* ---- Timing ---- */
#define SAMPLE_PERIOD_US    500000       /* 500 ms */
#define CONV_WAIT_US        10000        /* 10 ms for 128 SPS conversion */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register (big-endian on the wire). */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register (big-endian on the wire). */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value)
{
    char reg_buf[1] = { (char)reg };
    char data_buf[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select) failed for reg 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed for reg 0x%02X\n", reg);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single-shot conversion on AIN0 and read the result.      */
static int ads1115_read_ain0(int handle, float *voltage)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    gpioDelay(CONV_WAIT_US);

    uint16_t raw;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    int16_t signed_raw = (int16_t)raw;
    *voltage = (float)signed_raw * ADS1115_PGA_4_096_V / ADS1115_MAX_COUNT;
    return 0;
}

/* ------------------------------------------------------------------ */
static float voltage_to_current(float voltage)
{
    return (voltage - MLX91219_OFFSET) * MLX91219_SENSITIVITY;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus to ADS1115 ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify ADS1115 is present by reading the config register ---- */
    uint16_t cfg_check;
    if (ads1115_read_reg(g_i2c_handle, ADS1115_REG_CONFIG, &cfg_check) != 0) {
        fprintf(stderr, "[FATAL] ADS1115 not responding at 0x%02X — check wiring and ADDR pin\n",
                ADS1115_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 Current Sensor Reader\n");
    printf("ADC: ADS1115 on I2C bus %d, address 0x%02X\n", I2C_BUS, ADS1115_ADDR);
    printf("Sensor: MLX91219 (ADDR pin tied to GND, analog OUT -> ADS1115 AIN0)\n");
    printf("Press Ctrl+C to exit.\n\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float voltage;
        if (ads1115_read_ain0(g_i2c_handle, &voltage) != 0) {
            fprintf(stderr, "[WARN] ADC read failed — continuing\n");
        } else {
            float current = voltage_to_current(voltage);
            printf("Voltage: %.4f V  |  Current: %.4f A\n", voltage, current);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

