/*
 * Fire Detection System for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - Keyes KY-026 Flame Sensor  -> GPIO4  (BCM, digital input)
 *   - LM393 Heat Sensor (analog) -> ADS1115 AIN0 (single-ended)
 *   - Active-HIGH buzzer        -> GPIO27 (BCM, digital output)
 *   - ADS1115 on I2C bus 1, address 0x48
 *
 * Behavior:
 *   Polls both sensors every 100 ms with a 50 ms debounce on the flame
 *   sensor.  When both sensors indicate a fire condition (flame +
 *   temperature > 60 C), the buzzer sounds for 2 s, a fire event is
 *   logged to fire_log.txt, and the program continues.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o fire_detect fire_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */
#define FLAME_SENSOR_PIN      4
#define BUZZER_PIN            27
#define I2C_BUS               "/dev/i2c-1"
#define ADS1115_ADDR          0x48
#define ADS1115_REG_CONV      0x00
#define ADS1115_REG_CONFIG    0x01
#define TEMP_THRESHOLD_C      60.0f
#define POLL_INTERVAL_US      100000   /* 100 ms */
#define DEBOUNCE_US           50000    /* 50 ms  */
#define BUZZER_DURATION_S     2
#define LOG_FILE_NAME         "fire_log.txt"

/* ADS1115 config: single-shot, AIN0 single-ended, +/-4.096 V, 128 SPS */
#define ADS1115_CFG_BASE      0x8000   /* OS bit */
#define ADS1115_CFG_MUX_AIN0  0x4000   /* MUX[14:12] = 100 */
#define ADS1115_CFG_PGA_4_096 0x0200   /* PGA[11:9]  = 001 */
#define ADS1115_CFG_MODE_SS  0x0100   /* MODE[8]   = 1 (single-shot) */
#define ADS1115_CFG_DR_128   0x0080   /* DR[7:5]   = 100 */
#define ADS1115_CFG_CQUE_NONE 0x0003  /* COMP_QUE[1:0] = 11 (disable) */
#define ADS1115_CFG_FULL     (ADS1115_CFG_BASE | ADS1115_CFG_MUX_AIN0 | \
                            ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SS | \
                            ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE)

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static int   g_i2c_fd = -1;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  init_gpio(void);
static int  init_i2c(void);
static int  read_ads1115(float *temperature);
static bool is_flame_detected(void);
static void activate_buzzer(int duration_seconds);
static void log_event(const char *message);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- GPIO ------------------------------------ */
static int init_gpio(void)
{
    /*
     * gpiod is the Linux GPIO character-device API (libgpiod).
     * The Raspberry Pi 3 Model B+ exposes BCM GPIO pins via the gpiochip0
     * device; libgpiod exposes a consistent interface across kernels and
     * chip revisions.
     *
     * We use the standard Linux gpiochip character-device interface
     * (gpiochip0) for portability and simplicity.
     */
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    /* Request flame sensor pin as input */
    if (ioctl(fd, 8004, FLAME_SENSOR_PIN) < 0) {
        fprintf(stderr, "Error requesting GPIO%d as input: %s\n",
                FLAME_SENSOR_PIN, strerror(errno));
        close(fd);
        return -1;
    }

    /* Request buzzer pin as output, initial value LOW */
    if (ioctl(fd, 8003, BUZZER_PIN) < 0) {
        fprintf(stderr, "Error requesting GPIO%d as output: %s\n",
                BUZZER_PIN, strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, 8001, BUZZER_PIN) < 0) {
        fprintf(stderr, "Error setting GPIO%d LOW: %s\n",
                BUZZER_PIN, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------- I2C ------------------------------------- */
static int init_i2c(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n",
                I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read temperature from ADS1115 AIN0 (single-ended).
 *
 * Returns 0 on success and stores the temperature in Celsius in *temperature.
 * Returns -1 on I2C error or if the sensor is not present.
 */
static int read_ads1115(float *temperature)
{
    uint8_t config[3];
    uint8_t conv[2];
    int16_t raw;

    /* Write config: single-shot, AIN0, +/-4.096 V, 128 SPS, disable comparator */
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CFG_FULL >> 8) & 0xFF;
    config[2] = ADS1115_CFG_FULL & 0xFF;

    if (write(g_i2c_fd, config, 3) != 3) {
        fprintf(stderr, "Error writing ADS1115 config: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    /* Point to conversion register */
    if (write(g_i2c_fd, (uint8_t[]){ADS1115_REG_CONV}, 1) != 1) {
        fprintf(stderr, "Error selecting ADS1115 conversion register: %s\n",
                strerror(errno));
        return -1;
    }

    /* Read 2 bytes of conversion data */
    if (read(g_i2c_fd, conv, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion data: %s\n",
                strerror(errno));
        return -1;
    }

    raw = (int16_t)((conv[0] << 8) | conv[1]);

    /*
     * ADS1115 PGA = +/-4.096 V  -> 1 bit = 125 uV
     * LM393 gain = 2.5 V/°C     -> 1 °C = 4000 counts
     *
     * Temperature = raw * 125 uV / 4000 counts / 1000 = raw * 0.000003125
     */
    *temperature = (float)raw * 0.000003125f;
    return 0;
}

/* --------------------------- Flame detection ----------------------------- */
static bool is_flame_detected(void)
{
    static int last_state = 0;
    int current_state = (ioctl(g_i2c_fd, 8002, FLAME_SENSOR_PIN) == 1) ? 1 : 0;

    if (current_state == 1 && last_state == 0) {
        usleep(DEBOUNCE_US);
        current_state = (ioctl(g_i2c_fd, 8002, FLAME_SENSOR_PIN) == 1) ? 1 : 0;
    }

    last_state = current_state;
    return (current_state == 1);
}

/* ----------------------------- Buzzer ----------------------------------- */
static void activate_buzzer(int duration_seconds)
{
    if (ioctl(g_i2c_fd, 8003, BUZZER_PIN) < 0) {
        fprintf(stderr, "Error setting buzzer HIGH: %s\n", strerror(errno));
        return;
    }

    sleep(duration_seconds);

    if (ioctl(g_i2c_fd, 8001, BUZZER_PIN) < 0) {
        fprintf(stderr, "Error setting buzzer LOW: %s\n", strerror(errno));
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *message)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s: %s\n", timestamp, message);
        fflush(g_log_fp);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Ensure buzzer is off */
    if (g_i2c_fd >= 0) {
        ioctl(g_i2c_fd, 8001, BUZZER_PIN);
    }

    /* Close I2C device */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    /* Close log file */
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    /* Close gpiochip0 device (if still open) */
    /*
     * The gpiochip0 device is not closed here because the libgpiod
     * character-device interface does not expose a close() operation.
     * The device is closed when the process exits, but we explicitly
     * release the file descriptor for clarity.
     */
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n",
                strerror(errno));
        return 1;
    }

    /* Initialize GPIO */
    g_i2c_fd = init_gpio();
    if (g_i2c_fd < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    /* Initialize I2C */
    g_i2c_fd = init_i2c();
    if (g_i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed.\n");
        cleanup();
        return 1;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");
    log_event("System started.");

    /* Main loop */
    while (g_running) {
        float temperature = 0.0f;
        bool flame_detected = is_flame_detected();

        if (read_ads1115(&temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);

            if (flame_detected) {
                printf("Flame detected!\n");
                log_event("Flame detected!");

                if (temperature > TEMP_THRESHOLD_C) {
                    printf("Temperature exceeds threshold! Activating buzzer.\n");
                    log_event("Temperature exceeds threshold!");
                    activate_buzzer(BUZZER_DURATION_S);
                }
            } else {
                if (temperature > TEMP_THRESHOLD_C) {
                    printf("Temperature exceeds threshold!\n");
                    log_event("Temperature exceeds threshold!");
                }
            }
        } else {
            fprintf(stderr, "Error reading temperature from ADS1115.\n");
            log_event("Error reading temperature from ADS1115.");
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    log_event("System shutting down.");
    cleanup();
    return 0;
}

code:
/*
 * MLX91219 Current Sensor Monitor with MCP3008 ADC and Fan Control
 * Board:  Raspberry Pi 5
 * ADC:    MCP3008 on SPI0 CE0 (spidev0.0), 1 MHz, mode 0, 8 bits/word
 * Sensor: Melexis MLX91219 (SOIC-8)
 * Fan:    GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U
#define SPI_BITS_PER_WORD 8U
#define SPI_MODE          SPI_MODE_0

#define FAN_GPIO_LINE     18          /* BCM 18 */
#define GPIO_CHIP_NAME    "gpiochip4" /* Pi 5 default GPIO chip */

#define CURRENT_THRESHOLD 100.0f      /* Amperes */
#define LOG_FILE          "current_log.txt"
#define SAMPLE_INTERVAL_S 1

/* MCP3008 single-ended channel 0 (MLX91219 analog output) */
#define ADC_CHANNEL       0

/* Sensor-absent / bus-error sentinel values */
#define ADC_ERROR_VALUE   0x00
#define ADC_MAX_VALUE     0xFF

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static struct gpiod_chip  *g_chip  = NULL;
static struct gpiod_line  *g_fan_line = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (clock out low bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        /* Fallback: try gpiochip0 on older kernels */
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    g_fan_line = gpiod_chip_get_line(g_chip, FAN_GPIO_LINE);
    if (!g_fan_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                FAN_GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_fan_line, "current_monitor", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        g_fan_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void fan_set(int on)
{
    if (g_fan_line) {
        if (gpiod_line_set_value(g_fan_line, on ? 1 : 0) < 0) {
            fprintf(stderr, "gpiod_line_set_value(%d): %s\n",
                    on ? 1 : 0, strerror(errno));
        }
    }
}

/* ------------------------------------------------------------------ */
static void log_reading(float current)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Current: %.2f A\n", ts, current);
    } else {
        fprintf(fp, "(timestamp-error), Current: %.2f A\n", current);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fan_line) {
        gpiod_line_set_value(g_fan_line, 0);
        gpiod_line_release(g_fan_line);
        g_fan_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc = mcp3008_read(g_spi_fd, ADC_CHANNEL);

        if (adc < 0) {
            fprintf(stderr, "ADC read error; fan OFF for safety.\n");
            fan_set(0);
            log_reading(-1.0f);
        } else if (adc == ADC_ERROR_VALUE || adc == ADC_MAX_VALUE) {
            fprintf(stderr,
                    "ADC saturated (0x%02X) — sensor absent or bus error.\n",
                    adc);
            fan_set(0);
            log_reading(-1.0f);
        } else {
            float current = (float)adc * (3.3f / 1023.0f) * 1000.0f;
            printf("Current: %.2f A\n", current);

            if (current > CURRENT_THRESHOLD) {
                fan_set(1);
            } else {
                fan_set(0);
            }

            log_reading(current);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

