    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (clock out low bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        /* Fallback: try gpiochip0 on older kernels */
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    g_fan_line = gpiod_chip_get_line(g_chip, FAN_GPIO_LINE);
    if (!g_fan_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                FAN_GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_fan_line, "current_monitor", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        g_fan_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void fan_set(int on)
{
    if (g_fan_line) {
        if (gpiod_line_set_value(g_fan_line, on ? 1 : 0) < 0) {
            fprintf(stderr, "gpiod_line_set_value(%d): %s\n",
                    on ? 1 : 0, strerror(errno));
        }
    }
}

/* ------------------------------------------------------------------ */
static void log_reading(float current)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Current: %.2f A\n", ts, current);
    } else {
        fprintf(fp, "(timestamp-error), Current: %.2f A\n", current);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fan_line) {
        gpiod_line_set_value(g_fan_line, 0);
        gpiod_line_release(g_fan_line);
        g_fan_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc = mcp3008_read(g_spi_fd, ADC_CHANNEL);

        if (adc < 0) {
            fprintf(stderr, "ADC read error; fan OFF for safety.\n");
            fan_set(0);
            log_reading(-1.0f);
        } else if (adc == ADC_ERROR_VALUE || adc == ADC_MAX_VALUE) {
            fprintf(stderr,
                    "ADC saturated (0x%02X) — sensor absent or bus error.\n",
                    adc);
            fan_set(0);
            log_reading(-1.0f);
        } else {
            float current = (float)adc * (3.3f / 1023.0f) * 1000.0f;
            printf("Current: %.2f A\n", current);

            if (current > CURRENT_THRESHOLD) {
                fan_set(1);
            } else {
                fan_set(0);
            }

            log_reading(current);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

