/*
 * Raspberry Pi 4 Model B – Honeywell/SGX MICROceL MICS-4514 CO Sensor Reader
 *
 * Reads a dual-element MOS sensor via I2C bus 1 and converts the raw
 * 16-bit ADC reading to a CO concentration (ppm) using a calibrated
 * logarithmic curve.  Logs timestamped ppm values to co_log.txt every 5 s.
 *
 * Wiring:
 *   MICS-4514 VCC  -> Pi 3V3 (Pin 1)
 *   MICS-4514 GND  -> Pi GND (Pin 9)
 *   MICS-4514 SDA  -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *   MICS-4514 SCL  -> Pi GPIO3 / I2C1 SCL (Pin 5)
 *   MICS-4514 AOUT -> ADS1115 AIN0 (simulated 16-bit ADC)
 *
 * Build:  gcc -O2 -Wall -o co_reader co_reader.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS             1
#define I2C_ADDR            0x58          /* MICS-4514 default I2C address */
#define ADS1115_ADDR        0x48          /* ADS1115 default I2C address   */

#define ADS1115_REG_CONV    0x00
#define ADS1115_REG_CONFIG  0x01

/* Config: AIN0 single-ended, +/-4.096 V, 128 SPS, continuous */
#define ADS1115_CFG_BASE    0x8000        /* OS bit */
#define ADS1115_CFG_MUX_0  0x4000        /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4  0x0200        /* +/-4.096 V */
#define ADS1115_CFG_MODE   0x0100        /* Continuous */
#define ADS1115_CFG_DR_128 0x0080        /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE 0x0003     /* Disable comparator */

#define ADS1115_CFG_FULL   (ADS1115_CFG_BASE | ADS1115_CFG_MUX_0 | \
                          ADS1115_CFG_PGA_4 | ADS1115_CFG_MODE | \
                          ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE)

#define LOG_FILE            "co_log.txt"
#define SAMPLE_INTERVAL_S   5
#define MAX_RETRIES         3
#define CONV_TIMEOUT_US     100000        /* 100 ms for 128 SPS */

/* --------------------------- Calibration Data ----------------------------- */

/*
 * Calibration curve parameters for the MICS-4514 dual-element sensor.
 * These values are placeholders; replace them with actual calibration
 * data obtained from the sensor datasheet.
 */
static const float CO_A = 0.001f;
static const float CO_B = 0.0f;
static const float CO_C = 0.0f;

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_ads1115_handle = -1;

/* --------------------------- Signal Handler ------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Utility Functions ----------------------------- */

/*
 * Write a 16-bit value to an ADS1115 register.
 * Returns 0 on success, -1 on failure.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "ads1115_write_reg(reg=0x%02X): i2cWriteDevice failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * Returns 0 on success and stores the value in *out, -1 on failure.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data_buf[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "ads1115_read_reg(reg=0x%02X): i2cWriteDevice failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "ads1115_read_reg(reg=0x%02X): i2cReadDevice failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and wait for completion.
 * Returns 0 on success and stores the raw ADC value in *raw, -1 on failure.
 */
static int ads1115_read_ain0(int handle, int16_t *raw)
{
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, ADS1115_CFG_FULL) != 0)
        return -1;

    /* Wait for conversion to complete (128 SPS -> ~7.8 ms; use 10 ms margin) */
    gpioDelay(CONV_TIMEOUT_US);

    uint16_t cfg;
    if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) != 0)
        return -1;

    if (!(cfg & 0x8000)) {
        fprintf(stderr, "ads1115_read_ain0: conversion not complete (OS bit clear)\n");
        return -1;
    }

    uint16_t conv;
    if (ads1115_read_reg(handle, ADS1115_REG_CONV, &conv) != 0)
        return -1;

    *raw = (int16_t)conv;
    return 0;
}

/*
 * Convert raw ADC value to CO concentration (ppm) using the
 * calibrated logarithmic curve.
 */
static float raw_to_ppm(int16_t raw)
{
    /*
     * Placeholder conversion.  Replace with the actual calibration
     * curve from the MICS-4514 datasheet.
     */
    float r = (float)raw;
    return CO_A * expf(CO_B * r) + CO_C;
}

/*
 * Log a timestamped CO concentration reading to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_co_reading(float ppm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_co_reading: fopen(%s) failed: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_co_reading: localtime_r failed: %s\n",
                strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "log_co_reading: strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f ppm\n", timestamp, ppm) < 0) {
        fprintf(stderr, "log_co_reading: fprintf failed: %s\n",
                strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "log_co_reading: fclose failed: %s\n",
                strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_ads1115_handle >= 0) {
        i2cClose(g_ads1115_handle);
        g_ads1115_handle = -1;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "main: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus for MICS-4514 */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "main: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus for ADS1115 */
    g_ads1115_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_ads1115_handle < 0) {
        fprintf(stderr, "main: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "main: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "main: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CO sensor monitoring started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (ads1115_read_ain0(g_ads1115_handle, &raw) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Warning: ADS1115 read attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(100000); /* 100 ms backoff */
        }

        if (!success) {
            fprintf(stderr, "Error: Failed to read ADS1115 after %d attempts.\n",
                    MAX_RETRIES);
            /* Log a sentinel value to indicate sensor failure */
            if (log_co_reading(-1.0f) != 0) {
                fprintf(stderr, "Error: Failed to log sensor failure.\n");
            }
        } else {
            float ppm = raw_to_ppm(raw);
            printf("CO: %.2f ppm (raw=%d)\n", ppm, raw);

            if (log_co_reading(ppm) != 0) {
                fprintf(stderr, "Error: Failed to log CO reading.\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

