    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "main: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus for MICS-4514 */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "main: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus for ADS1115 */
    g_ads1115_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_ads1115_handle < 0) {
        fprintf(stderr, "main: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "main: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "main: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CO sensor monitoring started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (ads1115_read_ain0(g_ads1115_handle, &raw) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Warning: ADS1115 read attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(100000); /* 100 ms backoff */
        }

        if (!success) {
            fprintf(stderr, "Error: Failed to read ADS1115 after %d attempts.\n",
                    MAX_RETRIES);
            /* Log a sentinel value to indicate sensor failure */
            if (log_co_reading(-1.0f) != 0) {
                fprintf(stderr, "Error: Failed to log sensor failure.\n");
            }
        } else {
            float ppm = raw_to_ppm(raw);
            printf("CO: %.2f ppm (raw=%d)\n", ppm, raw);

            if (log_co_reading(ppm) != 0) {
                fprintf(stderr, "Error: Failed to log CO reading.\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

