/*
 * Raspberry Pi 3 Model B+ – KY-026 Flame Sensor + MCP3008 ADC Logger
 *
 * Wiring:
 *   KY-026 D0  -> GPIO 4  (BCM)
 *   MCP3008 CS -> GPIO 8  (BCM)
 *   MCP3008 CLK-> GPIO 11 (BCM)
 *   MCP3008 Dout-> GPIO 9  (BCM)
 *   MCP3008 Din -> GPIO 10 (BCM)
 *   MCP3008 VDD -> 3.3 V
 *   MCP3008 VREF-> 3.3 V
 *   MCP3008 AGND-> GND
 *   MCP3008 DGND-> GND
 *   KY-026 VCC -> 3.3 V
 *   KY-026 GND -> GND
 *
 * Build: gcc -O2 -Wall -Wextra -o flame_logger flame_logger.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN  4
#define MCP3008_CS_PIN    8
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS          8
#define SPI_DELAY_US      0
#define MCP3008_CHANNEL   0
#define LOG_FILE          "flame_data.csv"
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI transfer failure.
 */
static int mcp3008_read(struct gpiod_line *cs_line, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (clock out remaining bits)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in lower 2 bits
     *   rx[2] = b7..b0
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = SPI_DELAY_US,
        .cs_change     = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/*
 * Convert ADC value (0–1023) to a temperature in Celsius.
 * KY-026 analog output: 0 V -> ~20 °C, 3.3 V -> ~100 °C.
 * Returns -1000.0 on invalid input.
 */
static float adc_to_temperature(int adc_value)
{
    if (adc_value < 0 || adc_value > 1023) {
        return -1000.0f;
    }
    return 20.0f + ((float)adc_value / 1023.0f) * 80.0f;
}

static int log_data(FILE *fp, int flame_present, float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_present, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *cs_line = NULL;
    int spi_fd = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (flame_line == NULL) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, MCP3008_CS_PIN);
    if (cs_line == NULL) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", MCP3008_CS_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request CS as output, initially high (deselected) */
    if (gpiod_line_request_output(cs_line, "flame_logger", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request flame sensor pin as input */
    if (gpiod_line_request_input(flame_line, "flame_logger") < 0) {
        fprintf(stderr, "Failed to request flame sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open SPI device --- */
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open /dev/spidev0.0: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "Timestamp,Flame_Detected,Temperature_C\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
        fflush(fp);
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int flame_value = gpiod_line_get_value(flame_line);
        if (flame_value < 0) {
            fprintf(stderr, "Failed to read flame sensor: %s\n", strerror(errno));
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        int flame_present = (flame_value == 0) ? 1 : 0;

        int adc_value = mcp3008_read(cs_line, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read error – skipping sample\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float temperature = adc_to_temperature(adc_value);

        if (log_data(fp, flame_present, temperature) < 0) {
            fprintf(stderr, "Logging failed – continuing\n");
        }

        printf("Flame: %s, Temperature: %.2f C\n",
               flame_present ? "YES" : "NO", temperature);

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }
    if (flame_line != NULL) {
        gpiod_line_release(flame_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

