#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define CO_THRESHOLD 25.0f
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *ox, uint16_t *red) {
    char buf[4];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data (got %d bytes, expected 4): %s\n",
                bytes_read, bytes_read < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *ox = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *red = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
    return 0;
}

static float convert_to_ppm(uint16_t ox_value) {
    return (float)ox_value * 0.01f;
}

