/*
 * Raspberry Pi 4 Model B – Dual IMP23ABSU MEMS Microphone Logger
 *
 * Reads two analog MEMS microphones via a bit-banged I2C emulation on
 * bus 1 using the analog OUT signals connected to GPIO2 (BCM2) and
 * GPIO3 (BCM3).  Samples each microphone every 100 ms, computes the
 * average level, and appends a timestamped entry to audio_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_logger audio_logger.c
 * Run:    sudo ./audio_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS            1          /* /dev/i2c-1 on Raspberry Pi 4 */
#define I2C_ADDR           0x00       /* No real I2C device; bit-banged */

#define MIC1_GPIO          2          /* BCM2 – analog OUT from mic 1 */
#define MIC2_GPIO          3          /* BCM3 – analog OUT from mic 2 */

#define SAMPLE_PERIOD_US   100000     /* 100 ms between samples */
#define LOG_FILE           "audio_log.txt"
#define ERROR_VALUE        (-999.0)

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C emulation ------------------------------- */

/*
 * Bit-bang a single I2C read of a 16-bit register.
 * IMP23ABSU analog OUT is a 10-bit ADC; we read 16 bits and return the
 * lower 10 bits as a signed 16-bit value (two's complement).
 */
static int i2c_read_reg16(int handle, uint8_t reg, int16_t *out)
{
    char tx[1] = { (char)reg };
    char rx[2] = { 0, 0 };

    if (i2cWriteDevice(handle, tx, 1) != 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, rx, 2) != 2) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* IMP23ABSU analog OUT: 10-bit ADC, two's complement */
    uint16_t raw = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    *out = (int16_t)(raw & 0x03FF);          /* keep lower 10 bits */
    if (*out & 0x0200) {                     /* sign-extend */
        *out |= 0xFC00;
    }
    return 0;
}

/* --------------------------- Mic read helpers ----------------------------- */

/*
 * Read a single microphone's analog OUT via bit-banged I2C.
 * Returns 0 on success and stores the 10-bit ADC value in *out;
 * returns -1 on error.
 */
static int read_microphone(int handle, int16_t *out)
{
    return i2c_read_reg16(handle, 0x00, out);
}

/*
 * Read both microphones and compute the average.
 * Returns 0 on success; returns -1 if either read fails.
 */
static int read_and_average(int handle, double *avg)
{
    int16_t v1 = 0, v2 = 0;

    if (read_microphone(handle, &v1) != 0) {
        fprintf(stderr, "[MIC1] read failed\n");
        return -1;
    }
    if (read_microphone(handle, &v2) != 0) {
        fprintf(stderr, "[MIC2] read failed\n");
        return -1;
    }

    *avg = ((double)v1 + (double)v2) / 2.0;
    return 0;
}

/* ------------------------------- Logging --------------------------------- */

static void log_data(double avg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[LOG] open %s failed: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed\n");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[LOG] strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, %.2f\n", ts, avg);
    fclose(fp);
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIOs as inputs (bit-banged I2C) --- */
    if (gpioSetMode(MIC1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(MIC1) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MIC2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(MIC2) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open I2C device (bit-banged) --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Audio logger started.  Sampling every %d ms.  Press Ctrl+C to stop.\n",
           SAMPLE_PERIOD_US / 1000);

    /* --- Main loop --- */
    while (g_running) {
        double avg = ERROR_VALUE;

        if (read_and_average(g_i2c_handle, &avg) == 0) {
            log_data(avg);
        } else {
            /* Log error value so gaps are visible in the data stream */
            log_data(ERROR_VALUE);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

