#define SAMPLE_INTERVAL_US 1000
#define LED_ON_DURATION_US 500000
#define ADC_MAX_VALUE 1023.0

static volatile sig_atomic_t running = 1;
static int spi_handle_mic1 = -1;
static int spi_handle_mic2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_rms(const int *samples, int num_samples) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double val = (double)samples[i];
        sum_sq += val * val;
    }
    return sqrt(sum_sq / num_samples);
}

static void log_data(double rms1, double rms2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, rms1, rms2) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle_mic1 >= 0) {
        spiClose(spi_handle_mic1);
        spi_handle_mic1 = -1;
    }
    if (spi_handle_mic2 >= 0) {
        spiClose(spi_handle_mic2);
        spi_handle_mic2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle_mic1 = spiOpen(SPI_CHANNEL_MIC1, SPI_SPEED, SPI_FLAGS);
    if (spi_handle_mic1 < 0) {
        fprintf(stderr, "Failed to open SPI channel for mic1: %d\n", spi_handle_mic1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle_mic2 = spiOpen(SPI_CHANNEL_MIC2, SPI_SPEED, SPI_FLAGS);
    if (spi_handle_mic2 < 0) {
        fprintf(stderr, "Failed to open SPI channel for mic2: %d\n", spi_handle_mic2);
        spiClose(spi_handle_mic1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle_mic1);
        spiClose(spi_handle_mic2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int num_samples = SAMPLE_WINDOW_MS * 1000 / SAMPLE_INTERVAL_US;
    int *samples1 = (int *)malloc(num_samples * sizeof(int));
    int *samples2 = (int *)malloc(num_samples * sizeof(int));

    if (samples1 == NULL || samples2 == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(samples1);
        free(samples2);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < num_samples; i++) {
            int val1 = read_adc(spi_handle_mic1, 0);
            int val2 = read_adc(spi_handle_mic2, 0);

            if (val1 < 0 || val2 < 0) {
                fprintf(stderr, "ADC read error at sample %d\n", i);
                break;
            }

            samples1[i] = val1;
            samples2[i] = val2;

            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (!running) break;

        double rms1 = calculate_rms(samples1, num_samples);
        double rms2 = calculate_rms(samples2, num_samples);

        log_data(rms1, rms2);

        if (rms1 > RMS_THRESHOLD || rms2 > RMS_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            gpioDelay(LED_ON_DURATION_US);
            gpioWrite(LED_GPIO, 0);
        }
    }

    free(samples1);
    free(samples2);
    cleanup();
    printf("Audio monitoring stopped.\n");
    return EXIT_SUCCESS;
}

