/*
 * Raspberry Pi 4 Model B – MLX91204 Hall-effect current sensor monitor
 *
 * Hardware:
 *   - MLX91204 analog output -> ADS1115 A0 (single-ended)
 *   - ADS1115 SDA/SCL on I2C bus 1 (BCM GPIO2/GPIO3)
 *   - Warning LED on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c
 *
 * Run:
 *   ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15   OS      = 1  (start single conversion)
 *   Bits14:12 MUX     = 100 (AIN0 single-ended)
 *   Bits11:9  PGA     = 001 (+/-4.096 V)
 *   Bit  8    MODE    = 0  (single-shot)
 *   Bits7:5   DR      = 100 (128 SPS)
 *   Bit  4    COMP_MODE = 0
 *   Bit  3    COMP_POL  = 0
 *   Bit  2    COMP_LAT  = 0
 *   Bits1:0   COMP_QUE = 11 (disable comparator)
 */
#define ADS1115_CONFIG_BASE 0x8483

#define GPIO_LED          17
#define BUFFER_SIZE       100
#define CURRENT_THRESHOLD 50.0f   /* Amperes */
#define SAMPLE_PERIOD_US  100000 /* 10 Hz */
#define CONV_TIMEOUT_MS   100

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static int      g_gpio_fd = -1;
static float    g_current_buffer[BUFFER_SIZE];
static int      g_buffer_index = 0;
static int      g_buffer_count = 0;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  i2c_write_reg16(int fd, uint8_t reg, uint16_t val);
static int  i2c_read_reg16(int fd, uint8_t reg, uint16_t *val);
static int  ads1115_read_raw(int fd, int16_t *raw_out);
static float raw_to_current(int16_t raw);
static void buffer_add(float current);
static float buffer_average(void);
static void cleanup(void);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C helpers ------------------------------ */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* --------------------------- ADS1115 conversion -------------------------- */
static int ads1115_read_raw(int fd, int16_t *raw_out)
{
    uint16_t config = ADS1115_CONFIG_BASE;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS, use 100 ms margin) */
    usleep(CONV_TIMEOUT_MS * 1000);

    uint16_t conv;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &conv) < 0)
        return -1;

    *raw_out = (int16_t)conv;
    return 0;
}

/*
 * MLX91204 transfer function (simplified linear approximation):
 *   I = (Vout - Voffset) / Rgain
 *
 * With the ADS1115 configured for +/-4.096 V range, a 16-bit signed
 * value spans 4.096 V.  For a 50 A sensor, a typical offset is ~0.5 V
 * and a gain is ~10 mV/A.  We use a 100 mV/A gain for the conversion.
 */
static float raw_to_current(int16_t raw)
{
    const float v_per_bit = 4.096f / 32768.0f;   /* +/-4.096 V range */
    const float v_offset  = 0.5f;                 /* sensor offset */
    const float gain      = 0.1f;                 /* 100 mV/A */

    float voltage = (float)raw * v_per_bit;
    return (voltage - v_offset) / gain;
}

/* --------------------------- Circular buffer ----------------------------- */
static void buffer_add(float current)
{
    g_current_buffer[g_buffer_index] = current;
    g_buffer_index = (g_buffer_index + 1) % BUFFER_SIZE;
    if (g_buffer_count < BUFFER_SIZE)
        g_buffer_count++;
}

static float buffer_average(void)
{
    if (g_buffer_count == 0)
        return 0.0f;

    float sum = 0.0f;
    for (int i = 0; i < g_buffer_count; i++)
        sum += g_current_buffer[i];
    return sum / (float)g_buffer_count;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_gpio_fd >= 0) {
        /* Turn off LED */
        if (ioctl(g_gpio_fd, 0x00, 0) < 0)
            fprintf(stderr, "Warning: failed to turn off LED: %s\n",
                    strerror(errno));
        close(g_gpio_fd);
        g_gpio_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Verify ADS1115 presence by reading the config register --- */
    uint16_t cfg_check;
    if (i2c_read_reg16(g_i2c_fd, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X – sensor absent?\n",
                ADS1115_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip and request LED line --- */
    g_gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (g_gpio_fd < 0) {
        fprintf(stderr, "Cannot open /dev/gpiochip0: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_gpio_fd, 0x00, GPIO_LED) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d: %s\n",
                GPIO_LED, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (ioctl(g_gpio_fd, 0x01, 0) < 0) {
        fprintf(stderr, "Cannot set GPIO %d initial value: %s\n",
                GPIO_LED, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started.  Sampling %d Hz, threshold %.1f A.\n",
           1000000 / SAMPLE_PERIOD_US, CURRENT_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "ADC read error – continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float current = raw_to_current(raw);
        buffer_add(current);

        float avg = buffer_average();
        bool over = (avg > CURRENT_THRESHOLD);

        if (ioctl(g_gpio_fd, 0x01, over ? 1 : 0) < 0) {
            fprintf(stderr, "Warning: failed to set LED: %s\n",
                    strerror(errno));
        }

        printf("Raw: %6d  Current: %7.2f A  Avg: %7.2f A  LED: %s\n",
               raw, current, avg, over ? "ON" : "OFF");

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

