#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_ID 0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A

#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ATIME_256MS 0xFF
#define TCS34725_ID_VALUE 0x44

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_COMMAND_BIT), value };
    if (write(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value) {
    uint8_t cmd = (uint8_t)(reg | TCS34725_COMMAND_BIT);
    if (write(handle, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int handle) {
    uint16_t id;
    if (i2c_read_word(handle, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Failed to read TCS34725 ID register\n");
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "TCS34725 ID mismatch: got 0x%04X, expected 0x%04X\n", id, TCS34725_ID_VALUE);
        return -1;
    }
    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0) return -1;
    gpioDelay(3000);
    if (i2c_write_byte(handle, TCS34725_ATIME, TCS34725_ATIME_256MS) != 0) return -1;
    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0) return -1;
    gpioDelay(3000);
    return 0;
}

static int tcs34725_read_data(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_word(handle, TCS34725_CDATAL, clear) != 0) return -1;
    if (i2c_read_word(handle, TCS34725_RDATAL, red) != 0) return -1;
    if (i2c_read_word(handle, TCS34725_GDATAL, green) != 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATAL, blue) != 0) return -1;
    return 0;
}

static int log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (tcs34725_init(i2c_handle) != 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
        fflush(log_file);
    }

    int consecutive_failures = 0;
    while (running) {
        uint16_t clear, red, green, blue;
        if (tcs34725_read_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            consecutive_failures = 0;
            if (log_data(log_file, clear, red, green, blue) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Read failure #%d\n", consecutive_failures);
            if (consecutive_failures >= 3) {
                fprintf(stderr, "Too many consecutive failures, exiting.\n");
                break;
            }
        }
        gpioDelay(1000000);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    return 0;
}

