            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    ret_code = EXIT_SUCCESS;

    if (spi_fd >= 0) {
        if (close(spi_fd) != 0) {
            fprintf(stderr, "close(spi_fd): %s\n", strerror(errno));
            ret_code = EXIT_FAILURE;
        }
    }

    return ret_code;
}

