        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int spi_fd = -1;
    int ret_code = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Moisture sensor logger started. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int moisture1 = mcp3008_read(spi_fd, SENSOR1_CHANNEL);
        int moisture2 = mcp3008_read(spi_fd, SENSOR2_CHANNEL);

        if (moisture1 < 0 || moisture2 < 0) {
            fprintf(stderr, "Error reading sensor data. Skipping log entry.\n");
        } else {
            if (log_data(LOG_FILE, moisture1, moisture2) != 0) {
                fprintf(stderr, "Error logging data.\n");
            } else {
                printf("Logged: Moisture1=%d, Moisture2=%d\n", moisture1, moisture2);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    ret_code = EXIT_SUCCESS;

    if (spi_fd >= 0) {
        if (close(spi_fd) != 0) {
            fprintf(stderr, "close(spi_fd): %s\n", strerror(errno));
