/*
 * Raspberry Pi 4 Model B – MLX91211 Triaxis Current Sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (BCM 11, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (BCM 9,  SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (BCM 10, SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (BCM 8,  SPI0 CE0)
 *   MCP3008 CH0  -> MLX91211 analog output
 *   GPIO17       -> Motor shutdown control (active-low)
 *
 * Build: gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:   sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define MCP3008_CHANNEL  0          /* ADC channel connected to MLX91211 */

#define MOTOR_SHUTDOWN_PIN 17       /* GPIO17 – active-low motor shutdown */

#define OVERCURRENT_THRESHOLD 10.0f /* Amperes */
#define SAMPLE_INTERVAL_US    1000000 /* 1 second */
#define RETRY_DELAY_US        100000  /* 100 ms between retries */
#define MAX_RETRIES           3

#define LOG_FILE_NAME "current_log.csv"

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize_gpio(void);
static int  initialize_spi(void);
static int  read_mcp3008(int channel, int *adc_value);
static float adc_to_current(int adc_value);
static int  log_current(float current);
static void check_overcurrent(float current);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- GPIO / SPI -------------------------------- */

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", MOTOR_SHUTDOWN_PIN);
        gpioTerminate();
        return -1;
    }

    /* Start with motor enabled (active-low: drive high) */
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d high.\n", MOTOR_SHUTDOWN_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d.\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3): %s\n",
                bytes, strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/*
 * MLX91211 transfer function (approximate linear relationship):
 *   I = (Vout / Vref) * I_max
 *   Vref = 3.3 V (MCP3008 reference)
 *   I_max = 10 A (per datasheet)
 */
static float adc_to_current(int adc_value)
{
    const float vref = 3.3f;
    const float i_max = 10.0f;
    return ((float)adc_value / 1023.0f) * i_max;
}

/* ----------------------------- Logging ----------------------------------- */

static int log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.3f\n", timestamp, current) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        /* Non-fatal: data is in kernel buffer */
    }

    return 0;
}

/* ----------------------------- Overcurrent -------------------------------- */

static void check_overcurrent(float current)
{
    if (current > OVERCURRENT_THRESHOLD) {
        fprintf(stderr, "Overcurrent detected: %.3f A > %.1f A – disabling motor.\n",
                current, OVERCURRENT_THRESHOLD);

        if (gpioWrite(MOTOR_SHUTDOWN_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to disable motor (GPIO%d): %s\n",
                    MOTOR_SHUTDOWN_PIN, strerror(errno));
        }

        if (log_current(current) != 0) {
            fprintf(stderr, "Warning: failed to log overcurrent event.\n");
        }

        /* Wait for motor to cool down before re-enabling */
        gpioDelay(SAMPLE_INTERVAL_US);

        if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to re-enable motor (GPIO%d): %s\n",
                    MOTOR_SHUTDOWN_PIN, strerror(errno));
        } else {
            fprintf(stderr, "Motor re-enabled.\n");
        }
    }
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    /* Ensure motor is re-enabled before releasing resources */
    if (g_spi_handle >= 0) {
        gpioWrite(MOTOR_SHUTDOWN_PIN, 1);
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode) */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) != 0) {
        fprintf(stderr, "Error: fseek failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    long file_size = ftell(g_log_file);
    if (file_size < 0) {
        fprintf(stderr, "Error: ftell failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (file_size == 0) {
        if (fprintf(g_log_file, "Timestamp,Current (A)\n") < 0) {
            fprintf(stderr, "Error: failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    fprintf(stderr, "Current monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n",
            LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        int adc_value = -1;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && !read_ok) {
            if (read_mcp3008(MCP3008_CHANNEL, &adc_value) == 0) {
                read_ok = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "SPI read failed (attempt %d/%d), retrying...\n",
                            retries, MAX_RETRIES);
                    gpioDelay(RETRY_DELAY_US);
                }
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Error: failed to read ADC after %d retries – skipping sample.\n",
                    MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc_value);

        if (log_current(current) != 0) {
            fprintf(stderr, "Warning: failed to log current reading.\n");
        }

        check_overcurrent(current);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    cleanup();
    fprintf(stderr, "Current monitoring stopped.\n");
    return EXIT_SUCCESS;
}

