 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d.\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3): %s\n",
                bytes, strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/*
 * MLX91211 transfer function (approximate linear relationship):
 *   I = (Vout / Vref) * I_max
 *   Vref = 3.3 V (MCP3008 reference)
 *   I_max = 10 A (per datasheet)
 */
static float adc_to_current(int adc_value)
{
    const float vref = 3.3f;
    const float i_max = 10.0f;
    return ((float)adc_value / 1023.0f) * i_max;
}

/* ----------------------------- Logging ----------------------------------- */

static int log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.3f\n", timestamp, current) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        /* Non-fatal: data is in kernel buffer */
    }

    return 0;
}

/* ----------------------------- Overcurrent -------------------------------- */

static void check_overcurrent(float current)
{
    if (current > OVERCURRENT_THRESHOLD) {
        fprintf(stderr, "Overcurrent detected: %.3f A > %.1f A – disabling motor.\n",
                current, OVERCURRENT_THRESHOLD);

        if (gpioWrite(MOTOR_SHUTDOWN_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to disable motor (GPIO%d): %s\n",
                    MOTOR_SHUTDOWN_PIN, strerror(errno));
        }

        if (log_current(current) != 0) {
            fprintf(stderr, "Warning: failed to log overcurrent event.\n");
        }

        /* Wait for motor to cool down before re-enabling */
        gpioDelay(SAMPLE_INTERVAL_US);

        if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to re-enable motor (GPIO%d): %s\n",
                    MOTOR_SHUTDOWN_PIN, strerror(errno));
        } else {
            fprintf(stderr, "Motor re-enabled.\n");
        }
    }
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    /* Ensure motor is re-enabled before releasing resources */
    if (g_spi_handle >= 0) {
        gpioWrite(MOTOR_SHUTDOWN_PIN, 1);
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode) */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) != 0) {
        fprintf(stderr, "Error: fseek failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    long file_size = ftell(g_log_file);
    if (file_size < 0) {
        fprintf(stderr, "Error: ftell failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (file_size == 0) {
        if (fprintf(g_log_file, "Timestamp,Current (A)\n") < 0) {
            fprintf(stderr, "Error: failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    fprintf(stderr, "Current monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n",
            LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        int adc_value = -1;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && !read_ok) {
            if (read_mcp3008(MCP3008_CHANNEL, &adc_value) == 0) {
                read_ok = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "SPI read failed (attempt %d/%d), retrying...\n",
                            retries, MAX_RETRIES);
                    gpioDelay(RETRY_DELAY_US);
                }
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Error: failed to read ADC after %d retries – skipping sample.\n",
                    MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc_value);

        if (log_current(current) != 0) {
            fprintf(stderr, "Warning: failed to log current reading.\n");
        }

        check_overcurrent(current);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    cleanup();
    fprintf(stderr, "Current monitoring stopped.\n");
    return EXIT_SUCCESS;
}

