/*
 * MLX90817 absolute pressure sensor logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   MLX90817 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   MLX90817 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   MLX90817 VDD  -> 3.3 V
 *   MLX90817 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90817_logger mlx90817_logger.c -lpigpio -lrt
 * Run:    sudo ./mlx90817_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define MLX90817_ADDR       0x28          /* default I2C address (ADDR pin tied to GND) */
#define LOG_FILE            "pressure_log.csv"
#define SAMPLE_PERIOD_US    1000000       /* 1 second */
#define MAX_CONSECUTIVE_ERR 10

/*
 * MLX90817 register map (16-bit, big-endian on the bus).
 * The sensor is a 16-bit absolute pressure sensor; the 16-bit register
 * at 0x00 contains the raw ADC code.  The datasheet specifies a conversion
 * factor of 0.001 kPa per LSB.
 */
#define REG_PRESSURE        0x00
#define REG_STATUS          0x01          /* status register (optional) */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Timestamp helper ----------------------------- */
static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t     rawtime;
    struct tm  tm_utc;

    time(&rawtime);
    gmtime_r(&rawtime, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

/* --------------------------- I2C helpers --------------------------------- */
/*
 * Read a 16-bit big-endian register from the MLX90817.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 */
static int read_register16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* --------------------------- Sensor read --------------------------------- */
/*
 * Read pressure from the MLX90817.
 * Returns 0 on success and stores the pressure in kPa in *pressure;
 * returns -1 on error.
 */
static int read_pressure(int handle, float *pressure)
{
    uint16_t raw;

    if (read_register16(handle, REG_PRESSURE, &raw) != 0)
        return -1;

    /*
     * The MLX90817 is a 16-bit absolute pressure sensor.
     * Conversion factor: 0.001 kPa per LSB.
     */
    *pressure = (float)raw * 0.001f;
    return 0;
}

/* --------------------------- Logging ------------------------------------- */
static int log_pressure(FILE *fp, float pressure)
{
    char ts[32];

    get_iso8601_timestamp(ts, sizeof(ts));

    if (fprintf(fp, "%s,%.3f\n", ts, pressure) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    int consecutive_errors = 0;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, MLX90817_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append mode) --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0 ||
            fflush(g_log_file) != 0) {
            fprintf(stderr, "[FATAL] Failed to write CSV header: %s\n",
                    strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("MLX90817 logger started. Logging to %s every 1 s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        float pressure;

        if (read_pressure(g_i2c_handle, &pressure) == 0) {
            consecutive_errors = 0;
            if (log_pressure(g_log_file, pressure) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "[WARN] Pressure read failed (%d consecutive).\n",
                    consecutive_errors);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERR) {
                fprintf(stderr, "[FATAL] %d consecutive I2C errors; aborting.\n",
                        consecutive_errors);
                break;
            }
        }

        /* Sleep 1 s, but wake early if a signal arrives */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);  /* 100 ms */
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

