/*
 * Raspberry Pi 4 Model B – MLX90834 SENT pressure sensor via ADS1115 ADC
 *
 * Wiring:
 *   MLX90834 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   MLX90834 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   MLX90834 VDD  -> 3.3 V
 *   MLX90834 GND  -> GND
 *   ADS1115 SDA   -> GPIO2
 *   ADS1115 SCL   -> GPIO3
 *   ADS1115 ADDR  -> GND  (I2C address 0x48)
 *   ADS1115 VDD   -> 3.3 V
 *   ADS1115 GND   -> GND
 *   ADS1115 AIN0  -> MLX90834 pressure output
 *   ADS1115 AIN1  -> MLX90834 NTC temperature output
 *   LED + 330 Ω   -> GPIO17 -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90834_ads1115 mlx90834_ads1115.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Configuration ---- */
#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48
#define LED_GPIO         17
#define PRESSURE_THRESHOLD 105.0f   /* kPa */
#define SAMPLE_PERIOD_US 1000000   /* 1 second */
#define MAX_RETRIES      3

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config word: single-shot, AIN0 vs GND, +/-4.096 V, 128 SPS, no comparator */
#define ADS1115_CFG_BASE 0x8000  /* OS bit */
#define ADS1115_CFG_MUX_AIN0 0x4000
#define ADS1115_CFG_PGA_4_096 0x0200
#define ADS1115_CFG_MODE_SINGLE 0x0100
#define ADS1115_CFG_DR_128 0x0080
#define ADS1115_CFG_CQUE_NONE 0x0003

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ---- ADS1115 helpers ---- */
static int ads1115_read_channel(int fd, uint8_t mux, int16_t *raw)
{
    uint16_t cfg = ADS1115_CFG_BASE | mux | ADS1115_CFG_PGA_4_096 |
                   ADS1115_CFG_MODE_SINGLE | ADS1115_CFG_DR_128 |
                   ADS1115_CFG_CQUE_NONE;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, cfg) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t val;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &val) < 0)
        return -1;

    *raw = (int16_t)val;
    return 0;
}

/* ---- MLX90834 conversion (example – replace with datasheet formulas) ---- */
static float convert_pressure(int16_t raw)
{
    /* Placeholder linear conversion; calibrate against known load cell */
    return (float)raw * 0.001f;
}

static float convert_temperature(int16_t raw)
{
    /* Placeholder linear conversion; calibrate against known NTC */
    return (float)raw * 0.01f;
}

/* ---- GPIO helpers ---- */
static int gpio_init(int pin)
{
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/gpiochip0: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, 4004, pin) < 0) {  /* GPIO_SET_DIRECTION_OUTPUT */
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static void gpio_set(int fd, int pin, int value)
{
    if (ioctl(fd, 4002, value) < 0)  /* GPIO_SET_VALUE */
        fprintf(stderr, "Warning: GPIO_SET_VALUE failed on pin %d: %s\n", pin, strerror(errno));
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize LED GPIO */
    int led_fd = gpio_init(LED_GPIO);
    if (led_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    gpio_set(led_fd, LED_GPIO, 0);

    printf("MLX90834 SENT pressure monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw_pressure = 0, raw_temperature = 0;
        bool read_ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (ads1115_read_channel(g_i2c_fd, ADS1115_CFG_MUX_AIN0, &raw_pressure) == 0 &&
                ads1115_read_channel(g_i2c_fd, ADS1115_CFG_MUX_AIN1, &raw_temperature) == 0) {
                read_ok = true;
