#define SPI_CHANNEL      0          /* MCP3008 on SPI0 CE0 (BCM 8)            */
#define SPI_SPEED        1000000    /* 1 MHz                                  */
#define SPI_FLAGS        0          /* Mode 0, active-low CE, 8-bit words     */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0         */
#define ADC_MAX          1023       /* 10-bit ADC full-scale code             */
#define CURRENT_THRESHOLD 10.0f     /* Amperes                                */
#define SHUTDOWN_PIN     27         /* BCM 27 — motor shutdown control        */
#define LOG_FILE         "current_log.txt"
#define SAMPLE_PERIOD_US 100000     /* 100 ms between samples                */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Forward declarations ------------------------ */
static int  initialize_gpio(void);
static int  initialize_spi(void);
static int  read_adc(int channel, int *out_value);
static float adc_to_current(int adc_value);
static void log_current(float current);
static void log_overcurrent(float current);
static void shutdown_motor(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Initialize GPIO --- */
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize SPI --- */
    if (initialize_spi() != 0) {
        fprintf(stderr, "Error: SPI initialization failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append mode) --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started.  Sampling every %d ms.  Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_US / 1000);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = 0;

        if (read_adc(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Warning: ADC read failed; skipping sample.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "Warning: ADC value out of range (%d); skipping sample.\n",
                    adc_value);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float current = adc_to_current(adc_value);
        log_current(current);

        if (current > CURRENT_THRESHOLD) {
            log_overcurrent(current);
            shutdown_motor();
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- GPIO initialization ------------------------- */
static int initialize_gpio(void)
{
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", SHUTDOWN_PIN);
        return -1;
    }
    if (gpioWrite(SHUTDOWN_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed.\n", SHUTDOWN_PIN);
        return -1;
    }
    return 0;
}

/* --------------------------- SPI initialization ------------------------- */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen(channel=%d, speed=%d, flags=%d) failed: %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, g_spi_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------- ADC read -------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer, mode 0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1:0 + rx[2] bits 7:0    -> 10-bit result
 */
static int read_adc(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0-7).\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    *out_value = adc_value;
    return 0;
}

/* ------------------------- ADC value -> current -------------------------- */
/*
 * MLX91209 transfer function (simplified linear approximation):
 *   Vout = R_shunt * I + V_offset
 *   I = (Vout - V_offset) / R_shunt
 *
 * With a 10-bit ADC, Vref = 3.3 V, R_shunt = 0.1 Ω, V_offset = 0 V:
 *   I = (adc_value / 1023.0f) * 3.3f / 0.1f
 */
static float adc_to_current(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX) * 3.3f / 0.1f;
}

/* ------------------------------ Logging ---------------------------------- */
static void log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed; logging with raw time.\n");
        fprintf(g_log_file, "%ld, %.2f\n", (long)rawtime, current);
    } else {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
        fprintf(g_log_file, "%s, %.2f\n", timestamp, current);
    }

    if (fflush(g_log_file) != 0) {
        perror("Warning: fflush(log_file)");
    }
}

static void log_overcurrent(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed; logging with raw time.\n");
        fprintf(g_log_file, "%ld, OVERCURRENT, %.2f\n", (long)rawtime, current);
    } else {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
        fprintf(g_log_file, "%s, OVERCURRENT, %.2f\n", timestamp, current);
    }

    if (fflush(g_log_file) != 0) {
        perror("Warning: fflush(log_file)");
    }
}

/* --------------------------- Motor shutdown ------------------------------ */
static void shutdown_motor(void)
{
    printf("Overcurrent detected! Shutting down motor.\n");

    if (gpioWrite(SHUTDOWN_PIN, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 1) failed during shutdown.\n", SHUTDOWN_PIN);
    }

    if (g_log_file != NULL) {
        fprintf(g_log_file, "OVERCURRENT_SHUTDOWN\n");
        fflush(g_log_file);
    }

    g_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    printf("\nCleaning up...\n");

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Reset shutdown pin to a safe state */
    gpioWrite(SHUTDOWN_PIN, 0);

    gpioTerminate();
}

/* --------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

