/*
 * methane_monitor.c — Raspberry Pi 4 Model B
 *
 * Monitors a Honeywell MICROpeL Model 41000-020 combustible gas sensor
 * via an MCP3008 ADC on SPI bus 0, channel 0, at 1 MHz, mode 0.
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 3.3 V (pin 1)
 *   MCP3008 VREF -> Pi 3.3 V (pin 1)
 *   MCP3008 AGND -> Pi GND  (pin 9)
 *   MCP3008 DGND -> Pi GND  (pin 9)
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK, BCM 11)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO, BCM 9)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI, BCM 10)
 *   MCP3008 CS   -> Pi GPIO8  (CE0, BCM 8)
 *   MCP3008 CH0  -> MICROpeL analog output
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o methane_monitor methane_monitor.c
 *
 * Run:
 *   ./methane_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8U
#define SPI_MODE        SPI_MODE_0
#define ADC_CHANNEL     0U
#define ADC_MAX_VALUE   1023U
#define LEAK_THRESHOLD  1000.0f    /* ppm */
#define LOG_FILE        "methane_log.txt"
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI initialization                                                  */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    uint8_t  mode  = SPI_MODE;
    uint8_t  bits  = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3 bytes, mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1:0 + rx[2] bits 7:0    -> 10-bit result
 */
static int mcp3008_read(uint8_t channel, uint16_t *out_value)
{
    if (channel > 7) {
        fprintf(stderr, "mcp3008_read: invalid channel %u\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    *out_value = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor conversion                                                   */
/* ------------------------------------------------------------------ */
/*
 * MICROpeL Model 41000-020:
 *   Vout = 0.45 V + 0.0045 * ppm
 *   ppm  = (Vout - 0.45) / 0.0045
 *
 * The sensor output is linear over the 0–1000 ppm range.
 * At 1000 ppm the output is ~4.95 V; at 2000 ppm it is ~9.9 V.
 * We clamp the reading to 0–1000 ppm for safety.
 */
static float adc_to_ppm(uint16_t adc_value)
{
    float voltage = ((float)adc_value / (float)ADC_MAX_VALUE) * 3.3f;
    float ppm     = (voltage - 0.45f) / 0.0045f;

    if (ppm < 0.0f)   ppm = 0.0f;
    if (ppm > 1000.0f) ppm = 1000.0f;

    return ppm;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(float ppm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, %.2f ppm\n", timestamp, ppm) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Methane monitoring started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "SPI read failed; continuing.\n");
        } else {
            float ppm = adc_to_ppm(adc_value);

            if (log_data(ppm) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }

            if (ppm > LEAK_THRESHOLD) {
                fprintf(stderr, "Leak detected! Concentration: %.2f ppm\n", ppm);
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            usleep(100000U);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

