/*
 * Raspberry Pi 4 Model B – MLX90830 Pressure Logger
 *
 * Reads analog pressure data from a Melexis MLX90830 sensor via an ADS1115
 * 16-bit ADC on I2C bus 1 (SDA=GPIO2, SCL=GPIO3), channel AIN0.
 *
 * Wiring:
 *   MLX90830 VDD  -> 3.3 V (Pin 1)
 *   MLX90830 GND  -> GND  (Pin 9)
 *   MLX90830 OUT  -> ADS1115 AIN0
 *   ADS1115 VDD   -> 3.3 V
 *   ADS1115 GND   -> GND
 *   ADS1115 SDA   -> GPIO2 (Pin 3, I2C bus 1)
 *   ADS1115 SCL   -> GPIO3 (Pin 5, I2C bus 1)
 *   ADS1115 ADDR  -> GND  (I2C address 0x48)
 *
 * Build: gcc -O2 -Wall -o pressure_logger pressure_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48          /* ADS1115 ADDR pin tied to GND */

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15   OS      = 1  (start single conversion)
 *   Bits14:12 MUX     = 100 (AIN0 vs GND)
 *   Bits11:9  PGA     = 001 (+/-4.096 V)
 *   Bit  8    MODE    = 1  (single-shot)
 *   Bits7:5   DR      = 100 (128 SPS)
 *   Bit  4    COMP_MODE = 0
 *   Bit  3    COMP_POL  = 0
 *   Bit  2    COMP_LAT  = 0
 *   Bits1:0   COMP_QUE = 11 (disable comparator)
 */
#define ADS1115_CONFIG_BASE 0x8483

#define PRESSURE_MIN_KPA 0.0f
#define PRESSURE_MAX_KPA 100.0f
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  i2c_write_reg16(int fd, uint8_t reg, uint16_t value);
static int  i2c_read_reg16(int fd, uint8_t reg, uint16_t *value);
static int  ads1115_read_raw(int fd, int16_t *raw_out);
static float raw_to_kpa(int16_t raw);
static int  log_pressure(float pressure);
static void cleanup(void);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C helpers ------------------------------ */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)((value >> 8) & 0xFF);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* --------------------------- ADS1115 read raw ----------------------------- */
static int ads1115_read_raw(int fd, int16_t *raw_out)
{
    uint16_t config = ADS1115_CONFIG_BASE;

    /* Start a single-shot conversion on AIN0 */
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t conv;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &conv) != 0)
        return -1;

    *raw_out = (int16_t)conv;
    return 0;
}

/* --------------------------- Raw to kPa ---------------------------------- */
static float raw_to_kpa(int16_t raw)
{
    /*
     * PGA = +/-4.096 V  ->  1 bit = 4.096 / 32768 = 0.000125 V
     * MLX90830: 0 V -> 0 kPa, 4.096 V -> 100 kPa
     */
    return (float)raw * 0.000125f * 100.0f;
}

/* --------------------------- Log pressure -------------------------------- */
static int log_pressure(float pressure)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Pressure logger started. Logging to %s. Press Ctrl-C to stop.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_fd, &raw) != 0) {
            fprintf(stderr, "ADC read error – continuing after delay.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float pressure = raw_to_kpa(raw);

        if (pressure < PRESSURE_MIN_KPA || pressure > PRESSURE_MAX_KPA) {
            fprintf(stderr,
                    "Pressure out of range: %.2f kPa (raw=%d) – skipping.\n",
                    pressure, raw);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_pressure(pressure) != 0) {
            fprintf(stderr, "Logging failed – continuing.\n");
        }

        printf("Pressure: %.2f kPa\n", pressure);
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

