#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SENDER "sender@example.com"
#define EMAIL_SERVER "smtp.example.com"
#define EMAIL_PORT 25

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3208(uint8_t channel, uint16_t *value) {
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int read_humidity_temperature(float *humidity, float *temperature) {
    uint16_t adc_value;
    if (read_mcp3208(0, &adc_value) < 0) {
        return -1;
    }

    float voltage = (adc_value / 4095.0f) * 3.3f;
    *humidity = (voltage - 0.8f) * 125.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    *temperature = (voltage - 0.768f) * 165.0f - 40.0f;
    return 0;
}

static int log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("Failed to get local time");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature) < 0) {
        perror("Failed to write to log file");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    if (fclose(log_file) != 0) {
        perror("Failed to close log file");
        log_file = NULL;
        return -1;
    }
    log_file = NULL;

    return 0;
}

static int send_email_alert(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("Failed to get local time");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char command[512];
    snprintf(command, sizeof(command),
        "echo \"Subject: Humidity Alert\n\nHumidity exceeded threshold at %s. Current humidity: %.2f%%\" | ssmtp %s",
        timestamp, humidity, EMAIL_RECIPIENT);

    int result = system(command);
    if (result == -1) {
        perror("Failed to execute ssmtp command");
        return -1;
    }
    if (WIFEXITED(result) && WEXITSTATUS(result) != 0) {
        fprintf(stderr, "ssmtp command exited with status %d\n", WEXITSTATUS(result));
        return -1;
    }
    if (WIFSIGNALED(result)) {
        fprintf(stderr, "ssmtp command killed by signal %d\n", WTERMSIG(result));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float humidity, temperature;

        if (read_humidity_temperature(&humidity, &temperature) < 0) {
            fprintf(stderr, "Failed to read humidity and temperature. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        if (log_data(humidity, temperature) < 0) {
            fprintf(stderr, "Failed to log data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        if (humidity > HUMIDITY_THRESHOLD) {
            if (send_email_alert(humidity) < 0) {
                fprintf(stderr, "Failed to send email alert.\n");
            }
        }

        sleep(5);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Humidity monitoring stopped.\n");

    return 0;
}

