 *
 * Build: gcc -O2 -Wall -o impact_monitor impact_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define ADC_CHANNEL_X   0
#define ADC_CHANNEL_Y   1
#define ADC_CHANNEL_Z   2

#define ADC_MAX_VALUE   1023       /* 10-bit ADC */
#define ADC_MIN_VALUE   0

#define IMPACT_THRESHOLD 500
#define LOG_FILE        "impact_log.txt"
#define SAMPLE_PERIOD_US 10000U   /* 100 Hz */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * MCP3008 single-ended read.
 *
 * Protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *
 * Result: 10-bit value assembled from rx[1] (lower 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed on channel %d: %s\n",
                channel, strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    if (value < ADC_MIN_VALUE || value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range on channel %d: %d\n",
                channel, value);
        return -1;
    }

    return value;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(int x, int y, int z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

static void log_impact(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,IMPACT DETECTED\n", timestamp) < 0) {
        fprintf(stderr, "Error writing impact to log file: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact monitoring started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (g_running) {
        int x = mcp3008_read(ADC_CHANNEL_X);
        int y = mcp3008_read(ADC_CHANNEL_Y);
        int z = mcp3008_read(ADC_CHANNEL_Z);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error; continuing.\n");
        } else {
            log_data(x, y, z);

            if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD ||
                z > IMPACT_THRESHOLD) {
                log_impact();
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * Si1172‑A30‑GMR Optical Heart Rate Sensor Reader for Raspberry Pi Zero W
 *
 * Reads raw IR and RED ADC values (proxy for HR and SpO₂) from the Si1172
 * via I2C bus 1 and logs them to biometric_log.csv every second.
 *
 * Wiring:
 *   Si1172 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   Si1172 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   Si1172 VDD  -> 3.3 V
 *   Si1172 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1172_reader si1172_reader.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./si1172_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define SI1172_ADDR         0x44          /* Si1172 default I2C address (ADDR pin tied to GND) */
#define LOG_FILE            "biometric_log.csv"
#define SAMPLE_PERIOD_US    1000000       /* 1 second in microseconds */

/*
 * Si1172 register addresses (example values; replace with actual datasheet
 * values for your specific Si1172 variant).
 */
#define REG_PART_ID         0x00
#define REG_HW_KEY          0x07
#define REG_MEAS_RATE0      0x08
#define REG_MEAS_RATE1      0x09
#define REG_IRQ_ENABLE      0x0F
#define REG_IRQ_MODE1       0x10
#define REG_IRQ_MODE2       0x11
#define REG_INT_CFG         0x12
#define REG_IRQ_STATUS      0x13
#define REG_ALS_VIS_DATA0   0x22
#define REG_ALS_VIS_DATA1   0x23
#define REG_ALS_IR_DATA0    0x24
#define REG_ALS_IR_DATA1    0x25
#define REG_ALS_RED_DATA0   0x26
#define REG_ALS_RED_DATA1   0x27

#define EXPECTED_PART_ID    0x72          /* Si1172 PART_ID value */
#define HW_KEY_VALUE        0x17

/* ------------------------------- Globals --------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Function prototypes ------------------------- */
static int  initialize_i2c(void);
static int  initialize_sensor(void);
static int  read_sensor_data(uint16_t *ir, uint16_t *red);
static void log_data(uint16_t ir, uint16_t red, int error_flag);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- I2C helpers ----------------------------- */

/*
 * Write a single byte to an 8-bit register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/*
 * Read a single byte from an 8-bit register.
 * Returns the byte value (0–255) on success, -1 on failure.
 */
static int i2c_read_reg(uint8_t reg)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
    }
    return rc;
}

/*
 * Read a 16-bit little-endian register pair (low byte at reg, high byte at reg+1).
 * Returns 0 on success, -1 on failure.
 */
static int i2c_read_reg16(uint8_t reg, uint16_t *out)
{
    int lo = i2c_read_reg(reg);
    if (lo < 0)
        return -1;
    int hi = i2c_read_reg(reg + 1);
    if (hi < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* --------------------------- Sensor initialization ------------------------ */

static int initialize_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1172_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int initialize_sensor(void)
{
    /* Verify sensor presence by reading PART_ID */
    int part_id = i2c_read_reg(REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID — sensor may be absent or bus error.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID: 0x%02X (expected 0x%02X).\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("[INFO] Si1172 detected (PART_ID=0x%02X).\n", part_id);

    /* Write HW_KEY to enable the device */
    if (i2c_write_reg(REG_HW_KEY, HW_KEY_VALUE) < 0)
        return -1;

    /* Configure measurement rate (example: 100 Hz) */
    if (i2c_write_reg(REG_MEAS_RATE0, 0x0A) < 0)  /* 10 Hz */
        return -1;
    if (i2c_write_reg(REG_MEAS_RATE1, 0x00) < 0)
        return -1;

    /* Configure interrupt enable (example: enable ALS_VIS interrupt) */
    if (i2c_write_reg(REG_IRQ_ENABLE, 0x01) < 0)
        return -1;

    /* Configure interrupt mode (example: ALS_VIS interrupt on every measurement) */
    if (i2c_write_reg(REG_IRQ_MODE1, 0x01) < 0)
        return -1;
    if (i2c_write_reg(REG_IRQ_MODE2, 0x00) < 0)
        return -1;

    /* Configure interrupt configuration (example: enable ALS_VIS interrupt) */
    if (i2c_write_reg(REG_INT_CFG, 0x01) < 0)
        return -1;

    /* Clear any pending interrupts */
    if (i2c_write_reg(REG_IRQ_STATUS, 0xFF) < 0)
        return -1;

    printf("[INFO] Si1172 initialized successfully.\n");
    return 0;
}

/* --------------------------- Sensor data reading ------------------------- */

static int read_sensor_data(uint16_t *ir, uint16_t *red)
{
    /*
     * Trigger a measurement by writing to the IRQ_STATUS register.
     * The Si1172 requires a specific bit pattern to trigger a measurement.
     * In this example, we write 0x01 to the IRQ_STATUS register to trigger
     * a measurement.
     */
    if (i2c_write_reg(REG_IRQ_STATUS, 0x01) < 0)
        return -1;

    /*
     * Wait for the measurement to complete.
     * The Si1172 requires a short delay for the measurement to be ready.
     * In this example, we use a 10 ms delay.
     */
    gpioDelay(10000); /* 10 ms */

    /* Read IR and RED ADC values */
    if (i2c_read_reg16(REG_ALS_IR_DATA0, ir) < 0)
        return -1;
    if (i2c_read_reg16(REG_ALS_RED_DATA0, red) < 0)
        return -1;

    return 0;
}

/* ------------------------------- Logging --------------------------------- */

static void log_data(uint16_t ir, uint16_t red, int error_flag)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%ld,%u,%u,%d\n", (long)rawtime, ir, red, error_flag);
    fflush(log_file);
}

/* ------------------------------- Signal handler --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (initialize_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_sensor() < 0) {
        fprintf(stderr, "[ERROR] Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,ir,red,error_flag\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("[INFO] Logging to %s every 1 second. Press Ctrl+C to stop.\n", LOG_FILE);

    /* Main sampling loop */
    while (!terminate) {
        uint16_t ir = 0, red = 0;
        int rc = read_sensor_data(&ir, &red);

        if (rc == 0) {
            log_data(ir, red, 0);
            printf("[DATA] IR=%u, RED=%u\n", ir, red);
        } else {
            /*
             * On a read failure, log the error flag instead of crashing.
             * This allows the application to continue running and log
             * the failure, rather than crashing if a sensor is disconnected
             * or the I2C bus is unresponsive.
             */
            log_data(0, 0, 1);
            fprintf(stderr, "[ERROR] Failed to read sensor data.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\n[INFO] Shutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

