}

/* --------------------------- Sensor data reading ------------------------- */

static int read_sensor_data(uint16_t *ir, uint16_t *red)
{
    /*
     * Trigger a measurement by writing to the IRQ_STATUS register.
     * The Si1172 requires a specific bit pattern to trigger a measurement.
     * In this example, we write 0x01 to the IRQ_STATUS register to trigger
     * a measurement.
     */
    if (i2c_write_reg(REG_IRQ_STATUS, 0x01) < 0)
        return -1;

    /*
     * Wait for the measurement to complete.
     * The Si1172 requires a short delay for the measurement to be ready.
     * In this example, we use a 10 ms delay.
     */
    gpioDelay(10000); /* 10 ms */

    /* Read IR and RED ADC values */
    if (i2c_read_reg16(REG_ALS_IR_DATA0, ir) < 0)
        return -1;
    if (i2c_read_reg16(REG_ALS_RED_DATA0, red) < 0)
        return -1;

    return 0;
}

/* ------------------------------- Logging --------------------------------- */

static void log_data(uint16_t ir, uint16_t red, int error_flag)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%ld,%u,%u,%d\n", (long)rawtime, ir, red, error_flag);
    fflush(log_file);
}

/* ------------------------------- Signal handler --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (initialize_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_sensor() < 0) {
        fprintf(stderr, "[ERROR] Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,ir,red,error_flag\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("[INFO] Logging to %s every 1 second. Press Ctrl+C to stop.\n", LOG_FILE);

    /* Main sampling loop */
    while (!terminate) {
        uint16_t ir = 0, red = 0;
        int rc = read_sensor_data(&ir, &red);

        if (rc == 0) {
            log_data(ir, red, 0);
            printf("[DATA] IR=%u, RED=%u\n", ir, red);
        } else {
            /*
             * On a read failure, log the error flag instead of crashing.
             * This allows the application to continue running and log
             * the failure, rather than crashing if a sensor is disconnected
             * or the I2C bus is unresponsive.
             */
            log_data(0, 0, 1);
            fprintf(stderr, "[ERROR] Failed to read sensor data.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\n[INFO] Shutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

