/*
 * Raspberry Pi 4 Model B – Honeywell SpiroQuant A+ ES1-005 Mass Flow Sensor
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  Pin 24)
 *   MCP3008 CH0  -> SpiroQuant A+ analog output
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8)                          */
#define SPI_SPEED        1000000    /* 1 MHz                                     */
#define SPI_FLAGS        0          /* Mode 0, active-low CE handled by pigpio    */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0            */
#define ADC_MAX          1023       /* 10-bit ADC full-scale code                */
#define FLOW_MIN         0.0f       /* Minimum valid flow rate (L/min)           */
#define FLOW_MAX         5.0f       /* Maximum valid flow rate (L/min)           */
#define LOG_FILE         "flow_log.csv"
#define SAMPLE_PERIOD_US 1000000    /* 1 second between samples                  */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  initialize_spi(void);
static int  read_adc(int channel, uint16_t *adc_value);
static float adc_to_flow_rate(uint16_t adc_value);
static int  log_flow_rate(float flow_rate);
static void cleanup(void);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- SPI init --------------------------------- */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[ERROR] spiOpen failed (pigpio error %d).\n", g_spi_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------- ADC read --------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer, Mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel, padded)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result:
 *   rx[1] bits 1..0  + rx[2] bits 7..0  -> 10-bit ADC code
 */
static int read_adc(int channel, uint16_t *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "[ERROR] Invalid ADC channel %d.\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "[ERROR] spiXfer failed (returned %d).\n", ret);
        return -1;
    }

    uint16_t raw = ((uint16_t)(rx[1] & 0x03) << 8) | (uint16_t)(rx[2] & 0xFF);
    *adc_value = raw;
    return 0;
}

/* --------------------------- Flow-rate conversion ------------------------ */
/*
 * Placeholder linear conversion.  Replace with the calibration curve
 * provided by the SpiroQuant A+ ES1-005 datasheet.
 */
static float adc_to_flow_rate(uint16_t adc_value)
{
    return (float)adc_value * (FLOW_MAX - FLOW_MIN) / (float)ADC_MAX + FLOW_MIN;
}

/* ------------------------------- Logging ---------------------------------- */
static int log_flow_rate(float flow_rate)
{
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] Log file not open.\n");
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("[ERROR] clock_gettime");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("[ERROR] localtime_r");
        return -1;
    }

    char timestamp[40];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s.%06ld,%.4f\n", timestamp, ts.tv_nsec / 1000, flow_rate) < 0) {
        perror("[ERROR] fprintf");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        perror("[ERROR] fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize SPI --- */
    if (initialize_spi() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("Flow monitoring started. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (read_adc(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "[WARN] ADC read failed; skipping sample.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Sensor-absent / wiring fault heuristics */
        if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr,
                    "[WARN] ADC at rail (%u) – sensor absent or wiring fault.\n",
                    adc_value);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float flow_rate = adc_to_flow_rate(adc_value);

        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr,
                    "[WARN] Flow rate %.4f L/min out of range [%.1f, %.1f].\n",
                    flow_rate, FLOW_MIN, FLOW_MAX);
        }

        if (log_flow_rate(flow_rate) != 0) {
            fprintf(stderr, "[WARN] Logging failed; continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

