    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ICP10125_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV log file (append mode) */
    g_log_fp = fopen(CSV_FILENAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "[ERROR] fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature (C),Pressure (Pa)\n");
        fflush(g_log_fp);
    }

    printf("ICP-10125 logger started. Logging to %s every %d s.\n",
           CSV_FILENAME, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, pressure;

        if (read_sensor(g_i2c_fd, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n",
                   temperature, pressure);
            if (log_data(g_log_fp, temperature, pressure) != 0) {
                fprintf(stderr, "[WARN] Logging failed; will retry next cycle.\n");
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
