/*
 * Dual MP23ABS1 MEMS Microphone Noise Cancellation via MCP3008 ADC
 * Board:  Raspberry Pi 3 Model B+
 * ADC:    MCP3008 on SPI0 CE0 (GPIO8), SPI mode 0, 1 MHz
 * Mics:   2x STMicroelectronics MP23ABS1 (analog out -> MCP3008 CH0/CH1)
 *
 * Build:  gcc -O2 -Wall -o mic_nc mic_nc.c -lm
 * Run:    ./mic_nc <mic1_gain> <mic2_gain>
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define ADC_CHANNELS    2
#define ADC_MAX_VALUE   1023

#define SAMPLE_PERIOD_US 10000U   /* 10 ms -> 100 Hz output rate */

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read.
 * Returns 0–1023 on success, -1 on error.
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result:
     *   rx[1] bits 1:0  -> bits 9:8
     *   rx[2]          -> bits 7:0
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed on channel %u: %s\n",
                channel, strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

/* ------------------------------------------------------------------ */
/* Noise cancellation                                                  */
/* ------------------------------------------------------------------ */
static int16_t noise_cancel(int16_t mic1, int16_t mic2,
                            float gain1, float gain2)
{
    float diff = (float)(mic1 - mic2);
    float out  = gain1 * (float)mic1 - gain2 * diff;
    return (int16_t)(out + 0.5f);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <mic1_gain> <mic2_gain>\n", argv[0]);
        fprintf(stderr, "  Gains are floating-point values (e.g., 0.5)\n");
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    float gain1 = strtof(argv[1], &endptr);
    if (endptr == argv[1] || *endptr != '\0') {
        fprintf(stderr, "Invalid mic1 gain: %s\n", argv[1]);
        return EXIT_FAILURE;
    }

    float gain2 = strtof(argv[2], &endptr);
    if (endptr == argv[2] || *endptr != '\0') {
        fprintf(stderr, "Invalid mic2 gain: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    /* Initialize SPI */
    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Sampling MP23ABS1 microphones via MCP3008 (SPI0 CE0)...\n");
    printf("Mic1 gain: %.2f, Mic2 gain: %.2f\n", gain1, gain2);
    printf("Press Ctrl+C to stop.\n\n");
    fflush(stdout);

    int consecutive_errors = 0;

    while (g_running) {
        int mic1_raw = mcp3008_read(g_spi_fd, 0);
        int mic2_raw = mcp3008_read(g_spi_fd, 1);

        if (mic1_raw < 0 || mic2_raw < 0) {
            consecutive_errors++;
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive SPI errors; aborting.\n");
                break;
            }
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        consecutive_errors = 0;

        /* Convert 10-bit ADC values to signed 16-bit samples */
        int16_t mic1 = (int16_t)mic1_raw;
        int16_t mic2 = (int16_t)mic2_raw;

        int16_t out = noise_cancel(mic1, mic2, gain1, gain2);

        printf("%d,%d,%d\n", mic1, mic2, out);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

