    char *endptr = NULL;
    float gain1 = strtof(argv[1], &endptr);
    if (endptr == argv[1] || *endptr != '\0') {
        fprintf(stderr, "Invalid mic1 gain: %s\n", argv[1]);
        return EXIT_FAILURE;
    }

    float gain2 = strtof(argv[2], &endptr);
    if (endptr == argv[2] || *endptr != '\0') {
        fprintf(stderr, "Invalid mic2 gain: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    /* Initialize SPI */
    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Sampling MP23ABS1 microphones via MCP3008 (SPI0 CE0)...\n");
    printf("Mic1 gain: %.2f, Mic2 gain: %.2f\n", gain1, gain2);
    printf("Press Ctrl+C to stop.\n\n");
    fflush(stdout);

    int consecutive_errors = 0;

    while (g_running) {
        int mic1_raw = mcp3008_read(g_spi_fd, 0);
        int mic2_raw = mcp3008_read(g_spi_fd, 1);

        if (mic1_raw < 0 || mic2_raw < 0) {
            consecutive_errors++;
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive SPI errors; aborting.\n");
                break;
            }
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        consecutive_errors = 0;

        /* Convert 10-bit ADC values to signed 16-bit samples */
        int16_t mic1 = (int16_t)mic1_raw;
        int16_t mic2 = (int16_t)mic2_raw;

        int16_t out = noise_cancel(mic1, mic2, gain1, gain2);

        printf("%d,%d,%d\n", mic1, mic2, out);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

