/*
 * Raspberry Pi 4 Model B – Vegetronix VH400 soil moisture logger
 *
 * Hardware:
 *   - Vegetronix VH400 analog output  -> MCP3008 CH0
 *   - MCP3008 SPI0 CE0 (GPIO 8)       -> SPI0 SCLK (GPIO 11)
 *   - MCP3008 SPI0 CE0 (GPIO 8)       -> SPI0 MOSI (GPIO 10)
 *   - MCP3008 SPI0 CE0 (GPIO 8)       -> SPI0 MISO (GPIO 9)
 *   - MCP3008 VDD 3.3 V              -> 3.3 V
 *   - MCP3008 VREF 3.3 V             -> 3.3 V
 *   - MCP3008 AGND / DGND           -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o moisture_logger moisture_logger.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./moisture_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO 8) */
#define SPI_SPEED      1000000    /* 1 MHz – well within MCP3008 spec */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define LOG_FILE       "moisture_log.txt"
#define SAMPLE_PERIOD  60         /* seconds between readings */
#define ADC_MAX        1023       /* 10-bit ADC full-scale code */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *
 * Result:
 *   rx[1] bits 1..0  -> MSB of ADC result
 *   rx[2]           -> LSB of ADC result
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *timestamp, int adc_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, adc_value) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VH400 soil moisture logger started.\n");
    printf("SPI0 CE0 @ %d Hz, MCP3008 CH0, logging to %s every %d s.\n",
           SPI_SPEED, LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
        } else {
            char timestamp[32];
            if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
                fprintf(stderr, "Failed to generate timestamp.\n");
            } else {
                if (log_data(timestamp, adc_value) != 0) {
                    fprintf(stderr, "Failed to log data.\n");
                } else {
                    printf("%s  ADC: %4d\n", timestamp, adc_value);
                }
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

