static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ambient_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s; using default 25.0 C\n",
                TEMP_FILE, strerror(errno));
        return 25000;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Warning: invalid temperature in %s; using default 25.0 C\n",
                TEMP_FILE);
        temp = 25000;
    }
    fclose(fp);
    return temp;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc < 0 || adc > ADC_MAX) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc);
        return -1;
    }
    return adc;
}

static float adc_to_voltage(int adc) {
    return (float)adc * VREF / (float)ADC_MAX;
}

static float compensate_voltage(float voltage, int temp_raw) {
    float temp_c = (float)temp_raw / 1000.0f;
    return voltage * (1.0f + (temp_c - 25.0f) * 0.0033f);
}

static int detect_flame(float voltage) {
    return (voltage > 1.0f) ? 1 : 0;
}

static void log_data(int raw, float v, float cv, float temp, int flame) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (!localtime_r(&now, &tm_info)) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_fp, "%s,%d,%.3f,%.3f,%.2f,%d\n", ts, raw, v, cv, temp, flame);
    fflush(log_fp);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        fclose(log_fp);
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(BUZZER_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: cannot open %s: %s\n", BUZZER_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Error: cannot get GPIO line %d: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO line %d as output: %s\n",
                BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int temp_raw = read_ambient_temp();
        int adc = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && adc < 0) {
            adc = read_mcp3008(ADC_CHANNEL);
            if (adc < 0) {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Retrying ADC read (%d/%d)...\n", retries, MAX_RETRIES);
                    usleep(100000);
                }
            }
        }

        if (adc < 0) {
            fprintf(stderr, "Error: ADC read failed after %d retries; skipping iteration\n",
                    MAX_RETRIES);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_US);
            continue;
        }

        float voltage = adc_to_voltage(adc);
        float compensated = compensate_voltage(voltage, temp_raw);
        int flame = detect_flame(compensated);

        if (gpiod_line_set_value(buzzer_line, flame) < 0) {
            fprintf(stderr, "Warning: failed to set buzzer: %s\n", strerror(errno));
        }

        log_data(adc, voltage, compensated, (float)temp_raw / 1000.0f, flame);

        usleep(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

