#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 (GPIO 8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define LED_GPIO       17         /* BCM 17 */
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW  70.0
#define JSON_FILE      "water_levels.json"
#define SAMPLE_PERIOD_US 5000000  /* 5 seconds */
#define LOOP_DELAY_US  100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_json_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0–7)                            */
/* Returns 0–1023 on success, -1 on SPI transfer error                 */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
     *   tx[2] = 0x00                       (clock out low bits)
     * Result:
     *   rx[1] bits 1:0  -> high 2 bits of ADC value
     *   rx[2]          -> low 8 bits of ADC value
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value (0–1023) to water-level percentage               */
/* ------------------------------------------------------------------ */
static double adc_to_percentage(int adc_value)
{
    return ((double)adc_value / 1023.0) * 100.0;
}

/* ------------------------------------------------------------------ */
/* Append one JSON object to the array file                            */
/* ------------------------------------------------------------------ */
static int log_to_json(double percentage)
{
    if (g_json_file == NULL) {
        fprintf(stderr, "JSON file not open\n");
        return -1;
    }

    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    /* Millisecond precision */
    long ms = timeinfo.tm_sec * 1000L + timeinfo.tm_nsec / 1000000L;

    if (fprintf(g_json_file,
                "{\"timestamp\": \"%s.%03ld\", \"water_level\": %.2f},\n",
                timestamp, ms, percentage) < 0) {
        fprintf(stderr, "fprintf to JSON failed\n");
        return -1;
    }

    if (fflush(g_json_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_json_file != NULL) {
        /* Write closing ']' and flush */
        if (fprintf(g_json_file, "]\n") < 0)
            fprintf(stderr, "Warning: failed to write closing ']' to JSON\n");
        if (fflush(g_json_file) != 0)
            fprintf(stderr, "Warning: fflush failed on JSON file\n");
        fclose(g_json_file);
        g_json_file = NULL;
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Ensure LED is off */
    gpioWrite(LED_GPIO, 0);

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open JSON file for appending */
    g_json_file = fopen(JSON_FILE, "a");
    if (g_json_file == NULL) {
        fprintf(stderr, "Failed to open %s for appending\n", JSON_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write opening '[' so the file is a valid JSON array */
    if (fprintf(g_json_file, "[\n") < 0) {
        fprintf(stderr, "Failed to write opening '[' to JSON\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (fflush(g_json_file) != 0) {
        fprintf(stderr, "Failed to flush JSON file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    int led_on = 0;

    while (g_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double percentage = adc_to_percentage(adc_value);
        printf("Water level: %.2f%%\n", percentage);

        if (log_to_json(percentage) != 0) {
            fprintf(stderr, "Failed to log data to JSON\n");
        }

        /* Hysteresis LED control */
        if (percentage > WATER_LEVEL_THRESHOLD_HIGH && !led_on) {
            gpioWrite(LED_GPIO, 1);
            led_on = 1;
        } else if (percentage < WATER_LEVEL_THRESHOLD_LOW && led_on) {
            gpioWrite(LED_GPIO, 0);
            led_on = 0;
        }

        /* Sleep in ~100 ms increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(LOOP_DELAY_US);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

