/*
 * plant_monitor.c — Raspberry Pi Zero W soil-moisture monitor
 *
 * Hardware:
 *   - HiLetgo Soil Moisture Sensor (analog resistive) -> MCP3008 CH0
 *   - MCP3008 SPI: CE0 (GPIO 8), SCLK (GPIO 11), MOSI (GPIO 10), MISO (GPIO 9)
 *   - VDD 3.3 V, VREF 3.3 V, AGND/DGND common to Pi
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o plant_monitor plant_monitor.c -lpigpio -lrt
 *
 * Run:
 *   ./plant_monitor [-c channel] [-a adc_channel] [-m min_value] [-M max_value]
 *                   [-t threshold] [-i interval_sec] [-e email] [-f msmtp_conf]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL      0
#define DEFAULT_ADC_CHANNEL      0
#define DEFAULT_MIN_VALUE        300
#define DEFAULT_MAX_VALUE        700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_EMAIL_RECIPIENT  "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG     "/etc/msmtprc"
#define LOG_FILE                 "plant_data.txt"
#define SPI_SPEED_HZ             500000
#define SPI_FLAGS                0          /* mode 0, active-low CE */
#define ADC_MAX_VALUE            1023
#define SAMPLE_DELAY_US          100000     /* 100 ms between samples */

typedef struct {
    int  spi_channel;
    int  adc_channel;
    int  min_value;
    int  max_value;
    int  moisture_threshold;
    int  logging_interval;
    char email_recipient[256];
    char msmtp_config[256];
} Config;

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Configuration                                                       */
/* ------------------------------------------------------------------ */
static void parse_arguments(int argc, char *argv[], Config *cfg)
{
    cfg->spi_channel        = DEFAULT_SPI_CHANNEL;
    cfg->adc_channel        = DEFAULT_ADC_CHANNEL;
    cfg->min_value          = DEFAULT_MIN_VALUE;
    cfg->max_value          = DEFAULT_MAX_VALUE;
    cfg->moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    cfg->logging_interval   = DEFAULT_LOGGING_INTERVAL;
    strncpy(cfg->email_recipient, DEFAULT_EMAIL_RECIPIENT,
            sizeof(cfg->email_recipient) - 1);
    cfg->email_recipient[sizeof(cfg->email_recipient) - 1] = '\0';
    strncpy(cfg->msmtp_config, DEFAULT_MSMTP_CONFIG,
            sizeof(cfg->msmtp_config) - 1);
    cfg->msmtp_config[sizeof(cfg->msmtp_config) - 1] = '\0';

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            cfg->spi_channel = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            cfg->adc_channel = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-m") == 0 && i + 1 < argc) {
            cfg->min_value = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-M") == 0 && i + 1 < argc) {
            cfg->max_value = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            cfg->moisture_threshold = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            cfg->logging_interval = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-e") == 0 && i + 1 < argc) {
            strncpy(cfg->email_recipient, argv[++i],
                    sizeof(cfg->email_recipient) - 1);
            cfg->email_recipient[sizeof(cfg->email_recipient) - 1] = '\0';
        } else if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            strncpy(cfg->msmtp_config, argv[++i],
                    sizeof(cfg->msmtp_config) - 1);
            cfg->msmtp_config[sizeof(cfg->msmtp_config) - 1] = '\0';
        } else {
            fprintf(stderr,
                    "Usage: %s [-c channel] [-a adc_channel] [-m min_value] "
                    "[-M max_value] [-t threshold] [-i interval_sec] "
                    "[-e email] [-f msmtp_conf]\n", argv[0]);
            exit(EXIT_FAILURE);
        }
    }

    if (cfg->min_value < 0 || cfg->min_value > ADC_MAX_VALUE) {
        fprintf(stderr, "Error: min_value must be 0–%d\n", ADC_MAX_VALUE);
        exit(EXIT_FAILURE);
    }
    if (cfg->max_value < 0 || cfg->max_value > ADC_MAX_VALUE) {
        fprintf(stderr, "Error: max_value must be 0–%d\n", ADC_MAX_VALUE);
        exit(EXIT_FAILURE);
    }
    if (cfg->min_value >= cfg->max_value) {
        fprintf(stderr, "Error: min_value must be less than max_value\n");
        exit(EXIT_FAILURE);
    }
    if (cfg->moisture_threshold < 0 || cfg->moisture_threshold > 100) {
        fprintf(stderr, "Error: moisture_threshold must be 0–100\n");
        exit(EXIT_FAILURE);
    }
    if (cfg->logging_interval <= 0) {
        fprintf(stderr, "Error: logging_interval must be positive\n");
        exit(EXIT_FAILURE);
    }
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 *   rx[1] bits 1:0 + rx[2] bits 7:0    -> 10-bit result
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Moisture percentage (linear interpolation)                          */
/* ------------------------------------------------------------------ */
static int calculate_moisture_percentage(int adc_value, int min_value,
                                          int max_value)
{
    if (adc_value < min_value) adc_value = min_value;
    if (adc_value > max_value) adc_value = max_value;

    int range = max_value - min_value;
    if (range == 0) return 0;

    return (int)(((float)(adc_value - min_value) / (float)range) * 100.0f);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *log_file, int moisture_percentage)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s, %d\n", timestamp, moisture_percentage) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
    } else {
        fflush(log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Email alert via msmtp (popen pipe, no shell interpolation)           */
/* ------------------------------------------------------------------ */
static void send_email_alert(const char *recipient, const char *msmtp_config,
                             int moisture_percentage)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed for email\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed for email\n");
        return;
    }

    char command[512];
    snprintf(command, sizeof(command),
             "msmtp -C '%s' '%s'", msmtp_config, recipient);

    FILE *fp = popen(command, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: popen(%s) failed: %s\n",
                command, strerror(errno));
        return;
    }

    fprintf(fp, "Subject: Plant Moisture Alert\n");
    fprintf(fp, "To: %s\n", recipient);
    fprintf(fp, "From: plant_monitor@example.com\n");
    fprintf(fp, "\n");
    fprintf(fp, "Plant moisture level is below threshold (%d%%).\n",
            moisture_percentage);
    fprintf(fp, "Timestamp: %s\n", timestamp);

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed: %s\n", strerror(errno));
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n",
                WEXITSTATUS(status));
    } else if (WIFSIGNALED(status)) {
        fprintf(stderr, "Error: msmtp killed by signal %d\n",
                WTERMSIG(status));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    Config cfg;
    parse_arguments(argc, argv, &cfg);

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(cfg.spi_channel, SPI_SPEED_HZ, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz): %s\n",
                cfg.spi_channel, SPI_SPEED_HZ, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file open --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("Plant moisture monitoring started.\n");
    printf("  SPI channel: %d, ADC channel: %d\n", cfg.spi_channel, cfg.adc_channel);
    printf("  Min value: %d, Max value: %d, Threshold: %d%%\n",
           cfg.min_value, cfg.max_value, cfg.moisture_threshold);
    printf("  Logging interval: %d s, Email recipient: %s\n",
           cfg.logging_interval, cfg.email_recipient);
    printf("  Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, cfg.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed, retrying in %d s\n",
                    cfg.logging_interval);
        } else {
            int moisture_percentage =
                calculate_moisture_percentage(adc_value, cfg.min_value,
                                               cfg.max_value);

            log_data(g_log_file, moisture_percentage);

            if (moisture_percentage < cfg.moisture_threshold) {
                send_email_alert(cfg.email_recipient, cfg.msmtp_config,
                                 moisture_percentage);
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
