/*
 * soil_moisture.c — Raspberry Pi 3 Model B+
 *
 * Monitors a Keyes KY-036 analog soil moisture sensor via an MCP3008 ADC
 * (SPI0, CE0, 1 MHz, mode 0).  Logs raw ADC values and moisture percentage
 * to soil_moisture.log every argv[1] seconds (default 1).
 *
 * Build:  gcc -O2 -Wall -Wextra -o soil_moisture soil_moisture.c
 * Run:    ./soil_moisture [interval_seconds]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define MCP3008_CHANNEL 0          /* KY-036 analog out -> MCP3008 CH0 */
#define LOG_FILE        "soil_moisture.log"
#define DEFAULT_INTERVAL 1

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto fail;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto fail;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_reading(int adc_value, float moisture_pct)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (!tm_info) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s, ADC: %d, Moisture: %.2f%%\n",
                ts, adc_value, moisture_pct) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
    }

    if (fflush(g_log_fp) == EOF) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int interval = DEFAULT_INTERVAL;

    if (argc > 1) {
        char *endptr = NULL;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val <= 0 || val > 3600) {
            fprintf(stderr, "Usage: %s [interval_seconds]\n", argv[0]);
            return EXIT_FAILURE;
        }
        interval = (int)val;
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        return EXIT_FAILURE;
    }

    if (log_open() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Logging to %s every %d s.\n",
           LOG_FILE, interval);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = mcp3008_read(MCP3008_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "Warning: ADC read failed; skipping cycle.\n");
        } else {
            /*
             * KY-036 analog output: higher voltage -> drier soil.
             * Map 0..1023 to 100..0 percent.
             */
            float moisture_pct = 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
            log_reading(adc_value, moisture_pct);
            printf("ADC: %4d  Moisture: %5.2f%%\n", adc_value, moisture_pct);
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < interval && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

