#define SAMPLE_PERIOD_S 5          /* seconds between readings */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 *
 * MCP3008 SPI protocol (3 bytes, Mode 0, MSB-first):
 *   Byte 0: 0x01                       (start bit)
 *   Byte 1: (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   Byte 2: 0x00                       (clock out remaining bits)
