 * Response:
 *   rx[0] = ignored
 *   rx[1] = [null bit][b9 b8] in lower 2 bits
 *   rx[2] = b7..b0
 *
 * 10-bit result = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *out_value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

