    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *out_value = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

int main(void)
{
    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure SPI mode --- */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Configure bits per word --- */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* --- Configure max speed --- */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor v2.0 via MCP3008\n");
    printf("SPI device: %s | Channel: %d | Sample period: %d s\n",
           SPI_DEVICE, ADC_CHANNEL, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(spi_fd, ADC_CHANNEL, &adc_value) == 0) {
            /*
             * DFRobot Soil Moisture Sensor v2.0:
             *   - Higher ADC value = drier soil.
             *   - 0–3000 mV = 100 % moisture.
             *   - 3000–7000 mV = 0 % moisture.
             *
             * Convert 10-bit ADC value to moisture percentage.
             * 0–1023 ADC = 100 % moisture.
             * 1023–0 ADC = 0 % moisture.
             */
            float moisture_pct = 100.0f - ((float)adc_value / 1023.0f) * 100.0f;

            if (moisture_pct < 0.0f)   moisture_pct = 0.0f;
            if (moisture_pct > 100.0f) moisture_pct = 100.0f;

            printf("Raw ADC: %4u | Moisture: %5.1f %%\n", adc_value, moisture_pct);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++) {
            sleep(1);
        }
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (close(spi_fd) < 0) {
        fprintf(stderr, "Warning: error closing SPI device: %s\n", strerror(errno));
    }

    return EXIT_SUCCESS;
}

