/*
 * Raspberry Pi 4 Model B – MLX90823 Pressure Sensor Reader
 *
 * Hardware:
 *   - MLX90823 analog pressure sensor (0–3.3 V output)
 *   - MCP3008 10-bit ADC on SPI0 (CE0 = GPIO8, MISO = GPIO9, MOSI = GPIO10, SCLK = GPIO11)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90823_reader mlx90823_reader.c
 *
 * Run:
 *   sudo ./mlx90823_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz – well within MCP3008 3.3 V limit */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE   1023       /* 10-bit ADC */
#define ADC_VREF        3.3f       /* MCP3008 reference voltage */

#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI initialization                                                  */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *
 * Result:
 *   rx[1] bits 1..0  + rx[2] bits 7..0  = 10-bit ADC value
 */
static int mcp3008_read(uint8_t channel, uint16_t *adc_value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u (must be 0–7)\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Pressure conversion                                                */
/* ------------------------------------------------------------------ */
/*
 * MLX90823 transfer function (simplified linear approximation):
 *   Vout = Vref * (P / P_max)
 *   P = (Vout / Vref) * P_max
 *
 * With Vref = 3.3 V and P_max = 3.3 bar, the pressure range is 0–3.3 bar.
 */
static float adc_to_pressure(uint16_t adc_value)
{
    return ((float)adc_value / (float)ADC_MAX_VALUE) * 3.3f;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                   */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
