    }

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI device: %s | ADC channel: %d | Vref: %.1f V | Max pressure: 3.3 bar\n",
           SPI_DEVICE, ADC_CHANNEL, ADC_VREF);
    printf("Press Ctrl+C to exit.\n\n");

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(ADC_CHANNEL, &adc_value) != 0) {
            consecutive_errors++;
            fprintf(stderr, "ADC read error (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive SPI errors. Aborting.\n");
                break;
            }
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        consecutive_errors = 0;

        /* Sensor-absent / wiring fault detection */
        if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr, "%s WARNING: ADC saturated at %u – sensor absent or wiring fault\n",
                    ts, adc_value);
        }

        float pressure = adc_to_pressure(adc_value);

        char ts[32];
        get_timestamp(ts, sizeof(ts));
        printf("%s Pressure: %.2f bar (ADC: %u)\n", ts, pressure, adc_value);
        fflush(stdout);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    /* Clean shutdown */
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

