{
    int spi_fd = -1;
    int ret_code = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto cleanup;
    }

    printf("Soil Moisture Sensor Data Acquisition\n");
    printf("SPI device: %s | Mode: %u | Bits: %u | Speed: %u Hz\n",
           SPI_DEVICE, mode, bits, speed);
    printf("Sampling channel %d every %d seconds. Press Ctrl+C to exit.\n",
           ADC_CHANNEL, SAMPLE_PERIOD_S);
    fflush(stdout);

    while (g_running) {
        int adc_value = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
        } else if (adc_value == ADC_MIN || adc_value == ADC_MAX) {
            fprintf(stderr,
                    "Warning: ADC value at extreme (%d). Sensor may be absent "
                    "or wiring fault.\n", adc_value);
        } else {
            log_data(adc_value);
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0) {
        if (close(spi_fd) < 0) {
            perror("close(spi_fd)");
        }
    }
    return ret_code;
}

