    printf("Logging MCP3008 channels 0-3 to %s every %d s. Press Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_PERIOD_S);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            adc[i] = mcp3008_read(spi_fd, (uint8_t)i);
            if (adc[i] < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                error = 1;
                break;
            }
        }

        if (error) {
            fprintf(stderr, "SPI communication error – continuing after delay.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        float v[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++)
            v[i] = adc_to_voltage(adc[i]);

        if (log_data(fp, v[0], v[1], v[2], v[3]) != 0) {
            fprintf(stderr, "Logging failed – continuing after delay.\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly.\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0)
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
    }
    if (spi_fd >= 0) {
        if (close(spi_fd) != 0)
            fprintf(stderr, "close(spi_fd) failed: %s\n", strerror(errno));
    }
    return ret_code;
}

