/*
 * Raspberry Pi 3 Model B+ — Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 CE0 (bus 0, channel 0), 1 MHz, mode 0
 *     VH400 analog out  -> MCP3008 CH0
 *     MCP3008 VDD/VREF -> 3.3 V
 *     MCP3008 AGND/DGND -> GND
 *   - 12 V water pump via relay on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vh400_monitor vh400_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./vh400_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* SPI0 CE0 (BCM 8)                       */
#define SPI_SPEED        1000000    /* 1 MHz                                  */
#define SPI_FLAGS        0          /* Mode 0, active-low CE handled by pigpio */

#define PUMP_GPIO        17         /* Relay control (BCM 17)                 */

#define MOISTURE_CHANNEL 0          /* MCP3008 single-ended channel 0          */

#define MOISTURE_LOW     300        /* Below this -> pump ON                   */
#define MOISTURE_HIGH    600        /* Above this -> pump OFF                  */

#define BUFFER_SIZE      20
#define SAMPLE_PERIOD_US 5000000    /* 5 s                                    */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static bool     g_pump_on    = false;

/*
 * Circular buffer of moisture readings and pump states.
 * Accessed from the timer callback (pigpio thread) and the main loop.
 */
typedef struct {
    time_t timestamp;
    int    moisture;
    bool   pump_on;
} Reading;

static Reading g_buffer[BUFFER_SIZE];
static int     g_head = 0;
static int     g_count = 0;

/* --------------------------- Function prototypes ------------------------- */

static int  read_mcp3008(int channel);
static void pump_set(bool on);
static void timer_callback(void *userdata);
static void signal_handler(int sig);
static void buffer_add(int moisture, bool pump_on);
static void buffer_print(void);

/* ------------------------------- MCP3008 --------------------------------- */

/*
 * Read a single-ended channel from the MCP3008.
 *
 * MCP3008 SPI protocol (3 bytes, mode 0, MSB-first):
 *   tx[0] = 0x01                       Start bit
 *   tx[1] = (0x08 | channel) << 4      SGL/DIFF=1 (single) + D2 D1 D0 in upper nibble
 *   tx[2] = 0x00                       Padding for clocking out low data bits
 *   rx[1] bits 1..0  + rx[2] bits 7..0  -> 10-bit result
 *
 * Returns 0–1023 on success, -1 on SPI transfer failure.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------- Pump ------------------------------------ */

static void pump_set(bool on)
{
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", PUMP_GPIO);
        return;
    }
    g_pump_on = on;
}

/* ----------------------------- Timer callback ----------------------------- */

static void timer_callback(void *userdata)
{
    (void)userdata;

    int moisture = read_mcp3008(MOISTURE_CHANNEL);
    if (moisture < 0) {
        fprintf(stderr, "Sensor read failed; skipping cycle\n");
        return;
    }

    /* Hysteresis control */
    if (moisture < MOISTURE_LOW && !g_pump_on) {
        pump_set(true);
    } else if (moisture > MOISTURE_HIGH && g_pump_on) {
        pump_set(false);
    }

    buffer_add(moisture, g_pump_on);
    buffer_print();
}

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Circular buffer ----------------------------- */

static void buffer_add(int moisture, bool pump_on)
{
    time(&g_buffer[g_head].timestamp);
    g_buffer[g_head].moisture = moisture;
    g_buffer[g_head].pump_on  = pump_on;

    g_head = (g_head + 1) % BUFFER_SIZE;
    if (g_count < BUFFER_SIZE) {
        g_count++;
    }
}

static void buffer_print(void)
{
    printf("\n--- Moisture Log (%d entries) ---\n", g_count);
    for (int i = 0; i < g_count; i++) {
        int idx = (g_head - g_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&g_buffer[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Moisture: %4d  Pump: %s\n",
               ts, g_buffer[idx].moisture,
               g_buffer[idx].pump_on ? "ON" : "OFF");
    }
    printf("----------------------------------\n");
    fflush(stdout);
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    pump_set(false);

    /* --- Open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Start 5-second timer --- */
    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set timer\n");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VH400 soil moisture monitor started.\n");
    printf("SPI0 CE0 @ 1 MHz, MCP3008 CH0, pump on GPIO17.\n");
    printf("Thresholds: low=%d high=%d  Press Ctrl+C to exit.\n",
           MOISTURE_LOW, MOISTURE_HIGH);

    /* --- Main loop — sleep until signal --- */
    while (g_running) {
        sleep(1);
    }

    /* --- Cleanup --- */
    gpioSetTimerFuncEx(0, 0, NULL, NULL);   /* stop timer */
    pump_set(false);
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

