code:
/*
 * MAX30102 Pulse Oximeter Health Monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   MAX30102 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MAX30102 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MAX30102 VDD -> 3.3 V
 *   MAX30102 GND -> GND
 *
 * Build: gcc -O2 -Wall -o health_monitor health_monitor.c -lpigpio -lrt
 * Run:   sudo ./health_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define MAX30102_ADDR       0x57          /* Default I2C address (ADDR pin tied to GND) */

#define REG_INTR_STATUS_1   0x00
#define REG_INTR_ENABLE_1   0x01
#define REG_FIFO_WR_PTR     0x02
#define REG_OVF_COUNTER     0x03
#define REG_FIFO_RD_PTR     0x04
#define REG_FIFO_DATA       0x05
#define REG_FIFO_CONFIG     0x08
#define REG_MODE_CONFIG     0x09
#define REG_SPO2_CONFIG     0x0A
#define REG_LED1_PA         0x0C
#define REG_LED2_PA         0x0D
#define REG_PART_ID         0xFF

#define EXPECTED_PART_ID    0x15

#define SPO2_THRESHOLD      95.0f
#define HEART_RATE_THRESHOLD 100.0f

#define SAMPLE_PERIOD_US    1000000       /* 1 second */
#define MEASUREMENT_DELAY_US 100000       /* 100 ms settling after mode change */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Forward Declarations ------------------------ */
static void signal_handler(int sig);
static int  max30102_write_reg(uint8_t reg, uint8_t value);
static int  max30102_read_reg(uint8_t reg, uint8_t *value);
static int  max30102_init(void);
static int  max30102_read_fifo(uint32_t *red, uint32_t *ir);
static int  max30102_calculate_hr_spo2(uint32_t red, uint32_t ir,
                                       float *heart_rate, float *spo2);
static void log_health_data(float heart_rate, float spo2);
static void log_error(const char *message);

/* ------------------------------- Signal Handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ I2C Helpers ------------------------------ */
static int max30102_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

static int max30102_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------ MAX30102 Init ---------------------------- */
static int max30102_init(void)
{
    uint8_t part_id = 0;

    /* Verify sensor presence by reading Part ID */
    if (max30102_read_reg(REG_PART_ID, &part_id) != 0) {
        log_error("Failed to read Part ID from MAX30102");
        return -1;
    }

    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n",
                part_id, EXPECTED_PART_ID);
        log_error("MAX30102 Part ID mismatch");
        return -1;
    }

    /* Reset the device */
    if (max30102_write_reg(REG_MODE_CONFIG, 0x40) != 0) {
        log_error("Failed to reset MAX30102");
        return -1;
    }
    gpioDelay(10000); /* 10 ms reset settling */

    /* Clear any pending interrupts */
    if (max30102_write_reg(REG_INTR_STATUS_1, 0x00) != 0) {
        log_error("Failed to clear interrupt status");
        return -1;
    }

    /* Configure FIFO: sample averaging 1, FIFO rollover disabled, 18-bit */
    if (max30102_write_reg(REG_FIFO_CONFIG, 0x0F) != 0) {
        log_error("Failed to configure FIFO");
        return -1;
    }

    /* Configure Mode: SpO2 mode, Red and IR LEDs enabled */
    if (max30102_write_reg(REG_MODE_CONFIG, 0x03) != 0) {
        log_error("Failed to set SpO2 mode");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);

    /* Configure SpO2: 4096 ADC range, 100 Hz sample rate */
    if (max30102_write_reg(REG_SPO2_CONFIG, 0x27) != 0) {
        log_error("Failed to configure SpO2");
        return -1;
    }

    /* Configure LED pulse amplitudes (Red 440 nA, IR 440 nA) */
    if (max30102_write_reg(REG_LED1_PA, 0x24) != 0) {
        log_error("Failed to configure LED1 PA");
        return -1;
    }
    if (max30102_write_reg(REG_LED2_PA, 0x24) != 0) {
        log_error("Failed to configure LED2 PA");
        return -1;
    }

    return 0;
}

/* --------------------------- FIFO Data Read ------------------------------ */
static int max30102_read_fifo(uint32_t *red, uint32_t *ir)
{
    uint8_t wr_ptr = 0, rd_ptr = 0;
    uint8_t data[6];
    int bytes_read;

    if (max30102_read_reg(REG_FIFO_WR_PTR, &wr_ptr) != 0)
        return -1;
    if (max30102_read_reg(REG_OVF_COUNTER, &rd_ptr) != 0)
        return -1;

    /* Check for overflow (OVF bit in status register) */
    uint8_t status = 0;
    if (max30102_read_reg(REG_INTR_STATUS_1, &status) != 0)
        return -1;
    if (status & 0x10) {
        fprintf(stderr, "FIFO overflow detected\n");
        log_error("FIFO overflow detected");
        /* Clear overflow by writing to FIFO_WR_PTR */
        if (max30102_write_reg(REG_FIFO_WR_PTR, 0x00) != 0)
            return -1;
        return -1;
    }

    /* Read up to 3 samples (6 bytes) */
    bytes_read = i2cReadI2CBlockData(g_i2c_handle, REG_FIFO_DATA,
                                    (char *)data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "FIFO read error: expected 6 bytes, got %d\n", bytes_read);
        log_error("FIFO read error");
        return -1;
    }

    /* Data is 18-bit left-justified; shift right 2 to get 16-bit value */
    *red = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | data[2];
    *red >>= 2;
    *ir  = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];
    *ir >>= 2;

    return 0;
}

/* ------------------------- SpO2 / Heart Rate Calc ------------------------ */
static int max30102_calculate_hr_spo2(uint32_t red, uint32_t ir,
                                       float *heart_rate, float *spo2)
{
    /*
     * Placeholder SpO2 / heart-rate calculation.
     * A real implementation would use a full pulse-detection algorithm
     * (e.g., PPG peak detection) and a robust SpO2 estimator.
     */
    (void)red;
    (void)ir;

    *heart_rate = 72.0f;
    *spo2       = 98.0f;

    return 0;
}

/* ----------------------------- Logging Helpers ----------------------------- */
static void log_health_data(float heart_rate, float spo2)
{
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        perror("Error opening health_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&t, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp) - 1);
        timestamp[sizeof(timestamp) - 1] = '\0';
    }

