        float heart_rate = 0.0f, spo2 = 0.0f;

        if (max30102_read_fifo(&red, &ir) == 0) {
            if (max30102_calculate_hr_spo2(red, ir, &heart_rate, &spo2) == 0) {
                printf("Heart Rate: %.2f BPM, SpO2: %.2f%%\n", heart_rate, spo2);

                if (spo2 < SPO2_THRESHOLD) {
