#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 on SPI0 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define NUM_CHANNELS   3
#define LOG_FILE       "analog_log.csv"
#define SAMPLE_US      500000     /* 500 ms */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one single-ended channel from the MCP3008                       */
/* Returns 0–1023 on success, -1 on SPI error, -2 on invalid channel   */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d (must be 0–7)\n", channel);
        return -2;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out low bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n",
                channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC code (0–1023) to voltage (Vref = 3.3 V)                 */
/* ------------------------------------------------------------------ */
static float adc_to_voltage(int adc_value)
{
    return (float)adc_value * 3.3f / 1023.0f;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row: timestamp,channel,voltage                        */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int channel, float voltage)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "gmtime_r failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

    fprintf(fp, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append mode) --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Channel,Voltage\n");
        fflush(g_log_file);
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging MCP3008 channels 0-2 to %s every 500 ms. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        for (int ch = 0; ch < NUM_CHANNELS; ch++) {
            int adc_value = -1;
            int retries = 0;

            while (retries < MAX_RETRIES && adc_value < 0) {
                adc_value = read_mcp3008(ch);
                if (adc_value < 0) {
                    retries++;
                    if (retries < MAX_RETRIES) {
                        fprintf(stderr, "Retrying channel %d (%d/%d)...\n",
                                ch, retries, MAX_RETRIES);
                        gpioDelay(10000); /* 10 ms backoff */
                    }
                }
            }

            if (adc_value >= 0) {
                float voltage = adc_to_voltage(adc_value);
                log_data(g_log_file, ch, voltage);
                printf("Channel %d: %.3f V\n", ch, voltage);
            } else {
                fprintf(stderr, "Failed to read channel %d after %d retries\n",
                        ch, MAX_RETRIES);
                /* Log the failure with a sentinel value */
                log_data(g_log_file, ch, -1.0f);
            }
        }

        /* Sleep 500 ms (interruptible by signals) */
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

