#define ADS1115_ADDR       0x48          /* A0 tied to GND */

#define RELAY_GPIO_LINE    17            /* BCM 17 — active-high relay */
#define DOOR_SENSOR_LINE   27            /* BCM 27 — active-low reed */

#define LOG_FILE           "/var/log/door_events.log"
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_MS 50
#define SAMPLE_INTERVAL_MS  200
#define RELAY_PULSE_MS     3000
#define ADC_MAX_VALUE      32767.0f      /* 16-bit signed positive max */

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15   OS      = 1  (start single conversion)
 *   Bits14:12 MUX     = 100 (AIN0 vs GND)
 *   Bits11:9  PGA     = 001 (+/-4.096 V)
 *   Bit  8    MODE    = 1  (single-shot)
 *   Bits7:5   DR      = 100 (128 SPS)
 *   Bit  4    COMP_MODE = 0
 *   Bit  3    COMP_POL  = 0
 *   Bit  2    COMP_LAT  = 0
 *   Bits1:0   COMP_QUE = 11 (disable comparator)
 * => 0xC183
 */
#define ADS1115_CONFIG_BASE 0xC183

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static struct gpiod_chip  *g_chip  = NULL;
static struct gpiod_line  *g_relay = NULL;
static struct gpiod_line  *g_door  = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Logging helpers ----------------------------- */
static void log_event(const char *event)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        char tbuf[32];
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000L, event);
    } else {
        fprintf(fp, "[timestamp error]: %s\n", event);
    }

    fclose(fp);
}

/* --------------------------- I2C helpers -------------------------------- */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* --------------------------- ADS1115 ADC -------------------------------- */
static int ads1115_read_raw(int fd, int16_t *raw_out)
{
    uint16_t cfg = ADS1115_CONFIG_BASE;
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, cfg) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS, use 10 ms) */
    usleep(10000);

    uint16_t conv;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &conv) < 0)
        return -1;

    *raw_out = (int16_t)conv;
    return 0;
}

/* --------------------------- Distance calibration ------------------------ */
static int calibrate_distance(int fd, float *threshold_out)
{
    float sum = 0.0f;
    int   ok  = 0;

    printf("Calibrating distance sensor (%d samples)...\n", CALIBRATION_SAMPLES);

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int16_t raw;
        if (ads1115_read_raw(fd, &raw) < 0) {
            fprintf(stderr, "Calibration sample %d failed\n", i + 1);
            continue;
        }
        float voltage = (raw / ADC_MAX_VALUE) * 4.096f;
        /*
         * GP2Y0A21YK0F transfer function (approximate):
         *   distance (cm) = 27.0 / (voltage - 0.1)
         *   (valid for ~10 cm to ~80 cm; adjust constants for your sensor)
         */
        float distance = 27.0f / (voltage - 0.1f);
        sum += distance;
        ok++;
        usleep(CALIBRATION_DELAY_MS * 1000);
    }

    if (ok == 0) {
        fprintf(stderr, "Calibration failed: no valid samples\n");
        return -1;
    }

    *threshold_out = sum / ok;
    printf("Calibration complete. Threshold: %.2f cm\n", *threshold_out);
    return 0;
}

/* --------------------------- Relay control ------------------------------- */
static int relay_set(int state)
{
    if (gpiod_line_set_value(g_relay, state) < 0) {
        fprintf(stderr, "Failed to set relay GPIO %d: %s\n",
                RELAY_GPIO_LINE, strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- Door sensor -------------------------------- */
static int door_is_open(void)
{
    int val = gpiod_line_get_value(g_door);
    if (val < 0) {
        fprintf(stderr, "Failed to read door sensor GPIO %d: %s\n",
                DOOR_SENSOR_LINE, strerror(errno));
        return -1;
    }
    return (val == 0) ? 1 : 0;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_relay) {
        relay_set(0);
        gpiod_line_release(g_relay);
        g_relay = NULL;
    }
    if (g_door) {
        gpiod_line_release(g_door);
        g_door = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request lines */
    g_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!g_chip) {
        /* Fallback for older kernels */
        g_chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!g_chip) {
        fprintf(stderr, "Cannot open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_relay = gpiod_chip_get_line(g_chip, RELAY_GPIO_LINE);
    if (!g_relay) {
        fprintf(stderr, "Cannot get relay GPIO %d: %s\n",
                RELAY_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(g_relay, "door_lock_relay", 0) < 0) {
        fprintf(stderr, "Cannot request relay GPIO %d as output: %s\n",
                RELAY_GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_door = gpiod_chip_get_line(g_chip, DOOR_SENSOR_LINE);
    if (!g_door) {
        fprintf(stderr, "Cannot get door sensor GPIO %d: %s\n",
                DOOR_SENSOR_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input_flags(g_door, "door_sensor",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Cannot request door sensor GPIO %d as input: %s\n",
                DOOR_SENSOR_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Calibrate distance */
    float threshold = 0.0f;
    if (calibrate_distance(g_i2c_fd, &threshold) < 0) {
        fprintf(stderr, "Calibration failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring distance (threshold: %.2f cm). Press Ctrl+C to exit.\n",
           threshold);

    /* Main loop */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "ADC read failed; retrying in %d ms\n",
                    SAMPLE_INTERVAL_MS);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float voltage = (raw / ADC_MAX_VALUE) * 4.096f;
        float distance = 27.0f / (voltage - 0.1f);

        printf("Distance: %.2f cm\n", distance);

        if (distance < threshold) {
            printf("Distance below threshold. Activating relay.\n");
            if (relay_set(1) < 0) {
                fprintf(stderr, "Relay activation failed\n");
            } else {
                log_event("Door opened");

                int door_state = door_is_open();
                if (door_state < 0) {
                    fprintf(stderr, "Door sensor read failed\n");
                } else {
                    log_event(door_state ? "door opened" : "door not opened");
                }

                /* Hold relay for 3 s, checking for shutdown */
                for (int ms = 0; ms < RELAY_PULSE_MS && g_running; ms += 100)
                    usleep(100000);

                if (relay_set(0) < 0)
                    fprintf(stderr, "Relay deactivation failed\n");
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

