#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO 8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define PUMP_GPIO      18         /* BCM 18, active-high relay */
#define DEFAULT_THRESHOLD  30.0f   /* % of 0-3V range */
#define DEFAULT_DURATION   10      /* seconds */
#define DEFAULT_SLEEP      60      /* seconds */
#define LOG_FILE        "irrigation.log"
#define MAX_RETRIES      3
#define ADC_MAX         1023.0f
#define VREF            3.3f

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns 0-1023 on success, -1 on failure.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out low bits)
     * Result: bits 9-8 in rx[1] (masked 0x03), bits 7-0 in rx[2].
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc = ((rx[1] & 0x03) << 8) | rx[2];
            return adc;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d, ret=%d): %s\n",
                attempt + 1, MAX_RETRIES, ret, strerror(errno));
        gpioDelay(100000); /* 100 ms backoff */
    }
    return -1;
}

static float adc_to_moisture_pct(int adc)
{
    return (adc / ADC_MAX) * 100.0f;
}

static int control_pump(int state)
{
    if (gpioWrite(PUMP_GPIO, state) < 0) {
        fprintf(stderr, "Failed to write GPIO %d: %s\n",
                PUMP_GPIO, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[])
{
    float threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP;

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
        case 't':
            threshold = atof(optarg);
            if (threshold < 0.0f || threshold > 100.0f) {
                fprintf(stderr, "Threshold must be 0-100%%\n");
                return EXIT_FAILURE;
            }
            break;
        case 'd':
            duration = atoi(optarg);
            if (duration <= 0) {
                fprintf(stderr, "Duration must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 's':
            sleep_interval = atoi(optarg);
            if (sleep_interval <= 0) {
                fprintf(stderr, "Sleep interval must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-t threshold] [-d duration_s] [-s sleep_s]\n",
                    argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pump GPIO */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n",
                PUMP_GPIO, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (control_pump(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI bus */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %s\n",
                SPI_CHANNEL, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Irrigation system started");
    printf("Threshold: %.1f%% | Pump duration: %d s | Sleep interval: %d s\n",
           threshold, duration, sleep_interval);

    while (g_running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            log_message("Error: failed to read MCP3008 after retries");
            sleep(sleep_interval);
            continue;
        }

        float moisture = adc_to_moisture_pct(adc);
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Moisture: %.2f%% (ADC: %d)", moisture, adc);
        log_message(msg);

        if (moisture < threshold) {
            snprintf(msg, sizeof(msg),
                     "Moisture below threshold (%.1f%%), activating pump for %d s",
                     threshold, duration);
            log_message(msg);

            if (control_pump(1) == 0) {
                /*
                 * Sleep in 1-second increments so signals are caught
                 * promptly and the pump is turned off promptly.
                 */
                for (int i = 0; i < duration && g_running; i++) {
                    sleep(1);
                }
                control_pump(0);
            } else {
                log_message("Error: failed to activate pump");
            }

            snprintf(msg, sizeof(msg),
                     "Pump deactivated after %d s", duration);
            log_message(msg);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < sleep_interval && g_running; i++) {
            sleep(1);
        }
    }

    log_message("Shutting down irrigation system");
    cleanup();
    return EXIT_SUCCESS;
}

