/*
 * Raspberry Pi 3 Model B+ — Honeywell SS49E Hall-effect monitor
 *
 * Hardware:
 *   - Honeywell SS49E linear Hall-effect sensor on ADS1115 channel AIN0
 *   - ADS1115 on I2C bus 1, address 0x48
 *   - Motor shutdown indicator on GPIO27 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lgpiod -lm
 *
 * Run:
 *   sudo ./hall_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>

#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS             "/dev/i2c-1"
#define ADS1115_ADDR        0x48

#define ADS1115_REG_CONV    0x00
#define ADS1115_REG_CONFIG  0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15   OS      = 1  (start single conversion)
 *   Bits14:12 MUX     = 100 (AIN0 single-ended)
 *   Bits11:9  PGA     = 001 (+/-4.096 V)
 *   Bit  8    MODE    = 0  (single-shot)
 *   Bits7:5   DR      = 100 (128 SPS)
 *   Bit  4    COMP_MODE = 0
 *   Bit  3    COMP_POL  = 0
 *   Bit  2    COMP_LAT  = 0
 *   Bits1:0   COMP_QUE = 11 (disable comparator)
 */
#define ADS1115_CFG_BASE   0x8483

#define GPIO_CHIP           "gpiochip0"
#define GPIO_OFFSET         27

#define BUFFER_SIZE         10
#define SAMPLE_PERIOD_US    1000000  /* 1 Hz */
#define THRESHOLD_GAUSS     500.0f
#define VREF                4.096f   /* PGA full-scale range */
#define ADC_MAX             32767.0f /* 16-bit signed positive max */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static struct gpiod_chip  *g_chip  = NULL;
static struct gpiod_line  *g_line  = NULL;

/* --------------------------- Function prototypes ------------------------- */

static int  i2c_write_reg16(int fd, uint8_t reg, uint16_t val);
static int  i2c_read_reg16(int fd, uint8_t reg, uint16_t *out);
static int  ads1115_read_raw(int fd, int16_t *raw);
static float raw_to_voltage(int16_t raw);
static float voltage_to_gauss(float v);
static void buffer_add(float v);
static float buffer_average(void);
static void motor_shutdown(void);
static void motor_reset(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- I2C helpers ----------------------------- */

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        syslog(LOG_ERR, "I2C write to reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        syslog(LOG_ERR, "I2C write (reg select 0x%02X) failed: %s", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        syslog(LOG_ERR, "I2C read from reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* --------------------------- ADS1115 readings ----------------------------- */

/*
 * Trigger a single-shot conversion on AIN0 and read the raw 16-bit result.
 * Returns 0 on success, -1 on error.
 */
static int ads1115_read_raw(int fd, int16_t *raw)
{
    uint16_t cfg = ADS1115_CFG_BASE;

    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, cfg) != 0)
        return -1;

    /* 128 SPS → ~7.8 ms conversion; wait a bit longer for safety. */
    usleep(10000);

    uint16_t conv;
    if (i2c_read_reg16(fd, ADS1115_REG_CONV, &conv) != 0)
        return -1;

    *raw = (int16_t)conv;
    return 0;
}

static float raw_to_voltage(int16_t raw)
{
    return ((float)raw / ADC_MAX) * VREF;
}

static float voltage_to_gauss(float v)
{
    /*
     * SS49E transfer function (linear approximation):
     *   B = 1000 * V
     *   Gauss = B / 1000
     */
    return v * 1000.0f;
}

/* --------------------------- Circular buffer ----------------------------- */

static float g_buf[BUFFER_SIZE];
static int   g_buf_idx = 0;
static int   g_buf_count = 0;

static void buffer_add(float v)
{
    g_buf[g_buf_idx] = v;
    g_buf_idx = (g_buf_idx + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

static float buffer_average(void)
{
    if (g_buf_count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < g_buf_count; i++)
        sum += g_buf[i];
    return sum / (float)g_buf_count;
}

/* --------------------------- Motor control ------------------------------- */

static void motor_shutdown(void)
{
    if (g_line) {
        if (gpiod_line_set_value(g_line, 1) != 0)
            syslog(LOG_ERR, "Failed to set GPIO27 HIGH: %s", strerror(errno));
        else
            syslog(LOG_INFO, "Motor shutdown indicator set HIGH");
    }
}

static void motor_reset(void)
{
    if (g_line) {
        if (gpiod_line_set_value(g_line, 0) != 0)
            syslog(LOG_ERR, "Failed to set GPIO27 LOW: %s", strerror(errno));
        else
            syslog(LOG_INFO, "Motor shutdown indicator set LOW");
    }
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    motor_reset();

    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    closelog();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* --- I2C --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        syslog(LOG_ERR, "Cannot open %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        syslog(LOG_ERR, "Cannot set I2C slave 0x%02X: %s", ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- GPIO --- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        syslog(LOG_ERR, "Cannot open %s: %s", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_OFFSET);
    if (!g_line) {
        syslog(LOG_ERR, "Cannot get GPIO line %d: %s", GPIO_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_line, "hall_monitor", 0) < 0) {
        syslog(LOG_ERR, "Cannot request GPIO line %d as output: %s", GPIO_OFFSET, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Hall-effect monitor started (ADS1115 @ 0x%02X, GPIO%d)",
           ADS1115_ADDR, GPIO_OFFSET);

    /* --- Main loop --- */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_fd, &raw) != 0) {
            syslog(LOG_ERR, "ADC read failed; skipping sample");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = raw_to_voltage(raw);
        if (voltage < 0.0f || voltage > VREF) {
            syslog(LOG_ERR, "Voltage out of range: %.3f V (raw=%d)", voltage, raw);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        buffer_add(gauss);
        float avg = buffer_average();

        syslog(LOG_INFO, "Raw=%d  V=%.3f  B=%.2f G  Avg=%.2f G",
               raw, voltage, gauss, avg);

        if (avg > THRESHOLD_GAUSS) {
            syslog(LOG_WARNING, "Threshold exceeded (%.2f G > %.2f G); motor shutdown",
                   avg, THRESHOLD_GAUSS);
            motor_shutdown();
        }

        usleep(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down cleanly");
    cleanup();
    return EXIT_SUCCESS;
}

