/*
 * Raspberry Pi Zero W – Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 CE0 (GPIO8/GPIO9/GPIO10), SPI mode 0, 1 MHz
 *   - Vegetronix VH400 analog out -> MCP3008 CH0
 *   - Relay module (active-high) on GPIO18 (BCM)
 *
 * Behavior:
 *   - Reads CH0 every 60 s; when the 10-bit value drops below 300,
 *     activates the pump for 10 s, logs the event, and deactivates.
 *   - On SIGINT/SIGTERM, turns off the pump and exits cleanly.
 *   - Handles every API call with error checking.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vh400_monitor vh400_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./vh400_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* MCP3008 on SPI0 CE0 (BCM 8)            */
#define SPI_SPEED        1000000    /* 1 MHz                                  */
#define SPI_FLAGS        0          /* SPI mode 0, active-low CE              */

#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0         */
#define ADC_MAX          1023       /* 10-bit ADC full-scale code             */

#define MOISTURE_THRESHOLD 300      /* Below this -> watering                 */
#define PUMP_GPIO        18         /* BCM 18 – relay control                 */
#define PUMP_DURATION_S  10         /* Seconds to run the pump                */
#define SAMPLE_INTERVAL  60         /* Seconds between readings              */
#define LOG_FILE         "watering_events.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static int g_pump_gpio  = PUMP_GPIO;

/* --------------------------- Forward declarations ------------------------ */
static int  read_mcp3008(int channel, int *out_value);
static int  control_pump(int state);
static void log_event(int moisture_level);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[FATAL] spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (control_pump(0) != 0) {
        fprintf(stderr, "[FATAL] Failed to initialise pump GPIO %d low\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction");
        /* Non-fatal: continue running even if we cannot trap signals */
    }

    printf("VH400 soil moisture monitor started.\n");
    printf("  SPI0 CE0 @ %d Hz, MCP3008 CH%d, threshold %d, pump GPIO%d\n",
           SPI_SPEED, ADC_CHANNEL, MOISTURE_THRESHOLD, PUMP_GPIO);
    printf("  Sampling every %d s. Press Ctrl+C to exit.\n", SAMPLE_INTERVAL);

    /* --- Main loop --- */
    while (g_running) {
        int moisture_level = -1;

        if (read_mcp3008(ADC_CHANNEL, &moisture_level) != 0) {
            fprintf(stderr, "[ERROR] ADC read failed; skipping cycle\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (moisture_level < 0 || moisture_level > ADC_MAX) {
            fprintf(stderr, "[ERROR] ADC value out of range: %d\n", moisture_level);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        printf("Moisture level: %4d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("  Below threshold – activating pump for %d s\n", PUMP_DURATION_S);
            if (control_pump(1) != 0) {
                fprintf(stderr, "[ERROR] Failed to activate pump\n");
            } else {
                log_event(moisture_level);
                sleep(PUMP_DURATION_S);
                if (control_pump(0) != 0) {
                    fprintf(stderr, "[ERROR] Failed to deactivate pump\n");
                }
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- MCP3008 read -------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer, SPI mode 0):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 *
 * Returns 0 on success and stores the 10-bit value in *out_value.
 * Returns -1 on SPI transfer failure.
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "[ERROR] Invalid ADC channel %d (must be 0–7)\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "[ERROR] spiXfer returned %d (expected 3)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    *out_value = adc_value;
    return 0;
}

/* --------------------------- Pump control -------------------------------- */
static int control_pump(int state)
{
    if (gpioWrite(PUMP_GPIO, state ? 1 : 0) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, %d) failed\n", PUMP_GPIO, state);
        return -1;
    }
    return 0;
}

/* --------------------------- Event logging -------------------------------- */
static void log_event(int moisture_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s - Moisture level: %d\n", ts, moisture_level);
    } else {
        fprintf(fp, "<unknown time> - Moisture level: %d\n", moisture_level);
    }

    if (fclose(fp) != 0) {
        perror("[WARN] fclose(" LOG_FILE ")");
    }
}

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    /* Ensure pump is off before releasing resources */
    if (g_pump_gpio >= 0) {
        (void)gpioWrite(g_pump_gpio, 0);
    }

    if (g_spi_handle >= 0) {
        (void)spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    gpioTerminate();
}

