/*
 * Raspberry Pi – MCP3008 potentiometer-controlled motor PWM via SPI0 CE0.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND  (pin 6)
 *   MCP3008 DGND -> GND  (pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  pin 24)
 *   MCP3008 CH0  -> potentiometer wiper
 *   Motor +      -> GPIO18 (pin 12) via 1 kΩ series resistor
 *   Motor -      -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o motor_pwm motor_pwm.c -lpigpio -lrt
 * Run:    sudo ./motor_pwm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (BCM GPIO8)                       */
#define SPI_SPEED      1000000    /* 1 MHz – well within MCP3008 3.3 V limit    */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words          */

#define MOTOR_PIN      18         /* BCM GPIO18 – hardware PWM0                 */
#define PWM_FREQUENCY  1000       /* 1 kHz – motor driver requirement           */
#define PWM_RANGE      1023       /* 10-bit duty-cycle resolution               */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0             */
#define SAMPLE_PERIOD  100000     /* 100 ms between samples (microseconds)      */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Stop PWM output first so the motor is off even if the SPI bus is dead. */
    if (g_spi_handle >= 0) {
        gpioPWM(MOTOR_PIN, 0);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure motor PWM pin --- */
    if (gpioSetMode(MOTOR_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", MOTOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", MOTOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", MOTOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioPWM(MOTOR_PIN, 0);   /* Start with motor off */

    /* --- Open SPI0 CE0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz, flags 0x%02X).\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motor PWM control started.\n");
    printf("  SPI0 CE0 @ %d Hz, channel %d, ADC channel %d\n",
           SPI_SPEED, SPI_CHANNEL, ADC_CHANNEL);
    printf("  Motor on GPIO%d, PWM %d Hz, range %d\n",
           MOTOR_PIN, PWM_FREQUENCY, PWM_RANGE);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        /*
         * MCP3008 single-ended read (3-byte transfer, mode 0):
         *   tx[0] = 0x01                       (start bit)
         *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
         *   tx[2] = 0x00                       (clock out remaining bits)
         * Result:
         *   rx[1] bits 1..0  -> MSB of 10-bit result
         *   rx[2]           -> LSB of 10-bit result
         */
        char tx[3] = { 0x01, (char)((0x08 | ADC_CHANNEL) << 4), 0x00 };
        char rx[3] = { 0 };

        int ret = spiXfer(g_spi_handle, tx, rx, 3);
        if (ret != 3) {
            fprintf(stderr, "Warning: SPI transfer failed (returned %d).\n", ret);
            /* Brief pause before retrying to avoid tight error loop. */
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];

        /* Map 0..1023 ADC value to 0..1023 PWM duty cycle. */
        int pwm_value = adc_value;

        if (gpioPWM(MOTOR_PIN, pwm_value) < 0) {
            fprintf(stderr, "Warning: gpioPWM failed for value %d.\n", pwm_value);
        }

        printf("ADC: %4d  PWM: %4d\n", adc_value, pwm_value);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

