/*
 * Raspberry Pi 4 Model B – Honeywell SS49E Hall-effect sensor monitor
 *
 * Hardware:
 *   - Honeywell SS49E linear Hall-effect sensor (analog output)
 *   - ADS1115 16-bit ADC on I2C bus 1, address 0x48
 *     AIN0 single-ended, PGA gain = 4.096 V, 128 SPS
 *   - LED + 330 Ω resistor on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hall_monitor hall_monitor.c -lgpiod -lm
 *
 * Run:
 *   ./hall_monitor [-t threshold_gauss]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             "/dev/i2c-1"
#define ADS1115_ADDR        0x48

#define ADS1115_REG_CONV    0x00
#define ADS1115_REG_CONFIG  0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15   OS      = 1  (start single conversion)
 *   Bits14:12 MUX     = 100 (AIN0 single-ended)
 *   Bits11:9  PGA     = 001 (±4.096 V)
 *   Bit  8    MODE    = 0  (single-shot)
 *   Bits7:5   DR      = 100 (128 SPS)
 *   Bit  4    COMP_MODE = 0
 *   Bit  3    COMP_POL  = 0
 *   Bit  2    COMP_LAT  = 0
 *   Bits1:0   COMP_QUE = 11 (disable comparator)
 */
#define ADS1115_CFG_BASE   0x8483

#define LED_GPIO_LINE      17
#define LED_CHIP_NAME      "gpiochip4"   /* BCM GPIO17 on Pi 4 */

#define DEFAULT_THRESHOLD  100.0f
#define SAMPLE_PERIOD_US   100000       /* 100 ms */
#define BLINK_DURATION_US  1000000      /* 1 s   */
#define BLINK_HALF_US      50000        /* 50 ms */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handling ----------------------------- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------- I2C helpers ------------------------------ */
static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* --------------------------- ADS1115 ADC driver --------------------------- */
static int ads1115_init(int fd)
{
    /* Verify device presence by reading the config register back */
    uint16_t cfg;
    if (i2c_read16(fd, ADS1115_REG_CONFIG, &cfg) == -1)
        return -1;
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the raw 16-bit
 * result.  Returns 0 on success and stores the signed value in *raw;
 * returns -1 on any I2C error.
 */
static int ads1115_read_raw(int fd, int16_t *raw)
{
    uint16_t cfg = ADS1115_CFG_BASE;

    if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) == -1)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t conv;
    if (i2c_read16(fd, ADS1115_REG_CONV, &conv) == -1)
        return -1;

    *raw = (int16_t)conv;
    return 0;
}

/*
 * Convert raw ADC count to Gauss.
 *
 * SS49E transfer function (linear approximation):
 *   Vout = B * H + C
 * where B = 1.0 mV/Gauss and C = 0 V.
 *
 * ADS1115 PGA = ±4.096 V  =>  LSB = 125 µV
 *   => 1 count = 0.000125 V
 *   => 1 V = 8000 counts
 *   => 1 Gauss = 8000 counts / 1000 = 8 counts
 *
 * So raw / 8.0 = Gauss.
 */
static float raw_to_gauss(int16_t raw)
{
    return (float)raw / 8.0f;
}

/* ------------------------------- LED blink -------------------------------- */
static void led_blink(struct gpiod_line *line, int duration_us)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(1)");
        return;
    }
    usleep(BLINK_HALF_US);

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return;
    }
    usleep(BLINK_HALF_US);
}

/* --------------------------------- Main ---------------------------------- */
int main(int argc, char *argv[])
{
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
        case 't':
            threshold = strtof(optarg, NULL);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Threshold must be positive.\n");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    printf("Hall-effect sensor monitor started.\n");
    printf("Threshold: %.2f Gauss\n", threshold);
    printf("Press Ctrl+C to exit.\n");

    /* Signal handlers */
    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize ADC */
    if (ads1115_init(i2c_fd) == -1) {
        fprintf(stderr, "ADS1115 initialization failed (sensor absent or bus error).\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request LED line */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(LED_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", LED_CHIP_NAME, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "hall_monitor", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Main sampling loop */
    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(i2c_fd, &raw) == -1) {
            fprintf(stderr, "ADC read error – continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float gauss = raw_to_gauss(raw);
        printf("Gauss: %.2f\n", gauss);

        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED for 1 s.\n");
            led_blink(led_line, BLINK_DURATION_US);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

code:
/*
 * Soil Moisture Monitor with Hysteresis Control and MQTT Publish/Subscribe
 * Board:  Raspberry Pi 4 Model B
 * ADC:    MCP3008 on SPI0 (CE0 / GPIO8), 1 MHz, channel 0
 * Relay:  Active-high pump on GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lmosquitto
 * Run:    sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL      0          /* CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define PUMP_GPIO        17         /* BCM 17 */

#define MOISTURE_THRESHOLD_LOW  30.0f
#define MOISTURE_THRESHOLD_HIGH 35.0f

#define MQTT_BROKER      "localhost"
#define MQTT_PORT        1883
#define MQTT_CLIENT_ID   "soil_monitor"
#define MQTT_TOPIC_PUB   "soil_moisture"
#define MQTT_TOPIC_SUB   "pump_control"

#define SAMPLE_INTERVAL  60         /* seconds */
#define ADC_MAX          1023       /* 10-bit ADC */
#define ADC_VREF         3.3f       /* MCP3008 reference voltage */
#define ADC_RESOLUTION   0.0032258f /* 3.3 / 1024 */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static struct mosquitto *g_mosq = NULL;
static int      g_pump_state = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        syslog(LOG_ERR, "spiOpen failed: %s", pigpio_error(g_spi_handle));
        return -1;
    }
    syslog(LOG_INFO, "SPI initialized on CE0 at %d Hz", SPI_SPEED);
    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out low bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid ADC channel %d", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        syslog(LOG_ERR, "spiXfer failed: %s", pigpio_error(ret));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Moisture conversion                                                 */
/* ------------------------------------------------------------------ */
static float adc_to_moisture(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;

    /*
     * HL-69: dry soil -> high voltage, wet soil -> low voltage.
     * Convert ADC count to voltage, then invert so 0 = wet, 1023 = dry.
     */
    float voltage = (float)adc_value * ADC_RESOLUTION;
    float moisture = 100.0f - (voltage / ADC_VREF) * 100.0f;

    if (moisture < 0.0f)   moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;

    return moisture;
}

/* ------------------------------------------------------------------ */
/* Pump control                                                        */
/* ------------------------------------------------------------------ */
static int pump_set(int state)
{
    if (state != 0 && state != 1) {
        syslog(LOG_ERR, "Invalid pump state %d", state);
        return -1;
    }

    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed", PUMP_GPIO, state);
        return -1;
    }

    g_pump_state = state;
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    return 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks (v2)                                                 */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_SUB, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_subscribe failed: %s", mosquitto_strerror(rc));
        } else {
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC_SUB);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;
    syslog(LOG_WARNING, "MQTT disconnected: %s", mosquitto_strerror(rc));
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen <= 0 || message->payload == NULL) {
        syslog(LOG_WARNING, "Empty MQTT message on topic %s", message->topic);
        return;
    }

    char payload[32];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload)) len = sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    syslog(LOG_INFO, "MQTT message on %s: %s", message->topic, payload);

    if (strcmp(message->topic, MQTT_TOPIC_SUB) == 0) {
        if (strcmp(payload, "pump_on") == 0) {
            pump_set(1);
        } else if (strcmp(payload, "pump_off") == 0) {
            pump_set(0);
        } else {
            syslog(LOG_WARNING, "Unknown command: %s", payload);
        }
    }
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                        */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_loop_start(g_mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_loop_start failed: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    syslog(LOG_INFO, "MQTT initialized: connecting to %s:%d", MQTT_BROKER, MQTT_PORT);
    return 0;
}

static void mqtt_cleanup(void)
{
    if (g_mosq) {
        mosquitto_loop_stop(g_mosq, false);
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    syslog(LOG_INFO, "Cleaning up...");

    /* Ensure pump is off before releasing resources */
    if (g_pump_state) {
        gpioWrite(PUMP_GPIO, 0);
        g_pump_state = 0;
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    mqtt_cleanup();

    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting soil moisture monitor");

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialized");

    /* --- SPI init --- */
    if (spi_init() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Pump GPIO init --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);
    syslog(LOG_INFO, "Pump GPIO %d initialized to OFF", PUMP_GPIO);

    /* --- MQTT init --- */
    if (mqtt_init() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Entering main loop (sampling every %d s)", SAMPLE_INTERVAL);

    /* --- Main loop --- */
    while (g_running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            syslog(LOG_ERR, "ADC read failed; skipping cycle");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture = adc_to_moisture(adc);

        /* Hysteresis control */
        if (moisture < MOISTURE_THRESHOLD_LOW && !g_pump_state) {
            pump_set(1);
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && g_pump_state) {
            pump_set(0);
        }

