/*
 * Soil Moisture Monitor with Hysteresis Control and MQTT Publish/Subscribe
 * Board:  Raspberry Pi 4 Model B
 * ADC:    MCP3008 on SPI0 (CE0 / GPIO8), 1 MHz, channel 0
 * Relay:  Active-high pump on GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o soil_monitor soil_monitor.c -lpigpio -lmosquitto
 * Run:    sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL      0          /* CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define PUMP_GPIO        17         /* BCM 17 */

#define MOISTURE_THRESHOLD_LOW  30.0f
#define MOISTURE_THRESHOLD_HIGH 35.0f

#define MQTT_BROKER      "localhost"
#define MQTT_PORT        1883
#define MQTT_CLIENT_ID   "soil_monitor"
#define MQTT_TOPIC_PUB   "soil_moisture"
#define MQTT_TOPIC_SUB   "pump_control"

#define SAMPLE_INTERVAL  60         /* seconds */
#define ADC_MAX          1023       /* 10-bit ADC */
#define ADC_VREF         3.3f       /* MCP3008 reference voltage */
#define ADC_RESOLUTION   0.0032258f /* 3.3 / 1024 */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static struct mosquitto *g_mosq = NULL;
static int      g_pump_state = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        syslog(LOG_ERR, "spiOpen failed: %s", pigpio_error(g_spi_handle));
        return -1;
    }
    syslog(LOG_INFO, "SPI initialized on CE0 at %d Hz", SPI_SPEED);
    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out low bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid ADC channel %d", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        syslog(LOG_ERR, "spiXfer failed: %s", pigpio_error(ret));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Moisture conversion                                                 */
/* ------------------------------------------------------------------ */
static float adc_to_moisture(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;

    /*
     * HL-69: dry soil -> high voltage, wet soil -> low voltage.
     * Convert ADC count to voltage, then invert so 0 = wet, 1023 = dry.
     */
    float voltage = (float)adc_value * ADC_RESOLUTION;
    float moisture = 100.0f - (voltage / ADC_VREF) * 100.0f;

    if (moisture < 0.0f)   moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;

    return moisture;
}

/* ------------------------------------------------------------------ */
/* Pump control                                                        */
/* ------------------------------------------------------------------ */
static int pump_set(int state)
{
    if (state != 0 && state != 1) {
        syslog(LOG_ERR, "Invalid pump state %d", state);
        return -1;
    }

    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed", PUMP_GPIO, state);
        return -1;
    }

    g_pump_state = state;
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    return 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks (v2)                                                 */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_SUB, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_subscribe failed: %s", mosquitto_strerror(rc));
        } else {
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC_SUB);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;
    syslog(LOG_WARNING, "MQTT disconnected: %s", mosquitto_strerror(rc));
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen <= 0 || message->payload == NULL) {
        syslog(LOG_WARNING, "Empty MQTT message on topic %s", message->topic);
        return;
    }

    char payload[32];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload)) len = sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    syslog(LOG_INFO, "MQTT message on %s: %s", message->topic, payload);

    if (strcmp(message->topic, MQTT_TOPIC_SUB) == 0) {
        if (strcmp(payload, "pump_on") == 0) {
            pump_set(1);
        } else if (strcmp(payload, "pump_off") == 0) {
            pump_set(0);
        } else {
            syslog(LOG_WARNING, "Unknown command: %s", payload);
        }
    }
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                        */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_loop_start(g_mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_loop_start failed: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    syslog(LOG_INFO, "MQTT initialized: connecting to %s:%d", MQTT_BROKER, MQTT_PORT);
    return 0;
}

static void mqtt_cleanup(void)
{
    if (g_mosq) {
        mosquitto_loop_stop(g_mosq, false);
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    syslog(LOG_INFO, "Cleaning up...");

    /* Ensure pump is off before releasing resources */
    if (g_pump_state) {
        gpioWrite(PUMP_GPIO, 0);
        g_pump_state = 0;
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    mqtt_cleanup();

    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting soil moisture monitor");

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialized");

    /* --- SPI init --- */
    if (spi_init() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Pump GPIO init --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);
    syslog(LOG_INFO, "Pump GPIO %d initialized to OFF", PUMP_GPIO);

    /* --- MQTT init --- */
    if (mqtt_init() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Entering main loop (sampling every %d s)", SAMPLE_INTERVAL);

    /* --- Main loop --- */
    while (g_running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            syslog(LOG_ERR, "ADC read failed; skipping cycle");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture = adc_to_moisture(adc);

        /* Hysteresis control */
        if (moisture < MOISTURE_THRESHOLD_LOW && !g_pump_state) {
            pump_set(1);
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && g_pump_state) {
            pump_set(0);
        }

        /* Publish to MQTT */
        char payload[32];
        snprintf(payload, sizeof(payload), "%.2f", moisture);
        int rc = mosquitto_publish(g_mosq, NULL, MQTT_TOPIC_PUB,
                                  (int)strlen(payload), payload, 0, false);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_publish failed: %s", mosquitto_strerror(rc));
        }

        syslog(LOG_INFO, "Moisture: %.2f%%  ADC: %d  Pump: %s",
               moisture, adc, g_pump_state ? "ON" : "OFF");

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

