#define ADC_CHANNEL     0
#define VREF            3.3f
#define SAMPLE_PERIOD_US 500000U   /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer, mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel, padded)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *out_raw)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u (must be 0–7)\n", channel);
        return -1;
    }
    if (out_raw == NULL) {
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *out_raw = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure SPI mode --- */
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Cannot set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Configure bits per word --- */
    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Cannot set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Configure max speed --- */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Cannot set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("MCP3008 on %s, channel %u, VREF=%.2f V, sampling every 500 ms.\n",
           SPI_DEVICE, ADC_CHANNEL, VREF);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t raw = 0;
        if (mcp3008_read(fd, ADC_CHANNEL, &raw) < 0) {
            fprintf(stderr, "ADC read error; continuing.\n");
        } else {
            float voltage = ((float)raw / 1023.0f) * VREF;
            printf("Raw: %4u  Voltage: %.3f V\n", raw, voltage);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

