/*
 * Vibration monitoring system for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MAX9814 electret microphone amplifier -> MCP3008 ADC channel 0
 *   - MCP3008 SPI0 CE0 (/dev/spidev0.0), SPI mode 0, 1 MHz
 *   - Two 3 V vibration motors via transistors on GPIO17 and GPIO27
 *
 * Behavior:
 *   - Samples the ADC every 10 ms
 *   - Modulates the motors based on the ambient noise level
 *   - Logs timestamps of significant vibration events to vibration_log.txt
 *   - Handles SIGINT/SIGTERM for graceful shutdown
 *
 * Build:
 *   gcc -O2 -Wall -o vibration_monitor vibration_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./vibration_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000          /* 1 MHz */
#define SPI_MODE          0                /* SPI mode 0 (CPOL=0, CPHA=0) */
#define SPI_BITS          8                /* 8-bit words */

#define MOTOR1_GPIO       17               /* BCM pin for motor 1 */
#define MOTOR2_GPIO       27               /* BCM pin for motor 2 */
#define PWM_FREQUENCY     100              /* 100 Hz hardware PWM */
#define PWM_RANGE         100              /* Duty cycle range (0-100) */

#define NOISE_THRESHOLD   500              /* ADC value above which vibration is significant */
#define SAMPLE_PERIOD_US  10000            /* 10 ms sampling interval */
#define LOG_FILE          "vibration_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Function prototypes ------------------------- */
static int  initialize_spi(void);
static int  read_adc(int channel);
static void control_motor(int gpio, int duty_cycle);
static void log_vibration_event(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- SPI ------------------------------------- */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_DEVICE, SPI_SPEED_HZ, (1 << 8) | SPI_MODE);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device %s: pigpio error %d\n",
                SPI_DEVICE, g_spi_handle);
        return -1;
    }
    return 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns the 10-bit ADC value (0-1023) on success, or -1 on error.
 *
 * MCP3008 SPI protocol (3 bytes):
 *   tx[0] = 0x01                       Start bit
 *   tx[1] = (0x08 | channel) << 4      Single-ended + channel select
 *   tx[2] = 0x00                       Don't care
 *   rx[1] bits 1:0 + rx[2] bits 7:0    10-bit result
 */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: returned %d (pigpio error %d)\n",
                ret, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* --------------------------- Motor control ------------------------------- */
static void control_motor(int gpio, int duty_cycle)
{
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed on GPIO %d\n", gpio);
    }
}

/* --------------------------- Vibration logging --------------------------- */
static void log_vibration_event(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Vibration detected!\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Stop motors */
    control_motor(MOTOR1_GPIO, 0);
    control_motor(MOTOR2_GPIO, 0);

    /* Close SPI device */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor GPIOs as outputs */
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", MOTOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", MOTOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR1_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", MOTOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR2_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", MOTOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            /* SPI error: skip this iteration, keep running */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Modulate motors based on noise level */
        int duty1 = (adc_value > NOISE_THRESHOLD) ? PWM_RANGE : 0;
        int duty2 = (adc_value > NOISE_THRESHOLD) ? PWM_RANGE : 0;

        control_motor(MOTOR1_GPIO, duty1);
        control_motor(MOTOR2_GPIO, duty2);

        /* Log vibration event if noise exceeds threshold */
        if (adc_value > NOISE_THRESHOLD) {
            log_vibration_event();
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

