#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_PWR_ON  0x01
#define BH1750_CONT_HRES 0x10
#define BH1750_MEAS_MS  180

#define SPI_BUS        "/dev/spidev0.0"
#define SPI_SPEED_HZ   1000000
#define SPI_BITS       8
#define SPI_DELAY_US   0

#define CSV_FILE       "tamper_log.csv"
#define SAMPLE_PERIOD_S 5

#define ERR_NONE       0
#define ERR_I2C_BH1750 1
#define ERR_SPI_ADC    2
#define ERR_SPI_OPEN   3
#define ERR_I2C_OPEN   4
#define ERR_CSV_OPEN   5
#define ERR_WRITE      6
#define ERR_READ       7
#define ERR_CLOSE      8

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_spi_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_open(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", BH1750_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "i2c write 0x%02X: %s\n", byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c read %zu bytes: %s\n", len, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0) return -1;
    usleep(BH1750_MEAS_MS * 1000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int spi_open(void) {
    int fd = open(SPI_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_BUS, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int spi_read_adc(int fd, uint8_t channel, uint16_t *value) {
    if (channel > 7) return -1;
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_MESSAGE): %s\n", strerror(errno));
        return -1;
    }
    *value = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_data(FILE *fp, float sound_db, float light_lux, int err) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, sound_db, light_lux, err) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_csv) { fclose(g_csv); g_csv = NULL; }
    if (g_spi_fd >= 0) { close(g_spi_fd); g_spi_fd = -1; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = i2c_open();
    if (g_i2c_fd < 0) { cleanup(); return 1; }

    g_spi_fd = spi_open();
    if (g_spi_fd < 0) { cleanup(); return 1; }

    g_csv = fopen(CSV_FILE, "a");
    if (!g_csv) {
        fprintf(stderr, "fopen(%s): %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,sound_level_db,light_level_lux,error_code\n");
        fflush(g_csv);
    }

    printf("Logging to %s every %d seconds. Press Ctrl+C to stop.\n", CSV_FILE, SAMPLE_PERIOD_S);

    while (g_running) {
        float sound_db = 0.0f;
        float light_lux = 0.0f;
        int err = ERR_NONE;

        uint16_t adc_val = 0;
        if (spi_read_adc(g_spi_fd, 0, &adc_val) < 0) {
            err = ERR_SPI_ADC;
        } else {
            sound_db = (float)adc_val * 0.01f;
        }

        if (bh1750_read_lux(g_i2c_fd, &light_lux) < 0) {
            err = ERR_I2C_BH1750;
        }

        if (log_data(g_csv, sound_db, light_lux, err) < 0) {
            err = ERR_WRITE;
        }

        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

