/*
 * Raspberry Pi 4 Model B – Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0), SPI channel 0, 1 MHz, VDD 3.3 V, VREF 3.3 V
 *   - Vegetronix VH400 analog output -> MCP3008 CH0
 *   - Relay module (active-high) on BCM GPIO 17
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vh400_monitor vh400_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./vh400_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* MCP3008 on CE0 (SPI channel 0)          */
#define SPI_SPEED        1000000    /* 1 MHz – well within MCP3008 spec         */
#define SPI_FLAGS        0          /* Mode 0, active-low CE, 8-bit words       */

#define PUMP_GPIO        17         /* BCM GPIO 17 – relay control             */

#define MOISTURE_THRESHOLD 30.0f    /* % – pump turns ON below this            */
#define SAMPLE_INTERVAL  60         /* seconds between readings               */
#define MAX_SPI_RETRIES  3          /* retries per single MCP3008 read         */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC full-scale code              */
#define ADC_VREF         3.3f       /* MCP3008 reference voltage               */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0          */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Forward declarations ------------------------ */
static int  read_mcp3008(int channel, int *out_value);
static float adc_to_moisture(int adc_value);
static void control_pump(float moisture_level);
static void log_data(float moisture_level);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio daemon/library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);   /* ensure pump is OFF at startup */

    /* --- Open SPI bus --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers.\n");
    }

    printf("VH400 soil moisture monitor started.\n");
    printf("SPI channel %d @ %d Hz, pump on BCM GPIO %d, threshold %.1f%%.\n",
           SPI_CHANNEL, SPI_SPEED, PUMP_GPIO, MOISTURE_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = -1;

        /* Retry loop for a single MCP3008 read */
        for (int attempt = 1; attempt <= MAX_SPI_RETRIES && g_running; ++attempt) {
            if (read_mcp3008(ADC_CHANNEL, &adc_value) == 0) {
                break;
            }
            fprintf(stderr, "Warning: SPI read attempt %d/%d failed.\n",
                    attempt, MAX_SPI_RETRIES);
            if (attempt < MAX_SPI_RETRIES) {
                gpioDelay(100000);  /* 100 ms backoff before retry */
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: failed to read ADC after %d attempts.\n",
                    MAX_SPI_RETRIES);
            /* Ensure pump is off on sensor failure */
            gpioWrite(PUMP_GPIO, 0);
            gpioDelay(SAMPLE_INTERVAL * 1000000);
            continue;
        }

        float moisture = adc_to_moisture(adc_value);
        control_pump(moisture);
        log_data(moisture);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL && g_running; ++s) {
            gpioDelay(1000000);
        }
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

/* --------------------------- MCP3008 read ------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
