 * Linear interpolation:
 *   moisture = (adc / 1023.0f) * 100.0f
 *   if moisture < 30.0f  -> 0.0f
 *   if moisture > 100.0f -> 100.0f
 */
static float adc_to_moisture(int adc_value)
{
    float voltage = (float)adc_value * ADC_VREF / (float)(ADC_MAX_VALUE + 1);
    float moisture = (voltage / ADC_VREF) * 100.0f;

    if (moisture < 0.0f)   moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;

    return moisture;
