#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define VALVE_GPIO     17
#define PWM_FREQUENCY  100
#define PWM_RANGE      100
#define NUM_SAMPLES    3
#define LOG_INTERVAL   5
#define LOG_FILE       "irrigation.log"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calculate_average(int *samples, int num_samples) {
    long sum = 0;
    int valid_count = 0;

    for (int i = 0; i < num_samples; i++) {
        if (samples[i] >= 0) {
            sum += samples[i];
            valid_count++;
        }
    }

    if (valid_count == 0) {
        return -1;
    }

    return (int)(sum / valid_count);
}

static int set_valve_position(int position) {
    if (position < 0 || position > PWM_RANGE) {
        fprintf(stderr, "Invalid valve position: %d\n", position);
        return -1;
    }

    if (gpioPWM(VALVE_GPIO, position) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", VALVE_GPIO);
        return -1;
    }

    return 0;
}

static int log_data(int *samples, int avg, int position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Raw: %d, %d, %d, Avg: %d, Valve: %d\n",
                timestamp, samples[0], samples[1], samples[2], avg, position) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(VALVE_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    int samples[NUM_SAMPLES];
    int avg;
    int position;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Irrigation control system started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_SAMPLES; i++) {
            samples[i] = read_mcp3008(0);
            if (samples[i] < 0) {
                fprintf(stderr, "Failed to read sample %d, skipping\n", i + 1);
                samples[i] = -1;
            }
        }

        avg = calculate_average(samples, NUM_SAMPLES);
        if (avg < 0) {
            fprintf(stderr, "All samples failed, skipping cycle\n");
            sleep(LOG_INTERVAL);
            continue;
        }

        position = (int)(((float)avg / 1023.0f) * PWM_RANGE);
        if (set_valve_position(position) != 0) {
            fprintf(stderr, "Failed to set valve position\n");
        }

        if (log_data(samples, avg, position) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Raw: %d, %d, %d, Avg: %d, Valve: %d\n",
               samples[0], samples[1], samples[2], avg, position);

        sleep(LOG_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

