    gpioSetMode(TRIG_PIN, PI_INPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
}

/* ----------------------------- Main ------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
