/*
 * Theremin-like instrument using HC-SR04 ultrasonic sensor and LDR.
 *
 * Hardware:
 *   - Raspberry Pi Zero W
 *   - HC-SR04: Trig -> GPIO23 (BCM), Echo -> GPIO24 (BCM)
 *   - MCP3008 ADC: SPI0 (CE0), CS/SHDN -> GPIO8 (BCM), CLK -> GPIO11 (BCM),
 *                 MOSI -> GPIO10 (BCM), MISO -> GPIO9 (BCM)
 *   - LDR: A0 -> MCP3008 CH0, VCC -> 3.3V, GND -> GND
 *   - PWM0: GPIO18 (BCM)
 *
 * Build: gcc -O2 -Wall -o theremin theremin.c -lm
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define CONFIG_FILE "theremin_config.txt"

/* ----------------------------- Pin / SPI definitions ----------------------------- */
#define TRIG_PIN    23
#define ECHO_PIN    24
#define SPI_DEVICE  "/dev/spidev0.0"
#define SPI_SPEED   1000000U   /* 1 MHz */
#define PWM_CHIP    0
#define PWM_CHANNEL 0

/* ----------------------------- Tuning constants ------------------------------- */
#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define MIN_FREQUENCY_HZ  200.0f
#define MAX_FREQUENCY_HZ  1000.0f
#define MIN_VOLUME       0.0f
#define MAX_VOLUME       1.0f
#define ECHO_TIMEOUT_US  30000U   /* 30 ms */
#define LOOP_DELAY_US    50000U   /* 50 ms */

/* ----------------------------- Globals --------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static float g_distance = MIN_DISTANCE_CM;
static float g_volume   = MIN_VOLUME;

/* ----------------------------- Prototypes ------------------------------------ */
static void signal_handler(int sig);
static int  read_config(void);
static int  write_config(void);
static int  init_spi(void);
static int  init_pwm(void);
static int  read_ldr(int spi_fd);
static int  read_ultrasonic(int spi_fd);
static void set_pwm_frequency(uint32_t freq_hz);
static void set_pwm_volume(float volume);
static void cleanup(void);

/* ----------------------------- Signal handler -------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Config file ----------------------------------- */
static int read_config(void)
{
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s; using defaults\n",
                CONFIG_FILE, strerror(errno));
        return -1;
    }

    if (fscanf(fp, "%f %f", &g_distance, &g_volume) != 2) {
        fprintf(stderr, "Warning: malformed config; using defaults\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int write_config(void)
{
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for writing: %s\n",
                CONFIG_FILE, strerror(errno));
        return -1;
    }

    fprintf(fp, "%.2f %.2f\n", g_distance, g_volume);
    fclose(fp);
    return 0;
}

/* ----------------------------- SPI / MCP3008 ---------------------------------- */
static int init_spi(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read a single-ended channel (0-7) from the MCP3008.
 * Returns 0-1023 on success, -1 on error.
 */
static int read_ldr(int spi_fd)
{
    if (spi_fd < 0)
        return -1;

    /*
     * MCP3008 single-ended read (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out low bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | (0x07 & PWM_CHANNEL)) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

/* ----------------------------- HC-SR04 ultrasonic ----------------------------- */
static int read_ultrasonic(int spi_fd)
{
    /* Ensure trigger is low for a clean start */
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        return -1;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIG_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 1) failed\n");
        return -1;
    }
    usleep(10);
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIG, 0) failed\n");
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    float distance_cm = (float)pulse_us * 0.01715f;  /* speed of sound ~343 m/s */

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f-%.0f]\n",
                distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1;
    }

    return (int)distance_cm;
}

/* ----------------------------- PWM via sysfs ---------------------------------- */
static int init_pwm(void)
{
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);

    FILE *fp = fopen(path, "w");
    if (!fp) {
        /* EBUSY means already exported; ignore */
        if (errno != EBUSY) {
            fprintf(stderr, "Error: cannot export PWM channel %d: %s\n",
                    PWM_CHANNEL, strerror(errno));
            return -1;
        }
    } else {
        fprintf(fp, "%d", PWM_CHANNEL);
        fclose(fp);
        usleep(100000);  /* let sysfs settle */
    }

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period",
             PWM_CHIP, PWM_CHANNEL);
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error: cannot set PWM period: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "1000000");  /* 1 ms period -> 1 kHz base */
    fclose(fp);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle",
             PWM_CHIP, PWM_CHANNEL);
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error: cannot set PWM duty cycle: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "0");
    fclose(fp);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable",
             PWM_CHIP, PWM_CHANNEL);
    fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error: cannot enable PWM: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "1");
    fclose(fp);

    return 0;
}

static void set_pwm_frequency(uint32_t freq_hz)
{
    if (freq_hz < 1)
        freq_hz = 1;
    if (freq_hz > 1000000)
        freq_hz = 1000000;

    char path[128];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period",
             PWM_CHIP, PWM_CHANNEL);

    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error: cannot set PWM period: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%u", 1000000U / freq_hz);
    fclose(fp);
}

static void set_pwm_volume(float volume)
{
    if (volume < 0.0f) volume = 0.0f;
    if (volume > 1.0f) volume = 1.0f;

    char path[128];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle",
             PWM_CHIP, PWM_CHANNEL);

    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error: cannot set PWM duty cycle: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%u", (uint32_t)(volume * 1000000.0f));
    fclose(fp);
}

/* ----------------------------- Cleanup --------------------------------------- */
static void cleanup(void)
{
    /* Stop PWM */
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable",
             PWM_CHIP, PWM_CHANNEL);
    FILE *fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "0");
        fclose(fp);
    }

    /* Unexport */
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
    fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "%d", PWM_CHANNEL);
        fclose(fp);
    }

    /* Release GPIO pins */
    gpioWrite(TRIG_PIN, 0);
    gpioSetMode(TRIG_PIN, PI_INPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
}

/* ----------------------------- Main ------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIG) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
