    while (g_running) {
        int ultrasonic_value = read_ultrasonic(spi_fd);
        int ldr_value         = read_ldr(spi_fd);

        if (ultrasonic_value < 0) {
            fprintf(stderr, "Warning: ultrasonic read failed; using last valid distance\n");
        } else {
            g_distance = (float)ultrasonic_value;
        }

        if (ldr_value < 0) {
            fprintf(stderr, "Warning: LDR read failed; using last valid volume\n");
        } else {
            g_volume = (float)ldr_value / 1023.0f;
        }

        /* Map distance to frequency */
