/*
 * MQ-3 Alcohol Sensor Reader via MCP3008 ADC on Raspberry Pi Zero W
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  Pin 24)
 *   MCP3008 CH0  -> MQ-3 analog output
 *
 * Build: gcc -O2 -Wall -Wextra -o alcohol_monitor alcohol_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023
#define LOG_FILE        "alcohol_log.txt"
#define SAMPLE_INTERVAL 1          /* seconds */
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  100
#define SENSOR_ABSENT_THRESHOLD 100 /* consecutive 0 or 1023 reads */

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI initialization                                                   */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* Returns 0–1023 on success, -1 on error.                              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
     *   tx[2] = 0x00                       (clock out low bits)
     * Result: bits 9..0 are in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = sizeof(tx);
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Sensor-absent detection                                             */
/* ------------------------------------------------------------------ */
static int is_sensor_absent(int adc_value)
{
    return (adc_value == 0 || adc_value == ADC_MAX_VALUE);
}

/* ------------------------------------------------------------------ */
/* Alcohol level classification                                         */
/* ------------------------------------------------------------------ */
static const char *classify_alcohol_level(int adc_value)
{
    if (adc_value > 500) {
        return "Alcohol detected! Limit exceeded.";
    } else if (adc_value < 200) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_alcohol_level(int adc_value, const char *classification)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, ADC Value: %d, Alcohol Level: %s\n",
                timestamp, adc_value, classification) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Alcohol monitoring started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    int consecutive_absent = 0;

    while (g_running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && g_running) {
            adc_value = read_mcp3008(ADC_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "ADC read failed, retrying (%d/%d)...\n",
                        retries, MAX_RETRIES);
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed after %d retries. Logging error.\n",
                    MAX_RETRIES);
            if (log_alcohol_level(-1, "ERROR: ADC read failed") < 0) {
                fprintf(stderr, "Failed to log error.\n");
            }
            consecutive_absent = 0;
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (is_sensor_absent(adc_value)) {
            consecutive_absent++;
            if (consecutive_absent >= SENSOR_ABSENT_THRESHOLD) {
                fprintf(stderr,
                        "Sensor absent or disconnected (ADC stuck at %d). "
                        "Check wiring and sensor presence.\n",
                        adc_value);
                if (log_alcohol_level(adc_value, "ERROR: Sensor absent") < 0) {
                    fprintf(stderr, "Failed to log sensor-absent event.\n");
                }
                consecutive_absent = 0;
            }
        } else {
            consecutive_absent = 0;
        }

        const char *classification = classify_alcohol_level(adc_value);
        if (log_alcohol_level(adc_value, classification) < 0) {
            fprintf(stderr, "Failed to log alcohol level.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

