#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

#define ACCELERATION_TIME 2.0
#define DECELERATION_TIME 2.0
#define PAUSE_TIME 5.0
#define PWM_RANGE 255
#define PWM_FREQUENCY 1000

#define MAX_SPEED 255
#define MIN_SPEED 0

#define POT1_ADC_CHANNEL 0
#define POT2_ADC_CHANNEL 1

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, (char *)tx_buffer, (char *)rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

int map_adc_to_speed(int adc_value) {
    if (adc_value < 0) return MIN_SPEED;
    if (adc_value > 1023) return MAX_SPEED;
    return (int)(((float)adc_value / 1023.0) * (MAX_SPEED - MIN_SPEED) + MIN_SPEED);
}

void set_motor_speed(int motor, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    if (motor == 1) {
        gpioPWM(MOTOR1_ENABLE, speed);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_ENABLE, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
        return;
    }
}

void set_motor_direction(int motor, int direction) {
    if (motor == 1) {
        gpioWrite(MOTOR1_DIRECTION, direction);
    } else if (motor == 2) {
        gpioWrite(MOTOR2_DIRECTION, direction);
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
        return;
    }
}

void accelerate_motor(int motor, int target_speed) {
    int current_speed = 0;
    float increment = (float)target_speed / (ACCELERATION_TIME * 100);

    while (current_speed < target_speed && running) {
        current_speed += (int)increment;
        if (current_speed > target_speed) current_speed = target_speed;
        set_motor_speed(motor, current_speed);
        gpioDelay(10000);
    }
}

void decelerate_motor(int motor, int target_speed) {
    int current_speed = target_speed;
    float decrement = (float)target_speed / (DECELERATION_TIME * 100);

    while (current_speed > 0 && running) {
        current_speed -= (int)decrement;
        if (current_speed < 0) current_speed = 0;
        set_motor_speed(motor, current_speed);
        gpioDelay(10000);
    }
}

void cleanup() {
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    gpioWrite(MOTOR1_DIRECTION, 0);
    gpioWrite(MOTOR2_DIRECTION, 0);

    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

