    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);
    gpioSetPWMfrequency(MOTOR1_ENABLE, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENABLE, PWM_FREQUENCY);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (running) {
        int pot1_adc = read_mcp3008(POT1_ADC_CHANNEL);
        int pot2_adc = read_mcp3008(POT2_ADC_CHANNEL);

        if (pot1_adc < 0 || pot2_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC values. Retrying...\n");
            gpioDelay(100000);
            continue;
        }

        int motor1_speed = map_adc_to_speed(pot1_adc);
        int motor2_speed = map_adc_to_speed(pot2_adc);

        printf("Motor 1 Speed: %d, Motor 2 Speed: %d\n", motor1_speed, motor2_speed);

        accelerate_motor(1, motor1_speed);
        accelerate_motor(2, motor2_speed);

        if (!running) break;

        gpioDelay((unsigned int)(ACCELERATION_TIME * 1000000));

        decelerate_motor(1, motor1_speed);
        decelerate_motor(2, motor2_speed);

        if (!running) break;

        gpioDelay((unsigned int)(DECELERATION_TIME * 1000000));

        if (!running) break;

        gpioDelay((unsigned int)(PAUSE_TIME * 1000000));

        if (!running) break;

        set_motor_direction(1, 1);
        set_motor_direction(2, 0);
        gpioDelay(100000);

        accelerate_motor(1, motor1_speed);
        accelerate_motor(2, motor2_speed);

        if (!running) break;

        gpioDelay((unsigned int)(ACCELERATION_TIME * 1000000));

        decelerate_motor(1, motor1_speed);
        decelerate_motor(2, motor2_speed);

        if (!running) break;

        gpioDelay((unsigned int)(DECELERATION_TIME * 1000000));

        if (!running) break;

        gpioDelay((unsigned int)(PAUSE_TIME * 1000000));

        if (!running) break;

        set_motor_direction(1, 0);
        set_motor_direction(2, 1);
        gpioDelay(100000);

        accelerate_motor(1, motor1_speed);
        accelerate_motor(2, motor2_speed);

        if (!running) break;

        gpioDelay((unsigned int)(ACCELERATION_TIME * 1000000));

        decelerate_motor(1, motor1_speed);
        decelerate_motor(2, motor2_speed);

        if (!running) break;

        gpioDelay((unsigned int)(DECELERATION_TIME * 1000000));

        if (!running) break;

        gpioDelay((unsigned int)(PAUSE_TIME * 1000000));
    }

    cleanup();
    printf("Motor control program terminated.\n");
    return 0;
}

