                gpioWrite(LED_GPIO, 1);
                led_on = true;
                last_toggle_tick = now;
            }
        } else {
            gpioWrite(LED_GPIO, 0);
            led_on = false;
        }

        gpioDelay(SAMPLE_DELAY);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

