#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define LOG_FILE "airflow_log.txt"
#define SAMPLE_INTERVAL_MS 100

// Calibration curve parameters (example values)
#define A 0.1
#define B 0.2
#define C 0.3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_adc(int channel);
float voltage_to_airflow(float voltage);
void log_data(float airflow);
void log_error(const char *message);
void timer_callback(void *user_data);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        log_error("Invalid ADC channel");
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message for MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        log_error("SPI transfer failed");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert voltage to airflow using calibration curve
float voltage_to_airflow(float voltage) {
    return A * voltage * voltage + B * voltage + C;
}

// Function to log data to file
void log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to log errors to file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

// Timer callback function
void timer_callback(void *user_data) {
    (void)user_data; // Unused

    int adc_value = read_adc(ADC_CHANNEL);
    if (adc_value < 0) {
        log_error("Failed to read ADC value");
        return;
    }

    float voltage = (float)adc_value / 1023.0 * 3.3; // Assuming 3.3V reference
    float airflow = voltage_to_airflow(voltage);

    log_data(airflow);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // Unused
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer callback
    if (gpioSetTimerFunc(0, SAMPLE_INTERVAL_MS, timer_callback) != 0) {
        fprintf(stderr, "Failed to set timer\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop (keeps program running until signal received)
    while (program_running) {
        gpioDelay(100000); // 100ms delay to reduce CPU usage
    }

    // Cleanup
    printf("\nCleaning up...\n");
    gpioSetTimerFunc(0, SAMPLE_INTERVAL_MS, NULL); // Disable timer
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

