#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "gpiochip0"
#define CS_LINE_OFFSET  8          /* BCM GPIO 8, physical pin 24 */
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_RATE_HZ  1000
#define SPI_SPEED_HZ    1000000    /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        0
#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success and stores the 10-bit value in *out;
 * returns -1 on error.
 */
static int mcp3008_read(int spi_fd, struct gpiod_line *cs_line, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }
    if (out == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    FILE *log_file = NULL;
    int ret_code = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device '%s': %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open GPIO chip and request CS line --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (cs_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Main sampling loop --- */
    struct timespec next_deadline;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next_deadline);
    const struct timespec sample_period = {
        .tv_sec  = 0,
        .tv_nsec = 1000000L / SAMPLE_RATE_HZ
    };

    while (g_running) {
        uint16_t adc_value = 0;
        if (mcp3008_read(spi_fd, cs_line, ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read error; continuing\n");
            next_deadline.tv_nsec += sample_period.tv_nsec;
            if (next_deadline.tv_nsec >= 1000000000L) {
                next_deadline.tv_nsec -= 1000000000L;
                next_deadline.tv_sec++;
            }
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            next_deadline.tv_nsec += sample_period.tv_nsec;
            if (next_deadline.tv_nsec >= 1000000000L) {
                next_deadline.tv_nsec -= 1000000000L;
                next_deadline.tv_sec++;
            }
            continue;
        }

        long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

        if (fprintf(log_file, "%lld|%u\n", timestamp_ns, adc_value) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            break;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
            break;
        }

        /* Sleep until next deadline, but wake early if a signal arrives */
        while (g_running) {
            struct timespec remaining;
            if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
                fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                break;
            }
            long long now_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
            long long deadline_ns = (long long)next_deadline.tv_sec * 1000000000LL + next_deadline.tv_nsec;
            long long sleep_ns = deadline_ns - now_ns;
            if (sleep_ns <= 0) {
                break;
            }
            remaining.tv_sec  = sleep_ns / 1000000000L;
            remaining.tv_nsec = sleep_ns % 1000000000L;
            if (nanosleep(&remaining, NULL) < 0) {
                if (errno == EINTR) {
                    continue;
                }
