/*
 * Raspberry Pi 4 Model B – Honeywell MICROpeL MP-741 Combustible Gas Sensor
 *
 * Reads the sensor voltage via an MCP3008 ADC on SPI0 CE0 (channel 0),
 * converts it to a voltage, and prints the result to the console once per
 * second.  A simulated PPM value is also printed.  All data is appended
 * to gas_log.txt with timestamps for later analysis.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  Pin 24)
 *   MCP3008 CH0  -> MP-741 VOUT
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gas_monitor gas_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./gas_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* MCP3008 on SPI0 CE0 (GPIO8)            */
#define SPI_SPEED        1000000    /* 1 MHz – well within MCP3008 spec       */
#define SPI_FLAGS        0          /* Mode 0, active-low CE, 8-bit words     */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0        */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC                            */
#define VREF             3.3        /* Reference voltage                     */
#define LOG_FILE         "gas_log.txt"
#define SAMPLE_PERIOD_US 1000000    /* 1 second between samples              */
#define RETRY_DELAY_US   100000     /* 100 ms between retries                */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Function prototypes ------------------------- */
static int  initialize_spi(void);
static int  read_adc(int channel);
static float adc_to_voltage(int adc_value);
static void log_data(float voltage, float ppm);
static void signal_handler(int signal);
static void cleanup(void);

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI interface */
    if (initialize_spi() != 0) {
        fprintf(stderr, "Error: SPI initialization failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Gas sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("Logging to: %s\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying in 100 ms...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float ppm     = 0.0f;   /* Simulated PPM – replace with sensor calibration */

        log_data(voltage, ppm);
        printf("Voltage: %.3f V  |  PPM: %.2f\n", voltage, ppm);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

/* ----------------------------- SPI Setup --------------------------------- */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, speed %d, flags 0x%02X).\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        return -1;
    }
    return 0;
}

/* ----------------------------- ADC Read ---------------------------------- */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0–7).\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel select)
     *   Byte 2: 0x00  (clock out remaining bits)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in lower 2 bits
     *   rx[2] = b7..b0
     */
    char tx_buf[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx_buf[3] = { 0 };

    int bytes_transferred = spiXfer(g_spi_handle, tx_buf, rx_buf, 3);
    if (bytes_transferred != 3) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 3).\n", bytes_transferred);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | (uint8_t)rx_buf[2];
    return adc_value;
}

/* ------------------------- ADC to Voltage ------------------------------- */
static float adc_to_voltage(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX_VALUE) * VREF;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(float voltage, float ppm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error converting time");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s, Voltage: %.3f V, PPM: %.2f\n", timestamp, voltage, ppm) < 0) {
        perror("Error writing to log file");
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

/* --------------------------- Signal Handler ------------------------------ */
static void signal_handler(int signal)
{
    (void)signal;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

