/*
 * ADXL335 + MCP3008 Kalman-filtered accelerometer reader for Raspberry Pi 4.
 *
 * Wiring:
 *   ADXL335 X_OUT -> MCP3008 CH0
 *   ADXL335 Y_OUT -> MCP3008 CH1
 *   ADXL335 Z_OUT -> MCP3008 CH2
 *   MCP3008 VDD   -> 3.3 V
 *   MCP3008 VREF  -> 3.3 V
 *   MCP3008 AGND  -> GND
 *   MCP3008 DGND  -> GND
 *   MCP3008 CLK   -> GPIO11 (BCM)
 *   MCP3008 DOUT  -> GPIO9  (BCM)
 *   MCP3008 DIN   -> GPIO10 (BCM)
 *   MCP3008 CS    -> GPIO8  (BCM)
 *
 * Build: gcc -O2 -Wall -o adxl335_kalman adxl335_kalman.c -lm
 */

