#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz — well within MCP3008 3.3 V limit */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define CS_PIN          8          /* BCM GPIO8  */
#define ADC_CHANNELS    3
#define ADC_MAX_VALUE   1023       /* 10-bit ADC */
#define VREF            3.3f
#define SAMPLE_PERIOD_S 0.1f       /* 10 Hz */

/* Kalman filter parameters */
#define Q_NOISE         0.001f
#define R_NOISE         0.01f

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read.
 * Protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* Kalman filter                                                       */
/* ------------------------------------------------------------------ */
typedef struct {
    float x;
    float p;
} kalman_state_t;

static kalman_state_t kalman_init(float q, float r)
{
    kalman_state_t s = {0.0f, q};
    return s;
}

static float kalman_update(kalman_state_t *s, float measurement)
{
    s->p += s->p + q_noise;
    float k = s->p / (s->p + r_noise);
    s->x += k * (measurement - s->x);
    s->p *= (1.0f - k);
    return s->x;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("ADXL335 + MCP3008 Kalman filter running. Press Ctrl+C to exit.\n");

    /* Kalman state for each axis */
    kalman_state_t kx = kalman_init(Q_NOISE, R_NOISE);
    kalman_state_t ky = kalman_init(Q_NOISE, R_NOISE);
    kalman_state_t kz = kalman_init(Q_NOISE, R_NOISE);

    while (g_running) {
        int raw[ADC_CHANNELS];
        bool read_ok = true;

        for (int i = 0; i < ADC_CHANNELS; i++) {
            raw[i] = mcp3008_read(g_spi_fd, i);
            if (raw[i] < 0) {
                read_ok = false;
                break;
            }
        }

        if (!read_ok) {
            fprintf(stderr, "ADC read error — continuing.\n");
            usleep((useconds_t)(SAMPLE_PERIOD_S * 1e6));
            continue;
        }

        /* Convert raw 10-bit to g (ADXL335: 3.3 V supply, 3.3 V/g sensitivity) */
        float gx = ((float)raw[0] / (float)ADC_MAX_VALUE) * VREF / 3.3f;
        float gy = ((float)raw[1] / (float)ADC_MAX_VALUE) * VREF / 3.3f;
        float gz = ((float)raw[2] / (float)ADC_MAX_VALUE) * VREF / 3.3f;

        /* Kalman filter */
        gx = kalman_update(&kx, gx);
        gy = kalman_update(&ky, gy);
        gz = kalman_update(&kz, gz);

        printf("X: %+.3f g  Y: %+.3f g  Z: %+.3f g\n", gx, gy, gz);
        fflush(stdout);

        usleep((useconds_t)(SAMPLE_PERIOD_S * 1e6));
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

