#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000
#define ADC_VREF 3.3f
#define ADC_MAX_COUNT 1
#define ADC_RESOLUTION 1024.0f
#define MAGNETIC_FIELD_MIN -100.0f
#define MAGNETIC_FIELD_MAX 100.0f

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(int pin) {
    char command[64];
    char buffer[16];
    FILE *fp;
    int value;

    snprintf(command, sizeof(command), "gpio read %d", pin);
    fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to execute gpio read on pin %d: %s\n", pin, strerror(errno));
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error: Failed to read output from gpio read on pin %d\n", pin);
        pclose(fp);
        return -1;
    }

    pclose(fp);

    value = atoi(buffer);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid sensor reading on pin %d: %s\n", pin, buffer);
        return -1;
    }

    return value;
}

static float convert_to_magnetic_field(int sensor_value) {
    return (float)sensor_value * (ADC_VREF / ADC_RESOLUTION) * 1000.0f;
}

static void log_data(float sensor1, float sensor2, float sensor3) {
    FILE *fp;

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1, sensor2, sensor3);
    fflush(fp);
    fclose(fp);
}

static void check_magnetic_field_range(float sensor1, float sensor2, float sensor3) {
    if (sensor1 < MAGNETIC_FIELD_MIN || sensor1 > MAGNETIC_FIELD_MAX ||
        sensor2 < MAGNETIC_FIELD_MIN || sensor2 > MAGNETIC_FIELD_MAX ||
        sensor3 < MAGNETIC_FIELD_MIN || sensor3 > MAGNETIC_FIELD_MAX) {
        fprintf(stderr, "Warning: Magnetic field out of range (s1=%.2f, s2=%.2f, s3=%.2f)\n",
                sensor1, sensor2, sensor3);
    }
}

int main(void) {
    int sensor1_value, sensor2_value, sensor3_value;
    float sensor1_magnetic_field, sensor2_magnetic_field, sensor3_magnetic_field;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("Starting magnetic field monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        sensor1_value = read_sensor(SENSOR1_PIN);
        sensor2_value = read_sensor(SENSOR2_PIN);
        sensor3_value = read_sensor(SENSOR3_PIN);

        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error: Sensor read failure, skipping this iteration.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        sensor1_magnetic_field = convert_to_magnetic_field(sensor1_value);
        sensor2_magnetic_field = convert_to_magnetic_field(sensor2_value);
        sensor3_magnetic_field = convert_to_magnetic_field(sensor3_value);

        check_magnetic_field_range(sensor1_magnetic_field, sensor2_magnetic_field, sensor3_magnetic_field);
        log_data(sensor1_magnetic_field, sensor2_magnetic_field, sensor3_magnetic_field);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

