/*
 * Soil Moisture Monitor with Pump Control
 * Board:  Raspberry Pi 4 Model B
 * ADC:    MCP3008 on SPI0 CE0 (GPIO8/GPIO7/GPIO11), 500 kHz, mode 0
 * Sensor: Soil moisture on MCP3008 CH0 (single-ended)
 * Relay:  Pump on GPIO17 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define LOG_FILE        "watering.log"
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    500000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define PUMP_GPIO       17
#define MOISTURE_THRESHOLD 30
#define POLL_INTERVAL_S 60
#define ADC_CHANNEL     0
#define ADC_MAX         1023

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_pump_state = 0;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_event(const char *msg)
{
