#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8U
#define SPI_MODE        SPI_MODE_0
#define NUM_CHANNELS    3
#define SAMPLE_PERIOD_S 1
#define CSV_FILENAME    "sensor_data.csv"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read a single-ended channel (0–7) from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int mcp3008_read(int spi_fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u (must be 0–7)\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (lower 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static int log_data(FILE *fp, const int values[NUM_CHANNELS])
{
    if (fprintf(fp, "%d,%d,%d\n", values[0], values[1], values[2]) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure SPI mode --- */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Configure bits per word --- */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Configure max speed --- */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open CSV file --- */
    fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "ch0,ch1,ch2\n") < 0 || fflush(fp) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("Logging MCP3008 channels 0, 1, 2 to %s every %d s. Press Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_PERIOD_S);

    /* --- Main sampling loop --- */
    while (g_running) {
        int values[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = mcp3008_read(spi_fd, (uint8_t)i);
            if (v < 0) {
                error = 1;
                break;
            }
            values[i] = v;
        }

        if (error) {
            fprintf(stderr, "Error reading MCP3008 channels; aborting.\n");
            break;
        }

        if (log_data(fp, values) != 0) {
            fprintf(stderr, "Error logging data; aborting.\n");
            break;
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
        }
    }
    if (spi_fd >= 0) {
        if (close(spi_fd) != 0) {
            fprintf(stderr, "close(spi_fd) failed: %s\n", strerror(errno));
            ret = EXIT_FAILURE;
        }
    }
    return ret;
}

