/*
 * Raspberry Pi 4 Model B – MQTT LED Controller
 *
 * Subscribes to mqtt.eclipseprojects.io:1883/home/led_control (QoS 0)
 * and drives an LED on GPIO17 (BCM) HIGH when led_state == true,
 * LOW when led_state == false.
 *
 * Build:  gcc -O2 -Wall -Wextra -o led_control led_control.c -lpaho-mqtt3c
 * Run:    ./led_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS   "tcp://mqtt.eclipseprojects.io:1883"
#define MQTT_CLIENT_ID       "rpi_led_control"
#define MQTT_TOPIC           "home/led_control"
#define MQTT_QOS             0

#define GPIO_CHIP            0          /* BCM GPIO chip on Raspberry Pi 4 */
#define GPIO_PIN             17         /* BCM 17 – physical pin 11 */

#define MAX_RECONNECT_DELAY  60         /* seconds */
#define INITIAL_RECONNECT_DELAY 1       /* seconds */

/* ------------------------------------------------------------------ */
/* Globals                                                             */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_timestamped(const char *level, const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");

    fprintf(stderr, "[%s] [%s] %s\n", ts, level, msg);
    fflush(stderr);
}

/* ------------------------------------------------------------------ */
/* GPIO                                                                */
/* ------------------------------------------------------------------ */

static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        log_timestamped("ERROR", "gpioInitialise() failed");
        return -1;
    }
    return 0;
}

static void gpio_set_led(bool on)
{
    gpioWrite(GPIO_PIN, on ? 1 : 0);
}

static void gpio_cleanup(void)
{
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* JSON parsing                                                       */
/* ------------------------------------------------------------------ */

/*
 * Parse a JSON payload of the form:
 *   { "led_state": <bool> }
 * Returns 0 on success and stores the boolean value in *out_state.
 * Returns -1 on any JSON error.
 */
static int parse_led_state(const char *payload, size_t len, bool *out_state)
{
    JSON_Value *root = json_parse_string_with_comments(payload, len);
    if (!root) {
        log_timestamped("ERROR", "JSON parse failed");
        return -1;
    }

    JSON_Object *obj = json_value_get_object(root);
    if (!obj) {
        log_timestamped("ERROR", "JSON root is not an object");
        json_value_free(root);
        return -1;
    }

    JSON_Value *val = json_object_get_value(obj, "led_state");
    if (!val) {
        log_timestamped("ERROR", "Missing 'led_state' key in JSON");
        json_value_free(root);
        return -1;
    }

    if (json_value_get_type(val) != JSONBoolean) {
        log_timestamped("ERROR", "'led_state' is not a boolean");
        json_value_free(root);
        return -1;
    }

    *out_state = json_value_get_boolean(val);
    json_value_free(root);
    return 0;
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */

static void on_connect(void *context, MQTTClient_successData *response)
{
    (void)context;
    (void)response;
    log_timestamped("INFO", "Connected to MQTT broker");
}

static void on_disconnect(void *context, MQTTClient_successData *response)
{
    (void)context;
    (void)response;
    log_timestamped("INFO", "Disconnected from MQTT broker");
}

static void on_subscribe(void *context, MQTTClient_successData *response)
{
    (void)context;
    (void)response;
    log_timestamped("INFO", "Subscribed to topic");
}

static void on_unsubscribe(void *context, MQTTClient_successData *response)
{
    (void)context;
    (void)response;
    log_timestamped("INFO", "Unsubscribed from topic");
}

static void on_message(void *context, char *topicName, int topicLen,
                       MQTTClient_message *message)
{
    (void)context;
    (void)topicLen;

    if (!message || !message->payload || message->payloadlen <= 0) {
        log_timestamped("ERROR", "Null or empty MQTT message received");
        MQTTClient_freeMessage(&message);
        MQTTClient_free(topicName);
        return;
    }

    if (strcmp(topicName, MQTT_TOPIC) != 0) {
        char msg[256];
        snprintf(msg, sizeof(msg),
                 "Received message on unexpected topic: %s", topicName);
        log_timestamped("WARN", msg);
        MQTTClient_freeMessage(&message);
        MQTTClient_free(topicName);
        return;
    }

    char payload[256];
    size_t copy_len = (size_t)message->payloadlen;
    if (copy_len >= sizeof(payload))
        copy_len = sizeof(payload) - 1;
    memcpy(payload, message->payload, copy_len);
    payload[copy_len] = '\0';

    bool led_state;
    if (parse_led_state(payload, copy_len, &led_state) == 0) {
        gpio_set_led(led_state);
        char msg[128];
        snprintf(msg, sizeof(msg), "LED set to %s", led_state ? "ON" : "OFF");
        log_timestamped("INFO", msg);
    } else {
        log_timestamped("ERROR", "Failed to parse LED state from JSON");
    }

    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
}

static void on_delivery_complete(void *context, MQTTClient_deliveryToken dt)
{
    (void)context;
    (void)dt;
}

static void on_connection_lost(void *context, char *cause)
{
    (void)context;
    char msg[256];
    snprintf(msg, sizeof(msg), "Connection lost: %s", cause ? cause : "unknown");
    log_timestamped("ERROR", msg);
}

/* ------------------------------------------------------------------ */
/* MQTT client                                                         */
/* ------------------------------------------------------------------ */

static int mqtt_init(MQTTClient *client)
{
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    int rc = MQTTClient_create(client, MQTT_BROKER_ADDRESS,
                              MQTT_CLIENT_ID,
                              MQTTClient_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        char msg[128];
        snprintf(msg, sizeof(msg), "MQTTClient_create failed: %s",
                 MQTTClient_strerror(rc));
        log_timestamped("ERROR", msg);
        return -1;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    conn_opts.onSuccess = on_connect;
    conn_opts.onFailure = on_disconnect;
    conn_opts.onSubscribe = on_subscribe;
    conn_opts.onUnsubscribe = on_unsubscribe;
    conn_opts.onMessage = on_message;
    conn_opts.onDeliveryComplete = on_delivery_complete;
    conn_opts.onConnectionLost = on_connection_lost;

    rc = MQTTClient_setCallbacks(*client, NULL, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        char msg[128];
        snprintf(msg, sizeof(msg), "MQTTClient_setCallbacks failed: %s",
                 MQTTClient_strerror(rc));
        log_timestamped("ERROR", msg);
        MQTTClient_destroy(client);
        return -1;
    }

    rc = MQTTClient_connect(*client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        char msg[128];
        snprintf(msg, sizeof(msg), "MQTTClient_connect failed: %s",
                 MQTTClient_strerror(rc));
        log_timestamped("ERROR", msg);
        MQTTClient_destroy(client);
        return -1;
    }

    rc = MQTTClient_subscribe(*client, MQTT_TOPIC, MQTT_QOS);
    if (rc != MQTTCLIENT_SUCCESS) {
        char msg[128];
        snprintf(msg, sizeof(msg), "MQTTClient_subscribe failed: %s",
                 MQTTClient_strerror(rc));
        log_timestamped("ERROR", msg);
        MQTTClient_disconnect(*client, 1000);
        MQTTClient_destroy(client);
        return -1;
    }

    return 0;
}

static void mqtt_cleanup(MQTTClient *client)
{
    if (*client) {
        MQTTClient_unsubscribe(*client, MQTT_TOPIC);
        MQTTClient_disconnect(*client, 1000);
        MQTTClient_destroy(client);
        *client = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    MQTTClient client = NULL;
    int reconnect_delay = INITIAL_RECONNECT_DELAY;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_timestamped("ERROR", "sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_timestamped("ERROR", "sigaction(SIGTERM) failed");
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0)
        return EXIT_FAILURE;

    gpio_set_led(false);

    if (mqtt_init(&client) != 0) {
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    log_timestamped("INFO", "LED control started. Listening on " MQTT_TOPIC);

    while (g_running) {
        MQTTClient_yield();
        sleep(1);
    }

    log_timestamped("INFO", "Shutting down...");
    mqtt_cleanup(&client);
    gpio_cleanup();
    log_timestamped("INFO", "Exiting cleanly");
    return EXIT_SUCCESS;
}

