                SOUND_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alarm LED pin as output and ensure it starts OFF */
    ret = gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output (code %d)\n",
                ALARM_LED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioWrite(ALARM_LED_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d to LOW (code %d)\n",
                ALARM_LED_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("Sound sensor: GPIO%d | Alarm LED: GPIO%d\n",
           SOUND_SENSOR_PIN, ALARM_LED_PIN);

    /* Main polling loop */
    while (program_running) {
        int sound_level = gpioRead(SOUND_SENSOR_PIN);

        if (sound_level < 0) {
