                    SOUND_SENSOR_PIN, sound_level);
            break;
        }

        printf("Sound level: %d\n", sound_level);

        /* KY-038 DO pin goes LOW when sound exceeds threshold */
        if (sound_level == 0) {
            printf("Sound detected! Activating alarm.\n");

            ret = gpioWrite(ALARM_LED_PIN, 1);
            if (ret != 0) {
                fprintf(stderr, "Failed to turn on alarm LED (code %d)\n", ret);
                break;
            }

            /* Keep LED on for the alarm duration, checking for shutdown */
            uint32_t elapsed = 0;
            while (program_running && elapsed < ALARM_DURATION_US) {
                gpioDelay(POLL_DELAY_US);
                elapsed += POLL_DELAY_US;
            }

            ret = gpioWrite(ALARM_LED_PIN, 0);
            if (ret != 0) {
                fprintf(stderr, "Failed to turn off alarm LED (code %d)\n", ret);
                break;
            }

            printf("Alarm deactivated.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean up GPIO resources */
    gpioWrite(ALARM_LED_PIN, 0);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

