#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP_NAME   "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE         "/var/log/vibration_shutdown.log"
#define CONSUMER_LABEL   "vibration-monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static int log_message(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int chip_fd = open(GPIO_CHIP_NAME, O_RDWR);
    if (chip_fd < 0) {
        perror("open(" GPIO_CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    struct gpiochip_info chip_info;
    memset(&chip_info, 0, sizeof(chip_info));
    if (ioctl(chip_fd, GPIO_GET_CHIPINFO, &chip_info) < 0) {
        perror("ioctl(GPIO_GET_CHIPINFO)");
        close(chip_fd);
        return EXIT_FAILURE;
    }

    struct gpio_line_request_config line_cfg;
    memset(&line_cfg, 0, sizeof(line_cfg));
    line_cfg.consumer = CONSUMER_LABEL;
    line_cfg.request_type = GPIO_LINE_REQUEST_EVENT_FALLING_EDGE;
    line_cfg.flags = 0;

    struct gpio_line_settings settings;
    memset(&settings, 0, sizeof(settings));
    settings.direction = GPIO_LINE_DIRECTION_INPUT;
    settings.bias = GPIO_LINE_BIAS_PULL_UP;

    struct gpio_line_config line_cfg_array[1];
    line_cfg_array[0].offset = GPIO_LINE_OFFSET;
    line_cfg_array[0].settings = &settings;

    if (ioctl(chip_fd, GPIO_LINE_REQUEST, &line_cfg_array, 1) < 0) {
        perror("ioctl(GPIO_LINE_REQUEST)");
        close(chip_fd);
        return EXIT_FAILURE;
    }

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    while (program_running) {
        struct gpio_line_event event;
        memset(&event, 0, sizeof(event));

        int ret = ioctl(chip_fd, GPIO_LINE_EVENT_WAIT, NULL);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("ioctl(GPIO_LINE_EVENT_WAIT)");
            break;
        }

        if (ret == 0) {
            continue;
        }

        if (ioctl(chip_fd, GPIO_LINE_EVENT_READ, &event) < 0) {
            perror("ioctl(GPIO_LINE_EVENT_READ)");
            continue;
        }

        if (event.event_type != GPIO_LINE_EVENT_FALLING_EDGE) {
            continue;
        }

        printf("Vibration detected on GPIO%d!\n", GPIO_LINE_OFFSET);

        if (log_message("Vibration detected! Shutting down system.") != 0) {
            fprintf(stderr, "Warning: failed to log shutdown event.\n");
        }

        if (system("sudo shutdown -h now") == -1) {
            perror("system(\"sudo shutdown -h now\")");
        }

        break;
    }

    if (ioctl(chip_fd, GPIO_LINE_RELEASE, NULL) < 0) {
        perror("ioctl(GPIO_LINE_RELEASE)");
    }

    if (close(chip_fd) < 0) {
        perror("close(chip_fd)");
    }

    printf("Vibration monitoring stopped.\n");
    return EXIT_SUCCESS;
}

