/*
 * BMP280 altitude logger for Raspberry Pi 4 Model B
 * I2C bus 1: SDA=GPIO2 (pin 3), SCL=GPIO3 (pin 5)
 * Logs altitude (m) with ISO-8601 timestamps to altitude_log.txt
 *
 * Build: gcc -O2 -Wall -o bmp280_log bmp280_log.c -lm
 * Run:   sudo ./bmp280_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- BMP280 register map ---- */
#define BMP280_REG_ID          0xD0
#define BMP280_REG_RESET       0xE0
#define BMP280_REG_CTRL_MEAS   0xF4
#define BMP280_REG_CONFIG      0xF5
#define BMP280_REG_PRESS_MSB   0xF7
#define BMP280_REG_TEMP_MSB    0xFA
#define BMP280_REG_CALIB       0x88

#define BMP280_CHIP_ID         0x58
#define BMP280_RESET_CMD       0xB6

/* ---- Calibration coefficients ---- */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

/* ---- Globals for cleanup ---- */
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read N bytes from a register ---- */
static int read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    if (i2cWriteByte(handle, reg) < 0)
        return -1;
    int n = i2cReadDevice(handle, (char *)buf, len);
    return (n == (int)len) ? 0 : -1;
}

/* ---- Write a byte to a register ---- */
static int write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    return (i2cWriteDevice(handle, buf, 2) == 0) ? 0 : -1;
}

/* ---- Read calibration coefficients ---- */
static int read_calibration(int handle, bmp280_calib_t *cal)
{
    uint8_t buf[24];
    if (read_reg(handle, BMP280_REG_CALIB, buf, sizeof(buf)) != 0)
        return -1;

    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

/* ---- Read raw temperature (x1) ---- */
static int read_raw_temp(int handle, int32_t *raw)
{
    uint8_t buf[3];
    if (read_reg(handle, BMP280_REG_TEMP_MSB, buf, 3) != 0)
        return -1;
    *raw = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    return 0;
}

/* ---- Read raw pressure (x1) ---- */
static int read_raw_press(int handle, int32_t *raw)
{
    uint8_t buf[3];
    if (read_reg(handle, BMP280_REG_PRESS_MSB, buf, 3) != 0)
        return -1;
    *raw = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    return 0;
}

/* ---- Compensate temperature (returns T_fine) ---- */
static int32_t compensate_temp(int32_t raw, const bmp280_calib_t *cal, int32_t *t_fine)
{
    int32_t var1, var2;
    var1 = ((((raw >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((raw >> 4) - ((int32_t)cal->dig_T1)) * ((raw >> 4) - ((int32_t)cal->dig_T1))) >> 12) *
            ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;  /* centi-degrees C */
}

/* ---- Compensate pressure ---- */
static uint32_t compensate_press(int32_t raw, int32_t t_fine, const bmp280_calib_t *cal)
{
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) + ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;
    if (var1 == 0)
        return 0;
    p = 1048576 - raw;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (uint32_t)p;  /* Pa */
}

/* ---- Compute altitude from pressure (Pa) ---- */
static double compute_altitude(uint32_t pressure_pa)
{
    return 44330.0 * (1.0 - pow((double)pressure_pa / 101325.0, 0.1903));
}

/* ---- Log one data record ---- */
static int log_data(FILE *fp, double altitude)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return -1;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f\n", ts, altitude) < 0)
        return -1;
    if (fflush(fp) != 0)
        return -1;
    return 0;
}

/* ---- Cleanup all resources ---- */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at 0x76 (BMP280 default) */
    g_i2c_handle = i2cOpen(1, 0x76, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify chip ID */
    uint8_t chip_id;
    if (read_reg(g_i2c_handle, BMP280_REG_ID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error: cannot read chip ID (sensor absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: chip ID mismatch (got 0x%02X, expected 0x%02X).\n",
                chip_id, BMP280_CHIP_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Soft reset */
    if (write_reg(g_i2c_handle, BMP280_REG_RESET, BMP280_RESET_CMD) != 0) {
        fprintf(stderr, "Error: soft reset failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(2000);  /* 2 ms settle */

    /* Read calibration */
    bmp280_calib_t cal;
    if (read_calibration(g_i2c_handle, &cal) != 0) {
        fprintf(stderr, "Error: failed to read calibration data.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure: osrs_t=x1, osrs_p=x1, mode=normal, t_sb=500ms */
    if (write_reg(g_i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error: failed to write CTRL_MEAS.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    /* Config: filter=off, spi3w_en=0 */
    if (write_reg(g_i2c_handle, BMP280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write CONFIG.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("altitude_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open altitude_log.txt for appending.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("BMP280 logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (g_running) {
        int32_t raw_t, raw_p, t_fine;

        if (read_raw_temp(g_i2c_handle, &raw_t) != 0) {
            fprintf(stderr, "Warning: temperature read failed, retrying...\n");
            gpioDelay(5000000);
            continue;
        }
        if (read_raw_press(g_i2c_handle, &raw_p) != 0) {
            fprintf(stderr, "Warning: pressure read failed, retrying...\n");
            gpioDelay(5000000);
            continue;
        }

        int32_t temp_c = compensate_temp(raw_t, &cal, &t_fine);
        uint32_t press_pa = compensate_press(raw_p, t_fine, &cal);
        double altitude = compute_altitude(press_pa);

        if (log_data(g_log_file, altitude) != 0) {
            fprintf(stderr, "Warning: log write failed.\n");
        }

        printf("T=%.1f C  P=%u Pa  Alt=%.2f m\n", temp_c / 100.0, press_pa, altitude);

        /* Sleep 5 s (interruptible by signals) */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

