        memset(buffer, 0, sizeof(buffer));
    }

    /* Overwrite oldest entry. */
    buffer[0] = temperature;

    if (fseek(fp, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Error seeking log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    size_t w = fwrite(buffer, sizeof(float), BUFFER_SIZE, fp);
    if (w != BUFFER_SIZE) {
        fprintf(stderr, "Error writing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Skipping sample due to SPI read error.\n");
        } else {
            float temperature = adc_to_celsius(adc_value);
            print_temperature(temperature);
            if (log_temperature(temperature, LOG_FILE) < 0) {
                fprintf(stderr, "Warning: failed to log temperature.\n");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (g_spi_fd >= 0) {
        if (close(g_spi_fd) < 0) {
            fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
        }
        g_spi_fd = -1;
    }

    return EXIT_SUCCESS;
}

