    return (float)adc_value * 0.01f;
}

static int set_dac_voltage(float voltage) {
    if (voltage < 0.0f || voltage > 3.3f) {
        fprintf(stderr, "Voltage out of range: %.3f V\n", voltage);
        return -1;
    }

    uint16_t dac_value = (uint16_t)((voltage / 3.3f) * 4095.0f);
    uint8_t tx[3] = { 0x40, (uint8_t)(dac_value >> 4), (uint8_t)((dac_value & 0x0F) << 4) };

    if (write(i2c_fd, tx, 3) != 3) {
        fprintf(stderr, "Error writing to MCP4725: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int log_data(int adc_value, float temperature, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, ADC: %d, Temperature: %.2f C, DAC Voltage: %.3f V\n",
                timestamp, adc_value, temperature, voltage) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
