/*
 * Sequencer for four Songle SRD-05VDC-SL relay modules on a Raspberry Pi 3 B+.
 *
 * BCM GPIO pins 17, 22, 23, 24 are driven to active-high relays.
 * Each relay is activated for one second, then deactivated, and the
 * sequence repeats indefinitely until a signal is received.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_seq relay_seq.c -lgpiod
 * Run:    sudo ./relay_seq
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define ACTIVATION_MS 1000
#define DEBOUNCE_MS   1000

static const unsigned int relay_pins[NUM_RELAYS] = {17, 22, 23, 24};

static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/*
 * Activate a relay for ACTIVATION_MS milliseconds, then deactivate it.
 * Returns 0 on success, -1 on error.
 */
static int activate_relay(struct gpiod_line *line, unsigned int pin)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: failed to activate relay on BCM pin %u\n", pin);
        return -1;
    }
    sleep_ms(ACTIVATION_MS);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: failed to deactivate relay on BCM pin %u\n", pin);
        return -1;
    }
    return 0;
}

/*
 * Deactivate all relays.
 * Returns 0 on success, -1 on error.
 */
static int deactivate_all(struct gpiod_line *lines[NUM_RELAYS])
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_set_value(lines[i], 0) < 0) {
            fprintf(stderr, "Error: failed to deactivate relay on BCM pin %u during cleanup\n",
                    relay_pins[i]);
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    /* Initialize all line pointers to NULL for safe cleanup */
    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    /* ---- Open the default gpiochip (gpiochip0 on RPi 3 B+) ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        goto cleanup;
    }

    /* ---- Acquire each relay line ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: failed to get GPIO line for BCM pin %u\n",
                    relay_pins[i]);
            goto cleanup;
        }
    }

    /* ---- Request each line as output, initial value LOW ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "relay_seq", 0) < 0) {
            fprintf(stderr, "Error: failed to request BCM pin %u as output\n",
                    relay_pins[i]);
            goto cleanup;
        }
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    /* ---- Main loop: activate each relay, then wait ---- */
    while (running) {
        for (int i = 0; i < NUM_RELAYS && running; i++) {
            if (activate_relay(lines[i], relay_pins[i]) < 0) {
                goto cleanup;
            }
            sleep_ms(DEBOUNCE_MS);
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Deactivate all relays and release lines ---- */
    deactivate_all(lines);
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

