#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define MOTOR_IN1       17
#define MOTOR_IN2       18
#define MOTOR_ENA       27

#define PWM_RANGE       255
#define PWM_DUTY        150
#define MOTOR_RUN_SEC   3

#define RAIN_THRESHOLD  5
#define LOG_FILE        "rain_log.txt"
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int motor_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(MOTOR_IN1) failed\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_IN2, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(MOTOR_IN2) failed\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_ENA, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(MOTOR_ENA) failed\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_ENA, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(MOTOR_ENA) failed\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void motor_forward(void)
{
    gpioWrite(MOTOR_IN1, 1);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, PWM_DUTY);
}

static void motor_reverse(void)
{
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 1);
    gpioPWM(MOTOR_ENA, PWM_DUTY);
}

static void motor_stop(void)
{
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);
}

static void log_data(FILE *fp, int rain_level, int window_closed)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        return;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(fp, "%s, Rain Level: %d, Window: %s\n",
                timestamp, rain_level, window_closed ? "Closed" : "Open") < 0) {
        perror("fprintf(log)");
        return;
    }

    if (fflush(fp) != 0) {
        perror("fflush(log)");
    }
}

static void cleanup(void)
{
    motor_stop();

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    if (motor_init() < 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    int window_closed = 0;

    while (g_running) {
        int rain_level = read_mcp3008(g_spi_fd, 0);
        if (rain_level < 0) {
            fprintf(stderr, "Failed to read rain sensor, retrying in %d s\n",
                    POLL_INTERVAL_S);
            sleep(POLL_INTERVAL_S);
            continue;
        }

        if (rain_level > RAIN_THRESHOLD && !window_closed) {
            printf("Rain detected! Closing window.\n");
            motor_forward();
            sleep(MOTOR_RUN_SEC);
            motor_stop();
            window_closed = 1;
        } else if (rain_level <= RAIN_THRESHOLD && window_closed) {
            printf("Rain stopped! Opening window.\n");
            motor_reverse();
            sleep(MOTOR_RUN_SEC);
            motor_stop();
            window_closed = 0;
        }

        log_data(g_log_fp, rain_level, window_closed);
        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

