/*
 * Clap detection with MAX9814 electret microphone amplifier (bit-banged ADC)
 * Board:  Raspberry Pi 4 Model B
 * ADC:    MAX9814 analog output -> bit-banged on BCM GPIO26 (bit-banged ADC)
 * LED:    BCM GPIO16 (active-high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o clap_detect clap_detect.c
 * Run:    sudo ./clap_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADC_PIN          26          /* BCM GPIO26 — bit-banged ADC clock/data */
#define LED_PIN          16          /* BCM GPIO16 — LED indicator */

#define ADC_RESOLUTION   10          /* 10-bit ADC */
#define ADC_MAX_VALUE    ((1 << ADC_RESOLUTION) - 1)

#define SAMPLE_RATE_HZ   1000        /* ADC sampling rate */
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

#define CLAP_THRESHOLD   100         /* ADC threshold for clap detection */
#define DEBOUNCE_MS      50          /* Debounce interval */
#define LED_ON_MS        500         /* LED on duration */

#define ADC_SETTLE_US    1000        /* ADC settle time after power-up */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Bit-banged ADC read (single-ended, 10-bit)                          */
/* ------------------------------------------------------------------ */
static int read_adc(void)
{
    /*
     * MAX9814 SPI-like protocol (3-wire, mode 0):
     *   Clock: 100 kHz (safe for 3.3 V)
     *   MSB first, single-ended, channel 0
     *
     * Bit-banging: drive clock high, sample data on rising edge.
     * We use a software clock to avoid relying on pigpio's hardware
     * clock (which is not guaranteed to be precise enough for 100 kHz).
     */

    /* Start bit */
    gpioWrite(ADC_PIN, 0);
    gpioDelay(1);                       /* > 0.5 us low */
    gpioWrite(ADC_PIN, 1);
    gpioDelay(1);                       /* > 0.5 us high */

    /* Read 10 data bits */
    int value = 0;
    for (int i = 0; i < ADC_RESOLUTION; i++) {
        gpioWrite(ADC_PIN, 0);
        gpioDelay(1);                   /* > 0.5 us low */

        value <<= 1;
        if (gpioRead(ADC_PIN))
            value |= 1;

        gpioWrite(ADC_PIN, 1);
        gpioDelay(1);                   /* > 0.5 us high */
    }

    /* Null bit (clocks out remaining data) */
    gpioWrite(ADC_PIN, 0);
    gpioDelay(1);
    gpioWrite(ADC_PIN, 1);
    gpioDelay(1);

    return value;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void led_on(void)
{
    gpioWrite(LED_PIN, 1);
}

static void led_off(void)
{
    gpioWrite(LED_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &timeinfo);
    printf("[%s] ", buf);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(ADC_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set ADC pin %d as output.\n", ADC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED pin %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure ADC pin starts low (clock idle low) */
    gpioWrite(ADC_PIN, 0);

    /* --- Initialize LED to off --- */
    led_off();

    /* --- Allow ADC to settle after power-up --- */
    gpioDelay(ADC_SETTLE_US);

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    printf("ADC: BCM GPIO%d | LED: BCM GPIO%d | Threshold: %d\n",
           ADC_PIN, LED_PIN, CLAP_THRESHOLD);

    /* --- Main loop --- */
    uint32_t last_detection_tick = 0;
    bool clap_active = false;

    while (g_running) {
        int adc_value = read_adc();

        if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC value out of range (%d). "
                            "Sensor may be absent or bus error.\n", adc_value);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        uint32_t now_tick = gpioTick();

        /* Detect clap: rising edge above threshold */
        if (adc_value > CLAP_THRESHOLD && !clap_active) {
            clap_active = true;
            last_detection_tick = now_tick;
        }

        /* Debounce: require re-entry below threshold */
        if (clap_active && adc_value <= CLAP_THRESHOLD) {
            clap_active = false;

            /* Enforce debounce interval */
            if ((now_tick - last_detection_tick) <
                (uint32_t)(DEBOUNCE_MS * 1000)) {
                continue;
            }

            /* Valid clap detected */
            print_timestamp();
            printf("Clap detected (ADC: %d)\n", adc_value);
            fflush(stdout);

            led_on();
            gpioDelay(LED_ON_MS * 1000);
            led_off();
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    led_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

