#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define PUMP_GPIO_LINE  17
#define PUMP_CHIP       "gpiochip0"

#define MOISTURE_THRESHOLD  50.0f
#define SAMPLE_INTERVAL_SEC  60
#define ADC_MAX_VALUE        1023
#define ADC_CHANNEL          0

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pump_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        return -1.0f;
    }
    return ((float)adc_value / (float)ADC_MAX_VALUE) * 100.0f;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(PUMP_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    pump_line = gpiod_chip_get_line(chip, PUMP_GPIO_LINE);
    if (!pump_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(pump_line, "soil_moisture_pump", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        pump_line = NULL;
        return -1;
    }

    return 0;
}

static void pump_on(void) {
    if (pump_line) {
        gpiod_line_set_value(pump_line, 1);
    }
}

static void pump_off(void) {
    if (pump_line) {
        gpiod_line_set_value(pump_line, 0);
    }
}

static void log_data(float moisture_percentage, int pump_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n",
                timestamp, moisture_percentage, pump_status ? "ON" : "OFF");
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

static void cleanup(void) {
    if (pump_line) {
        pump_off();
        gpiod_line_release(pump_line);
        pump_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return EXIT_FAILURE;
    }

    log_file = fopen("soil_moisture.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            log_data(-1.0f, 0);
        } else {
            float moisture_percentage = adc_to_moisture_percentage(adc_value);
            if (moisture_percentage < 0.0f) {
                fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
                log_data(-1.0f, 0);
            } else {
                printf("Moisture: %.2f%%\n", moisture_percentage);

                if (moisture_percentage < MOISTURE_THRESHOLD) {
                    pump_on();
                    printf("Pump ON\n");
                } else {
                    pump_off();
                    printf("Pump OFF\n");
                }

                log_data(moisture_percentage, gpiod_line_get_value(pump_line));
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

