/*
 * DRV5055‑A1 Hall-effect sensor reader via MCP3008 ADC on Raspberry Pi Zero W
 *
 * Wiring (BCM numbering):
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND  (pin 6)
 *   MCP3008 DGND -> GND  (pin 6)
 *   MCP3008 CLK  -> GPIO11 (pin 23, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO10 (pin 19, SPI0 MISO)
 *   MCP3008 DIN  -> GPIO9  (pin 21, SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (pin 24, SPI0 CE0)
 *   MCP3008 CH0  -> DRV5055‑A1 VOUT
 *   DRV5055‑A1 VCC -> 3.3 V
 *   DRV5055‑A1 GND -> GND
 *
 * Build: gcc -O2 -Wall -Wextra -o drv5055_mcp3008 drv5055_mcp3008.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8U
#define SPI_MODE        SPI_MODE_0

#define MCP3008_CHANNEL 0          /* DRV5055‑A1 VOUT on MCP3008 CH0 */
#define MCP3008_VREF    3300       /* 3.3 V reference */
#define ADC_MAX         1023       /* 10-bit ADC */

#define LOG_FILE        "magnetic_log.txt"
#define SAMPLE_PERIOD_US 500000U  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI transfer failure.
 */
static int mcp3008_read(int spi_fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer, mode 0, MSB-first):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out low bits)
