/*
 * MLX91209 current sensor reader via MCP3008 ADC on Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND  (pin 6)
 *   MCP3008 DGND -> GND  (pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  pin 24)
 *   MCP3008 CH0  -> MLX91209 VOUT
 *   MLX91209 VCC -> 3.3 V
 *   MLX91209 GND -> GND
 *   MLX91209 EN  -> GPIO17 (BCM 17, pin 11)
 *
 * Build:  gcc -O2 -Wall -Wextra -o current_logger current_logger.c
 * Run:    sudo ./current_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz — well within MCP3008 spec */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_LINE       17         /* BCM 17 */

#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX         1023       /* 10-bit ADC */

#define VREF            3.3f       /* MCP3008 reference voltage */
#define SENSOR_VOUT_MAX 5.0f       /* MLX91209 0-5 V output */
#define SENSOR_SENS     0.100f     /* ~100 mV/A typical */

#define LOG_FILE        "current_log.txt"
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI                                                                 */
/* ------------------------------------------------------------------ */
static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "mcp3008_read: invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* GPIO (manual bit-banging via sysfs)                                 */
/* ------------------------------------------------------------------ */
static int gpio_export(int line)
{
    FILE *fp = fopen("/sys/class/gpio/export", "w");
    if (!fp) {
        if (errno != EBUSY) {
            fprintf(stderr, "gpio_export: %s\n", strerror(errno));
        }
        return 0;                 /* already exported or not needed */
    }
    if (fprintf(fp, "%d", line) < 0) {
        fprintf(stderr, "gpio_export: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int gpio_unexport(int line)
{
    FILE *fp = fopen("/sys/class/gpio/unexport", "w");
    if (!fp) {
        if (errno != EBUSY) {
            fprintf(stderr, "gpio_unexport: %s\n", strerror(errno));
        }
        return -1;
    }
    if (fprintf(fp, "%d", line) < 0) {
        fprintf(stderr, "gpio_unexport: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int gpio_set_direction(int line, const char *direction)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", line);

    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "gpio_set_direction(%d): %s\n", line, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s", direction) < 0) {
        fprintf(stderr, "gpio_set_direction(%d): %s\n", line, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int gpio_write(int line, int value)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", line);

    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "gpio_write(%d): %s\n", line, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", value) < 0) {
        fprintf(stderr, "gpio_write(%d): %s\n", line, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }
    return (int)fileno(fp);
}

static int log_write(int fd, float current_A)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    if (dprintf(fd, "%s,%.4f\n", timestamp, current_A) < 0) {
        fprintf(stderr, "dprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fsync(fd) == -1) {
        fprintf(stderr, "fsync: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(int spi_fd, int log_fd)
{
    /* Ensure sensor is powered down before releasing the GPIO line. */
    if (spi_fd >= 0) {
        gpio_write(GPIO_LINE, 0);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }

    gpio_unexport(GPIO_LINE);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int spi_fd = -1;
    int log_fd = -1;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* --- GPIO setup (manual sysfs) --- */
    if (gpio_export(GPIO_LINE) != 0) {
        fprintf(stderr, "Failed to export GPIO line %d\n", GPIO_LINE);
        return EXIT_FAILURE;
    }
    if (gpio_set_direction(GPIO_LINE, "out") != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LINE);
        cleanup(spi_fd, log_fd);
        return EXIT_FAILURE;
    }
    if (gpio_write(GPIO_LINE, 1) != 0) {
        fprintf(stderr, "Failed to power on sensor\n");
        cleanup(spi_fd, log_fd);
        return EXIT_FAILURE;
    }

    /* --- SPI setup --- */
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup(spi_fd, log_fd);
        return EXIT_FAILURE;
    }

    /* --- Log file setup --- */
    log_fd = log_open(LOG_FILE);
    if (log_fd < 0) {
        fprintf(stderr, "Log file initialization failed\n");
        cleanup(spi_fd, log_fd);
        return EXIT_FAILURE;
    }

    printf("MLX91209 current logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
        } else {
            float voltage = ((float)adc_value / (float)ADC_MAX) * VREF;
            float current = (voltage / SENSOR_VOUT_MAX) * SENSOR_S;

            if (log_write(log_fd, current) != 0) {
                fprintf(stderr, "Log write error\n");
            } else {
                printf("ADC: %4d  V: %.3f  I: %.4f A\n",
                       adc_value, voltage, current);
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;
    cleanup(spi_fd, log_fd);
    return ret;
}

