    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", line);

    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "gpio_write(%d): %s\n", line, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", value) < 0) {
        fprintf(stderr, "gpio_write(%d): %s\n", line, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }
    return (int)fileno(fp);
}

static int log_write(int fd, float current_A)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    if (dprintf(fd, "%s,%.4f\n", timestamp, current_A) < 0) {
        fprintf(stderr, "dprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fsync(fd) == -1) {
        fprintf(stderr, "fsync: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(int spi_fd, int log_fd)
{
    /* Ensure sensor is powered down before releasing the GPIO line. */
    if (spi_fd >= 0) {
        gpio_write(GPIO_LINE, 0);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }

    gpio_unexport(GPIO_LINE);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int spi_fd = -1;
    int log_fd = -1;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* --- GPIO setup (manual sysfs) --- */
    if (gpio_export(GPIO_LINE) != 0) {
        fprintf(stderr, "Failed to export GPIO line %d\n", GPIO_LINE);
        return EXIT_FAILURE;
    }
    if (gpio_set_direction(GPIO_LINE, "out") != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LINE);
        cleanup(spi_fd, log_fd);
        return EXIT_FAILURE;
    }
    if (gpio_write(GPIO_LINE, 1) != 0) {
        fprintf(stderr, "Failed to power on sensor\n");
        cleanup(spi_fd, log_fd);
        return EXIT_FAILURE;
    }

    /* --- SPI setup --- */
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup(spi_fd, log_fd);
        return EXIT_FAILURE;
    }

    /* --- Log file setup --- */
    log_fd = log_open(LOG_FILE);
    if (log_fd < 0) {
        fprintf(stderr, "Log file initialization failed\n");
        cleanup(spi_fd, log_fd);
        return EXIT_FAILURE;
    }

    printf("MLX91209 current logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
        } else {
            float voltage = ((float)adc_value / (float)ADC_MAX) * VREF;
            float current = (voltage / SENSOR_VOUT_MAX) * SENSOR_S;

            if (log_write(log_fd, current) != 0) {
                fprintf(stderr, "Log write error\n");
            } else {
                printf("ADC: %4d  V: %.3f  I: %.4f A\n",
                       adc_value, voltage, current);
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;
    cleanup(spi_fd, log_fd);
    return ret;
}

