/*
 * MLX91211 current sensor reader via MCP3008 ADC on Raspberry Pi Zero W.
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 5 V (pin 2)
 *   MCP3008 VREF -> Pi 5 V (pin 2)
 *   MCP3008 AGND -> Pi GND (pin 6)
 *   MCP3008 DGND -> Pi GND (pin 6)
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK, pin 23)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO, pin 21)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI, pin 19)
 *   MCP3008 CS   -> Pi GPIO8  (CE0,  pin 24)
 *   MLX91211 VDD -> Pi 5 V
 *   MLX91211 GND -> Pi GND
 *   MLX91211 OUT -> MCP3008 CH0
 *
 * Build:  gcc -O2 -Wall -Wextra -o current_logger current_logger.c -lgpiod
 * Run:    ./current_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE      "/dev/spidev0.0"   /* SPI0 CE0 on GPIO8 */
#define SPI_SPEED_HZ    1000000            /* 1 MHz */
#define SPI_MODE        0                  /* SPI mode 0 (CPOL=0, CPHA=0) */
#define SPI_BITS        8                  /* 8-bit words */

#define ADC_CHANNEL     0                  /* MCP3008 single-ended channel 0 */
#define ADC_MAX         1023               /* 10-bit ADC */

#define VREF            5.0                /* Pi 5 V rail */
#define ADC_RESOLUTION  1023.0             /* 10-bit ADC */
#define ADC_VREF        5.0                /* ADC reference voltage */

#define LOG_FILE        "current_log.txt"
#define SAMPLE_PERIOD_US 100000            /* 100 ms */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  read_mcp3008(int spi_fd, int channel, int *out_value);
static float adc_to_voltage(int adc_value);
static float voltage_to_current(float voltage);
static int  log_current(float current);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- MCP3008 read -------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer, mode 0, MSB-first).
 *
 * tx[0] = 0x01                       Start bit
 * tx[1] = (0x08 | channel) << 4      SGL/DIFF=1 (single) + D2 D1 D0 channel
 * tx[2] = 0x00                       Padding for clocking out low data bits
 *
 * rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int read_mcp3008(int spi_fd, int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        fprintf(stderr, "Error: NULL output pointer\n");
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* --------------------------- Voltage conversion --------------------------- */
static float adc_to_voltage(int adc_value)
{
    return ((float)adc_value / ADC_RESOLUTION) * ADC_VREF;
}

/* --------------------------- Current conversion --------------------------- */
/*
 * MLX91211 transfer function (simplified linear approximation):
 *   I = (Vout - V_offset) / R_sense
 *
 * The MLX91211 module typically has a 100 mV offset and a 10 mΩ sense
 * resistor.  Adjust the constants below for your specific module.
 */
static float voltage_to_current(float voltage)
{
    const float V_OFFSET = 0.100f;   /* 100 mV offset */
    const float R_SENSE  = 0.010f;   /* 10 mΩ sense resistor */

    return (voltage - V_OFFSET) / R_SENSE;
}

/* ------------------------------- Logging --------------------------------- */
static int log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    int spi_fd = -1;
    int ret = EXIT_FAILURE;

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: cannot open SPI device '%s': %s\n",
                SPI_DEVICE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Configure SPI mode --- */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MODE failed: %s\n",
                strerror(errno));
        goto cleanup_spi;
    }

    /* --- Configure SPI bits per word --- */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_BITS_PER_WORD failed: %s\n",
                strerror(errno));
        goto cleanup_spi;
    }

    /* --- Configure SPI max speed --- */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n",
                strerror(errno));
        goto cleanup_spi;
    }

    printf("MLX91211 current logger started. Logging to '%s'.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = 0;

        if (read_mcp3008(spi_fd, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "Warning: ADC read failed, skipping sample.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);

        if (voltage < 0.0f || voltage > VREF) {
            fprintf(stderr,
                    "Warning: voltage %.3f V out of range [0, %.1f], "
                    "skipping sample.\n",
                    voltage, VREF);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float current = voltage_to_current(voltage);

        if (log_current(current) != 0) {
            fprintf(stderr, "Warning: log write failed, continuing.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup_spi:
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    cleanup();
    return ret;
}

