#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int sum = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int val = gpioRead(pin);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", pin);
            return -1;
        }
        sum += val;
        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }
    return (sum >= DEBOUNCE_READINGS / 2) ? 0 : 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
