/*
 * PIR Motion-Triggered Security Camera for Raspberry Pi 4 Model B
 * Sensor : HC-SR501 on GPIO17 (BCM), pull-down resistor to GND
 * Output : JPEG snapshots saved to /home/pi/security_cam/
 * Build  : gcc -O2 -Wall -Wextra -o pir_cam pir_cam.c -lgpiod
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <syslog.h>
#include <gpiod.h>

#define PIR_PIN             17
#define POLL_INTERVAL_US    50000   /* 50 ms  */
#define DEBOUNCE_DELAY_US   200000  /* 200 ms */
#define CAPTURE_DIR         "/home/pi/security_cam"
#define LOG_FILE            "/var/log/pir_cam.log"
#define MAX_PATH_LEN        512
#define MAX_CMD_LEN         1024

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
}

/* ------------------------------------------------------------------ */
/* Directory helpers                                                   */
/* ------------------------------------------------------------------ */
static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "Path '%s' exists but is not a directory", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0 && errno != EEXIST) {
        syslog(LOG_ERR, "mkdir('%s'): %s", path, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1)
        return -1;
    if (localtime_r(&rawtime, &tm_info) == NULL)
        return -1;
    if (strftime(buf, len, "%Y%m%dT%H%M%S", &tm_info) == 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Capture helper                                                      */
/* ------------------------------------------------------------------ */
static int capture_image(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork(): %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        /* Child: redirect stdout/stderr to /dev/null so libcamera-still
         * doesn't spew its own messages to syslog. */
        freopen("/dev/null", "w", stdout);
        freopen("/dev/null", "w", stderr);

        char *const argv[] = {
            "libcamera-still",
            "--nopreview",
            "-o", (char *)filename,
            "-q", "85",
            "--timeout", "1000",
            NULL
        };

        execvp("libcamera-still", argv);

        /* If execvp returns, it failed. */
        syslog(LOG_ERR, "execvp(libcamera-still): %s", strerror(errno));
        _exit(127);
    }

    /* Parent: wait for child to finish. */
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR)
            continue;
        syslog(LOG_ERR, "waitpid(): %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;

    syslog(LOG_ERR, "libcamera-still failed (status=0x%04x)", status);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = EXIT_FAILURE;

    /* Open syslog. */
    openlog("pir_cam", LOG_PID | LOG_CONS, LOG_USER);

    /* Install signal handlers. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        goto cleanup;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 4). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name: %s", strerror(errno));
        goto cleanup;
    }

    /* Get the PIR line. */
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (pir_line == NULL) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d): %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request the line as input with pull-down. */
    if (gpiod_line_request_input_flags(pir_line, "pir_cam",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) != 0) {
        syslog(LOG_ERR, "gpiod_line_request_input: %s", strerror(errno));
        goto cleanup;
    }

    /* Ensure the capture directory exists. */
    if (ensure_directory(CAPTURE_DIR) != 0)
        goto cleanup;

    log_event(LOG_INFO, "PIR camera monitoring started on GPIO17");

    int last_state = gpiod_line_get_value(pir_line);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpiod_line_get_value: %s", strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int current_state = gpiod_line_get_value(pir_line);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value: %s", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (current_state != last_state) {
            usleep(DEBOUNCE_DELAY_US);

            int confirmed_state = gpiod_line_get_value(pir_line);
            if (confirmed_state < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value (debounce): %s", strerror(errno));
                usleep(POLL_INTERVAL_US);
                continue;
            }

            if (confirmed_state == current_state) {
                if (current_state == 1) {
                    char ts[32];
                    char filename[MAX_PATH_LEN];
                    char log_msg[MAX_PATH_LEN + 64];

                    if (get_timestamp(ts, sizeof(ts)) != 0) {
                        syslog(LOG_ERR, "Failed to generate timestamp");
                        usleep(POLL_INTERVAL_US);
                        continue;
                    }

                    int n = snprintf(filename, sizeof(filename),
                                     "%s/motion_%s.jpg", CAPTURE_DIR, ts);
                    if (n < 0 || (size_t)n >= sizeof(filename)) {
                        syslog(LOG_ERR, "Filename buffer too small");
                        usleep(POLL_INTERVAL_US);
                        continue;
                    }

                    n = snprintf(log_msg, sizeof(log_msg),
                                 "Motion detected on GPIO%d, capturing %s",
                                 PIR_PIN, filename);
                    if (n < 0 || (size_t)n >= sizeof(log_msg)) {
                        syslog(LOG_ERR, "Log message buffer too small");
                        usleep(POLL_INTERVAL_US);
                        continue;
                    }

                    log_event(LOG_INFO, log_msg);

                    if (capture_image(filename) == 0) {
                        n = snprintf(log_msg, sizeof(log_msg),
                                     "Image saved: %s", filename);
                        if (n < 0 || (size_t)n >= sizeof(log_msg))
                            log_msg[0] = '\0';
                        log_event(LOG_INFO, log_msg);
                    } else {
                        n = snprintf(log_msg, sizeof(log_msg),
                                     "Failed to capture image: %s", filename);
                        if (n < 0 || (size_t)n >= sizeof(log_msg))
                            log_msg[0] = '\0';
                        log_event(LOG_ERR, log_msg);
                    }
                }
                last_state = current_state;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    log_event(LOG_INFO, "PIR camera monitoring stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (pir_line != NULL)
        gpiod_line_release(pir_line);
    if (chip != NULL)
        gpiod_chip_close(chip);
    closelog();
    return ret;
}

