#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 1
#define MAX_FILENAME_LEN 64
#define TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device %s does not support video capture\n", device);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device %s does not support streaming I/O\n", device);
        close(fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_GREY) {
        fprintf(stderr, "Device does not support grayscale format\n");
        close(fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on device\n");
        close(fd);
        return -1;
    }

    return fd;
}

static int init_mmap(int fd, struct v4l2_buffer *buffers) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "mmap failed: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int start_streaming(int fd, struct v4l2_buffer *buffers) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(int fd, struct v4l2_buffer *buffers, unsigned char *image_data) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            return -1;
        }
        fprintf(stderr, "select() failed: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select() timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        if (errno == EAGAIN) {
            return -1;
        }
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    if (buf.index >= NUM_BUFFERS) {
        fprintf(stderr, "Invalid buffer index: %u\n", buf.index);
        return -1;
    }

    memcpy(image_data, buffers[buf.index].start, buf.bytesused);

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int save_pgm(const char *filename, const unsigned char *image_data, int width, int height) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", width, height);
    size_t written = fwrite(image_data, 1, (size_t)(width * height), fp);
    if (written != (size_t)(width * height)) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(int fd, struct v4l2_buffer *buffers) {
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            fprintf(stderr, "Warning: VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        }
        close(fd);
    }
    if (buffers != NULL) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i].start != NULL && buffers[i].start != MAP_FAILED) {
                if (munmap(buffers[i].start, buffers[i].length) < 0) {
                    fprintf(stderr, "Warning: munmap failed: %s\n", strerror(errno));
                }
            }
        }
        free(buffers);
    }
}

int main(int argc, char *argv[]) {
    const char *device = (argc > 1) ? argv[1] : DEFAULT_DEVICE;
    int fd = -1;
    struct v4l2_buffer *buffers = NULL;
    unsigned char *image_data = NULL;
    int image_number = 1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = init_camera(device);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    buffers = calloc(NUM_BUFFERS, sizeof(struct v4l2_buffer));
    if (buffers == NULL) {
        fprintf(stderr, "Failed to allocate buffer array: %s\n", strerror(errno));
        cleanup(fd, NULL);
        return EXIT_FAILURE;
    }

    if (init_mmap(fd, buffers) < 0) {
        cleanup(fd, buffers);
        return EXIT_FAILURE;
    }

    if (start_streaming(fd, buffers) < 0) {
        cleanup(fd, buffers);
        return EXIT_FAILURE;
    }

    image_data = malloc((size_t)(IMAGE_WIDTH * IMAGE_HEIGHT));
    if (image_data == NULL) {
        fprintf(stderr, "Failed to allocate image buffer: %s\n", strerror(errno));
        cleanup(fd, buffers);
        return EXIT_FAILURE;
    }

    printf("Capturing images from %s. Press Ctrl+C to stop.\n", device);

    while (!stop_flag) {
        char filename[MAX_FILENAME_LEN];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", image_number);

        if (capture_image(fd, buffers, image_data) == 0) {
            if (save_pgm(filename, image_data, IMAGE_WIDTH, IMAGE_HEIGHT) == 0) {
                printf("Saved %s\n", filename);
                image_number++;
            } else {
                fprintf(stderr, "Failed to save image %s\n", filename);
            }
        } else {
            if (stop_flag) {
                break;
            }
            fprintf(stderr, "Failed to capture image\n");
        }
    }

    printf("\nExiting...\n");
    ret = EXIT_SUCCESS;

    free(image_data);
    cleanup(fd, buffers);
    return ret;
}

