/*
 * MJPEG Video Capture with Timestamp Logging
 * Board:  Raspberry Pi 4 Model B
 * Camera: USB webcam (e.g., Logitech C920)
 * Device: /dev/video0
 * Output: frame_log.txt  (one timestamp per frame)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mjpeg_capture mjpeg_capture.c
 *
 * NOTE: This program uses the Linux kernel MJPEG capture API directly
 * (V4L2) — no external video-capture libraries are required.
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME     "/dev/video0"
#define LOG_FILE        "frame_log.txt"
#define NUM_BUFFERS     4
#define CAPTURE_TIMEOUT_SEC  5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* V4L2 helpers                                                        */
/* ------------------------------------------------------------------ */

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int fd)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    /* --- Query capabilities --- */
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }

    /* --- Set format: MJPEG, 640x480 --- */
    memset(&fmt, 0, sizeof(fmt));
    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = 640;
    fmt.fmt.pix.height      = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field       = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device does not support MJPEG format\n");
        return -1;
    }

    if (fmt.fmt.pix.width != 640 || fmt.fmt.pix.height != 480) {
        fprintf(stderr, "Warning: camera resized to %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
    }

    /* --- Request buffers --- */
    memset(&req, 0, sizeof(req));
    req.count  = NUM_BUFFERS;
    req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    /* --- Query and map each buffer --- */
    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index  = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
            return -1;
        }

        void *ptr = mmap(NULL, buf.length, PROT_READ | PROT_WRITE,
                         MAP_SHARED, fd, buf.m.offset);
        if (ptr == MAP_FAILED) {
            fprintf(stderr, "mmap failed: %s\n", strerror(errno));
            return -1;
        }
        buf.m.userptr = (unsigned long)ptr;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            munmap(ptr, buf.length);
            return -1;
        }
    }

    /* --- Start streaming --- */
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, void **frame_ptr, size_t *frame_size)
{
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec  = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) {
        if (errno == EINTR)
            return -1;
        fprintf(stderr, "select failed: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout: no frame within %d s\n",
                CAPTURE_TIMEOUT_SEC);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    *frame_ptr  = (void *)(unsigned long)buf.m.userptr;
    *frame_size = buf.bytesused;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup_camera(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Warning: VIDIOC_STREAMOFF failed: %s\n",
                strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int fd = -1;
    FILE *log_fp = NULL;
    int ret_code = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open device --- */
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize camera --- */
    if (init_camera(fd) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        goto cleanup;
    }

    /* --- Open log file --- */
    log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Capturing MJPEG frames from %s. Press Ctrl+C to stop.\n",
           DEVICE_NAME);

    /* --- Main capture loop --- */
    while (g_running) {
        void *frame_ptr = NULL;
        size_t frame_size = 0;

        if (capture_frame(fd, &frame_ptr, &frame_size) < 0) {
            if (!g_running)
                break;
            continue;
        }

        struct timeval tv;
        if (gettimeofday(&tv, NULL) < 0) {
            fprintf(stderr, "gettimeofday failed: %s\n", strerror(errno));
            continue;
        }

        if (fprintf(log_fp, "%ld.%06ld\n",
                    (long)tv.tv_sec, (long)tv.tv_usec) < 0) {
            fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
            continue;
        }
        if (fflush(log_fp) != 0) {
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        }
    }

    printf("\nShutting down cleanly.\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (log_fp)
        fclose(log_fp);
    if (fd >= 0)
        cleanup_camera(fd);
    if (fd >= 0)
        close(fd);

    return ret_code;
}

