#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 192
#define NUM_BUFFERS 4
#define OUTPUT_FILE "image.jpg"

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

static int init_device(int fd) {
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP failed");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_WIDTH;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT failed");
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device did not accept MJPEG format\n");
        return -1;
    }

    if (fmt.fmt.pix.width != IMAGE_WIDTH || fmt.fmt.pix.height != IMAGE_WIDTH) {
        fprintf(stderr, "Device did not accept requested resolution\n");
        return -1;
    }

    return 0;
}

static int init_mmap(int fd, struct v4l2_requestbuffers *req, struct v4l2_buffer **buffers) {
    memset(req, 0, sizeof(*req));
    req->count = NUM_BUFFERS;
    req->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req->memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, req) < 0) {
        perror("VIDIOC_REQBUFS failed");
        return -1;
    }

    if (req->count < 2) {
        fprintf(stderr, "Insufficient buffer memory on device\n");
        return -1;
    }

    *buffers = calloc(req->count, sizeof(struct v4l2_buffer));
    if (!*buffers) {
        perror("Out of memory");
        return -1;
    }

    for (unsigned int i = 0; i < req->count; ++i) {
        memset(&((*buffers)[i]), 0, sizeof((*buffers)[i]));
        (*buffers)[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        (*buffers)[i].memory = V4L2_MEMORY_MMAP;
        (*buffers)[i].index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &((*buffers)[i])) < 0) {
            perror("VIDIOC_QUERYBUF failed");
            return -1;
        }

        (*buffers)[i].length = (*buffers)[i].bytesused;
        (*buffers)[i].m.offset = (*buffers)[i].m.offset;

        void *map = mmap(NULL, (*buffers)[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, (*buffers)[i].m.offset);
        if (map == MAP_FAILED) {
            perror("mmap failed");
            return -1;
        }
        (*buffers)[i].m.userptr = (unsigned long)map;
    }

    return 0;
}

static int start_streaming(int fd, struct v4l2_buffer **buffers, unsigned int n_buffers) {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (xioctl(fd, VIDIOC_QBUF, &((*buffers)[i])) < 0) {
            perror("VIDIOC_QBUF failed");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON failed");
        return -1;
    }

    return 0;
}

static int capture_image(int fd, struct v4l2_buffer **buffers, unsigned int n_buffers, FILE *fp) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF failed");
        return -1;
    }

    if (buf.index >= n_buffers) {
        fprintf(stderr, "Buffer index out of range\n");
        return -1;
    }

    if (buf.bytesused == 0) {
        fprintf(stderr, "No data in buffer\n");
        return -1;
    }

    size_t written = fwrite((void *)buf.m.userptr, 1, buf.bytesused, fp);
    if (written != buf.bytesused) {
        perror("fwrite failed");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush failed");
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF failed");
        return -1;
    }

    return 0;
}

static void stop_streaming(int fd, struct v4l2_buffer **buffers, unsigned int n_buffers) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF failed");
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        if ((*buffers)[i].m.userptr != 0) {
            if (munmap((void *)(*buffers)[i].m.userptr, (*buffers)[i].length) < 0) {
                perror("munmap failed");
            }
            (*buffers)[i].m.userptr = 0;
        }
    }
}

static void cleanup(int fd, struct v4l2_buffer **buffers, unsigned int n_buffers, FILE *fp) {
    if (fp) {
        fclose(fp);
    }
    if (buffers && *buffers) {
        stop_streaming(fd, buffers, n_buffers);
        free(*buffers);
        *buffers = NULL;
    }
    if (fd >= 0) {
        close(fd);
    }
}

int main(void) {
    int fd = -1;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer *buffers = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM) failed");
        return EXIT_FAILURE;
    }

    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    if (init_device(fd) < 0) {
        cleanup(fd, &buffers, NUM_BUFFERS, NULL);
        return EXIT_FAILURE;
    }

    if (init_mmap(fd, &req, &buffers) < 0) {
        cleanup(fd, &buffers, NUM_BUFFERS, NULL);
        return EXIT_FAILURE;
    }

    if (start_streaming(fd, &buffers, NUM_BUFFERS) < 0) {
        cleanup(fd, &buffers, NUM_BUFFERS, NULL);
        return EXIT_FAILURE;
    }

    fp = fopen(OUTPUT_FILE, "wb");
    if (!fp) {
        perror("Error opening output file");
        cleanup(fd, &buffers, NUM_BUFFERS, NULL);
        return EXIT_FAILURE;
    }

    printf("Capturing image...\n");

    if (capture_image(fd, &buffers, NUM_BUFFERS, fp) < 0) {
        if (stop_flag) {
            fprintf(stderr, "Interrupted by signal\n");
        } else {
            fprintf(stderr, "Failed to capture image\n");
        }
        cleanup(fd, &buffers, NUM_BUFFERS, fp);
        return EXIT_FAILURE;
    }

    printf("Image captured successfully.\n");
    ret = EXIT_SUCCESS;

    cleanup(fd, &buffers, NUM_BUFFERS, fp);
    return ret;
}

