/*
 * pan_tilt_mount.c — Raspberry Pi pan-tilt camera mount controller
 *
 * Board:  Raspberry Pi (any model with 40-pin header)
 * Library: pigpio (hardware PWM via gpioHardwarePWM)
 *
 * Wiring (BCM numbering):
 *   GPIO4  -> pan servo signal  (active-low PWM)
 *   GPIO5  -> tilt servo signal (active-low PWM)
 *   GPIO6  -> tilt-up button    (internal pull-up, active-low)
 *   GPIO7  -> tilt-down button  (internal pull-up, active-low)
 *   GPIO8  -> pan-left button   (internal pull-up, active-low)
 *   GPIO9  -> pan-right button  (internal pull-up, active-low)
 *
 * Build:  gcc -O2 -Wall -Wextra -o pan_tilt_mount pan_tilt_mount.c -lpigpio -lrt
 * Run:    sudo ./pan_tilt_mount
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM) ---- */
#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define TILT_UP_PIN      6
#define TILT_DOWN_PIN    7
#define PAN_LEFT_PIN     8
#define PAN_RIGHT_PIN    9

/* ---- Servo parameters ---- */
#define SERVO_MIN_PULSE_US  1000   /* 1 ms  -> 0 degrees   */
#define SERVO_MAX_PULSE_US  2000   /* 2 ms  -> 180 degrees */
#define SERVO_MID_PULSE_US  1500   /* 1.5 ms -> mid-point  */
#define SERVO_RANGE_US     1000   /* 1 ms to 2 ms range    */
#define SERVO_STEP_US      50     /* 50 us per step       */
#define SERVO_MIN_DEG      25
#define SERVO_MAX_DEG      125

/* ---- PWM parameters ---- */
#define PWM_FREQ_HZ        50     /* 50 Hz -> 20 ms period */
#define PWM_RANGE          1000   /* duty 0..1000         */
#define POLL_DELAY_US      50000  /* 50 ms poll interval  */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Map a pulse width (microseconds) to a duty value (0..PWM_RANGE).     */
/* Returns -1 on invalid input.                                        */
/* ------------------------------------------------------------------ */
static int pulse_to_duty(int pulse_us)
{
    if (pulse_us < SERVO_MIN_PULSE_US || pulse_us > SERVO_MAX_PULSE_US)
        return -1;
    return (int)(((long)(pulse_us - SERVO_MIN_PULSE_US) * PWM_RANGE) /
                 (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));
}

/* ------------------------------------------------------------------ */
/* Map a duty value (0..PWM_RANGE) to a pulse width (microseconds).     */
/* ------------------------------------------------------------------ */
static int duty_to_pulse(int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    return SERVO_MIN_PULSE_US +
           (int)(((long)duty * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US)) /
                 PWM_RANGE);
}

/* ------------------------------------------------------------------ */
/* Set servo pulse width (microseconds) via pigpio hardware PWM.       */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int set_servo_pulse(int pin, int pulse_us)
{
    int duty = pulse_to_duty(pulse_us);
    if (duty < 0) {
        fprintf(stderr, "Invalid pulse %d us on pin %d\n", pulse_us, pin);
        return -1;
    }
    if (gpioHardwarePWM(pin, PWM_FREQ_HZ, (unsigned)duty) != 0) {
        fprintf(stderr, "gpioHardwarePWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a button: returns 1 if pressed (active-low), 0 otherwise.      */
/* ------------------------------------------------------------------ */
static int read_button(int pin)
{
    return (gpioRead(pin) == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Clamp a value to the servo range.                                   */
/* ------------------------------------------------------------------ */
static int clamp_servo(int value)
{
    if (value < SERVO_MIN_DEG) return SERVO_MIN_DEG;
    if (value > SERVO_MAX_DEG) return SERVO_MAX_DEG;
    return value;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure servo pins.                         */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Configure servo pins as outputs (hardware PWM) */
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", PAN_SERVO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", TILT_SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Configure button pins as inputs with internal pull-ups */
    if (gpioSetMode(TILT_UP_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TILT_UP_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(TILT_DOWN_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TILT_DOWN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(PAN_LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", PAN_LEFT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(PAN_RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", PAN_RIGHT_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", TILT_UP_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", TILT_DOWN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", PAN_LEFT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", PAN_RIGHT_PIN);
        gpioTerminate();
        return -1;
    }

    /* Start with servos at mid-position */
    if (set_servo_pulse(PAN_SERVO_PIN, SERVO_MID_PULSE_US) != 0) {
        gpioTerminate();
        return -1;
    }
    if (set_servo_pulse(TILT_SERVO_PIN, SERVO_MID_PULSE_US) != 0) {
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup: stop PWM and terminate pigpio.                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM on both servo pins */
    gpioHardwarePWM(PAN_SERVO_PIN, PWM_FREQ_HZ, 0);
    gpioHardwarePWM(TILT_SERVO_PIN, PWM_FREQ_HZ, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int pan_position  = SERVO_MID_PULSE_US;
    int tilt_position = SERVO_MID_PULSE_US;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Pan-tilt mount controller running. Press Ctrl+C to exit.\n");
    printf("Pan: left=GPIO%d, right=GPIO%d | Tilt: up=GPIO%d, down=GPIO%d\n",
           PAN_LEFT_PIN, PAN_RIGHT_PIN, TILT_UP_PIN, TILT_DOWN_PIN);

    while (g_running) {
        int new_pan  = pan_position;
        int new_tilt = tilt_position;

        if (read_button(TILT_UP_PIN)) {
            new_tilt += SERVO_STEP_US;
        }
        if (read_button(TILT_DOWN_PIN)) {
            new_tilt -= SERVO_STEP_US;
        }
        if (read_button(PAN_LEFT_PIN)) {
            new_pan -= SERVO_STEP_US;
        }
        if (read_button(PAN_RIGHT_PIN)) {
            new_pan += SERVO_STEP_US;
        }

        /* Clamp to valid servo range */
        new_pan  = clamp_servo(new_pan);
        new_tilt = clamp_servo(new_tilt);

        /* Only update if changed */
        if (new_pan != pan_position) {
            if (set_servo_pulse(PAN_SERVO_PIN, new_pan) != 0) {
                fprintf(stderr, "Failed to set pan servo\n");
            } else {
                pan_position = new_pan;
            }
        }
        if (new_tilt != tilt_position) {
            if (set_servo_pulse(TILT_SERVO_PIN, new_tilt) != 0) {
                fprintf(stderr, "Failed to set tilt servo\n");
            } else {
                tilt_position = new_tilt;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

