        fprintf(stderr, "Failed to set GPIO%d as input\n", TILT_DOWN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(PAN_LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", PAN_LEFT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(PAN_RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", PAN_RIGHT_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", TILT_UP_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", TILT_DOWN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", PAN_LEFT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", PAN_RIGHT_PIN);
        gpioTerminate();
        return -1;
    }

    /* Start with servos at mid-position */
    if (set_servo_pulse(PAN_SERVO_PIN, SERVO_MID_PULSE_US) != 0) {
        gpioTerminate();
        return -1;
    }
    if (set_servo_pulse(TILT_SERVO_PIN, SERVO_MID_PULSE_US) != 0) {
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup: stop PWM and terminate pigpio.                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM on both servo pins */
    gpioHardwarePWM(PAN_SERVO_PIN, PWM_FREQ_HZ, 0);
    gpioHardwarePWM(TILT_SERVO_PIN, PWM_FREQ_HZ, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int pan_position  = SERVO_MID_PULSE_US;
    int tilt_position = SERVO_MID_PULSE_US;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Pan-tilt mount controller running. Press Ctrl+C to exit.\n");
    printf("Pan: left=GPIO%d, right=GPIO%d | Tilt: up=GPIO%d, down=GPIO%d\n",
           PAN_LEFT_PIN, PAN_RIGHT_PIN, TILT_UP_PIN, TILT_DOWN_PIN);

    while (g_running) {
        int new_pan  = pan_position;
        int new_tilt = tilt_position;

        if (read_button(TILT_UP_PIN)) {
            new_tilt += SERVO_STEP_US;
        }
        if (read_button(TILT_DOWN_PIN)) {
            new_tilt -= SERVO_STEP_US;
        }
        if (read_button(PAN_LEFT_PIN)) {
            new_pan -= SERVO_STEP_US;
        }
        if (read_button(PAN_RIGHT_PIN)) {
            new_pan += SERVO_STEP_US;
        }

        /* Clamp to valid servo range */
        new_pan  = clamp_servo(new_pan);
        new_tilt = clamp_servo(new_tilt);

        /* Only update if changed */
        if (new_pan != pan_position) {
            if (set_servo_pulse(PAN_SERVO_PIN, new_pan) != 0) {
                fprintf(stderr, "Failed to set pan servo\n");
            } else {
                pan_position = new_pan;
            }
        }
        if (new_tilt != tilt_position) {
            if (set_servo_pulse(TILT_SERVO_PIN, new_tilt) != 0) {
                fprintf(stderr, "Failed to set tilt servo\n");
            } else {
                tilt_position = new_tilt;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

