#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4
#define JPEG_QUALITY 75
#define SELECT_TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device did not accept YUYV format\n");
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    return 0;
}

static int init_buffers(int fd, struct buffer **buffers, unsigned int *n_buffers) {
    struct v4l2_buffer buf;
    unsigned int i;

    *buffers = calloc(NUM_BUFFERS, sizeof(struct buffer));
    if (!*buffers) {
        fprintf(stderr, "Out of memory allocating buffer array\n");
        return -1;
    }

    for (i = 0; i < NUM_BUFFERS; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
            free(*buffers);
            *buffers = NULL;
            return -1;
        }

        (*buffers)[i].length = buf.length;
        (*buffers)[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if ((*buffers)[i].start == MAP_FAILED) {
            fprintf(stderr, "mmap failed: %s\n", strerror(errno));
            free(*buffers);
            *buffers = NULL;
            return -1;
        }
    }

    *n_buffers = NUM_BUFFERS;
    return 0;
}

static int start_streaming(int fd, struct buffer *buffers, unsigned int n_buffers) {
    unsigned int i;
    struct v4l2_buffer buf;

    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, struct buffer *buffers, unsigned int n_buffers, unsigned char **image_data) {
    fd_set fds;
    struct timeval tv;
    int r;
    struct v4l2_buffer buf;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = SELECT_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            return -1;
        }
        fprintf(stderr, "select() failed: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select() timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    if (buf.index >= n_buffers) {
        fprintf(stderr, "Buffer index out of range\n");
        return -1;
    }

    *image_data = (unsigned char *)buffers[buf.index].start;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void uninit_buffers(int fd, struct buffer *buffers, unsigned int n_buffers) {
    unsigned int i;
    for (i = 0; i < n_buffers; ++i) {
        if (buffers && buffers[i].start && buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
        }
    }
    if (buffers) {
        free(buffers);
    }
    close(fd);
}

static void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    int i, j;
    for (i = 0; i < height; ++i) {
        for (j = 0; j < width; ++j) {
            int y = yuyv[i * width * 2 + j * 2];
            int u = yuyv[i * width * 2 + j * 2 + 1];
            int v = yuyv[i * width * 2 + j * 2 + 3];

            int r = y + (1402 * (v - 128)) / 1000;
            int g = y - (344 * (u - 128) + 714 * (v - 128)) / 1000;
            int b = y + (1772 * (u - 128)) / 1000;

            if (r < 0) r = 0; if (r > 255) r = 255;
            if (g < 0) g = 0; if (g > 255) g = 255;
            if (b < 0) b = 0; if (b > 255) b = 255;

            rgb[(i * width + j) * 3] = (unsigned char)r;
            rgb[(i * width + j) * 3 + 1] = (unsigned char)g;
            rgb[(i * width + j) * 3 + 2] = (unsigned char)b;
        }
    }
}

static void blur_image(unsigned char *image, int width, int height) {
    unsigned char *temp = malloc(width * height * 3);
    if (!temp) {
        fprintf(stderr, "Memory allocation failed for blur\n");
        return;
    }
    memcpy(temp, image, width * height * 3);

    int i, j;
    for (i = 1; i < height - 1; ++i) {
        for (j = 1; j < width - 1; ++j) {
            int r = 0, g = 0, b = 0;
            int count = 0;
            for (int k = -1; k <= 1; ++k) {
                for (int l = -1; l <= 1; ++l) {
                    r += temp[(i + k) * width * 3 + (j + l) * 3];
                    g += temp[(i + k) * width * 3 + (j + l) * 3 + 1];
                    b += temp[(i + k) * width * 3 + (j + l) * 3 + 2];
                    count++;
                }
            }
            image[i * width * 3 + j * 3] = (unsigned char)(r / count);
            image[i * width * 3 + j * 3 + 1] = (unsigned char)(g / count);
            image[i * width * 3 + j * 3 + 2] = (unsigned char)(b / count);
        }
    }
    free(temp);
}

static int encode_jpeg(const unsigned char *image, int width, int height, const char *filename, int quality) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    outfile = fopen(filename, "wb");
    if (!outfile) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = (JSAMPROW)(image + cinfo.next_scanline * width * 3);
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

int main(void) {
    int fd = -1;
    struct buffer *buffers = NULL;
    unsigned int n_buffers = 0;
    unsigned char *image_data = NULL;
    unsigned char *rgb_image = NULL;
    char filename[64];
    time_t rawtime;
    struct tm *timeinfo;

    signal(SIGINT, signal_handler);

    if (init_camera(&fd) != 0) {
        return EXIT_FAILURE;
    }

    if (init_buffers(fd, &buffers, &n_buffers) != 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (start_streaming(fd, buffers, n_buffers) != 0) {
        uninit_buffers(fd, buffers, n_buffers);
        return EXIT_FAILURE;
    }

    printf("Capturing image...\n");

    if (capture_frame(fd, buffers, n_buffers, &image_data) != 0) {
        if (stop_flag) {
            fprintf(stderr, "Interrupted by signal\n");
        }
        stop_streaming(fd);
        uninit_buffers(fd, buffers, n_buffers);
        return EXIT_FAILURE;
    }

    if (stop_streaming(fd) != 0) {
        uninit_buffers(fd, buffers, n_buffers);
        return EXIT_FAILURE;
    }

    rgb_image = malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (!rgb_image) {
        fprintf(stderr, "Memory allocation failed for RGB image\n");
        uninit_buffers(fd, buffers, n_buffers);
        return EXIT_FAILURE;
    }

    yuyv_to_rgb24(image_data, rgb_image, IMAGE_WIDTH, IMAGE_HEIGHT);
    blur_image(rgb_image, IMAGE_WIDTH, IMAGE_HEIGHT);

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    if (encode_jpeg(rgb_image, IMAGE_WIDTH, IMAGE_HEIGHT, filename, JPEG_QUALITY) != 0) {
        free(rgb_image);
        uninit_buffers(fd, buffers, n_buffers);
        return EXIT_FAILURE;
    }

    printf("Image saved as %s\n", filename);

    free(rgb_image);
    uninit_buffers(fd, buffers, n_buffers);

    return EXIT_SUCCESS;
}

