/*
 * csi_camera_info.c — Query a V4L2 CSI camera for supported resolutions,
 * frame rates and autofocus capability.
 *
 * Build:  gcc -O2 -Wall -Wextra -o csi_camera_info csi_camera_info.c
 * Run:    ./csi_camera_info   (on a Raspberry Pi with a CSI camera)
 */

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static void print_fourcc(unsigned int fourcc)
{
    char buf[5] = {
        (char)(fourcc & 0xFF),
        (char)((fourcc >> 8) & 0xFF),
        (char)((fourcc >> 16) & 0xFF),
        (char)((fourcc >> 24) & 0xFF),
        '\0'
    };
    printf("%s", buf);
}

static void print_frmsize(const struct v4l2_frmsizeenum *frmsize)
{
    if (frmsize->type == V4L2_FRMSIZE_TYPE_DISCRETE) {
        printf("%ux%u", frmsize->discrete.width, frmsize->discrete.height);
    } else if (frmsize->type == V4L2_FRMSIZE_TYPE_STEPWISE) {
        printf("%ux%u-%ux%u step %ux%u",
               frmsize->stepwise.min_width, frmsize->stepwise.min_height,
               frmsize->stepwise.max_width, frmsize->stepwise.max_height,
               frmsize->stepwise.step_width, frmsize->stepwise.step_height);
    } else {
        printf("unknown frame size type");
    }
}

static void print_frmival(const struct v4l2_frmivalenum *frmival)
{
    if (frmival->type == V4L2_FRMIVAL_TYPE_DISCRETE) {
        printf("%u/%u", frmival->discrete.numerator, frmival->discrete.denominator);
    } else if (frmival->type == V4L2_FRMIVAL_TYPE_STEPWISE) {
        printf("%u/%u-%u/%u step %u/%u",
               frmival->stepwise.min.numerator, frmival->stepwise.min.denominator,
               frmival->stepwise.max.numerator, frmival->stepwise.max.denominator,
               frmival->stepwise.step.numerator, frmival->stepwise.step.denominator);
    } else {
        printf("unknown frame interval type");
    }
}

int main(void)
{
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_queryctrl ctrl;
    unsigned int i, j;
    int ret;

    /* --- Open the device node --- */
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Query capabilities --- */
    memset(&cap, 0, sizeof(cap));
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    printf("Camera: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Bus:    %s\n", cap.bus_info);
    printf("Version: %u.%u.%u\n",
           (cap.version >> 16) & 0xFF,
           (cap.version >> 8) & 0xFF,
           cap.version & 0xFF);

    /* --- Enumerate supported frame sizes --- */
    printf("\nSupported frame sizes:\n");
    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_JPEG;

    for (;;) {
        ret = ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize);
        if (ret < 0) {
            if (errno == EINVAL) {
                break;  /* no more frame sizes */
            }
            fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("  ");
        print_frmsize(&frmsize);
        printf("  ");

        /* Enumerate supported frame intervals for this size */
        memset(&frmival, 0, sizeof(frmival));
        frmival.index = 0;
        frmival.pixel_format = V4L2_PIX_FMT_JPEG;
        frmival.width = frmsize.discrete.width;
        frmival.height = frmsize.discrete.height;

        for (;;) {
            ret = ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival);
            if (ret < 0) {
                if (errno == EINVAL) {
                    break;  /* no more frame intervals for this size */
                }
                fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n", strerror(errno));
                goto cleanup;
            }

            if (frmival.index > 0) {
                printf(", ");
            }
            print_frmival(&frmival);
            frmival.index++;
        }

        printf("\n");
        frmsize.index++;
    }

    /* --- Query autofocus control --- */
    memset(&ctrl, 0, sizeof(ctrl));
    ctrl.id = V4L2_CID_FOCUS_AUTO;

    ret = ioctl(fd, VIDIOC_QUERYCTRL, &ctrl);
    if (ret < 0) {
        if (errno == EINVAL) {
            printf("\nAutofocus: not supported\n");
        } else {
            fprintf(stderr, "VIDIOC_QUERYCTRL (focus) failed: %s\n", strerror(errno));
            goto cleanup;
        }
    } else {
        printf("\nAutofocus: supported\n");
    }

    printf("\n");
    return EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return EXIT_FAILURE;
}

