#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define MIN_PULSE_WIDTH  1000
#define MAX_PULSE_WIDTH  2000
#define CENTER_PULSE_WIDTH 1500
#define PULSE_INCREMENT  10
#define LOOP_DELAY_US    50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse_width(int pin, int pulse_width)
{
    if (pulse_width < MIN_PULSE_WIDTH)
        pulse_width = MIN_PULSE_WIDTH;
    if (pulse_width > MAX_PULSE_WIDTH)
        pulse_width = MAX_PULSE_WIDTH;

    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pulse %d us)\n",
                pin, pulse_width);
        return -1;
    }
    return 0;
}

static int read_button(int pin)
{
    return (gpioRead(pin) == 0);
}

int main(void)
{
    int pan_pulse  = CENTER_PULSE_WIDTH;
    int tilt_pulse = CENTER_PULSE_WIDTH;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for servo pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_pulse_width(PAN_SERVO_PIN, pan_pulse) < 0 ||
        set_servo_pulse_width(TILT_SERVO_PIN, tilt_pulse) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Camera Mount Control\n");
    printf("=============================\n");
    printf("Pan Servo : GPIO%d | Pulse: %d us\n", PAN_SERVO_PIN, pan_pulse);
    printf("Tilt Servo: GPIO%d | Pulse: %d us\n", TILT_SERVO_PIN, tilt_pulse);
    printf("Buttons   : UP=GPIO%d, DOWN=GPIO%d, LEFT=GPIO%d, RIGHT=GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        if (read_button(UP_BUTTON_PIN)) {
            tilt_pulse -= PULSE_INCREMENT;
            if (tilt_pulse < MIN_PULSE_WIDTH)
                tilt_pulse = MIN_PULSE_WIDTH;
            set_servo_pulse_width(TILT_SERVO_PIN, tilt_pulse);
            printf("Tilt UP   -> %d us\n", tilt_pulse);
            fflush(stdout);
        }
        if (read_button(DOWN_BUTTON_PIN)) {
            tilt_pulse += PULSE_INCREMENT;
            if (tilt_pulse > MAX_PULSE_WIDTH)
                tilt_pulse = MAX_PULSE_WIDTH;
            set_servo_pulse_width(TILT_SERVO_PIN, tilt_pulse);
            printf("Tilt DOWN -> %d us\n", tilt_pulse);
            fflush(stdout);
        }
        if (read_button(LEFT_BUTTON_PIN)) {
            pan_pulse -= PULSE_INCREMENT;
            if (pan_pulse < MIN_PULSE_WIDTH)
                pan_pulse = MIN_PULSE_WIDTH;
            set_servo_pulse_width(PAN_SERVO_PIN, pan_pulse);
            printf("Pan LEFT  -> %d us\n", pan_pulse);
            fflush(stdout);
        }
        if (read_button(RIGHT_BUTTON_PIN)) {
            pan_pulse += PULSE_INCREMENT;
            if (pan_pulse > MAX_PULSE_WIDTH)
                pan_pulse = MAX_PULSE_WIDTH;
            set_servo_pulse_width(PAN_SERVO_PIN, pan_pulse);
            printf("Pan RIGHT -> %d us\n", pan_pulse);
            fflush(stdout);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

code:
/*
 * PIR Motion Detection and Image Capture with HTTP Upload
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: HC-SR501 PIR on GPIO17 (BCM, physical pin 11)
 * Camera: Raspberry Pi Camera Module v2 (CSI interface)
 *
 * Build:  gcc -O2 -Wall -Wextra -o motion_capture motion_capture.c \
 *          -lpigpio -ljpeg -lcurl
 * Run:    ./motion_capture <http_ip> <http_port>
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_PIN             17
#define DEBOUNCE_TIME_SEC   2
#define POLL_INTERVAL_US    100000   /* 100 ms */
#define CAPTURE_QUALITY     85
#define CAPTURE_DIR         "motion_captures"
#define MAX_FILENAME_LEN    256
#define MAX_JSON_LEN        512
#define MAX_HTTP_RESPONSE   65536

/* ------------------------------------------------------------------ */
/* Globals for signal-safe cleanup                                    */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Directory helpers                                                   */
/* ------------------------------------------------------------------ */

static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        fprintf(stderr, "Error: cannot create directory '%s': %s\n",
                path, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */

static int get_timestamp(char *buf, size_t len)
{
    struct timeval tv;
    struct tm tm_info;

    if (gettimeofday(&tv, NULL) != 0) {
        fprintf(stderr, "Error: gettimeofday failed: %s\n", strerror(errno));
        return -1;
    }

    if (localtime_r(&tv.tv_sec, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    size_t cur = strlen(buf);
    int remaining = (int)(len - cur);
    if (remaining <= 0)
        return -1;

    int written = snprintf(buf + cur, remaining, ".%06ld", (long)tv.tv_usec);
    if (written < 0 || written >= remaining) {
        fprintf(stderr, "Error: timestamp formatting truncated\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* JPEG capture                                                        */
/* ------------------------------------------------------------------ */

static int capture_jpeg(const char *filename, int quality)
{
    char command[512];
    int ret = snprintf(command, sizeof(command),
                       "raspistill -o %s -q %d --nopreview",
                       filename, quality);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: capture command too long\n");
        return -1;
    }

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed to launch raspistill: %s\n",
                strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: raspistill exited with status %d\n",
                WIFEXITED(status) ? WEXITSTATUS(status) : -1);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* JSON payload                                                        */
/* ------------------------------------------------------------------ */

static int format_json(char *buf, size_t len,
                       const char *filename, const char *timestamp,
                       int motion_detected, int gpio_pin)
{
    int ret = snprintf(buf, len,
                       "{\"filename\":\"%s\",\"timestamp\":\"%s\","
                       "\"motion_detected\":%s,\"gpio_pin\":%d}",
                       filename, timestamp,
                       motion_detected ? "true" : "false", gpio_pin);
    if (ret < 0 || (size_t)ret >= len) {
        fprintf(stderr, "Error: JSON formatting truncated\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* HTTP upload                                                         */
/* ------------------------------------------------------------------ */

typedef struct {
    char *data;
    size_t size;
} MemoryStruct;

static size_t write_cb(void *contents, size_t size, size_t nmemb, void *userp)
{
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;

    char *ptr = realloc(mem->data, mem->size + realsize + 1);
    if (!ptr) {
        fprintf(stderr, "Error: realloc failed in write_cb\n");
        return 0;
    }
    mem->data = ptr;
    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = '\0';
    return realsize;
}

static int upload_data(const char *url, const char *json_data,
                       const char *filename, const char *mime_type)
{
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }

    struct curl_httppost *formpost = NULL;
    struct curl_httppost *lastptr = NULL;

    curl_formadd(&formpost, &lastptr,
                 CURLFORM_COPYNAME, "json_data",
                 CURLFORM_COPYCONTENTS, json_data,
                 CURLFORM_END);

    if (filename && mime_type) {
        curl_formadd(&formpost, &lastptr,
                     CURLFORM_COPYNAME, "image",
                     CURLFORM_FILE, filename,
                     CURLFORM_CONTENTTYPE, mime_type,
                     CURLFORM_END);
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_HTTPPOST, formpost);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_cb);

    MemoryStruct response = {NULL, 0};
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&response);

    CURLcode res = curl_easy_perform(curl);
    long http_code = 0;

    if (res == CURLE_OK) {
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    } else {
        fprintf(stderr, "Error: curl_easy_perform() failed: %s\n",
                curl_easy_strerror(res));
    }

    curl_easy_cleanup(curl);
    curl_formfree(formpost);

    if (res != CURLE_OK || http_code < 200 || http_code >= 300) {
        fprintf(stderr, "Error: HTTP request failed (code %ld)\n", http_code);
        if (response.data) {
            fprintf(stderr, "Server response: %s\n", response.data);
            free(response.data);
        }
        return -1;
    }

    if (response.data)
        free(response.data);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    gpioTerminate();
    curl_global_cleanup();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <http_ip> <http_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *http_ip = argv[1];
    const char *http_port = argv[2];
    char http_url[256];

    int ret = snprintf(http_url, sizeof(http_url),
                       "http://%s:%s/upload", http_ip, http_port);
    if (ret < 0 || (size_t)ret >= sizeof(http_url)) {
        fprintf(stderr, "Error: HTTP URL too long\n");
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure PIR pin ---- */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", PIR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n",
                PIR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize libcurl (global) ---- */
    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        fprintf(stderr, "Error: curl_global_init() failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Ensure capture directory exists ---- */
    if (ensure_directory(CAPTURE_DIR) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");
    printf("PIR on GPIO%d, HTTP upload to %s\n", PIR_PIN, http_url);

    int last_state = 0;
    time_t last_motion_time = 0;

    while (g_running) {
        int current_state = gpioRead(PIR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", PIR_PIN);
            break;
        }

        if (current_state == 1 && last_state == 0) {
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) >= DEBOUNCE_TIME_SEC) {
                printf("Motion detected!\n");

                char filename[MAX_FILENAME_LEN];
                char timestamp[32];
                char json_data[MAX_JSON_LEN];

                if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
                    fprintf(stderr, "Error: failed to generate timestamp\n");
                    break;
                }

                int ret = snprintf(filename, sizeof(filename),
                                   "%s/motion_%s.jpg", CAPTURE_DIR, timestamp);
                if (ret < 0 || (size_t)ret >= sizeof(filename)) {
                    fprintf(stderr, "Error: filename too long\n");
                    break;
                }

                if (capture_jpeg(filename, CAPTURE_QUALITY) != 0) {
                    fprintf(stderr, "Error: failed to capture JPEG\n");
                    break;
                }

                if (format_json(json_data, sizeof(json_data),
                                filename, timestamp, 1, PIR_PIN) != 0) {
                    fprintf(stderr, "Error: failed to format JSON\n");
                    break;
                }

                if (upload_data(http_url, json_data, filename,
                                "image/jpeg") != 0) {
                    fprintf(stderr, "Error: failed to upload data\n");
                    break;
                }

                printf("Motion captured and uploaded.\n");
                last_motion_time = now;
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

