        return EXIT_FAILURE;
    }

    const char *http_ip = argv[1];
    const char *http_port = argv[2];
    char http_url[256];

    int ret = snprintf(http_url, sizeof(http_url),
                       "http://%s:%s/upload", http_ip, http_port);
    if (ret < 0 || (size_t)ret >= sizeof(http_url)) {
        fprintf(stderr, "Error: HTTP URL too long\n");
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure PIR pin ---- */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", PIR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n",
                PIR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize libcurl (global) ---- */
    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        fprintf(stderr, "Error: curl_global_init() failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Ensure capture directory exists ---- */
    if (ensure_directory(CAPTURE_DIR) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");
    printf("PIR on GPIO%d, HTTP upload to %s\n", PIR_PIN, http_url);

    int last_state = 0;
    time_t last_motion_time = 0;

    while (g_running) {
        int current_state = gpioRead(PIR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", PIR_PIN);
            break;
        }

        if (current_state == 1 && last_state == 0) {
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) >= DEBOUNCE_TIME_SEC) {
                printf("Motion detected!\n");

                char filename[MAX_FILENAME_LEN];
                char timestamp[32];
                char json_data[MAX_JSON_LEN];

                if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
                    fprintf(stderr, "Error: failed to generate timestamp\n");
                    break;
                }

                int ret = snprintf(filename, sizeof(filename),
                                   "%s/motion_%s.jpg", CAPTURE_DIR, timestamp);
                if (ret < 0 || (size_t)ret >= sizeof(filename)) {
                    fprintf(stderr, "Error: filename too long\n");
                    break;
                }

                if (capture_jpeg(filename, CAPTURE_QUALITY) != 0) {
                    fprintf(stderr, "Error: failed to capture JPEG\n");
                    break;
                }

                if (format_json(json_data, sizeof(json_data),
                                filename, timestamp, 1, PIR_PIN) != 0) {
                    fprintf(stderr, "Error: failed to format JSON\n");
                    break;
                }

                if (upload_data(http_url, json_data, filename,
                                "image/jpeg") != 0) {
                    fprintf(stderr, "Error: failed to upload data\n");
                    break;
                }

                printf("Motion captured and uploaded.\n");
                last_motion_time = now;
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

