#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <gpiod.h>

#define PIR_GPIO_LINE	17
#define DEBOUNCE_MS	50
#define POLL_TIMEOUT_MS	1000
#define IMAGES_DIR	"/home/pi/images"
#define LOG_FILE	"/home/pi/motion_capture.log"
#define MAX_FILENAME	256
#define MAX_COMMAND	512

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
	(void)sig;
	program_running = 0;
}

static void log_message(const char *message)
{
	FILE *fp = fopen(LOG_FILE, "a");
	if (!fp) {
		perror("fopen(log)");
		return;
	}

	time_t t = time(NULL);
	struct tm tm;
	if (localtime_r(&t, &tm)) {
		fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
			tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
			tm.tm_hour, tm.tm_min, tm.tm_sec, message);
	} else {
		fprintf(fp, "[unknown time] %s\n", message);
	}
	fclose(fp);
}

static int ensure_images_dir(void)
{
	struct stat st;
	if (stat(IMAGES_DIR, &st) == 0) {
		if (S_ISDIR(st.st_mode))
			return 0;
		log_message("Images directory exists but is not a directory");
		return -1;
	}
	if (errno != ENOENT) {
		log_message("stat(images) failed");
		return -1;
	}
	if (mkdir(IMAGES_DIR, 0755) != 0) {
		log_message("mkdir(images) failed");
		return -1;
	}
	return 0;
}

static int capture_image(const char *filename)
{
	char command[MAX_COMMAND];
	int n = snprintf(command, sizeof(command),
		"raspistill -o '%s' --width 640 --height 480 "
		"--quality 85 --timeout 2000 --nopreview", filename);
	if (n < 0 || (size_t)n >= sizeof(command)) {
		log_message("Command buffer too small");
		return -1;
	}

	int status = system(command);
	if (status == -1) {
		log_message("system() failed to launch raspistill");
		return -1;
	}
	if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
		char msg[256];
		snprintf(msg, sizeof(msg),
			"raspistill failed (status=%d)", status);
		log_message(msg);
		return -1;
	}
	return 0;
}

static int generate_filename(char *filename, size_t size)
{
	time_t t = time(NULL);
	struct tm tm;
	if (!localtime_r(&t, &tm)) {
		log_message("localtime_r failed");
		return -1;
	}

	struct timespec ts;
	if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
		log_message("clock_gettime failed");
		return -1;
	}

	int ms = (int)(ts.tv_nsec / 1000000);

	if (snprintf(filename, size, "%s/%04d%02d%02d_%02d%02d%02d_%03d.jpg",
			IMAGES_DIR,
			tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
			tm.tm_hour, tm.tm_min, tm.tm_sec, ms) >= (int)size) {
		log_message("Filename buffer too small");
		return -1;
	}
	return 0;
}

int main(void)
{
	struct gpiod_chip *chip = NULL;
	struct gpiod_line *line = NULL;
	int ret = EXIT_FAILURE;

	struct sigaction sa;
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = signal_handler;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;
	if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
		log_message("sigaction failed");
		return EXIT_FAILURE;
	}

	if (ensure_images_dir() != 0)
		return EXIT_FAILURE;

	chip = gpiod_chip_open_by_name("gpiochip0");
	if (!chip) {
		log_message("gpiod_chip_open_by_name failed");
		return EXIT_FAILURE;
	}

	line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
	if (!line) {
		log_message("gpiod_chip_get_line failed");
		goto cleanup;
	}

	if (gpiod_line_request_falling_edge_events(line, "pir-motion") < 0) {
		log_message("gpiod_line_request_falling_edge_events failed");
		goto cleanup;
	}

	log_message("Motion detection started on GPIO17 (falling edge)");

	while (program_running) {
		struct timespec ts = { 0, POLL_TIMEOUT_MS * 1000000L };
		int ev = gpiod_line_event_wait(line, &ts);
		if (ev < 0) {
			if (errno == EINTR)
				continue;
			log_message("gpiod_line_event_wait failed");
			break;
		}
		if (ev == 0)
			continue;

		struct gpiod_line_event event;
		if (gpiod_line_event_read(line, &event) < 0) {
			if (errno == EINTR)
				continue;
			log_message("gpiod_line_event_read failed");
			continue;
		}

		if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE)
			continue;

		usleep(DEBOUNCE_MS * 1000);

		char filename[MAX_FILENAME];
		if (generate_filename(filename, sizeof(filename)) != 0)
			continue;

		log_message("Motion detected, capturing image");

		if (capture_image(filename) == 0) {
			char msg[MAX_FILENAME + 64];
			snprintf(msg, sizeof(msg), "Image saved: %s", filename);
			log_message(msg);
		} else {
			log_message("Image capture failed");
		}
	}

	log_message("Motion detection stopped");
	ret = EXIT_SUCCESS;

cleanup:
	if (line)
		gpiod_line_release(line);
	if (chip)
		gpiod_chip_close(chip);
	return ret;
}

