#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 200
#define HEIGHT 150
#define OUTPUT_FILE "cropped.yuv"
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        perror("Error opening device");
        return -1;
    }

    memset(&cap, 0, sizeof(cap));
    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(*fd);
        return -1;
    }

    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT ||
        fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Format not accepted: got %ux%u, format 0x%08x\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height, fmt.fmt.pix.pixelformat);
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(*fd);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(*fd);
        return -1;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, *fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(*fd);
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queueing buffer");
        munmap(buffer, buf.length);
        close(*fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(*fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting streaming");
        munmap(buffer, buf.length);
        close(*fd);
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, void **buffer, size_t *buffer_size) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            return -1;
        }
        perror("Error during select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (buf.index != 0) {
        fprintf(stderr, "Unexpected buffer index: %u\n", buf.index);
        return -1;
    }

    *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*buffer == MAP_FAILED) {
        perror("Error mapping captured buffer");
        return -1;
    }

    *buffer_size = buf.length;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error re-queueing buffer");
        munmap(*buffer, buf.length);
        return -1;
    }

    return 0;
}

static int crop_and_write(void *buffer, size_t buffer_size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening output file");
        return -1;
    }

    size_t expected_size = (size_t)WIDTH * HEIGHT * 2;
    if (buffer_size < expected_size) {
        fprintf(stderr, "Buffer too small: got %zu, expected %zu\n", buffer_size, expected_size);
        fclose(fp);
        return -1;
    }

    unsigned char *yuyv_data = (unsigned char *)buffer;
    unsigned char *cropped_data = malloc(WIDTH * HEIGHT * 2);
    if (cropped_data == NULL) {
        perror("Error allocating memory for cropped data");
        fclose(fp);
        return -1;
    }

    int crop_start_x = (WIDTH - WIDTH) / 2;
    int crop_start_y = (HEIGHT - HEIGHT) / 2;

    for (int y = 0; y < HEIGHT; y++) {
        for (int x = 0; x < WIDTH; x++) {
            int src_x = crop_start_x + x;
            int src_y = crop_start_y + y;
            int src_index = (src_y * WIDTH + src_x) * 2;
            int dst_index = (y * WIDTH + x) * 2;
            cropped_data[dst_index] = yuyv_data[src_index];
            cropped_data[dst_index + 1] = yuyv_data[src_index + 1];
        }
    }

    size_t bytes_written = fwrite(cropped_data, 1, expected_size, fp);
    if (bytes_written != expected_size) {
        fprintf(stderr, "Error writing to file: wrote %zu of %zu bytes\n", bytes_written, expected_size);
        free(cropped_data);
        fclose(fp);
        return -1;
    }

    free(cropped_data);
    fclose(fp);
    return 0;
}

int main(void) {
    int fd = -1;
    void *buffer = NULL;
    size_t buffer_size = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (init_camera(&fd) != 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        if (capture_frame(fd, &buffer, &buffer_size) == 0) {
            if (crop_and_write(buffer, buffer_size, OUTPUT_FILE) == 0) {
                printf("Cropped image saved to %s\n", OUTPUT_FILE);
                ret = EXIT_SUCCESS;
            }
            munmap(buffer, buffer_size);
            break;
        } else if (stop_flag) {
            break;
        }
    }

    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }

    return ret;
}

