#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  17
#define TILT_SERVO_PIN 18

#define SERVO_FREQUENCY 50
#define SERVO_RANGE     20000   /* 20 ms pulse width range (microseconds) */
#define SERVO_NEUTRAL   1500    /* 1.5 ms neutral pulse width (microseconds) */

#define STEP_SIZE       5
#define MIN_ANGLE       0
#define MAX_ANGLE       180

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return SERVO_NEUTRAL + (angle - 90) * (SERVO_RANGE / 90);
}

static int set_servo_angle(int pin, int angle) {
    int pulse_width = angle_to_pulse_width(angle);
    if (gpioServo(pin, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo on GPIO %d to angle %d (pulse %d us)\n",
                pin, angle, pulse_width);
        return -1;
    }
    return 0;
}

static int move_servo(int pin, int *current_angle, int direction) {
    *current_angle += direction * STEP_SIZE;
    if (*current_angle < MIN_ANGLE) *current_angle = MIN_ANGLE;
    if (*current_angle > MAX_ANGLE) *current_angle = MAX_ANGLE;
    return set_servo_angle(pin, *current_angle);
}

static void cleanup(void) {
    /* Stop PWM pulses and release the pigpio library */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    int pan_angle  = 90;
    int tilt_angle = 90;
    int ch;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    /* Set servo pins as outputs and initialize to neutral */
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PAN_SERVO_PIN);
        cleanup();
        return 1;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", TILT_SERVO_PIN);
        cleanup();
        return 1;
    }

    if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0 ||
        set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
        cleanup();
        return 1;
    }

    printf("Servo control started. Press arrow keys (up/down/left/right) to move, 'q' to quit.\n");

    while (running) {
        ch = getchar();
        if (ch == EOF) {
            break;
        }

        switch (ch) {
            case 'q':
            case 'Q':
                running = 0;
                break;

            case '\033': /* Escape sequence */
                ch = getchar();
                if (ch == '[') {
                    ch = getchar();
                    switch (ch) {
                        case 'A': /* Up arrow */
                            if (move_servo(TILT_SERVO_PIN, &tilt_angle, -1) != 0) {
                                fprintf(stderr, "Error: Failed to move tilt servo up\n");
                            }
                            break;
                        case 'B': /* Down arrow */
                            if (move_servo(TILT_SERVO_PIN, &tilt_angle, 1) != 0) {
                                fprintf(stderr, "Error: Failed to move tilt servo down\n");
                            }
                            break;
                        case 'C': /* Right arrow */
                            if (move_servo(PAN_SERVO_PIN, &pan_angle, 1) != 0) {
                                fprintf(stderr, "Error: Failed to move pan servo right\n");
                            }
                            break;
                        case 'D': /* Left arrow */
                            if (move_servo(PAN_SERVO_PIN, &pan_angle, -1) != 0) {
                                fprintf(stderr, "Error: Failed to move pan servo left\n");
                            }
                            break;
                    }
                }
                break;

            default:
                /* Ignore any other character */
                break;
        }

        if (running) {
            usleep(100000); /* 100 ms delay between commands */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

