#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define LCD_ENABLE 0x04
#define LCD_ON 0x04
#define LCD_OFF 0x00
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_FUNCTIONSET 0x20
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_5x8DOTS 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTDECREMENT 0x00
#define LCD_DISPLAYON 0x04
#define LCD_CURSOROFF 0x00
#define LCD_BLINKOFF 0x00
#define LCD_NOCURSOR 0x00
#define LCD_NOBLINK 0x00
#define LCD_DISPLAYMOVE 0x08
#define LCD_MOVERIGHT 0x04
#define LCD_MOVELEFT 0x00
#define LCD_8BITMODE 0x10
#define LCD_2LINE_5x8DOTS 0x08

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void lcd_strobe(int data) {
    if (i2c_handle < 0) return;
    int high = data | LCD_BACKLIGHT | LCD_ENABLE;
    int low = (data | LCD_BACKLIGHT) & ~LCD_ENABLE;
    i2cWriteByte(i2c_handle, high);
    gpioDelay(1);
    i2cWriteByte(i2c_handle, low);
    gpioDelay(100);
}

void lcd_byte(int bits, int mode) {
    if (i2c_handle < 0) return;
    int high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;
    lcd_strobe(high);
    lcd_strobe(low);
}

void lcd_command(int cmd) {
    lcd_byte(cmd, LCD_CMD);
}

void lcd_data(int data) {
    lcd_byte(data, LCD_CHR);
}

void lcd_string(const char *s) {
    while (*s) {
        lcd_data((unsigned char)*s++);
    }
}

void lcd_clear(void) {
    lcd_command(LCD_CLEARDISPLAY);
    gpioDelay(2000);
}

void lcd_set_cursor(int col, int row) {
    int row_offsets[] = {0x00, 0x40, 0x14, 0x54};
    if (row >= sizeof(row_offsets) / sizeof(row_offsets[0])) return;
    lcd_command(LCD_SETDDRAMADDR | (col + row_offsets[row]));
}

void lcd_init(void) {
    gpioDelay(50000);
    lcd_command(0x33);
    lcd_command(0x32);
    lcd_command(0x28);
    lcd_command(0x0C);
    lcd_command(0x06);
    lcd_command(0x01);
    gpioDelay(2000);
}

void lcd_display_flow_and_volume(float flow_rate, float total_volume) {
    char buffer[LCD_WIDTH + 1];
    lcd_clear();
    lcd_set_cursor(0, 0);
    snprintf(buffer, sizeof(buffer), "Flow: %.2f L/s", flow_rate);
    lcd_string(buffer);
    lcd_set_cursor(0, 1);
    snprintf(buffer, sizeof(buffer), "Vol: %.2f L", total_volume);
    lcd_string(buffer);
}

float calculate_flow_rate(int pulse_count, float time_interval) {
    if (time_interval <= 0.0f) return 0.0f;
    return (float)pulse_count / time_interval;
}

void log_data(float flow_rate, float total_volume) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Flow Rate: %.2f L/s, Total Volume: %.2f L\n", timestamp, flow_rate, total_volume);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN);

    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int pulse_count = 0;
    float total_volume = 0.0f;
    float flow_rate = 0.0f;
    time_t last_time = time(NULL);
    time_t lcd_update_time = time(NULL);

    while (running) {
        if (gpioRead(FLOW_SENSOR_GPIO) == 1) {
            pulse_count++;
            gpioDelay(100);
        }

        time_t current_time = time(NULL);
        float time_interval = (float)(current_time - last_time);

        if (time_interval > 0.0f) {
            flow_rate = calculate_flow_rate(pulse_count, time_interval);
            total_volume += (flow_rate * time_interval);
            log_data(flow_rate, total_volume);
            pulse_count = 0;
            last_time = current_time;
        }

        if (current_time - lcd_update_time >= 10) {
            lcd_display_flow_and_volume(flow_rate, total_volume);
            lcd_update_time = current_time;
        }

        gpioDelay(100000);
    }

    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_string("Shutting down...");
    gpioDelay(2000000);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

