/*
 * Wind speed and direction monitor for Raspberry Pi 4 Model B.
 *
 * Anemometer pulse on GPIO17 (BCM) — rising edge interrupt.
 * Wind vane on MCP3008 channel 0 (SPI0/CE0, mode 0, 1 MHz).
 * 16x2 LCD via PCF8574 backpack on I2C bus 1.
 *
 * Build:  gcc -O2 -Wall -Wextra -o wind_monitor wind_monitor.c -lm
 * Run:    sudo ./wind_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */

#define ANEMOMETER_GPIO          17          /* BCM pin for anemometer pulse */
#define SPI_DEVICE               "/dev/spidev0.0"
#define SPI_SPEED_HZ             1000000     /* 1 MHz */
#define SPI_BITS_PER_WORD        8
#define SPI_MODE                 0
#define I2C_BUS                  "/dev/i2c-1"
#define LCD_I2C_ADDR             0x27        /* PCF8574 backpack */
#define LCD_WIDTH                16
#define LCD_HEIGHT               2
#define SAMPLE_WINDOW_MS         500
#define LCD_UPDATE_INTERVAL_MS   500
#define ADC_CHANNEL              0           /* MCP3008 single-ended channel 0 */
#define ADC_MAX                  1023        /* 10-bit ADC */
#define ADC_MIN                  0
#define ADC_STUCK_THRESHOLD      5           /* consecutive stuck readings */
#define ADC_READ_ERROR_THRESHOLD 10          /* consecutive read errors */
#define ANEMOMETER_READ_ERROR_THRESHOLD 10

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static volatile uint32_t     g_last_pulse_tick = 0;
static volatile bool         g_pulse_pending = false;
static int                    g_spi_fd = -1;
static int                    g_i2c_fd = -1;

/* --------------------------- Function prototypes ------------------------- */

static void signal_handler(int sig);
static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  spi_init(void);
static int  i2c_init(void);
static int  lcd_init(void);
static int  lcd_write_byte(uint8_t data, bool is_data);
static int  lcd_send_command(uint8_t cmd);
static int  lcd_send_data(uint8_t data);
static int  lcd_clear(void);
static int  lcd_set_cursor(uint8_t col, uint8_t row);
static int  lcd_print(const char *s);
static int  read_adc(uint8_t channel, uint16_t *out_value);
static void cleanup(void);

/* ------------------------------- ISR ------------------------------------- */

static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1)            /* rising edge only */
        return;

    uint32_t elapsed = tick - g_last_pulse_tick;
    if (elapsed > 0) {          /* ignore spurious glitches */
        g_pulse_count++;
        g_last_pulse_tick = tick;
    }
}

/* ------------------------------- SPI ------------------------------------- */

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------- I2C ------------------------------------- */

static int i2c_init(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LCD_I2C_ADDR) < 0) {
        fprintf(stderr, "I2C_SLAVE(0x%02X): %s\n", LCD_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------- LCD ------------------------------------- */

/*
 * PCF8574 backpack: 4-bit data interface, HD44780 compatible.
 *
 * Wiring:
 *   PCF8574  LCD
 *   --------  ----
 *   VCC      5V
 *   GND      GND
 *   SDA      GPIO2 (I2C bus 1)
 *   SCL      GPIO3 (I2C bus 1)
 *   A0       GND  (HD44780 mode)
 *   EN       GPIO2 (hardware enable)
 *   RW       GND  (write mode)
 *   RS       GPIO2 (register select)
 *   D0-D3    GPIO2 (4-bit data)
 *   D4-D7    GPIO2 (4-bit data)
 *   BL       3V3  (backlight)
 */

static int lcd_init(void)
{
    if (lcd_send_command(0x33) < 0) return -1;  /* init: 8-bit, 2-line */
    usleep(5000);
    if (lcd_send_command(0x32) < 0) return -1;  /* init: 8-bit, 2-line */
    usleep(5000);
    if (lcd_send_command(0x28) < 0) return -1;  /* 4-bit, 2-line, 5x8 font */
    usleep(5000);
    if (lcd_send_command(0x0C) < 0) return -1;  /* display on, cursor off */
    usleep(5000);
    if (lcd_send_command(0x06) < 0) return -1;  /* entry mode: inc, no shift */
    usleep(5000);
    if (lcd_clear() < 0) return -1;
    return 0;
}

static int lcd_write_byte(uint8_t data, bool is_data)
{
    uint8_t hi = (data & 0xF0) | (is_data ? 0x08 : 0x00);
    uint8_t lo = ((data << 4) & 0xF0) | (is_data ? 0x08 : 0x00);

    /* Enable high nibble */
    if (write(g_i2c_fd, &hi, 1) != 1) {
        fprintf(stderr, "LCD write high nibble: %s\n", strerror(errno));
        return -1;
    }
    usleep(1);
    hi |= 0x04;
    if (write(g_i2c_fd, &hi, 1) != 1) {
        fprintf(stderr, "LCD high nibble enable: %s\n", strerror(errno));
        return -1;
    }
    usleep(100);
    hi &= ~0x04;
    if (write(g_i2c_fd, &hi, 1) != 1) {
        fprintf(stderr, "LCD high nibble disable: %s\n", strerror(errno));
        return -1;
    }

    /* Enable low nibble */
    if (write(g_i2c_fd, &lo, 1) != 1) {
        fprintf(stderr, "LCD write low nibble: %s\n", strerror(errno));
        return -1;
    }
    usleep(1);
    lo |= 0x04;
    if (write(g_i2c_fd, &lo, 1) != 1) {
        fprintf(stderr, "LCD low nibble enable: %s\n", strerror(errno));
        return -1;
    }
    usleep(100);
    lo &= ~0x04;
    if (write(g_i2c_fd, &lo, 1) != 1) {
        fprintf(stderr, "LCD low nibble disable: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int lcd_send_command(uint8_t cmd)
{
    return lcd_write_byte(cmd, false);
}

static int lcd_send_data(uint8_t data)
{
    return lcd_write_byte(data, true);
}

static int lcd_clear(void)
{
    return lcd_send_command(0x01);
}

static int lcd_set_cursor(uint8_t col, uint8_t row)
{
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    return lcd_send_command(addr);
}

static int lcd_print(const char *s)
{
    for (size_t i = 0; s[i] != '\0'; i++) {
        if (lcd_send_data((uint8_t)s[i]) < 0)
            return -1;
    }
    return 0;
}

/* ----------------------------- ADC (MCP3008) ----------------------------- */

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low 2 bits)
 *   rx[1] bits 1-0 + rx[2] bits 7-0    -> 10-bit result
 */
static int read_adc(uint8_t channel, uint16_t *out_value)
{
    if (channel > 7) {
        fprintf(stderr, "ADC channel %u out of range\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_print("Shutting down...");
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------- Signal ---------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (i2c_init() < 0) {
        fprintf(stderr, "I2C initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize LCD */
    if (lcd_init() < 0) {
        fprintf(stderr, "LCD initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize anemometer ISR */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx failed for GPIO%d.\n", ANEMOMETER_GPIO);
        gpioTerminate();
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Wind speed and direction monitor started.\n");
    printf("  Anemometer : GPIO%d (rising edge)\n", ANEMOMETER_GPIO);
    printf("  ADC        : MCP3008 channel %d, SPI0/CE0\n", ADC_CHANNEL);
    printf("  LCD        : 16x2 via PCF8574 on I2C bus 1, addr 0x27\n");
    printf("Press Ctrl+C to exit.\n");

    struct timespec next_update;
    clock_gettime(CLOCK_MONOTONIC, &next_update);

    uint32_t sample_start_tick = 0;
    uint32_t sample_end_tick   = 0;
    uint32_t sample_window_us  = (uint32_t)SAMPLE_WINDOW_MS * 1000;
    uint32_t last_sample_tick  = 0;

    int  adc_err_count = 0;
    int  anem_err_count = 0;
    int  adc_stuck_count = 0;

    while (g_running) {
        /* ----------------------- Sample window ----------------------- */

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        uint32_t elapsed_us = (uint32_t)(now.tv_sec - next_update.tv_sec) * 1000000ULL
                             + (uint32_t)(now.tv_nsec - next_update.tv_nsec) / 1000ULL;

        if (elapsed_us >= sample_window_us) {
            uint32_t pulses = g_pulse_count;
            g_pulse_count = 0;
            g_last_pulse_tick = now.tv_sec;

            /* ----------------------- Wind speed ----------------------- */

            /*
             * Wind speed (m/s) = (pulses / window_s) * 3600 / 447.0
             *   pulses / window_s  -> revolutions per second
             *   3600 / 447.0       -> m/s
             */
            double revolutions_per_sec = (double)pulses / (double)sample_window_us;
            double wind_speed_mps = revolutions_per_sec * 3600.0 / 447.0;

            /* ----------------------- Direction ----------------------- */

            uint16_t adc_value = 0;
            if (read_adc(ADC_CHANNEL, &adc_value) < 0) {
                adc_err_count++;
                if (adc_err_count >= ADC_READ_ERROR_THRESHOLD) {
                    fprintf(stderr, "ADC read error threshold reached. Exiting.\n");
                    g_running = 0;
                }
                next_update = now;
                continue;
            }

            /*
             * Wind direction (degrees):
             *   0-180  -> calm
             *   181-360 -> gust
             */
            double direction = 0.0;
            if (adc_value > ADC_MIN && adc_value < ADC_MAX) {
                direction = (double)adc_value / (double)ADC_MAX * 360.0;
            }

            /* ----------------------- Display update ----------------------- */

            char line1[20];
            char line2[20];

            snprintf(line1, sizeof(line1), "Wind: %.1f m/s", wind_speed_mps);
            snprintf(line2, sizeof(line2), "Dir: %.0f deg", direction);

            lcd_clear();
            lcd_set_cursor(0, 0);
            lcd_print(line1);
            lcd_set_cursor(0, 1);
            lcd_print(line2);

            next_update = now;
        }

        /* ----------------------- Error checking ----------------------- */

        /* Anemometer ISR error checking */
        if (g_pulse_pending) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            uint32_t elapsed_us = (uint32_t)(now.tv_sec - last_sample_tick) * 1000000ULL
                                 + (uint32_t)(now.tv_nsec - last_sample_tick) / 1000ULL;
            if (elapsed_us > sample_window_us) {
                anem_err_count++;
                if (anem_err_count >= ANEM_ERR_THRESHOLD) {
                    fprintf(stderr, "Anemometer ISR error threshold reached. Exiting.\n");
                    g_running = 0;
                }
            }
        }

        /* ADC stuck value error checking */
        if (adc_value == ADC_MIN || adc_value == ADC_MAX) {
            adc_stuck_count++;
            if (adc_stuck_count >= ADC_STUCK_THRESHOLD) {
                fprintf(stderr, "ADC stuck value error threshold reached. Exiting.\n");
                g_running = 0;
            }
        }

        usleep(10000); /* 10 ms poll interval */
    }

    printf("\nExiting...\n");
    cleanup();
    gpioTerminate();
    return EXIT_SUCCESS;
}

