/*
 * Water Flow Rate Monitor using YF-S201 Sensor and LCD1602
 * Board: Raspberry Pi 3 Model B+
 * Sensor: YF-S201 pulse output -> GPIO17 (BCM 17, physical pin 11)
 * LCD:   LCD1602 via I2C bus 1 (address 0x27)
 *
 * Build: gcc -O2 -Wall -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:   sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27

#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

#define FLOW_CALIBRATION_FACTOR 7.5
#define PULSES_PER_LITER 1000.0
#define SAMPLE_INTERVAL_SEC 1.0
#define SENSOR_TIMEOUT_SEC 10.0

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static volatile uint32_t last_pulse_tick = 0;
static volatile bool sensor_present = true;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pulse_count++;
        last_pulse_tick = tick;
    }
}

static void lcd_strobe(int data) {
    gpioWrite(LCD_RS, LCD_CHR);
    gpioWrite(LCD_D4, (data >> 4) & 0x01);
    gpioWrite(LCD_D5, (data >> 5) & 0x01);
    gpioWrite(LCD_D6, (data >> 6) & 0x01);
    gpioWrite(LCD_D7, (data >> 7) & 0x01);
    gpioWrite(LCD_EN, ENABLE);
    gpioDelay(1);
    gpioWrite(LCD_EN, 0);
    gpioDelay(100);
}

static void lcd_byte(int bits, int mode) {
    gpioWrite(LCD_RS, mode);
    lcd_strobe(bits);
}

static void lcd_command(int cmd) {
    lcd_byte(cmd, LCD_CMD);
}

static void lcd_data(int data) {
    lcd_byte(data, LCD_CHR);
}

static void lcd_string(const char *s) {
    while (*s) {
        lcd_data((unsigned char)*s++);
    }
}

static void lcd_clear(void) {
    lcd_command(0x01);
    gpioDelay(2000);
}

static void lcd_init(void) {
    gpioDelay(50000);
    lcd_strobe(0x30);
    gpioDelay(5000);
    lcd_strobe(0x30);
    gpioDelay(150);
    lcd_strobe(0x30);
    gpioDelay(150);
    lcd_strobe(0x20);
    gpioDelay(150);
    lcd_command(0x28);
    lcd_command(0x08);
    lcd_command(0x01);
    gpioDelay(2000);
    lcd_command(0x06);
    lcd_command(0x0C);
}

static void lcd_display_flow_rate(float flow_rate) {
    char buffer[LCD_WIDTH + 1];
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);
    lcd_clear();
    lcd_command(LCD_LINE_1);
    lcd_string(buffer);
    lcd_command(LCD_LINE_2);
    lcd_string("Sensor OK");
}

static void lcd_display_sensor_absent(void) {
    lcd_clear();
    lcd_command(LCD_LINE_1);
    lcd_string("Sensor Absent");
    lcd_command(LCD_LINE_2);
    lcd_string("Check wiring");
}

static void lcd_display_error(const char *message) {
    lcd_clear();
    lcd_command(LCD_LINE_1);
    lcd_string("Error");
    lcd_command(LCD_LINE_2);
    lcd_string(message);
}

static float calculate_flow_rate(uint32_t pulses, float calibration_factor) {
    float liters = (float)pulses / PULSES_PER_LITER;
    return (liters / calibration_factor) * 60.0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO%d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n", I2C_BUS, LCD_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init();
    lcd_clear();

    time_t last_sample_time = time(NULL);
    uint32_t last_pulse_count = 0;

    while (running) {
        time_t current_time = time(NULL);
        double elapsed = difftime(current_time, last_sample_time);

        if (elapsed >= SAMPLE_INTERVAL_SEC) {
            uint32_t current_pulse_count = pulse_count;
            uint32_t pulses_in_interval = current_pulse_count - last_pulse_count;
            last_pulse_count = current_pulse_count;
            last_sample_time = current_time;

            if (pulses_in_interval == 0) {
                if (sensor_present) {
                    sensor_present = false;
                    lcd_display_sensor_absent();
                }
            } else {
                if (!sensor_present) {
                    sensor_present = true;
                    lcd_clear();
                }
                float flow_rate = calculate_flow_rate(pulses_in_interval, FLOW_CALIBRATION_FACTOR);
                lcd_display_flow_rate(flow_rate);
            }

            uint32_t current_tick = gpioTick();
            uint32_t last_seen_tick = last_pulse_tick;
            if (current_tick - last_seen_tick > (uint32_t)(SENSOR_TIMEOUT_SEC * 1000000)) {
                if (sensor_present) {
                    sensor_present = false;
                    lcd_display_sensor_absent();
                }
            }
        }

        gpioDelay(100000);
    }

    lcd_clear();
    lcd_command(LCD_LINE_1);
    lcd_string("Shutting down...");
    gpioDelay(2000000);

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

