#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ROW_COUNT 8
#define COL_COUNT 8
#define SCAN_DELAY_US 800

static const int row_pins[ROW_COUNT] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[COL_COUNT] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(int pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d to mode %u\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(int pin, int level) {
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d to level %d\n", pin, level);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < ROW_COUNT; i++) {
        if (safe_set_mode(row_pins[i], PI_OUTPUT) != 0) {
            gpioTerminate();
            return -1;
        }
        if (safe_write(row_pins[i], 0) != 0) {
            gpioTerminate();
            return -1;
        }
    }

    for (int i = 0; i < COL_COUNT; i++) {
        if (safe_set_mode(col_pins[i], PI_OUTPUT) != 0) {
            gpioTerminate();
            return -1;
        }
        if (safe_write(col_pins[i], 1) != 0) {
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < ROW_COUNT; i++) {
        safe_write(row_pins[i], 0);
    }
    for (int i = 0; i < COL_COUNT; i++) {
        safe_write(col_pins[i], 1);
    }
    gpioTerminate();
}

static void display_matrix(const int matrix[ROW_COUNT][COL_COUNT]) {
    for (int row = 0; row < ROW_COUNT; row++) {
        if (safe_write(row_pins[row], 1) != 0) return;
        for (int col = 0; col < COL_COUNT; col++) {
            if (safe_write(col_pins[col], matrix[row][col]) != 0) return;
        }
        gpioDelay(SCAN_DELAY_US);
        if (safe_write(row_pins[row], 0) != 0) return;
    }
}

static void generate_wave(int matrix[ROW_COUNT][COL_COUNT], int direction) {
    for (int row = 0; row < ROW_COUNT; row++) {
        for (int col = 0; col < COL_COUNT; col++) {
            int index = (direction == 1) ? (row + col) % COL_COUNT : (row - col + COL_COUNT) % COL_COUNT;
            matrix[row][col] = (index == 0) ? 1 : 0;
        }
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int matrix[ROW_COUNT][COL_COUNT];
    int direction = 1;

    while (running) {
        generate_wave(matrix, direction);
        display_matrix(matrix);
        direction = (direction == 1) ? -1 : 1;
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

