#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define DELAY_MS 150

static const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int set_all_rows_low(struct gpiod_line_bulk *row_bulk) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpiod_line_set_value(row_bulk->lines[i], 0) < 0) {
            perror("gpiod_line_set_value (row low)");
            return -1;
        }
    }
    return 0;
}

static int set_all_cols_high(struct gpiod_line_bulk *col_bulk) {
    for (int i = 0; i < NUM_COLS; i++) {
        if (gpiod_line_set_value(col_bulk->lines[i], 1) < 0) {
            perror("gpiod_line_set_value (col high)");
            return -1;
        }
    }
    return 0;
}

static int set_col_low(struct gpiod_line_bulk *col_bulk, int col) {
    if (gpiod_line_set_value(col_bulk->lines[col], 0) < 0) {
        perror("gpiod_line_set_value (col low)");
        return -1;
    }
    return 0;
}

static int set_row_high(struct gpiod_line_bulk *row_bulk, int row) {
    if (gpiod_line_set_value(row_bulk->lines[row], 1) < 0) {
        perror("gpiod_line_set_value (row high)");
        return -1;
    }
    return 0;
}

static int clear_matrix(struct gpiod_line_bulk *row_bulk, struct gpiod_line_bulk *col_bulk) {
    if (set_all_cols_high(col_bulk) < 0) return -1;
    if (set_all_rows_low(row_bulk) < 0) return -1;
    return 0;
}

static int display_column(struct gpiod_line_bulk *row_bulk, struct gpiod_line_bulk *col_bulk, int col) {
    if (clear_matrix(row_bulk, col_bulk) < 0) return -1;
    if (set_col_low(col_bulk, col) < 0) return -1;
    for (int row = 0; row < NUM_ROWS; row++) {
        if (set_row_high(row_bulk, row) < 0) return -1;
        usleep(DELAY_MS * 1000);
        if (set_row_high(row_bulk, row) < 0) return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk row_bulk, col_bulk;
    int ret = EXIT_FAILURE;

    gpiod_line_bulk_init(&row_bulk);
    gpiod_line_bulk_init(&col_bulk);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, row_pins[i]);
        if (!line) {
            perror("gpiod_chip_get_line (row)");
            goto cleanup;
        }
        if (gpiod_line_bulk_add(&row_bulk, line) < 0) {
            perror("gpiod_line_bulk_add (row)");
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, col_pins[i]);
        if (!line) {
            perror("gpiod_chip_get_line (col)");
            goto cleanup;
        }
        if (gpiod_line_bulk_add(&col_bulk, line) < 0) {
            perror("gpiod_line_bulk_add (col)");
            goto cleanup;
        }
    }

    if (gpiod_line_request_bulk_output(&row_bulk, "led-matrix", 0) < 0) {
        perror("gpiod_line_request_bulk_output (row)");
        goto cleanup;
    }

    if (gpiod_line_request_bulk_output(&col_bulk, "led-matrix", 1) < 0) {
        perror("gpiod_line_request_bulk_output (col)");
        goto cleanup;
    }

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    while (running) {
        for (int col = 0; col < NUM_COLS && running; col++) {
            if (display_column(&row_bulk, &col_bulk, col) < 0) {
                fprintf(stderr, "Error displaying column %d\n", col);
                goto cleanup;
            }
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    clear_matrix(&row_bulk, &col_bulk);
    gpiod_line_release_bulk(&row_bulk);
    gpiod_line_release_bulk(&col_bulk);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

