/*
 * VL53L3CX multi-target distance reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L3CX SDA -> GPIO2 (pin 3, I2C bus 1)
 *   VL53L3CX SCL -> GPIO3 (pin 5, I2C bus 1)
 *   VL53L3CX VDD -> 3.3 V
 *   VL53L3CX GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l3cx_reader vl53l3cx_reader.c
 *
 * Run:
 *   ./vl53l3cx_reader
 */

#include <stdio.h>
