        (void)i2c_write_reg8(g_i2c_fd, VL53L3CX_REG_SYSTEM_MODE_START, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("VL53L3CX reader terminated.\n");
    return EXIT_SUCCESS;
}

