/*
 * MLX75031 Time-of-Flight Distance Logger for Raspberry Pi Zero W
 *
 * Reads distance data from a Melexis MLX75031 sensor on I2C bus 1
 * (address 0x50) every 100 ms and appends timestamped readings to
 * depth_log.csv.  On I2C read failure, logs -1 and attempts to
 * re-open the I2C handle.  Handles SIGINT for graceful shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75031_logger mlx75031_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75031_ADDR  0x50
#define LOG_FILE       "depth_log.csv"
#define SAMPLE_MS      100
#define MAX_RETRIES    3

/*
 * MLX75031 register map (example; adjust per datasheet).
 * The sensor returns a 16-bit distance value in registers 0x00-0x01.
 */
#define REG_DISTANCE_L 0x00
#define REG_DISTANCE_H 0x01

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "[ERROR] open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
