/*
 * Si1145 Proximity & Ambient Light Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   Si1145 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   Si1145 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   Si1145 VDD  -> 3.3 V
 *   Si1145 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1145_logger si1145_logger.c -lsi1145
 *
 * Run:
 *   ./si1145_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <si1145.h>

#define I2C_BUS        1
#define SI1145_ADDR    0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_PERIOD  500000   /* microseconds (500 ms) */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, Proximity: %u, Ambient: %u\n",
                timestamp, proximity, ambient) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int i2c_handle = -1;
    FILE *log_fp = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus to Si1145 */
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, SI1145_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize Si1145 sensor */
    if (si1145_init(i2c_handle) != 0) {
        fprintf(stderr, "Error initializing Si1145 sensor (addr 0x%02X).\n",
                SI1145_ADDR);
        fprintf(stderr, "Check wiring and that the sensor is present.\n");
        goto cleanup;
    }

    printf("Si1145 logger started. Logging to '%s' every %d ms.\n",
           LOG_FILE, SAMPLE_PERIOD / 1000);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t proximity = 0;
        uint16_t ambient   = 0;

        if (si1145_read_proximity(i2c_handle, &proximity) != 0) {
            fprintf(stderr, "Error reading proximity data.\n");
        } else if (si1145_read_ambient(i2c_handle, &ambient) != 0) {
            fprintf(stderr, "Error reading ambient light data.\n");
        } else {
            log_data(log_fp, proximity, ambient);
        }

        /* Sleep 500 ms; interruptible by signals */
        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (i2c_handle >= 0) {
        si1145_call(i2c_handle);   /* best-effort sensor shutdown */
        i2cClose(i2c_handle);
    }
    if (log_fp != NULL) {
        fflush(log_fp);
        fclose(log_fp);
    }
    return rc;
}

