/*
 * E18-D50NK IR Proximity Sensor – Falling-Edge Detection Logger
 * Board:  Raspberry Pi 5
 * Sensor: E18-D50NK on GPIO4  (BCM 4, physical pin 7)  – LOW  = object detected
 * LED:    GPIO17 (BCM 17, physical pin 11)
 * Log:    proximity.log  (ISO-8601 UTC timestamps)
 *
 * Build:  gcc -O2 -Wall -Wextra -o proximity proximity.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_PIN      4
#define LED_PIN         17
#define LOG_FILE        "proximity.log"
#define POLL_INTERVAL_US 100000   /* 100 ms */
#define LED_ON_US       100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_detection(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s Object detected\n", ts) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() on log failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Blinking LED                                                        */
/* ------------------------------------------------------------------ */
static int blink_led(struct gpiod_line *led)
{
    if (gpiod_line_set_value(led, 1) < 0) {
        fprintf(stderr, "Failed to turn LED on: %s\n", strerror(errno));
        return -1;
    }
    usleep(LED_ON_US);
    if (gpiod_line_set_value(led, 0) < 0) {
        fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor = NULL;
    struct gpiod_line *led = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip (default name) ---- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fallback: let the library's API call find the default chip */
        chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    }
    if (!chip) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get lines ---- */
    sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor) {
        fprintf(stderr, "Failed to get sensor line %d: %s\n",
                SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Failed to get LED line %d: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request sensor as input ---- */
    if (gpiod_line_request_input(sensor, "e18-d50nk-sensor") < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Request LED as output, initial value LOW ---- */
    if (gpiod_line_request_output(led, "e18-d50nk-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Monitoring E18-D50NK on GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_PIN);

    int prev_state = gpiod_line_get_value(sensor);
    if (prev_state < 0) {
        fprintf(stderr, "Initial sensor read failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Main polling loop ---- */
    while (g_running) {
        int cur = gpiod_line_get_value(sensor);
        if (cur < 0) {
            fprintf(stderr, "Sensor read error: %s\n", strerror(errno));
            break;
        }

        /* Falling edge: HIGH -> LOW */
        if (prev_state == 1 && cur == 0) {
            if (log_detection() < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
            if (blink_led(led) < 0) {
                fprintf(stderr, "LED blink failed; continuing.\n");
            }
        }

        prev_state = cur;
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led) {
        gpiod_line_set_value(led, 0);   /* best-effort LED off */
        gpiod_line_release(led);
    }
    if (sensor) {
        gpiod_line_release(sensor);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting cleanly.\n");
    return ret;
}

