code:
/*
 * Si1145 Proximity & Ambient Light Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si1145 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   Si1145 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   Si1145 VDD -> 3.3 V
 *   Si1145 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1145_logger si1145_logger.c -lgpiod
 *
 * Run:
 *   sudo ./si1145_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si1145 register definitions (from datasheet) ---- */
#define SI1145_I2C_ADDR        0x60
#define SI1145_REG_PART_ID     0x00
#define SI1145_REG_REV_ID      0x01
#define SI1145_REG_SEQ_ID      0x02
#define SI1145_REG_INT_CFG     0x03
#define SI1145_REG_IRQ_ENABLE  0x04
#define SI1145_REG_IRQ_MODE1   0x05
#define SI1145_REG_IRQ_MODE2   0x06
#define SI1145_REG_HW_KEY      0x07
#define SI1145_REG_MEAS_RATE0  0x08
#define SI1145_REG_MEAS_RATE1  0x09
#define SI1145_REG_PS_RATE     0x0A
#define SI1145_REG_PS_LED21    0x0F
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_IR_DATA0  0x24
#define SI1145_REG_ALS_IR_DATA1  0x25
#define SI1145_REG_PS1_DATA0    0x26
#define SI1145_REG_PS1_DATA1    0x27
#define SI1145_REG_COMMAND     0x30

#define SI1145_PART_ID         0x45
#define SI1145_HW_KEY_VAL      0x17
#define SI1145_CMD_RESET       0x01
#define SI1145_CMD_PSALS_AUTO  0x0F

/* ---- Globals for signal-handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; heavy work in main loop             */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                              */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, value, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) != 0)
        return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) != 0)
        return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Si1145 sensor driver                                               */
/* ------------------------------------------------------------------ */
static int si1145_init(int fd)
{
    uint8_t part_id;

    /* Verify sensor identity */
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X).\n",
                part_id, SI1145_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART_ID=0x%02X).\n", part_id);

    /* Software reset */
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_RESET) != 0)
        return -1;
    usleep(10000); /* 10 ms settle after reset */

    /* Write HW_KEY to enable the device */
    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) != 0)
        return -1;

    /* Configure measurement rate (0x00 = 0 ms / no auto-measurement) */
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE1, 0x00) != 0)
        return -1;

    /* Configure PS_RATE (proximity measurement rate) */
    if (i2c_write_reg8(fd, SI1145_REG_PS_RATE, 0x00) != 0)
        return -1;

    /* Configure PS_LED21 (LED current for proximity) */
    if (i2c_write_reg8(fd, SI1145_REG_PS_LED21, 0x0F) != 0)
        return -1;

    /* Start autonomous PS+ALS measurement */
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_PSALS_AUTO) != 0)
        return -1;

    return 0;
}

static int si1145_read_proximity(int fd, uint16_t *proximity)
{
    return i2c_read_reg16(fd, SI1145_REG_PS1_DATA0, proximity);
}

static int si1145_read_ambient_light(int fd, uint16_t *ambient_light)
{
    return i2c_read_reg16(fd, SI1145_REG_ALS_VIS_DATA0, ambient_light);
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u\n", timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    const char *i2c_dev = "/dev/i2c-1";
    const char *log_file = "biometric_data.log";
    uint16_t proximity, ambient_light;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(i2c_dev, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", i2c_dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1145_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1145_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1145_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1145 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(log_file, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", log_file, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging Si1145 data to %s. Press Ctrl+C to stop.\n", log_file);

    /* Main sampling loop */
    while (g_running) {
        if (si1145_read_proximity(g_i2c_fd, &proximity) != 0) {
            fprintf(stderr, "Proximity read error — continuing.\n");
        } else if (si1145_read_ambient_light(g_i2c_fd, &ambient_light) != 0) {
            fprintf(stderr, "Ambient light read error — continuing.\n");
        } else {
            if (log_data(g_log_fp, proximity, ambient_light) != 0) {
                fprintf(stderr, "Logging error — continuing.\n");
            }
        }
        sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

