/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 27 (BCM) via 1k/2k voltage divider (5V -> 3.3V)
 *   HC-SR04 VCC  -> 5V
 *   HC-SR04 GND  -> GND
 *
 * Build: gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27

#define SPEED_OF_SOUND   34300.0          /* cm/s at ~20 °C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define WATERING_THRESHOLD_CM 15.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000            /* 30 ms max echo wait */
#define LOOP_DELAY_US    60000000         /* 60 s between readings */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Measure the distance in cm.
 * Returns:
 *   >= 0.0 on success
 *   -1.0 on timeout (no echo start)
 *   -2.0 on timeout (echo stuck high)
 *   -3.0 on out-of-range reading
 */
static double measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write TRIGGER low\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write TRIGGER high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write TRIGGER low\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout 30 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            return -1.0;                 /* no echo — sensor absent or wiring fault */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 30 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            return -2.0;                 /* echo stuck high — sensor fault or out of range */
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    double distance = (double)pulse_us * SPEED_OF_SOUND / 2000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -3.0;
    }
    return distance;
}

/*
 * Log a reading with an ISO-8601 timestamp.
 * Returns 0 on success, -1 on failure.
 */
static int log_reading(double distance, const char *status)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (g_log_file == NULL) {
        fprintf(stderr, "Error: log file not open\n");
        return -1;
    }

    if (status != NULL) {
        fprintf(g_log_file, "%s, Distance: %s\n", timestamp, status);
    } else {
        fprintf(g_log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    }
    fflush(g_log_file);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(100000); /* 100 ms settle */

    /* Open log file */
    g_log_file = fopen("distance_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGINT) failed");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: sigaction(SIGTERM) failed");
    }

    printf("HC-SR04 distance sensor started. Logging to distance_log.txt every 60 s.\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            if (distance == -1.0) {
                fprintf(stderr, "Warning: echo timeout — sensor absent or wiring fault\n");
                log_reading(0.0, "ERROR: echo timeout");
            } else if (distance == -2.0) {
                fprintf(stderr, "Warning: echo stuck high — sensor fault or out of range\n");
                log_reading(0.0, "ERROR: echo stuck high");
            } else {
                fprintf(stderr, "Warning: reading out of range\n");
                log_reading(0.0, "ERROR: out of range");
            }
        } else {
            printf("Distance: %.2f cm\n", distance);
            log_reading(distance, NULL);

            if (distance < WATERING_THRESHOLD_CM) {
                printf("Time to water the plant!\n");
                log_reading(distance, "Time to water the plant!");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 600 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(TRIGGER_PIN, 0);
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

