#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x90
#define APDS9960_CONFIG2 0x91
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C
#define APDS9960_POFFSET_UR 0x9D
#define APDS9960_POFFSET_DL 0x9E
#define APDS9960_CONFIG3 0x9F

#define PROXIMITY_THRESHOLD 200
#define POLL_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg_low, uint16_t *value) {
    uint8_t lo, hi;
    if (read_reg(reg_low, &lo) < 0) return -1;
    if (read_reg(reg_low + 1, &hi) < 0) return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_apds9960(void) {
    if (write_reg(APDS9960_ENABLE, 0x00) < 0) return -1;
    gpioDelay(3000);

    if (write_reg(APDS9960_ATIME, 0xFF) < 0) return -1;
    if (write_reg(APDS9960_PTIME, 0xFF) < 0) return -1;
    if (write_reg(APDS9960_WTIME, 0xFF) < 0) return -1;
    if (write_reg(APDS9960_PPULSE, 0x87) < 0) return -1;
    if (write_reg(APDS9960_CONTROL, 0x03) < 0) return -1;
    if (write_reg(APDS9960_CONFIG1, 0x60) < 0) return -1;
    if (write_reg(APDS9960_CONFIG2, 0x01) < 0) return -1;
    if (write_reg(APDS9960_POFFSET_UR, 0x00) < 0) return -1;
    if (write_reg(APDS9960_POFFSET_DL, 0x00) < 0) return -1;
    if (write_reg(APDS9960_CONFIG3, 0x00) < 0) return -1;

    if (write_reg(APDS9960_ENABLE, 0x0F) < 0) return -1;
    gpioDelay(3000);

    return 0;
}

static int read_proximity(uint8_t *proximity) {
    uint8_t status;
    if (read_reg(APDS9960_STATUS, &status) < 0) return -1;
    if ((status & 0x01) == 0) return 1;
    if (read_reg(APDS9960_PDATA, proximity) < 0) return -1;
    return 0;
}

static int read_color(uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_word(APDS9960_CDATAL, red) < 0) return -1;
    if (read_word(APDS9960_RDATAL, red) < 0) return -1;
    if (read_word(APDS9960_GDATAL, green) < 0) return -1;
    if (read_word(APDS9960_BDATAL, blue) < 0) return -1;
    return 0;
}

static void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_apds9960() < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
        fflush(log_file);
    }

