    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting data logging...\n");

    while (!terminate) {
        uint8_t proximity;
        int rc = read_proximity(&proximity);

        if (rc == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                uint16_t red, green, blue;
                if (read_color(&red, &green, &blue) == 0) {
                    log_data(red, green, blue, proximity);
                }
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error reading proximity, re-initializing sensor...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                break;
            }
            if (init_apds9960() < 0) {
                fprintf(stderr, "APDS9960 re-initialisation failed\n");
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

