/*
 * Si1182‑A‑GMR heart-rate monitor for Raspberry Pi 5
 * I2C bus : /dev/i2c-1
 * CSV    : heartrate.csv  (timestamp,bpm)
 *
 * Build  : gcc -O2 -Wall -Wextra -o heartrate heartrate.c
 * Run    : ./heartrate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ---- Si1182 register map (subset) ---- */
#define SI1182_I2C_ADDR        0x50
#define SI1182_REG_PART_ID     0x00
#define SI1182_REG_HW_KEY      0x07
#define SI1182_REG_MEAS_RATE0  0x08
#define SI1182_REG_MEAS_RATE1  0x09
#define SI1182_REG_PS_LED21    0x0F
#define SI1182_REG_PS1_DATA0   0x26
#define SI1182_REG_PS1_DATA1   0x27
#define SI1182_REG_PS2_DATA0   0x28
#define SI1182_REG_PS2_DATA1   0x29
#define SI1182_REG_PS3_DATA0   0x2A
#define SI1182_REG_PS3_DATA1   0x2B
#define SI1182_REG_COMMAND     0x46

#define SI1182_CMD_RESET       0x01
#define SI1182_CMD_PS_FORCE    0x05

#define SI1182_PART_ID         0x82

#define SAMPLE_PERIOD_MS       100
#define CSV_FILENAME           "heartrate.csv"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- I2C helpers ---- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ---- Si1182 driver ---- */

static int si1182_init(int fd)
{
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1182_REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X) — wrong sensor?\n",
                part_id, SI1182_PART_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1182_REG_HW_KEY, 0x17) < 0)
        return -1;

    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE0, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE1, 0x00) < 0)
        return -1;

    if (i2c_write_reg8(fd, SI1182_REG_PS_LED21, 0x0F) < 0)
        return -1;

    if (i2c_write_reg8(fd, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0)
        return -1;
    usleep(10000);

    return 0;
}

static int si1182_read_proximity(int fd, uint16_t *prox)
{
    if (i2c_write_reg8(fd, SI1182_REG_COMMAND, SI1182_CMD_PS_FORCE) < 0)
        return -1;
    usleep(10000);
    return i2c_read_reg16(fd, SI1182_REG_PS1_DATA0, prox);
}

/* ---- Timestamp helper ---- */

static int get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    if (t == (time_t)-1)
        return -1;
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return -1;
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm) == 0)
        return -1;
    return 0;
}

/* ---- CSV logging ---- */

static int log_to_csv(FILE *fp, const char *ts, float bpm)
{
    if (fprintf(fp, "%s,%.2f\n", ts, bpm) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Main ---- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (si1182_init(fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Logging heart rate to %s (Ctrl+C to stop)...\n", CSV_FILENAME);

    while (g_running) {
        uint16_t prox;
        if (si1182_read_proximity(fd, &prox) < 0) {
            fprintf(stderr, "Proximity read failed; skipping sample.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        float bpm = (float)prox * 0.1f;

        char ts[32];
        if (get_timestamp(ts, sizeof(ts)) < 0) {
            fprintf(stderr, "Timestamp generation failed; skipping sample.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        if (log_to_csv(fp, ts, bpm) < 0) {
            fprintf(stderr, "CSV logging failed; aborting.\n");
            break;
        }

        printf("%s  Proximity: %u  BPM: %.2f\n", ts, prox, bpm);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

