/*
 * Raspberry Pi 4 Model B – TDK CH101 ultrasonic distance sensor
 * I2C bus 1, address 0x40
 *
 * Reads distance every 200 ms, samples every 50 ms after a trigger,
 * logs to distance_log.txt and prints to stdout.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch101_distance ch101_distance.c
 * Run:    ./ch101_distance
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x40

/* CH101 register addresses */
#define CH101_REG_TRIGGER   0x00
#define CH101_REG_DISTANCE  0x02

/* Trigger command: write 0x01 to the trigger register */
#define CH101_TRIGGER_CMD   0x01

/* Sampling delay after trigger (microseconds) */
#define TRIGGER_DELAY_US    50000

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US  200000

/* Log file name */
#define LOG_FILE_NAME       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Write a single byte to an 8-bit register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian value from an 8-bit register.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, sizeof(reg)) != (ssize_t)sizeof(reg)) {
        fprintf(stderr, "[I2C] write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */

/*
 * Trigger a measurement and read the distance in millimetres.
 * Returns 0 on success and stores the distance in *distance_mm,
 * -1 on any I2C error.
 */
static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    if (i2c_write_reg8(fd, CH101_REG_TRIGGER, CH101_TRIGGER_CMD) != 0)
        return -1;

    usleep(TRIGGER_DELAY_US);

    if (i2c_read_reg16(fd, CH101_REG_DISTANCE, distance_mm) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

/*
 * Format the current local time as "YYYY-MM-DD HH:MM:SS".
 * Returns 0 on success, -1 on error.
 */
static int format_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        fprintf(stderr, "[LOG] time() failed: %s\n", strerror(errno));
        return -1;
    }

    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "[LOG] localtime_r() failed\n");
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "[LOG] strftime() failed\n");
        return -1;
    }

    return 0;
}

/*
 * Append a timestamped distance reading to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    char ts[32];

    if (format_timestamp(ts, sizeof(ts)) != 0)
        return -1;

    if (fprintf(fp, "%s, %u\n", ts, distance_mm) < 0) {
        fprintf(stderr, "[LOG] fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[LOG] fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[MAIN] sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[MAIN] sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "[MAIN] open(%s) failed: %s\n",
                I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Acquire the CH101 slave address --- */
    if (ioctl(fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "[MAIN] ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "[MAIN] fopen(%s) failed: %s\n",
                LOG_FILE_NAME, strerror(errno));
        goto cleanup;
    }

    printf("CH101 distance logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (ch101_read_distance(fd, &distance_mm) == 0) {
            printf("Distance: %u mm\n", distance_mm);

            if (log_distance(fp, distance_mm) != 0) {
                fprintf(stderr, "[MAIN] Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "[MAIN] Sensor read error; skipping sample.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < 20 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL)
        fclose(fp);
    if (fd >= 0)
        close(fd);

    return rc;
}

