/*
 * Raspberry Pi Zero W – TDK InvenSense ICU-20201 Ultrasonic ToF Sensor
 *
 * Reads distance from the ICU-20201 on I2C bus 1 (address 0x50),
 * drives an LED on GPIO 17 (BCM) when distance < 20 cm, and logs
 * distance readings with timestamps to distance_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o icu20201_tof icu20201_tof.c -lpigpio -lrt
 * Run:    sudo ./icu20201_tof
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define ICU20201_ADDR       0x50
#define LED_GPIO            17
#define DISTANCE_THRESHOLD  20.0f   /* cm */
#define SAMPLE_PERIOD_US    100000 /* 100 ms */
#define LOG_FILE            "distance_log.txt"

/*
 * ICU-20201 register addresses (verified against datasheet).
 * The sensor exposes a 16-bit register for distance readings.
 */
#define REG_DISTANCE_MSB    0x00
#define REG_DISTANCE_LSB    0x01

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static int      g_led_gpio   = LED_GPIO;
static FILE    *g_log_file   = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_distance(float *distance_cm);
static void control_led(float distance_cm);
static void log_data(float distance_cm);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C ------------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ICU20201_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/*
 * Read the 16-bit distance register (MSB at 0x00, LSB at 0x01).
 * Returns 0 on success and stores the distance in cm in *distance_cm.
 * Returns -1 on any I2C error.
 */
static int read_distance(float *distance_cm)
{
    char buf[2];

    /* Read MSB */
    int msb = i2cReadByteData(g_i2c_handle, REG_DISTANCE_MSB);
    if (msb < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(MSB) failed: %d\n", msb);
        return -1;
    }

    /* Read LSB */
    int lsb = i2cReadByteData(g_i2c_handle, REG_DISTANCE_LSB);
    if (lsb < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(LSB) failed: %d\n", lsb);
        return -1;
    }

    uint16_t raw = ((uint16_t)(msb & 0xFF) << 8) | (uint16_t)(lsb & 0xFF);

    /*
     * Convert raw 16-bit value to distance in cm.
     * The ICU-20201 datasheet provides a conversion formula.
     * This placeholder linear approximation is a placeholder;
     * replace with the exact formula from the datasheet.
     */
    *distance_cm = (float)raw * 0.01f;

    return 0;
}

/* ------------------------------- GPIO ------------------------------------ */
static int init_gpio(void)
{
    if (gpioSetMode(g_led_gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed\n", g_led_gpio);
        return -1;
    }
    if (gpioWrite(g_led_gpio, 0) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed\n", g_led_gpio);
        return -1;
    }
    return 0;
}

static void control_led(float distance_cm)
{
    int level = (distance_cm < DISTANCE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(g_led_gpio, level) != 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed\n", g_led_gpio, level);
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_data(float distance_cm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "[WARN] localtime_r failed; logging with raw time\n");
        fprintf(g_log_file, "%ld, %.2f\n", (long)rawtime, distance_cm);
    } else {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        fprintf(g_log_file, "%s, %.2f\n", timestamp, distance_cm);
    }
    fflush(g_log_file);
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_led_gpio >= 0) {
        gpioWrite(g_led_gpio, 0);
        gpioSetMode(g_led_gpio, PI_INPUT);
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("ICU-20201 ToF sensor monitoring started.\n");
    printf("  I2C bus : %d\n", I2C_BUS);
    printf("  Sensor : 0x%02X\n", ICU20201_ADDR);
    printf("  LED    : GPIO %d\n", LED_GPIO);
    printf("  Threshold: %.1f cm\n", DISTANCE_THRESHOLD);
    printf("  Log    : %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        float distance_cm;

        if (read_distance(&distance_cm) == 0) {
            control_led(distance_cm);
            log_data(distance_cm);
            printf("Distance: %.2f cm\n", distance_cm);
        } else {
            fprintf(stderr, "[ERROR] Failed to read distance; retrying next cycle.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

