code:
/*
 * Si1182-GMR Proximity & Ambient Light Sensor Logger
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Silicon Labs Si1182-GMR
 *
 * Reads proximity (PS1) and ambient light (ALS1) every 500 ms,
 * logs timestamped samples to biometric_log.txt, and cleans up
 * on SIGINT (Ctrl+C).
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1182_logger si1182_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- Si1182-GMR I2C address ---- */
#define SI1182_ADDR 0x40

/* ---- Si1182 register addresses ---- */
#define SI1182_REG_PART_ID       0x00
#define SI1182_REG_HW_KEY        0x07
#define SI1182_REG_MEAS_RATE0    0x08
#define SI1182_REG_MEAS_RATE1    0x09
#define SI1182_REG_PS_LED21      0x0F
#define SI1182_REG_PS1_ADCMUX    0x10
#define SI1182_REG_ALS_VIS_ADCMUX 0x11
#define SI1182_REG_PS_ADC_GAIN   0x12
#define SI1182_REG_ALS_VIS_ADC_GAIN 0x13
#define SI1182_REG_PS_ADC_MISC   0x14
#define SI1182_REG_ALS_VIS_ADC_MISC 0x15
#define SI1182_REG_COMMAND       0x18
#define SI1182_REG_RESPONSE      0x20
#define SI1182_REG_IRQ_ENABLE    0x21
#define SI1182_REG_IRQ_MODE1     0x22
#define SI1182_REG_IRQ_MODE2     0x23
#define SI1182_REG_INT_CFG       0x24
#define SI1182_REG_IRQ_STATUS    0x25
#define SI1182_REG_ALS_VIS_DATA0 0x22
#define SI1182_REG_ALS_VIS_DATA1 0x23
#define SI1182_REG_PS1_DATA0     0x24
#define SI1182_REG_PS1_DATA1     0x25

/* ---- Si1182 command codes ---- */
#define SI1182_CMD_RESET         0x01
#define SI1182_CMD_PSALS_AUTO    0x0F
#define SI1182_CMD_PSALS_FORCE   0x0D

/* ---- Expected PART_ID ---- */
#define SI1182_PART_ID_EXPECTED  0x82

/* ---- Timing ---- */
#define SAMPLE_INTERVAL_US      500000  /* 500 ms */
#define MAX_RETRIES             3
#define LOG_FILE_NAME           "biometric_log.txt"

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1182 register; returns 0 on success, -1 on err */
/* ------------------------------------------------------------------ */
static int si1182_write_reg(uint8_t reg, uint8_t value)
{
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteByteData(g_i2c_handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s (attempt %d/%d)\n",
                reg, value, strerror(errno), attempt + 1, MAX_RETRIES);
        gpioDelay(10000);  /* 10 ms backoff */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1182 register; returns 0 on success, -1 on err */
/* ------------------------------------------------------------------ */
static int si1182_read_reg(uint8_t reg, uint8_t *out)
{
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadByteData(g_i2c_handle, reg);
        if (rc >= 0) {
            *out = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadByteData(reg=0x%02X) failed: %s (attempt %d/%d)\n",
                reg, strerror(errno), attempt + 1, MAX_RETRIES);
        gpioDelay(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair; returns 0 on success, -1  */
/* ------------------------------------------------------------------ */
static int si1182_read_reg16(uint8_t reg_lo, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1182_read_reg(reg_lo, &lo) != 0)
        return -1;
    if (si1182_read_reg(reg_lo + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1182 sensor                                        */
/* ------------------------------------------------------------------ */
static int si1182_init(void)
{
    uint8_t part_id;

    /* 1. Verify sensor presence via PART_ID */
    if (si1182_read_reg(SI1182_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID: 0x%02X (expected 0x%02X).\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }
    printf("[INFO] Si1182 detected (PART_ID=0x%02X).\n", part_id);

    /* 2. Software reset */
    if (si1182_write_reg(SI1182_REG_COMMAND, SI1182_CMD_RESET) != 0) {
        fprintf(stderr, "[ERROR] Software reset failed.\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms settle after reset */

    /* 3. Write HW_KEY (required after reset) */
    if (si1182_write_reg(SI1182_REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "[ERROR] Failed to write HW_KEY.\n");
        return -1;
    }

    /* 4. Configure measurement rate (0x00 = 0 Hz, manual mode) */
    if (si1182_write_reg(SI1182_REG_MEAS_RATE0, 0x00) != 0)
        return -1;
    if (si1182_write_reg(SI1182_REG_MEAS_RATE1, 0x00) != 0)
        return -1;

    /* 5. Configure PS LED current (LED21 = 0x0F) */
    if (si1182_write_reg(SI1182_REG_PS_LED21, 0x0F) != 0)
        return -1;

    /* 6. Configure PS1 ADC mux (large photodiode) */
    if (si1182_write_reg(SI1182_REG_PS1_ADCMUX, 0x03) != 0)
        return -1;

    /* 7. Configure ALS VIS ADC mux (large photodiode) */
    if (si1182_write_reg(SI1182_REG_ALS_VIS_ADCMUX, 0x03) != 0)
        return -1;

    /* 8. Configure PS ADC gain */
    if (si1182_write_reg(SI1182_REG_PS_ADC_GAIN, 0x00) != 0)
        return -1;

    /* 9. Configure ALS VIS ADC gain */
    if (si1182_write_reg(SI1182_REG_ALS_VIS_ADC_GAIN, 0x00) != 0)
        return -1;

    /* 10. Configure PS ADC misc */
    if (si1182_write_reg(SI1182_REG_PS_ADC_MISC, 0x00) != 0)
        return -1;

    /* 11. Configure ALS VIS ADC misc */
    if (si1182_write_reg(SI1182_REG_ALS_VIS_ADC_MISC, 0x00) != 0)
        return -1;

    /* 12. Clear any pending interrupts */
    if (si1182_write_reg(SI1182_REG_IRQ_STATUS, 0x0F) != 0)
        return -1;

    /* 13. Enable PS1 and ALS VIS interrupts */
    if (si1182_write_reg(SI1182_REG_IRQ_ENABLE, 0x03) != 0)
        return -1;

    /* 14. Set interrupt mode (active low, push-pull) */
    if (si1182_write_reg(SI1182_REG_IRQ_MODE1, 0x00) != 0)
        return -1;
    if (si1182_write_reg(SI1182_REG_IRQ_MODE2, 0x00) != 0)
        return -1;

    /* 15. Configure interrupt configuration */
    if (si1182_write_reg(SI1182_REG_INT_CFG, 0x00) != 0)
        return -1;

    /* 16. Start autonomous PS+ALS measurement */
    if (si1182_write_reg(SI1182_REG_COMMAND, SI1182_CMD_PSALS_AUTO) != 0) {
        fprintf(stderr, "[ERROR] Failed to start autonomous measurement.\n");
        return -1;
    }

    printf("[INFO] Si1182 initialized successfully.\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read proximity (PS1) and ambient light (ALS_VIS) data              */
/* ------------------------------------------------------------------ */
static int si1182_read_data(uint16_t *proximity, uint16_t *ambient_light)
{
    if (si1182_read_reg16(SI1182_REG_PS1_DATA0, proximity) != 0) {
        fprintf(stderr, "[ERROR] Failed to read PS1 data.\n");
        return -1;
    }
    if (si1182_read_reg16(SI1182_REG_ALS_VIS_DATA0, ambient_light) != 0) {
        fprintf(stderr, "[ERROR] Failed to read ALS_VIS data.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                        */
/* ------------------------------------------------------------------ */
static int log_data(uint16_t proximity, uint16_t ambient_light)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "[ERROR] strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, Proximity: %u, Ambient Light: %u\n",
                timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x40 */
    g_i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                SI1182_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1182_init() != 0) {
        fprintf(stderr, "[FATAL] Si1182 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }

    printf("[INFO] Logging to '%s' every 500 ms. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        uint16_t proximity, ambient_light;

        if (si1182_read_data(&proximity, &ambient_light) == 0) {
            if (log_data(proximity, ambient_light) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(10000);  /* 10 ms */
    }

    printf("\n[INFO] Shutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

