/* ------------------------------------------------------------------ */
/* Write one byte to a Si1182 register; returns 0 on success, -1 on err */
/* ------------------------------------------------------------------ */
static int si1182_write_reg(uint8_t reg, uint8_t value)
{
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteByteData(g_i2c_handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s (attempt %d/%d)\n",
                reg, value, strerror(errno), attempt + 1, MAX_RETRIES);
        gpioDelay(10000);  /* 10 ms backoff */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1182 register; returns 0 on success, -1 on err */
/* ------------------------------------------------------------------ */
static int si1182_read_reg(uint8_t reg, uint8_t *out)
{
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadByteData(g_i2c_handle, reg);
