/*
 * Raspberry Pi 4 Model B – TDK InvenSense ICU-20201 Ultrasonic ToF Sensor
 *
 * Reads distance continuously from the ICU-20201 on I2C bus 1 at a 50 ms
 * polling interval.  Lights an LED on GPIO 17 when the distance falls below
 * a configurable threshold.  Logs each reading with a timestamp to
 * tof_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tof_sensor tof_sensor.c -lpigpio -lrt
 * Run:    sudo ./tof_sensor [threshold_mm]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define I2C_ADDR            0x50          /* ICU-20201 default I2C address */
#define WHO_AM_I_REG        0x00          /* WHO_AM_I register            */
#define WHO_AM_I_VAL        0x20          /* Expected device ID           */
#define GPIO_LED            17            /* BCM pin for LED indicator     */
#define DEFAULT_THRESHOLD   100           /* mm                            */
#define LOG_FILE            "tof_log.txt"
#define POLL_DELAY_US       50000         /* 50 ms                         */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static int      g_threshold  = DEFAULT_THRESHOLD;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  initialize_i2c(void);
static int  read_distance(uint16_t *distance_mm);
static void control_led(int on);
static void log_data(uint16_t distance_mm);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C ------------------------------------- */
static int initialize_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }

    /* Verify sensor identity */
    int who = i2cReadByteData(g_i2c_handle, WHO_AM_I_REG);
    if (who < 0) {
        fprintf(stderr, "[ERROR] Failed to read WHO_AM_I register: %d\n", who);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr,
                "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    printf("[INFO] ICU-20201 detected (WHO_AM_I = 0x%02X).\n", who);
    return 0;
}

/*
 * Read a 16-bit distance value from the sensor.
 * Returns 0 on success and stores the distance in mm in *distance_mm.
 * Returns -1 on any I2C error.
 */
static int read_distance(uint16_t *distance_mm)
{
    /*
     * The ICU-20201 continuously updates a 16-bit distance register.
     * A simple read of two consecutive bytes returns the current value.
     */
    char buf[2];
    int  n = i2cReadDevice(g_i2c_handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 2)\n", n);
        return -1;
    }

    *distance_mm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
