{
    if (gpioWrite(GPIO_LED, on ? 1 : 0) < 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed\n", GPIO_LED, on);
    }
}

/* ------------------------------- Logging ---------------------------------- */
static void log_data(uint16_t distance_mm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %u mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    } else {
        fprintf(fp, "[timestamp error], Distance: %u mm\n", distance_mm);
    }

