    if (argc > 1) {
        g_threshold = atoi(argv[1]);
        if (g_threshold <= 0) {
            fprintf(stderr, "[WARN] Invalid threshold '%s'; using default %d mm\n",
                    argv[1], DEFAULT_THRESHOLD);
