    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction");
    }

    printf("[INFO] Polling ICU-20201 every %d ms. Press Ctrl+C to exit.\n",
           POLL_DELAY_US / 1000);

    /* Main polling loop */
    while (g_running) {
        uint16_t distance_mm = 0;

