/*
 * Raspberry Pi Zero W – Omron B5L-LD50-07050 3D TOF intrusion detector
 *
 * Wiring:
 *   B5L SDA  -> GPIO2  (pin 3,  I2C bus 1)
 *   B5L SCL  -> GPIO3  (pin 5,  I2C bus 1)
 *   B5L VDD  -> 3.3 V
 *   B5L GND  -> GND
 *
 * The B5L-LD50-07050 is a 3D TOF sensor that exposes a 15-byte response
 * over I2C after a 4-byte command frame is sent.  This program sends
 * the documented command frame, waits 10 ms, reads the response,
 * extracts the 16-bit big-endian distance from bytes 11 and 12,
 * samples the sensor 10 times per cycle, computes the average, and
 * logs intrusion events (distance < 1000 mm) to intrusion_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o intrusion intrusion.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_I2C_ADDR   0x50          /* B5L-LD50-07050 default I2C address */
#define LOG_FILE       "intrusion_log.txt"
#define DISTANCE_THRESHOLD_MM 1000
#define NUM_SAMPLES    10
#define SAMPLE_DELAY_MS 100
#define MEASURE_DELAY_MS 10

/*
 * B5L-LD50-07050 15-byte response frame (after a 4-byte command).
 *   Byte 0:  0x00  – header (expected)
 *   Byte 1:  0x00  – status / error code
 *   Bytes 2–3: 0x0000 – reserved
 *   Bytes 4–5: 0x0000 – reserved
 *   Bytes 6–7: 0x0000 – reserved
 *   Bytes 8–9: 0x0000 – reserved
 *   Bytes 10–11: 0x0000 – reserved
 *   Bytes 12–13: 16-bit big-endian distance (mm)
 *   Byte 14: 0x00  – reserved
 */
#define B5L_RESP_LEN   15
#define B5L_RESP_DIST_OFF 12
#define B5L_RESP_DIST_LEN 2
#define B5L_RESP_HDR   0x00

/*
 * B5L-LD50-07050 4-byte command frame.
 *   Byte 0:  0x01  – command code
 *   Byte 1:  0x00  – reserved
 *   Bytes 2–3: 0x0000 – reserved
 */
static const uint8_t B5L_CMD[4] = { 0x01, 0x00, 0x00, 0x00 };

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write the 4-byte command to the B5L.  Returns 0 on success, -1 on error. */
static int b5l_write_command(int fd)
{
    ssize_t n = write(fd, B5L_CMD, sizeof(B5L_CMD));
    if (n != (ssize_t)sizeof(B5L_CMD)) {
        fprintf(stderr, "write(command) failed: %s (wrote %zd bytes)\n",
                strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 15-byte response.  Returns 0 on success, -1 on error.      */
static int b5l_read_response(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "read(response) failed: %s (got %zd of %zu bytes)\n",
                strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Extract the 16-bit big-endian distance from the response.            */
static int b5l_extract_distance(const uint8_t *resp)
{
    if (resp[0] != B5L_RESP_HDR) {
        fprintf(stderr, "Unexpected response header 0x%02X (expected 0x%02X)\n",
                resp[0], B5L_RESP_HDR);
        return -1;
    }
    return (resp[B5L_RESP_DIST_OFF] << 8) | resp[B5L_RESP_DIST_OFF + 1];
}

/* ------------------------------------------------------------------ */
/* Sample the sensor `count` times and return the average distance.    */
static int b5l_sample_distance(int fd, int count)
{
    long sum = 0;
    int valid = 0;

    for (int i = 0; i < count; i++) {
        if (b5l_write_command(fd) != 0)
            return -1;

        usleep(MEASURE_DELAY_MS * 1000);

        uint8_t resp[B5L_RESP_LEN];
        if (b5l_read_response(fd, resp, sizeof(resp)) != 0)
            return -1;

        int dist = b5l_extract_distance(resp);
        if (dist < 0)
            return -1;

        sum += dist;
        valid++;
    }

    if (valid == 0)
        return -1;
    return (int)(sum / valid);
}

/* ------------------------------------------------------------------ */
static void log_intrusion(FILE *fp, int distance)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(fp, "%s, Intrusion detected! Distance: %d mm\n", ts, distance) < 0)
        fprintf(stderr, "fprintf(log) failed: %s\n", strerror(errno));
    else
        fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Acquire the B5L slave address --- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, B5L_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                B5L_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Intrusion detection started.  Logging to %s\n", LOG_FILE);
    printf("Threshold: %d mm  |  Samples: %d  |  Delay: %d ms\n",
           DISTANCE_THRESHOLD_MM, NUM_SAMPLES, SAMPLE_DELAY_MS);
    printf("Press Ctrl-C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int distance = b5l_sample_distance(g_i2c_fd, NUM_SAMPLES);

        if (distance < 0) {
            fprintf(stderr, "Sensor read error – continuing\n");
        } else if (distance < DISTANCE_THRESHOLD_MM) {
            log_intrusion(g_log_fp, distance);
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

