/*
 * Si1182 Proximity Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (pin 3)
 *   Si1182 SCL  -> GPIO3 (pin 5)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1182_prox si1182_prox.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./si1182_prox
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1182 I2C configuration ---- */
#define I2C_BUS        1
#define SI1182_ADDR    0x60          /* Si1182 default I2C address (ADDR pin tied to GND) */

/* ---- Si1182 register addresses ---- */
#define REG_PART_ID    0x00
#define REG_HW_KEY     0x07
#define REG_MEAS_RATE  0x08
#define REG_PS_LED21   0x0F
#define REG_PS1_DATA0  0x26
#define REG_PS1_DATA1  0x27

/* ---- Expected PART_ID for Si1182 ---- */
#define SI1182_PART_ID 0x82

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a Si1182 register                            */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int si1182_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a Si1182 register                           */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int si1182_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers    */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int si1182_read_reg16(int handle, uint8_t reg_low, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1182_read_reg(handle, reg_low, &lo) < 0)
        return -1;
    if (si1182_read_reg(handle, reg_low + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1182 sensor                                        */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int si1182_init(int handle)
{
    uint8_t part_id = 0;

    /*
     * Verify sensor presence by reading PART_ID.
     * A NACK on the initial write typically means the sensor is absent
     * or the bus is unresponsive.
     */
    if (si1182_read_reg(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "[ERROR] Si1182 not responding on I2C bus %d at addr 0x%02X.\n",
                I2C_BUS, SI1182_ADDR);
        return -1;
    }

    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID: 0x%02X (expected 0x%02X).\n",
                part_id, SI1182_PART_ID);
        return -1;
    }

    printf("[INFO] Si1182 detected (PART_ID = 0x%02X).\n", part_id);

    /*
     * Write HW_KEY to enable the device.
     * The exact value depends on the Si1182 variant; 0x17 is a safe
     * default for most variants.
     */
    if (si1182_write_reg(handle, REG_HW_KEY, 0x17) < 0)
        return -1;

    /*
     * Set measurement rate to 0x00 (manual mode).
     * The Si1182 will not start autonomous measurements until a PS_LED21
     * command is issued, but we keep the rate at 0 so the sensor is
     * ready to accept commands.
     */
    if (si1182_write_reg(handle, REG_MEAS_RATE, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read proximity data from the Si1182                                  */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int si1182_read_proximity(int handle, uint16_t *proximity)
{
    return si1182_read_reg16(handle, REG_PS1_DATA0, proximity);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to Si1182 */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1182_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1182_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si1182 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGINT)");
    }

    printf("[INFO] Reading proximity data every 500 ms. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t proximity = 0;

        if (si1182_read_proximity(g_i2c_handle, &proximity) == 0) {
            printf("Proximity: %u\n", proximity);
        } else {
            fprintf(stderr, "[WARN] Failed to read proximity data.\n");
        }

        /* Sleep 500 ms (microseconds) */
        gpioDelay(500000);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

