#include <linux/i2c-dev.h>

/* ---- OPT3101 register definitions (16-bit addresses, big-endian on bus) ---- */
#define OPT3101_I2C_ADDR        0x28
#define I2C_BUS                 "/dev/i2c-1"

#define REG_RESULT_DISTANCE     0x0000
#define REG_RESULT_AMBIENT      0x0002
#define REG_RESULT_FLAGS        0x0004
#define REG_SYSTEM_CONFIG       0x0006
#define REG_RANGE_CONFIG        0x0008
#define REG_AMBIENT_CONFIG      0x000A
#define REG_INT_CONFIG          0x000C
#define REG_GPIO_CONFIG         0x000E
#define REG_RANGE_START         0x0010
#define REG_RANGE_STATUS        0x0012
#define REG_INT_STATUS          0x0014
#define REG_GPIO_STATUS         0x0016
#define REG_DEVICE_ID           0x0018
#define REG_RESET               0x001A

#define EXPECTED_DEVICE_ID      0x3101

/* ---- Globals for signal-handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address (big-endian)                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg_addr(int fd, uint16_t reg)
{
    uint8_t buf[2] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF)
    };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg addr 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register                            */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4] = {
        (uint8_t)(reg >> 8),
        (uint8_t)(reg & 0xFF),
        (uint8_t)(value >> 8),
        (uint8_t)(value & 0xFF)
    };
    if (write(fd, buf, 4) != 4) {
        fprintf(stderr, "I2C write (reg 0x%04X, val 0x%04X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register                           */
/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    if (i2c_write_reg_addr(fd, reg) < 0)
        return -1;

    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read (reg 0x%04X) failed: got %zd bytes, %s\n",
                reg, n, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of 16-bit values starting at a 16-bit register          */
/* ------------------------------------------------------------------ */
static int i2c_read_block16(int fd, uint16_t reg, uint16_t *buf, size_t len)
{
    if (i2c_write_reg_addr(fd, reg) < 0)
        return -1;

    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, (uint8_t *)buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "I2C block read (reg 0x%04X) failed: %s\n",
                    reg, strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C block read (reg 0x%04X) unexpected EOF\n", reg);
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the OPT3101 sensor                                       */
/* ------------------------------------------------------------------ */
static int opt3101_init(int fd)
{
    uint16_t device_id = 0;
    if (i2c_read_reg16(fd, REG_DEVICE_ID, &device_id) < 0) {
        fprintf(stderr, "Cannot read DEVICE_ID — sensor absent or bus error\n");
        return -1;
    }
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected DEVICE_ID: 0x%04X (expected 0x%04X)\n",
                device_id, EXPECTED_DEVICE_ID);
        return -1;
    }
    printf("OPT3101 detected (DEVICE_ID = 0x%04X)\n", device_id);

    /* Software reset */
    if (i2c_write_reg16(fd, REG_RESET, 0x0001) < 0)
        return -1;
    usleep(10000); /* 10 ms settle after reset */

    /* Configure range: channel 0 enabled, range 0 (400 mm) */
    if (i2c_write_reg16(fd, REG_RANGE_CONFIG, 0x0001) < 0)
        return -1;

    /* Configure ambient light: channel 0 enabled, 10-bit resolution */
    if (i2c_write_reg16(fd, REG_AMBIENT_CONFIG, 0x0001) < 0)
        return -1;

    /* Clear any pending interrupts */
    if (i2c_write_reg16(fd, REG_INT_STATUS, 0x0000) < 0)
        return -1;

    /* Start a single-shot range measurement */
    if (i2c_write_reg16(fd, REG_RANGE_START, 0x0001) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the OPT3101                                    */
/* ------------------------------------------------------------------ */
static int opt3101_read_sample(int fd, uint16_t *distance, uint16_t *ambient,
                              uint16_t *flags)
{
    uint16_t status = 0;
    if (i2c_read_reg16(fd, REG_RANGE_STATUS, &status) < 0)
        return -1;

    if ((status & 0x0001) == 0) {
        /* Measurement not ready yet — not an error, just no data */
        return 1;
    }

    uint16_t vals[3];
    if (i2c_read_block16(fd, REG_RESULT_DISTANCE, vals, sizeof(vals)) < 0)
        return -1;

    *distance = vals[0];
    *ambient  = vals[1];
    *flags    = vals[2];

    /* Clear the data-ready bit so the next measurement can be started */
    if (i2c_write_reg16(fd, REG_RANGE_STATUS, 0x0000) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Print a timestamped log line                                        */
/* ------------------------------------------------------------------ */
static void log_data(uint16_t distance, uint16_t ambient, uint16_t flags)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    printf("[%s] Distance: %u mm, Ambient: %u, Flags: 0x%04X\n",
           ts, distance, ambient, flags);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the OPT3101 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3101_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                OPT3101_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (opt3101_init(g_i2c_fd) < 0) {
        fprintf(stderr, "OPT3101 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting OPT3101 readings every 500 ms. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t distance = 0, ambient = 0, flags = 0;
        int rc = opt3101_read_sample(g_i2c_fd, &distance, &ambient, &flags);

        if (rc == 0) {
            log_data(distance, ambient, flags);
        } else if (rc < 0) {
            fprintf(stderr, "Read error — continuing\n");
        }
        /* rc == 1 means no data ready yet, just wait */

        usleep(500000); /* 500 ms */
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

