/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 18 (BCM) via 1 kOhm resistor to GND
 *   HC-SR04 VCC -> 5 V (external supply recommended; 3.3 V Pi is not 5 V tolerant)
 *   HC-SR04 GND -> GND
 *
 * The HC-SR04 operates at 5 V and the Pi GPIO is only 3.3 V tolerant.
 * A 1 kOhm resistor is required on the echo line within the library API
 * call() that provides microsecond precision.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse */
#define ECHO_TIMEOUT_US  200000      /* 200 ms max echo wait */
#define LOOP_DELAY_US    1000000     /* 1 second between readings */
#define MAX_DISTANCE_CM  400.0f      /* HC-SR04 rated maximum range */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in cm using the HC-SR04.                              */
/* Returns distance on success, or -1.0 on error.                      */
/* ------------------------------------------------------------------ */
static float read_distance(void)
{
    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t timeout;

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger LOW\n");
        return -1.0f;
    }
    gpioDelay(5);  /* let line settle */

    /* 10 us trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout if no object detected) */
    timeout = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout) >= 0) {
            fprintf(stderr, "Error: echo rising edge timeout (no object detected)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout if no echo received) */
    timeout = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout) >= 0) {
            fprintf(stderr, "Error: echo falling edge timeout (sensor absent or stuck)\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;

    /* Sanity check: HC-SR04 max range is ~400 cm; 343 m/s round trip => 29 us/cm */
    if (pulse_us <= 0 || pulse_us > 38000) {
        fprintf(stderr, "Error: invalid pulse duration %u us\n", pulse_us);
        return -1.0f;
    }

    /* distance = (pulse_us * 34300) / (2 * 1000000) */
    return (float)pulse_us * 0.01715f;
}

/* ------------------------------------------------------------------ */
/* Print distance with timestamp.                                     */
/* ------------------------------------------------------------------ */
static void print_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(100000);  /* 100 ms settle */

    printf("HC-SR04 distance sensor started. Press Ctrl+C to exit.\n");
    fflush(stdout);

