#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <gpiod.h>

#define UART_DEVICE        "/dev/serial0"
#define BAUD_RATE          B115200
#define MAGIC_WORD_SIZE    8
#define RANGE_PROFILE_SIZE 128
#define NUM_RANGE_BINS     64
#define TARGET_THRESHOLD   1.0f
#define ALERT_LED_GPIO     17
#define ALERT_LED_CONSUMER "intrusion_alert"
#define LOG_FILE           "intrusion_log.csv"
#define POLL_TIMEOUT_SEC   1
#define POLL_TIMEOUT_USEC  0

static volatile sig_atomic_t program_running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static const uint8_t magic_word[MAGIC_WORD_SIZE] = {
    0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07
};

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, ALERT_LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", ALERT_LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(led_line, ALERT_LED_CONSUMER, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", ALERT_LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int find_magic_word(const uint8_t *buf, size_t len) {
    for (size_t i = 0; i <= len - MAGIC_WORD_SIZE; i++) {
        if (memcmp(buf + i, magic_word, MAGIC_WORD_SIZE) == 0) {
            return (int)i;
        }
    }
    return -1;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        struct timeval tv;
        tv.tv_sec = POLL_TIMEOUT_SEC;
        tv.tv_usec = POLL_TIMEOUT_USEC;

        int retval = select(fd + 1, &readfds, NULL, NULL, &tv);
        if (retval < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error in select(): %s\n", strerror(errno));
            return -1;
        }
        if (retval == 0) {
            fprintf(stderr, "Timeout waiting for data\n");
            return -1;
        }

        ssize_t bytes_read = read(fd, buf + total, len - total);
        if (bytes_read < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        if (bytes_read == 0) {
            fprintf(stderr, "UART closed unexpectedly\n");
            return -1;
        }
        total += (size_t)bytes_read;
    }
    return 0;
}

static int decode_range_profile(const uint8_t *data, float *distances, int num_bins) {
    if (num_bins <= 0 || num_bins > 256) {
        fprintf(stderr, "Invalid number of bins: %d\n", num_bins);
        return -1;
    }
    if (data == NULL || distances == NULL) {
        fprintf(stderr, "Null pointer argument\n");
        return -1;
    }

    for (int i = 0; i < num_bins; i++) {
        uint16_t raw = (uint16_t)((data[2 * i] << 8) | data[2 * i + 1]);
        distances[i] = (float)raw * 0.043f;
    }
    return 0;
}

static int check_target_threshold(const float *distances, int num_bins, float threshold) {
    for (int i = 0; i < num_bins; i++) {
        if (distances[i] > 0.0f && distances[i] <= threshold) {
            return 1;
        }
    }
    return 0;
}

static int log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void trigger_alert(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 1);
        sleep(2);
        gpiod_line_set_value(led_line, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t *frame_buf = malloc(MAGIC_WORD_SIZE + RANGE_PROFILE_SIZE);
    if (frame_buf == NULL) {
        fprintf(stderr, "Error allocating memory for frame buffer\n");
        cleanup();
        return 1;
    }

    float *distances = malloc(NUM_RANGE_BINS * sizeof(float));
    if (distances == NULL) {
        fprintf(stderr, "Error allocating memory for distances\n");
        free(frame_buf);
        cleanup();
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int magic_pos = find_magic_word(frame_buf, MAGIC_WORD_SIZE);
        if (magic_pos < 0) {
            uint8_t discard;
            if (read_exact(uart_fd, &discard, 1) < 0) {
                break;
            }
            continue;
        }

        if (magic_pos > 0) {
            memmove(frame_buf, frame_buf + magic_pos, MAGIC_WORD_SIZE);
        }

        if (read_exact(uart_fd, frame_buf + MAGIC_WORD_SIZE, RANGE_PROFILE_SIZE) < 0) {
            break;
        }

        if (decode_range_profile(frame_buf + MAGIC_WORD_SIZE, distances, NUM_RANGE_BINS) < 0) {
            continue;
        }

        if (check_target_threshold(distances, NUM_RANGE_BINS, TARGET_THRESHOLD)) {
            printf("Target detected!\n");
            if (log_intrusion(TARGET_THRESHOLD) < 0) {
                fprintf(stderr, "Error logging intrusion\n");
            }
            trigger_alert();
        }
    }

    free(frame_buf);
    free(distances);
    cleanup();
    printf("Intrusion detection system stopped.\n");
    return 0;
}

