    if (uart_fd < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t *frame_buf = malloc(MAGIC_WORD_SIZE + RANGE_PROFILE_SIZE);
    if (frame_buf == NULL) {
        fprintf(stderr, "Error allocating memory for frame buffer\n");
        cleanup();
        return 1;
    }

    float *distances = malloc(NUM_RANGE_BINS * sizeof(float));
    if (distances == NULL) {
        fprintf(stderr, "Error allocating memory for distances\n");
        free(frame_buf);
        cleanup();
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int magic_pos = find_magic_word(frame_buf, MAGIC_WORD_SIZE);
        if (magic_pos < 0) {
            uint8_t discard;
            if (read_exact(uart_fd, &discard, 1) < 0) {
                break;
            }
            continue;
        }

        if (magic_pos > 0) {
            memmove(frame_buf, frame_buf + magic_pos, MAGIC_WORD_SIZE);
        }

        if (read_exact(uart_fd, frame_buf + MAGIC_WORD_SIZE, RANGE_PROFILE_SIZE) < 0) {
            break;
        }

        if (decode_range_profile(frame_buf + MAGIC_WORD_SIZE, distances, NUM_RANGE_BINS) < 0) {
            continue;
        }

        if (check_target_threshold(distances, NUM_RANGE_BINS, TARGET_THRESHOLD)) {
            printf("Target detected!\n");
            if (log_intrusion(TARGET_THRESHOLD) < 0) {
                fprintf(stderr, "Error logging intrusion\n");
            }
            trigger_alert();
        }
    }

    free(frame_buf);
    free(distances);
    cleanup();
    printf("Intrusion detection system stopped.\n");
    return 0;
}

