/*
 * obstacle_buzzer.c — Raspberry Pi 4 Model B
 *
 * Reads an E18-D80NK IR obstacle sensor on GPIO 17 (active-low: 0 = obstacle, 1 = clear)
 * and drives a buzzer on GPIO 18 (active-high).  Logs state transitions to
 * obstacle_log.txt every 100 ms.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_buzzer obstacle_buzzer.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_PIN  17
#define BUZZER_PIN  18
#define LOG_FILE    "obstacle_log.txt"
#define POLL_MS     100

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int log_transition(FILE *fp, int obstacle)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s - Obstacle: %s\n", ts, obstacle ? "YES" : "NO") < 0) {
        perror("fprintf()");
        return -1;
    }

    if (fflush(fp) == EOF) {
        perror("fflush()");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor = NULL;
    struct gpiod_line *buzzer = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        /* Fallback: try the first chip */
        chip = gpiod_chip_open_by_number(0);
    }
    if (chip == NULL) {
        perror("gpiod_chip_open");
        goto cleanup;
    }

    sensor = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (sensor == NULL) {
        perror("gpiod_chip_get_line(sensor)");
        goto cleanup;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (buzzer == NULL) {
        perror("gpiod_chip_get_line(buzzer)");
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor, "obstacle_sensor") < 0) {
        perror("gpiod_line_request_input(sensor)");
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output(buzzer)");
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    printf("Obstacle detection started.  Sensor=GPIO%d  Buzzer=GPIO%d  Log=%s\n",
           SENSOR_PIN, BUZZER_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    int prev_obstacle = -1;  /* force initial log */

    while (g_running) {
        int val = gpiod_line_get_value(sensor);
        if (val < 0) {
            perror("gpiod_line_get_value(sensor)");
            break;
        }

        int obstacle = (val == 0);  /* E18-D80NK is active-low */

        if (gpiod_line_set_value(buzzer, obstacle ? 1 : 0) < 0) {
            perror("gpiod_line_set_value(buzzer)");
            break;
        }

        if (obstacle != prev_obstacle) {
            if (log_transition(log_fp, obstacle) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
            prev_obstacle = obstacle;
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer != NULL) {
        gpiod_line_set_value(buzzer, 0);
        gpiod_line_release(buzzer);
    }
    if (sensor != NULL)
        gpiod_line_release(sensor);
    if (chip != NULL)
        gpiod_chip_close(chip);
    if (log_fp != NULL)
        fclose(log_fp);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");

    return ret;
}

