/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 ultrasonic distance monitor
 *
 * Wiring:
 *   ICU-20201 SDA  -> GPIO 2 (I2C bus 1 SDA, pin 3)
 *   ICU-20201 SCL  -> GPIO 3 (I2C bus 1 SCL, pin 5)
 *   ICU-20201 VDD  -> 3.3 V (pin 1)
 *   ICU-20201 GND  -> GND  (pin 6)
 *   Alert LED/buzzer -> GPIO 17 (BCM 17, pin 11) via suitable driver
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o distance_monitor distance_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./distance_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define I2C_ADDR            0x40          /* ICU-20201 default I2C address */
#define ALERT_GPIO          17            /* BCM 17 – physical pin 11 */
#define DISTANCE_THRESHOLD  10.0f         /* cm – alert below this */
#define LOG_FILE            "distance_log.txt"
#define SAMPLE_PERIOD_US    100000        /* 100 ms */

/*
 * ICU-20201 register map (example – adjust per datasheet).
 * The sensor returns a 16-bit distance value in mm.
 */
#define REG_DISTANCE_MM     0x00
#define REG_STATUS          0x01
#define STATUS_READY        0x01          /* bit 0: new measurement ready */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_distance_mm(uint16_t *distance_mm);
static float mm_to_cm(uint16_t mm);
static int  log_distance(float distance_cm);
static void cleanup(void);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C init --------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }

    /*
     * Probe the sensor by reading the status register.
     * If the sensor is absent or the bus is unresponsive, this will fail.
     */
    int status = i2cReadByteData(g_i2c_handle, REG_STATUS);
    if (status < 0) {
        fprintf(stderr, "[ERROR] Sensor not responding at 0x%02X: %s\n",
                I2C_ADDR, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    printf("[INFO] I2C bus %d opened, sensor at 0x%02X (status=0x%02X)\n",
           I2C_BUS, I2C_ADDR, status);
    return 0;
}

/* ------------------------------- GPIO init -------------------------------- */
static int init_gpio(void)
{
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed\n", ALERT_GPIO);
        return -1;
    }
    if (gpioWrite(ALERT_GPIO, 0) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed\n", ALERT_GPIO);
        return -1;
    }
    printf("[INFO] GPIO %d configured as output (alert LED)\n", ALERT_GPIO);
    return 0;
}

/* --------------------------- Read distance (mm) -------------------------- */
static int read_distance_mm(uint16_t *distance_mm)
{
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] I2C handle invalid\n");
        return -1;
    }

    /*
     * Read the 16-bit distance register.
     * i2cReadWordData returns the byte-swapped value from the sensor.
     */
    int raw = i2cReadWordData(g_i2c_handle, REG_DISTANCE_MM);
    if (raw < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %s\n",
                REG_DISTANCE_MM, strerror(errno));
        return -1;
    }

    *distance_mm = (uint16_t)raw;
    return 0;
}

/* --------------------------- Convert mm → cm ----------------------------- */
static float mm_to_cm(uint16_t mm)
{
    return (float)mm / 10.0f;
}

/* ------------------------------- Log data -------------------------------- */
static int log_distance(float distance_cm)
{
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] Log file not open\n");
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, %.2f cm\n", ts, distance_cm) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
        /* non-fatal */
    }

    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    printf("\n[INFO] Cleaning up...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        printf("[INFO] I2C handle closed\n");
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
        printf("[INFO] Log file closed\n");
    }

    /* Ensure alert LED is off */
    if (gpioInitialise() >= 0) {
        gpioWrite(ALERT_GPIO, 0);
        gpioTerminate();
    }
    printf("[INFO] GPIO terminated\n");
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- Initialize I2C --- */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize GPIO --- */
    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    printf("[INFO] Logging to %s\n", LOG_FILE);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("[INFO] Monitoring distance every %d ms. Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_US / 1000);

    /* --- Main loop --- */
    while (g_running) {
        uint16_t raw;
        if (read_distance_mm(&raw) != 0) {
            /* I2C error – keep running but skip this sample */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float distance_cm = mm_to_cm(raw);

        if (log_distance(distance_cm) != 0) {
            /* Logging failed – non-fatal, continue monitoring */
        }

        if (distance_cm < DISTANCE_THRESHOLD) {
            printf("[ALERT] Distance %.2f cm below threshold %.1f cm – alert ON\n",
                   distance_cm, DISTANCE_THRESHOLD);
            if (gpioWrite(ALERT_GPIO, 1) < 0) {
                fprintf(stderr, "[WARN] gpioWrite(%d, 1) failed\n", ALERT_GPIO);
            }
        } else {
            if (gpioWrite(ALERT_GPIO, 0) < 0) {
                fprintf(stderr, "[WARN] gpioWrite(%d, 0) failed\n", ALERT_GPIO);
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown --- */
    cleanup();
    return EXIT_SUCCESS;
}

