/*
 * Parking Assistance System using VL53L1X Time-of-Flight sensor
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: STMicroelectronics VL53L1X at address 0x29
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c -lvl53l1x
 * Run:    ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <vl53l1x_api.h>

#define I2C_BUS             1
#define VL53L1X_ADDR        0x29
#define LOG_FILE            "distance_log.csv"
#define POLL_INTERVAL_US    100000   /* 100 ms */

/* Distance thresholds (mm) */
#define STOP_DISTANCE_MM    300
#define APPROACH_DISTANCE_MM 600
#define SLOW_DISTANCE_MM    1200

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int ensure_log_header(FILE *fp)
{
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "timestamp,distance_mm\n") < 0) {
            fprintf(stderr, "Failed to write header: %s\n", strerror(errno));
            return -1;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Parking guidance                                                    */
/* ------------------------------------------------------------------ */
static void print_parking_guidance(uint16_t distance_mm)
{
    if (distance_mm < STOP_DISTANCE_MM) {
        printf("Parking Guidance: STOP\n");
    } else if (distance_mm < APPROACH_DISTANCE_MM) {
        printf("Parking Guidance: APPROACH\n");
    } else if (distance_mm < SLOW_DISTANCE_MM) {
        printf("Parking Guidance: SLOW\n");
    } else {
        printf("Parking Guidance: CLEAR\n");
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int i2c_handle = -1;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Open I2C bus ---- */
    i2c_handle = vl53l1x_i2c_init(I2C_BUS, VL53L1X_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "vl53l1x_i2c_init failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        goto cleanup;
    }

    /* ---- Open log file ---- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    if (ensure_log_header(log_fp) != 0) {
        goto cleanup;
    }

    printf("Parking Assistance System started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main polling loop ---- */
    while (g_running) {
        uint16_t distance_mm = 0;
        int rc;

        /*
         * Read one measurement.  vl53l1x_get_distance_mm returns 0 on
         * success and stores the distance in *distance_mm.
         */
        rc = vl53l1x_get_distance_mm(i2c_handle, &distance_mm);
        if (rc != 0) {
            fprintf(stderr, "vl53l1x_get_distance_mm failed: %d\n", rc);
            /* Brief back-off before retrying to avoid log flooding */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (log_distance(log_fp, distance_mm) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        print_parking_guidance(distance_mm);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
        }
        log_fp = NULL;
    }
    if (i2c_handle >= 0) {
        vl53l1x_i2c_close(i2c_handle);
        i2c_handle = -1;
    }
    return ret;
}

