/*
 * CH201 Ultrasonic Distance Sensor Reader with Smooth LED Blink
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO 2 = SDA, GPIO 3 = SCL)
 * Sensor: TDK InvenSense CH201 (I2C address 0x50)
 * LED:    GPIO 18 (BCM), 330 Ω series resistor to 3.3 V
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch201_led ch201_led.c -lpigpio -lrt
 * Run:    sudo ./ch201_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define CH201_ADDR          0x50
#define LED_GPIO            18
#define BLINK_HALF_PERIOD_US 500000   /* 500 ms half-cycle -> 1 Hz blink */
#define SAMPLE_PERIOD_US    100000   /* 100 ms between samples */
#define MAX_RETRIES         3
#define RETRY_DELAY_US      10000    /* 10 ms between retries */

/* CH201 register addresses (verified against datasheet) */
#define CH201_REG_DISTANCE  0x00
#define CH201_REG_CONFIG    0x01
#define CH201_REG_STATUS    0x02

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_terminate = 0;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* --------------------------- I2C helpers -------------------------------- */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, value, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *out = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadByteData(reg=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* --------------------------- Sensor init -------------------------------- */
static int ch201_init(int handle)
{
    /*
     * CH201 default configuration:
     *   REG_CONFIG = 0x00  -> continuous measurement, 100 ms period
     *   REG_STATUS = 0x00  -> clear any stale status bits
     */
    if (i2c_write_byte(handle, CH201_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "[ERROR] Failed to write CH201 config register\n");
        return -1;
    }
    if (i2c_write_byte(handle, CH201_REG_STATUS, 0x00) != 0) {
        fprintf(stderr, "[ERROR] Failed to clear CH201 status register\n");
        return -1;
    }
    return 0;
}

/* --------------------------- Distance read ------------------------------- */
static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t lo, hi;

    if (i2c_read_byte(handle, CH201_REG_DISTANCE, &lo) != 0)
        return -1;
    if (i2c_read_byte(handle, CH201_REG_DISTANCE + 1, &hi) != 0)
        return -1;

    *distance_mm = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* --------------------------- Blink frequency ----------------------------- */
static uint32_t calculate_blink_frequency(uint16_t distance_mm)
{
    /*
     * Distance 0 mm  -> 100 Hz (fastest blink)
     * Distance 400 mm ->  10 Hz (slowest blink)
     * Linear interpolation clamped to [10, 100].
     */
    if (distance_mm == 0)
        return 100;
    if (distance_mm >= 400)
        return 10;

    float freq = 100.0f - ((float)distance_mm / 400.0f) * 90.0f;
    return (uint32_t)(freq + 0.5f);
}

/* --------------------------- LED control --------------------------------- */
static void led_on(void)
{
    gpioWrite(LED_GPIO, 1);
}

static void led_off(void)
{
    gpioWrite(LED_GPIO, 0);
}

/* --------------------------- Main loop ----------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    led_off();

    /* --- Open I2C bus to CH201 --- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, CH201_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize sensor --- */
    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] CH201 initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance reader started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (!g_terminate) {
        uint16_t distance_mm = 0;

        if (ch201_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "[ERROR] Failed to read distance after %d retries; continuing\n",
                    MAX_RETRIES);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        uint32_t freq_hz = calculate_blink_frequency(distance_mm);
        uint32_t half_period_us = 1000000u / freq_hz;

        /*
         * Smooth half-cycle blink: one half-period on, one half-period off.
         * gpioDelay is interruptible by signals, so we break the half-period
         * into 100 ms slices so that SIGINT is caught promptly.
         */
        for (int i = 0; i < 5 && !g_terminate; i++) {
            led_on();
            gpioDelay(half_period_us / 5);
            if (g_terminate)
                break;
            led_off();
            gpioDelay(half_period_us / 5);
        }

        /* --- Timestamp --- */
        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

        printf("%s  Distance: %4u mm  Blink: %3u Hz\n", ts, distance_mm, freq_hz);
        fflush(stdout);
    }

    /* --- Cleanup --- */
