#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_US 50000   /* 50 ms in microseconds */
#define POLL_INTERVAL_US 10000    /* 10 ms in microseconds */
#define LOG_FILE_NAME "proximity_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown (SIGINT, SIGTERM) */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Get current UTC time as an ISO 8601 string; returns 0 on success, -1 on error */
static int get_iso8601_timestamp(char *buf, size_t buf_size) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }

    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }

    if (strftime(buf, buf_size, "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        return -1;
    }

    return 0;
}

/* Log a state transition to the log file; returns 0 on success, -1 on error */
static int log_state_transition(int sensor_id, const char *event_type) {
    char timestamp[32];

    if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
        fprintf(stderr, "Error: Failed to generate timestamp: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(log_file, "%s - Sensor %d - %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Read a sensor value with error checking; returns 0 or 1 on success, -1 on error */
static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

/* Initialize pigpio and configure GPIO pins; returns 0 on success, -1 on error */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down resistors to ensure defined state when sensor is disconnected */
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int sensor1_state = 0;
    int sensor2_state = 0;
    int last_sensor1_state = 0;
    int last_sensor2_state = 0;
    int first_read = 1;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity detection started. Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE_NAME);

    /* Main polling loop */
    while (program_running) {
        sensor1_state = read_sensor(SENSOR_1_GPIO);
        sensor2_state = read_sensor(SENSOR_2_GPIO);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error: Sensor read failure, exiting.\n");
            break;
        }

        /* Debounce sensor 1 */
        if (sensor1_state != last_sensor1_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            sensor1_state = read_sensor(SENSOR_1_GPIO);
            if (sensor1_state < 0) {
                fprintf(stderr, "Error: Sensor 1 read failure during debounce, exiting.\n");
                break;
            }
        }

        /* Debounce sensor 2 */
        if (sensor2_state != last_sensor2_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            sensor2_state = read_sensor(SENSOR_2_GPIO);
            if (sensor2_state < 0) {
                fprintf(stderr, "Error: Sensor 2 read failure during debounce, exiting.\n");
                break;
            }
