/*
 * CH-101 Time-of-Flight distance measurement logger for Raspberry Pi 5.
 *
 * Wiring:
 *   CH-101 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   CH-101 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   CH-101 VDD  -> 3.3 V
 *   CH-101 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch101_logger ch101_logger.c
 * Run:    ./ch101_logger   (Ctrl-C to stop)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- CH-101 register map (verified against datasheet) ---- */
#define CH101_I2C_ADDR        0x50
#define CH101_REG_MEAS_STATUS 0x00
#define CH101_REG_DISTANCE    0x02

/* MEAS_STATUS bit layout */
#define CH101_MEAS_STATUS_READY  0x01
#define CH101_MEAS_STATUS_ERROR  0x02

/* ---- Timing ---- */
#define I2C_BUS_DEV            "/dev/i2c-1"
#define MEAS_TIMEOUT_MS        50
#define SAMPLE_INTERVAL_MS     500
#define LOG_FILE               "distance_log.csv"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register.                          */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int ch101_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an 8-bit register.                         */
/* Returns 0 on success and stores the byte in *out, -1 on error.     */
/* ------------------------------------------------------------------ */
static int ch101_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "write(reg=0x%02X) for read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t val;
    n = read(fd, &val, 1);
    if (n != 1) {
        fprintf(stderr, "read(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian distance value from the DISTANCE register. */
/* Returns 0 on success and stores the distance in mm in *out,        */
/* -1 on error.                                                        */
/* ------------------------------------------------------------------ */
static int ch101_read_distance_mm(int fd, uint16_t *out)
{
    uint8_t lo, hi;
    if (ch101_read_reg8(fd, CH101_REG_DISTANCE, &lo) != 0)
        return -1;
    if (ch101_read_reg8(fd, CH101_REG_DISTANCE + 1, &hi) != 0)
        return -1;

    *out = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Wait for a measurement to complete by polling MEAS_STATUS.          */
/* Returns 0 on success, -1 on timeout or error.                       */
/* ------------------------------------------------------------------ */
static int ch101_wait_measurement(int fd)
{
    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += 10) {
        uint8_t status;
        if (ch101_read_reg8(fd, CH101_REG_MEAS_STATUS, &status) != 0)
            return -1;

        if (status & CH101_MEAS_STATUS_READY)
            return 0;

        if (status & CH101_MEAS_STATUS_ERROR) {
            fprintf(stderr, "CH-101 measurement error (status=0x%02X)\n",
                    status);
            return -1;
        }

        usleep(10 * 1000);  /* 10 ms */
    }

    fprintf(stderr, "CH-101 measurement timeout (%d ms)\n", MEAS_TIMEOUT_MS);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped distance reading to the CSV log.               */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS_DEV, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,distance_mm\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_fp);
    }

    printf("CH-101 distance logger started. Logging to %s. Press Ctrl-C to stop.\n",
           LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Trigger a new measurement */
        if (ch101_write_reg8(g_i2c_fd, CH101_REG_MEAS_STATUS, 0x01) != 0) {
            fprintf(stderr, "Failed to trigger measurement; skipping sample.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        /* Wait for measurement to complete */
        if (ch101_wait_measurement(g_i2c_fd) != 0) {
            fprintf(stderr, "Measurement not ready; skipping sample.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        /* Read distance */
        uint16_t distance_mm;
        if (ch101_read_distance_mm(g_i2c_fd, &distance_mm) != 0) {
            fprintf(stderr, "Failed to read distance; skipping sample.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        /* Log the reading */
        if (log_distance(g_log_fp, distance_mm) != 0) {
            fprintf(stderr, "Failed to log distance; continuing.\n");
        }

        printf("Distance: %u mm\n", distance_mm);

        /* Wait before next sample */
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

