#include <string.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50
#define SAMPLE_PERIOD  100000   /* microseconds (100 ms) */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000    /* 10 ms */

/*
 * MLX75030 register map (16-bit addresses, big-endian on the bus).
 * The sensor exposes a 16-bit distance register at 0x0000 and a 16-bit
 * status register at 0x0002.  A read of the distance register returns
 * the current distance in mm; a read of the status register returns
 * a 16-bit status word.
 */
#define REG_DISTANCE   0x0000
#define REG_STATUS     0x0002

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit register address to the sensor (big-endian on the bus).
 * Returns 0 on success, -1 on failure.
 */
static int sensor_write_reg_addr(int handle, uint16_t reg)
{
    char buf[2];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 2);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: i2cWriteDevice (reg addr 0x%04X) failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read a 16-bit value from a 16-bit-addressed sensor register.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int sensor_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char buf[2];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (sensor_write_reg_addr(handle, reg) != 0)
            continue;

        int rc = i2cReadDevice(handle, buf, 2);
        if (rc == 2) {
            *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "Warning: i2cReadDevice (reg 0x%04X) failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read the distance register and return the distance in mm.
 * Returns 0 on success and stores the distance in *distance;
 * -1 on persistent failure.
 */
static int read_distance(int handle, uint16_t *distance)
{
    return sensor_read_reg16(handle, REG_DISTANCE, distance);
}

/*
 * Read the status register and return the 16-bit status word.
 * Returns 0 on success and stores the status in *status;
 * -1 on persistent failure.
 */
static int read_status(int handle, uint16_t *status)
{
    return sensor_read_reg16(handle, REG_STATUS, status);
}

/*
 * Print a timestamped distance reading to stdout.
 */
static void print_reading(uint16_t distance)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("[%s.%03ld] Distance: %u mm\n", time_buf, ts.tv_nsec / 1000000, distance);
    fflush(stdout);
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to the MLX75030 */
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX75030 distance sensor reader started.\n");
    printf("I2C bus: %d, address: 0x%02X, sample period: %d ms\n",
           I2C_BUS, I2C_ADDR, SAMPLE_PERIOD / 1000);
    printf("Press Ctrl+C to exit.\n\n");
    fflush(stdout);

    int exit_code = EXIT_SUCCESS;

    while (g_running) {
        uint16_t distance = 0;
        uint16_t status   = 0;

        if (read_distance(i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error: Failed to read distance after %d retries.\n", MAX_RETRIES);
            exit_code = EXIT_FAILURE;
            break;
        }

        if (read_status(i2c_handle, &status) != 0) {
            fprintf(stderr, "Warning: Failed to read status after %d retries.\n", MAX_RETRIES);
        }

        print_reading(distance);

        /* Sleep for the sample period, checking g_running every 10 ms */
        for (int i = 0; i < SAMPLE_PERIOD / 10000 && g_running; i++)
            gpioDelay(10000);
    }

    /* Clean up resources */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return exit_code;
}

