/*
 * VL53L4CX distance reader for Raspberry Pi Zero W
 * Bus: I2C-1  Address: 0x29  Library: pigpio
 *
 * Reads distance data from the VL53L4CX every 500 ms and logs
 * microsecond-precision timestamps to stdout.  Handles SIGINT/SIGTERM
 * cleanly so that resources are released on every exit path.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/* ---- VL53L4CX register addresses (16-bit, big-endian on the bus) ---- */
#define VL53L4CX_REG_SOFT_RESET            0x0003
#define VL53L4CX_REG_SYSTEM_START          0x0001
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR 0x000B
#define VL53L4CX_REG_SYSTEM_INTERRUPT_STATUS 0x000A
#define VL53L4CX_REG_RESULT_DISTANCE       0x0096

#define VL53L4CX_I2C_ADDR 0x29
#define I2C_BUS          1
#define POLL_DELAY_US    500000   /* 500 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/* Write a 16-bit register address (big-endian) followed by a byte value. */
static int vl53l4cx_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address (big-endian) followed by a byte value. */
static int vl53l4cx_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char addr[2];
    addr[0] = (char)(reg >> 8);
    addr[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address (big-endian) followed by a 16-bit value. */
static int vl53l4cx_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char addr[2];
    char data[2];
    addr[0] = (char)(reg >> 8);
    addr[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int vl53l4cx_init(int handle)
{
    /* Soft reset */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_REG_SOFT_RESET, 0x01) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Clear any pending interrupt */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    /* Start ranging */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_REG_SYSTEM_START, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance with error checking                                   */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t  status;
    uint16_t dist;

    /* Poll interrupt status register */
    if (vl53l4cx_read_reg8(handle, VL53L4CX_REG_SYSTEM_INTERRUPT_STATUS, &status) != 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* No new data available yet */
        return 1;
    }

    /* Read distance (16-bit, big-endian) */
    if (vl53l4cx_read_reg16(handle, VL53L4CX_REG_RESULT_DISTANCE, &dist) != 0)
        return -1;

    /* Clear interrupt so the next measurement can signal */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t cur = strlen(buf);
    snprintf(buf + cur, len - cur, ".%06ld", ts.tv_nsec / 1000);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int handle = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    handle = i2cOpen(I2C_BUS, VL53L4CX_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, VL53L4CX_I2C_ADDR, strerror(errno));
        goto cleanup_gpio;
    }

    /* Initialize sensor */
    if (vl53l4cx_init(handle) != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        goto cleanup_i2c;
    }

    printf("VL53L4CX distance reader started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t distance;
        int      ret;

        ret = vl53l4cx_read_distance(handle, &distance);

        if (ret == 0) {
            char ts[40];
            get_timestamp(ts, sizeof(ts));
            printf("Timestamp: %s, Distance: %u mm\n", ts, distance);
            fflush(stdout);
        } else if (ret < 0) {
            /* I2C error — abort cleanly */
            fprintf(stderr, "I2C communication error during read\n");
            break;
        }
        /* ret == 1: no new data yet — just wait */

        gpioDelay(POLL_DELAY_US);
    }

    rc = EXIT_SUCCESS;

cleanup_i2c:
    i2cClose(handle);
cleanup_gpio:
    gpioTerminate();
    return rc;
}

