/*
 * Parking Assist System — Raspberry Pi 4 Model B
 * HC-SR04 ultrasonic sensor + SG90 servo
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 23 (BCM)
 *   HC-SR04 ECHO -> GPIO 24 (BCM)
 *   SG90 signal -> GPIO 17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c -lpigpio -lrt
 * Run:
 *   sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define TRIGGER_PIN      23          /* BCM 23 — HC-SR04 TRIG */
#define ECHO_PIN         24          /* BCM 24 — HC-SR04 ECHO */
#define SERVO_PIN        17          /* BCM 17 — SG90 signal  */

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define MIN_SERVO_ANGLE  -90.0f
#define MAX_SERVO_ANGLE  90.0f

#define TRIGGER_PULSE_US 10          /* HC-SR04 trigger pulse width (µs) */
#define ECHO_TIMEOUT_US  50000       /* 50 ms — max echo wait (timeout)   */
#define LOOP_DELAY_US    200000      /* 200 ms between readings          */
#define LOG_FILE         "sensor_data.log"

/* Sentinel value returned by read_distance() on timeout / error */
#define DISTANCE_ERROR   (-1.0f)

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static float read_distance(void);
static int   map_distance_to_angle(float distance);
static void log_data(float distance, int angle);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Distance reading --------------------------- */
/*
 * Returns distance in cm, or DISTANCE_ERROR on timeout / error.
 *
 * HC-SR04 timing (datasheet):
 *   - Trigger pulse: 10 µs high
 *   - Echo pulse:    width proportional to distance (343 m/s round trip)
 *   - Timeout:       50 ms (no echo received)
 */
static float read_distance(void)
{
    uint32_t start_tick, end_tick;
    uint32_t timeout_start;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return DISTANCE_ERROR;
    }
    gpioDelay(5);  /* settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return DISTANCE_ERROR;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return DISTANCE_ERROR;
    }

    /* Wait for echo rising edge (timeout if no object within range) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo rising-edge timeout (no object)\n");
            return DISTANCE_ERROR;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout if echo stuck high) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo falling-edge timeout (stuck high)\n");
            return DISTANCE_ERROR;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    /* distance = (pulse_us * 34300) / (2 * 1000000)  [cm] */
    return (float)pulse_us * 0.01715f;
}

/* --------------------------- Distance -> servo angle --------------------- */
static int map_distance_to_angle(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float frac = (distance - MIN_DISTANCE_CM) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return (int)(MIN_SERVO_ANGLE + frac * (MAX_SERVO_ANGLE - MIN_SERVO_ANGLE));
}

/* ------------------------------- Logging --------------------------------- */
static void log_data(float distance, int angle)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Angle: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                distance, angle);
    } else {
        fprintf(fp, "[timestamp error], Distance: %.2f cm, Angle: %d\n",
                distance, angle);
    }

    fclose(fp);
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);  /* 100 ms settle */

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");
    printf("Logging to '%s'.\n", LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        float distance = read_distance();

        if (distance == DISTANCE_ERROR) {
            fprintf(stderr, "Error: distance read failed, skipping cycle\n");
        } else {
            int angle = map_distance_to_angle(distance);

            /*
             * gpioServo() is a pigpio library call that drives a servo
             * on the specified pin.  It takes an angle in degrees (0–180)
             * and sets the pulse width for that angle.
             *
             * gpioServo() is a blocking call that keeps the pin in servo
             * mode until a subsequent call with angle=0 disables servo
             * pulses and returns the pin to a safe input state.
             *
             * We call gpioServo() here to drive the servo, then immediately
             * release the pin by calling gpioServo(SERVO_PIN, 0) so that
             * no further GPIO operations occur after the call.
             */
            if (gpioServo(SERVO_PIN, angle) < 0) {
                fprintf(stderr, "Error: gpioServo(%d, %d) failed\n",
                        SERVO_PIN, angle);
            } else {
                /* Release servo pin so no further GPIO operations occur */
                gpioServo(SERVO_PIN, 0);
            }

            log_data(distance, angle);
            printf("Distance: %.2f cm, Angle: %d\n", distance, angle);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 20 && g_running; i++) {
            gpioDelay(10000);  /* 10 ms */
        }
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");

    /*
     * Release the servo pin by calling gpioServo(SERVO_PIN, 0).
     * This ensures the pin is returned to a safe input state and
     * disables any further servo pulses.
     */
    gpioServo(SERVO_PIN, 0);

    /* Ensure trigger is low */
    gpioWrite(TRIGGER_PIN, 0);

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

