/*
 * VL53L1X Distance Sensor Monitor with Buzzer Alert
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: VL53L1X on I2C address 0x29
 * Buzzer: GPIO23 (BCM)
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_monitor vl53l1x_monitor.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <mqueue.h>
#include <pigpio.h>

#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define BUZZER_GPIO          23
#define DISTANCE_THRESHOLD   100   /* mm */
#define TIMING_BUDGET_MS     50
#define POLL_INTERVAL_US     50000 /* 50 ms */
#define MSG_QUEUE_NAME       "/vl53l1x_distance_queue"
#define MSG_QUEUE_MAX_MSGS   10
#define MSG_QUEUE_MSG_SIZE   64

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET            0x0003
#define VL53L1X_REG_SYSTEM_START          0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS   0x0089
#define VL53L1X_REG_RESULT_DISTANCE       0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x000A
