                     "%Y-%m-%d %H:%M:%S", timeinfo);
            snprintf(message + strlen(message),
                     sizeof(message) - strlen(message),
                     " Distance: %u mm", distance);

            if (message_queue_send(message) != 0) {
                fprintf(stderr, "Failed to send message\n");
            }

            /* Activate buzzer if distance is below threshold */
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

