/*
 * Parking sensor using HC-SR04 ultrasonic sensor on Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 27 (BCM)
 *   Buzzer      -> GPIO 22 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:
 *   sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define SPEED_OF_SOUND_CM_PER_US 0.0343f   /* cm/us at ~20 °C */
#define MIN_DISTANCE_CM         2.0f
#define MAX_DISTANCE_CM         400.0f
#define BUZZER_THRESHOLD_CM     30.0f
#define TRIGGER_PULSE_US        10
#define ECHO_TIMEOUT_US         30000      /* 30 ms max echo wait */
#define LOOP_DELAY_US           100000     /* 100 ms between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static void buzzer_set(int state)
{
    if (gpioWrite(BUZZER_PIN, state) < 0) {
        fprintf(stderr, "Warning: gpioWrite(BUZZER_PIN, %d) failed\n", state);
    }
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */
/*
 * Returns distance in cm on success, or -1.0 on timeout / error.
 *
 * The HC-SR04 echo pulse width is proportional to the round-trip
 * distance.  pigpio's gpioTick wraps every ~71.6 min; the 32-bit
 * subtraction handles the wrap correctly.
 */
static float measure_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);  /* let line settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER_PIN, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo start timeout (sensor absent?)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo end timeout (no object?)\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioWrite(BUZZER_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioWrite(BUZZER_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started.  Trigger=GPIO%d  Echo=GPIO%d  Buzzer=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.0f cm  Range: %.0f–%.0f cm  Press Ctrl+C to exit.\n",
           BUZZER_THRESHOLD_CM, MIN_DISTANCE_CM, MAX_DISTANCE_CM);

    bool buzzer_on = false;

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            /* Sensor error or out-of-range: ensure buzzer is off */
            if (buzzer_on) {
                buzzer_set(0);
                buzzer_on = false;
            }
        } else {
            printf("Distance: %.2f cm\n", distance);

            if (distance < BUZZER_THRESHOLD_CM) {
                if (!buzzer_on) {
                    buzzer_set(1);
                    buzzer_on = true;
                }
            } else {
                if (buzzer_on) {
                    buzzer_set(0);
                    buzzer_on = false;
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    buzzer_set(0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

