/*
 * Gate control system using VL53L1X ToF sensor and SG90 servo.
 *
 * Hardware:
 *   - Raspberry Pi Zero W
 *   - VL53L1X on I2C bus 1, address 0x29
 *   - SG90 servo on GPIO18 (BCM) with hardware PWM
 *
 * Build:
 *   gcc -O2 -Wall -o gate_control gate_control.c -lpigpio -lrt
 * Run:
 *   sudo ./gate_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define SERVO_PIN            18          /* BCM 18 */

#define DISTANCE_THRESHOLD_CM 20
#define POLL_INTERVAL_US     100000      /* 100 ms */
#define MAX_RETRIES          3
#define LOG_FILE             "gate_log.txt"

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define VL53L1X_REG_SOFT_RESET          0x0003
#define VL53L1X_REG_SYSTEM_START        0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE     0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT    0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_GPIO_HV_MUX_CTRL    0x0030
#define VL53L1X_REG_GPIO_TIO_HV_STATUS  0x0031
#define VL53L1X_REG_SYSTEM_MODE_START   0x0000
#define VL53L1X_REG_SYSTEM_MODE_STOP    0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x000A

#define VL53L1X_SOFT_RESET_VALUE        0x00
#define VL53L1X_SYSTEM_START_VALUE      0x01
#define VL53L1X_SYSTEM_MODE_STOP_VALUE   0x00
#define VL53L1X_SYSTEM_MODE_START_VALUE  0x40
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR_VALUE 0x01

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  log_event(const char *msg);
static int  i2c_write_reg16(int handle, uint16_t reg, uint8_t value);
static int  i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance);
static int  vl53l1x_start_ranging(int handle);
static int  vl53l1x_stop_ranging(int handle);
static void servo_set_angle(int pin, int angle);
static void gate_open(void);
static void gate_close(void);
static void gate_control(uint16_t distance);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Logging ----------------------------------- */

static int log_event(const char *msg)
{
    if (!g_log_file)
        return -1;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s: %s\n", ts, msg);
    fflush(g_log_file);
    return 0;
}

/* ----------------------------- I2C helpers -------------------------------- */

/* Write a single byte to a 16-bit register address (big-endian on bus). */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read `len` bytes from a 16-bit register address (big-endian on bus). */
static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ----------------------------- VL53L1X driver ---------------------------- */

/*
 * Software reset and wait for boot.
 * Returns 0 on success, -1 on error.
 */
static int vl53l1x_init(int handle)
{
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_VALUE) < 0) {
        log_event("VL53L1X: soft reset write failed");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Clear any pending interrupt */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR,
                       VL53L1X_SYSTEM_INTERRUPT_CLEAR_VALUE) < 0) {
        log_event("VL53L1X: interrupt clear failed");
        return -1;
    }

    /* Start ranging */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, VL53L1X_SYSTEM_START_VALUE) < 0) {
        log_event("VL53L1X: start ranging failed");
        return -1;
    }

    return 0;
}

/*
 * Read distance in mm.
 * Returns 0 on success, -1 on error.
 */
static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t status = 0;
    uint8_t data[2];
    int retries = 0;

    /* Poll for data-ready (bit 0 of RESULT_RANGE_STATUS) */
    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
            log_event("VL53L1X: status read failed");
            retries++;
            gpioDelay(10000);
            continue;
        }
        if (status & 0x01)
            break;
        gpioDelay(10000);
        retries++;
    }

    if (retries >= MAX_RETRIES) {
        log_event("VL53L1X: data-ready timeout");
        return -1;
    }

    /* Read 2 bytes of distance (big-endian) */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, data, 2) < 0) {
        log_event("VL53L1X: distance read failed");
        return -1;
    }

    *distance = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* Start continuous ranging. */
static int vl53l1x_start_ranging(int handle)
{
    return i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, VL53L1X_SYSTEM_START_VALUE);
}

/* Stop ranging. */
static int vl53l1x_stop_ranging(int handle)
{
    return i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, VL53L1X_SYSTEM_MODE_STOP_VALUE);
}

/* ----------------------------- Servo control ----------------------------- */

static void servo_set_angle(int pin, int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;

    /* SG90: 500 us pulse = 0 deg, 2500 us pulse = 180 deg */
    int pulse_width = 500 + (angle * 2000 / 180);
    gpioServo(pin, pulse_width);
}

static void gate_open(void)
{
    servo_set_angle(SERVO_PIN, 180);
    log_event("Gate opened");
}

static void gate_close(void)
{
    servo_set_angle(SERVO_PIN, 0);
    log_event("Gate closed");
}

/* ----------------------------- Gate control ------------------------------ */

static void gate_control(uint16_t distance)
{
    static int gate_open = 0;

    if (distance < DISTANCE_THRESHOLD_CM) {
        if (!gate_open) {
            gate_open = 1;
            gate_open();
        }
    } else {
        if (gate_open) {
            gate_open = 0;
            gate_close();
        }
    }
}

/* ----------------------------- Cleanup ----------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        vl53l1x_stop_ranging(g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    if (g_log_file) {
        log_event("Program terminated");
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ----------------------------- Main -------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        log_event("I2C open failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize VL53L1X */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor absent or bus error)\n");
        log_event("VL53L1X init failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    /* Main loop */
    while (g_running) {
        uint16_t distance = 0;

