/*
 * HC-SR04 Ultrasonic Distance Measurement with Falling-Edge Interrupt
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM)
 *   ECHO -> GPIO 24 (physical pin 18, BCM)
 *
 * NOTE: The HC-SR04 ECHO line is 5 V and must be level-shifted or
 * divided to 3.3 V for the Raspberry Pi's 3.3 V logic tolerance.
 *
 * Build:  gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse            */
#define SAMPLE_PERIOD_US 200000      /* 5 Hz sampling interval         */
#define ECHO_TIMEOUT_US  60000       /* 60 ms without echo => timeout  */
#define MIN_PULSE_US     100         /* reject noise below this       */
#define MAX_PULSE_US     30000       /* reject implausible echo       */
#define SOUND_SPEED_CM_S 34300.0     /* cm/s at 20 C                  */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t     rawtime;
    struct tm  tm_info;

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Distance calculation                                                */
/* ------------------------------------------------------------------ */
static double calculate_distance(uint32_t pulse_us)
{
    /* distance = (pulse_us * speed_cm_s) / 2 / 1e6 */
    return (double)pulse_us * SOUND_SPEED_CM_S / 2.0 / 1000000.0;
}

/* ------------------------------------------------------------------ */
/* Echo alert callback (rising + falling edges)                         */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    static uint32_t rise_tick = 0;
    static bool     rise_seen = false;

    if (level == 1) {
        /* Rising edge: echo starts */
        rise_tick  = tick;
        rise_seen  = true;
    } else if (level == 0 && rise_seen) {
        /* Falling edge: echo ends */
        uint32_t fall_tick = tick;

        /* Handle 32-bit tick wraparound (~72 min) */
        uint32_t pulse_us;
        if (fall_tick >= rise_tick) {
            pulse_us = fall_tick - rise_tick;
        } else {
            pulse_us = (0xFFFFFFFFu - rise_tick) + fall_tick + 1u;
        }

        if (pulse_us >= MIN_PULSE_US && pulse_us <= MAX_PULSE_US) {
            double distance = calculate_distance(pulse_us);
            char   ts[32];
            get_timestamp(ts, sizeof(ts));

            printf("%s Distance: %.2f cm (pulse: %u us)\n", ts, distance, pulse_us);
            fflush(stdout);

            if (g_log_file) {
                fprintf(g_log_file, "%s,%.2f,%u\n", ts, distance, pulse_us);
                fflush(g_log_file);
            }
        } else {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr, "%s WARNING: Invalid pulse width %u us (noise or timeout)\n",
                    ts, pulse_us);
        }

        rise_seen = false;
    }
    /* level == 2 indicates a watchdog timeout; ignore */
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN LOW.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down on ECHO so the line is defined when idle */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        perror("Error: failed to open distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: failed to register SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: failed to register SIGTERM handler");
    }

    /* ---- Register echo alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO_PIN %d.\n",
                ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIGGER: GPIO %d | ECHO: GPIO %d | Sample: 5 Hz\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Generate 10 us trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Warning: failed to set TRIGGER HIGH.\n");
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Warning: failed to set TRIGGER LOW.\n");
        }

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        bool     echo_seen  = false;

        while (g_running) {
            uint32_t now = gpioTick();
            if (now - wait_start >= ECHO_TIMEOUT_US) {
                break;
            }
            if (gpioRead(ECHO_PIN) == 1) {
                echo_seen = true;
                break;
            }
            gpioDelay(100); /* 100 us poll interval */
        }

        if (!echo_seen) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr, "%s WARNING: No echo received within %u us (timeout).\n",
                    ts, ECHO_TIMEOUT_US);
        }

        /* Sleep until next sample period */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

