    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
            fprintf(stderr, "Warning: I2C write (reg select) to 0x%04X failed (attempt %d/%d)\n",
                    reg, attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US * (1 << attempt));
            continue;
        }
        if (i2cReadDevice(handle, (char *)value, 1) == 1) return 0;
        fprintf(stderr, "Warning: I2C read from reg 0x%04X failed (attempt %d/%d)\n",
                reg, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US * (1 << attempt));
    }
    return -1;
}

static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    char data[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
            fprintf(stderr, "Warning: I2C write (reg select) to 0x%04X failed (attempt %d/%d)\n",
                    reg, attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US * (1 << attempt));
            continue;
        }
        if (i2cReadDevice(handle, data, 2) == 2) {
            *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
            return 0;
        }
        fprintf(stderr, "Warning: I2C read16 from reg 0x%04X failed (attempt %d/%d)\n",
                reg, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US * (1 << attempt));
    }
    return -1;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (vl53l1x_read_reg8(handle, 0x010F, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID from VL53L1X\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    if (vl53l1x_write_reg8(handle, 0x0000, 0x01) != 0) return -1;
    gpioDelay(1000);

    if (vl53l1x_write_reg8(handle, 0x0000, 0x00) != 0) return -1;
