#define LED_GPIO_0          17
#define LED_GPIO_1          18
#define LED_GPIO_2          27
#define LED_GPIO_3          22

#define POLL_DELAY_US       50000   /* 50 ms */
#define DEBOUNCE_DELAY_US   20000   /* 20 ms */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR           0x5E
#define MPR121_SOFTRESET     0x80

/* Expected ECR after soft reset */
#define MPR121_ECR_EXPECTED  0x0C

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* --------------------------- Forward declarations ------------------------ */

static void signal_handler(int sig);
static int  mpr121_write(uint8_t reg, uint8_t value);
static int  mpr121_read(uint8_t reg, uint8_t *value);
static int  mpr121_init(void);
static void cleanup(void);
static void log_event(const char *message);
static void set_led_pattern(uint8_t pattern);

/* ------------------------------- Signal ---------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ I2C helpers ------------------------------ */

/*
 * Write a single byte to an MPR121 register.
 * Returns 0 on success, -1 on error.
 */
static int mpr121_write(uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };

    if (i2cWriteDevice(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an MPR121 register.
 * Returns 0 on success and stores the value in *value, -1 on error.
 */
static int mpr121_read(uint8_t reg, uint8_t *value)
{
    char reg_buf[1] = { (char)reg };
    char data_buf[1];

    if (i2cWriteDevice(g_i2c_fd, reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(g_i2c_fd, data_buf, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

/* ------------------------------ MPR121 init ------------------------------ */

/*
 * Initialize the MPR121 sensor.
 * Returns 0 on success, -1 on error.
 */
static int mpr121_init(void)
{
    uint8_t ecr;

    /* Soft reset */
    if (mpr121_write(MPR121_SOFTRESET, 0x63) != 0) {
        fprintf(stderr, "MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle after reset */

    /* Verify sensor is present by reading back ECR */
    if (mpr121_read(MPR121_ECR, &ecr) != 0) {
        fprintf(stderr, "MPR121 not responding on I2C bus\n");
        return -1;
    }
    if (ecr != MPR121_ECR_EXPECTED) {
        fprintf(stderr, "MPR121 ECR mismatch: got 0x%02X, expected 0x%02X\n",
                ecr, MPR121_ECR_EXPECTED);
        return -1;
    }

    /*
     * Baseline filtering configuration (defaults from datasheet).
     * Rising / falling filter thresholds are set to 0x0F for all electrodes.
     */
    for (int i = 0; i < 12; i++) {
        uint8_t reg = 0x41 + (i * 2);
        if (mpr121_write(reg, 0x0F) != 0) return -1;   /* touch threshold */
        if (mpr121_write(reg + 1, 0x0F) != 0) return -1; /* release threshold */
    }

    /*
     * Enable 12 electrodes, baseline tracking, and enter run mode.
     * ECR = 0x0C: CL=10 (16 samples), ELEPROX=0, ELE_EN=12 (0x0C), ELE_CFG=0
     */
    if (mpr121_write(MPR121_ECR, 0x0C) != 0) {
        fprintf(stderr, "Failed to set MPR121 ECR\n");
        return -1;
    }

    gpioDelay(1000); /* 1 ms settle after configuration */
    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    /* Turn off LEDs */
    set_led_pattern(0x00);

    /* Release GPIO lines */
    gpioSetMode(LED_GPIO_0, PI_INPUT);
    gpioSetMode(LED_GPIO_1, PI_INPUT);
    gpioSetMode(LED_GPIO_2, PI_INPUT);
    gpioSetMode(LED_GPIO_3, PI_INPUT);

    /* Close I2C */
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }

