#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_AFE_CONFIG 0x5C
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int mpr121_read_reg(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int mpr121_init(void) {
    int id = mpr121_read_reg(0x5C);
    if (id < 0) {
        fprintf(stderr, "Failed to read MPR121 ID\n");
        return -1;
    }
    if ((id & 0x0F) != 0x0C) {
        fprintf(stderr, "Unexpected MPR121 ID: 0x%02X (expected 0x0C)\n", id & 0x0F);
        return -1;
    }

    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write_reg(MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTOCONFIG1, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_USL, 200) < 0) return -1;
    if (mpr121_write_reg(MPR121_LSL, 130) < 0) return -1;
    if (mpr121_write_reg(MPR121_TL, 180) < 0) return -1;

    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(MPR121_TOUCHTH_0 + 2 * i, 12) < 0) return -1;
        if (mpr121_write_reg(MPR121_RELEASETH_0 + 2 * i, 6) < 0) return -1;
    }

    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;
    if (mpr121_write_reg(MPR121_AFE_CONFIG, 0x24) < 0) return -1;

    if (mpr121_write_reg(MPR121_ECR, 0x8C) < 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int read_touch_status(void) {
    int lo = mpr121_read_reg(MPR121_TOUCHSTATUS_L);
    int hi = mpr121_read_reg(MPR121_TOUCHSTATUS_H);
    if (lo < 0 || hi < 0) return -1;
    return (hi << 8) | lo;
}

static void log_proximity_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Proximity detected\n", timestamp);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int touch_status = read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status\n");
            gpioDelay(100000);
            continue;
        }

        if (touch_status & 0x01) {
            printf("Proximity detected!\n");
            log_proximity_event();
            gpioWrite(LED_GPIO, 1);
            gpioDelay(1000000);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(10000);
    }

    printf("\nCleaning up...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

