/*
 * HC-SR04 Ultrasonic Distance Measurement for Raspberry Pi Zero W
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO17 (BCM)
 *   HC-SR04 ECHO -> GPIO18 (BCM)
 *   HC-SR04 VCC  -> 5 V
 *   HC-SR04 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define SPEED_OF_SOUND   343.0          /* m/s at 20 C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define TIMEOUT_US       30000          /* 30 ms timeout for echo */
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    1000000        /* 1 second between readings */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    time(&rawtime);
    gmtime_r(&rawtime, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on the trigger pin                            */
/* ------------------------------------------------------------------ */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    gpioDelay(5);                       /* ensure clean low */

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Measure echo pulse width in microseconds                            */
/* Returns >= 0 on success, -1 on timeout, -2 on read error            */
/* ------------------------------------------------------------------ */
static long measure_echo(void)
{
    uint32_t start_tick, end_tick;
    uint32_t deadline;

    /* Wait for echo rising edge (timeout) */
    deadline = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1;                 /* echo never went high */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    deadline = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1;                 /* echo stuck high */
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/* ------------------------------------------------------------------ */
/* Convert pulse width to distance in cm                               */
/* ------------------------------------------------------------------ */
static float pulse_to_distance(long pulse_us)
{
    return (float)pulse_us * SPEED_OF_SOUND / 2000000.0f;
}

/* ------------------------------------------------------------------ */
/* Log a reading or error line to the file                             */
/* ------------------------------------------------------------------ */
static void log_reading(float distance, bool valid)
{
    char ts[32];

    get_timestamp(ts, sizeof(ts));

    if (valid) {
        fprintf(g_log_file, "%s, Distance: %.2f cm\n", ts, distance);
    } else {
        fprintf(g_log_file, "%s, Error: invalid reading\n", ts);
    }
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(50000);                   /* 50 ms settle */

    /* Open log file */
    g_log_file = fopen("distance_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    /* Main measurement loop */
    while (g_running) {
        if (trigger_sensor() != 0) {
            log_reading(0.0f, false);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        long pulse = measure_echo();
        if (pulse < 0) {
            log_reading(0.0f, false);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float distance = pulse_to_distance(pulse);
        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            log_reading(distance, false);
        } else {
            log_reading(distance, true);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

