/*
 * HC-SR04 Ultrasonic Distance Measurement (Interrupt-driven)
 * Board:  Raspberry Pi Zero W
 * Library: pigpio (modern API, no wiringPi)
 *
 * Wiring:
 *   TRIG -> GPIO17 (BCM)
 *   ECHO -> GPIO18 (BCM) via 1k/2k voltage divider (5V -> 3.3V)
 *
 * Build:  gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define TRIGGER_PULSE_US 10
#define LOG_FILE         "distance_log.txt"
#define SAMPLE_PERIOD_S  1.0
#define MIN_PULSE_US     58   /* ~1 cm round-trip */
#define MAX_PULSE_US     25000 /* ~4 m round-trip */

/* Shared state between ISR and main thread */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen  = false;
static volatile bool     g_new_reading = false;
static volatile bool     g_running    = true;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up and exit       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* ISR callback — fires on every edge of ECHO_PIN                      */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_seen  = true;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        if (g_echo_seen) {
            g_end_tick   = tick;
            g_new_reading = true;
            g_echo_seen  = false;
        }
    }
    /* level == 2 indicates a watchdog timeout — ignore */
}

/* ------------------------------------------------------------------ */
/* Convert pigpio tick (microseconds, wraps every ~71.6 min) to seconds */
/* ------------------------------------------------------------------ */
static double tick_to_seconds(uint32_t tick)
{
    return (double)tick / 1000000.0;
}

/* ------------------------------------------------------------------ */
/* Convert pulse width (µs) to distance (m)                          */
/* ------------------------------------------------------------------ */
static double pulse_to_distance(uint32_t pulse_us)
{
    /* Speed of sound ≈ 343 m/s → 0.0343 cm/µs round-trip */
    return (double)pulse_us * 0.0343 / 2.0 / 100.0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped distance reading to the log file               */
/* ------------------------------------------------------------------ */
static void log_distance(FILE *fp, double distance)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, Distance: %.2f m\n", ts, distance) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

