            /* No valid echo received — skip this sample */
            continue;
        }

        /* Validate pulse width */
        uint32_t pulse_us = g_end_tick - g_start_tick;
        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Invalid pulse width: %u µs (out of range)\n", pulse_us);
            continue;
        }

        /* Convert to distance */
        double distance = pulse_to_distance(pulse_us);

        /* Log to file */
        log_distance(fp, distance);

        /* Print to console */
        printf("Distance: %.2f m\n", distance);

        /* Sleep until next sample period */
        double elapsed = tick_to_seconds(gpioTick() - wait_start);
        if (elapsed < SAMPLE_PERIOD_S) {
            gpioDelay((uint32_t)((SAMPLE_PERIOD_S - elapsed) * 1000000.0));
        }
    }

    rc = EXIT_SUCCESS;

cleanup_all:
    /* Disable ISR before closing */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

