#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define GATE_GPIO            24
#define DISTANCE_THRESHOLD   20.0f
#define POLL_INTERVAL_US     100000
#define LOG_FILE             "gate_log.txt"

#define VL53L1X_REG_SOFT_RESET       0x000B
#define VL53L1X_REG_SYSTEM_START     0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE   0x0096

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    if (!g_log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(g_log_file, "[unknown time] %s\n", msg);
    }
    fflush(g_log_file);
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle)
{
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        log_message("Error: failed to write soft reset low");
        return -1;
    }
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        log_message("Error: failed to write soft reset high");
        return -1;
    }
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) {
        log_message("Error: failed to start VL53L1X");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_read_distance(int handle, float *distance_cm)
{
    uint8_t status = 0;
    uint8_t dist_buf[2];

    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
        log_message("Error: failed to read range status");
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1;
    }
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
        log_message("Error: failed to read distance data");
        return -1;
    }
    uint16_t raw = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

static void control_gate(int gpio_pin, int state)
{
    if (gpioWrite(gpio_pin, state) < 0) {
        log_message("Error: failed to write gate GPIO");
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GATE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GATE_GPIO, 0);

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Program started");

    int gate_state = 0;

    while (g_running) {
        float distance = 0.0f;
        int ret = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (ret == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance);
            log_message(msg);

            if (distance < DISTANCE_THRESHOLD && gate_state == 0) {
                control_gate(GATE_GPIO, 1);
                gate_state = 1;
                log_message("Gate opened");
            } else if (distance >= DISTANCE_THRESHOLD && gate_state == 1) {
                control_gate(GATE_GPIO, 0);
                gate_state = 0;
                log_message("Gate closed");
            }
        } else if (ret < 0) {
            log_message("Error reading distance, retrying...");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_message("Shutting down");
    control_gate(GATE_GPIO, 0);
    cleanup();
    return EXIT_SUCCESS;
}

