#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SERVO_PIN        18

#define SPEED_OF_SOUND   34300.0f   /* cm/s at 20 °C */
#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define TIMEOUT_US       30000      /* 30 ms echo timeout */
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    100000     /* 100 ms between measurements */
#define MOVING_AVG_SIZE  5

static volatile uint32_t g_pulse_width = 0;
static volatile bool     g_new_pulse   = false;
static volatile sig_atomic_t g_running = 1;

static float g_distance_history[MOVING_AVG_SIZE];
static int   g_history_index = 0;
static int   g_history_count = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Moving-average filter                                               */
/* ------------------------------------------------------------------ */
static float moving_average(float new_value)
{
    g_distance_history[g_history_index] = new_value;
    g_history_index = (g_history_index + 1) % MOVING_AVG_SIZE;
    if (g_history_count < MOVING_AVG_SIZE)
        g_history_count++;

    float sum = 0.0f;
    for (int i = 0; i < g_history_count; i++)
        sum += g_distance_history[i];
    return sum / (float)g_history_count;
}

/* ------------------------------------------------------------------ */
/* Echo callback (runs in pigpio thread)                                */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        g_pulse_width = 0;
    } else if (level == 0) {
        uint32_t diff = tick - g_pulse_width;   /* handles 32-bit wrap */
        g_pulse_width = diff;
        g_new_pulse   = true;
    }
}

/* ------------------------------------------------------------------ */
/* Trigger the HC-SR04                                                  */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Read distance in cm with moving-average filtering                    */
/* Returns -1.0 on invalid reading                                      */
/* ------------------------------------------------------------------ */
static float read_distance(void)
{
    g_new_pulse = false;
    trigger_sensor();

    uint32_t start_tick = gpioTick();
    while (!g_new_pulse) {
        if ((gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Warning: echo timeout (no object detected)\n");
            return -1.0f;
        }
        gpioDelay(10);
    }

    uint32_t pulse_us = g_pulse_width;
    if (pulse_us == 0) {
        fprintf(stderr, "Warning: zero pulse width\n");
        return -1.0f;
    }

    float distance = (float)pulse_us * SPEED_OF_SOUND / 2000000.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return moving_average(distance);
}

/* ------------------------------------------------------------------ */
/* Pan servo to track distance                                         */
/* ------------------------------------------------------------------ */
static void track_distance(float distance)
{
    if (distance < 0.0f) {
        /* Invalid reading: center servo */
        if (gpioServo(SERVO_PIN, 1500) != 0)
            fprintf(stderr, "Warning: gpioServo failed for center\n");
        return;
    }

    /* Map distance (2 cm -> 400 cm) to angle (0 deg -> 180 deg) */
    float angle = 90.0f - (distance - MIN_DISTANCE_CM) * 90.0f /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

    if (angle < 0.0f)   angle = 0.0f;
    if (angle > 180.0f) angle = 180.0f;

    int pulse_width = 1000 + (int)(angle * 1000.0f / 180.0f);

    if (gpioServo(SERVO_PIN, pulse_width) != 0)
        fprintf(stderr, "Warning: gpioServo failed for angle %.1f\n", angle);
}

/* ------------------------------------------------------------------ */
/* Log data to CSV                                                      */
/* ------------------------------------------------------------------ */
static void log_data(float distance, float angle)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(stderr, "%s, Distance: %.2f cm, Angle: %.1f deg\n",
            timestamp, distance, angle);

    fprintf(g_log_file, "%s,%.2f,%.1f\n", timestamp, distance, angle);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop servo PWM */
    gpioServo(SERVO_PIN, 0);

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* Register echo callback */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Error: failed to register alert on ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("distance_log.csv", "w");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open distance_log.csv for writing\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "Timestamp,Distance_cm,Angle_deg\n");
    fflush(g_log_file);

    /* Initialize distance history */
    for (int i = 0; i < MOVING_AVG_SIZE; i++)
        g_distance_history[i] = 0.0f;

    /* Install signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float distance = read_distance();
        track_distance(distance);

        if (distance < 0.0f) {
            log_data(-1.0f, 90.0f);
        } else {
            float angle = 90.0f - (distance - MIN_DISTANCE_CM) * 90.0f /
                          (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
            if (angle < 0.0f)   angle = 0.0f;
            if (angle > 180.0f) angle = 180.0f;
            log_data(distance, angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

