/*
 * Si1102 Proximity Sensor Monitor for Raspberry Pi Zero W
 *
 * Reads proximity data from a Si1102 sensor on I2C bus 1, configures a
 * rising-edge interrupt on GPIO27 (BCM), and logs timestamped events
 * to proximity.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1102_monitor si1102_monitor.c -lpigpio -lpthread
 * Run:    sudo ./si1102_monitor [-a i2c_addr] [-t threshold]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define DEFAULT_I2C_BUS        1
#define DEFAULT_I2C_ADDR       0x40          /* Si1102 default 7-bit address */
#define DEFAULT_GPIO_PIN       27            /* BCM 27 */
#define DEFAULT_PROXIMITY_THRESHOLD 1000
#define LOG_FILE_NAME          "proximity.log"

/* Si1102 register addresses (from datasheet) */
#define SI1102_REG_PART_ID     0x00
#define SI1102_REG_HW_KEY      0x07
#define SI1102_REG_MEAS_RATE0  0x08
#define SI1102_REG_MEAS_RATE1  0x09
#define SI1102_REG_PS_LED21    0x0F
#define SI1102_REG_PS1_DATA0   0x22
#define SI1102_REG_PS1_DATA1   0x23
#define SI1102_REG_INT_CFG     0x03
#define SI1102_REG_IRQ_ENABLE  0x04
#define SI1102_REG_IRQ_MODE1   0x05
#define SI1102_REG_IRQ_MODE2   0x06

/* Expected PART_ID for Si1102 */
#define SI1102_PART_ID         0x02

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static int      g_threshold  = DEFAULT_PROXIMITY_THRESHOLD;
static int      g_i2c_addr   = DEFAULT_I2C_ADDR;
static int      g_gpio_pin   = DEFAULT_GPIO_PIN;

/* --------------------------- Forward Declarations ------------------------ */

static int  si1102_write_reg(uint8_t reg, uint8_t value);
static int  si1102_read_reg(uint8_t reg, uint8_t *value);
static int  si1102_init(void);
static int  read_proximity(uint16_t *proximity);
static void log_event(uint16_t proximity, const char *status);
static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata);
static void signal_handler(int sig);
static void cleanup(void);
static void usage(const char *prog);

/* ------------------------------- I2C Helpers ------------------------------ */

/* Write a single byte to a Si1102 register; returns 0 on success, -1 on error. */
static int si1102_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* Read a single byte from a Si1102 register; returns 0 on success, -1 on error. */
static int si1102_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ----------------------------- Sensor Init ------------------------------- */

/*
 * Initialise the Si1102 sensor.
 * Returns 0 on success, -1 on failure.
 */
static int si1102_init(void)
{
    uint8_t part_id = 0;

    /* Verify sensor identity */
    if (si1102_read_reg(SI1102_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID — sensor not present or bus error.\n");
        return -1;
    }
    if (part_id != SI1102_PART_ID) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID: 0x%02X (expected 0x%02X).\n",
                part_id, SI1102_PART_ID);
        return -1;
    }
    printf("[INFO] Si1102 detected (PART_ID=0x%02X).\n", part_id);

    /* Write HW_KEY to enable the device */
    if (si1102_write_reg(SI1102_REG_HW_KEY, 0x17) != 0)
        return -1;

    /* Set measurement rate to 0 (manual mode) */
    if (si1102_write_reg(SI1102_REG_MEAS_RATE0, 0x00) != 0)
        return -1;
    if (si1102_write_reg(SI1102_REG_MEAS_RATE1, 0x00) != 0)
        return -1;

    /* Configure PS LED current for PS1 (LED1) */
    if (si1102_write_reg(SI1102_REG_PS_LED21, 0x0F) != 0)
        return -1;

    /* Clear any pending interrupts */
    if (si1102_write_reg(SI1102_REG_IRQ_ENABLE, 0x00) != 0)
        return -1;

    /* Configure interrupt: rising edge on PS1_DATA0 */
    if (si1102_write_reg(SI1102_REG_INT_CFG, 0x01) != 0)
        return -1;

    /* Enable PS1 interrupt */
    if (si1102_write_reg(SI1102_REG_IRQ_ENABLE, 0x01) != 0)
        return -1;

    /* Set interrupt mode to push-pull (active high) */
    if (si1102_write_reg(SI1102_REG_IRQ_MODE1, 0x00) != 0)
        return -1;
    if (si1102_write_reg(SI1102_REG_IRQ_MODE2, 0x00) != 0)
        return -1;

    return 0;
}

/* --------------------------- Proximity Read ------------------------------ */

/*
 * Read the 16-bit proximity value from PS1_DATA0/PS1_DATA1.
 * Returns 0 on success, -1 on failure.
 */
static int read_proximity(uint16_t *proximity)
{
    uint8_t lo = 0, hi = 0;

    if (si1102_read_reg(SI1102_REG_PS1_DATA0, &lo) != 0)
        return -1;
    if (si1102_read_reg(SI1102_REG_PS1_DATA1, &hi) != 0)
        return -1;

    *proximity = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------- Logging --------------------------------- */

/*
 * Append a timestamped event to the log file.
 * status is either "SAFE" or "ALERT".
 */
static void log_event(uint16_t proximity, const char *status)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s, Proximity: %u, Status: %s\n",
                timestamp, proximity, status);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "[ERROR] Log file is not open.\n");
    }
}

/* --------------------------- Interrupt Handler --------------------------- */

/*
 * pigpio alert callback — runs in a pigpio thread.
 * We defer heavy work to the main thread by setting a flag and waking it.
 */
static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    /*
     * We only care about rising edges, so level == 1.
     * If the sensor supports falling edges, level == 0 would be handled here.
     */
    if (level == 1) {
        /* Wake the main thread to process the event */
        g_running = 0;
    }
}

/* ------------------------------- Signal ---------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    /* Disable the interrupt */
    if (g_i2c_handle >= 0) {
        si1102_write_reg(SI1102_REG_IRQ_ENABLE, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    /* Close the log file */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

static void usage(const char *prog)
{
    fprintf(stderr,
            "Usage: %s [-a i2c_addr] [-t threshold] [-p gpio_pin]\n"
            "  -a i2c_addr   I2C address of Si1102 (hex or decimal, default 0x%02X)\n"
            "  -t threshold  Proximity threshold (default %d)\n"
            "  -p gpio_pin   GPIO pin for interrupt (BCM, default %d)\n",
            prog, DEFAULT_I2C_ADDR, DEFAULT_PROXIMITY_THRESHOLD, DEFAULT_GPIO_PIN);
}

/* --------------------------------- Main ---------------------------------- */

int main(int argc, char *argv[])
{
    int opt;

    /* Parse command-line arguments */
    while ((opt = getopt(argc, argv, "a:t:p:h")) != -1) {
        switch (opt) {
