            if (g_gpio_pin < 0 || g_gpio_pin > 31) {
                fprintf(stderr, "[ERROR] Invalid GPIO pin: %d\n", g_gpio_pin);
                usage(argv[0]);
                return EXIT_FAILURE;
            }
