#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define TRIGGER_PIN      23          /* BCM 23 — HC-SR04 trigger  */
#define ECHO_PIN         24          /* BCM 24 — HC-SR04 echo     */
#define SPEAKER_PIN      18          /* BCM 18 — hardware PWM0    */

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200.0f
#define MAX_FREQUENCY_HZ 2000.0f
#define PWM_DUTY_50PCT   128         /* 50 % of 255 range          */
#define PWM_RANGE        255
#define ECHO_TIMEOUT_US  200000      /* 200 ms max echo wait       */
#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse        */
#define LOOP_DELAY_US    50000       /* 50 ms main-loop period     */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Distance measurement ------------------------ */
/*
 * Returns distance in cm, or -1.0 on timeout / error.
 * HC-SR04 timing:
 *   trigger pulse 10 us high
 *   echo high duration = distance * 58 us  (round trip)
 *   echo low  duration = (343 m/s / 2) * distance
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick;
    uint32_t timeout_start;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
    }

    /* Wait for echo rising edge */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo start timeout\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo end timeout\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t elapsed_us = end_tick - start_tick;
    return (float)elapsed_us / 58.0f;
}

/* ----------------------------- Frequency map ----------------------------- */
static float distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    /* Logarithmic mapping: closer -> higher pitch */
    float norm = (distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    return MIN_FREQUENCY_HZ +
           (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) * (1.0f - powf(norm, 2.0f));
}

/* ------------------------------- PWM setup ------------------------------- */
static int setup_pwm(void)
{
    /*
     * pigpio hardware PWM on GPIO18 (BCM) uses the main clock (19.2 MHz)
     * divided by the range (255) to generate a 500 kHz carrier.
     * With a 50 % duty cycle, the speaker sees a square wave at 500 kHz.
     */
    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set speaker pin mode\n");
        return -1;
    }
    if (gpioSetPWMrange(SPEAKER_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        return -1;
    }
    if (gpioPWM(SPEAKER_PIN, PWM_DUTY_50PCT) < 0) {
        fprintf(stderr, "Error: failed to initialise PWM\n");
        return -1;
    }
    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Silence speaker */
    gpioPWM(SPEAKER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, ensure low */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIGGER_PIN, 0);

    /* Configure echo pin as input */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise PWM */
    if (setup_pwm() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Theremin ready.  Trigger: GPIO%d  Echo: GPIO%d  Speaker: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, SPEAKER_PIN);
    printf("Press Ctrl+C to exit.\n");

    float previous_frequency = MIN_FREQUENCY_HZ;

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            /*
             * Sensor error or timeout — preserve the previous frequency
             * so the instrument stays responsive even when the sensor is
             * out of range.
             */
            gpioSetPWMfrequency(SPEAKER_PIN, (int)previous_frequency);
            gpioPWM(SPEAKER_PIN, PWM_DUTY_50PCT);
        } else {
            float freq = distance_to_frequency(distance);
            gpioSetPWMfrequency(SPEAKER_PIN, (int)freq);
            gpioPWM(SPEAKER_PIN, PWM_DUTY_50PCT);
            previous_frequency = freq;

            printf("Distance: %.2f cm  Frequency: %.2f Hz\n", distance, freq);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

