        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN (GPIO%d) as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN (GPIO%d).\n", ECHO_PIN);
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN low.\n");
        gpioTerminate();
        return -1;
    }

