#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define TIMEOUT_US 50000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static long measure_echo_pulse(void) {
    uint32_t start_tick, end_tick;
    int level;

    /* Wait for echo to go high (start of pulse) */
    level = gpioRead(ECHO_PIN);
    if (level < 0) {
        fprintf(stderr, "Error reading echo pin\n");
        return -1;
    }
    if (level == 0) {
        start_tick = gpioTick();
        while (running) {
            level = gpioRead(ECHO_PIN);
            if (level < 0) {
                fprintf(stderr, "Error reading echo pin\n");
                return -1;
            }
            if (level == 1) {
                break;
            }
            if ((gpioTick() - start_tick) > TIMEOUT_US) {
                return -1; /* Timeout waiting for echo start */
            }
        }
        if (!running) return -1;
    }

    /* Wait for echo to go low (end of pulse) */
    end_tick = gpioTick();
    while (running) {
        level = gpioRead(ECHO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error reading echo pin\n");
            return -1;
        }
        if (level == 0) {
            break;
        }
        if ((gpioTick() - end_tick) > TIMEOUT_US) {
            return -1; /* Timeout waiting for echo end */
        }
    }
    if (!running) return -1;

    return (long)(end_tick - start_tick);
}

static float calculate_distance(long pulse_duration_us) {
    if (pulse_duration_us < 0) return -1.0f;
    return (float)pulse_duration_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(50000); /* 50 ms settle time */

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Send 10 us trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "Error writing trigger pin high\n");
            break;
        }
        gpioDelay(10);
        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "Error writing trigger pin low\n");
            break;
        }

        long pulse_duration = measure_echo_pulse();
        float distance = calculate_distance(pulse_duration);

        if (distance < 0) {
            printf("Invalid reading\n");
        } else if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            printf("Invalid reading (out of range: %.2f cm)\n", distance);
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < 10.0f) {
                printf("  Too close!");
            }
            printf("\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

