 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define CS_GPIO         8          /* BCM GPIO8 (SPI0 CE0) */
#define LOG_FILE        "distance_log.csv"
#define READ_DELAY_MS   100
#define MAX_RETRIES     3

/* ICU-20201 register addresses (example – adjust per datasheet) */
#define REG_DISTANCE_MSB 0x00
#define REG_DISTANCE_LSB 0x01
#define REG_STATUS       0x02
#define REG_CONFIG       0x03

static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/*
 * Read a single register from the ICU-20201.
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int icu20201_read_reg(uint8_t reg, uint8_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };   /* MSB=1 for read */
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 2;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE(read reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = rx[1];
    return 0;
}

/*
 * Write a single register on the ICU-20201.
 * Returns 0 on success, -1 on error.
 */
static int icu20201_write_reg(uint8_t reg, uint8_t value)
{
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };   /* MSB=0 for write */
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 2;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE(write reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    return 0;
}

/*
 * Read distance (mm) from the ICU-20201.
 * Returns 0 on success and stores the distance in *distance; -1 on error.
 */
static int icu20201_read_distance(uint16_t *distance)
{
    uint8_t msb = 0, lsb = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (icu20201_read_reg(REG_DISTANCE_MSB, &msb) == 0 &&
            icu20201_read_reg(REG_DISTANCE_LSB, &lsb) == 0) {
            *distance = ((uint16_t)msb << 8) | lsb;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES)
            usleep(10000);   /* 10 ms backoff */
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0)
        fprintf(g_log_fp, "Timestamp,Distance_mm\n");
    return 0;
}

static void log_data(uint16_t distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s,%u\n", timestamp, distance);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (spi_init() != 0)
        return EXIT_FAILURE;

    if (log_open() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /*
     * Optional: configure the sensor for continuous measurement.
     * Adjust the register values below per the ICU-20201 datasheet.
     */
    if (icu20201_write_reg(REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Warning: failed to configure sensor\n");
    }

    printf("ICU-20201 distance logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t distance = 0;

        if (icu20201_read_distance(&distance) == 0) {
            /*
             * Validate distance range.
             * The ICU-20201 datasheet specifies a range of 200–5000 mm.
             */
            if (distance >= 200 && distance <= 5000) {
                log_data(distance);
            } else {
                fprintf(stderr, "Invalid distance: %u mm (out of range)\n",
                        distance);
            }
        } else {
            fprintf(stderr, "Sensor read error – continuing\n");
        }

        usleep(READ_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

