#define SI1175_REG_COMMAND     0x46
#define SI1175_CMD_RESET       0x01
#define SI1175_CMD_ALS_FORCE   0x06
#define SI1175_PART_ID_VAL     0x75

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, value, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read word from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ---- Si1175 initialization ---- */
static int si1175_init(int fd)
{
    uint8_t part_id = 0;

    /* Verify sensor presence */
    if (i2c_read_byte(fd, SI1175_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor may be absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1175_PART_ID_VAL) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X). Wrong sensor?\n",
                part_id, SI1175_PART_ID_VAL);
        return -1;
    }

    /* Software reset */
    if (i2c_write_byte(fd, SI1175_REG_COMMAND, SI1175_CMD_RESET) != 0) {
        fprintf(stderr, "Software reset failed.\n");
        return -1;
    }
    usleep(10000); /* 10 ms settle after reset */

    /* Force a single ALS measurement to verify the device is responsive */
    if (i2c_write_byte(fd, SI1175_REG_COMMAND, SI1175_CMD_ALS_FORCE) != 0) {
        fprintf(stderr, "ALS force command failed.\n");
        return -1;
    }
    usleep(10000); /* 10 ms conversion time */

    return 0;
}

