/*
 * Si1120 ambient light & proximity logger for Raspberry Pi 4 Model B
 * I2C bus 1, address 0x60, sampling every 500 ms, up to 3 retries.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1120_log si1120_log.c -lgpiod
 * Run:    ./si1120_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si1120 constants (verified against datasheet rev 2.0) ---- */
#define SI1120_I2C_ADDR        0x60
#define I2C_BUS                "/dev/i2c-1"
#define LOG_FILE               "si1120_log.txt"
#define SAMPLE_PERIOD_MS       500
#define MAX_RETRIES            3
#define RETRY_DELAY_MS         10

/* Si1120 register addresses */
#define REG_PART_ID            0x00
#define REG_HW_KEY             0x07
#define REG_MEAS_RATE0         0x08
#define REG_ALS_VIS_DATA0      0x22
#define REG_ALS_VIS_DATA1      0x23
#define REG_PS1_DATA0          0x24
#define REG_PS1_DATA1          0x25

/* Expected part ID and HW_KEY values */
#define SI1120_PART_ID         0x20
#define SI1120_HW_KEY_VAL      0x17

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register; returns 0 on success, -1 on err */
static int si1120_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register; returns 0 on success, -1 on err */
static int si1120_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "write(reg=0x%02X) for read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "read(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers */
static int si1120_read_le16(int fd, uint8_t reg_lo, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1120_read_reg(fd, reg_lo, &lo) != 0)
        return -1;
    if (si1120_read_reg(fd, reg_lo + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static int si1120_init(int fd)
{
    uint8_t part_id = 0;

    /* 1. Software reset via HW_KEY write */
    if (si1120_write_reg(fd, REG_HW_KEY, SI1120_HW_KEY_VAL) != 0)
        return -1;
    usleep(10000);  /* 10 ms settle after reset */

    /* 2. Verify part ID */
    if (si1120_read_reg(fd, REG_PART_ID, &part_id) != 0)
        return -1;
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID);
        return -1;
    }
    printf("Si1120 detected (PART_ID=0x%02X)\n", part_id);

    /* 3. Configure measurement rate (0x08 = 0.5 ms / sample) */
    if (si1120_write_reg(fd, REG_MEAS_RATE0, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, uint16_t *als_vis, uint16_t *prox)
{
    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        if (si1120_read_le16(fd, REG_ALS_VIS_DATA0, als_vis) != 0) {
            fprintf(stderr, "ALS read failed (attempt %d/%d)\n",
                    attempt, MAX_RETRIES);
            if (attempt < MAX_RETRIES)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (si1120_read_le16(fd, REG_PS1_DATA0, prox) != 0) {
            fprintf(stderr, "Proximity read failed (attempt %d/%d)\n",
                    attempt, MAX_RETRIES);
            if (attempt < MAX_RETRIES)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0;
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t als_vis, uint16_t prox)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s, ALS_VIS=%u, Proximity=%u\n", ts, als_vis, prox) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1120_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1120_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1120_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging Si1120 data to %s every %d ms. Press Ctrl-C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD_MS);

    /* Main sampling loop */
    while (g_running) {
        uint16_t als_vis = 0, prox = 0;

        if (read_sensor_data(g_i2c_fd, &als_vis, &prox) == 0) {
            if (log_data(g_log_fp, als_vis, prox) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed after %d retries; "
                            "continuing.\n", MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int ms = 0; ms < SAMPLE_PERIOD_MS && g_running; ms += 100)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

