#define SI1182_REG_MEAS_RATE    0x08
#define SI1182_REG_ALS_VIS_DATA0 0x22
#define SI1182_REG_PS1_DATA0    0x26

/* ---- Expected part ID ---- */
#define SI1182_PART_ID_EXPECTED 0x82

/* ---- Measurement rate (0x08 = 100 ms) ---- */
#define SI1182_MEAS_RATE_100MS  0x08

/* ---- Global resources for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1182 register                                */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int si1182_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1182 register                               */
/* Returns 0 on success and stores value in *out, -1 on error         */
/* ------------------------------------------------------------------ */
static int si1182_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    /* Write the register pointer */
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }

    /* Read the data byte */
    uint8_t val;
    n = read(fd, &val, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }

    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian data word from two consecutive registers */
/* Returns 0 on success and stores value in *out, -1 on error         */
/* ------------------------------------------------------------------ */
static int si1182_read_word(int fd, uint8_t reg_low, uint16_t *out)
{
    uint8_t lo, hi;
    if (si1182_read_reg(fd, reg_low, &lo) != 0)
        return -1;
    if (si1182_read_reg(fd, reg_low + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

