/* Initialize the Si1182 sensor                                       */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int si1182_init(int fd)
{
    uint8_t part_id = 0;

    /* Verify sensor presence by reading PART_ID */
    if (si1182_read_reg(fd, SI1182_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor may be absent or bus error.\n");
        return -1;
    }

    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X). "
                        "Wrong sensor or wrong address.\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }

    printf("Si1182 detected (PART_ID = 0x%02X).\n", part_id);

    /* Configure measurement rate to 100 ms */
    if (si1182_write_reg(fd, SI1182_REG_MEAS_RATE, SI1182_MEAS_RATE_100MS) != 0) {
        fprintf(stderr, "Failed to set measurement rate.\n");
        return -1;
    }

