/* ------------------------------------------------------------------ */
/* Read sensor data                                                   */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int si1182_read_data(int fd, uint16_t *ambient_light, uint16_t *proximity)
{
    if (si1182_read_word(fd, SI1182_REG_ALS_VIS_DATA0, ambient_light) != 0)
        return -1;
    if (si1182_read_word(fd, SI1182_REG_PS1_DATA0, proximity) != 0)
        return -1;
    return 0;
}

