    /* Milliseconds are in ts.tv_nsec, but strftime does not support %3N */
    long ms = ts.tv_nsec / 1000000L;

    fprintf(fp, "%s.%03ld,%u,%u\n", timestamp, ms, ambient_light, proximity);
    fflush(fp);

    printf("%s.%03ld,%u,%u\n", timestamp, ms, ambient_light, proximity);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the Si1182 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (si1182_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    g_log_fp = fopen("biometric_log.txt", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open biometric_log.txt: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging Si1182 data to biometric_log.txt (Ctrl+C to stop)...\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t ambient_light = 0, proximity = 0;

        if (si1182_read_data(g_i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(g_log_fp, ambient_light, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        /* Sleep 100 ms (100,000 microseconds) */
        usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

