#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_PS_LED21 0x0F
#define SI1145_REG_PS1_DATA0 0x26
#define SI1145_REG_PS1_DATA1 0x27
#define SI1145_REG_COMMAND 0x18
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_RESET 0x01
#define SI1145_HW_KEY_VAL 0x17
#define SI1145_PART_ID_VAL 0x45
#define I2C_BUS 1
#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
    }
    return result;
}

static int read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
    }
    return result;
}

static int initialize_sensor(int handle) {
    int part_id = read_register(handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID_VAL) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID_VAL);
        return -1;
    }

    if (write_register(handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        return -1;
    }

    if (write_register(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0) {
        fprintf(stderr, "Failed to write MEAS_RATE0\n");
        return -1;
    }

    if (write_register(handle, SI1145_REG_PS_LED21, 0x03) < 0) {
        fprintf(stderr, "Failed to write PS_LED21\n");
        return -1;
    }

    return 0;
}

static int read_proximity(int handle) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadWordData(handle, SI1145_REG_PS1_DATA0);
        if (result >= 0) {
            return result;
        }
        retries++;
        fprintf(stderr, "I2C read error (attempt %d/%d): %s\n", retries, MAX_RETRIES, strerror(errno));
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
    }

    fprintf(stderr, "Failed to read proximity after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_data(FILE *fp, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %u\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, proximity);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int proximity = read_proximity(i2c_handle);
        if (proximity >= 0) {
            log_data(log_file, (uint16_t)proximity);
        } else {
            log_error(log_file, "Failed to read proximity data");
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

