#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define SPEED_OF_SOUND_CM_PER_US 0.0343f
#define DISTANCE_THRESHOLD_CM   20.0f
#define TRIGGER_PULSE_US        10
#define LOOP_DELAY_US           1000000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_received = 0;
static volatile int      running = 1;

static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    if (level == 1) {
        start_tick = tick;
        echo_received = 0;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
    }
}

static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
    }
}

static float calculate_distance(uint32_t start, uint32_t end)
{
    uint32_t diff = end - start;
    return (float)diff * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

static void set_buzzer(int on)
{
    if (gpioWrite(BUZZER_PIN, on ? 1 : 0) < 0) {
        fprintf(stderr, "Error: failed to write buzzer pin\n");
    }
}

static void cleanup(void)
{
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on echo pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: failed to set alert function on echo pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise buzzer pin low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 Ultrasonic Distance Measurement\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Buzzer: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.1f cm | Loop delay: %d us\n",
           DISTANCE_THRESHOLD_CM, LOOP_DELAY_US);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        trigger_sensor();

        uint32_t waited = 0;
        while (!echo_received && waited < 30000 && running) {
            gpioDelay(100);
            waited += 100;
        }

        if (!running) {
            break;
        }

        if (!echo_received) {
            fprintf(stderr, "Warning: echo timeout (no object detected)\n");
            set_buzzer(0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float distance = calculate_distance(start_tick, end_tick);
        printf("Distance: %.2f cm\n", distance);

        if (distance < DISTANCE_THRESHOLD_CM) {
            set_buzzer(1);
        } else {
            set_buzzer(0);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

