/*
 * VL53L1X Time-of-Flight Sensor – Gate Controller
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: VL53L1X, default I2C address 0x29
 * Servo:  GPIO18 (BCM), hardware PWM capable
 *
 * Build:  gcc -O2 -Wall -o gate_ctrl gate_ctrl.c -lpigpio -lrt
 * Run:    sudo ./gate_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define VL53L1X_ADDR        0x29
#define SERVO_PIN           18          /* BCM 18 – hardware PWM */

#define DIST_THRESHOLD_FAR  250         /* mm – gate opens above this */
#define DIST_THRESHOLD_NEAR 200         /* mm – gate closes below this */

#define SERVO_PULSE_OPEN    1000        /* µs – gate fully open */
#define SERVO_PULSE_CLOSE   2000        /* µs – gate fully closed */

#define LOG_FILE            "gate_log.txt"
#define POLL_DELAY_US       50000       /* 50 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_IDENTIFICATION_MODEL_ID  0x010F
#define REG_SYSTEM_MODE_START        0x0000
#define REG_RESULT_RANGE_STATUS      0x0089
#define REG_RESULT_DISTANCE          0x0096
#define REG_SYSTEM_INTERRUPT_CLEAR   0x0086
#define REG_SYSTEM_INTERRUPT_CONFIG  0x000A
#define REG_GPIO_HV_MUX_CTRL         0x0030
#define REG_GPIO_TIO_HV_STATUS       0x0031
#define REG_SYSTEM_INTERRUPT_STATUS  0x0044
#define REG_RESULT_INTERRUPT_STATUS  0x0046
#define REG_SYSTEM_RANGE_CONFIG      0x005E
#define REG_SYSTEM_INTERMEASUREMENT  0x006B
#define REG_SYSTEM_THRESH_HIGH       0x007C
#define REG_SYSTEM_THRESH_LOW        0x007E
#define REG_SYSTEM_SEQUENCE_CONFIG   0x0001

#define EXPECTED_MODEL_ID            0xEACC

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers -------------------------------- */
/* Write a 16-bit register address (big-endian) followed by a byte. */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)((reg >> 8) & 0xFF);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Write a 16-bit register address (big-endian) followed by a 16-bit value (big-endian). */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (char)((reg >> 8) & 0xFF);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)((value >> 8) & 0xFF);
    buf[3] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register address (big-endian) then read `len` bytes. */
static int vl53l1x_read_reg(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (char)((reg >> 8) & 0xFF);
    addr[1] = (char)(reg & 0xFF);
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* --------------------------- VL53L1X driver ----------------------------- */
static int vl53l1x_init(int handle)
{
    uint8_t id = 0;

    /* Verify model ID */
    if (vl53l1x_read_reg(handle, REG_IDENTIFICATION_MODEL_ID, &id, 1) < 0) {
        fprintf(stderr, "[ERROR] Failed to read model ID register.\n");
        return -1;
    }
    uint16_t model_id = ((uint16_t)id << 8) | id;
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "[ERROR] Unexpected model ID: 0x%04X (expected 0x%04X).\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("[INFO] VL53L1X detected (model ID 0x%04X).\n", model_id);

    /* Data init */
    if (vl53l1x_write_reg8(handle, 0x0207, 0x01) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x0208, 0x01) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x0096, 0x00) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x0097, 0xFD) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00E3, 0x00) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00E4, 0x04) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00E5, 0x02) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00E6, 0x01) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00E7, 0x03) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00F5, 0x02) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00D9, 0x05) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00DB, 0xCE) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00DC, 0x03) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00DD, 0xF8) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x009F, 0x00) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00A3, 0x3C) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00B7, 0x00) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00BB, 0x3C) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00B2, 0x09) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00CA, 0x09) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x0198, 0x01) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x01B0, 0x17) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x01AD, 0x00) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x00FF, 0x05) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x0100, 0x05) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x0199, 0x05) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x01A6, 0x1B) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x01AC, 0x3E) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x01A7, 0x1F) < 0) return -1;
    if (vl53l1x_write_reg8(handle, 0x0030, 0x00) < 0) return -1;

    /* Set timing budget to 50 ms (0x006B = 100 ms, 0x005E = 50 ms) */
    if (vl53l1x_write_reg16(handle, REG_SYSTEM_INTERMEASUREMENT, 0x006B) < 0) return -1;
    if (vl53l1x_write_reg16(handle, REG_SYSTEM_RANGE_CONFIG, 0x005E) < 0) return -1;

    /* Set threshold high and low (mm) */
    if (vl53l1x_write_reg16(handle, REG_SYSTEM_THRESH_HIGH, DIST_THRESHOLD_FAR) < 0) return -1;
    if (vl53l1x_write_reg16(handle, REG_SYSTEM_THRESH_LOW,  DIST_THRESHOLD_NEAR) < 0) return -1;

    /* Start ranging */
    if (vl53l1x_write_reg8(handle, REG_SYSTEM_MODE_START, 0x40) < 0) return -1;

    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t status = 0;
    uint8_t buf[2];

    /* Poll for data ready (bit 0 of RESULT_INTERRUPT_STATUS) */
    for (int i = 0; i < 100; i++) {
        if (vl53l1x_read_reg(handle, REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
        if (i == 99) {
            fprintf(stderr, "[WARN] Timeout waiting for data ready.\n");
            return -1;
        }
    }

    /* Read 16-bit distance (big-endian) */
    if (vl53l1x_read_reg(handle, REG_RESULT_DISTANCE, buf, 2) < 0)
        return -1;

    *distance = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------- Servo ----------------------------------- */
static void servo_set_pulse(int pin, int pulse_us)
{
    if (pulse_us < 500)   pulse_us = 500;
    if (pulse_us > 2500)  pulse_us = 2500;
    gpioServo(pin, pulse_us);
}

/* ------------------------------- Logging ---------------------------------- */
static void log_event(const char *event)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s: %s\n", timestamp, event);
    fflush(g_log_file);
    printf("%s: %s\n", timestamp, event);
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        vl53l1x_write_reg8(g_i2c_handle, REG_SYSTEM_MODE_START, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioServo(SERVO_PIN, 0);
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] Failed to open I2C bus %d at addr 0x%02X (err %d).\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure servo pin */
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioServo(SERVO_PIN, 0); /* stop PWM initially */

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Gate controller started. Press Ctrl+C to exit.\n");

    int gate_open = 0;
    int last_distance = -1;

    while (g_running) {
        uint16_t distance = 0;

        if (vl53l1x_read_distance(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "[ERROR] I2C read failure – continuing.\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Hysteresis control */
        if (distance > DIST_THRESHOLD_FAR && !gate_open) {
            servo_set_pulse(SERVO_PIN, SERVO_PULSE_OPEN);
            log_event("Gate opened.");
            gate_open = 1;
        } else if (distance < DIST_THRESHOLD_NEAR && gate_open) {
            servo_set_pulse(SERVO_PIN, SERVO_PULSE_CLOSE);
            log_event("Gate closed.");
            gate_open = 0;
        }

        last_distance = (int)distance;
        gpioDelay(POLL_DELAY_US);
    }

    printf("\n[INFO] Shutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

