#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define TRIGGER_PULSE_US 10
#define TIMEOUT_US       50000   /* 50 ms */
#define LOOP_DELAY_US    100000  /* 100 ms */

#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define MIN_ANGLE_DEG    0.0
#define MAX_ANGLE_DEG    180.0

#define SERVO_MIN_US 500
#define SERVO_MAX_US 2500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm using the HC-SR04.
 * Returns distance >= 0 on success, -1.0 on timeout/error.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }

    /* Wait for echo rising edge */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * 0.01715f; /* speed of sound ~343 m/s */

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }

    return distance;
}

/*
 * Map distance (cm) to servo angle (degrees).
 * 20 cm -> 0 deg, 200 cm -> 180 deg, linear interpolation in between.
 */
static float distance_to_angle(float distance)
{
    if (distance < MIN_DISTANCE_CM)
        return MIN_ANGLE_DEG;
    if (distance > MAX_DISTANCE_CM)
        return MAX_ANGLE_DEG;

    return MIN_ANGLE_DEG +
           (distance - MIN_DISTANCE_CM) *
           (MAX_ANGLE_DEG - MIN_ANGLE_DEG) /
           (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
}

/*
 * Set servo angle (degrees) using the SG90 servo.
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(float angle)
{
    if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
        fprintf(stderr, "Error: angle %.2f out of valid range [%.0f, %.0f]\n",
                angle, MIN_ANGLE_DEG, MAX_ANGLE_DEG);
        return -1;
    }

    float pulse_us = SERVO_MIN_US +
                     (angle - MIN_ANGLE_DEG) *
                     (SERVO_MAX_US - SERVO_MIN_US) /
                     (MAX_ANGLE_DEG - MIN_ANGLE_DEG);

    if (gpioServo(SERVO_PIN, (unsigned)pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %.0f us\n", pulse_us);
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Register signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();
        float angle;

        if (distance < 0.0f) {
            fprintf(stderr, "Error: measurement failed, skipping servo update\n");
        } else {
            angle = distance_to_angle(distance);
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Error: failed to set servo angle\n");
            } else {
                printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
            }
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        uint32_t remaining = LOOP_DELAY_US;
        while (remaining > 0 && running) {
            uint32_t chunk = (remaining > 10000) ? 10000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    /* Clean shutdown: stop servo and terminate pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

