    printf("Logging every 2 seconds. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t raw_temp, raw_humid;
        float temp_c, humid_rh;

        /* Trigger temperature measurement */
        if (si7005_write_reg(g_i2c_fd, SI7005_REG_TEMP_HOLD, 0x00) != 0) {
            fprintf(stderr, "Failed to trigger temperature measurement; re-opening I2C.\n");
