#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si7005 constants (per datasheet) ---- */
#define SI7005_ADDR             0x40
#define SI7005_REG_CONFIG       0x01
#define SI7005_REG_TEMP_HOLD    0xE3
#define SI7005_REG_HUMID_HOLD   0xE5

/* CONFIG register bits */
#define SI7005_CONFIG_HEAT      0x00
#define SI7005_CONFIG_11_BIT    0x00
#define SI7005_CONFIG_12_BIT    0x01
#define SI7005_CONFIG_14_BIT    0x02
#define SI7005_CONFIG_16_BIT    0x03

/* Conversion times (datasheet: typ 10 ms, max 12.1 ms for 12-bit) */
#define SI7005_CONV_TEMP_MS     12
#define SI7005_CONV_HUMID_MS    12

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si7005 register. Returns 0 on success, -1 on error. */
static int si7005_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si7005 register. Returns 0 on success, -1 on error. */
static int si7005_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }

    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit measurement from a Si7005 register (MSB first).        */
static int si7005_read_measurement(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t msb, lsb;
    if (si7005_read_reg(fd, reg, &msb) != 0)
        return -1;
    if (si7005_read_reg(fd, reg + 1, &lsb) != 0)
        return -1;
    *out = ((uint16_t)msb << 8) | lsb;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si7005: set 12-bit resolution, no heater.            */
static int si7005_init(int fd)
{
    uint8_t config = SI7005_CONFIG_12_BIT | SI7005_CONFIG_HEAT;
    if (si7005_write_reg(fd, SI7005_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Failed to configure Si7005\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw temperature to Celsius.                                */
static float si7005_convert_temp(uint16_t raw)
{
    return (175.72f * raw / 65536.0f) - 46.85f;
}

/* ------------------------------------------------------------------ */
