        close_i2c();
        return EXIT_FAILURE;
    }

    printf("Si7005 initialized on /dev/i2c-1 at address 0x%02X.\n", SI7005_ADDR);
    printf("Logging every 2 seconds. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t raw_temp, raw_humid;
        float temp_c, humid_rh;

        /* Trigger temperature measurement */
        if (si7005_write_reg(g_i2c_fd, SI7005_REG_TEMP_HOLD, 0x00) != 0) {
            fprintf(stderr, "Failed to trigger temperature measurement; re-opening I2C.\n");
            close_i2c();
            sleep(1);
            g_i2c_fd = open_i2c();
            if (g_i2c_fd < 0) {
                fprintf(stderr, "I2C re-open failed; exiting.\n");
                return EXIT_FAILURE;
            }
            continue;
        }

        usleep(SI7005_CONV_TEMP_MS * 1000);

        if (si7005_read_measurement(g_i2c_fd, SI7005_REG_TEMP_HOLD, &raw_temp) != 0) {
            fprintf(stderr, "Failed to read temperature; re-opening I2C.\n");
            close_i2c();
            sleep(1);
            g_i2c_fd = open_i2c();
            if (g_i2c_fd < 0) {
                fprintf(stderr, "I2C re-open failed; exiting.\n");
                return EXIT_FAILURE;
            }
            continue;
        }

        /* Trigger humidity measurement */
        if (si7005_write_reg(g_i2c_fd, SI7005_REG_HUMID_HOLD, 0x00) != 0) {
            fprintf(stderr, "Failed to trigger humidity measurement; re-opening I2C.\n");
