/*
 * MPU-6050 I2C reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (SDA=GPIO2, SCL=GPIO3), Address: 0x68
 * Reads accelerometer and gyroscope data every 100 ms.
 *
 * Build: gcc -O2 -Wall -o mpu6050_reader mpu6050_reader.c -lpigpio -lrt
 * Run:   sudo ./mpu6050_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_WHO_AM_I    0x75
#define MPU6050_WHO_AM_I_VAL 0x68
#define MPU6050_PWR_MGMT_1  0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_TEMP_OUT_H  0x41
#define MPU6050_GYRO_XOUT_H  0x43

#define SAMPLE_PERIOD_US   100000  /* 100 ms */

/* ---- Globals for signal-handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an 8-bit register. Returns 0 on success, -1 on
 * error. */
static int mpu_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, v);
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register. Returns 0 on success, -1 on
 * error. */
static int mpu_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes starting at `reg` (auto-increment). Returns 0 on
 * success, -1 on error. */
static int mpu_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) got %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify the MPU-6050 is present by reading WHO_AM_I. */
static bool mpu_verify_sensor(int handle)
{
    uint8_t who;
    if (mpu_read_reg8(handle, MPU6050_WHO_AM_I, &who) != 0) {
        fprintf(stderr, "[ERROR] Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return false;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who, MPU6050_WHO_AM_I_VAL);
        return false;
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* Initialise the MPU-6050: wake up from sleep, verify sensor. */
static bool mpu_init(int handle)
{
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 (bit 6). */
    if (mpu_write_reg8(handle, MPU6050_PWR_MGMT_1, 0x00) != 0)
        return false;

    /* Allow oscillator to stabilise after wake-up. */
    gpioDelay(100000); /* 100 ms */

    return mpu_verify_sensor(handle);
}

/* ------------------------------------------------------------------ */
/* Parse the 14-byte raw block into big-endian int16 values. */
static void mpu_parse_data(const uint8_t *raw,
                           int16_t *ax, int16_t *ay, int16_t *az,
                           int16_t *temp,
                           int16_t *gx, int16_t *gy, int16_t *gz)
{
    *ax = (int16_t)((raw[0]  << 8) | raw[1]);
    *ay = (int16_t)((raw[2]  << 8) | raw[3]);
    *az = (int16_t)((raw[4]  << 8) | raw[5]);
    /* raw[6..7] = temperature (skipped) */
    *gx = (int16_t)((raw[8]  << 8) | raw[9]);
    *gy = (int16_t)((raw[10] << 8) | raw[11]);
    *gz = (int16_t)((raw[12] << 8) | raw[13]);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at MPU-6050 address ---- */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence ---- */
    if (!mpu_verify_sensor(g_i2c_handle)) {
        fprintf(stderr, "[FATAL] MPU-6050 not detected at 0x%02X.\n", MPU6050_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (!mpu_init(g_i2c_handle)) {
        fprintf(stderr, "[FATAL] MPU-6050 initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 reader started. Press Ctrl+C to stop.\n");
    printf("Accel (X/Y/Z)  |  Temp  |  Gyro (X/Y/Z)\n");
    printf("--------------|-------|--------------\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint8_t raw[14];

        if (mpu_read_block(g_i2c_handle, MPU6050_ACCEL_XOUT_H, raw, sizeof(raw)) != 0) {
            fprintf(stderr, "[WARN] I2C read error — continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int16_t ax, ay, az, temp, gx, gy, gz;
        mpu_parse_data(raw, &ax, &ay, &az, &temp, &gx, &gy, &gz);

        printf("%6d %6d %6d | %6d | %6d %6d %6d\n",
               ax, ay, az, temp, gx, gy, gz);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

