}

/* ------------------------------------------------------------------ */
/* Verify the MPU-6050 is present by reading WHO_AM_I. */
static bool mpu_verify_sensor(int handle)
{
    uint8_t who;
    if (mpu_read_reg8(handle, MPU6050_WHO_AM_I, &who) != 0) {
        fprintf(stderr, "[ERROR] Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return false;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who, MPU6050_WHO_AM_I_VAL);
        return false;
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* Initialise the MPU-6050: wake up from sleep, verify sensor. */
static bool mpu_init(int handle)
{
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 (bit 6). */
    if (mpu_write_reg8(handle, MPU6050_PWR_MGMT_1, 0x00) != 0)
        return false;

    /* Allow oscillator to stabilise after wake-up. */
    gpioDelay(100000); /* 100 ms */

    return mpu_verify_sensor(handle);
}

/* ------------------------------------------------------------------ */
/* Parse the 14-byte raw block into big-endian int16 values. */
static void mpu_parse_data(const uint8_t *raw,
                           int16_t *ax, int16_t *ay, int16_t *az,
                           int16_t *temp,
                           int16_t *gx, int16_t *gy, int16_t *gz)
{
    *ax = (int16_t)((raw[0]  << 8) | raw[1]);
    *ay = (int16_t)((raw[2]  << 8) | raw[3]);
    *az = (int16_t)((raw[4]  << 8) | raw[5]);
    /* raw[6..7] = temperature (skipped) */
    *gx = (int16_t)((raw[8]  << 8) | raw[9]);
    *gy = (int16_t)((raw[10] << 8) | raw[11]);
    *gz = (int16_t)((raw[12] << 8) | raw[13]);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at MPU-6050 address ---- */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence ---- */
    if (!mpu_verify_sensor(g_i2c_handle)) {
        fprintf(stderr, "[FATAL] MPU-6050 not detected at 0x%02X.\n", MPU6050_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (!mpu_init(g_i2c_handle)) {
        fprintf(stderr, "[FATAL] MPU-6050 initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 reader started. Press Ctrl+C to stop.\n");
    printf("Accel (X/Y/Z)  |  Temp  |  Gyro (X/Y/Z)\n");
    printf("--------------|-------|--------------\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint8_t raw[14];

        if (mpu_read_block(g_i2c_handle, MPU6050_ACCEL_XOUT_H, raw, sizeof(raw)) != 0) {
            fprintf(stderr, "[WARN] I2C read error — continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int16_t ax, ay, az, temp, gx, gy, gz;
        mpu_parse_data(raw, &ax, &ay, &az, &temp, &gx, &gy, &gz);

        printf("%6d %6d %6d | %6d | %6d %6d %6d\n",
               ax, ay, az, temp, gx, gy, gz);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

code:
/*
 * SHT40 Temperature & Humidity Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SHT40 VCC  -> Pi 3V3  (Pin 1)
 *   SHT40 GND  -> Pi GND  (Pin 9)
 *   SHT40 SDA  -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *   SHT40 SCL  -> Pi GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sht40_logger sht40_logger.c -lgpiod
 *
 * Run:
 *   ./sht40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x44
#define CMD_MEASURE    0x2C06   /* High repeatability, clock stretching disabled */
#define MEASURE_DELAY_MS 10
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* CRC-8 as defined by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int sht40_read(int fd, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {
        (uint8_t)((CMD_MEASURE >> 8) & 0xFF),
        (uint8_t)(CMD_MEASURE & 0xFF)
    };
    uint8_t buf[6];

    /* Send measurement command */
    if (write(fd, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    usleep(MEASURE_DELAY_MS * 1000);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: expected 6 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* Validate CRCs */
    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    /* Convert raw values */
    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t rh_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)rh_raw / 65535.0f;

    /* Clamp humidity to physical range */
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("SHT40 logger started on %s (addr 0x%02X). Press Ctrl+C to stop.\n",
           I2C_BUS, SHT40_ADDR);

    while (g_running) {
        fd = i2c_open(I2C_BUS, SHT40_ADDR);
        if (fd < 0) {
            fprintf(stderr, "Re-opening I2C bus in 5 s...\n");
            sleep(5);
            continue;
        }

        float temperature, humidity;
        if (sht40_read(fd, &temperature, &humidity) == 0) {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
            printf("[%s] Temperature: %.2f C, Humidity: %.2f %%\n",
                   ts, temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed; re-opening I2C bus.\n");
        }

        close(fd);
        fd = -1;

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    if (fd >= 0)
        close(fd);
    return rc;
}

