#define MLX90614_ADDR  0x5A

/* MLX90614 register addresses (EEPROM-mapped) */
#define MLX90614_REG_TA  0x06   /* Ambient temperature */
#define MLX90614_REG_TO  0x07   /* Object temperature  */

#define LOG_FILE       "temperature_log.csv"
#define SAMPLE_PERIOD  5      /* seconds */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: got %zd bytes, %s\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* MLX90614 sends LSB first */
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Temperature conversion                                             */
/* ------------------------------------------------------------------ */
/*
 * MLX90614 raw value -> Celsius.
 * Resolution: 0.02 °C per LSB (16-bit signed).
 */
static float raw_to_celsius(uint16_t raw)
{
    return (float)raw * 0.02f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_temperature(FILE *fp, float ambient, float object)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, ambient, object) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Signal handling --------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus ------------------------------------------------ */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MLX90614_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* --- Open log file ----------------------------------------------- */
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,Ambient_C,Object_C\n");
        fflush(log_fp);
    }

    printf("MLX90614 logger started.  Logging to %s every %d s.  Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    /* --- Main sampling loop ------------------------------------------ */
    while (g_running) {
        uint16_t raw_amb = 0, raw_obj = 0;

        if (i2c_read_reg16(i2c_fd, MLX90614_REG_TA, &raw_amb) != 0) {
            fprintf(stderr, "Sensor read error — skipping sample.\n");
        } else if (i2c_read_reg16(i2c_fd, MLX90614_REG_TO, &raw_obj) != 0) {
            fprintf(stderr, "Sensor read error — skipping sample.\n");
        } else {
            float amb = raw_to_celsius(raw_amb);
            float obj = raw_to_celsius(raw_obj);

            if (log_temperature(log_fp, amb, obj) != 0) {
                fprintf(stderr, "Logging failed — continuing.\n");
            } else {
                printf("Ambient: %.2f °C  |  Object: %.2f °C\n", amb, obj);
            }
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    /* --- Clean shutdown ---------------------------------------------- */
    printf("\nShutting down...\n");
    if (fclose(log_fp) != 0) {
        fprintf(stderr, "fclose(log) failed: %s\n", strerror(errno));
    }
    if (close(i2c_fd) != 0) {
        fprintf(stderr, "close(i2c) failed: %s\n", strerror(errno));
    }

    printf("Resources released.  Goodbye.\n");
    return EXIT_SUCCESS;
}

