#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define STS30_ADDR             0x68
#define STS30_CMD_START_MEAS   0x2003
#define STS30_CMD_READ_MEAS    0xE000
#define STS30_CMD_SOFT_RESET   0x30A2
#define STS30_CMD_GET_ID       0xEF00
#define STS30_CMD_GET_DATA_READY 0xE4B8
#define STS30_CMD_SET_MEAS_RATE 0x4600

#define LOG_FILE               "enclosure_temp_log.txt"
#define ERROR_LOG_FILE         "error_log.txt"
#define SAMPLE_INTERVAL_SEC    5
#define MAX_RETRIES            3
#define MEAS_DELAY_US          20000
#define RESET_DELAY_US         100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen(error_log.txt)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s (errno=%d: %s)\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg, errno, strerror(errno));
    } else {
        fprintf(fp, "[unknown time] %s (errno=%d: %s)\n", msg, errno, strerror(errno));
    }
    fclose(fp);
}

static int i2c_write_cmd(uint16_t cmd) {
    char buf[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    if (i2cWriteDevice(g_i2c_handle, buf, 2) != 0) {
        log_error("i2cWriteDevice failed");
        return -1;
    }
    return 0;
}

static int i2c_read_data(uint8_t *buf, int len) {
    if (i2cReadDevice(g_i2c_handle, (char *)buf, len) != len) {
        log_error("i2cReadDevice failed");
        return -1;
    }
    return 0;
}

static int sts30_reset(void) {
    if (i2c_write_cmd(STS30_CMD_SOFT_RESET) != 0) return -1;
    gpioDelay(RESET_DELAY_US);
    return 0;
}

static int sts30_start_measurement(void) {
    if (i2c_write_cmd(STS30_CMD_START_MEAS) != 0) return -1;
    gpioDelay(MEAS_DELAY_US);
    return 0;
}

static int sts30_read_measurement(float *temperature) {
    uint8_t buf[6];
    if (i2c_write_cmd(STS30_CMD_READ_MEAS) != 0) return -1;
    gpioDelay(MEAS_DELAY_US);
    if (i2c_read_data(buf, 6) != 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temperature = -45.0f + 175.0f * (float)raw / 65535.0f;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("fopen(log_file) failed");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);
    } else {
        fprintf(fp, "[unknown time], %.2f\n", temperature);
    }
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, STS30_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", STS30_ADDR, g_i2c_handle);
        log_error("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    if (sts30_reset() != 0) {
        fprintf(stderr, "STS30 reset failed\n");
        cleanup();
        return 1;
    }

    if (sts30_start_measurement() != 0) {
        fprintf(stderr, "STS30 start measurement failed\n");
        cleanup();
        return 1;
    }

    while (g_running) {
        float temperature;
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sts30_read_measurement(&temperature) == 0) {
                success = 1;
                break;
            }
            gpioDelay(100000);
        }

        if (success) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature\n");
            } else {
                printf("Temperature: %.2f C\n", temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature after %d attempts\n", MAX_RETRIES);
            log_error("Failed to read temperature after retries");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

