/*
 * SDP31 differential pressure logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   SDP31 SDA  -> GPIO2  (pin 3, I²C bus 1)
 *   SDP31 SCL  -> GPIO3  (pin 5, I²C bus 1)
 *   SDP31 VDD  -> 3.3 V
 *   SDP31 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sdp31_logger sdp31_logger.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./sdp31_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SDP31_ADDR           0x25          /* SDP31 default I²C address (ADDR pin tied to GND) */
#define LOG_FILE             "airflow.log"
#define SAMPLE_INTERVAL_US   100000        /* 100 ms */
#define MEAS_DELAY_US        1000          /* 1 ms measurement conversion time */
#define MAX_RETRIES          3
#define RETRY_DELAY_US       10000         /* 10 ms initial retry delay */
#define CRC8_POLYNOMIAL      0x31
#define CRC8_INIT            0xFF

/* SDP31 continuous measurement command (mass flow mode, no averaging) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x2F };

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                 */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLYNOMIAL);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I²C helpers with retry                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_retry(int handle, const uint8_t *buf, uint32_t count)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, (char *)buf, count);
        if (rc == (int)count)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteDevice failed (attempt %d/%d): rc=%d\n",
                attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US * (1 << attempt));
    }
    return -1;
}

static int i2c_read_retry(int handle, uint8_t *buf, uint32_t count)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, count);
        if (rc == (int)count)
            return 0;
        fprintf(stderr, "[WARN] i2cReadDevice failed (attempt %d/%d): rc=%d\n",
                attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US * (1 << attempt));
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor data conversion                                              */
/* ------------------------------------------------------------------ */
static int convert_data(const uint8_t *data, float *pressure, float *temperature)
{
    /* CRC checks */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);

    /* SDP31: 14-bit signed, LSB = 0.2 Pa */
    *pressure    = (float)raw_pressure    * 0.2f;
    *temperature = (float)raw_temperature * 0.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("[ERROR] time()");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("[ERROR] localtime_r()");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        perror("[ERROR] fprintf()");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("[ERROR] fflush()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I²C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SDP31_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("[INFO] SDP31 logger started. Logging to %s every %d ms.\n",
           LOG_FILE, SAMPLE_INTERVAL_US / 1000);
    printf("[INFO] Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint8_t data[6];
        float   pressure, temperature;

        /* Trigger continuous measurement */
        if (i2c_write_retry(g_i2c_handle, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0) {
            fprintf(stderr, "[ERROR] Failed to trigger measurement\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Wait for conversion to complete */
        gpioDelay(MEAS_DELAY_US);

        /* Read 6 bytes: pressure(2)+crc, temperature(2)+crc */
        if (i2c_read_retry(g_i2c_handle, data, sizeof(data)) != 0) {
            fprintf(stderr, "[ERROR] Failed to read measurement data\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Convert and log */
        if (convert_data(data, &pressure, &temperature) == 0) {
            if (log_data(g_log_file, pressure, temperature) != 0) {
                fprintf(stderr, "[ERROR] Failed to log data\n");
            }
        } else {
            fprintf(stderr, "[ERROR] Data conversion failed\n");
        }

        /* Wait for next sample interval */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

