code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Si7015 I2C address (7-bit) */
#define SI7015_ADDR 0x40

/* Si7015 commands (No Hold Master mode) */
#define SI7015_CMD_MEASURE_TEMP_NO_HOLD  0xF3
#define SI7015_CMD_MEASURE_HUMID_NO_HOLD 0xF5

/* Measurement ready poll timeout (microseconds) */
#define SI7015_MEASURE_TIMEOUT_US 20000

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 5000000

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read temperature from Si7015 in No Hold Master mode */
static int read_temperature(int handle, float *temperature) {
    uint8_t cmd = SI7015_CMD_MEASURE_TEMP_NO_HOLD;
    uint8_t buf[2];
    int result;

    /* Send measurement command */
    result = i2cWriteDevice(handle, (char *)&cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command to I2C device: %s\n", strerror(errno));
        return -1;
    }

    /* Poll for measurement completion */
    gpioDelay(SI7015_MEASURE_TIMEOUT_US);

    /* Read 2 bytes of data */
    result = i2cReadDevice(handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data from I2C device: %s\n", strerror(errno));
        return -1;
    }

    /* Convert raw data to temperature (Celsius) */
    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
    *temperature = (175.72f * raw_temp / 65536.0f) - 46.85f;

    return 0;
}

/* Read humidity from Si7015 in No Hold Master mode */
static int read_humidity(int handle, float *humidity) {
    uint8_t cmd = SI7015_CMD_MEASURE_HUMID_NO_HOLD;
    uint8_t buf[2];
    int result;

    /* Send measurement command */
    result = i2cWriteDevice(handle, (char *)&cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command to I2C device: %s\n", strerror(errno));
        return -1;
    }

    /* Poll for measurement completion */
    gpioDelay(SI7015_MEASURE_TIMEOUT_US);

    /* Read 2 bytes of data */
    result = i2cReadDevice(handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data from I2C device: %s\n", strerror(errno));
        return -1;
    }

    /* Convert raw data to humidity (%RH) */
    uint16_t raw_humid = ((uint16_t)buf[0] << 8) | buf[1];
    *humidity = (125.0f * raw_humid / 65536.0f) - 6.0f;

    /* Clamp humidity to valid range */
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

/* Log data to file and console */
static void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(fp);
    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

int main(void) {
    float temperature, humidity;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at Si7015 address */
    i2c_handle = i2cOpen(1, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", SI7015_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }

