        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        /* Read temperature */
        if (read_temperature(i2c_handle, &temperature) == 0) {
            /* Read humidity */
            if (read_humidity(i2c_handle, &humidity) == 0) {
                /* Log data */
                log_data(log_file, temperature, humidity);
            } else {
                fprintf(stderr, "Failed to read humidity. Retrying in 5 seconds.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in 5 seconds.\n");
        }

        /* Wait 5 seconds before next sample */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

