/*
 * SDP800-500Pa differential pressure logger for Raspberry Pi 3 Model B+
 * Uses Linux I2C syscalls (no wiringPi dependency).
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25

/* Continuous measurement command (no averaging, no clock stretching) */
#define CMD_CONT_MEAS  0x362F

/* Measurement conversion time (datasheet: typ. 45 ms) */
#define MEAS_DELAY_MS  45

/* Sampling interval */
#define SAMPLE_MS      100

#define LOG_FILE       "airflow_data.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF (Sensirion convention) */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* Write a 16-bit command to the SDP800 */
static int sdp_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(cmd 0x%04X) failed: %s (wrote %zd bytes)\n",
                cmd, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Read exactly `len` bytes from the SDP800 */
static int sdp_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "read: unexpected EOF (sensor may be absent)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* Trigger a continuous measurement and read the 9-byte result */
static int sdp_read_measurement(int fd, float *pressure, float *temperature)
{
    if (sdp_write_cmd(fd, CMD_CONT_MEAS) != 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    uint8_t raw[9];
    if (sdp_read_bytes(fd, raw, sizeof(raw)) != 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&raw[i * 3], 2) != raw[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_p = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t raw_t = (int16_t)((raw[3] << 8) | raw[4]);
    int16_t scale = (int16_t)((raw[6] << 8) | raw[7]);

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    *pressure    = (float)raw_p / (float)scale;
    *temperature = (float)raw_t / 200.0f;
    return 0;
}

static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SDP800_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,pressure_pa,temperature_c\n") < 0) {
            fprintf(stderr, "Failed to write header: %s\n", strerror(errno));
            fclose(fp);
            close(fd);
            return EXIT_FAILURE;
        }
        fflush(fp);
    }

    printf("SDP800 logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    int consecutive_errors = 0;

    while (g_running) {
        float pressure, temperature;

        if (sdp_read_measurement(fd, &pressure, &temperature) == 0) {
            consecutive_errors = 0;
            if (log_data(fp, pressure, temperature) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Sensor read error (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors; aborting.\n");
                break;
            }
        }

        /* Sleep in 10 ms increments so signals are caught promptly */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 10)
            usleep(10 * 1000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    fclose(fp);
    close(fd);
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

