/*
 * Raspberry Pi Zero W – Sensirion STS30-DIS Temperature Logger
 *
 * Reads temperature from the STS30-DIS (I2C address 0x68) every 5 seconds
 * and logs successful readings with timestamps to enclosure_temp_log.txt.
 * On any I2C error, logs the error with a timestamp to error_log.txt and
 * continues sampling.  Handles SIGINT for graceful shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sts30_logger sts30_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS30_ADDR     0x68
#define LOG_FILE       "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

/*
 * STS30-DIS single-shot high-repeatability measurement command.
 * Value 0x240B: bit 15 = 1 (start measurement), bits 14:12 = 001 (high repeatability),
 *              bits 11:8  = 0000 (clock stretching disabled), bits 7:0 = 1011.
 */
#define STS30_CMD_MSB  0x24
#define STS30_CMD_LSB  0x0B

/* Conversion time for high-repeatability measurement is ~15 ms. */
#define STS30_CONV_MS  15

/* Sampling interval between readings. */
#define SAMPLE_MS      5000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
