/*
 * Si7021 humidity & temperature monitor with fan control.
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Si7021 at 0x40 (ADDR pin tied to GND)
 * Fan:    GPIO18 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_fan si7021_fan.c -lpigpio -lrt
 * Run:    sudo ./si7021_fan
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define SI7021_ADDR         0x40          /* ADDR pin tied to GND */
#define FAN_GPIO            18            /* BCM pin */

#define TEMP_HIGH_THRESHOLD 28.0f         /* °C — fan ON  */
#define TEMP_LOW_THRESHOLD  27.0f         /* °C — fan OFF */
#define FAN_ON_DELAY_US     10000         /* 10 ms after fan ON */
#define SAMPLE_INTERVAL_S   2             /* seconds between samples */
#define BUFFER_SIZE         60
#define MAX_RETRIES         3

/* Si7021 commands */
#define CMD_MEASURE_TEMP    0xE3          /* Hold master, no clock stretching */
#define CMD_READ_TEMP       0xE0          /* No master hold, clock stretching */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static bool     g_fan_on     = false;

/* Circular buffer of timestamped temperature readings */
typedef struct {
    time_t timestamp;
    float  temperature;
} Reading;

static Reading g_buffer[BUFFER_SIZE];
static int     g_buf_head = 0;
static int     g_buf_count = 0;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  read_temperature(float *temperature);
static void control_fan(float temperature);
static void add_reading(float temperature);
static void print_buffer(void);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C init -------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* --------------------------- Temperature read ----------------------------- */
/*
 * Returns 0 on success and stores temperature in °C.
 * Returns -1 on persistent failure.
 */
static int read_temperature(float *temperature)
{
    char cmd = CMD_MEASURE_TEMP;
    char buf[2];
    int  rc;

    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        /* Send measurement command (no register address) */
        rc = i2cWriteDevice(g_i2c_handle, &cmd, 1);
        if (rc < 0) {
            fprintf(stderr, "[WARN] i2cWriteDevice (attempt %d/%d) failed: %d\n",
                    attempt, MAX_RETRIES, rc);
            gpioDelay(10000); /* 10 ms back-off */
            continue;
        }

        /* Wait for conversion to complete (~11 ms typ) */
        gpioDelay(15000);

        /* Read 2 bytes: MSB first, then LSB */
        rc = i2cReadDevice(g_i2c_handle, buf, 2);
        if (rc != 2) {
            fprintf(stderr, "[WARN] i2cReadDevice (attempt %d/%d) returned %d\n",
                    attempt, MAX_RETRIES, rc);
            gpioDelay(10000);
            continue;
        }

        uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
        *temperature = (175.72f * raw) / 65536.0f - 46.85f;
        return 0;
    }

    fprintf(stderr, "[ERROR] Temperature read failed after %d attempts.\n",
            MAX_RETRIES);
    return -1;
}

/* ------------------------------- Fan control ------------------------------ */
static void control_fan(float temperature)
{
    if (temperature > TEMP_HIGH_THRESHOLD && !g_fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            g_fan_on = true;
            printf("[INFO] Fan ON  (T=%.2f C)\n", temperature);
        } else {
            fprintf(stderr, "[ERROR] gpioWrite(FAN_GPIO, 1) failed\n");
        }
    } else if (temperature < TEMP_LOW_THRESHOLD && g_fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            g_fan_on = false;
            printf("[INFO] Fan OFF (T=%.2f C)\n", temperature);
        } else {
            fprintf(stderr, "[ERROR] gpioWrite(FAN_GPIO, 0) failed\n");
        }
    }
}

/* ----------------------------- Circular buffer --------------------------- */
static void add_reading(float temperature)
{
    time(&g_buffer[g_buf_head].timestamp);
    g_buffer[g_buf_head].temperature = temperature;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

static void print_buffer(void)
{
    printf("\n--- Temperature Log (%d entries) ---\n", g_buf_count);
    for (int i = 0; i < g_buf_count; ++i) {
        int idx = (g_buf_head - g_buf_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&g_buffer[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] T = %.2f C\n", ts, g_buffer[idx].temperature);
    }
    printf("---------------------------------------\n");
    fflush(stdout);
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Ensure fan is off */
    if (g_fan_on) {
        gpioWrite(FAN_GPIO, 0);
        g_fan_on = false;
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);
    g_fan_on = false;

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 fan monitor started.  Bus=%d  Addr=0x%02X  Fan=GPIO%d\n",
           I2C_BUS, SI7021_ADDR, FAN_GPIO);
    printf("Thresholds: ON > %.1f C, OFF < %.1f C  Sample every %d s\n",
           TEMP_HIGH_THRESHOLD, TEMP_LOW_THRESHOLD, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main sampling loop */
    while (g_running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            printf("[DATA] T = %.2f C\n", temperature);
            add_reading(temperature);
            control_fan(temperature);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; fan may be stuck.\n");
        }

        /* Wait for next sample interval (interruptible by signals) */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; ++s)
            sleep(1);
    }

    printf("\nShutting down...\n");
    print_buffer();
    cleanup();
    return EXIT_SUCCESS;
}

