/*
 * SCD40 CO2 Monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SCD40 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o scd40_monitor scd40_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./scd40_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define SCD40_ADDR          0x61          /* SCD40 default I2C address */
#define LOG_FILE            "air_quality.log"
#define SAMPLE_INTERVAL_S   5             /* seconds between readings */
#define MEASUREMENT_DELAY_S 1             /* first measurement after reset */

/* SCD40 commands (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC  0x21B1
#define CMD_STOP_PERIODIC   0x3F86
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_GET_DATA_READY   0xE4B8

/* CRC-8 parameters used by Sensirion (poly 0x31, init 0xFF) */
#define CRC8_POLYNOMIAL     0x31
#define CRC8_INIT           0xFF

/* ------------------------------- Globals --------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static uint8_t crc8(const uint8_t *data, size_t len);
static int  scd40_write_command(uint16_t cmd);
static int  scd40_read_measurement(uint16_t *co2, uint16_t *temp, uint16_t *rh);
static int  scd40_data_ready(uint8_t *ready);
static int  log_data(uint16_t co2, uint16_t temp, uint16_t rh);
static void cleanup(void);

/* ------------------------------- CRC-8 ----------------------------------- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLYNOMIAL);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- I²C helpers -------------------------------- */
static int scd40_write_command(uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/*
 * Read 9 bytes from the SCD40: 3 words × (2 data + 1 CRC).
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int scd40_read_measurement(uint16_t *co2, uint16_t *temp, uint16_t *rh)
{
    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected 9 bytes, got %d\n", rc);
        return -1;
    }

    /* CRC check on each 2-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on CO2 word\n");
        return -2;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] CRC mismatch on temperature word\n");
        return -2;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] CRC mismatch on humidity word\n");
        return -2;
    }

    *co2  = (uint16_t)((buf[0] << 8) | buf[1]);
    *temp = (uint16_t)((buf[3] << 8) | buf[4]);
    *rh   = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

/*
 * Poll the data-ready flag.
 * Returns 1 if data is ready, 0 if not, -1 on I/O error.
 */
static int scd40_data_ready(uint8_t *ready)
{
    if (scd40_write_command(CMD_GET_DATA_READY) != 0)
        return -1;

    gpioDelay(2000); /* 2 ms processing time */

    uint8_t buf[3];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "[ERROR] i2cReadDevice (data-ready) expected 3 bytes, got %d\n", rc);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on data-ready word\n");
        return -1;
    }

    uint16_t word = (uint16_t)((buf[0] << 8) | buf[1]);
    *ready = (word & 0x07FF) ? 1 : 0;
    return 0;
}

/* ------------------------------- Logging --------------------------------- */
static int log_data(uint16_t co2, uint16_t temp, uint16_t rh)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%u,%u,%u\n", ts, co2, temp, rh) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        /* Best-effort stop of periodic measurement */
        (void)scd40_write_command(CMD_STOP_PERIODIC);
        gpioDelay(2000); /* 2 ms processing time */
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------ Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Open I²C bus */
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SCD40_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    /* Start periodic measurement */
    if (scd40_write_command(CMD_START_PERIODIC) != 0) {
        fprintf(stderr, "[FATAL] Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow first measurement to complete */
    sleep(MEASUREMENT_DELAY_S);

    fprintf(stderr, "[INFO] SCD40 monitoring started. Logging to '%s' every %d s.\n",
            LOG_FILE, SAMPLE_INTERVAL_S);
    fprintf(stderr, "[INFO] Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        uint8_t ready = 0;

        if (scd40_data_ready(&ready) != 0) {
            fprintf(stderr, "[WARN] Data-ready check failed; retrying in %d s.\n",
                    SAMPLE_INTERVAL_S);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        if (!ready) {
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        uint16_t co2, temp, rh;
        int rc = scd40_read_measurement(&co2, &temp, &rh);
        if (rc == 0) {
            if (log_data(co2, temp, rh) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            } else {
                fprintf(stderr, "[INFO] CO2: %u ppm, Temp: %u C, RH: %u %%\n",
                        co2, temp, rh);
            }
        } else if (rc == -1) {
            fprintf(stderr, "[WARN] I/O error reading measurement; retrying in %d s.\n",
                    SAMPLE_INTERVAL_S);
        } else {
            fprintf(stderr, "[WARN] CRC mismatch on measurement; retrying in %d s.\n",
                    SAMPLE_INTERVAL_S);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    fprintf(stderr, "\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

