/*
 * SCD40 CO2 Monitor — Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   SCD40 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *   LED anode -> GPIO17 (BCM) via 330 Ω resistor -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o scd40_monitor scd40_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./scd40_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SCD40_ADDR           0x61          /* SCD40 default I2C address (ADDR pin tied to GND) */
#define GPIO_LED             17            /* BCM pin for the warning LED */
#define CO2_THRESHOLD_PPM    1000
#define BUFFER_SIZE          20
#define SAMPLE_INTERVAL_S    5

/* SCD40 command opcodes (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC   0x21B1
#define CMD_STOP_PERIODIC    0x3F86
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_GET_DATA_READY   0xE4B8
#define CMD_SOFT_RESET       0xD304

/* ------------------------------- Globals --------------------------------- */
static int      g_i2c_handle = -1;
static volatile sig_atomic_t g_terminate = 0;

/* --------------------------- Circular buffer ----------------------------- */
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float    temperature;
    float    humidity;
} sensor_data_t;

static sensor_data_t g_buffer[BUFFER_SIZE];
static int           g_buf_head = 0;   /* next write slot */
static int           g_buf_count = 0; /* number of valid entries */

/* --------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* --------------------------- CRC-8 (Sensirion: poly 0x31, init 0xFF) --------------------------- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            crc = (crc & 0x80) ? (uint8_t)((crc << 1) ^ 0x31)
                               : (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- I2C helpers ------------------------------- */
static int i2c_write_cmd(uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t *buf, size_t len)
{
    if (i2cReadDevice(g_i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %zu bytes\n", len);
        return -1;
    }
    return 0;
}

/* --------------------------- SCD40 commands ----------------------------- */
static int scd40_start_periodic(void)
{
    return i2c_write_cmd(CMD_START_PERIODIC);
}

static int scd40_stop_periodic(void)
{
    return i2c_write_cmd(CMD_STOP_PERIODIC);
}

static int scd40_soft_reset(void)
{
    return i2c_write_cmd(CMD_SOFT_RESET);
}

static int scd40_get_data_ready(uint16_t *ready)
{
    if (i2c_write_cmd(CMD_GET_DATA_READY) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms processing time */

    uint8_t buf[3];
    if (i2c_read_block(buf, sizeof(buf)) != 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on data-ready word\n");
        return -1;
    }
    *ready = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int scd40_read_measurement(uint16_t *co2, float *temp, float *rh)
{
    if (i2c_write_cmd(CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms processing time */

    uint8_t buf[9];
    if (i2c_read_block(buf, sizeof(buf)) != 0)
        return -1;

    /* Validate CRC for each 2-byte data word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on CO2 word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[WARN] CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[WARN] CRC mismatch on humidity word\n");
        return -1;
    }

    *co2    = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t t_raw = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t h_raw = (uint16_t)((buf[6] << 8) | buf[7]);

    *temp   = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh     = 100.0f * (float)h_raw / 65535.0f;
    return 0;
}

/* --------------------------- Circular buffer ----------------------------- */
static void buffer_add(uint16_t co2, float temp, float rh)
{
    g_buffer[g_buf_head].timestamp  = time(NULL);
    g_buffer[g_buf_head].co2        = co2;
    g_buffer[g_buf_head].temperature = temp;
    g_buffer[g_buf_head].humidity    = rh;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

static void buffer_print(void)
{
    printf("\n--- Circular Buffer (%d entries) ---\n", g_buf_count);
    for (int i = 0; i < g_buf_count; i++) {
        int idx = (g_buf_head - g_buf_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&g_buffer[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] CO2: %u ppm, T: %.2f C, RH: %.2f %%\n",
               ts, g_buffer[idx].co2,
               g_buffer[idx].temperature, g_buffer[idx].humidity);
    }
    printf("--------------------------------------\n");
}

/* --------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SCD40_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Soft reset --- */
    if (scd40_soft_reset() != 0) {
        fprintf(stderr, "[FATAL] SCD40 soft reset failed — sensor may be absent\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(20000); /* 20 ms for reset to complete */

    /* --- Start periodic measurement --- */
    if (scd40_start_periodic() != 0) {
        fprintf(stderr, "[FATAL] Failed to start periodic measurement\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_LED);
        scd40_stop_periodic();
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (!g_terminate) {
        uint16_t ready = 0;
        if (scd40_get_data_ready(&ready) != 0) {
            fprintf(stderr, "[WARN] get_data_ready failed; retrying next cycle\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        if (ready == 0) {
            /* No new data yet — wait and retry */
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        uint16_t co2 = 0;
        float    temp = 0.0f, rh = 0.0f;
        if (scd40_read_measurement(&co2, &temp, &rh) != 0) {
            fprintf(stderr, "[WARN] read_measurement failed; retrying next cycle\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        buffer_add(co2, temp, rh);
        buffer_print();

        /* Warning LED */
        gpioWrite(GPIO_LED, (co2 > CO2_THRESHOLD_PPM) ? 1 : 0);

        sleep(SAMPLE_INTERVAL_S);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    scd40_stop_periodic();
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

