/*
 * TMP05 temperature logger for Raspberry Pi 4 Model B
 *
 * Reads the PWM-style output on GPIO4 (BCM 4, physical pin 7) and computes
 * the temperature using the TMP05 datasheet formula:
 *
 *   T = (TH * 256 + TL) / 100 - 40
 *
 * where TH is the high-time count and TL is the low-time count.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp05_logger tmp05_logger.c -lrt
 * Run:    ./tmp05_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip4"   /* BCM GPIO controller on Pi 4/5 */
#define GPIO_LINE_OFFSET   4             /* BCM 4, physical pin 7 */

#define LOG_FILE_NAME      "temperature_log.txt"
#define SAMPLE_INTERVAL_S  5
#define EDGE_TIMEOUT_US    50000         /* 50 ms per edge wait */
#define MAX_CONSECUTIVE_ERRORS 3

#define TEMP_MIN_C         (-40.0f)
#define TEMP_MAX_C         (150.0f)

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    if (!g_log_fp)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log_fp, "%s: %s\n", ts, msg);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Busy-wait timestamp helpers (microseconds)                          */
/* ------------------------------------------------------------------ */
static uint64_t now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
        return 0;
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

static void sleep_us(uint64_t us)
{
    struct timespec ts = {
        .tv_sec  = (time_t)(us / 1000000ULL),
        .tv_nsec = (long)((us % 1000000ULL) * 1000ULL)
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* TMP05 PWM measurement                                               */
/* ------------------------------------------------------------------ */
/*
 * TMP05 PWM output:
 *   - Idle low (0 V)
 *   - High pulse width proportional to temperature
 *   - Low pulse width proportional to temperature
 *
 * We sample the line at 100 kHz (10 µs period) and count the high-time
 * and low-time counts.  A timeout is applied to each edge so we can
 * detect a stuck line or sensor absent.
 */
static int read_tmp05(struct gpiod_line *line, float *temperature)
{
    uint64_t t0, t_edge;
    int high_count = 0, low_count = 0;
    int state;

    /* --- Wait for line to go HIGH (start of high pulse) --- */
    t0 = now_us();
    state = gpiod_line_get_value(line);
    if (state < 0) {
        log_message("Error: failed to read GPIO line value");
        return -1;
    }
    if (state == 1) {
        /* Already high — skip the initial wait */
        t_edge = t0;
    } else {
        while (gpiod_line_get_value(line) == 0) {
            if (now_us() - t0 > EDGE_TIMEOUT_US) {
                log_message("Error: timeout waiting for TMP05 high-pulse start");
                return -1;
            }
        }
        t_edge = now_us();
    }

    /* --- Count high-time pulses --- */
    while (gpiod_line_get_value(line) == 1) {
        high_count++;
        sleep_us(10);
        if (now_us() - t_edge > EDGE_TIMEOUT_US) {
            log_message("Error: timeout during TMP05 high-pulse measurement");
            return -1;
        }
    }
    t_edge = now_us();

    /* --- Count low-time pulses --- */
    while (gpiod_line_get_value(line) == 0) {
        low_count++;
        sleep_us(10);
        if (now_us() - t_edge > EDGE_TIMEOUT_US) {
            log_message("Error: timeout during TMP05 low-pulse measurement");
            return -1;
        }
    }

    /* --- Convert counts to temperature (datasheet formula) --- */
    int th = high_count;
    int tl = low_count;
    float temp = ((float)th * 256.0f + (float)tl) / 100.0f - 40.0f;

    /* Sanity range check */
    if (temp < TEMP_MIN_C || temp > TEMP_MAX_C) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Warning: temperature out of range: %.2f C (TH=%d, TL=%d)",
                 temp, th, tl);
        log_message(msg);
        return -1;
    }

    *temperature = temp;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int consecutive_errors = 0;
    int ret_code = EXIT_FAILURE;

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE_NAME ")");
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        log_message("Error: failed to open gpiochip4");
        goto cleanup;
    }

    /* --- Get GPIO line --- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        log_message("Error: failed to get GPIO line 4");
        goto cleanup;
    }

    /* --- Request line as input --- */
    if (gpiod_line_request_input(line, "tmp05_logger") < 0) {
        perror("gpiod_line_request_input");
        log_message("Error: failed to request GPIO line 4 as input");
        goto cleanup;
    }

    log_message("TMP05 logger started (GPIO4, BCM)");

    /* --- Main sampling loop --- */
    while (g_running) {
        float temperature;

        if (read_tmp05(line, &temperature) == 0) {
            consecutive_errors = 0;

            char msg[128];
            snprintf(msg, sizeof(msg), "Temperature: %.2f C", temperature);
            log_message(msg);
        } else {
            consecutive_errors++;
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Error: failed to read temperature (consecutive=%d)",
                     consecutive_errors);
            log_message(msg);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_message("SENSOR MALFUNCTION");
                consecutive_errors = 0;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            sleep_us(100000);
    }

    log_message("Shutting down...");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    if (g_log_fp)
        fclose(g_log_fp);

    return ret_code;
}

