#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH_REP 0x2C06
#define MEASUREMENT_DELAY_US 15000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define SAMPLE_INTERVAL_US 5000000
#define OFFSET_PERIOD_US 3600000000
#define LOG_FILE "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} SensorData;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, addr 0x%02X (pigpio error %d)\n",
                I2C_BUS, SHT35_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sht35(SensorData *data) {
    uint8_t cmd[2] = {
        (MEASURE_CMD_HIGH_REP >> 8) & 0xFF,
        MEASURE_CMD_HIGH_REP & 0xFF
    };
    uint8_t buf[6];

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "Warning: I2C write failed (attempt %d/%d)\n", attempt + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "Warning: I2C read failed (attempt %d/%d)\n", attempt + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Warning: Temperature CRC mismatch (attempt %d/%d)\n", attempt + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Warning: Humidity CRC mismatch (attempt %d/%d)\n", attempt + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        uint16_t raw_hum  = (buf[3] << 8) | buf[4];

        data->temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);
        data->humidity    = 100.0f * (float)raw_hum / 65535.0f;
        return 0;
    }
    return -1;
}

static float apply_sinusoidal_offset(float base, float amplitude, float period_us, uint64_t now_us) {
    float phase = (float)(now_us % period_us) / period_us * 2.0f * M_PI;
    return base + amplitude * sinf(phase);
}

static void log_data(float temp, float hum) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", ts, temp, hum);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    uint64_t start_time = gpioTick();
    SensorData sensor_data;

    while (!terminate) {
        if (read_sht35(&sensor_data) == 0) {
            uint64_t now_us = gpioTick();
            float offset_temp = apply_sinusoidal_offset(sensor_data.temperature, 2.0f, OFFSET_PERIOD_US, now_us);
            float offset_hum  = apply_sinusoidal_offset(sensor_data.humidity, 5.0f, OFFSET_PERIOD_US, now_us);
            log_data(offset_temp, offset_hum);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data after %d retries\n", RETRY_COUNT);
            log_data(NAN, NAN);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

