        uint16_t raw_hum  = (buf[3] << 8) | buf[4];

        data->temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);
        data->humidity    = 100.0f * (float)raw_hum / 65535.0f;
        return 0;
    }
    return -1;
}

static float apply_sinusoidal_offset(float base, float amplitude, float period_us, uint64_t now_us) {
    float phase = (float)(now_us % period_us) / period_us * 2.0f * M_PI;
    return base + amplitude * sinf(phase);
}

static void log_data(float temp, float hum) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", ts, temp, hum);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    uint64_t start_time = gpioTick();
    SensorData sensor_data;

    while (!terminate) {
        if (read_sht35(&sensor_data) == 0) {
            uint64_t now_us = gpioTick();
            float offset_temp = apply_sinusoidal_offset(sensor_data.temperature, 2.0f, OFFSET_PERIOD_US, now_us);
            float offset_hum  = apply_sinusoidal_offset(sensor_data.humidity, 5.0f, OFFSET_PERIOD_US, now_us);
            log_data(offset_temp, offset_hum);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data after %d retries\n", RETRY_COUNT);
            log_data(NAN, NAN);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

