/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   SDP810 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   SDP810 VDD  -> 3.3 V (pin 1)
 *   SDP810 GND  -> GND  (pin 6)
 *
 * I2C address: 0x25 (SDP810 default)
 * Continuous measurement command: 0x362F (MSB first)
 * Conversion time: ~45 ms
 *
 * Build: gcc -O2 -Wall -o airflow airflow.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x25
#define CMD_CONT_MEAS  0x362F
#define CSV_FILENAME   "airflow.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define CONV_DELAY_MS  45         /* conversion time */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                 */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: got %zd of %zu (%s)\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data conversion                                              */
/* ------------------------------------------------------------------ */
static int convert_data(const uint8_t *raw, float *pressure, float *temperature)
{
    /* Pressure: bytes 0-1, scale factor: byte 2 */
    int16_t raw_p = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t raw_t = (int16_t)((raw[3] << 8) | raw[4]);
    int16_t raw_s = (int16_t)((raw[6] << 8) | raw[7]);

    if (raw_s == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    /* SDP810 conversion formulas */
    *pressure    = (float)raw_p / (float)raw_s;
    *temperature = (float)raw_t / 200.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush CSV failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV file */
    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,pressure_pa,temperature_c\n");
        fflush(g_csv);
    }

    printf("SDP810 airflow logger started. Logging to %s every %d s.\n",
           CSV_FILENAME, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint8_t raw[9];
        float pressure = 0.0f, temperature = 0.0f;
        int ok = 0;

        /* Send continuous measurement command */
        if (i2c_write_cmd(g_i2c_fd, CMD_CONT_MEAS) != 0) {
            fprintf(stderr, "Sensor absent or bus error — retrying in %d s\n",
                    SAMPLE_PERIOD);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Wait for conversion */
        usleep(CONV_DELAY_MS * 1000);

        /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, scale(2)+crc */
        if (i2c_read_block(g_i2c_fd, raw, sizeof(raw)) != 0) {
            fprintf(stderr, "Sensor read error — retrying in %d s\n",
                    SAMPLE_PERIOD);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Validate CRCs */
        if (crc8(&raw[0], 2) != raw[2] ||
            crc8(&raw[3], 2) != raw[5] ||
            crc8(&raw[6], 2) != raw[8]) {
            fprintf(stderr, "CRC mismatch — skipping sample\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Convert */
        if (convert_data(raw, &pressure, &temperature) == 0) {
            ok = 1;
        } else {
            fprintf(stderr, "Conversion error — skipping sample\n");
        }

        if (ok) {
            if (log_data(g_csv, pressure, temperature) != 0) {
                fprintf(stderr, "Logging failed — continuing\n");
            } else {
                printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                       pressure, temperature);
            }
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

