code:
/*
 * SHT35-DIS-B temperature & humidity logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   SHT35 VDD  -> Pi 3V3  (pin 1)
 *   SHT35 GND  -> Pi GND  (pin 9)
 *   SHT35 SDA  -> Pi GPIO2 / I2C bus 1 SDA (pin 3)
 *   SHT35 SCL  -> Pi GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht35_logger sht35_logger.c -lsht35
 * Run:    ./sht35_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <sht35.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44
#define CSV_FILENAME   "environment.csv"
#define SAMPLE_PERIOD  5          /* seconds between readings */
#define MEAS_DELAY_MS  15         /* SHT35 high-repeatability max conversion time */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* CSV file helpers                                                    */
/* ------------------------------------------------------------------ */
static int csv_needs_header(const char *path)
{
    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        /* File does not exist yet — write header. */
        return 1;
    }
    if (fseek(fp, 0, SEEK_END) != 0) {
        perror("fseek");
        fclose(fp);
        return 0;
    }
    long sz = ftell(fp);
    fclose(fp);
    return (sz <= 0);
}

static int write_csv_header(const char *path)
{
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        perror("fopen(csv header)");
        return -1;
    }
    if (fprintf(fp, "timestamp,temperature_c,humidity_pct\n") < 0) {
        perror("fprintf(csv header)");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose(csv header)");
        return -1;
    }
    return 0;
}

static int write_csv_row(const char *path, float temp_c, float rh_pct)
{
    FILE *fp = fopen(path, "a");
    if (fp == NULL) {
        perror("fopen(csv append)");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        fclose(fp);
        return -1;
    }

    struct tm tm_buf;
    struct tm *tm = localtime_r(&t, &tm_buf);
    if (tm == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh_pct) < 0) {
        perror("fprintf(csv row)");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose(csv append)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    /* --- Open I2C bus --- */
    int i2c_fd = i2c_open(I2C_BUS, SHT35_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "i2c_open(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SHT35_ADDR, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize sensor library --- */
    if (sht35_init(i2c_fd) != 0) {
        fprintf(stderr, "sht35_init failed (sensor may be absent or bus error)\n");
        goto cleanup_i2c;
    }

    /* --- Write CSV header if file is new/empty --- */
    if (csv_needs_header(CSV_FILENAME)) {
        if (write_csv_header(CSV_FILENAME) != 0) {
            fprintf(stderr, "Failed to write CSV header\n");
            goto cleanup_sht35;
        }
    }

    printf("SHT35 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           CSV_FILENAME, SAMPLE_PERIOD);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint8_t cmd[2] = {
            0x24, 0x00  /* single-shot, high repeatability, clock stretching disabled */
        };
        uint8_t data[6];

        /* Send measurement command */
        if (i2c_write(i2c_fd, (char *)cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
            fprintf(stderr, "i2c_write failed: %s\n", strerror(errno));
            goto cleanup_sht35;
        }

        /* Wait for conversion to complete */
        usleep(MEAS_DELAY_MS * 1000);

        /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
        ssize_t n = i2c_read(i2c_fd, (char *)data, sizeof(data));
        if (n != (ssize_t)sizeof(data)) {
            fprintf(stderr, "i2c_read failed: expected 6 bytes, got %zd (%s)\n",
                    n, n < 0 ? strerror(errno) : "short read");
            goto cleanup_sht35;
        }

        /* CRC validation */
        if (sht35_crc8(&data[0], 2) != data[2]) {
            fprintf(stderr, "Temperature CRC mismatch\n");
            goto cleanup_sht35;
        }
        if (sht35_crc8(&data[3], 2) != data[5]) {
            fprintf(stderr, "Humidity CRC mismatch\n");
            goto cleanup_sht35;
        }

        /* Convert raw values */
        uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
        uint16_t rh_raw = ((uint16_t)data[3] << 8) | data[4];

        float temp_c = -45.0f + (175.0f * (float)t_raw / 65535.0f);
        float rh_pct = 100.0f * (float)rh_raw / 65535.0f;

        /* Clamp humidity to physical range */
        if (rh_pct < 0.0f)   rh_pct = 0.0f;
        if (rh_pct > 100.0f) rh_pct = 100.0f;

        /* Log to CSV */
        if (write_csv_row(CSV_FILENAME, temp_c, rh_pct) != 0) {
            fprintf(stderr, "Failed to write CSV row\n");
            goto cleanup_sht35;
        }

        printf("%s  T=%.2f C  RH=%.2f %%\n",
               CSV_FILENAME, temp_c, rh_pct);

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup_sht35:
    sht35_shutdown(i2c_fd);

cleanup_i2c:
    if (i2c_close(i2c_fd) != 0)
        perror("i2c_close");

    return ret;
}

