        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Si7021 polynomial 0x31, init 0x00)                            */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Sensor read with CRC validation                                     */
/* ------------------------------------------------------------------ */
static int read_measurement(int fd, uint8_t cmd, uint16_t *raw_out)
{
    uint8_t buf[3];

    if (i2c_write_byte(fd, cmd) < 0)
        return -1;

    /* Wait for conversion to complete (max ~12 ms for RH, ~12 ms for T) */
    usleep(15000);

    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on measurement 0x%02X\n", cmd);
        return -1;
    }

    *raw_out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Temperature (°C)                                                    */
/* ------------------------------------------------------------------ */
static int read_temperature(int fd, float *temp_c)
{
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_TEMP_HOLD, &raw) < 0)
        return -1;
    *temp_c = (float)((175.72 * raw) / 65536.0 - 46.85);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relative humidity (%RH)                                             */
/* ------------------------------------------------------------------ */
static int read_humidity(int fd, float *rh_pct)
{
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_RH_HOLD, &raw) < 0)
        return -1;
    float h = (float)((125.0 * raw) / 65536.0 - 6.0);
    if (h < 0.0f)   h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    *rh_pct = h;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor reset                                                        */
/* ------------------------------------------------------------------ */
static int reset_sensor(int fd)
{
    if (i2c_write_byte(fd, CMD_RESET) < 0)
        return -1;
    usleep(15000); /* reset takes ~15 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float temp_c, float rh_pct)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
    fclose(fp);
    return 0;
}

static int log_error(const char *filename, const char *msg)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() < 0)
        return EXIT_FAILURE;

    g_i2c_fd = i2c_open(I2C_BUS, SI7021_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    /* Write CSV header if file is empty */
    {
        FILE *fp = fopen(LOG_FILE, "r");
        int need_header = (fp == NULL);
        if (fp) fclose(fp);
        if (need_header) {
            fp = fopen(LOG_FILE, "w");
            if (fp) {
                fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
                fclose(fp);
            }
        }
    }

    printf("Si7021 greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp_c = 0.0f, rh_pct = 0.0f;
        int ok = 1;

        if (read_temperature(g_i2c_fd, &temp_c) < 0) {
            fprintf(stderr, "Temperature read failed; resetting sensor.\n");
            log_error(LOG_FILE, "temperature read failed");
            ok = 0;
        }

        if (ok && read_humidity(g_i2c_fd, &rh_pct) < 0) {
            fprintf(stderr, "Humidity read failed; resetting sensor.\n");
            log_error(LOG_FILE, "humidity read failed");
            ok = 0;
        }

        if (ok) {
            if (log_data(LOG_FILE, temp_c, rh_pct) < 0)
                fprintf(stderr, "Warning: failed to log data.\n");
            else
                printf("%s  T=%.2f C  RH=%.2f %%\n",
                       LOG_FILE, temp_c, rh_pct);
        }

        /* Reset sensor on any failure to recover */
        if (!ok) {
            if (reset_sensor(g_i2c_fd) < 0)
                fprintf(stderr, "Warning: sensor reset failed.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

