#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/* SDP810-500Pa I2C address (7-bit) */
#define SDP810_ADDR 0x25

/* Continuous measurement command (no averaging, clock stretching disabled) */
#define SDP810_CMD_CONT_MEAS 0x362F

/* Conversion time for continuous measurement (datasheet: typ. 45 ms) */
#define SDP810_CONV_TIME_US 50000

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *data_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* CRC-8 calculation (polynomial 0x31, init 0xFF) per Sensirion datasheet */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

/* Initialize the SDP810 sensor */
static int init_sdp810(void) {
    uint8_t cmd[2];
    cmd[0] = (SDP810_CMD_CONT_MEAS >> 8) & 0xFF;
    cmd[1] = SDP810_CMD_CONT_MEAS & 0xFF;

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write continuous measurement command to SDP810.\n");
        return -1;
    }

    return 0;
}

/* Read raw data from the SDP810 sensor */
static int read_sdp810_data(int16_t *pressure_raw, int16_t *temperature_raw) {
    uint8_t buffer[9];

    /* Read 9 bytes: pressure MSB, pressure LSB, CRC, temperature MSB, temperature LSB, CRC, scale factor MSB, scale factor LSB, scale factor CRC */
    if (i2cReadDevice(i2c_handle, (char *)buffer, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from SDP810.\n");
        return -1;
    }

    /* Validate CRC for pressure (bytes 0-1, CRC at byte 2) */
    if (crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 3-4, CRC at byte 5) */
    if (crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }

    /* Extract raw values */
    *pressure_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    *temperature_raw = (int16_t)((buffer[3] << 8) | buffer[4]);

    return 0;
}

/* Convert raw data to physical units */
static void convert_data(int16_t pressure_raw, int16_t temperature_raw, float *pressure, float *temperature) {
    /* SDP810-500Pa: pressure scale factor = 200, temperature scale factor = 200 */
    const float pressure_scale = 200.0f;
    const float temperature_scale = 200.0f;

    *pressure = (float)pressure_raw / pressure_scale;
    *temperature = (float)temperature_raw / temperature_scale;
}

/* Log data to a binary file */
static int log_data(float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, data_file) != 1) {
        fprintf(stderr, "Error: Failed to write pressure to file.\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, data_file) != 1) {
        fprintf(stderr, "Error: Failed to write temperature to file.\n");
        return -1;
    }
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at SDP810 address */
    i2c_handle = i2cOpen(1, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", SDP810_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the SDP810 sensor */
    if (init_sdp810() != 0) {
        fprintf(stderr, "Error: SDP810 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the data file in binary append mode */
    data_file = fopen("airflow.dat", "ab");
    if (data_file == NULL) {
        fprintf(stderr, "Error: Failed to open airflow.dat for writing.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler.\n");
    }

    int16_t pressure_raw, temperature_raw;
    float pressure, temperature;

    /* Main loop */
    while (!terminate) {
        /* Read sensor data */
        if (read_sdp810_data(&pressure_raw, &temperature_raw) == 0) {
            /* Convert data */
            convert_data(pressure_raw, temperature_raw, &pressure, &temperature);

            /* Log data */
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        /* Wait for the next sample (45 ms conversion time + margin) */
        gpioDelay(SDP810_CONV_TIME_US + 10000);
    }

    /* Cleanup */
    printf("\nShutting down gracefully...\n");

    if (data_file != NULL) {
        fclose(data_file);
        data_file = NULL;
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

