/*
 * SDP800-500Pa differential pressure logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800_logger sdp800_logger.c -lpigpio -lrt
 * Run:    sudo ./sdp800_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define SDP800_ADDR         0x25          /* SDP800-500Pa default I2C address */
#define LOG_FILE            "pressure_log.txt"
#define SAMPLE_INTERVAL_S   5
#define CONVERSION_DELAY_US 45000         /* 45 ms conversion time */
#define READ_RETRIES        3
#define READ_RETRY_DELAY_US 10000         /* 10 ms between retries */

/* SDP800 continuous measurement command (mass flow mode, no averaging) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x2F };

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static void cleanup(void);
static uint8_t crc8(const uint8_t *data, int len);
static int  sdp800_init(void);
static int  sdp800_read_pressure(float *pressure_pa);
static int  log_pressure(float pressure_pa);

/* ------------------------------- CRC-8 ---------------------------------- */
/* Sensirion polynomial 0x31, init 0xFF — matches SDP800 datasheet */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------- Sensor init -------------------------------- */
static int sdp800_init(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SDP800_ADDR, g_i2c_handle);
        return -1;
    }

    /* Send continuous measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)CMD_CONT_MEAS, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to send continuous measurement command\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* ------------------------- Read pressure data --------------------------- */
static int sdp800_read_pressure(float *pressure_pa)
{
    uint8_t buf[9];
    int     bytes_read;

    for (int attempt = 0; attempt < READ_RETRIES; attempt++) {
        /* Wait for conversion to complete */
        gpioDelay(CONVERSION_DELAY_US);

        bytes_read = i2cReadDevice(g_i2c_handle, (char *)buf, sizeof(buf));
        if (bytes_read == (int)sizeof(buf)) {
            /* Validate CRC for each 2-byte data word */
            for (int i = 0; i < 3; i++) {
                if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
                    fprintf(stderr, "[WARN] CRC mismatch on word %d (attempt %d)\n",
                            i, attempt + 1);
                    if (attempt < READ_RETRIES - 1)
                        gpioDelay(READ_RETRY_DELAY_US);
                    continue;
                }
            }

            /*
             * SDP800 continuous measurement output:
             *   Word 0: differential pressure (MSB, LSB)
             *   Word 1: temperature (MSB, LSB)
             *   Word 2: scale factor (MSB, LSB)
             *
             * Pressure is signed 16-bit, scale factor is signed 16-bit.
             */
            int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
            int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

            if (scale_factor == 0) {
                fprintf(stderr, "[WARN] Invalid scale factor (0) — skipping sample\n");
                if (attempt < READ_RETRIES - 1)
                    gpioDelay(READ_RETRY_DELAY_US);
                continue;
            }

            *pressure_pa = (float)raw_pressure / (float)scale_factor;
            return 0;
        }

        fprintf(stderr, "[WARN] I2C read returned %d bytes (attempt %d/%d)\n",
                bytes_read, attempt + 1, READ_RETRIES);
        if (attempt < READ_RETRIES - 1)
            gpioDelay(READ_RETRY_DELAY_US);
    }

    fprintf(stderr, "[ERROR] Failed to read valid pressure data after %d attempts\n",
            READ_RETRIES);
    return -1;
}

/* ------------------------------- Logging --------------------------------- */
static int log_pressure(float pressure_pa)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, %.2f Pa\n", timestamp, pressure_pa) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }

    return 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sdp800_init() != 0) {
        fprintf(stderr, "[FATAL] SDP800 initialization failed — check wiring and address\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("SDP800 logger started. Logging to '%s' every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    /* Main sampling loop */
    while (g_running) {
        float pressure_pa;

        if (sdp800_read_pressure(&pressure_pa) == 0) {
            if (log_pressure(pressure_pa) != 0) {
                fprintf(stderr, "[ERROR] Logging failed — continuing\n");
            }
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed — continuing\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

