#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_pressure(int handle, float *pressure) {
    char buf[2];
    int result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %d\n", result);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw * 0.1f;
    return 0;
}

static float calculate_flow_rate(float pressure) {
    return pressure * 0.01f;
}

static int set_fan_speed(int gpio, float flow_rate) {
    int duty_cycle = (int)(flow_rate * 100.0f);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    int pwm_range = 100;
    if (gpioSetPWMrange(gpio, pwm_range) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", gpio);
        return -1;
    }
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    while (running) {
        float pressure = 0.0f;
        if (read_pressure(i2c_handle, &pressure) == 0) {
            float flow_rate = calculate_flow_rate(pressure);
            if (set_fan_speed(FAN_GPIO, flow_rate) != 0) {
                fprintf(stderr, "Warning: failed to set fan speed\n");
            }
            if (log_data(log_file, pressure) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read pressure\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

