#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS        1
#define LPS33HW_ADDR   0x5C
#define LOG_FILE       "environmental_data.txt"
#define SAMPLE_PERIOD  1.0

/* LPS33HW register addresses */
#define CTRL_REG1      0x10
#define CTRL_REG2      0x11
#define PRESS_OUT_XL   0x28
#define TEMP_OUT_L     0x2B

/* CTRL_REG1: ODR=1Hz (0x10), BDU=1 (0x04) -> 0x14 */
#define CTRL_REG1_VAL  0x14

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(stderr, "[%s] ERROR: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));

    if (g_log_file) {
        fprintf(g_log_file, "[%s] ERROR: %s (errno=%d: %s)\n",
                ts, msg, errno, strerror(errno));
        fflush(g_log_file);
    }
}

static int init_lps33hw(void)
{
    /* Soft reset: write 0xB0 to CTRL_REG2 */
    if (i2cWriteByteData(g_i2c_handle, CTRL_REG2, 0xB0) < 0) {
        log_error("Failed to soft-reset LPS33HW");
        return -1;
    }
    gpioDelay(2000); /* 2 ms settle after reset */

    /* Configure: ODR=1Hz, BDU=1 */
    if (i2cWriteByteData(g_i2c_handle, CTRL_REG1, CTRL_REG1_VAL) < 0) {
        log_error("Failed to configure LPS33HW CTRL_REG1");
        return -1;
    }

    return 0;
}

static int read_pressure(float *pressure_hpa)
{
    char buf[3];
    int32_t raw;

    if (i2cReadI2CBlockData(g_i2c_handle, PRESS_OUT_XL, buf, 3) != 3) {
        log_error("Failed to read pressure data block");
        return -1;
    }

    raw = (int32_t)((uint32_t)buf[2] << 16 |
                   (uint32_t)buf[1] << 8  |
                   (uint32_t)buf[0]);
    /* Sign-extend 24-bit two's complement to 32-bit */
    if (raw & 0x00800000)
        raw |= 0xFF000000;

    *pressure_hpa = (float)raw / 4096.0f;
    return 0;
}

static int read_temperature(float *temp_c)
{
    char buf[2];
    int16_t raw;

