#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define STLM75_ADDR    0x48
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000

/* STLM75 registers */
#define STLM75_TEMP_REG 0x00
#define STLM75_CONF_REG 0x01

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature from the STLM75.
 * Returns 0 on success and stores the temperature in *out_temp;
 * returns -1 on I2C error.
 */
static int read_temperature(int handle, float *out_temp)
{
    int raw;

    raw = i2cReadWordData(handle, STLM75_TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register (pigpio code %d)\n", raw);
        return -1;
    }

    /* pigpio returns little-endian word; STLM75 sends MSB first */
    raw = ((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF);

    /* 12-bit two's complement, left-justified in 16 bits */
    int16_t temp_raw = (int16_t)raw;
    temp_raw >>= 4;

    *out_temp = (float)temp_raw * 0.0625f;
    return 0;
}

/*
 * Compute the running average of the last `count` elements in the buffer.
 * If count is 0 or the buffer is empty, returns 0.0.
 */
static float calculate_average(const float buffer[], int count)
{
    if (count <= 0)
        return 0.0f;

    float sum = 0.0f;
    for (int i = 0; i < count; i++)
        sum += buffer[i];

    return sum / (float)count;
}

int main(void)
{
    int i2c_handle = -1;
    float temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;
    bool led_state = false;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to STLM75 */
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X (pigpio code %d)\n",
                I2C_BUS, STLM75_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output and ensure it starts off */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;

        if (read_temperature(i2c_handle, &temperature) == 0) {
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE)
                buffer_count++;

            float average_temperature = calculate_average(temperature_buffer, buffer_count);

            if (average_temperature > TEMP_THRESHOLD) {
                if (!led_state) {
                    gpioWrite(LED_GPIO, 1);
                    led_state = true;
                    printf("Average temperature %.2f°C exceeds threshold %.1f°C — LED ON\n",
                           average_temperature, TEMP_THRESHOLD);
                }
            } else {
                if (led_state) {
                    gpioWrite(LED_GPIO, 0);
                    led_state = false;
                    printf("Average temperature %.2f°C below threshold %.1f°C — LED OFF\n",
                           average_temperature, TEMP_THRESHOLD);
                }
            }
        } else {
            fprintf(stderr, "Skipping iteration due to I2C read failure\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

