/*
 * SCD30 CO₂ / Temperature / Humidity Logger for Raspberry Pi 4 Model B
 *
 * Reads CO₂, temperature and humidity from a Sensirion SCD30 sensor on
 * the I2C bus every 5 seconds and logs each sample to air_quality.log
 * as CSV lines with an ISO-8601 UTC timestamp.  Implements ventilation
 * control logic where CO₂ below 800 ppm -> OFF, 800–1199 ppm -> LOW,
 * 1200 ppm or above -> HIGH.
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd30_logger scd30_logger.c -lscd30
 *
 * Run (hardware):  ./scd30_logger
 * Run (mocked):    ./scd30_logger --mock
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>

#include <scd30.h>

#define I2C_BUS          1
#define SCD30_ADDR       0x61
#define LOG_FILE         "air_quality.log"
#define SAMPLE_PERIOD_S  5

#define CO2_LOW_THRESHOLD   800
#define CO2_HIGH_THRESHOLD  1200

#define VENT_OFF  0
#define VENT_LOW  1
#define VENT_HIGH 2

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static bool     g_mock_mode  = false;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (gmtime_r(&now, &tm_utc) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    } else {
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00Z");
    }

    fprintf(g_log_file, "%s, %s\n", ts, msg);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(uint8_t cmd)
{
    if (g_mock_mode)
        return 0;

    if (i2cWriteByte(g_i2c_handle, cmd) != 0) {
        fprintf(stderr, "i2cWriteByte(0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t *buf, size_t len)
{
    if (g_mock_mode) {
        memset(buf, 0, len);
        return 0;
    }

    int n = i2cReadDevice(g_i2c_handle, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "i2cReadDevice expected %zu bytes, got %d: %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* SCD30 driver wrappers                                               */
/* ------------------------------------------------------------------ */
static int scd30_init(void)
{
    if (g_mock_mode)
        return 0;

    g_i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SCD30_ADDR, strerror(errno));
        return -1;
    }

    /* Soft reset */
    if (i2c_write_cmd(SCD30_CMD_RESET) != 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    usleep(20000); /* 20 ms reset settling */

    /* Set measurement interval to 5 s (0x0005) */
    uint8_t cmd[3] = { SCD30_CMD_MEASUREMENT_INTERVAL, 0x00, 0x05 };
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 3) != 0) {
        fprintf(stderr, "Failed to set measurement interval: %s\n",
                strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Start periodic measurement */
    if (i2c_write_cmd(SCD30_CMD_START_PERIODIC_MEASUREMENT) != 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int scd30_read_data(float *co2, float *temp, float *rh)
{
    if (g_mock_mode) {
        *co2 = 1000.0f;
        *temp = 25.0f;
        *rh = 50.0f;
        return 0;
    }

    /* Trigger a forced measurement */
    if (i2c_write_cmd(SCD30_CMD_FORCED_MEASUREMENT) != 0)
        return -1;
    usleep(20000); /* 20 ms conversion time */

    /* Read 9 bytes: 3 words × (2 data + 1 CRC) */
    uint8_t buf[9];
    if (i2c_read_block(buf, sizeof(buf)) != 0)
        return -1;

    /* CRC check on each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t rh_raw = ((uint16_t)buf[6] << 8) | buf[7];

    *co2 = (float)co2_raw;
    *temp = (float)temp_raw / 100.0f;
    *rh = (float)rh_raw / 100.0f;

    return 0;
}

static void scd30_cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2c_write_cmd(SCD30_CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        log_message("SCD30 measurement stopped.");
        fclose(g_log_file);
        g_log_file = NULL;
    }
    scd30_terminate();
}

/* ------------------------------------------------------------------ */
/* Ventilation control                                                 */
/* ------------------------------------------------------------------ */
static int control_ventilation(float co2)
{
    if (co2 < CO2_LOW_THRESHOLD)
        return VENT_OFF;
    if (co2 < CO2_HIGH_THRESHOLD)
        return VENT_LOW;
    return VENT_HIGH;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc > 1 && strcmp(argv[1], "--mock") == 0) {
