    /* CRC check on each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t rh_raw = ((uint16_t)buf[6] << 8) | buf[7];

    *co2 = (float)co2_raw;
    *temp = (float)temp_raw / 100.0f;
    *rh = (float)rh_raw / 100.0f;

    return 0;
}

static void scd30_cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2c_write_cmd(SCD30_CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        log_message("SCD30 measurement stopped.");
        fclose(g_log_file);
        g_log_file = NULL;
    }
    scd30_terminate();
}

/* ------------------------------------------------------------------ */
/* Ventilation control                                                 */
/* ------------------------------------------------------------------ */
static int control_ventilation(float co2)
{
    if (co2 < CO2_LOW_THRESHOLD)
        return VENT_OFF;
    if (co2 < CO2_HIGH_THRESHOLD)
        return VENT_LOW;
    return VENT_HIGH;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
