        g_mock_mode = true;
        printf("Running in mocked (emulated) mode — no hardware access.\n");
    }

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (scd30_init() != 0) {
        if (g_mock_mode) {
            printf("No SCD30 detected in mocked mode — exiting gracefully.\n");
            return EXIT_SUCCESS;
        }
        fprintf(stderr, "SCD30 initialization failed.\n");
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        scd30_cleanup();
        return EXIT_FAILURE;
    }

    log_message("SCD30 logger started.");

    while (g_running) {
        float co2, temp, rh;

        if (scd30_read_data(&co2, &temp, &rh) == 0) {
            int vent = control_ventilation(co2);
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "CO2=%.0f ppm, Temp=%.2f C, RH=%.2f %%RH, Vent=%s",
                     co2, temp, rh,
                     vent == VENT_OFF ? "OFF" :
                     vent == VENT_LOW ? "LOW" : "HIGH");
            log_message(msg);
        } else {
            log_message("Error reading sensor data.");
        }

        /* Sleep in 1 s increments so signals are caught promptly */
