/*
 * SDP32 differential pressure reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SDP32 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   SDP32 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   SDP32 VDD  -> 3.3 V
 *   SDP32 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp32_reader sdp32_reader.c
 * Run:    ./sdp32_reader [interval_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

#define I2C_BUS        1
#define SDP32_ADDR     0x25          /* SDP32 default I2C address (ADDR pin tied to GND) */
#define CMD_MEASURE    0x362F        /* Continuous measurement, clock stretching disabled */
#define CMD_STOP       0x3FF9        /* Stop continuous measurement */
#define MEASURE_DELAY  45000         /* 45 ms conversion time (datasheet: typ 40 ms) */
#define READ_LEN       9             /* 3 words × (2 data + 1 CRC) */
#define DEFAULT_MS     1000
#define MAX_MS         10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                 */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, size_t len)
{
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %d (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */
static int sdp32_start_measurement(void)
{
    return i2c_write_cmd(CMD_MEASURE);
}

static int sdp32_stop_measurement(void)
{
    return i2c_write_cmd(CMD_STOP);
}

/*
 * Read one 9-byte measurement frame.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int sdp32_read_measurement(uint8_t *data)
{
    if (i2c_read_bytes(data, READ_LEN) != 0)
        return -1;

    /* CRC checks: pressure, temperature, scale factor */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -2;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -2;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "CRC mismatch on scale-factor word\n");
        return -2;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int interval_ms = DEFAULT_MS;

    if (argc > 1) {
        char *endptr = NULL;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val <= 0 || val > MAX_MS) {
            fprintf(stderr, "Invalid interval '%s'. Using default %d ms.\n",
                    argv[1], DEFAULT_MS);
        } else {
            interval_ms = (int)val;
        }
    }

    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, SDP32_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Probe the sensor by sending a measurement command.
     * If the device NACKs, it is not present on the bus.
     */
    if (sdp32_start_measurement() != 0) {
        fprintf(stderr, "Sensor not responding at address 0x%02X on bus %d.\n",
                SDP32_ADDR, I2C_BUS);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow first conversion to complete */
    gpioDelay(MEASURE_DELAY);

    printf("SDP32 differential pressure reader started (interval %d ms).\n", interval_ms);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint8_t data[READ_LEN];
        int rc = sdp32_read_measurement(data);

        if (rc == 0) {
            /*
             * SDP32 data layout (9 bytes):
             *   bytes 0-1 : differential pressure (MSB, LSB)
             *   byte  2   : CRC-8 for pressure
             *   bytes 3-4 : temperature (MSB, LSB)
             *   byte  5   : CRC-8 for temperature
             *   bytes 6-7 : scale factor (MSB, LSB)
             *   byte  8   : CRC-8 for scale factor
             */
            int16_t pressure_raw = (int16_t)((data[0] << 8) | data[1]);
            int16_t temp_raw    = (int16_t)((data[3] << 8) | data[4]);
            int16_t scale_raw   = (int16_t)((data[6] << 8) | data[7]);

            /*
             * Per datasheet:
             *   pressure [Pa] = pressure_raw / scale_raw
             *   temperature [°C] = temp_raw / 200.0
             */
            float pressure = (float)pressure_raw / (float)scale_raw;
            float temperature = (float)temp_raw / 200.0f;

            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            printf("%s  Pressure: %.2f Pa  Temperature: %.2f °C\n",
                   ts, pressure, temperature);
            fflush(stdout);
        } else if (rc == -1) {
            /* I2C error – attempt to recover by stopping and restarting */
            fprintf(stderr, "I2C error, attempting to re-start measurement...\n");
            sdp32_stop_measurement();
            gpioDelay(MEASURE_DELAY);
            sdp32_start_measurement();
            gpioDelay(MEASURE_DELAY);
        } else {
            /* CRC mismatch – attempt to recover by stopping and restarting */
            fprintf(stderr, "CRC mismatch, attempting to re-start measurement...\n");
            sdp32_stop_measurement();
            gpioDelay(MEASURE_DELAY);
            sdp32_start_measurement();
            gpioDelay(MEASURE_DELAY);
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < interval_ms / 100 && g_running; i++)
            gpioDelay(100000);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    sdp32_stop_measurement();
    gpioDelay(MEASURE_DELAY);

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

