/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (BCM 2, physical pin 3)
 *   SDP810 SCL  -> GPIO3 (BCM 3, physical pin 5)
 *   SDP810 VDD  -> 3.3 V (physical pin 1)
 *   SDP810 GND  -> GND  (physical pin 6)
 *
 * I2C bus: /dev/i2c-1 (BCM GPIO2=SDA, BCM GPIO3=SCL), address 0x25.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_reader sdp810_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x25

/* SDP810 measurement command: continuous measurement, clock stretching disabled. */
#define SDP810_CMD_MSB 0x36
#define SDP810_CMD_LSB 0x2F

/* Conversion time for SDP810-125Pa (datasheet: typ. 45 ms). */
#define SDP810_CONV_MS 45

/* Sampling interval between readings. */
#define SAMPLE_MS      1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: polynomial 0x31, initial value 0xFF. */
static bool sdp_crc8(const uint8_t *data, size_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            crc = (crc & 0x80) ? (uint8_t)((crc << 1) ^ 0x31)
                               : (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

/*
 * Trigger a continuous measurement and read 9 bytes back.
 * Layout: [P_MSB, P_LSB, P_CRC, T_MSB, T_LSB, T_CRC, S_MSB, S_LSB, S_CRC].
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int sdp810_read(int fd, float *pressure, float *temperature)
{
    uint8_t cmd[2] = { SDP810_CMD_MSB, SDP810_CMD_LSB };
    uint8_t buf[9];

    /* Send measurement command. */
    if (write(fd, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete. */
    struct timespec ts = { 0, SDP810_CONV_MS * 1000000L };
    nanosleep(&ts, NULL);

    /* Read 9 bytes: pressure(2) + scale(2) + temperature(2) + scale(2). */
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                sizeof(buf), n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* Validate CRC for each 3-byte word. */
    if (!sdp_crc8(&buf[0], 2, buf[2])) {
        fprintf(stderr, "CRC mismatch on pressure word\n");
        return -2;
    }
    if (!sdp_crc8(&buf[3], 2, buf[5])) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -2;
    }
    if (!sdp_crc8(&buf[6], 2, buf[8])) {
        fprintf(stderr, "CRC mismatch on scale word\n");
        return -2;
    }

    /*
     * SDP810 scale factors are signed 16-bit integers.
     * Pressure and temperature are signed 16-bit integers.
     */
    int16_t p_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t t_raw = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t s_raw = (int16_t)((buf[6] << 8) | buf[7]);

    if (s_raw == 0) {
        fprintf(stderr, "Invalid scale factor (0) — sensor may be absent\n");
        return -2;
    }

    *pressure    = (float)p_raw / (float)s_raw;
    *temperature = (float)t_raw / (float)s_raw;

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the SDP810 slave address. */
    if (ioctl(fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("SDP810 reader started on %s (addr 0x%02X). Press Ctrl+C to stop.\n",
           I2C_BUS, SDP810_ADDR);

    /* Main sampling loop. */
    while (g_running) {
        float pressure, temperature;

        int ret = sdp810_read(fd, &pressure, &temperature);
        if (ret == 0) {
            printf("Pressure: %.4f Pa, Temperature: %.4f °C\n",
                   pressure, temperature);
            fflush(stdout);
        } else if (ret == -2) {
            fprintf(stderr, "Sensor data CRC mismatch — continuing\n");
        } else {
            fprintf(stderr, "Sensor read error — continuing\n");
        }

        /* Sleep SAMPLE_MS, but wake early on signal. */
        struct timespec rem;
        struct timespec req = { SAMPLE_MS / 1000, (SAMPLE_MS % 1000) * 1000000L };
        while (nanosleep(&req, &rem) == -1 && errno == EINTR) {
            if (!g_running) {
                break;
            }
            req = rem;
        }
    }

    printf("\nShutting down...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

