#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define HDC1000_ADDR        0x40
#define I2C_BUS             "/dev/i2c-1"
#define CONVERSION_DELAY_MS 20
#define SAMPLE_INTERVAL_S   5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed (0x%02X): %s\n", byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (expected %zu, got %zd): %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int hdc1000_trigger_and_read(int fd, float *temperature, float *humidity)
{
    /*
     * Trigger a 14-bit temperature and humidity conversion.
     * Bit 15 = 1 (start conversion), bits 14:12 = 000 (14-bit T + 14-bit RH).
     */
    uint8_t trigger = 0x80;
    if (i2c_write_byte(fd, trigger) < 0)
        return -1;

    usleep(CONVERSION_DELAY_MS * 1000);

    uint8_t data[4];
    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    uint16_t raw_temp = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_hum  = ((uint16_t)data[2] << 8) | data[3];

    *temperature = (float)raw_temp / 65536.0f * 165.0f - 40.0f;
    *humidity    = (float)raw_hum  / 65536.0f * 100.0f;

    return 0;
}

int main(void)
{
    int fd = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        fprintf(stderr, "Hint: enable I2C with 'sudo raspi-config' and ensure user is in the 'i2c' group.\n");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * Probe the sensor by reading the device ID register (0xFE).
     * If the sensor is absent or the bus is unresponsive, the read will fail.
     */
    uint8_t id_reg = 0xFE;
    if (i2c_write_byte(fd, id_reg) < 0) {
        fprintf(stderr, "HDC1000 not detected at address 0x%02X on %s\n",
                HDC1000_ADDR, I2C_BUS);
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t id[2];
    if (i2c_read_bytes(fd, id, sizeof(id)) < 0) {
        fprintf(stderr, "Failed to read HDC1000 device ID\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 detected (ID: 0x%02X%02X). Logging every %d seconds.\n",
           id[0], id[1], SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;

        if (hdc1000_trigger_and_read(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /*
         * Sleep in 1-second increments so signals are caught promptly.
         */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nExiting gracefully...\n");
    if (fd >= 0)
        close(fd);

    return EXIT_SUCCESS;
}

