/*
 * MLX90833 Pressure Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MLX90833 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90833 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90833 VDD -> 3.3 V
 *   MLX90833 GND -> GND
 *
 * The MLX90833 is a differential pressure sensor; this program reads the
 * absolute pressure register (0x00) and converts it to a signed 16-bit
 * value.  The sensor is assumed to be configured for differential mode
 * (0x00) and the pressure register is assumed to hold a signed 16-bit
 * value in units of 0.1 Pa.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90833_reader mlx90833_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90833_ADDR  0x28          /* Default I2C address (ADDR pin tied to GND) */
#define PRESSURE_REG   0x00          /* Absolute pressure register (differential mode) */
#define SAMPLE_PERIOD  500000        /* 500 ms in microseconds */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_word(int handle, uint8_t reg, int16_t *out)
{
    /*
     * pigpio's i2cReadWordData returns the word as (msb << 8) | lsb,
     * which matches the MLX90833 register layout.
     */
    int raw = i2cReadWordData(handle, reg);
    if (raw < 0) {
        return -1;
    }
    *out = (int16_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }

    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("[%s] ", buf);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to MLX90833 */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X). "
                        "Check wiring and that the sensor is present.\n",
                I2C_BUS, MLX90833_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    install_signal_handlers();

    printf("MLX90833 Pressure Sensor Reader\n");
    printf("I2C bus %d, address 0x%02X, register 0x%02X\n",
           I2C_BUS, MLX90833_ADDR, PRESSURE_REG);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t raw_pressure = 0;

        if (i2c_read_word(g_i2c_handle, PRESSURE_REG, &raw_pressure) != 0) {
            print_timestamp();
            fprintf(stderr, "Error: I2C read failed (reg 0x%02X).\n",
                    PRESSURE_REG);
        } else {
            print_timestamp();
            printf("Pressure: %d Pa\n", raw_pressure);
            fflush(stdout);
        }

        /* Sleep 500 ms; gpioDelay is microseconds */
        gpioDelay(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        if (i2cClose(g_i2c_handle) != 0) {
            fprintf(stderr, "Warning: i2cClose failed.\n");
        }
        g_i2c_handle = -1;
    }

    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

