#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10101_ADDR  0x60

/* ICP-10101 register addresses */
#define REG_MEAS_MSB   0x00
#define REG_MEAS_LSB   0x01
#define REG_MEAS_XLSB  0x02
#define REG_TEMP_MSB   0x03
#define REG_TEMP_LSB   0x04
#define REG_TEMP_XLSB  0x05
#define REG_PRESS_MSB  0x06
#define REG_PRESS_LSB  0x07
#define REG_PRESS_XLSB 0x08
#define REG_ID_MSB     0x0D
#define REG_ID_LSB     0x0E

/* Expected chip ID for ICP-10101 (0x50) */
#define ICP10101_ID    0x50

/* Measurement command: bit 7 = 1, bits 6:4 = 000 (continuous), bits 3:0 = 0000 */
#define CMD_MEASURE    0x80

/* Conversion time for continuous mode is ~7 ms */
#define MEAS_DELAY_MS  7

/* Sampling interval */
#define SAMPLE_PERIOD_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Write a single byte to an 8-bit register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg 0x%02X): %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes starting at `reg` into `buf`.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write(reg ptr 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "read(reg 0x%02X, %zu bytes): %s (got %zd)\n",
                reg, len, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data conversion                                              */
/* ------------------------------------------------------------------ */
/*
 * Read a 24-bit big-endian value from three consecutive registers.
 * Returns 0 on success, -1 on error.
 */
static int read_24bit(int fd, uint8_t reg_msb, uint32_t *out)
{
    uint8_t buf[3];
    if (i2c_read_reg(fd, reg_msb, buf, sizeof(buf)) != 0)
        return -1;

    *out = ((uint32_t)buf[0] << 16) |
           ((uint32_t)buf[1] << 8)  |
           ((uint32_t)buf[2]);
    return 0;
}

/*
 * Convert raw 24-bit measurement data to temperature (°C).
 * Formula from ICP-10101 datasheet (section 4.2.1):
 *   T = (raw / 2^16) * 200 - 50
 */
static float convert_temperature(uint32_t raw)
{
    return ((float)raw / 65536.0f) * 200.0f - 50.0f;
}

/*
 * Convert raw 24-bit measurement data to pressure (Pa).
 * Formula from ICP-10101 datasheet (section 4.2.2):
 *   P = (raw / 2^16) * 100000
 */
static float convert_pressure(uint32_t raw)
{
    return ((float)raw / 65536.0f) * 100000.0f;
}

/* ------------------------------------------------------------------ */
/* Sensor identification                                               */
/* ------------------------------------------------------------------ */
static int verify_sensor_id(int fd)
{
    uint8_t id[2];
    if (i2c_read_reg(fd, REG_ID_MSB, id, sizeof(id)) != 0)
        return -1;

    if (id[0] != ICP10101_ID) {
        fprintf(stderr,
                "Sensor ID mismatch: got 0x%02X 0x%02X, expected 0x%02X\n",
                id[0], id[1], ICP10101_ID);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    g_i2c_fd = i2c_open(I2C_BUS, ICP10101_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    if (verify_sensor_id(g_i2c_fd) != 0) {
        fprintf(stderr, "ICP-10101 not detected at address 0x%02X\n",
                ICP10101_ADDR);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("ICP-10101 detected at 0x%02X. Starting measurements every %d s.\n",
           ICP10101_ADDR, SAMPLE_PERIOD_S);

    while (g_running) {
        /* Trigger a continuous measurement */
        if (i2c_write_reg8(g_i2c_fd, REG_MEAS_MSB, CMD_MEASURE) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /* Wait for conversion to complete */
        usleep(MEAS_DELAY_MS * 1000);

        /* Read all measurement registers */
        uint32_t raw_temp, raw_press;
        if (read_24bit(g_i2c_fd, REG_TEMP_MSB, &raw_temp) != 0 ||
            read_24bit(g_i2c_fd, REG_PRESS_MSB, &raw_press) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /* Convert to physical units */
        float temperature = convert_temperature(raw_temp);
        float pressure    = convert_pressure(raw_press);

        /* Timestamp */
        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

        printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
               ts, temperature, pressure);
        fflush(stdout);

        /* Sleep for the remainder of the sample period */
        sleep(SAMPLE_PERIOD_S);
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

