#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90819_ADDR  0x28
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
    }
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("[%s] ", buf);
    }
}

/*
 * Read 16-bit big-endian pressure value from the MLX90819.
 * Returns 0 on success and stores the pressure in *pressure_pa.
 * Returns -1 on I2C read error.
 */
static int read_pressure(int fd, float *pressure_pa)
{
    uint8_t reg = 0x00;  /* Pressure register (0x00) */
    uint8_t buf[2];
    ssize_t n;

    /* Write the register pointer */
    n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write error (reg select): %s\n", strerror(errno));
        return -1;
    }

    /* Read 2 bytes of pressure data */
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read error (pressure data): %s\n", strerror(errno));
        return -1;
    }

    /* MLX90819 sends MSB first */
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];

    /*
     * Convert raw ADC value to pressure in Pa.
     * The MLX90819 outputs a 16-bit value proportional to the applied
     * pressure.  The datasheet provides a conversion formula:
     *
     *   pressure_pa = (raw - 16384) * 0.000001 * Vcc
     *
     * We assume a 3.3 V supply (Vcc = 3.3 V).  The raw value is a signed
     * 16-bit two's complement value.
     */
    int16_t signed_raw = (int16_t)raw;
    *pressure_pa = (float)signed_raw * 0.000001f * 3.3f;

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    install_signal_handlers();

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("MLX90819 pressure sensor reader started on %s (addr 0x%02X).\n",
           I2C_BUS, MLX90819_ADDR);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        float pressure_pa;

        if (read_pressure(fd, &pressure_pa) == 0) {
            print_timestamp();
            printf("Pressure: %.4f Pa\n", pressure_pa);
            fflush(stdout);
        } else {
            print_timestamp();
            fprintf(stderr, "Failed to read pressure from sensor.\n");
            fflush(stderr);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

