/*
 * Raspberry Pi 4 Model B – Sensirion SDP800-500Pa differential pressure logger
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c
 * Run:    ./airflow_logger   (Ctrl+C to stop)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25          /* SDP800 default I2C address (ADDR pin tied to GND) */
#define LOG_FILE       "airflow_log.csv"
#define READ_INTERVAL  1             /* seconds between readings */
#define MEAS_DELAY_MS  8             /* SDP800 conversion time */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                 */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            crc = (crc & 0x80) ? (uint8_t)((crc << 1) ^ 0x31)
                               : (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "[ERROR] open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Trigger a single-measurement read and return the differential
 * pressure in Pa.  Returns 0 on success, -1 on persistent failure.
 */
static int read_sdp800(int fd, float *pressure_out)
{
    uint8_t cmd = 0x36;          /* continuous measurement, clock stretching disabled */
    uint8_t buf[3];

    /* Send measurement command */
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "[ERROR] write trigger: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    usleep(MEAS_DELAY_MS * 1000);

    /* Read 3 bytes: MSB, LSB, CRC */
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[ERROR] read: expected 3 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* CRC check */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch (calc=0x%02X recv=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    /* Convert raw 16-bit signed value to Pa */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure_out = (float)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure)
{
    int need_header = (access(filename, F_OK) != 0);

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    if (need_header) {
        fprintf(fp, "timestamp,pressure_pa\n");
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f\n", ts, pressure);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%.2f\n", pressure);
    }

    if (fclose(fp) != 0) {
