#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x28
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0
#define MIN_PRESSURE   200.0
#define MAX_PRESSURE   250.0
#define RETRY_COUNT    2

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_out)
{
    char buf[2];
    int  rc;

    rc = i2cReadDevice(g_i2c_handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2): %s\n",
                rc, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure_out = (float)raw / 100.0f;
    return 0;
}

static int log_pressure(float pressure)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    long file_size = ftell(g_log_file);
    if (file_size == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Error: cannot write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    printf("MLX90821 pressure logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        float pressure;
        int   ok = 0;

        for (int attempt = 0; attempt < RETRY_COUNT && g_running; attempt++) {
            if (read_pressure(&pressure) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Warning: I2C read attempt %d/%d failed, retrying...\n",
                    attempt + 1, RETRY_COUNT);
            gpioDelay(100000); /* 100 ms backoff */
        }

        if (!ok) {
            fprintf(stderr, "Error: I2C read failed after %d attempts, re-initializing...\n",
                    RETRY_COUNT);
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(1000000); /* 1 s backoff before retry */
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Error: I2C re-initialization failed, exiting.\n");
                break;
            }
            continue;
        }

        if (log_pressure(pressure) != 0) {
            fprintf(stderr, "Error: logging failed, continuing.\n");
        }

        if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            fprintf(stderr, "Warning: pressure %.2f kPa out of safe range [%.0f, %.0f] kPa\n",
                    pressure, MIN_PRESSURE, MAX_PRESSURE);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

