/*
 * HIH6130 I2C Temperature & Humidity Logger
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Honeywell HIH6130 at address 0x27
 *
 * Build:  gcc -O2 -Wall -Wextra -o hih6130_logger hih6130_logger.c
 * Run:    ./hih6130_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HIH6130_ADDR   0x27
#define LOG_FILE       "environmental_data.log"
#define LOG_SIZE_LIMIT (1024 * 1024)   /* 1 MB */
#define MEASURE_DELAY_MS 40
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read 4 bytes from the HIH6130 and convert them to temperature (°C)
 * and relative humidity (%RH).  Returns 0 on success, -1 on error.
 */
static int read_hih6130(int fd, float *temperature, float *humidity)
{
    uint8_t buf[4];
    ssize_t n;

    /* Trigger a measurement by writing a zero byte to the sensor */
    n = write(fd, buf, 0);
    if (n < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for the conversion to complete (~40 ms) */
    usleep(MEASURE_DELAY_MS * 1000);

    /* Read 4 bytes: [status][humidity_hi][humidity_lo][temp_hi] */
    n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read error: expected %zu bytes, got %zd (%s)\n",
                sizeof(buf), n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* Check status bits (bits 7:6 of the first byte) */
    uint8_t status = buf[0] & 0xC0;
    if (status == 0x00) {
        /* Normal mode, no error */
    } else if (status == 0x80) {
        fprintf(stderr, "HIH6130 warning: stale data (status=0x80)\n");
    } else if (status == 0xC0) {
        fprintf(stderr, "HIH6130 error: command mode (status=0xC0)\n");
        return -1;
    } else {
        fprintf(stderr, "HIH6130 error: unknown status 0x%02X\n", status);
        return -1;
    }

    /* Humidity: 14-bit value, left-justified in 16-bit word */
    uint16_t humidity_raw = ((uint16_t)(buf[1] & 0x3F) << 8) | buf[2];
    *humidity = (float)humidity_raw / 16383.0f * 100.0f;

    /* Temperature: 14-bit value, left-justified in 16-bit word */
    uint16_t temp_raw = ((uint16_t)(buf[3] & 0x3F) << 8) | buf[4];
    *temperature = (float)temp_raw / 16383.0f * 165.0f - 40.0f;

    return 0;
}

/*
 * Append a timestamped reading to the log file.
 * Rolls the log file when it exceeds LOG_SIZE_LIMIT.
 */
static int log_data(float temperature, float humidity)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    /* Check file size to decide whether to roll */
    long file_size = 0;
    int fd = open(LOG_FILE, O_RDONLY);
    if (fd != -1) {
        file_size = lseek(fd, 0, SEEK_END);
        if (file_size == -1) {
            fprintf(stderr, "lseek() failed: %s\n", strerror(errno));
            close(fd);
            return -1;
        }
        if (close(fd) != 0) {
            fprintf(stderr, "close() failed: %s\n", strerror(errno));
            return -1;
        }
    }

    if (file_size >= LOG_SIZE_LIMIT) {
        /* Roll: truncate the file and write a header */
        fd = open(LOG_FILE, O_WRONLY | O_TRUNC);
        if (fd == -1) {
            fprintf(stderr, "open(truncate) failed: %s\n", strerror(errno));
            return -1;
        }
        if (close(fd) != 0) {
            fprintf(stderr, "close(truncate) failed: %s\n", strerror(errno));
            return -1;
        }
    }

    fd = open(LOG_FILE, O_WRONLY | O_APPEND);
    if (fd == -1) {
        fprintf(stderr, "open(append) failed: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    int len = snprintf(line, sizeof(line), "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                       timestamp, temperature, humidity);
    if (len < 0 || (size_t)len >= sizeof(line)) {
        fprintf(stderr, "snprintf() failed or truncated\n");
        close(fd);
        return -1;
    }

    ssize_t written = write(fd, line, (size_t)len);
    if (written == -1) {
        fprintf(stderr, "write() failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (written != len) {
        fprintf(stderr, "write() short: %zd of %d bytes\n", written, len);
        close(fd);
        return -1;
    }

    if (close(fd) != 0) {
        fprintf(stderr, "close() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
