            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (close(fd) != 0) {
        fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
