/* ------------------------------------------------------------------ */
/*
 * Read one complete SENT frame and extract the 8-bit status, 12-bit
 * data, and 4-bit checksum nibbles.
 *
 * Returns 0 on success, -1 on timeout / bus error.
 */
static int read_sent_frame(uint8_t *status, uint16_t *data, uint8_t *checksum)
{
    int pulses[MAX_PULSES];
    int count = 0;

    /*
     * The MLX90824 SENT protocol is a single-wire bus where the
     * master clocks out nibbles.  We sample the line at a fixed
     * rate and look for falling edges to measure pulse widths.
     */
    while (count < MAX_PULSES) {
        int w = measure_pulse();
        if (w < 0) {
            fprintf(stderr, "SENT read timeout (got %d pulses)\n", count);
            return -1;
        }
        pulses[count++] = w;
    }

    /*
     * Frame format (simplified for the MLX90824):
     *   1. Synchronization pulse (56 ticks)
     *   2. Status nibble (12 ticks)
     *   3. Data nibble 1 (12 ticks)
     *   4. Data nibble 2 (12 ticks)
     *   5. Data nibble 3 (12 ticks)
     *   6. Checksum nibble (12 ticks)
     */
    if (count < 6) {
        fprintf(stderr, "SENT frame too short (%d pulses)\n", count);
        return -1;
    }

    /* Synchronization pulse */
    if (pulses[0] < SYNC_MIN_TICKS || pulses[0] > SYNC_MAX_TICKS) {
        fprintf(stderr, "Invalid sync pulse width: %d ticks\n", pulses[0]);
        return -1;
    }

    /* Status nibble */
    if (pulses[1] < NIBBLE_MIN_TICKS || pulses[1] > NIBBLE_MAX_TICKS) {
        fprintf(stderr, "Invalid status nibble width: %d ticks\n", pulses[1]);
        return -1;
    }
    *status = (uint8_t)(pulses[1] - NIBBLE_MIN_TICKS);

    /* Data nibbles 1-3 */
    for (int i = 0; i < 3; i++) {
        int idx = 2 + i;
        if (pulses[idx] < NIBBLE_MIN_TICKS || pulses[idx] > NIBBLE_MAX_TICKS) {
            fprintf(stderr, "Invalid data nibble %d width: %d ticks\n",
                    i + 1, pulses[idx]);
            return -1;
        }
        *data = (*data << 4) | (uint16_t)(pulses[idx] - NIBBLE_MIN_TICKS);
    }

    /* Checksum nibble */
    if (pulses[5] < NIBBLE_MIN_TICKS || pulses[5] > NIBBLE_MAX_TICKS) {
        fprintf(stderr, "Invalid checksum nibble width: %d ticks\n", pulses[5]);
        return -1;
    }
    *checksum = (uint8_t)(pulses[5] - NIBBLE_MIN_TICKS);

    /* Verify checksum: status ^ data[11:8] ^ data[7:4] ^ data[3:0] */
    uint8_t calc = (uint8_t)(*status ^ (*data >> 8) ^ (*data >> 4) ^ (*data & 0x0F));
    if (calc != *checksum) {
        fprintf(stderr, "Checksum mismatch: calc=0x%02X recv=0x%02X\n",
                calc, *checksum);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Pressure conversion                                                 */
/* ------------------------------------------------------------------ */
/*
 * Convert the 12-bit SENT data nibble to a brake pressure (Pa).
 * The MLX90824 outputs a linear 0-2000 Pa range.
 */
static float convert_pressure(uint16_t data)
{
    return (float)data * (PRESSURE_MAX - PRESSURE_MIN) / 4095.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_pressure(float pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Pressure: %.2f Pa\n", ts, pressure) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO4 as input */
    if (gpioSetMode(SENT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-up so the line is defined when idle */
    if (gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", SENT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90824 SENT brake pressure reader started.\n");
    printf("GPIO%d, logging to '%s'. Press Ctrl+C to exit.\n",
           SENT_GPIO, LOG_FILE);

    int consecutive_errors = 0;

    while (g_running) {
        uint8_t status = 0;
        uint16_t data = 0;
        uint8_t checksum = 0;

        if (read_sent_frame(&status, &data, &checksum) == 0) {
            consecutive_errors = 0;

            if (status == STATUS_OK) {
                float pressure = convert_pressure(data);

                if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) {
                    printf("Pressure: %.2f Pa\n", pressure);
                    if (log_pressure(pressure) != 0) {
                        fprintf(stderr, "Warning: failed to log pressure\n");
                    }
                } else {
                    fprintf(stderr, "Pressure out of range: %.2f Pa\n", pressure);
                }
            } else {
                fprintf(stderr, "Sensor status error (0x%02X)\n", status);
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive SENT errors; "
                                "sensor may be absent or bus fault.\n");
                consecutive_errors = 0;
            }
        }

        /* Sleep 100 ms between readings */
        gpioDelay(100000);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

