/*
 * TMP117 Greenhouse Temperature Logger
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Adafruit TMP117 (I2C address 0x48)
 *
 * Logs 4-byte little-endian floats to greenhouse_temps.dat every 60 s.
 * Handles SIGINT/SIGTERM for graceful shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- TMP117 constants (verified against datasheet) ---- */
#define TMP117_ADDR             0x48
#define TMP117_REG_TEMP_LOW     0x00
#define TMP117_REG_TEMP_HIGH    0x01
#define TMP117_REG_CONFIG       0x02
#define TMP117_REG_DEVICE_ID    0x0F

#define TMP117_DEVICE_ID        0x0001  /* TMP117 */
#define TMP117_CONFIG_DEFAULT   0x0000  /* 12-bit, continuous conversion */

#define LOG_FILE_NAME           "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC     60

/* ---- Globals for signal-handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the TMP117 (little-endian on the bus).  */
/* Returns 0 on success and stores the value in *out; -1 on error.     */
/* ------------------------------------------------------------------ */
static int tmp117_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a TMP117 register.                          */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int tmp117_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value & 0xFF);
    buf[2] = (char)((value >> 8) & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%04X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify the TMP117 device ID.                                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int tmp117_verify_device_id(int handle)
{
    uint16_t id = 0;

    if (tmp117_read_reg16(handle, TMP117_REG_DEVICE_ID, &id) != 0)
        return -1;

    if (id != TMP117_DEVICE_ID) {
        fprintf(stderr,
                "[ERROR] Device ID mismatch: got 0x%04X, expected 0x%04X\n",
                id, TMP117_DEVICE_ID);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the temperature register and convert to Celsius.              */
/* Returns 0 on success and stores the temperature in *out; -1 on error.*/
/* ------------------------------------------------------------------ */
static int tmp117_read_temperature(int handle, float *out)
{
    uint16_t raw = 0;

    if (tmp117_read_reg16(handle, TMP117_REG_TEMP_LOW, &raw) != 0)
        return -1;

    /* TMP117: 12-bit two's-complement, left-justified in 16 bits. */
    int16_t signed_raw = (int16_t)raw;
    *out = (float)signed_raw / 256.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a 4-byte little-endian float to the log file.                 */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_temperature(FILE *file, float temperature)
{
    uint32_t raw;
    memcpy(&raw, &temperature, sizeof(raw));

    if (fwrite(&raw, sizeof(raw), 1, file) != 1) {
        fprintf(stderr, "[ERROR] fwrite failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at TMP117 address ---- */
    g_i2c_handle = i2cOpen(1, TMP117_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                TMP117_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify device identity ---- */
    if (tmp117_verify_device_id(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] TMP117 not detected at address 0x%02X\n",
                TMP117_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure TMP117 (12-bit, continuous) ---- */
    if (tmp117_write_reg16(g_i2c_handle, TMP117_REG_CONFIG,
                          TMP117_CONFIG_DEFAULT) != 0) {
        fprintf(stderr, "[FATAL] Failed to configure TMP117\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (binary, append) ---- */
    g_log_file = fopen(LOG_FILE_NAME, "ab");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("TMP117 greenhouse logger started. Logging to %s every %d s.\n",
           LOG_FILE_NAME, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float temperature;

        if (tmp117_read_temperature(g_i2c_handle, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);

            if (log_temperature(g_log_file, temperature) != 0) {
                fprintf(stderr, "[ERROR] Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "[ERROR] Temperature read failed; will retry.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

