/*
 * SHT40 Temperature & Humidity Logger for Raspberry Pi Zero W
 *
 * Reads temperature and humidity from an Adafruit SHT40 sensor on I2C bus 1
 * (GPIO 2 = SDA, GPIO 3 = SCL), samples every 5 seconds, and logs to
 * environmental_data.txt with CRC-8 validation.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht40_logger sht40_logger.c
 * Run:    sudo ./sht40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT40_ADDR     0x44
#define CMD_MEASURE    0x2C
#define CMD_ARG_HIGH   0x06   /* clock stretching disabled, high repeatability */
#define CONV_DELAY_US  9000   /* 8.5 ms worst-case conversion time */
#define SAMPLE_PERIOD  5      /* seconds between samples */
#define LOG_FILE       "environmental_data.txt"

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity from SHT40                            */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_sht40(float *temperature, float *humidity)
{
    uint8_t cmd[2] = { CMD_MEASURE, CMD_ARG_HIGH };
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONV_DELAY_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (expected 6 bytes)\n");
        return -1;
    }

    /* Validate CRC for temperature */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for humidity */
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    /* Convert raw values to physical units */
    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
