#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define CONFIG_REG 0x01
#define BUFFER_SIZE 100
#define LOG_FILE "temperature_log.dat"
#define SAMPLE_INTERVAL_SEC 5

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

static TemperatureReading temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, TMP117_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char reg = TEMP_REG;
    char buf[2];
    int16_t raw_temp;

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing temperature register address: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }

    raw_temp = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw_temp * 0.0078125f;
    return 0;
}

static void add_to_buffer(time_t timestamp, float temperature) {
    temperature_buffer[buffer_index].timestamp = timestamp;
    temperature_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static int write_buffer_to_file(const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t items_to_write = (size_t)buffer_count;
    size_t items_written = fwrite(temperature_buffer, sizeof(TemperatureReading), items_to_write, fp);

    if (ferror(fp)) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (items_written != items_to_write) {
        fprintf(stderr, "Warning: wrote %zu of %zu items to file\n", items_written, items_to_write);
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float temperature;
        time_t current_time = time(NULL);

        if (read_temperature(&temperature) == 0) {
            add_to_buffer(current_time, temperature);
            printf("Temperature: %.2f C, Timestamp: %ld\n", temperature, (long)current_time);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }

        if (!program_running) {
            break;
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_SEC, 0);
    }

    printf("\nShutting down gracefully...\n");

    if (write_buffer_to_file(LOG_FILE) != 0) {
        fprintf(stderr, "Failed to write buffer to file.\n");
    }

    cleanup();
    printf("Temperature monitoring stopped.\n");
    return EXIT_SUCCESS;
}

