        for (int b = 0; b < 8; b++) {
            crc = (crc & 0x80) ? (uint8_t)((crc << 1) ^ 0x31)
                               : (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity from SHTC3                            */
/* ------------------------------------------------------------------ */
static int read_shtc3(int fd, float *temperature, float *humidity)
{
    uint8_t cmd[2] = { SHTC3_MEASURE_HIGHREP, SHTC3_MEASURE_HIGHREP };
    uint8_t data[6];
    int ret;

    /* Send measurement command */
    ret = write(fd, cmd, sizeof(cmd));
    if (ret != (int)sizeof(cmd)) {
        fprintf(stderr, "[ERROR] I2C write failed (cmd 0x%02X 0x%02X): %s\n",
                cmd[0], cmd[1], strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    usleep(CONV_DELAY_MS * 1000);

    /* Read 6 bytes: T_MSB T_LSB T_CRC  RH_MSB RH_LSB RH_CRC */
    ret = read(fd, data, sizeof(data));
    if (ret != (int)sizeof(data)) {
        fprintf(stderr, "[ERROR] I2C read failed: expected 6 bytes, got %d: %s\n",
                ret, strerror(errno));
        return -1;
    }

    /* Validate CRC for temperature */
    if (shtc3_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for humidity */
    if (shtc3_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    /* Convert raw values to physical units */
    uint16_t t_ticks = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t h_ticks = (uint16_t)((data[3] << 8) | data[4]);

    *temperature = shtc3_calculate_temperature(t_ticks);
    *humidity    = shtc3_calculate_humidity(h_ticks);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Validate sensor data                                                */
/* ------------------------------------------------------------------ */
static int validate_data(float temperature, float humidity)
{
    if (temperature < -40.0f || temperature > 125.0f) {
        fprintf(stderr, "[WARN] Temperature out of range: %.2f C\n", temperature);
        return -1;
    }
    if (humidity < 0.0f || humidity > 100.0f) {
        fprintf(stderr, "[WARN] Humidity out of range: %.2f %%\n", humidity);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to file                                                    */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float temperature, float humidity)
{
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "[ERROR] Cannot open log file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);

    if (fclose(fp) != 0) {
        fprintf(stderr, "[ERROR] fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        shtc3_close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] Cannot open I2C bus '%s': %s\n",
                I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire SHTC3 device */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SHTC3_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SHTC3_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize SHTC3 (soft reset) */
    if (shtc3_init(g_i2c_fd) != 0) {
        fprintf(stderr, "[ERROR] SHTC3 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHTC3 initialized on %s at address 0x%02X. Logging to %s every %d s.\n",
           I2C_BUS, SHTC3_ADDR, LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

        if (read_shtc3(g_i2c_fd, &temperature, &humidity) == 0) {
            if (validate_data(temperature, humidity) == 0) {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                       temperature, humidity);

                if (log_data(LOG_FILE, temperature, humidity) != 0) {
                    fprintf(stderr, "[WARN] Logging failed for this sample\n");
                }
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle\n");
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

