/*
 * Si7202 I2C Hall-effect sensor reader for Raspberry Pi 3 Model B+
 *
 * Reads magnetic field strength (uT) and temperature (deg C) from a
 * Silicon Labs Si7202 over I2C and logs the data to mag_temp_log.csv
 * at one-second intervals.  Handles SIGINT for clean shutdown.
 *
 * Wiring:
 *   Si7202 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   Si7202 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   Si7202 VDD  -> 3.3 V
 *   Si7202 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si7202_logger si7202_logger.c -lpigpio -lrt -lm
 * Run:
 *   sudo ./si7202_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS          1          /* /dev/i2c-1 on Raspberry Pi 3 B+ */
#define SI7202_ADDR      0x40       /* Si7202 default I2C address      */

/* Si7202 register addresses (from datasheet) */
#define SI7202_REG_TEMP_MSB   0x00
#define SI7202_REG_TEMP_LSB   0x01
#define SI7202_REG_MAG_MSB    0x02
#define SI7202_REG_MAG_LSB    0x03
#define SI7202_REG_CONFIG     0x04

/*
 * CONFIG register bits (0x04):
 *   BIT7: 0 = continuous conversion mode
 *   BIT6: 0 = no clock stretching
 *   BIT5: 0 = no reset
 *   BIT4: 0 = no reserved bit
 *   BIT3: 0 = no reserved bit
 *   BIT2: 0 = no reserved bit
 *   BIT1: 0 = no reserved bit
 *   BIT0: 0 = no reserved bit
 */
#define SI7202_CONFIG_VALUE  0x00

/* Conversion constants (from datasheet) */
#define SI7202_TEMP_SCALE    0.0001f   /* deg C per LSB */
#define SI7202_MAG_SCALE     0.0001f   /* uT per LSB   */

#define LOG_FILE_NAME       "mag_temp_log.csv"
#define SAMPLE_PERIOD_US    1000000   /* 1 second in microseconds */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Forward declarations ------------------------ */

static int  initialize_i2c(void);
static int  read_si7202(float *temperature, float *magnetic_field);
static int  log_data(float temperature, float magnetic_field);
static void signal_handler(int signal);
static void cleanup(void);

/* ------------------------------- I2C ------------------------------------- */

static int initialize_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, SI7202_ADDR, g_i2c_handle);
        return -1;
    }

    /* Configure the Si7202 for continuous conversion mode */
    if (i2cWriteByteData(g_i2c_handle, SI7202_REG_CONFIG, SI7202_CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error writing CONFIG register: %d\n", g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/*
 * Read temperature (deg C) and magnetic field (uT) from the Si7202.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_si7202(float *temperature, float *magnetic_field)
{
    int raw_temp, raw_mag;

    /* Read 2 bytes of temperature data (MSB first) */
    raw_temp = i2cReadWordData(g_i2c_handle, SI7202_REG_TEMP_MSB);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", raw_temp);
        return -1;
    }

    /* Read 2 bytes of magnetic field data (MSB first) */
    raw_mag = i2cReadWordData(g_i2c_handle, SI7202_REG_MAG_MSB);
    if (raw_mag < 0) {
        fprintf(stderr, "Error reading magnetic field data: %d\n", raw_mag);
        return -1;
    }

    /* pigpio returns the word as (msb << 8) | lsb; Si7202 sends MSB first */
    *temperature    = (float)((raw_temp >> 8) | (raw_temp << 8)) * SI7202_TEMP_SCALE;
    *magnetic_field = (float)((raw_mag >> 8)  | (raw_mag  << 8)) * SI7202_MAG_SCALE;

    return 0;
}

/* ------------------------------- Logging --------------------------------- */

static int log_data(float temperature, float magnetic_field)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%.4f,%.4f\n", timestamp, temperature, magnetic_field) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }

    return 0;
}

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int signal)
{
    (void)signal;
    g_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    float temperature, magnetic_field;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode; create header if file is new/empty */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE_NAME);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Temperature (C),Magnetic Field (uT)\n");
        fflush(g_log_file);
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler\n");
    }

    printf("Si7202 logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        if (read_si7202(&temperature, &magnetic_field) == 0) {
            if (log_data(temperature, magnetic_field) != 0) {
                fprintf(stderr, "Logging failed; continuing...\n");
            }
        } else {
            /*
             * On I2C error, log NaN values so the data line is still valid
             * and the CSV remains parseable.
             */
            fprintf(stderr, "Sensor read failed; logging NaN values.\n");
            if (log_data(NAN, NAN) != 0) {
                fprintf(stderr, "Logging failed for NaN values.\n");
            }
        }

        /* Sleep for 1 second (interruptible by signals) */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

