#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    int raw_temp;
    int16_t temp_val;

    raw_temp = i2cReadWordData(handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature register: %s\n", strerror(errno));
        return -1;
    }

    /* TMP117 returns data in two's complement, left-justified in 16 bits */
    temp_val = (int16_t)raw_temp;
    *temperature = (float)temp_val / 256.0f;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp;
    time_t t;
    struct tm tm_info;
    char timestamp[20];

    t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int initialize_i2c(void) {
    int retries = 0;

    while (retries < MAX_RETRIES) {
        i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
        if (i2c_handle >= 0) {
            return 0;
        }

        fprintf(stderr, "Error opening I2C device (attempt %d/%d): %s\n",
                retries + 1, MAX_RETRIES, strerror(errno));
        retries++;
        gpioDelay(100000); /* 100 ms backoff */
    }

    return -1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    float temperature;
    int retries = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C after %d attempts. Exiting.\n", MAX_RETRIES);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP117 temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature. Attempting re-initialization...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;

            retries = 0;
            while (retries < MAX_RETRIES && running) {
                if (initialize_i2c() == 0) {
                    break;
                }
                retries++;
                gpioDelay(100000);
            }

            if (retries == MAX_RETRIES) {
                fprintf(stderr, "Failed to re-initialize I2C after %d attempts. Exiting.\n", MAX_RETRIES);
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

