#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float flow_rate;
    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    char buffer[4];
    int result;

    result = i2cReadDevice(i2c_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: expected 4 bytes, got %d\n", result);
        return -1;
    }

    uint16_t raw_flow = ((uint16_t)(buffer[0] & 0x3F) << 8) | (uint8_t)buffer[1];
    uint16_t raw_temp = ((uint16_t)(buffer[2] & 0x0F) << 8) | (uint8_t)buffer[3];

    data->flow_rate = (float)raw_flow / 16383.0f * 25.0f;
    data->temperature = (float)raw_temp / 4095.0f * 100.0f;

    return 0;
}

static int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Flow Rate: %.2f SLPM, Temperature: %.2f C\n",
                timestamp, data->flow_rate, data->temperature) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }

    return 0;
}

int main(void) {
    sensor_data_t sensor_data;
    int consecutive_failures = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    printf("Starting airflow monitoring. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            consecutive_failures = 0;
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Read failure #%d\n", consecutive_failures);

            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Attempting to re-initialize I2C.\n");
                if (initialize_i2c() != 0) {
                    fprintf(stderr, "Re-initialization failed. Exiting.\n");
                    break;
                }
                consecutive_failures = 0;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

