        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

