/*
 * DHT11 bit-bang reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   DHT11 VCC  -> 3.3 V (pin 1)
 *   DHT11 GND  -> GND  (pin 9)
 *   DHT11 DATA -> GPIO4 (pin 7, BCM 4)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o dht11_reader dht11_reader.c
 *
 * Run:
 *   sudo ./dht11_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <pigpio.h>

#define DHT11_GPIO          4
#define READINGS_FILE       "dht11_readings.txt"
#define ERROR_LOG_FILE      "dht11_errors.txt"
#define SAMPLE_INTERVAL_S   2
#define MAX_RETRIES         3

/* DHT11 timing (microseconds) */
#define START_LOW_US        20000   /* >18 ms low  */
#define START_HIGH_US       30      /* 20–40 us high */
#define RESP_LOW_US         80      /* 80 us low   */
#define RESP_HIGH_US        80      /* 80 us high  */
#define BIT_LOW_US          50      /* 50 us low   */
#define BIT_THRESHOLD_US    50      /* >50 us high => '1' */
#define DATA_BIT_US         100     /* 100 us per bit slot */
#define MAX_BIT_WAIT_US     100     /* guard against stuck lines */

/* Error codes */
#define ERR_OK              0
#define ERR_TIMEOUT_START   1
#define ERR_TIMEOUT_RESP    2
#define ERR_TIMEOUT_BIT     3
#define ERR_CHECKSUM        4
#define ERR_LINE_STUCK      5
#define ERR_SENSOR_ABSENT   6

typedef struct {
    int  humidity_int;
    int  humidity_dec;
    int  temp_int;
    int  temp_dec;
    int  checksum;
} DHT11Data;

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg, int code)
{
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n",
                ERROR_LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, %s, code=%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg, code);
    } else {
        fprintf(fp, "[timestamp-error], %s, code=%d\n", msg, code);
    }
    fclose(fp);
}

static void log_reading(const DHT11Data *d)
{
    FILE *fp = fopen(READINGS_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n",
                READINGS_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, "
                    "Humidity: %d.%01d%%, Temperature: %d.%01dC\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                d->humidity_int, d->humidity_dec,
                d->temp_int, d->temp_dec);
    } else {
        fprintf(fp, "[timestamp-error], "
                    "Humidity: %d.%01d%%, Temperature: %d.%01dC\n",
                d->humidity_int, d->humidity_dec,
                d->temp_int, d->temp_dec);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers (pigpio)                                               */
/* ------------------------------------------------------------------ */
static int gpio_set_mode(unsigned gpio, unsigned mode)
{
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int gpio_write(unsigned gpio, unsigned level)
{
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int gpio_read(unsigned gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "[ERROR] gpioRead(%u) failed\n", gpio);
    }
    return v;
}

/*
 * Wait for the line to reach the given level, or until timeout
 * microseconds elapse.  Returns 0 on success, -1 on timeout.
 */
static int wait_level(unsigned gpio, unsigned level, unsigned timeout_us)
{
    uint32_t start = gpioTick();
    while (gpio_read(gpio) != (int)level) {
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return 0;
}

/*
 * Measure the duration (in microseconds) that the line stays at the
 * given level.  Returns the duration, or -1 on timeout.
 */
static int measure_level(unsigned gpio, unsigned level, unsigned timeout_us)
{
    uint32_t start = gpioTick();
    while (gpio_read(gpio) == (int)level) {
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return (int)(gpioTick() - start);
}

/* ------------------------------------------------------------------ */
/* DHT11 read                                                          */
/* ------------------------------------------------------------------ */
static int read_dht11(DHT11Data *data)
{
    uint8_t raw[5] = {0};

    /* --- Start signal: pull low >= 18 ms, then release --- */
    if (gpio_write(DHT11_GPIO, 0) != 0)
        return ERR_LINE_STUCK;
    gpioDelay(START_LOW_US);

    if (gpio_write(DHT11_GPIO, 1) != 0)
        return ERR_LINE_STUCK;
    gpioDelay(START_HIGH_US);

    /* --- Sensor response: ~80 us low then ~80 us high --- */
    if (wait_level(DHT11_GPIO, 0, MAX_BIT_WAIT_US) != 0)
        return ERR_TIMEOUT_RESP;
    if (measure_level(DHT11_GPIO, 0, MAX_BIT_WAIT_US) < 0)
        return ERR_TIMEOUT_RESP;

    if (wait_level(DHT11_GPIO, 1, MAX_BIT_WAIT_US) != 0)
        return ERR_TIMEOUT_RESP;
    if (measure_level(DHT11_GPIO, 1, MAX_BIT_WAIT_US) < 0)
        return ERR_TIMEOUT_RESP;

    /* --- Read 40 data bits --- */
    for (int i = 0; i < 40; i++) {
        /* Low preamble (~50 us) */
        if (wait_level(DHT11_GPIO, 0, MAX_BIT_WAIT_US) != 0)
            return ERR_TIMEOUT_BIT;
        if (measure_level(DHT11_GPIO, 0, MAX_BIT_WAIT_US) < 0)
            return ERR_TIMEOUT_BIT;

        /* High pulse: ~26-28 us => '0', ~70 us => '1' */
        int hi_us = measure_level(DHT11_GPIO, 1, MAX_BIT_WAIT_US);
        if (hi_us < 0)
            return ERR_TIMEOUT_BIT;

        if (hi_us > BIT_THRESHOLD_US)
            raw[i / 8] |= (1 << (7 - (i % 8)));
    }

    /* --- Checksum --- */
    uint8_t checksum = (uint8_t)(raw[0] + raw[1] + raw[2] + raw[3]);
    if (checksum != raw[4])
        return ERR_CHECKSUM;

    /* --- Sensor-absent heuristic: line stuck high or low --- */
    if (gpio_read(DHT11_GPIO) == 0)
        return ERR_SENSOR_ABSENT;
    if (gpio_read(DHT11_GPIO) == 1)
        return ERR_SENSOR_ABSENT;

    data->humidity_int  = raw[0];
    data->humidity_dec  = 0;
    data->temp_int      = raw[2];
    data->temp_dec      = 0;
    data->checksum      = raw[4];

    return ERR_OK;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO --- */
    if (gpio_set_mode(DHT11_GPIO, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpio_write(DHT11_GPIO, 1) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(100000); /* 100 ms settle */

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed: %s\n", strerror(errno));
    }

    printf("DHT11 reader started on GPIO%d. Press Ctrl+C to exit.\n",
           DHT11_GPIO);

    /* --- Main loop --- */
    while (g_running) {
        DHT11Data data;
        int rc = read_dht11(&data);

        if (rc == ERR_OK) {
            log_reading(&data);
            printf("Humidity: %d.%01d%%, Temperature: %d.%01dC\n",
                   data.humidity_int, data.humidity_dec,
                   data.temp_int, data.temp_dec);
        } else {
            log_error("DHT11 read failed", rc);
            fprintf(stderr, "[ERROR] DHT11 read failed (code %d)\n", rc);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* --- Cleanup --- */
    gpio_write(DHT11_GPIO, 1);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

