/*
 * SHT31-D Temperature & Humidity Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   SHT31-D SDA  -> GPIO2 (BCM, bus 1)
 *   SHT31-D SCL  -> GPIO3 (BCM, bus 1)
 *   SHT31-D VDD  -> 3.3 V
 *   SHT31-D GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sht31d_logger sht31d_logger.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./sht31d_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT31_ADDR     0x44
#define CMD_MEASURE    0x2C
#define MEASURE_DELAY  20000   /* microseconds (20 ms) */
#define LOG_INTERVAL   5       /* seconds */
#define MAX_RETRIES    3
#define LOG_FILE       "sht31d_data.log"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity from SHT31-D                           */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int read_sht31d(float *temperature, float *humidity)
{
    uint8_t cmd = CMD_MEASURE;
    uint8_t buf[6];
    int     rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /* Issue measurement command */
        rc = i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1);
        if (rc != 0) {
            fprintf(stderr, "[attempt %d] i2cWriteDevice failed (rc=%d)\n",
                    attempt + 1, rc);
            gpioDelay(MEASURE_DELAY);
            continue;
        }

        /* Wait for conversion to complete */
        gpioDelay(MEASURE_DELAY);

        /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
        rc = i2cReadDevice(g_i2c_handle, (char *)buf, 6);
        if (rc != 6) {
            fprintf(stderr, "[attempt %d] i2cReadDevice failed (rc=%d)\n",
                    attempt + 1, rc);
            gpioDelay(MEASURE_DELAY);
            continue;
        }

        /* Validate CRC for temperature */
        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "[attempt %d] temperature CRC mismatch\n",
                    attempt + 1);
            gpioDelay(MEASURE_DELAY);
            continue;
        }

        /* Validate CRC for humidity */
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "[attempt %d] humidity CRC mismatch\n",
                    attempt + 1);
            gpioDelay(MEASURE_DELAY);
            continue;
        }

        /* Convert raw values */
        uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)t_raw / 65535.0f);
        *humidity    = 100.0f * (float)h_raw / 65535.0f;

        return 0;
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Log data to file                                                    */
/* ------------------------------------------------------------------ */
static void log_data(float temperature, float humidity)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SHT31-D logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, LOG_INTERVAL);

    float temperature, humidity;

    while (g_running) {
        if (read_sht31d(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            printf("%s  T=%.2f C  RH=%.2f %%\n",
                   "reading", temperature, humidity);
        } else {
            time_t     rawtime;
            struct tm  timeinfo;
            char       timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

            fprintf(stderr, "%s  ERROR: Failed to read sensor after %d retries\n",
                    timestamp, MAX_RETRIES);
