/* Read a single byte from an ADPD105 register                         */
/* ------------------------------------------------------------------ */
static int adpd105_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(handle=%d, reg=0x%02X) failed: %s\n",
                handle, reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair (low byte at reg, high at reg+1) */
/* ------------------------------------------------------------------ */
static int adpd105_read_reg16(int handle, uint8_t reg, uint16_t *value)
{
    uint8_t lo, hi;
    if (adpd105_read_reg(handle, reg, &lo) < 0)
        return -1;
    if (adpd105_read_reg(handle, reg + 1, &hi) < 0)
        return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize an ADPD105 sensor                                        */
/* ------------------------------------------------------------------ */
static int adpd105_init(int handle)
{
    uint8_t part_id = 0;

    /* Verify sensor presence by reading PART_ID */
    if (adpd105_read_reg(handle, ADPD105_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID from handle %d – sensor absent or bus error.\n", handle);
        return -1;
    }

    printf("[INFO] ADPD105 (handle %d) detected: PART_ID = 0x%02X\n", handle, part_id);

    /* Put sensor in standby mode before configuring */
    if (adpd105_write_reg(handle, ADPD105_REG_OP_MODE, 0x00) < 0)
        return -1;

    /* Clear any pending interrupts */
    if (adpd105_write_reg(handle, ADPD105_REG_INT_STATUS, 0x01) < 0)
        return -1;

    /* Enable data-ready interrupt (bit 0) */
    if (adpd105_write_reg(handle, ADPD105_REG_INT_ENABLE, 0x01) < 0)
        return -1;

    /* Start continuous measurement mode */
    if (adpd105_write_reg(handle, ADPD105_REG_OP_MODE, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all four channel data from an ADPD105                           */
/* ------------------------------------------------------------------ */
static int adpd105_read_channels(int handle, uint16_t *ch0, uint16_t *ch1,
                                uint16_t *ch2, uint16_t *ch3)
{
    if (adpd105_read_reg16(handle, ADPD105_REG_DATA_CH0_L, ch0) < 0) return -1;
    if (adpd105_read_reg16(handle, ADPD105_REG_DATA_CH1_L, ch1) < 0) return -1;
    if (adpd105_read_reg16(handle, ADPD105_REG_DATA_CH2_L, ch2) < 0) return -1;
    if (adpd105_read_reg16(handle, ADPD105_REG_DATA_CH3_L, ch3) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Correlated color temperature (CCT) calculation                      */
/* ------------------------------------------------------------------ */
static float calculate_cct(uint16_t ch0, uint16_t ch1, uint16_t ch2, uint16_t ch3)
{
    /*
     * Placeholder CCT calculation.  Replace with the actual
     * ADPD105 CCT algorithm from the datasheet.
     */
    float cct = 2800.0f + (float)(ch0 - ch1) * 0.1f;
    return cct;
}

/* ------------------------------------------------------------------ */
/* Log a CCT reading to the CSV file                                    */
/* ------------------------------------------------------------------ */
static int log_cct(float cct)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, cct) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources                                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at addresses 0x20 and 0x21 */
    g_i2c_handle1 = i2cOpen(1, ADPD105_ADDR_1, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(1, 0x%02X) failed: %s\n",
                ADPD105_ADDR_1, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(1, ADPD105_ADDR_2, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(1, 0x%02X) failed: %s\n",
                ADPD105_ADDR_2, strerror(errno));
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensors */
    if (adpd105_init(g_i2c_handle1) < 0) {
        fprintf(stderr, "[FATAL] Sensor 1 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (adpd105_init(g_i2c_handle2) < 0) {
        fprintf(stderr, "[FATAL] Sensor 2 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("cct_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open cct_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Average_CCT\n");
        fflush(g_log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("[INFO] Logging CCT to cct_log.csv.  Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t ch0_1 = 0, ch1_1 = 0, ch2_1 = 0, ch3_1 = 0;
        uint16_t ch0_2 = 0, ch1_2 = 0, ch2_2 = 0, ch3_2 = 0;
        float cct1 = 0.0f, cct2 = 0.0f;
        int ok1 = 0, ok2 = 0;

        /* Read sensor 1 */
        if (adpd105_read_channels(g_i2c_handle1, &ch0_1, &ch1_1, &ch2_1, &ch3_1) == 0) {
            cct1 = calculate_cct(ch0_1, ch1_1, ch2_1, ch3_1);
            ok1 = 1;
        } else {
            fprintf(stderr, "[ERROR] Failed to read sensor 1 – skipping cycle.\n");
        }

        /* Read sensor 2 */
        if (adpd105_read_channels(g_i2c_handle2, &ch0_2, &ch1_2, &ch2_2, &ch3_2) == 0) {
            cct2 = calculate_cct(ch0_2, ch1_2, ch2_2, ch3_2);
            ok2 = 1;
        } else {
            fprintf(stderr, "[ERROR] Failed to read sensor 2 – skipping cycle.\n");
        }

        /* Log only if both reads succeeded */
        if (ok1 && ok2) {
            float avg_cct = (cct1 + cct2) / 2.0f;
            if (log_cct(avg_cct) < 0) {
                fprintf(stderr, "[ERROR] Logging failed – continuing.\n");
            }
        }

        /* Sleep 1 second (interruptible by signals) */
        sleep(1);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

