/*
 * MLX90824 Absolute Pressure Sensor Logger for Raspberry Pi 4 Model B
 *
 * Reads pressure and temperature from an MLX90824 over I2C every 2 seconds,
 * appending timestamped records to pressure_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90824_logger mlx90824_logger.c -lmlx90824
 * Run:    ./mlx90824_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <mlx90824.h>

#define I2C_BUS        1
#define I2C_ADDR       0x28          /* MLX90824 default I2C address (ADDR pin tied to GND) */
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  2             /* seconds between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, const char *timestamp, float pressure, float temperature)
{
    if (fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
                timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

static void log_error(FILE *fp, const char *timestamp, const char *message)
{
    if (fprintf(fp, "%s, ERROR: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int i2c_handle = -1;
    FILE *log_file = NULL;
    int ret_code = EXIT_FAILURE;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize MLX90824 sensor library ---- */
    if (mlx90824_init() != 0) {
        fprintf(stderr, "Failed to initialize MLX90824 sensor library.\n");
        goto cleanup;
    }

    /* ---- Open I2C bus ---- */
    i2c_handle = mlx90824_open_i2c(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("MLX90824 logger started. Logging to '%s' every %d seconds.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        char timestamp[32];
        float pressure = 0.0f;
        float temperature = 0.0f;
        int read_ok = 1;

        get_timestamp(timestamp, sizeof(timestamp));

        /* Read pressure and temperature */
        if (mlx90824_read_pressure(i2c_handle, &pressure) != 0) {
            fprintf(stderr, "%s: Failed to read pressure: %s\n",
                    timestamp, strerror(errno));
            read_ok = 0;
        }

        if (mlx90824_read_temperature(i2c_handle, &temperature) != 0) {
            fprintf(stderr, "%s: Failed to read temperature: %s\n",
                    timestamp, strerror(errno));
            read_ok = 0;
        }

        if (read_ok) {
            log_data(log_file, timestamp, pressure, temperature);
            printf("%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
                   timestamp, pressure, temperature);
        } else {
            log_error(log_file, timestamp, "Sensor read failure");
        }

        /* Sleep for the sample period, but wake early if a signal arrives */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    /* ---- Clean up resources ---- */
    if (i2c_handle >= 0) {
        mlx90824_close_i2c(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    mlx90824_cleanup();

    return ret_code;
}

