#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define LM75B_TEMP_REG 0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_ON        28.0f
#define TEMP_OFF       26.0f
#define SAMPLE_PERIOD  1.0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

static int read_temperature(int handle, float *out_temp) {
    char reg = LM75B_TEMP_REG;
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to select LM75B temperature register.\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read 2 bytes from LM75B.\n");
        return -1;
    }
    int16_t raw = (int16_t)(((uint8_t)data[0] << 8) | (uint8_t)data[1]);
    raw >>= 5;
    *out_temp = (float)raw * 0.125f;
    return 0;
}

static int control_fan(int gpio, float avg_temp) {
    static bool fan_on = false;
    if (avg_temp > TEMP_ON && !fan_on) {
        if (gpioWrite(gpio, 1) != 0) {
            fprintf(stderr, "Error: failed to turn fan ON.\n");
            return -1;
        }
        fan_on = true;
        printf("Fan ON  (avg=%.2f C)\n", avg_temp);
    } else if (avg_temp < TEMP_OFF && fan_on) {
        if (gpioWrite(gpio, 0) != 0) {
            fprintf(stderr, "Error: failed to turn fan OFF.\n");
            return -1;
        }
        fan_on = false;
        printf("Fan OFF (avg=%.2f C)\n", avg_temp);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d.\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    while (g_running) {
        float temperature;
        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            cb_add(&temp_buffer, temperature);
            float avg = cb_average(&temp_buffer);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, avg);
            control_fan(FAN_GPIO, avg);
        } else {
            fprintf(stderr, "Warning: temperature read failed, retrying next cycle.\n");
        }
        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

