/*
 * SDP810-500Pa differential pressure logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c -lpigpio -lrt
 * Run:    sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define I2C_ADDR         0x25          /* SDP810 default I2C address */
#define LOG_FILE         "airflow.log"
#define PRESSURE_THRESHOLD 5.0f        /* Pa */
#define SAMPLE_PERIOD_US 1000000      /* 1 second */
#define MEASURE_DELAY_US 45000        /* 45 ms after first measurement */
#define MAX_RETRIES      3

/* SDP810 measurement command: differential pressure, mass flow */
static const uint8_t CMD_MEASURE[2] = {0x36, 0x2F};

/* Sensirion CRC-8: polynomial 0x31, initial value 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read one differential-pressure sample from the SDP810.
 * Returns 0 on success and fills *pressure_pa and *temperature_c;
 * returns -1 on any I/O or CRC error.
 */
static int read_sdp810(int handle, float *pressure_pa, float *temperature_c)
{
    uint8_t buf[9];
    int16_t raw_pressure, raw_temperature;

    /* Issue measurement command */
    if (i2cWriteDevice(handle, (char *)CMD_MEASURE, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MEASURE_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(2)+crc */
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (expected 9 bytes)\n");
        return -1;
    }

    /* Validate CRC for pressure (bytes 0-1, CRC byte 2) */
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 3-4, CRC byte 5) */
    if (sensirion_crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for scale factor (bytes 6-7, CRC byte 8) */
    if (sensirion_crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "[ERROR] Scale factor CRC mismatch\n");
        return -1;
    }

    /* Parse raw values (big-endian, signed) */
    raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    /*
     * SDP810 scale factor: 1 LSB = 0.01 Pa.
     * Temperature scale: 1 LSB = 0.01 °C.
     */
    *pressure_pa    = (float)raw_pressure / 100.0f;
    *temperature_c  = (float)raw_temperature / 100.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

static void check_threshold(float pressure)
{
    if (pressure > PRESSURE_THRESHOLD) {
        fprintf(stderr,
                "[WARN] Pressure %.2f Pa exceeds threshold %.2f Pa\n",
                pressure, PRESSURE_THRESHOLD);
    }
}

static void signal_handler(int sig)
{
    fprintf(stderr, "\n[INFO] Signal %d received, shutting down...\n", sig);
    gpioTerminate();
    exit(0);
}

int main(void)
{
    int handle = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, handle);
        goto cleanup_gpio;
    }

    /* Open log file in append mode */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "[ERROR] Cannot open log file '%s'\n", LOG_FILE);
        goto cleanup_i2c;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,differential_pressure_pa,temperature_c\n");
        fflush(fp);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction failed\n");
        goto cleanup_log;
    }

    fprintf(stderr, "[INFO] Logging SDP810 data to %s (threshold %.1f Pa)\n",
            LOG_FILE, PRESSURE_THRESHOLD);

    /* Main sampling loop */
    while (1) {
        float pressure = 0.0f, temperature = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_sdp810(handle, &pressure, &temperature) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(10000); /* 10 ms backoff before retry */
        }

        if (ok) {
            log_data(fp, pressure, temperature);
            check_threshold(pressure);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed after %d attempts\n",
                    MAX_RETRIES);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    rc = EXIT_SUCCESS;

cleanup_log:
    fclose(fp);
cleanup_i2c:
    i2cClose(handle);
cleanup_gpio:
    gpioTerminate();
    return rc;
}

