/*
 * STTS2004 temperature monitor with hysteresis LED control.
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: STTS2004 on I2C bus 1, address 0x48
 * LED:    GPIO17 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o stts2004_monitor stts2004_monitor.c -lpigpio -lrt
 * Run:    sudo ./stts2004_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define STTS2004_ADDR       0x48
#define STTS2004_REG_TEMP   0x00
#define STTS2004_REG_CONFIG 0x01

#define LED_GPIO            17
#define TEMP_HIGH           28.0f   /* °C — LED on  */
#define TEMP_LOW            27.0f   /* °C — LED off */
#define SAMPLE_PERIOD_US    1000000 /* 1 second */
#define MAX_CONSECUTIVE_ERR 10

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static bool g_pigpio_initialised = false;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers -------------------------------- */
/*
 * Read the 16-bit temperature register from the STTS2004.
 * Returns 0 on success and stores the temperature in *out_temp;
 * returns -1 on failure.
 */
static int read_temperature(int fd, float *out_temp)
{
    char reg = STTS2004_REG_TEMP;
    char buf[2];

    /* Select the temperature register pointer. */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C write (reg select) failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* Read two bytes of temperature data. */
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C read (temperature) failed: %s\n",
                strerror(errno));
        return -1;
    }

    /*
     * STTS2004 temperature register layout (16-bit, two's complement):
     *   Bits 15..12 : reserved
     *   Bits 11..4  : temperature MSB (0.0625 °C per LSB)
     *   Bits 3..0   : temperature LSB (0.0625 °C per LSB)
     */
    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                            (uint8_t)buf[1]);
    raw >>= 4;                       /* arithmetic right-shift keeps sign */
    *out_temp = (float)raw * 0.0625f;
    return 0;
}

/* --------------------------- GPIO helpers -------------------------------- */
static int set_led(int gpio, int level)
{
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, %d) failed: %s\n",
                gpio, level, strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_pigpio_initialised) {
        set_led(LED_GPIO, 0);
        gpioTerminate();
        g_pigpio_initialised = false;
    }
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_initialised = true;

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n",
                LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (set_led(LED_GPIO, 0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus to STTS2004 --- */
    g_i2c_fd = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, STTS2004_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    /* --- Main loop --- */
    bool led_on = false;
    int  consecutive_errors = 0;

    while (g_running) {
        float temperature;

        if (read_temperature(g_i2c_fd, &temperature) == 0) {
            consecutive_errors = 0;

            /* Hysteresis control */
            if (temperature > TEMP_HIGH && !led_on) {
                if (set_led(LED_GPIO, 1) == 0) {
                    led_on = true;
                }
            } else if (temperature < TEMP_LOW && led_on) {
                if (set_led(LED_GPIO, 0) == 0) {
                    led_on = false;
                }
            }

            /* Timestamp */
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            if (t != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            } else {
                snprintf(ts, sizeof(ts), "----");
            }

            printf("[%s] Temperature: %.2f °C  LED: %s\n",
                   ts, temperature, led_on ? "ON" : "OFF");
            fflush(stdout);
        } else {
            consecutive_errors++;
            fprintf(stderr, "[ERROR] Temperature read failed (%d/%d)\n",
                    consecutive_errors, MAX_CONSECUTIVE_ERR);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERR) {
                fprintf(stderr, "[FATAL] %d consecutive I2C failures — aborting.\n",
                        consecutive_errors);
                break;
            }
        }

        /* Sleep 1 second, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_PERIOD_US / 10);
        }
    }

    /* --- Graceful shutdown --- */
    cleanup();
    return EXIT_SUCCESS;
}

