/*
 * SDP800-500Pa Differential Pressure & Temperature Logger
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Sensirion SDP800-500Pa
 *
 * The SDP800-500Pa is a differential pressure sensor that outputs
 * differential pressure and temperature data over I2C.  The sensor
 * requires a measurement command (0x362F) to be sent, followed by a
 * conversion delay of at least 45 ms before reading the 9-byte
 * response:
 *
 *   [DP_MSB, DP_LSB, DP_CRC] [T_MSB, T_LSB, T_CRC] [S_MSB, S_LSB, S_CRC]
 *
 * The CRC-8 calculation uses the polynomial 0x31, and the initialization
 * value 0xFF.  The CRC is calculated over the two data bytes of each
 * 16-bit word.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "flow_data.txt"
#define MEASURE_CMD    0x362F
#define CONV_DELAY_MS  45
#define READ_LEN       9
#define SAMPLE_PERIOD  1000000  /* microseconds (1 second) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 calculation (Sensirion: poly 0x31, init 0xFF)                  */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command to the SDP800                                 */
/* ------------------------------------------------------------------ */
static int sdp_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write failed: %s (wrote %zd bytes)\n",
                strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly `len` bytes from the SDP800                            */
/* ------------------------------------------------------------------ */
static int sdp_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and read the 9-byte response                   */
/* ------------------------------------------------------------------ */
static int sdp_read_measurement(int fd, float *dp, float *temp)
{
    if (sdp_write_cmd(fd, MEASURE_CMD) != 0)
        return -1;

    usleep(CONV_DELAY_MS * 1000);

    uint8_t raw[READ_LEN];
    if (sdp_read_bytes(fd, raw, READ_LEN) != 0)
        return -1;

    /* Validate CRC for differential pressure (bytes 0-1, CRC byte 2) */
    if (crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "CRC error: differential pressure\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 3-4, CRC byte 5) */
    if (crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "CRC error: temperature\n");
        return -1;
    }

    /* Validate CRC for scale factor (bytes 6-7, CRC byte 8) */
    if (crc8(&raw[6], 2) != raw[8]) {
        fprintf(stderr, "CRC error: scale factor\n");
        return -1;
    }

    /*
     * SDP800-500Pa outputs differential pressure in Pa and temperature
     * in °C.  The raw 16-bit values are signed two's-complement.
     */
    int16_t dp_raw = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t t_raw  = (int16_t)((raw[3] << 8) | raw[4]);

    *dp   = (float)dp_raw;
    *temp = (float)t_raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a measurement with a timestamp                                  */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float dp, float temp)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, Differential Pressure: %.2f Pa, Temperature: %.2f C\n",
                ts, dp, temp) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handler for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Acquire the SDP800 slave address --- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SDP800-500Pa logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        float dp, temp;

        if (sdp_read_measurement(g_i2c_fd, &dp, &temp) == 0) {
            if (log_data(g_log_fp, dp, temp) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Measurement read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

