           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        float dp, temp;

        if (sdp_read_measurement(g_i2c_fd, &dp, &temp) == 0) {
            if (log_data(g_log_fp, dp, temp) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Measurement read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

