/*
 * Si7021 temperature & humidity logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si7021 SDA  -> GPIO2 (BCM, bus 1)
 *   Si7021 SCL  -> GPIO3 (BCM, bus 1)
 *   Si7021 VDD  -> 3.3 V
 *   Si7021 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si7021_logger si7021_logger.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./si7021_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40

/* Si7021 command codes (no register addressing) */
#define CMD_MEASURE_RH_NO_HOLD   0xE5   /* Measure Relative Humidity, No Master Hold */
#define CMD_MEASURE_TEMP_NO_HOLD 0xF3   /* Measure Temperature, No Master Hold */
#define CMD_READ_PREV_RH         0xE0   /* Read Temperature from Previous RH Measurement */

#define LOG_FILE_NAME  "environment.log"
#define SAMPLE_PERIOD  60          /* seconds between samples */
#define MAX_RETRIES    3
#define MEASURE_DELAY_US 20000     /* 20 ms max conversion time */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    if (g_log_file) {
        fprintf(g_log_file, "%s,ERROR,%s\n", ts, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s,ERROR,%s\n", ts, msg);
}

static void log_data(float temp_c, float rh_pct)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    if (g_log_file) {
        fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
        fflush(g_log_file);
    }
    printf("%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Send a single command byte to the Si7021.
 * Returns 0 on success, -1 on failure.
 */
static int si7021_send_command(uint8_t cmd)
{
    int rc = i2cWriteByte(g_i2c_handle, cmd);
    if (rc < 0) {
        log_error("i2cWriteByte failed");
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian measurement result from the Si7021.
 * Returns 0 on success and stores the raw value in *raw; -1 on failure.
 */
static int si7021_read_measurement(uint16_t *raw)
{
    char buf[2];
    int rc = i2cReadDevice(g_i2c_handle, buf, 2);
    if (rc != 2) {
        log_error("i2cReadDevice failed");
        return -1;
    }
    *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Read temperature from the Si7021 using the “Read Temperature from
 * Previous RH Measurement” command (0xE0).  This avoids a separate
 * temperature measurement and saves power.
 * Returns 0 on success and stores the temperature in *temp_c; -1 on failure.
 */
static int si7021_read_temperature(float *temp_c)
{
    if (si7021_send_command(CMD_READ_PREV_RH) < 0)
        return -1;

    gpioDelay(MEASURE_DELAY_US);

    uint16_t raw;
    if (si7021_read_measurement(&raw) < 0)
        return -1;

    /*
     * Si7021 temperature conversion:
     *   T(°C) = (175.72 * raw) / 65536 - 46.85
     */
    *temp_c = ((175.72f * (float)raw) / 65536.0f) - 46.85f;
    return 0;
}

/*
 * Read relative humidity from the Si7021 using the “Measure Relative
 * Humidity, No Master Hold” command (0xE5).
 * Returns 0 on success and stores the humidity in *rh_pct; -1 on failure.
 */
static int si7021_read_humidity(float *rh_pct)
{
    if (si7021_send_command(CMD_MEASURE_RH_NO_HOLD) < 0)
        return -1;

    gpioDelay(MEASURE_DELAY_US);

    uint16_t raw;
    if (si7021_read_measurement(&raw) < 0)
        return -1;

    /*
     * Si7021 humidity conversion:
     *   RH(%) = (125.0 * raw) / 65536 - 6.0
     */
    *rh_pct = ((125.0f * (float)raw) / 65536.0f) - 6.0f;

    /* Clamp humidity to physical range */
    if (*rh_pct < 0.0f)   *rh_pct = 0.0f;
    if (*rh_pct > 100.0f) *rh_pct = 100.0f;
    return 0;
}

/*
 * Verify sensor presence by reading the Si7021 electronic ID (SNA_0, SNA_1).
 * Returns 0 on success, -1 on failure.
 */
static int si7021_verify_sensor(void)
{
    /*
     * Read the 8-bit SNA_0 register (0xFA, 0x0F) using a combined
     * write-then-read transfer.  The Si7021 returns the ID byte
     * in the first byte of the response.
     */
    char cmd[2] = { 0xFA, 0x0F };
    char buf[1];

    int rc = i2cWriteDevice(g_i2c_handle, cmd, 2);
    if (rc < 0) {
        log_error("Failed to write electronic ID request");
        return -1;
    }

    gpioDelay(10000); /* 10 ms settle */

    rc = i2cReadDevice(g_i2c_handle, buf, 1);
    if (rc != 1) {
        log_error("Failed to read electronic ID");
        return -1;
    }

    uint8_t id = (uint8_t)buf[0];
    if (id != 0x15) {
        fprintf(stderr, "Unexpected Si7021 ID: 0x%02X (expected 0x15)\n", id);
        log_error("Unexpected Si7021 ID");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence */
    if (si7021_verify_sensor() < 0) {
        fprintf(stderr, "Si7021 not detected on bus %d addr 0x%02X\n",
                I2C_BUS, SI7021_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,temperature_c,humidity_pct\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME, SAMPLE_PERIOD);

    /* Main sampling loop */
    while (g_running) {
        float temp_c = 0.0f, rh_pct = 0.0f;
        int ok = 0;

        /*
         * Retry the temperature read up to MAX_RETRIES times.
         * The Si7021 is a slow sensor; a single failure may be transient.
         */
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (si7021_read_temperature(&temp_c) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(100000); /* 100 ms backoff before retry */
        }

        if (!ok) {
            log_error("Temperature read failed after retries");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /*
         * Retry the humidity read up to MAX_RETRIES times.
         * The Si7021 is a slow sensor; a single failure may be transient.
         */
        ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (si7021_read_humidity(&rh_pct) == 0) {
                ok = 1;
                break;
            }
            gpioDelay(100000); /* 100 ms backoff before retry */
        }

        if (!ok) {
            log_error("Humidity read failed after retries");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        log_data(temp_c, rh_pct);
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

