#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONFIG_REG 0x02
#define LOG_FILE "enviro_log.txt"
#define CONVERSION_DELAY_US 20000
#define SAMPLE_INTERVAL_US 5000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hdc1080(int handle, float *temperature, float *humidity) {
    uint8_t buf[4];
    int rc;

    rc = i2cReadI2CBlockData(handle, TEMP_REG, (char *)buf, 4);
    if (rc != 4) {
        fprintf(stderr, "Error reading HDC1080 data block (rc=%d)\n", rc);
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_humid = ((uint16_t)buf[2] << 8) | buf[3];

    *temperature = (float)raw_temp / 65536.0f * 165.0f - 40.0f;
