#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS40_ADDR     0x48
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_PERIOD  5
#define CONV_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                  */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Trigger a single-shot measurement on the STS40 and read the 3-byte
 * result.  Returns 0 on success and fills *temp_c; returns -1 on any
 * I/O or CRC error.
 */
static int sts40_read(int fd, float *temp_c)
{
    uint8_t cmd = 0x24;          /* single-shot, clock stretching disabled */
    uint8_t buf[3];

    /* --- Trigger measurement --- */
    if (write(fd, &cmd, 1) != 1) {
        perror("write trigger command");
        return -1;
    }

    /* --- Wait for conversion to complete --- */
    usleep(CONV_DELAY_MS * 1000);

    /* --- Read 3 bytes: MSB, LSB, CRC --- */
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0)
            perror("read measurement");
        else
            fprintf(stderr, "read: short read (%zd bytes)\n", n);
        return -1;
    }

    /* --- CRC check --- */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    /* --- Convert raw value to Celsius --- */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp_c = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_temperature(FILE *fp, float temp_c)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return;
    }

    fprintf(fp, "%s, %.2f\n", ts, temp_c);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus and set slave address --- */
    g_i2c_fd = i2c_open(I2C_BUS, STS40_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("STS40 temperature logger started.  Bus=%s  Addr=0x%02X  "
           "Log=%s  Sample=%ds  Conv=%dms\n",
           I2C_BUS, STS40_ADDR, LOG_FILE, SAMPLE_PERIOD, CONV_DELAY_MS);

    /* --- Main sampling loop --- */
    while (g_running) {
        float temp_c;

        if (sts40_read(g_i2c_fd, &temp_c) == 0) {
            log_temperature(g_log_fp, temp_c);
            printf("Temperature: %.2f C\n", temp_c);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

