/*
 * Raspberry Pi Zero W – HVAC Air-Duct Pressure Monitor
 * Sensor : Sensirion SDP810-500Pa differential pressure sensor
 * Bus    : I2C bus 1 (GPIO2=SDA, GPIO3=SCL), address 0x25
 * Output : hvac_pressure_log.txt (CSV: timestamp,pressure_Pa,temperature_C)
 *
 * Build  : gcc -O2 -Wall -Wextra -o hvac_monitor hvac_monitor.c -lgpiod
 * Run    : sudo ./hvac_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define LOG_FILE       "hvac_pressure_log.txt"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MEAS_DELAY_MS  50         /* SDP810 measurement settling time */

/* ---- SDP810 CRC-8 (polynomial 0x31, init 0xFF) per datasheet ---- */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Globals for signal-handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log    = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Timestamp helper ---- */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
    else
        snprintf(buf, len, "1970-01-01 00:00:00");
}

/* ---- Cleanup all resources ---- */
static void cleanup(void)
{
    if (g_log) {
        fflush(g_log);
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* gpiod_chip_close() is safe to call even if not held */
}

int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "i2c_open(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HVAC monitor started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        /*
         * Trigger a single-measurement conversion.
         * SDP810 command 0x362F: clock stretching disabled, continuous mode off.
         */
        uint8_t cmd[2] = { 0x36, 0x2F };
        if (i2c_write(g_i2c_fd, cmd, 2) != 0) {
            fprintf(g_log, "%s,ERROR,I2C write failed: %s\n",
                    ts, strerror(errno));
            fflush(g_log);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Wait for conversion to complete (>= 50 ms per datasheet) */
        usleep(MEAS_DELAY_MS * 1000);

        /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, scale(3)+crc */
        uint8_t buf[9];
        ssize_t n = i2c_read(g_i2c_fd, buf, sizeof(buf));
        if (n != (ssize_t)sizeof(buf)) {
            fprintf(g_log, "%s,ERROR,I2C read failed: expected %zu bytes, got %zd (%s)\n",
                    ts, sizeof(buf), n, n < 0 ? strerror(errno) : "short read");
            fflush(g_log);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* CRC validation */
        if (sdp_crc8(&buf[0], 2) != buf[2]) {
            fprintf(g_log, "%s,ERROR,pressure CRC mismatch\n", ts);
            fflush(g_log);
            sleep(SAMPLE_PERIOD);
            continue;
        }
        if (sdp_crc8(&buf[3], 2) != buf[5]) {
            fprintf(g_log, "%s,ERROR,temperature CRC mismatch\n", ts);
            fflush(g_log);
            sleep(SAMPLE_PERIOD);
            continue;
        }
        if (sdp_crc8(&buf[6], 3) != buf[8]) {
            fprintf(g_log, "%s,ERROR,scale-factor CRC mismatch\n", ts);
            fflush(g_log);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /*
         * Convert raw values.
         * Pressure  : 16-bit signed, LSB = 0.01 Pa
         * Temperature: 16-bit signed, LSB = 0.01 °C
         * Scale     : 24-bit signed, LSB = 1
         */
        int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
        int32_t scale_factor = (int32_t)((buf[6] << 16) | (buf[7] << 8) | buf[8]);

        if (scale_factor == 0) {
            fprintf(g_log, "%s,ERROR,invalid scale factor (0)\n", ts);
            fflush(g_log);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float pressure_Pa = (float)raw_pressure / scale_factor;
        float temp_C      = (float)raw_temp     / scale_factor;

        /* Log to CSV */
        fprintf(g_log, "%s,%.2f,%.2f\n", ts, pressure_Pa, temp_C);
        fflush(g_log);

        printf("%s  Pressure: %.2f Pa  Temperature: %.2f C\n",
               ts, pressure_Pa, temp_C);

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

