#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SCD40_ADDR 0x61
#define BUFFER_SIZE 100
#define LOG_FILE_DIR "/var/log/scd40_data"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define LOGGING_INTERVAL_SEC 60
#define READ_INTERVAL_SEC 5
#define STARTUP_DELAY_SEC 1

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_GET_DATA_READY_STATUS 0xE4B8

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s (errno: %d - %s)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message, errno, strerror(errno));
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 8; bit > 0; bit--) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_command(uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        log_error("I2C write command failed");
        return -1;
    }
    return 0;
}

static int i2c_read_data(uint8_t *data, int len) {
    if (i2cReadDevice(i2c_handle, (char *)data, len) != len) {
        log_error("I2C read data failed");
        return -1;
    }
    return 0;
}

static int read_scd40_data(sensor_data_t *data) {
    uint8_t buf[9];
    if (i2c_write_command(CMD_READ_MEASUREMENT) != 0) {
        return -1;
    }
    gpioDelay(10000);
    if (i2c_read_data(buf, 9) != 0) {
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        log_error("CRC check failed for CO2");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        log_error("CRC check failed for temperature");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        log_error("CRC check failed for humidity");
        return -1;
    }
    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (float)((buf[3] << 8) | buf[4]) / 100.0f;
    data->humidity = (float)((buf[6] << 8) | buf[7]) / 100.0f;
    return 0;
}

static void buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void buffer_add(circular_buffer_t *cb, sensor_data_t data) {
    pthread_mutex_lock(&cb->mutex);
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

static int buffer_get(circular_buffer_t *cb, sensor_data_t *data, int index) {
    pthread_mutex_lock(&cb->mutex);
    if (index < 0 || index >= cb->count) {
        pthread_mutex_unlock(&cb->mutex);
        return -1;
    }
    int actual_index = (cb->tail + index) % BUFFER_SIZE;
    *data = cb->data[actual_index];
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

static int buffer_count(circular_buffer_t *cb) {
    int count;
    pthread_mutex_lock(&cb->mutex);
    count = cb->count;
    pthread_mutex_unlock(&cb->mutex);
    return count;
}

static void *logging_function(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOGGING_INTERVAL_SEC);
        int count = buffer_count(&buffer);
        if (count == 0) {
            continue;
        }
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char filename[256];
        snprintf(filename, sizeof(filename), "%s/scd40_data_%d-%02d-%02d_%02d-%02d-%02d.csv",
                 LOG_FILE_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec);
        FILE *fp = fopen(filename, "w");
        if (fp == NULL) {
            log_error("Error opening log file for writing");
            continue;
        }
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
        for (int i = 0; i < count; i++) {
            sensor_data_t data;
            if (buffer_get(&buffer, &data, i) == 0) {
                time_t timestamp = time(NULL);
                struct tm *tm_info = localtime(&timestamp);
                char timestamp_str[20];
                strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
                fprintf(fp, "%s,%u,%.2f,%.2f\n", timestamp_str, data.co2, data.temperature, data.humidity);
            }
        }
        fclose(fp);
        buffer_init(&buffer);
    }
    return NULL;
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int create_log_directory(void) {
    struct stat st = {0};
    if (stat(LOG_FILE_DIR, &st) == -1) {
        if (mkdir(LOG_FILE_DIR, 0755) == -1) {
            log_error("Error creating log directory");
            return -1;
        }
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (create_log_directory() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    buffer_init(&buffer);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    if (i2c_write_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        log_error("Failed to start periodic measurement");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    sleep(STARTUP_DELAY_SEC);
    if (pthread_create(&logging_thread, NULL, logging_function, NULL) != 0) {
        log_error("Error creating logging thread");
        i2c_write_command(CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) {
        sensor_data_t data;
        if (read_scd40_data(&data) == 0) {
            buffer_add(&buffer, data);
        }
        sleep(READ_INTERVAL_SEC);
    }
    i2c_write_command(CMD_STOP_PERIODIC_MEASUREMENT);
    pthread_join(logging_thread, NULL);
    int count = buffer_count(&buffer);
    if (count > 0) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char filename[256];
        snprintf(filename, sizeof(filename), "%s/scd40_data_%d-%02d-%02d_%02d-%02d-%02d.csv",
                 LOG_FILE_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec);
        FILE *fp = fopen(filename, "w");
        if (fp == NULL) {
            log_error("Error opening final log file for writing");
        } else {
            fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");
            for (int i = 0; i < count; i++) {
                sensor_data_t data;
                if (buffer_get(&buffer, &data, i) == 0) {
                    time_t timestamp = time(NULL);
                    struct tm *tm_info = localtime(&timestamp);
                    char timestamp_str[20];
                    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
                    fprintf(fp, "%s,%u,%.2f,%.2f\n", timestamp_str, data.co2, data.temperature, data.humidity);
                }
            }
            fclose(fp);
        }
    }
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

