/*
 * SDP810-500Pa differential pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_logger sdp810_logger.c
 * Run:    ./sdp810_logger   (Ctrl-C to stop)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25          /* SDP810 default I2C address (ADDR pin tied to GND) */
#define LOG_FILE       "sdp810_log.txt"
#define SAMPLE_PERIOD  1.0           /* seconds between samples */
#define MEAS_DELAY_US  45000         /* 45 ms conversion time */

/* SDP810 command: continuous measurement, averaging disabled, clock stretching enabled */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x2F };

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                 */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read one sample from the SDP810                                     */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.           */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t buf[9];

    /* Trigger continuous measurement */
    if (i2cWriteDevice(handle, (char *)CMD_CONT_MEAS, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed\n");
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, scale(2)+crc */
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (expected 9 bytes)\n");
        return -1;
    }

    /* Validate CRCs */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] pressure CRC mismatch\n");
        return -2;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] temperature CRC mismatch\n");
        return -2;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] scale-factor CRC mismatch\n");
        return -2;
    }

    /*
     * SDP810 differential pressure register (bytes 0-1, signed 16-bit).
     * Scale factor is bytes 6-7 (signed 16-bit).
     * Temperature is bytes 3-4 (signed 16-bit).
     */
    int16_t dp_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t sc_raw = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t t_raw  = (int16_t)((buf[3] << 8) | buf[4]);

    /*
     * Per SDP810 datasheet:
     *   pressure [Pa] = dp_raw / sc_raw
     *   temperature [°C] = t_raw / 200.0
     */
    *pressure    = (float)dp_raw / (float)sc_raw;
    *temperature = (float)t_raw / 200.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to CSV                                                */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s for append\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "timestamp,pressure_Pa,temperature_C\n");

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810 logger started. Logging to %s. Press Ctrl-C to stop.\n",
           LOG_FILE);

    float pressure, temperature;

    while (g_running) {
        int rc = read_sdp810(g_i2c_handle, &pressure, &temperature);

        if (rc == 0) {
            log_sample(g_log_file, pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed (rc=%d)\n", rc);
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay((int)(SAMPLE_PERIOD * 1000000.0 / 10.0));
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

