#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x28
#define TRIGGER_DELAY_US 10000   /* 10 ms */
#define LOOP_DELAY_US   5000000 /* 5 seconds */
#define FILENAME       "environmental_data.txt"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read pressure (Pa) and temperature (°C) from the TDK ICP-10110.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_sensor(int handle, float *pressure, float *temperature)
{
    char buf[6];
    int  rc;

    /* Trigger a measurement by writing a zero byte to the sensor. */
    rc = i2cWriteByte(handle, 0x00);
    if (rc < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", rc);
        return -1;
    }

    gpioDelay(TRIGGER_DELAY_US);

    /* Read 6 bytes: pressure(3) + CRC, temperature(3) + CRC. */
    rc = i2cReadDevice(handle, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading sensor data: expected 6 bytes, got %d\n", rc);
        return -1;
    }

    /*
     * The ICP-10110 returns 20-bit pressure and 20-bit temperature values.
     * The first two bytes of each group are the MSBs, the third byte is the
     * LSB (bits 7:4 are the upper nibble of the 20-bit value).
     */
    uint32_t raw_pressure    = ((uint32_t)(uint8_t)buf[0] << 12) |
                              ((uint32_t)(uint8_t)buf[1] << 4)  |
                              ((uint32_t)(uint8_t)buf[2] >> 4);
    uint32_t raw_temperature = ((uint32_t)(uint8_t)buf[3] << 12) |
                              ((uint32_t)(uint8_t)buf[4] << 4)  |
                              ((uint32_t)(uint8_t)buf[5] >> 4);

    /* Sign-extend 20-bit values to 32-bit. */
    if (raw_pressure & 0x80000)    raw_pressure    |= 0xFFF00000;
    if (raw_temperature & 0x80000) raw_temperature |= 0xFFF00000;

    /*
     * Convert to physical units.
     * Pressure:    raw / 2^12  [Pa]
     * Temperature: raw / 2^12  [°C]
     */
    *pressure    = (float)raw_pressure    / 4096.0f;
    *temperature = (float)raw_temperature / 4096.0f;

    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t     rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", timeinfo);
}

static int log_data(FILE *fp, const char *timestamp, float pressure, float temperature)
{
    if (fprintf(fp, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
                timestamp, pressure, temperature) < 0) {
        perror("Error writing to file");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("Error flushing file");
        return -1;
    }
    return 0;
}

int main(void)
{
    int  i2c_handle = -1;
    FILE *fp        = NULL;
    int  rc         = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus. */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        goto cleanup_gpio;
    }

    /* Open log file in append mode. */
    fp = fopen(FILENAME, "a");
    if (fp == NULL) {
        perror("Error opening file");
        goto cleanup_i2c;
    }

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (read_sensor(i2c_handle, &pressure, &temperature) == 0) {
            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));

            if (log_data(fp, timestamp, pressure, temperature) == 0) {
                printf("%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
                       timestamp, pressure, temperature);
            }
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly. */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nExiting gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup_file:
    if (fp != NULL) {
        fclose(fp);
    }
cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
cleanup_gpio:
    gpioTerminate();
    return rc;
}

