    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus. */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        goto cleanup_gpio;
    }

    /* Open log file in append mode. */
    fp = fopen(FILENAME, "a");
    if (fp == NULL) {
        perror("Error opening file");
        goto cleanup_i2c;
    }

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (read_sensor(i2c_handle, &pressure, &temperature) == 0) {
            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));

            if (log_data(fp, timestamp, pressure, temperature) == 0) {
                printf("%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
                       timestamp, pressure, temperature);
            }
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly. */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nExiting gracefully...\n");
    rc = EXIT_SUCCESS;

cleanup_file:
    if (fp != NULL) {
        fclose(fp);
    }
cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
cleanup_gpio:
    gpioTerminate();
    return rc;
}

