/*
 * Raspberry Pi 4 Model B – TDK ICP-10125 barometric pressure sensor reader
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   ICP-10125 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *   LED anode      -> GPIO17 (BCM 17, pin 11) via 330 Ω resistor
 *   LED cathode    -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o icp10125 icp10125.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x40          /* TDK ICP-10125 default I2C address */
#define GPIO_CHIP      "gpiochip4"   /* BCM GPIO controller on Pi 4 */
#define GPIO_LINE      17            /* BCM 17 */
#define PRESSURE_THRESHOLD 95000.0f  /* Pa */
#define POLL_INTERVAL_US 1000000     /* 1 s */
#define TRIGGER_DELAY_US 20000       /* 20 ms */

/* ICP-10125 register addresses (datasheet section 4.2) */
#define REG_PRESSURE_MSB 0x00
#define REG_TEMP_MSB     0x02
#define REG_CRC_MSB      0x04

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF (datasheet section 4.3) */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read exactly `len` bytes starting at `reg` from the ICP-10125.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int icp10125_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read (reg 0x%02X, want %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Trigger a measurement and read the 6-byte result.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int icp10125_read(int fd, float *pressure, float *temperature)
{
    uint8_t raw[6];

    /* Trigger measurement: write 0x00 to the CRC register */
    if (write(fd, (uint8_t[]){REG_CRC_MSB, 0x00}, 2) != 2) {
        fprintf(stderr, "I2C trigger write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(TRIGGER_DELAY_US);

    if (icp10125_read_reg(fd, REG_PRESSURE_MSB, raw, sizeof(raw)) != 0)
        return -1;

    /* CRC covers pressure (bytes 0-1), temperature (bytes 2-3), and CRC (byte 4) */
    if (crc8(raw, 5) != raw[5]) {
        fprintf(stderr, "CRC mismatch on sensor data\n");
        return -2;
    }

    uint16_t p_raw = ((uint16_t)raw[0] << 8) | raw[1];
    uint16_t t_raw = ((uint16_t)raw[2] << 8) | raw[3];

    /*
     * Conversion formulas from TDK ICP-10125 datasheet (section 4.4).
     * Pressure:  Pa = (p_raw / 65536.0f) * 100000.0f
     * Temperature: °C = (t_raw / 65536.0f) * 165.0f - 40.0f
     */
    *pressure    = ((float)p_raw / 65536.0f) * 100000.0f;
    *temperature = ((float)t_raw / 65536.0f) * 165.0f - 40.0f;

    return 0;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

int main(void)
{
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ICP10125_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Open GPIO chip and request line --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "icp10125-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("ICP-10125 pressure sensor reader started.\n");
    printf("I2C bus : %s  address : 0x%02X\n", I2C_BUS, ICP10125_ADDR);
    printf("LED     : BCM %d\n", GPIO_LINE);
    printf("Threshold: %.1f Pa\n", PRESSURE_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        float pressure, temperature;

        int rc = icp10125_read(fd, &pressure, &temperature);
        if (rc == 0) {
            printf("Pressure: %.2f Pa  Temperature: %.2f °C\n",
                   pressure, temperature);

            if (pressure < PRESSURE_THRESHOLD) {
                /* 5 Hz blink: 100 ms on, 100 ms off */
                for (int i = 0; i < 5 && g_running; i++) {
                    gpiod_line_set_value(line, 1);
                    sleep_us(100000);
                    if (!g_running) break;
                    gpiod_line_set_value(line, 0);
                    sleep_us(100000);
                }
            } else {
                /* 1 Hz blink: 500 ms on, 500 ms off */
                for (int i = 0; i < 5 && g_running; i++) {
                    gpiod_line_set_value(line, 1);
                    sleep_us(500000);
                    if (!g_running) break;
                    gpiod_line_set_value(line, 0);
                    sleep_us(500000);
                }
            }
        } else if (rc == -1) {
            /* I2C bus error – ensure LED is off and back off briefly */
            gpiod_line_set_value(line, 0);
            sleep_us(100000);
        } else {
            /* CRC mismatch – ensure LED is off and back off briefly */
            gpiod_line_set_value(line, 0);
            sleep_us(100000);
        }

        /* Poll every second (interruptible by signal) */
        for (int i = 0; i < 10 && g_running; i++)
            sleep_us(100000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    if (fd >= 0)
        close(fd);

    return ret;
}

