#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define READ_INTERVAL_SEC 2
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *ambient, float *object) {
    int raw_ambient, raw_object;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        raw_ambient = i2cReadWordData(handle, 0x06);
        if (raw_ambient >= 0) {
            raw_object = i2cReadWordData(handle, 0x07);
            if (raw_object >= 0) {
                *ambient = (float)raw_ambient * 0.02 - 273.15;
                *object = (float)raw_object * 0.02 - 273.15;
                return 0;
            }
        }
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

static void control_fan(int gpio, float object_temp) {
    static int fan_on = 0;
    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(gpio, 1);
        fan_on = 1;
        printf("Fan ON (temp=%.2f C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(gpio, 0);
        fan_on = 0;
        printf("Fan OFF (temp=%.2f C)\n", object_temp);
    }
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, ambient, object);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", MLX90614_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float ambient, object;
        if (read_temperature(i2c_handle, &ambient, &object) == 0) {
            log_temperature(ambient, object);
            control_fan(FAN_GPIO, object);
        } else {
            fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
        }
        sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

