#define I2C_BUS 1
#define SHT40_ADDR 0x45
#define MEASURE_CMD_HIGH 0x2C
#define MEASURE_CMD_LOW 0x06
#define MEASUREMENT_DELAY_US 15000
#define MAX_RETRIES 3
#define HTTP_PORT 8080
#define HTTP_BUFFER_SIZE 4096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    unsigned char data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, (char *)data, 6) != 6) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        unsigned int temp_ticks = (data[0] << 8) | data[1];
        unsigned int hum_ticks = (data[3] << 8) | data[4];

        *temperature = -45.0f + (175.0f * (float)temp_ticks / 65535.0f);
        *humidity = 100.0f * (float)hum_ticks / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1;
}

void format_html(float temperature, float humidity, char *buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(buffer, buffer_size,
             "HTTP/1.1 200 OK\r\n"
             "Content-Type: text/html\r\n"
             "Connection: close\r\n"
             "\r\n"
             "<!DOCTYPE html>\n"
             "<html>\n"
             "  <head>\n"
             "    <title>SHT40 Sensor Data</title>\n"
             "    <meta http-equiv=\"refresh\" content=\"5\">\n"
             "  </head>\n"
             "  <body>\n"
             "    <h1>SHT40 Sensor Data</h1>\n"
             "    <p>Timestamp: %s</p>\n"
             "    <p>Temperature: %.2f &deg;C</p>\n"
             "    <p>Humidity: %.2f %%</p>\n"
             "  </body>\n"
             "</html>\n",
             timestamp, temperature, humidity);
}

int main() {
    float temperature, humidity;
    char html_buffer[HTTP_BUFFER_SIZE];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SHT40 sensor data streaming to HTTP server on port %d...\n", HTTP_PORT);

    while (running) {
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            format_html(temperature, humidity, html_buffer, sizeof(html_buffer));
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
            snprintf(html_buffer, sizeof(html_buffer),
                     "HTTP/1.1 500 Internal Server Error\r\n"
                     "Content-Type: text/html\r\n"
                     "Connection: close\r\n"
                     "\r\n"
                     "<!DOCTYPE html>\n"
                     "<html>\n"
                     "  <head>\n"
                     "    <title>Error</title>\n"
                     "  </head>\n"
                     "  <body>\n"
                     "    <h1>Error</h1>\n"
                     "    <p>Failed to read sensor data.</p>\n"
                     "  </body>\n"
                     "</html>\n");
        }

        printf("Sending HTTP response...\n");
        write(1, html_buffer, strlen(html_buffer));
        fflush(stdout);

        gpioDelay(5000000);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

