/*
 * HDC2010 Temperature & Humidity Sensor Reader
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: TI HDC2010, 7-bit I2C address 0x40
 *
 * Build:  gcc -O2 -Wall -Wextra -o hdc2010 hdc2010.c -lgpiod
 * Run:    sudo ./hdc2010
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- HDC2010 constants (per TI datasheet) ---- */
#define HDC2010_ADDR            0x40
#define REG_TEMP_LOW            0x00
#define REG_TEMP_HIGH           0x01
#define REG_HUMID_LOW           0x02
#define REG_HUMID_HIGH          0x03
#define REG_MEAS_CONFIG         0x0F
#define REG_INT_CONFIG          0x0E
#define REG_INT_STATUS          0x0D
#define REG_DEVICE_CONFIG       0x0A
#define REG_MANUFACTURER_ID     0xFE
#define REG_DEVICE_ID           0xFF

#define HDC2010_MANUFACTURER_ID 0x5449  /* 'TI' */
#define HDC2010_DEVICE_ID       0x1050  /* HDC2010 */

#define MEAS_CONFIG_TEMP_EN     0x0001
#define MEAS_CONFIG_HUMID_EN    0x0002
#define MEAS_CONFIG_MODE_TEMP   0x0000
#define MEAS_CONFIG_MODE_HUMID  0x0004
#define MEAS_CONFIG_TRIG        0x0008
#define MEAS_CONFIG_HEAT_EN     0x0080

#define MEAS_CONFIG_MASK        0x008F

#define I2C_BUS                 "/dev/i2c-1"
#define POLL_TIMEOUT_MS         500
#define POLL_INTERVAL_US        10000   /* 10 ms */
#define SAMPLE_INTERVAL_S       5
#define MAX_RETRIES             3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; do not call non-async-signal-safe  */
/* functions here.  The main loop checks g_running and exits cleanly. */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                              */
/* ------------------------------------------------------------------ */

/*
 * Write a 16-bit value to a 16-bit-addressed register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value & 0xFF);
    buf[2] = (uint8_t)((value >> 8) & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from a 16-bit-addressed register.
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write pointer 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read two bytes */
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/*
 * Read a single byte from a 16-bit-addressed register.
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    uint8_t buf[1];

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write pointer 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read one byte */
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = buf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                  */
/* ------------------------------------------------------------------ */

/*
 * Verify the sensor identity by reading the manufacturer and device ID
 * registers.  Returns 0 on success, -1 on error.
 */
static int hdc2010_verify_identity(int fd)
{
    uint16_t manuf_id = 0, device_id = 0;

    if (i2c_read_reg16(fd, REG_MANUFACTURER_ID, &manuf_id) != 0)
        return -1;
    if (i2c_read_reg16(fd, REG_DEVICE_ID, &device_id) != 0)
        return -1;

    if (manuf_id != HDC2010_MANUFACTURER_ID) {
        fprintf(stderr, "Manufacturer ID mismatch: got 0x%04X, expected 0x%04X\n",
                manuf_id, HDC2010_MANUFACTURER_ID);
        return -1;
    }
    if (device_id != HDC2010_DEVICE_ID) {
        fprintf(stderr, "Device ID mismatch: got 0x%04X, expected 0x%04X\n",
                device_id, HDC2010_DEVICE_ID);
        return -1;
