 * Returns 0 on success, -1 on error.
 */
static int hdc2010_trigger_measurement(int fd)
{
    uint16_t config = 0;

    /* Read current configuration */
    if (i2c_read_reg16(fd, REG_MEAS_CONFIG, &config) != 0)
        return -1;

    /* Enable temperature and humidity, set mode to temperature, trigger */
    config |= MEAS_CONFIG_TEMP_EN | MEAS_CONFIG_HUMID_EN |
              MEAS_CONFIG_MODE_TEMP | MEAS_CONFIG_TRIG;

    if (i2c_write_reg16(fd, REG_MEAS_CONFIG, config) != 0)
        return -1;

    /* Poll bit 0 of MEAS_CONFIG until it reads 0 (conversion complete) */
    for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS; elapsed += 10) {
        uint16_t cfg = 0;
        if (i2c_read_reg16(fd, REG_MEAS_CONFIG, &cfg) != 0)
            return -1;
        if ((cfg & MEAS_CONFIG_TRIG) == 0)
            return 0;
        usleep(POLL_INTERVAL_US);
    }

