     * HDC2010 conversion formulas (per datasheet):
     *   T  = raw_t  / 65536.0 * 165.0 - 40.0
     *   RH = raw_h  / 65536.0 * 100.0
     */
    *temp_c = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
