    if (ioctl(g_i2c_fd, I2C_SLAVE, HDC2010_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                HDC2010_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    if (hdc2010_verify_identity(g_i2c_fd) != 0) {
        fprintf(stderr, "HDC2010 not detected at address 0x%02X\n",
                HDC2010_ADDR);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("HDC2010 initialized.  Sampling every %d seconds.  Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_S);

    /* Main sampling loop */
    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        int success = 0;

        /*
         * Trigger measurement with retries.
         * On transient I2C errors, retry up to MAX_RETRIES times.
         */
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (hdc2010_trigger_measurement(g_i2c_fd) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Measurement attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                sleep(1);
        }

        if (!success) {
            fprintf(stderr, "Failed to trigger measurement after %d attempts.\n",
                    MAX_RETRIES);
            /* Brief pause before retrying to avoid log flooding */
            sleep(1);
            continue;
        }

        /* Read data with retries */
        success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (hdc2010_read_data(g_i2c_fd, &temperature, &humidity) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Data read attempt %d/%d failed\n",
                    attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                sleep(1);
        }

        if (!success) {
            fprintf(stderr, "Failed to read sensor data after %d attempts.\n",
                    MAX_RETRIES);
            sleep(1);
            continue;
        }

        /* Print results */
        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        printf("[%s] Temperature: %.2f C, Humidity: %.2f %%\n",
               ts, temperature, humidity);
        fflush(stdout);

        /* Sleep for the sample interval, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

