/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x25 (SDP800 default)
 * Measurement command: 0x362F (continuous measurement, clock stretching disabled)
 * Conversion time: ~45 ms
 * Data format: 6 bytes, pressure(2)+CRC, temperature(2)+CRC
 *
 * Build: gcc -O2 -Wall -o sdp800 sdp800.c -lpigpio -lrt
 * Run:   sudo ./sdp800
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x25
#define MEASURE_CMD    0x362F   /* continuous measurement, clock stretching disabled */
#define CONV_TIME_US   45000    /* 45 ms conversion time */
#define SAMPLE_PERIOD  500000   /* 500 ms between samples */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: polynomial 0x31, initial value 0xFF */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read one 6-byte measurement frame from the SDP800.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to write measurement command to I2C device.\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONV_TIME_US);

    /* Read 6 bytes: pressure(2)+CRC, temperature(2)+CRC */
    uint8_t buf[6];
    int n = i2cReadDevice(handle, (char *)buf, 6);
    if (n != 6) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 6).\n", n);
        return -1;
    }

    /* Validate CRC for pressure */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: pressure CRC mismatch (calc=0x%02X recv=0x%02X).\n",
                crc8(&buf[0], 2), buf[2]);
        return -2;
    }

    /* Validate CRC for temperature */
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X recv=0x%02X).\n",
                crc8(&buf[3], 2), buf[5]);
        return -2;
    }

    /* Convert raw big-endian values to signed 16-bit integers */
    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);

    return 0;
}

int main(void)
{
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to SDP800 */
    int handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (pigpio error %d).\n",
                I2C_BUS, SDP800_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP800-500Pa reader started on I2C bus %d, address 0x%02X.\n", I2C_BUS, SDP800_ADDR);
    printf("Press Ctrl+C to stop.\n");

    int16_t pressure, temperature;
