/*
 * Reflow oven controller for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MAX6675 thermocouple amplifier on SPI0 (CE0 / GPIO8)
 *   - Solid-state relay on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o reflow reflow.c -lpigpio -lrt -lm
 * Run:
 *   sudo ./reflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define SSR_GPIO         17         /* BCM 17 */
#define SSR_PWM_RANGE    1000       /* 1000 steps => 1 ms resolution */
#define SSR_PWM_FREQ     1000       /* 1 kHz PWM frequency */

#define LOG_FILE         "reflow_log.csv"
#define PROFILE_FILE     "profile.txt"

#define SAMPLE_PERIOD_US 1000000    /* 1 second */
#define MAX_TEMP_C       250.0
#define MIN_TEMP_C       0.0

/* PID gains (tuned empirically) */
#define KP  1.0
#define KI  0.01
#define KD  0.1

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  read_max6675(float *temp_c);
static int  load_profile(const char *filename, float *profile, int max_points);
static float calculate_pid(float setpoint, float actual, float *integral,
                           float *prev_error, float dt);
static void set_ssr_duty(float duty);
static void log_data(float temp_c, float duty);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MAX6675 read ------------------------------- */

/*
 * MAX6675 SPI protocol (32-bit, Mode 0, MSB first):
 *   D[31:18]  14-bit thermocouple temperature, signed, 0.25 C/bit
 *   D[17:4]   14-bit internal reference temperature, signed, 0.25 C/bit
 *   D[3]      SCV  (short to VCC)
 *   D[2]      SCG  (short to GND)
 *   D[1]      OC   (open circuit)
 *   D[0]      reserved
 *
 * Returns 0 on success and stores the thermocouple temperature in *temp_c.
 * Returns -1 on SPI transfer failure, -2 if the thermocouple is absent
 * (SCV or SCG asserted), -3 if the thermocouple is open circuit.
 */
static int read_max6675(float *temp_c)
{
    char rx[4] = {0, 0, 0, 0};
    int  ret;

    ret = spiRead(g_spi_handle, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "[ERROR] spiRead failed: returned %d (pigpio error %d)\n",
                ret, ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    /* Check fault bits */
    if (raw & 0x00000004) {
        fprintf(stderr, "[ERROR] MAX6675 fault: short to VCC (SCV)\n");
        return -2;
    }
    if (raw & 0x00000002) {
        fprintf(stderr, "[ERROR] MAX6675 fault: short to GND (SCG)\n");
        return -2;
    }
    if (raw & 0x00000001) {
        fprintf(stderr, "[ERROR] MAX6675 fault: open circuit (OC)\n");
        return -3;
    }

    /* Thermocouple temperature: bits 31:18, signed, 0.25 C/bit */
    int16_t tc_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (tc_raw & 0x2000) {
        tc_raw |= 0xC000;          /* sign-extend 14-bit to 16-bit */
    }
    *temp_c = tc_raw * 0.25f;

    return 0;
}

/* ----------------------------- Profile load ------------------------------- */

/*
 * Loads a temperature profile from the given file.
 * Each line must contain: time_seconds,target_temp_celsius
 * Returns the number of points loaded, or -1 on error.
 */
static int load_profile(const char *filename, float *profile, int max_points)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open profile file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    int count = 0;
    char line[256];

    while (fgets(line, sizeof(line), fp)) {
        if (count >= max_points) {
            fprintf(stderr, "[WARN] Profile file has more than %d points; "
                            "truncating.\n", max_points);
            break;
        }

        float t, v;
        if (sscanf(line, "%f,%f", &t, &v) != 2) {
            fprintf(stderr, "[WARN] Skipping malformed line: %s", line);
            continue;
        }

        if (t < 0.0f) {
            fprintf(stderr, "[WARN] Time must be non-negative; skipping line.\n");
            continue;
        }

        if (v < MIN_TEMP_C || v > MAX_TEMP_C) {
            fprintf(stderr, "[WARN] Target temperature %.2f C out of range [%.0f, %.0f]; "
                            "skipping line.\n", v, MIN_TEMP_C, MAX_TEMP_C);
            continue;
        }

        profile[count++] = v;
    }

    fclose(fp);
    return count;
}

/* ----------------------------- PID calculation ----------------------------- */

static float calculate_pid(float setpoint, float actual, float *integral,
                           float *prev_error, float dt)
{
    float error = setpoint - actual;

    *integral += error * dt;
    if (*integral > 100.0f) *integral = 100.0f;
    if (*integral < 0.0f)   *integral = 0.0f;

    float derivative = (error - *prev_error) / dt;
    *prev_error = error;

    float output = KP * error + KI * (*integral) + KD * derivative;

    if (output > 1.0f) output = 1.0f;
    if (output < 0.0f) output = 0.0f;

    return output;
}

/* ----------------------------- SSR control -------------------------------- */

static void set_ssr_duty(float duty)
{
    if (duty < 0.0f) duty = 0.0f;
    if (duty > 1.0f) duty = 1.0f;

    int pwm_value = (int)(duty * (float)SSR_PWM_RANGE);
    if (gpioPWM(SSR_GPIO, pwm_value) != 0) {
        fprintf(stderr, "[ERROR] gpioPWM failed for GPIO%d\n", SSR_GPIO);
    }
}

/* ----------------------------- Logging ------------------------------------ */

static void log_data(float temp_c, float duty)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%.2f,%.2f\n", timestamp, temp_c, duty);
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ------------------------------------ */

static void cleanup(void)
{
    /* Ensure SSR is off */
    if (g_spi_handle >= 0) {
        gpioPWM(SSR_GPIO, 0);
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure SSR GPIO */
    if (gpioSetMode(SSR_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode failed for GPIO%d\n", SSR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMrange(SSR_GPIO, SSR_PWM_RANGE);
    gpioSetPWMfrequency(SSR_GPIO, SSR_PWM_FREQ);
    gpioPWM(SSR_GPIO, 0);

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[FATAL] spiOpen failed (channel %d, speed %d): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Temperature (C),Duty Cycle\n");
        fflush(g_log_file);
    }

    /* Load profile */
    const int MAX_PROFILE_POINTS = 100;
    float profile[MAX_PROFILE_POINTS];
    int profile_length = load_profile(PROFILE_FILE, profile, MAX_PROFILE_POINTS);
    if (profile_length <= 0) {
        fprintf(stderr, "[FATAL] No valid profile data loaded. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Loaded %d profile points.\n", profile_length);

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* PID state */
    float integral    = 0.0f;
    float prev_error  = 0.0f;
    float dt          = 1.0f;   /* 1 second */
    int   profile_idx = 0;
    float target_temp = profile[0];

    printf("Reflow started. Press Ctrl+C to stop.\n");

    /* Main control loop */
    while (g_running) {
        float temp_c;
        int   rc;

        rc = read_max6675(&temp_c);
        if (rc != 0) {
            fprintf(stderr, "[ERROR] Sensor read failed (code %d). "
                            "Retrying in 1 s...\n", rc);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Advance profile if we have reached the current setpoint */
        if (temp_c >= target_temp) {
            profile_idx++;
            if (profile_idx < profile_length) {
                target_temp = profile[profile_idx];
                printf("Profile step %d: target %.2f C\n",
                       profile_idx, target_temp);
            } else {
                printf("Profile complete. Reflow cycle complete.\n");
                break;
            }
        }

        float duty = calculate_pid(target_temp, temp_c, &integral,
                                   &prev_error, dt);
        set_ssr_duty(duty);
        log_data(temp_c, duty);

        printf("T=%.2f C  Target=%.2f C  Duty=%.2f%%\n",
               temp_c, target_temp, duty * 100.0f);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    printf("Reflow cycle complete.\n");
    return EXIT_SUCCESS;
}

