    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%.2f,%.2f\n", timestamp, temp_c, duty);
    fflush(g_log_file);
}

/* ----------------------------- Cleanup ------------------------------------ */

static void cleanup(void)
{
    /* Ensure SSR is off */
    if (g_spi_handle >= 0) {
        gpioPWM(SSR_GPIO, 0);
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure SSR GPIO */
    if (gpioSetMode(SSR_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode failed for GPIO%d\n", SSR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMrange(SSR_GPIO, SSR_PWM_RANGE);
    gpioSetPWMfrequency(SSR_GPIO, SSR_PWM_FREQ);
    gpioPWM(SSR_GPIO, 0);

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[FATAL] spiOpen failed (channel %d, speed %d): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Temperature (C),Duty Cycle\n");
        fflush(g_log_file);
    }

    /* Load profile */
    const int MAX_PROFILE_POINTS = 100;
    float profile[MAX_PROFILE_POINTS];
    int profile_length = load_profile(PROFILE_FILE, profile, MAX_PROFILE_POINTS);
    if (profile_length <= 0) {
        fprintf(stderr, "[FATAL] No valid profile data loaded. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Loaded %d profile points.\n", profile_length);

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* PID state */
    float integral    = 0.0f;
    float prev_error  = 0.0f;
    float dt          = 1.0f;   /* 1 second */
    int   profile_idx = 0;
    float target_temp = profile[0];

    printf("Reflow started. Press Ctrl+C to stop.\n");

    /* Main control loop */
    while (g_running) {
        float temp_c;
        int   rc;

        rc = read_max6675(&temp_c);
        if (rc != 0) {
            fprintf(stderr, "[ERROR] Sensor read failed (code %d). "
                            "Retrying in 1 s...\n", rc);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Advance profile if we have reached the current setpoint */
        if (temp_c >= target_temp) {
            profile_idx++;
            if (profile_idx < profile_length) {
                target_temp = profile[profile_idx];
                printf("Profile step %d: target %.2f C\n",
                       profile_idx, target_temp);
            } else {
                printf("Profile complete. Reflow cycle complete.\n");
                break;
            }
        }

        float duty = calculate_pid(target_temp, temp_c, &integral,
                                   &prev_error, dt);
        set_ssr_duty(duty);
        log_data(temp_c, duty);

        printf("T=%.2f C  Target=%.2f C  Duty=%.2f%%\n",
               temp_c, target_temp, duty * 100.0f);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    printf("Reflow cycle complete.\n");
    return EXIT_SUCCESS;
}

