/*
 * Greenhouse heater controller for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - DS18B20 temperature sensor on 1-wire bus (/sys/bus/w1/devices/)
 *   - Relay module (active-high) on GPIO17 (physical pin 11)
 *   - Hardware PWM on GPIO18 (physical pin 12)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o greenhouse greenhouse.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define DS18B20_DIR        "/sys/bus/w1/devices/"
#define DS18B20_ID         "28-000000000000"   /* Replace with actual sensor ID */
#define DS18B20_FILE       DS18B20_DIR DS18B20_ID "/w1_slave"

#define RELAY_GPIO         17
#define PWM_GPIO           18
#define PWM_RANGE          1000
#define PWM_FREQUENCY      1000

#define LOG_FILE           "greenhouse.log"
#define SAMPLE_INTERVAL_S  5

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers (pigpio-style bit-banging on GPIO17/18)                */
/* ------------------------------------------------------------------ */
static int gpio_write(int gpio, int value)
{
    char path[64];
    int fd;
    int ret;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    ret = write(fd, value ? "1" : "0", 1);
    close(fd);
    return (ret == 1) ? 0 : -1;
}

static int gpio_read(int gpio)
{
    char path[64];
    int fd;
    int ret;
    char val;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }
    ret = read(fd, &val, 1);
    close(fd);
    return (ret == 1) ? (val == '1' ? 1 : 0) : -1;
}

/* ------------------------------------------------------------------ */
/* DS18B20 temperature read                                            */
/* ------------------------------------------------------------------ */
static int read_ds18b20(float *temperature)
{
    FILE *fp;
    char line1[256], line2[256];
    uint8_t crc;
    uint8_t data[9];
    int i;

    fp = fopen(DS18B20_FILE, "r");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", DS18B20_FILE, strerror(errno));
        return -1;
    }

    if (!fgets(line1, sizeof(line1), fp)) {
        fprintf(stderr, "fgets(line1): %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (!fgets(line2, sizeof(line2), fp)) {
        fprintf(stderr, "fgets(line2): %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Check CRC */
    if (strncmp(line1, "YES", 3) != 0) {
        fprintf(stderr, "DS18B20 CRC check failed\n");
        return -1;
    }

    /* Parse raw data (9 bytes) */
    for (i = 0; i < 9; i++) {
        data[i] = (uint8_t)strtol(line2 + 3 + i * 3, NULL, 16);
    }

    /* Verify CRC */
    crc = 0;
    for (i = 0; i < 8; i++) {
        crc = crc ^ data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01)
                crc = (crc >> 1) ^ 0x8C;
            else
                crc >>= 1;
        }
    }
    if (crc != data[8]) {
        fprintf(stderr, "DS18B20 CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc, data[8]);
        return -1;
    }

    /* Convert to Celsius */
    int16_t raw = (int16_t)((data[1] << 8) | data[0]);
    *temperature = (float)raw / 16.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* PID control                                                         */
/* ------------------------------------------------------------------ */
static float pid_control(float setpoint, float current_temp,
                         float *integral, float *prev_error,
                         float kp, float ki, float kd)
{
    float error = setpoint - current_temp;
    *integral += error;
    float derivative = error - *prev_error;
    float output = kp * error + ki * (*integral) + kd * derivative;
    *prev_error = error;
    return output;
}

/* ------------------------------------------------------------------ */
/* PWM control                                                         */
/* ------------------------------------------------------------------ */
static int pwm_set(int gpio, int duty_percent)
{
    if (duty_percent < 0)   duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int duty = (duty_percent * PWM_RANGE) / 100;
    char path[64];
    int fd;
    int ret;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }

    char buf[32];
    snprintf(buf, sizeof(buf), "%d", duty);
    ret = write(fd, buf, strlen(buf));
    close(fd);
    return (ret > 0) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float avg_temp, float setpoint, float pid_out, int pwm_duty)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s, %.2f, %.2f, %.2f, %d\n",
            ts, avg_temp, setpoint, pid_out, pwm_duty);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure relay is off */
    gpio_write(RELAY_GPIO, 0);
    /* Ensure PWM is off */
    pwm_set(PWM_GPIO, 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float setpoint = 25.0f;
    float kp = 1.0f, ki = 0.1f, kd = 0.01f;
    float integral = 0.0f, prev_error = 0.0f;
    float temperatures[5] = {0.0f};
    int sample_count = 0;
    int pwm_duty = 0;
    int i;

    /* Parse command-line arguments */
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return EXIT_FAILURE;
    }
    setpoint = atof(argv[1]);
    kp = atof(argv[2]);
    ki = atof(argv[3]);
    kd = atof(argv[4]);

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (gpio_write(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialize relay GPIO\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (pwm_set(PWM_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialize PWM GPIO\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Greenhouse heater controller started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp;

        if (read_ds18b20(&temp) == 0) {
            temperatures[sample_count % 5] = temp;
            sample_count++;

            float avg_temp = 0.0f;
            for (i = 0; i < 5; i++) avg_temp += temperatures[i];
            avg_temp /= 5.0f;

            float pid_out = pid_control(setpoint, avg_temp,
                                        &integral, &prev_error,
                                        kp, ki, kd);

            /* Clamp PID output to 0-100 */
            if (pid_out < 0.0f)   pid_out = 0.0f;
            if (pid_out > 100.0f) pid_out = 100.0f;

            pwm_duty = (int)pid_out;
            if (pwm_set(PWM_GPIO, pwm_duty) < 0) {
                fprintf(stderr, "PWM write failed\n");
            }

            if (avg_temp > setpoint) {
                gpio_write(RELAY_GPIO, 1);
            } else {
                gpio_write(RELAY_GPIO, 0);
            }

            log_data(avg_temp, setpoint, pid_out, pwm_duty);
            printf("Temp: %.2f C, Setpoint: %.2f C, PID: %.2f, PWM: %d%%\n",
                   avg_temp, setpoint, pid_out, pwm_duty);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying...\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

