            printf("Temp: %.2f C, Setpoint: %.2f C, PID: %.2f, PWM: %d%%\n",
                   avg_temp, setpoint, pid_out, pwm_duty);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying...\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

