/*
 * AHT20 humidity monitor with relay control on Raspberry Pi 5.
 *
 * Wiring:
 *   AHT20 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   AHT20 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   AHT20 VCC  -> 3.3 V
 *   AHT20 GND  -> GND
 *   Relay IN   -> GPIO17 (pin 11) via suitable driver module
 *   Relay VCC  -> 5 V
 *   Relay GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o aht20_monitor aht20_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define AHT20_CMD_MEAS 0xAC
#define AHT20_CMD_SOFT 0xBA
#define AHT20_CMD_ID   0xBE
#define AHT20_CMD_RESET 0xBA

#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define POLL_INTERVAL  5
#define MEAS_DELAY_MS  80
#define RETRY_COUNT    3
#define RETRY_DELAY_MS 10

#define GPIO_CHIP      "gpiochip4"   /* BCM GPIO bank on Pi 5 */
#define GPIO_LINE      17

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read(%zu bytes) failed: got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* AHT20                                                               */
/* ------------------------------------------------------------------ */

static int aht20_reset(int fd)
{
    if (i2c_write_cmd(fd, AHT20_CMD_RESET) < 0)
        return -1;
    usleep(15000);   /* datasheet: wait >= 15 ms after reset */
    return 0;
}

static int aht20_read_id(int fd, uint8_t *id)
{
    if (i2c_write_cmd(fd, AHT20_CMD_ID) < 0)
        return -1;
    usleep(1000);
    if (i2c_read_bytes(fd, id, 7) < 0)
        return -1;
    /* Byte 0 = 0x34 (fixed), bytes 1-3 = chip ID, byte 4 = reserved,
     * byte 5 = checksum, byte 6 = status. */
    if (id[0] != 0x34) {
        fprintf(stderr, "AHT20 ID mismatch: got 0x%02X, expected 0x34\n", id[0]);
        return -1;
    }
    return 0;
}

/*
 * Trigger a measurement and read the 6-byte result.
 * Returns 0 on success and fills *humidity (percent).
 * Returns -1 on any I2C error.
 */
static int aht20_read_humidity(int fd, float *humidity)
{
    uint8_t buf[6];
    int ok = 0;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (i2c_write_cmd(fd, AHT20_CMD_MEAS) < 0)
            goto retry;
        usleep(MEAS_DELAY_MS * 1000);

        if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
            goto retry;

        /* Status byte: bit 0 = busy, bit 1 = calibrated. */
        if (buf[6] & 0x01) {
            fprintf(stderr, "AHT20 busy (status=0x%02X)\n", buf[6]);
            goto retry;
        }
        if (!(buf[6] & 0x02)) {
            fprintf(stderr, "AHT20 not calibrated (status=0x%02X)\n", buf[6]);
            goto retry;
        }

        /* Humidity: 20-bit value, LSB first. */
        uint32_t raw = ((uint32_t)buf[1] << 12) |
                       ((uint32_t)buf[2] << 4)  |
                       ((uint32_t)buf[3] >> 4);
        *humidity = (float)raw / 1048576.0f * 100.0f;
        ok = 1;
        break;

    retry:
        if (attempt < RETRY_COUNT - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }

    if (!ok)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO                                                                */
/* ------------------------------------------------------------------ */

static int gpio_set_output(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "GPIO set_value(%d) failed: %s\n",
                value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Verify sensor identity */
    uint8_t id[7];
    if (aht20_read_id(fd, id) < 0) {
        fprintf(stderr, "AHT20 not detected at 0x%02X\n", AHT20_ADDR);
        goto cleanup;
    }

    /* Reset sensor */
    if (aht20_reset(fd) < 0) {
        fprintf(stderr, "AHT20 reset failed\n");
        goto cleanup;
    }

    /* Open GPIO chip and request relay line */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    relay = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay, "aht20_monitor", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("AHT20 monitor started.  Polling every %d s.  Ctrl+C to exit.\n",
           POLL_INTERVAL);

    int relay_on = 0;

    while (g_running) {
        float humidity;

        if (aht20_read_humidity(fd, &humidity) < 0) {
            fprintf(stderr, "Sensor read failed after %d retries; "
                            "continuing to monitor.\n", RETRY_COUNT);
            sleep(POLL_INTERVAL);
            continue;
        }

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

        printf("[%s] Humidity: %.2f %%\n", ts, humidity);

        if (humidity > HUMIDITY_HIGH && !relay_on) {
            if (gpio_set_output(relay, 1) == 0) {
                relay_on = 1;
                printf("  -> Dehumidifier ON\n");
            }
        } else if (humidity < HUMIDITY_LOW && relay_on) {
            if (gpio_set_output(relay, 0) == 0) {
                relay_on = 0;
                printf("  -> Dehumidifier OFF\n");
            }
        }

        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay) {
        gpiod_line_set_value(relay, 0);   /* ensure relay is off */
        gpiod_line_release(relay);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (fd >= 0)
        close(fd);

    return ret;
}

