/*
 * HTU21D Humidity Sensor Reader for Raspberry Pi Zero W
 *
 * Reads relative humidity from an HTU21D sensor on /dev/i2c-1 (address 0x40)
 * and posts the reading as a JSON document to http://api.example.com/humidity.
 *
 * Build: gcc -O2 -Wall -Wextra -o htu21d_reader htu21d_reader.c -lrt
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <syslog.h>

#define I2C_BUS          "/dev/i2c-1"
#define HTU21D_ADDR      0x40
#define API_ENDPOINT     "http://api.example.com/humidity"
#define POLL_INTERVAL_S  60
#define MAX_RETRIES      3
#define MEASURE_DELAY_US 15000   /* 15 ms max conversion time */

/* HTU21D commands */
#define CMD_TEMP_HOLD    0xE3
#define CMD_HUMID_HOLD   0xE5
#define CMD_RESET        0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_sock_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed (cmd 0x%02X): %s", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        syslog(LOG_ERR, "I2C read failed: expected %zu bytes, got %zd (%s)",
               len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* HTU21D measurement                                                  */
/* ------------------------------------------------------------------ */
/*
 * CRC-8 polynomial 0x31, init 0x00 (per HTU21D datasheet).
 * Returns 0 on success, -1 on CRC mismatch.
 */
static int htu21d_crc8(const uint8_t *data, size_t len, uint8_t expected)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return (crc == expected) ? 0 : -1;
}

/*
 * Read a 16-bit measurement with CRC validation.
 * Returns 0 on success and stores the raw value in *raw.
 */
static int htu21d_read_measurement(int fd, uint16_t *raw)
{
    uint8_t buf[3];

    if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0)
        return -1;

    if (htu21d_crc8(buf, 2, buf[2]) != 0) {
        syslog(LOG_ERR, "CRC mismatch on measurement data");
        return -1;
    }

    *raw = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/*
 * Trigger a measurement and read the raw value.
 * Returns 0 on success and stores the raw value in *raw.
 */
static int htu21d_read_raw(int fd, uint16_t *raw)
{
    uint8_t cmd;

    if (g_i2c_fd < 0) {
        syslog(LOG_ERR, "I2C file descriptor invalid");
        return -1;
    }

    /*
     * HTU21D supports two measurement modes:
     *   0xE3  - Temperature, hold master
     *   0xE5  - Humidity, hold master
     * We use hold master mode so the sensor holds the bus while
     * conversion completes.
     */
    cmd = CMD_HUMID_HOLD;
    if (i2c_write_cmd(fd, cmd) != 0)
        return -1;

    usleep(MEASURE_DELAY_US);

    return htu21d_read_measurement(fd, raw);
}

/*
 * Convert raw humidity to relative humidity (%RH).
 * Returns 0 on success and stores the humidity in *humidity.
 */
static int htu21d_convert_humidity(uint16_t raw, float *humidity)
{
    if (raw == 0x0000 || raw == 0xFFFF) {
        syslog(LOG_ERR, "Humidity raw value out of range: 0x%04X", raw);
        return -1;
    }

    float h = -6.0f + (125.0f * (float)raw / 65536.0f);
    if (h < 0.0f)   h = 0.0f;
    if (h > 100.0f) h = 100.0f;

    *humidity = h;
    return 0;
}

/* ------------------------------------------------------------------ */
/* HTTP POST                                                           */
/* ------------------------------------------------------------------ */
static int http_post(const char *endpoint, const char *json_data)
{
    struct sockaddr_in addr;
    char request[512];
    size_t req_len;
    ssize_t sent;

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(80);

    if (inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid IP address for %s: %s", endpoint, strerror(errno));
        return -1;
    }

    g_sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (g_sock_fd < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }

    if (connect(g_sock_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to %s: %s", endpoint, strerror(errno));
        close(g_sock_fd);
        g_sock_fd = -1;
        return -1;
    }

    req_len = snprintf(request, sizeof(request),
                       "POST %s HTTP/1.1\r\n"
                       "Host: api.example.com\r\n"
                       "Content-Type: application/json\r\n"
                       "Content-Length: %zu\r\n"
                       "Connection: close\r\n"
                       "\r\n"
                       "%s",
                       endpoint, strlen(json_data), json_data);

    if (req_len >= sizeof(request)) {
        syslog(LOG_ERR, "HTTP request too long for buffer");
        close(g_sock_fd);
        g_sock_fd = -1;
        return -1;
    }

    sent = send(g_sock_fd, request, req_len, 0);
    if (sent < 0) {
        syslog(LOG_ERR, "Failed to send HTTP request: %s", strerror(errno));
        close(g_sock_fd);
        g_sock_fd = -1;
        return -1;
    }

    if (sent != (ssize_t)req_len) {
        syslog(LOG_ERR, "Partial HTTP request sent: %zd of %zu bytes", sent, req_len);
        close(g_sock_fd);
        g_sock_fd = -1;
        return -1;
    }

    /* Read and discard response headers (we only care about status code) */
    char buf[256];
    ssize_t n;
    while ((n = recv(g_sock_fd, buf, sizeof(buf), 0)) > 0) {
        /* discard */
    }
    if (n < 0 && errno != EINTR) {
        syslog(LOG_ERR, "Failed to read HTTP response headers: %s", strerror(errno));
        close(g_sock_fd);
        g_sock_fd = -1;
        return -1;
    }

    close(g_sock_fd);
    g_sock_fd = -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
