#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_REG 0xE0
#define BMP280_RESET_CMD 0xB6
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_CALIB_START_REG 0x88
#define BMP280_CALIB_LEN 24
#define BMP280_TEMP_CALIB_LEN 6
#define BMP280_PRESS_CALIB_LEN 18
#define BMP280_OVERSAMPLING_TEMP 2
#define BMP280_OVERSAMPLING_PRESS 2
#define BMP280_MODE_NORMAL 3
#define BMP280_T_SB_500MS 0x05
#define BMP280_FILTER_COEFF_4 0x02
#define BMP280_SPI3W_EN 0x00
#define PRESSURE_THRESHOLD_HIGH 1020.0
#define PRESSURE_THRESHOLD_LOW 980.0
#define LOG_FILE "pressure_log.txt"
#define I2C_BUS 1
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read block failed (reg=0x%02X, rc=%d, expected=%u)\n", reg, rc, len);
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write byte failed (reg=0x%02X, rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_calibration_data(int handle, bmp280_calib_data *cal) {
    uint8_t buf[BMP280_CALIB_LEN];
    if (i2c_read_block(handle, BMP280_CALIB_START_REG, buf, BMP280_CALIB_LEN) != 0) {
        return -1;
    }
    cal->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    cal->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    cal->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    cal->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    cal->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)calib.dig_T1 << 1))) * ((int32_t)calib.dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)calib.dig_T1)) * ((adc_T >> 4) - ((int32_t)calib.dig_T1))) >> 12) * ((int32_t)calib.dig_T3)) >> 14;
    t_fine = var1 + var2;
    return (t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)calib.dig_P6;
    var2 = var2 + ((var1 * (int64_t)calib.dig_P5) << 17);
    var2 = var2 + (((int64_t)calib.dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)calib.dig_P3) >> 8) + ((var1 * (int64_t)calib.dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)calib.dig_P1) >> 33;
    if (var1 == 0) return 0;
    p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)calib.dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)calib.dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)calib.dig_P7) << 4);
    return (uint32_t)((p >> 8) * 25);
}

static int read_bmp280_data(int handle, float *temperature, float *pressure) {
    uint8_t data[6];
    if (i2c_read_block(handle, BMP280_PRESS_MSB_REG, data, 6) != 0) {
        return -1;
    }
    int32_t adc_P = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t adc_T = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t temp_comp = compensate_temperature(adc_T);
    uint32_t press_comp = compensate_pressure(adc_P);
    *temperature = temp_comp / 100.0f;
    *pressure = press_comp / 100.0f;
    return 0;
}

static int log_pressure_data(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f hPa\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fclose(fp);
    return 0;
}

static int initialize_bmp280(int handle) {
    uint8_t chip_id;
    if (i2c_read_block(handle, BMP280_CHIP_ID_REG, &chip_id, 1) != 0) {
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_byte(handle, BMP280_RESET_REG, BMP280_RESET_CMD) != 0) {
        return -1;
    }
    gpioDelay(2000);
    if (read_calibration_data(handle, &calib) != 0) {
        return -1;
    }
    uint8_t config = (BMP280_T_SB_500MS << 5) | (BMP280_FILTER_COEFF_4 << 2) | BMP280_SPI3W_EN;
    if (i2c_write_byte(handle, BMP280_CONFIG_REG, config) != 0) {
        return -1;
    }
    uint8_t ctrl_meas = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | BMP280_MODE_NORMAL;
    if (i2c_write_byte(handle, BMP280_CTRL_MEAS_REG, ctrl_meas) != 0) {
        return -1;
    }
    return 0;
}

static int open_i2c_connection(void) {
    int handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", handle);
        return -1;
    }
    return handle;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    i2c_handle = open_i2c_connection();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }
    if (initialize_bmp280(i2c_handle) != 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        cleanup();
        return 1;
    }
    printf("BMP280 initialized successfully. Monitoring pressure...\n");
    while (running) {
        float temperature, pressure;
        if (read_bmp280_data(i2c_handle, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);
            if (pressure > PRESSURE_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
                if (log_pressure_data(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading BMP280 data. Attempting to re-initialize...\n");
            int retries = 0;
            while (retries < MAX_RETRIES && running) {
                i2cClose(i2c_handle);
                i2c_handle = -1;
                gpioDelay(100000);
                i2c_handle = open_i2c_connection();
                if (i2c_handle < 0) {
                    fprintf(stderr, "Failed to re-open I2C connection (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
                    retries++;
                    continue;
                }
                if (initialize_bmp280(i2c_handle) == 0) {
                    fprintf(stderr, "BMP280 re-initialized successfully after %d retries.\n", retries + 1);
                    break;
                }
                fprintf(stderr, "BMP280 re-initialization failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
            }
            if (retries == MAX_RETRIES) {
                fprintf(stderr, "Failed to re-initialize BMP280 after %d retries. Exiting.\n", MAX_RETRIES);
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

