/*
 * Raspberry Pi 4B – TMP117 + AHT20 + PIR motion logger
 *
 * Build:  gcc -O2 -Wall -Wextra -o logger logger.c -lgpiod -lrt
 * Run:    ./logger
 *
 * TMP117  I2C  /dev/i2c-1  address 0x48
 * AHT20   I2C  /dev/i2c-1  address 0x38
 * PIR     GPIO gpiochip4 line 17 (BCM 17, input)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define AHT20_ADDR     0x38

#define TMP117_REG_TEMP 0x00
#define TMP117_REG_CONF 0x01
#define TMP117_REG_MANU 0x7E
#define TMP117_REG_ID   0x7F

#define AHT20_CMD_MEASURE 0xAC
#define AHT20_CMD_RESET   0xBA

#define PIR_CHIP_NAME "gpiochip4"
#define PIR_LINE_OFFSET 17

#define LOG_FILE_PREFIX "sensor_data"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "[ERROR] open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C write reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C read reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C write reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C read reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write reg 0x%02X val 0x%02X: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* TMP117                                                             */
/* ------------------------------------------------------------------ */

static int tmp117_init(int fd)
{
    uint16_t id;
    if (i2c_read_reg16(fd, TMP117_REG_ID, &id) < 0)
        return -1;
    if ((id & 0x0FFF) != 0x0483) {
        fprintf(stderr, "[WARN] TMP117 ID mismatch: got 0x%04X, expected 0x0483\n",
                id);
        return -1;
    }
    /*
     * Config register bits:
     *   [15:12] 0x0  – reserved
     *   [11:8]  0x0  – reserved
     *   [7:6]   0x0  – reserved
     *   [5:4]   0x0  – reserved
     *   [3]     0x0  – reserved
     *   [2]     0x0  – reserved
     *   [1]     0x0  – reserved
     *   [0]     0x0  – reserved
     */
    if (i2c_write_reg8(fd, TMP117_REG_CONF, 0x00) < 0)
        return -1;
    return 0;
}

static int tmp117_read_temp(int fd, float *temp_c)
{
    uint16_t raw;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(fd, TMP117_REG_TEMP, &raw) == 0) {
            int16_t signed_raw = (int16_t)raw;
            *temp_c = (float)signed_raw / 256.0f;
            return 0;
        }
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* AHT20                                                               */
/* ------------------------------------------------------------------ */

static int aht20_init(int fd)
{
    if (i2c_write_reg8(fd, AHT20_CMD_RESET, 0xBA) < 0)
        return -1;
    usleep(20000);  /* 20 ms reset settling */
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity)
{
    uint8_t cmd = AHT20_CMD_MEASURE;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "[ERROR] AHT20 trigger: %s\n", strerror(errno));
        return -1;
    }
    usleep(20000);  /* 20 ms conversion */

    uint8_t buf[7];
    if (read(fd, buf, 7) != 7) {
        fprintf(stderr, "[ERROR] AHT20 read: %s\n", strerror(errno));
        return -1;
    }
    if (buf[0] != 0x68 || buf[1] != 0x32) {
        fprintf(stderr, "[ERROR] AHT20 checksum failed\n");
        return -1;
    }
    uint32_t hum_raw = ((uint32_t)buf[2] << 12) |
                       ((uint32_t)buf[3] << 4)  |
                       ((uint32_t)buf[4] >> 4);
    *humidity = (float)hum_raw / 1048576.0f * 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* PIR motion sensor (library API)                                    */
/* ------------------------------------------------------------------ */

/*
 * The PIR sensor is wired to GPIO17 (BCM 17).  The library exposes
 * a read() call that returns 1 when motion is detected and 0
 * otherwise.  We use the gpiod line API for robustness and
 * portability.
 */

static int pir_init(struct gpiod_line *line)
{
    /*
     * Request the line as input.  The PIR module drives the line
     * high when motion is detected; the internal pull-down keeps
     * it low when idle.
     */
    if (gpiod_line_request_input(line, "pir-sensor") < 0) {
        fprintf(stderr, "[ERROR] gpiod_line_request_input: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

static int pir_read(struct gpiod_line *line)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "[ERROR] gpiod_line_get_value: %s\n",
                strerror(errno));
        return -1;
    }
    return val;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int ensure_log_file(const char *prefix, const char *date_str)
{
    char filename[256];
    snprintf(filename, sizeof(filename), "%s_%s.csv", prefix, date_str);

    FILE *fp = fopen(filename, "r");
    if (fp) {
        fclose(fp);
        return 0;  /* file already exists */
    }
    if (errno != ENOENT) {
        fprintf(stderr, "[ERROR] fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "[ERROR] fopen(%s, w): %s\n", filename, strerror(errno));
        return -1;
    }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    fclose(fp);
    return 0;
}

static int log_data(const char *prefix, const char *date_str,
                    float temp_c, float humidity, int motion)
{
    char filename[256];
    snprintf(filename, sizeof(filename), "%s_%s.csv", prefix, date_str);

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] fopen(%s, a): %s\n", filename, strerror(errno));
        return -1;
    }

    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp_c, humidity, motion);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
