    /* Open TMP117 */
    int tmp117_fd = i2c_open(I2C_BUS, TMP117_ADDR);
    if (tmp117_fd < 0) {
        fprintf(stderr, "[WARN] TMP117 not present; continuing without.\n");
    } else {
