            fprintf(stderr, "[WARN] TMP117 init failed; continuing without.\n");
            close(tmp117_fd);
            tmp117_fd = -1;
        }
    }

    /* Open AHT20 */
    int aht20_fd = i2c_open(I2C_BUS, AHT20_ADDR);
    if (aht20_fd < 0) {
        fprintf(stderr, "[WARN] AHT20 not present; continuing without.\n");
    } else {
        if (aht20_init(aht20_fd) < 0) {
            fprintf(stderr, "[WARN] AHT20 init failed; continuing without.\n");
            close(aht20_fd);
            aht20_fd = -1;
        }
    }

