                PIR_CHIP_NAME, strerror(errno));
        fprintf(stderr, "[WARN] PIR motion detection disabled.\n");
    } else {
        struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_LINE_OFFSET);
        if (!pir_line) {
            fprintf(stderr, "[WARN] gpiod_chip_get_line(%d): %s\n",
                    PIR_LINE_OFFSET, strerror(errno));
            fprintf(stderr, "[WARN] PIR motion detection disabled.\n");
            gpiod_chip_close(chip);
            chip = NULL;
