#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define MOTOR_RUN_TIME_SEC 5
#define POLL_INTERVAL_SEC  2

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioSetMode failed for pin %u", pin);
        log_event(buf);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "gpioWrite failed for pin %u", pin);
        log_event(buf);
        return -1;
    }
    return 0;
}

static int motor_stop(void)
{
    if (safe_write(MOTOR_IN1_PIN, 0) != 0) return -1;
    if (safe_write(MOTOR_IN2_PIN, 0) != 0) return -1;
    if (safe_write(MOTOR_ENA_PIN, 0) != 0) return -1;
    return 0;
}

static int motor_forward(int duration_sec)
{
    if (safe_write(MOTOR_IN1_PIN, 1) != 0) return -1;
    if (safe_write(MOTOR_IN2_PIN, 0) != 0) return -1;
    if (safe_write(MOTOR_ENA_PIN, 1) != 0) return -1;

    for (int i = 0; i < duration_sec && g_running; i++)
        sleep(1);

    return motor_stop();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(RAIN_SENSOR_PIN, PI_INPUT) != 0) goto fail_init;
    if (safe_set_mode(MOTOR_ENA_PIN, PI_OUTPUT) != 0) goto fail_init;
    if (safe_set_mode(MOTOR_IN1_PIN, PI_OUTPUT) != 0) goto fail_init;
    if (safe_set_mode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) goto fail_init;

    log_event("Rain sensor monitoring started");

    while (g_running) {
        int rain_detected = (gpioRead(RAIN_SENSOR_PIN) == 0);

        if (rain_detected) {
            log_event("Rain detected! Closing window.");
            if (motor_forward(MOTOR_RUN_TIME_SEC) != 0) {
                log_event("Motor control failed during window closure.");
            } else {
                log_event("Window closed successfully.");
            }
        } else {
            log_event("No rain detected.");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    log_event("Shutting down gracefully.");
    motor_stop();
    gpioTerminate();
    return EXIT_SUCCESS;

fail_init:
    gpioTerminate();
    return EXIT_FAILURE;
}

