#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27

#define SAMPLE_INTERVAL_US 500000  /* 500 ms */
#define PWM_RANGE          255

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read the CPU load from /proc/stat.
 * Returns 0 on success and stores the load percentage in *load_pct.
 * Returns -1 on error.
 */
static int read_cpu_load(float *load_pct)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strncmp(line, "cpu ", 4) != 0) {
        fprintf(stderr, "Unexpected format in /proc/stat\n");
        return -1;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal;
    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal) != 8) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        return -1;
    }

    static unsigned long long prev_user = 0, prev_nice = 0, prev_system = 0, prev_idle = 0;
    static unsigned long long prev_iowait = 0, prev_irq = 0, prev_softirq = 0, prev_steal = 0;
    static int first_sample = 1;

    unsigned long long total_prev = prev_user + prev_nice + prev_system + prev_idle +
                                   prev_iowait + prev_irq + prev_softirq + prev_steal;
    unsigned long long total_cur  = user + nice + system + idle +
                                   iowait + irq + softirq + steal;

    unsigned long long totald = total_cur - total_prev;
    unsigned long long idled  = idle - prev_idle;

    if (totald == 0) {
        *load_pct = 0.0f;
    } else {
        *load_pct = (float)(totald - idled) / (float)totald * 100.0f;
    }

    if (first_sample) {
        first_sample = 0;
    } else {
        prev_user    = user;
        prev_nice    = nice;
        prev_system  = system;
        prev_idle    = idle;
        prev_iowait  = iowait;
        prev_irq     = irq;
        prev_softirq = softirq;
        prev_steal   = steal;
    }

    return 0;
}

/*
 * Map a load percentage (0-100) to a color gradient:
 *   0%   -> green (0,255,0)
 *   50%  -> yellow (255,255,0)
 *   100% -> red (255,0,0)
 * Returns 0 on success, -1 on pigpio error.
 */
static int set_led_color(float load_pct)
{
    if (load_pct < 0.0f)   load_pct = 0.0f;
    if (load_pct > 100.0f) load_pct = 100.0f;

    int red, green, blue;

    if (load_pct < 50.0f) {
        green = (int)(255.0f * (load_pct / 50.0f));
        red   = 0;
        blue  = 0;
    } else {
        red   = (int)(255.0f * ((load_pct - 50.0f) / 50.0f));
        green = 255;
        blue  = 0;
    }

    /* Common-anode LED: invert the PWM values */
    int r_inv = PWM_RANGE - red;
    int g_inv = PWM_RANGE - green;
    int b_inv = PWM_RANGE - blue;

    if (gpioPWM(RED_PIN,   r_inv) < 0) {
        fprintf(stderr, "gpioPWM failed for RED_PIN: %s\n", pigpio_error(r_inv));
        return -1;
    }
    if (gpioPWM(GREEN_PIN, g_inv) < 0) {
        fprintf(stderr, "gpioPWM failed for GREEN_PIN: %s\n", pigpio_error(g_inv));
        return -1;
    }
    if (gpioPWM(BLUE_PIN,  b_inv) < 0) {
        fprintf(stderr, "gpioPWM failed for BLUE_PIN: %s\n", pigpio_error(b_inv));
        return -1;
    }

    return 0;
}

/*
 * Turn the LED off (all channels full off for a common-anode LED).
 */
static void led_off(void)
{
    gpioPWM(RED_PIN,   PWM_RANGE);
    gpioPWM(GREEN_PIN, PWM_RANGE);
    gpioPWM(BLUE_PIN,  PWM_RANGE);
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    /* Configure GPIO pins as outputs and set PWM range */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for RED_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GREEN_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for BLUE_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed for RED_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GREEN_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed for BLUE_PIN\n");
        gpioTerminate();
        return 1;
    }

    /* Ensure LED is off at startup */
    led_off();

    printf("CPU load monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float load_pct;

        if (read_cpu_load(&load_pct) == 0) {
            if (set_led_color(load_pct) != 0) {
                fprintf(stderr, "Error setting LED color\n");
            }
            printf("CPU Load: %.2f%%\n", load_pct);
        } else {
            fprintf(stderr, "Error reading CPU load\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(10000); /* 10 ms */
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    led_off();
    gpioTerminate();
    printf("CPU load monitor stopped.\n");

    return 0;
}

