/*
 * BMP280 temperature/pressure logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   BMP280 SDA  -> GPIO2  (pin 3)
 *   BMP280 SCL  -> GPIO3  (pin 5)
 *   BMP280 VDD  -> 3.3 V
 *   BMP280 GND  -> GND
 *
 * I2C bus: /dev/i2c-1  (BCM pins 2/3)
 * BMP280 I2C address: 0x76 (SDO tied to GND)
 *
 * UDP destination: 192.168.1.100:5000
 *
 * Build: gcc -O2 -Wall -Wextra -o bmp280_logger bmp280_logger.c -lpigpio -lrt
 * Run:   sudo ./bmp280_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

/* ---- BMP280 constants (datasheet rev 1.26) ---- */
#define BMP280_I2C_ADDR        0x76
#define BMP280_REG_ID          0xD0
#define BMP280_REG_RESET       0xE0
#define BMP280_REG_CTRL_MEAS   0xF4
#define BMP280_REG_CONFIG      0xF5
#define BMP280_REG_PRESS_MSB   0xF7
#define BMP280_REG_TEMP_MSB    0xFA
#define BMP280_REG_CALIB       0x88
#define BMP280_CHIP_ID         0x58

#define BMP280_RESET_CMD       0xB6
#define BMP280_OSRS_T_1X       0x20
#define BMP280_OSRS_P_1X       0x04
#define BMP280_MODE_NORMAL     0x03
#define BMP280_T_WAIT_US       5000   /* 4.5 ms max for 1 x oversampling */
#define BMP280_P_WAIT_US       5000   /* 4.5 ms max for 1 x oversampling */

#define UDP_SERVER_IP   "192.168.1.100"
#define UDP_SERVER_PORT 5000
#define SAMPLE_PERIOD_S 5

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static int  g_udp_socket = -1;
static volatile sig_atomic_t g_terminate = 0;

/* ---- Calibration coefficients ---- */
static uint16_t dig_T1;
static int16_t  dig_T2, dig_T3;
static uint16_t dig_P1;
static int16_t  dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
static int32_t  t_fine;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    if (i2cWriteByte(handle, reg) < 0)
        return -1;
    int n = i2cReadDevice(handle, (char *)buf, len);
    return (n == (int)len) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    return (i2cWriteDevice(handle, buf, 2) == 0) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
static int read_calibration(int handle)
{
    uint8_t cal[24];
    if (i2c_read_block(handle, BMP280_REG_CALIB, cal, sizeof(cal)) != 0) {
        fprintf(stderr, "Error: failed to read calibration data: %s\n",
                strerror(errno));
        return -1;
    }

    dig_T1 = (uint16_t)((cal[1]  << 8) | cal[0]);
    dig_T2 = (int16_t) ((cal[3]  << 8) | cal[2]);
    dig_T3 = (int16_t) ((cal[5]  << 8) | cal[4]);
    dig_P1 = (uint16_t)((cal[7]  << 8) | cal[6]);
    dig_P2 = (int16_t) ((cal[9]  << 8) | cal[8]);
    dig_P3 = (int16_t) ((cal[11] << 8) | cal[10]);
    dig_P4 = (int16_t) ((cal[13] << 8) | cal[12]);
    dig_P5 = (int16_t) ((cal[15] << 8) | cal[14]);
    dig_P6 = (int16_t) ((cal[17] << 8) | cal[16]);
    dig_P7 = (int16_t) ((cal[19] << 8) | cal[18]);
    dig_P8 = (int16_t) ((cal[21] << 8) | cal[20]);
    dig_P9 = (int16_t) ((cal[23] << 8) | cal[22]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_bmp280(int handle)
{
    uint8_t id;
    if (i2c_read_block(handle, BMP280_REG_ID, &id, 1) != 0) {
        fprintf(stderr, "Error: cannot read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: chip ID 0x%02X != expected 0x%02X (sensor absent?)\n",
                id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_byte(handle, BMP280_REG_RESET, BMP280_RESET_CMD) != 0) {
        fprintf(stderr, "Error: reset write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2000);  /* 2 ms reset settling */

    if (read_calibration(handle) != 0)
        return -1;

    /* config: t_sb=0.5ms (0x00), filter=off (0x00), spi3w_en=0 */
    if (i2c_write_byte(handle, BMP280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: config write failed: %s\n", strerror(errno));
        return -1;
    }

    /* ctrl_meas: osrs_t=1x (0x20), osrs_p=1x (0x04), mode=normal (0x03) */
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS,
                       BMP280_OSRS_T_1X | BMP280_OSRS_P_1X | BMP280_MODE_NORMAL) != 0) {
        fprintf(stderr, "Error: ctrl_meas write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_raw_temperature(int handle, int32_t *raw_t)
{
    uint8_t buf[3];
    if (i2c_read_block(handle, BMP280_REG_TEMP_MSB, buf, 3) != 0)
        return -1;
    *raw_t = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_raw_pressure(int handle, int32_t *raw_p)
{
    uint8_t buf[3];
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, buf, 3) != 0)
        return -1;
    *raw_p = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    return 0;
}

/* ------------------------------------------------------------------ */
static double compensate_temperature(int32_t raw_t)
{
    double v1 = ((double)raw_t / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double v2 = ((double)raw_t / 131072.0 - (double)dig_T1 / 8192.0) *
                ((double)raw_t / 131072.0 - (double)dig_T1 / 8192.0) *
                (double)dig_T3;
    t_fine = (int32_t)(v1 + v2);
    return (v1 + v2) / 5120.0;
}

/* ------------------------------------------------------------------ */
static double compensate_pressure(int32_t raw_p)
{
    double v1 = ((double)t_fine / 2.0) - 64000.0;
    double v2 = v1 * v1 * (double)dig_P6 / 32768.0;
    v2 = v2 + v1 * (double)dig_P5 * 2.0;
    v2 = (v2 / 4.0) + ((double)dig_P4 * 65536.0);
    v1 = ((double)dig_P3 * v1 * v1 / 524288.0 + (double)dig_P2 * v1) / 524288.0;
    v1 = (1.0 + v1 / 32768.0) * (double)dig_P1;
    if (v1 == 0.0)
        return 0.0;
    double p = 1048576.0 - (double)raw_p;
    p = (p - (v2 / 4096.0)) * 6250.0 / v1;
    v1 = (double)dig_P9 * p * p / 2147483648.0;
    v2 = p * (double)dig_P8 / 32768.0;
    p = p + (v1 + v2 + (double)dig_P7) / 16.0;
    return p;
}

/* ------------------------------------------------------------------ */
static int format_json(double temp_c, double press_pa, char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL)
        return -1;
