    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    return snprintf(buf, len,
                     "{\"timestamp\":\"%s\",\"temperature\":%.2f,\"pressure\":%.2f}",
                     ts, temp_c, press_pa);
}

/* ------------------------------------------------------------------ */
static int send_udp(const char *json)
{
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
