    addr.sin_port   = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Error: invalid UDP address: %s\n", UDP_SERVER_IP);
        return -1;
    }

    size_t len = strlen(json);
    ssize_t sent = sendto(g_udp_socket, json, len, 0,
                          (struct sockaddr *)&addr, sizeof(addr));
    if (sent < 0 || (size_t)sent != len) {
        fprintf(stderr, "Error: UDP send failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_udp_socket >= 0) {
        close(g_udp_socket);
        g_udp_socket = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
