        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_bmp280(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_udp_socket < 0) {
        fprintf(stderr, "Error: socket creation failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP280 logger started. Sending to %s:%d every %d s.\n",
