/*
 * Raspberry Pi 4 Model B — MAX31855 thermocouple fan controller
 *
 * Hardware:
 *   MAX31855  SPI0  CE0  (GPIO8)  — 4-wire thermocouple interface
 *   Fan PWM    GPIO18 (BCM) — hardware PWM at 1 kHz, duty 0-255
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o fan_ctrl fan_ctrl.c -lrt -lpigpio
 *   sudo ./fan_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define FAN_GPIO          18          /* BCM pin for fan PWM */
#define SPI_CHANNEL       0           /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED         500000      /* 500 kHz — well within MAX31855 5 MHz limit */
#define SPI_FLAGS         0           /* Mode 0, active-low CE */
#define PWM_FREQUENCY     1000        /* 1 kHz — typical for 4-wire PC fans */
#define PWM_RANGE         255         /* 8-bit duty resolution */
#define BUFFER_SIZE       20
#define SAMPLE_PERIOD_US  1000000     /* 1 second */

/* ------------------------------- Data types ------------------------------- */
typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} FanData;

/* --------------------------- Global state -------------------------------- */
static FanData fan_buffer[BUFFER_SIZE];
static int     buffer_index = 0;
static int     buffer_count = 0;

static volatile sig_atomic_t program_running = 1;

/* --------------------------- Function prototypes -------------------------- */
static int  initialize_spi(void);
static int  read_max31855(float *temperature);
static int  calculate_pwm_duty(float temperature);
static void set_fan_speed(int duty_cycle);
static void log_data(float temperature, int duty_cycle);
static void print_buffer(void);
static void signal_handler(int signal);

/* ------------------------------- SPI init --------------------------------- */
static int initialize_spi(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz, flags %d): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, handle);
        gpioTerminate();
        return -1;
    }
    return handle;
}

/* --------------------------- MAX31855 read ------------------------------- */
/*
 * MAX31855 32-bit SPI frame (MSB first):
 *   D[31:18]  Thermocouple temperature, 14-bit signed, 0.25 °C / count
 *   D[17]     Reserved
 *   D[16]     Fault bit (1 = fault)
 *   D[15:4]   Internal reference / cold-junction temperature, 12-bit signed, 0.0625 °C / count
 *   D[3]      Reserved
 *   D[2]      SCV fault (short to VCC)
 *   D[1]      SCG fault (short to GND)
 *   D[0]      OC  fault (open circuit)
 *
 * Returns 0 on success, -1 on SPI transfer error, -2 on MAX31855 fault.
 */
static int read_max31855(float *temperature)
{
    char rx[4] = {0, 0, 0, 0};
    char tx[4] = {0, 0, 0, 0};

    int bytes = spiXfer(SPI_CHANNEL, tx, rx, 4);
    if (bytes != 4) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 4).\n", bytes);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "Error: MAX31855 fault detected (raw=0x%08X).\n", raw);
        if (raw & 0x00000001) fprintf(stderr, "  Fault: Open circuit.\n");
        if (raw & 0x00000002) fprintf(stderr, "  Fault: Short to GND.\n");
        if (raw & 0x00000004) fprintf(stderr, "  Fault: Short to VCC.\n");
        return -2;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

/* --------------------------- Fan curve ----------------------------------- */
static int calculate_pwm_duty(float temperature)
{
    if (temperature < 25.0f) {
        return 0;
    } else if (temperature < 40.0f) {
        return (int)((temperature - 25.0f) * 255.0f / 15.0f);
    } else if (temperature < 60.0f) {
        return (int)((temperature - 40.0f) * 150.0f / 20.0f + 128.0f);
    } else {
        return 255;
    }
}

/* --------------------------- PWM control --------------------------------- */
static void set_fan_speed(int duty_cycle)
{
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed for duty %d.\n", duty_cycle);
    }
}

/* --------------------------- Circular buffer ------------------------------ */
static void log_data(float temperature, int duty_cycle)
{
    time(&fan_buffer[buffer_index].timestamp);
    fan_buffer[buffer_index].temperature = temperature;
    fan_buffer[buffer_index].pwm_duty    = duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

