    }
    printf("---------------------------------------\n");
}

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int signal)
{
    (void)signal;
    program_running = 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
