#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define INTERRUPT_PIN 2
#define LOG_FILE "altitude_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static int logging_enabled = 0;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    int bytes = i2cReadDevice(handle, (char *)buf, len);
    return (bytes == (int)len) ? 0 : -1;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    return (i2cWriteDevice(handle, buf, 2) == 0) ? 0 : -1;
}

static int read_calibration(int handle, bmp180_cal_t *c) {
    uint8_t buf[22];
    if (i2c_read_reg(handle, BMP180_REG_CAL_AC1, buf, 22) < 0) return -1;
    c->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    c->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    c->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    c->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    c->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    c->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    c->b1 = (int16_t)((buf[12] << 8) | buf[13]);
    c->b2 = (int16_t)((buf[14] << 8) | buf[15]);
    c->mb = (int16_t)((buf[16] << 8) | buf[17]);
    c->mc = (int16_t)((buf[18] << 8) | buf[19]);
    c->md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 2) < 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) return -1;
    gpioDelay(2 + (3 << BMP180_OSS));
    uint8_t buf[3];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 3) < 0) return -1;
    *up = (((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | (int32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

static float calculate_temperature(int32_t ut, const bmp180_cal_t *c) {
    int32_t b5 = compute_b5(ut, c);
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut, const bmp180_cal_t *c) {
    int32_t b5 = compute_b5(ut, c);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return p + ((x1 + x2 + 3791) >> 4);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

static void log_data(float temp, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, pressure);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration(i2c_handle, &cal) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);
    if (gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("BMP180 logging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(i2c_handle, &ut) < 0) {
                fprintf(stderr, "Temperature read error\n");
            } else if (read_raw_pressure(i2c_handle, &up) < 0) {
                fprintf(stderr, "Pressure read error\n");
            } else {
                float temp = calculate_temperature(ut, &cal);
                float pressure = calculate_pressure(up, ut, &cal);
                log_data(temp, pressure);
            }
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, NULL, NULL);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

