    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

static float calculate_temperature(int32_t ut, const bmp180_cal_t *c) {
    int32_t b5 = compute_b5(ut, c);
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut, const bmp180_cal_t *c) {
    int32_t b5 = compute_b5(ut, c);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return p + ((x1 + x2 + 3791) >> 4);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

static void log_data(float temp, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, pressure);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration(i2c_handle, &cal) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);
    if (gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("BMP180 logging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(i2c_handle, &ut) < 0) {
                fprintf(stderr, "Temperature read error\n");
            } else if (read_raw_pressure(i2c_handle, &up) < 0) {
                fprintf(stderr, "Pressure read error\n");
            } else {
                float temp = calculate_temperature(ut, &cal);
                float pressure = calculate_pressure(up, ut, &cal);
                log_data(temp, pressure);
            }
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, NULL, NULL);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

