/*
 * BME280 I2C Logger for Raspberry Pi Zero W
 * Bus: /dev/i2c-1  Address: 0x76  Chip ID: 0x60
 * Logs: timestamp, temp_c, rh, pressure_hpa to bme280_log.csv every 5 s
 * Build: gcc -O2 -Wall -o bme280_logger bme280_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BME280_ADDR    0x76
#define BME280_CHIP_ID 0x60

#define REG_ID         0xD0
#define REG_RESET      0xE0
#define REG_CTRL_HUM   0xF2
#define REG_STATUS     0xF3
#define REG_CTRL_MEAS  0xF4
#define REG_CONFIG     0xF5
#define REG_PRESS_MSB  0xF7
#define REG_TEMP_MSB   0xFA
#define REG_HUM_MSB    0xFD

#define RESET_CMD      0xB6
#define STATUS_MEAS    0x08

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read block (reg 0x%02X, want %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int bme280_init(int fd)
{
    uint8_t id;
    if (i2c_read_reg(fd, REG_ID, &id) != 0)
        return -1;
    if (id != BME280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, REG_RESET, RESET_CMD) != 0)
        return -1;
    usleep(2000);

    uint8_t status;
    for (int i = 0; i < 20; i++) {
        if (i2c_read_reg(fd, REG_STATUS, &status) != 0)
            return -1;
        if ((status & STATUS_MEAS) == 0)
            break;
        usleep(2000);
    }
    if (status & STATUS_MEAS) {
        fprintf(stderr, "BME280 reset timeout\n");
        return -1;
    }

    if (i2c_write_reg(fd, REG_CTRL_HUM, 0x01) != 0)
        return -1;
    if (i2c_write_reg(fd, REG_CONFIG, 0xA0) != 0)
        return -1;
    if (i2c_write_reg(fd, REG_CTRL_MEAS, 0x27) != 0)
        return -1;

    return 0;
}

static int bme280_read(int fd, float *temp, float *rh, float *press)
{
    uint8_t d[8];
    if (i2c_read_block(fd, REG_PRESS_MSB, d, 8) != 0)
        return -1;

    int32_t p = (d[0] << 12) | (d[1] << 4) | (d[2] >> 4);
    int32_t t = (d[3] << 12) | (d[4] << 4) | (d[5] >> 4);
    int32_t h = (d[6] << 8)  | d[7];

    *press = p / 100.0f;
    *temp  = t / 100.0f;
    *rh    = h / 1024.0f;
    return 0;
}

static void log_data(FILE *fp, float temp, float rh, float press)
{
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    localtime_r(&now, &tmv);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, temp, rh, press);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                BME280_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (bme280_init(fd) != 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("bme280_log.csv", "a");
    if (!fp) {
        fprintf(stderr, "Cannot open bme280_log.csv: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0)
        fprintf(fp, "timestamp,temperature_c,humidity_rh,pressure_hpa\n");

    while (g_running) {
        float temp, rh, press;
        if (bme280_read(fd, &temp, &rh, &press) == 0) {
            log_data(fp, temp, rh, press);
        } else {
            fprintf(stderr, "Read error; continuing\n");
        }
        sleep(5);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

