/*
 * BMP180 Pressure Monitor with Rolling Average Alert
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: BMP180 at I2C address 0x77
 * Alert:  GPIO24 (active-HIGH)
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp180_monitor bmp180_monitor.c -lpigpio -lrt
 * Run:    sudo ./bmp180_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define BMP180_ADDR         0x77
#define ALERT_GPIO          24
#define BUFFER_SIZE         60          /* 60 samples × 50 ms = 3 s window */
#define SAMPLE_PERIOD_US    50000       /* 50 ms in microseconds            */
#define DEVIATION_THRESHOLD 5.0f        /* hPa                             */
#define LOG_FILE            "bmp180_log.txt"

/* BMP180 registers */
#define BMP180_REG_CONTROL  0xF4
#define BMP180_REG_MSB      0xF6
#define BMP180_REG_LSB      0xF7
#define BMP180_REG_XLSB     0xF8
#define BMP180_REG_CAL_AC1  0xAA
#define BMP180_REG_CAL_AC2  0xAC
#define BMP180_REG_CAL_AC3  0xAE
#define BMP180_REG_CAL_AC4  0xB0
#define BMP180_REG_CAL_AC5  0xB2
#define BMP180_REG_CAL_AC6  0xB4
#define BMP180_REG_CAL_B1   0xB6
#define BMP180_REG_CAL_B2   0xB8
#define BMP180_REG_CAL_MB   0xBA
#define BMP180_REG_CAL_MC   0xBC
#define BMP180_REG_CAL_MD   0xBE

/* Oversampling setting (0–3) */
#define OSS 3

/* ------------------------------- Data Types ------------------------------- */
typedef struct {
    time_t timestamp;
    float  pressure;
} PressureReading;

typedef struct {
    PressureReading readings[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

/* ----------------------------- Global State ------------------------------ */
static int           i2c_handle = -1;
static CircularBuffer pressure_buffer;
static volatile sig_atomic_t terminate = 0;

/* Calibration coefficients (signed 16-bit, unsigned 16-bit) */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

/* --------------------------- Function Prototypes -------------------------- */
static int  read_calibration_data(void);
static int  read_raw_temperature(int32_t *ut);
static int  read_raw_pressure(int32_t *up);
static int  calculate_pressure(int32_t ut, int32_t up, float *pressure);
static void add_reading(float pressure);
static float calculate_average_pressure(void);
static void check_pressure_deviation(float current_pressure);
static void signal_handler(int sig);
static void timer_callback(void);
static void cleanup(void);

/* ------------------------------- Calibration ------------------------------ */
static int read_calibration_data(void)
{
    char buf[22];

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "[ERROR] Failed to read BMP180 calibration data\n");
        return -1;
    }

    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);

    return 0;
}

/* --------------------------- Raw Temperature Read ------------------------- */
static int read_raw_temperature(int32_t *ut)
{
    char cmd = BMP180_REG_CONTROL;
    char buf[2];

    /* Write control register: 0x2E → temperature measurement */
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] Failed to write temperature command\n");
        return -1;
    }

    /* Wait for conversion (~4.5 ms at OSS=3) */
    gpioDelay(5000);

    /* Read 2 bytes of temperature data */
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] Failed to read temperature data\n");
        return -1;
    }

    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* --------------------------- Raw Pressure Read ----------------------------- */
static int read_raw_pressure(int32_t *up)
{
    char cmd = BMP180_REG_CONTROL;
    char buf[3];

    /* Write control register: 0x34 + (OSS << 6) → pressure measurement */
    cmd = 0x34 + (OSS << 6);
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] Failed to write pressure command\n");
        return -1;
    }

    /* Wait for conversion (~26 ms at OSS=3) */
    gpioDelay(30000);

    /* Read 3 bytes of pressure data */
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] Failed to read pressure data\n");
        return -1;
    }

    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - OSS);
    return 0;
}

/* --------------------------- Pressure Calculation -------------------------- */
static int calculate_pressure(int32_t ut, int32_t up, float *pressure)
{
    int32_t x1, x2, x3, b3, b5, b6, p;
    uint32_t b4, b7;

    /* Temperature compensation */
    x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    b5 = x1 + x2;

    /* Pressure compensation */
    b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)up - b3) * (50000 >> OSS);

    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    *pressure = (float)p / 100.0f; /* Pa → hPa */
    return 0;
}

/* --------------------------- Circular Buffer ------------------------------ */
static void add_reading(float pressure)
{
    pressure_buffer.readings[pressure_buffer.head].timestamp = time(NULL);
    pressure_buffer.readings[pressure_buffer.head].pressure  = pressure;
    pressure_buffer.head = (pressure_buffer.head + 1) % BUFFER_SIZE;
    if (pressure_buffer.count < BUFFER_SIZE) {
        pressure_buffer.count++;
    }
}

static float calculate_average_pressure(void)
{
    if (pressure_buffer.count == 0) {
        return 0.0f;
    }

    float sum = 0.0f;
    for (int i = 0; i < pressure_buffer.count; i++) {
        sum += pressure_buffer.readings[i].pressure;
    }
    return sum / (float)pressure_buffer.count;
}

/* --------------------------- Pressure Deviation --------------------------- */
static void check_pressure_deviation(float current_pressure)
{
    float average = calculate_average_pressure();
    float deviation = current_pressure - average;

    if (deviation < 0.0f) {
        deviation = -deviation;
    }

    if (deviation > DEVIATION_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1);
        fprintf(stderr, "[ALERT] Pressure deviation: %.2f hPa (avg=%.2f hPa)\n",
                deviation, average);
    } else {
        gpioWrite(ALERT_GPIO, 0);
    }
}

/* ------------------------------- Signal Handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------- Timer Callback --------------------------- */
static void timer_callback(void)
{
    int32_t ut, up;
    float pressure;

    if (read_raw_temperature(&ut) != 0) {
        fprintf(stderr, "[ERROR] Temperature read failed; skipping sample\n");
        return;
    }

    if (read_raw_pressure(&up) != 0) {
        fprintf(stderr, "[ERROR] Pressure read failed; skipping sample\n");
        return;
    }

    if (calculate_pressure(ut, up, &pressure) != 0) {
        fprintf(stderr, "[ERROR] Pressure calculation failed\n");
        return;
    }

    add_reading(pressure);
    check_pressure_deviation(pressure);
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] Failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, BMP180_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read calibration data */
    if (read_calibration_data() != 0) {
        fprintf(stderr, "[FATAL] BMP180 not detected or calibration read failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure alert GPIO */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO %d as output\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    /* Initialize circular buffer */
    memset(&pressure_buffer, 0, sizeof(pressure_buffer));

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] Failed to register SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] Failed to register SIGTERM handler\n");
    }

    /* Start 50 ms timer */
    if (gpioSetTimerFunc(0, SAMPLE_PERIOD_US / 1000, timer_callback) != 0) {
        fprintf(stderr, "[FATAL] Failed to set up 50 ms timer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 pressure monitor started. Sampling every 50 ms. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        gpioDelay(100000); /* 100 ms sleep to reduce CPU usage */
    }

    printf("\nShutting down...\n");
    gpioSetTimerFunc(0, 0, NULL); /* Disable timer */
    cleanup();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

