#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_PIN 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define LOG_FILE "fan_log.txt"
#define LOG_INTERVAL 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(float *temp) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    int raw;
    if (fscanf(fp, "%d", &raw) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    *temp = (float)raw / 1000.0f;
    return 0;
}

static int map_temp_to_duty(float temp) {
    if (temp < TEMP_MIN) temp = TEMP_MIN;
    if (temp > TEMP_MAX) temp = TEMP_MAX;

    float range = TEMP_MAX - TEMP_MIN;
    float duty = (temp - TEMP_MIN) / range * PWM_RANGE;
    return (int)duty;
}

static int set_fan_speed(int duty) {
    if (gpioPWM(PWM_PIN, duty) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(float temp, int duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    if (fprintf(log_file, "%s, Temperature: %.2f C, Duty Cycle: %d\n", timestamp, temp, duty) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Warning: Could not set exact PWM frequency\n");
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: Could not set exact PWM range\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp;
        if (read_cpu_temp(&temp) != 0) {
            fprintf(stderr, "Failed to read temperature, retrying in %d seconds...\n", LOG_INTERVAL);
            sleep(LOG_INTERVAL);
            continue;
        }

        int duty = map_temp_to_duty(temp);
        if (set_fan_speed(duty) != 0) {
            fprintf(stderr, "Failed to set fan speed\n");
        }

        if (log_data(temp, duty) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Temperature: %.2f C, Duty Cycle: %d\n", temp, duty);
        sleep(LOG_INTERVAL);
    }

    printf("\nShutting down...\n");
    set_fan_speed(0);

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    printf("Fan control stopped.\n");
    return EXIT_SUCCESS;
}

