/*
 * BMP280 weather logger for Raspberry Pi 4 Model B
 * I2C bus 1 (/dev/i2c-1), SDA=GPIO2, SCL=GPIO3
 * Default address 0x76; falls back to 0x77 if SDO tied to GND.
 * Logs to weather_data.txt every 5 s in CSV format.
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp280_logger bmp280_logger.c
 * Run:    ./bmp280_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- BMP280 constants (datasheet rev 1.26) ---- */
#define BMP280_ADDR_DEFAULT  0x76
#define BMP280_ADDR_ALT      0x77

#define BMP280_REG_ID        0xD0
#define BMP280_REG_RESET     0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG    0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB  0xFA
#define BMP280_REG_CALIB     0x88

#define BMP280_CHIP_ID       0x58
#define BMP280_RESET_CMD     0xB6

/* ctrl_meas: osrs_t=x1 (001), osrs_p=x1 (001), mode=forced (10) -> 0x25 */
#define BMP280_CTRL_MEAS_FORCED 0x25

/* config: t_sb=500ms (010), filter=off (000), spi3w_en=0 -> 0xA0 */
#define BMP280_CONFIG_DEFAULT 0xA0

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "weather_data.txt"
#define SAMPLE_PERIOD  5          /* seconds */
#define MAX_RETRIES    3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Calibration coefficients ---- */
static uint16_t dig_T1;
static int16_t  dig_T2, dig_T3;
static uint16_t dig_P1;
static int16_t  dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
static int32_t  t_fine;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int bmp280_init(int fd)
{
    uint8_t id;
    if (i2c_read_block(fd, BMP280_REG_ID, &id, 1) != 0)
        return -1;
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x%02X)\n",
                id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, BMP280_RESET_CMD) != 0)
        return -1;
    usleep(2000);  /* datasheet: wait >= 2 ms after reset */

    uint8_t cal[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, cal, sizeof(cal)) != 0)
        return -1;

