/*
 * LM75 temperature monitor with alert LED on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   LM75 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   LM75 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   LM75 VDD  -> 3.3 V
 *   LM75 GND  -> GND
 *   Alert LED anode -> GPIO18 (BCM 18, pin 12) via 330 Ω resistor
 *   Alert LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o lm75_monitor lm75_monitor.c -lpigpio -lpthread
 * Run:    sudo ./lm75_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define LM75_ADDR           0x48          /* LM75 default address (ADDR pin tied to GND) */
#define ALERT_GPIO          18            /* BCM pin for alert LED */
#define BUFFER_SIZE         60            /* samples in circular buffer */
#define TEMP_THRESHOLD      28.0f         /* °C — alert LED turns on above this */
#define SAMPLE_PERIOD_US    1000000       /* 1 second between samples */
#define REINIT_DELAY_US     5000000       /* 5 s back-off after a reinit attempt */
#define MAX_CONSECUTIVE_ERR 10            /* abort after this many consecutive errors */

/* LM75 registers */
#define LM75_REG_TEMP       0x00
#define LM75_REG_CONFIG     0x01

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static pthread_mutex_t g_buf_mutex = PTHREAD_MUTEX_INITIALIZER;
static float    g_temp_buf[BUFFER_SIZE];
static int      g_buf_head = 0;
static int      g_buf_count = 0;
static float    g_avg_temp = 0.0f;
static bool     g_alert_active = false;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_temperature(float *temp_c);
static void update_buffer(float temp);
static void update_average(void);
static void *alert_thread(void *arg);
static void cleanup(void);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C init --------------------------------- */
static int init_i2c(void)
{
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }

    g_i2c_fd = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, LM75_ADDR, strerror(errno));
        return -1;
    }

    /*
     * Verify the sensor is present by reading the CONFIG register.
     * A NACK here typically means the device is not responding at the
     * expected address.
     */
    int cfg = i2cReadByteData(g_i2c_fd, LM75_REG_CONFIG);
    if (cfg < 0) {
        fprintf(stderr, "[ERROR] LM75 not responding at 0x%02X: %s\n",
                LM75_ADDR, strerror(errno));
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------- GPIO init -------------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return -1;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, OUTPUT) failed\n", ALERT_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed\n", ALERT_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* --------------------------- Temperature read ----------------------------- */
static int read_temperature(float *temp_c)
{
    int raw = i2cReadWordData(g_i2c_fd, LM75_REG_TEMP);
    if (raw < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(TEMP) failed: %s\n",
                strerror(errno));
        return -1;
    }

    /*
     * LM75 returns 16-bit two's-complement data.
     * Bits [15:8] = MSB, Bits [7:0] = LSB.
     * Resolution is 0.125 °C per LSB.
     */
    int16_t signed_raw = (int16_t)raw;
    *temp_c = (float)signed_raw * 0.125f;
    return 0;
