static void update_buffer(float temp)
{
    pthread_mutex_lock(&g_buf_mutex);

    g_temp_buf[g_buf_head] = temp;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;

    update_average();

    pthread_mutex_unlock(&g_buf_mutex);
}

static void update_average(void)
{
    float sum = 0.0f;
    for (int i = 0; i < g_buf_count; i++)
        sum += g_temp_buf[i];
    g_avg_temp = (g_buf_count > 0) ? (sum / (float)g_buf_count) : 0.0f;
}

/* ------------------------------- Alert thread ----------------------------- */
static void *alert_thread(void *arg)
{
    (void)arg;

    while (g_running) {
        pthread_mutex_lock(&g_buf_mutex);
        bool above = (g_buf_count > 0 && g_avg_temp > TEMP_THRESHOLD);
        pthread_mutex_unlock(&g_buf_mutex);

        if (above && !g_alert_active) {
            if (gpioWrite(ALERT_GPIO, 1) == 0) {
                g_alert_active = true;
                printf("[ALERT] Temperature %.2f C exceeds %.1f C — LED ON\n",
                       g_avg_temp, TEMP_THRESHOLD);
            } else {
                fprintf(stderr, "[ERROR] gpioWrite(%d, 1) failed\n", ALERT_GPIO);
            }
        } else if (!above && g_alert_active) {
            if (gpioWrite(ALERT_GPIO, 0) == 0) {
                g_alert_active = false;
                printf("[ALERT] Temperature %.2f C below %.1f C — LED OFF\n",
                       g_avg_temp, TEMP_THRESHOLD);
            } else {
                fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed\n", ALERT_GPIO);
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    return NULL;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    /* Turn off alert LED */
    if (g_alert_active) {
        gpioWrite(ALERT_GPIO, 0);
        g_alert_active = false;
    }

    /* Release GPIO resources */
    gpioTerminate();

    /* Close I2C bus */
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }

    /* Destroy mutex */
    pthread_mutex_destroy(&g_buf_mutex);
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "[FATAL] I2C initialization failed — aborting.\n");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        fprintf(stderr, "[FATAL] GPIO initialization failed — aborting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start alert thread */
    pthread_t alert_tid;
    if (pthread_create(&alert_tid, NULL, alert_thread, NULL) != 0) {
        perror("[FATAL] pthread_create(alert_thread)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LM75 temperature monitor started.\n");
    printf("  I2C bus %d, address 0x%02X, alert GPIO %d\n",
           I2C_BUS, LM75_ADDR, ALERT_GPIO);
    printf("  Threshold: %.1f C, Sample period: %d ms\n",
           TEMP_THRESHOLD, SAMPLE_PERIOD_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        float temp;

        if (read_temperature(&temp) == 0) {
            consecutive_errors = 0;
            update_buffer(temp);
            printf("Temperature: %.2f C  (avg: %.2f C)\n", temp, g_avg_temp);
        } else {
            consecutive_errors++;
            fprintf(stderr, "[WARN] Temperature read failed (%d/%d)\n",
                    consecutive_errors, MAX_CONSECUTIVE_ERR);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERR) {
                fprintf(stderr, "[FATAL] %d consecutive errors — aborting.\n",
                        consecutive_errors);
                break;
            }

            if (init_i2c() != 0) {
                fprintf(stderr, "[WARN] I2C re-initialization failed; retrying in %d ms\n",
                        REINIT_DELAY_US / 1000);
                gpioDelay(REINIT_DELAY_US);
                continue;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
