#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>
#include <jansson.h>

#define CONFIG_FILE "config.json"
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX_TEMPERATURE 80.0
#define DEFAULT_TARGET_TEMPERATURE 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define LOOP_DELAY_US 100000
#define PT100_R0 100.0
#define PT100_ALPHA 0.00385
#define RREF 430.0
#define MAX31865_CONFIG_VBIAS 0x80
#define MAX31865_CONFIG_FAULT_STATUS 0x01
#define MAX31865_CONFIG_FAULT_AUTO_CLEAR 0x02
#define MAX31865_CONFIG_50HZ_FILTER 0x04
#define MAX31865_CONFIG_3WIRE 0x08
#define MAX31865_CONFIG_FAULT_DETECT 0x60
#define MAX31865_CONFIG_FAULT_DETECT_1 0x00
#define MAX31865_CONFIG_FAULT_DETECT_2 0x20
#define MAX31865_CONFIG_FAULT_DETECT_4 0x40
#define MAX31865_CONFIG_FAULT_DETECT_60 0x60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double target_temperature = DEFAULT_TARGET_TEMPERATURE;
static double kp = DEFAULT_KP;
static double ki = DEFAULT_KI;
static double kd = DEFAULT_KD;
static double integral = 0.0;
static double previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(void) {
    json_error_t error;
    json_t *root = json_load_file(CONFIG_FILE, 0, &error);
    if (!root) {
        fprintf(stderr, "Error loading config file '%s': %s (line %d, column %d)\n",
                CONFIG_FILE, error.text, error.line, error.column);
        return -1;
    }

    json_t *temp = json_object_get(root, "target_temperature");
    if (json_is_number(temp)) {
        target_temperature = json_number_value(temp);
    } else {
        fprintf(stderr, "Warning: target_temperature not found, using default %.2f\n", DEFAULT_TARGET_TEMPERATURE);
        target_temperature = DEFAULT_TARGET_TEMPERATURE;
    }

    json_t *kp_val = json_object_get(root, "kp");
    if (json_is_number(kp_val)) {
        kp = json_number_value(kp_val);
    } else {
        fprintf(stderr, "Warning: kp not found, using default %.2f\n", DEFAULT_KP);
        kp = DEFAULT_KP;
    }

    json_t *ki_val = json_object_get(root, "ki");
    if (json_is_number(ki_val)) {
        ki = json_number_value(ki_val);
    } else {
        fprintf(stderr, "Warning: ki not found, using default %.2f\n", DEFAULT_KI);
        ki = DEFAULT_KI;
    }

    json_t *kd_val = json_object_get(root, "kd");
    if (json_is_number(kd_val)) {
        kd = json_number_value(kd_val);
    } else {
        fprintf(stderr, "Warning: kd not found, using default %.2f\n", DEFAULT_KD);
        kd = DEFAULT_KD;
    }

    json_decref(root);
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n", SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", PWM_GPIO);
        return -1;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", PWM_GPIO);
        return -1;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", PWM_GPIO);
        return -1;
    }
    if (gpioPWM(PWM_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing PWM on GPIO %d\n", PWM_GPIO);
        return -1;
    }
    return 0;
}

static int read_max31865(double *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)(rx[0] & 0x7F) << 8) | (uint8_t)rx[1];
    uint8_t fault = (uint8_t)rx[2] & 0x07;

    if (fault != 0) {
        fprintf(stderr, "MAX31865 fault detected: ");
        if (fault & 0x01) fprintf(stderr, "Open circuit ");
        if (fault & 0x02) fprintf(stderr, "Short to GND ");
        if (fault & 0x04) fprintf(stderr, "Short to VCC ");
        fprintf(stderr, "\n");
        return -1;
    }

    if (raw & 0x0001) {
        fprintf(stderr, "MAX31865 fault: Thermocouple not connected\n");
        return -1;
    }

    double rtd_resistance = (double)raw * RREF / 32768.0;
    if (rtd_resistance < 0.01) {
        fprintf(stderr, "MAX31865 fault: Invalid RTD resistance: %.4f\n", rtd_resistance);
        return -1;
    }

    double z1 = -PT100_ALPHA;
    double z2 = PT100_ALPHA * PT100_ALPHA * (rtd_resistance - PT100_R0) / (PT100_R0 * PT100_R0);
    double z3 = sqrt(z2 * z2 - 4.0 * PT100_ALPHA * (1.0 - rtd_resistance / PT100_R0));
    double temp_internal = (-z2 + z3) / (2.0 * PT100_ALPHA);
    *temperature = temp_internal;
    return 0;
}

static double calculate_pid(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = kp * error + ki * integral + kd * derivative;
    previous_error = error;
    return output;
}

static int set_pwm_duty(double duty) {
    if (duty < 0.0) duty = 0.0;
    if (duty > 100.0) duty = 100.0;
    int pwm_value = (int)(duty * (PWM_RANGE / 100.0));
    if (gpioPWM(PWM_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(PWM_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (read_config() != 0) {
        fprintf(stderr, "Failed to read configuration, using defaults\n");
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature regulation started. Target: %.2f°C, Kp: %.2f, Ki: %.2f, Kd: %.2f\n",
           target_temperature, kp, ki, kd);

    while (running) {
        double current_temperature;
        if (read_max31865(&current_temperature) != 0) {
            fprintf(stderr, "Error reading temperature, shutting down\n");
            break;
        }

        if (current_temperature > MAX_TEMPERATURE) {
            fprintf(stderr, "Temperature exceeds maximum: %.2f°C, shutting down\n", current_temperature);
            break;
        }

        double pid_output = calculate_pid(current_temperature);
        if (set_pwm_duty(pid_output) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle, shutting down\n");
            break;
        }

        printf("Current: %.2f°C, Target: %.2f°C, PID: %.2f%%\n",
               current_temperature, target_temperature, pid_output);

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("Temperature regulation stopped.\n");
    return 0;
}

