    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1, &cal->ac1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC2, &cal->ac2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC3, &cal->ac3) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC4, &cal->ac4) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC5, &cal->ac5) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC6, &cal->ac6) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B1, &cal->b1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B2, &cal->b2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MB, &cal->mb) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MC, &cal->mc) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MD, &cal->md) < 0) return -1;
    return 0;
}

static int read_raw_temp(int fd, int32_t *ut) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    usleep(5000);
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up, uint8_t oss) {
    uint8_t cmd = BMP180_CMD_PRESSURE_0 | (oss << 6);
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, cmd) < 0) return -1;
    usleep(2000 + (3000 << oss));
    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_XLSB, &xlsb) < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - oss);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *cal) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static float compute_temperature(int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    return ((b5 + 8) >> 4) / 10.0f;
}

static float compute_pressure(int32_t up, int32_t ut, uint8_t oss, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal->ac1) * 4 + x3) << oss) + 2) >> 2;
    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> oss);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return (float)(p + ((x1 + x2 + 3791) >> 4));
}

static int log_breach(float temp, float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return -1; }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Temp: %.2f C, Pressure: %.2f hPa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp, pressure);
    } else {
        fprintf(fp, "[timestamp error] - Temp: %.2f C, Pressure: %.2f hPa\n", temp, pressure);
    }
    fclose(fp);
    return 0;
}

static int init_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) { perror("open i2c bus"); return -1; }
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl I2C_SLAVE"); close(fd); return -1;
    }
    return fd;
}

static int read_sensor(int fd, const bmp180_cal_t *cal, float *temp, float *pressure) {
    int32_t ut, up;
    uint8_t oss = 3;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read_raw_temp(fd, &ut) < 0) {
            retries++; usleep(100000); continue;
        }
        if (read_raw_pressure(fd, &up, oss) < 0) {
            retries++; usleep(100000); continue;
        }
        *temp = compute_temperature(ut, cal);
        *pressure = compute_pressure(up, ut, oss, cal);
        return 0;
    }
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction"); return 1;
    }

    g_i2c_fd = init_i2c();
    if (g_i2c_fd < 0) return 1;

    bmp180_cal_t cal;
    if (read_calibration(g_i2c_fd, &cal) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        close(g_i2c_fd); return 1;
    }

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp, pressure;
        if (read_sensor(g_i2c_fd, &cal, &temp, &pressure) < 0) {
            fprintf(stderr, "Sensor read failed after %d retries\n", MAX_RETRIES);
        } else {
            if (temp > TEMP_THRESHOLD) {
                printf("Temperature breach: %.2f C\n", temp);
                log_breach(temp, pressure);
            }
            if (pressure < PRESSURE_THRESHOLD) {
                printf("Pressure breach: %.2f hPa\n", pressure);
                log_breach(temp, pressure);
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

