/*
 * BMP180 temperature/pressure monitor with fan control on Raspberry Pi 4.
 *
 * Wiring:
 *   BMP180 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   BMP180 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   BMP180 VDD  -> 3.3 V
 *   BMP180 GND  -> GND
 *   Fan +       -> GPIO18 (via suitable driver/MOSFET)
 *   Fan -       -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o bmp180_monitor bmp180_monitor.c -lpigpio -lrt
 * Run:    sudo ./bmp180_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define BMP180_ADDR         0x5F          /* BMP180 default I2C address (ADDR pin tied to GND) */
#define FAN_GPIO            18
#define TEMP_THRESHOLD_C    30.0f
#define BUFFER_SIZE         60
#define SAMPLE_PERIOD_US    500000        /* 500 ms */
#define OSS                 0             /* Oversampling setting (0–3) */

/* BMP180 registers */
#define BMP180_REG_CONTROL  0xF4
#define BMP180_REG_MSB      0xF6
#define BMP180_REG_LSB      0xF7
#define BMP180_REG_XLSB     0xF8
#define BMP180_REG_CAL_AC1  0xAA
#define BMP180_REG_CAL_AC2  0xAC
#define BMP180_REG_CAL_AC3  0xAE
#define BMP180_REG_CAL_AC4  0xB0
#define BMP180_REG_CAL_AC5  0xB2
#define BMP180_REG_CAL_AC6  0xB4
#define BMP180_REG_CAL_B1   0xB6
#define BMP180_REG_CAL_B2   0xB8
#define BMP180_REG_CAL_MB   0xBA
#define BMP180_REG_CAL_MC   0xBC
#define BMP180_REG_CAL_MD   0xBE

/* BMP180 commands */
#define BMP180_CMD_TEMP     0x2E
#define BMP180_CMD_PRESS    0x34

/* ------------------------------- Data types ------------------------------- */
typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int        head;
    int        count;
} CircularBuffer;

/* --------------------------- Global state -------------------------------- */
static int           i2c_handle = -1;
static volatile sig_atomic_t running = 1;
static CircularBuffer buffer;

/* Calibration coefficients (signed/unsigned per datasheet) */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

/* --------------------------- Function prototypes -------------------------- */
static int  read_calibration(void);
static int  read_raw_temperature(int32_t *ut);
static int  read_raw_pressure(int32_t *up);
static int  compute_b5(int32_t ut, int32_t *b5_out);
static int  read_temperature(float *temp_c);
static int  read_pressure(float *pressure_pa);
static void fan_control(float temp_c);
static void timer_callback(void *userdata);
static void signal_handler(int sig);
static void buffer_init(CircularBuffer *cb);
static void buffer_add(CircularBuffer *cb, SensorData d);
static void buffer_print(const CircularBuffer *cb);

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_calibration() != 0) {
        fprintf(stderr, "Error: failed to read BMP180 calibration data.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d.\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    buffer_init(&buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed.\n");
        gpioWrite(FAN_GPIO, 0);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BMP180 monitoring started. Sampling every %d ms. Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_US / 1000);

    while (running) {
        sleep(1);
    }

    /* Graceful shutdown */
    gpioSetTimerFuncEx(0, 0, NULL, NULL);   /* cancel timer */
    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

/* --------------------------- Calibration read ----------------------------- */
static int read_calibration(void)
{
    uint8_t buf[22];

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: failed to read 22-byte calibration block.\n");
        return -1;
    }

    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);

    return 0;
}

/* --------------------------- Raw temperature ------------------------------ */
static int read_raw_temperature(int32_t *ut)
{
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) {
        fprintf(stderr, "Error: failed to write temperature command.\n");
        return -1;
    }
    gpioDelay(5000);  /* 4.5 ms max conversion time */

    uint8_t msb = (uint8_t)i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    uint8_t lsb = (uint8_t)i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (msb == 0xFF && lsb == 0xFF) {
        fprintf(stderr, "Error: temperature read returned 0xFFFF (sensor absent or bus error).\n");
        return -1;
    }
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

/* --------------------------- Raw pressure -------------------------------- */
static int read_raw_pressure(int32_t *up)
{
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESS + (OSS << 6)) != 0) {
        fprintf(stderr, "Error: failed to write pressure command.\n");
        return -1;
    }
    gpioDelay(2000 + (3000 << OSS));  /* 2 ms + (3–5 ms × 2^OSS) */

    uint8_t msb = (uint8_t)i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    uint8_t lsb = (uint8_t)i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    uint8_t xlsb = (uint8_t)i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb == 0xFF && lsb == 0xFF && xlsb == 0xFF) {
        fprintf(stderr, "Error: pressure read returned 0xFFFFFF (sensor absent or bus error).\n");
        return -1;
    }
    *up = ((int32_t)msb << 16) | ((int32_t)lsb << 8) | (int32_t)xlsb;
    *up >>= (8 - OSS);
    return 0;
}

/* --------------------------- B5 compensation ------------------------------ */
static int compute_b5(int32_t ut, int32_t *b5_out)
{
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    *b5_out = x1 + x2;
    return 0;
}

/* --------------------------- Temperature (°C) ----------------------------- */
static int read_temperature(float *temp_c)
{
    int32_t ut;
    if (read_raw_temperature(&ut) != 0)
        return -1;

    int32_t b5;
    compute_b5(ut, &b5);
    *temp_c = ((b5 + 8) >> 4) / 10.0f;
    return 0;
}

/* --------------------------- Pressure (Pa) -------------------------------- */
static int read_pressure(float *pressure_pa)
{
    int32_t ut, up;
    if (read_raw_temperature(&ut) != 0)
        return -1;
    if (read_raw_pressure(&up) != 0)
        return -1;

    int32_t b5;
    compute_b5(ut, &b5);

    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;

    uint32_t x4 = ((uint32_t)ac3 * (uint32_t)b6) >> 13;
    uint32_t x5 = ((uint32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    uint32_t x6 = ((x4 + x5) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x6 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    *pressure_pa = (float)p;
    return 0;
}

/* --------------------------- Fan control ---------------------------------- */
static void fan_control(float temp_c)
{
    int level = (temp_c > TEMP_THRESHOLD_C) ? 1 : 0;
    if (gpioWrite(FAN_GPIO, level) != 0) {
        fprintf(stderr, "Warning: gpioWrite failed for GPIO%d.\n", FAN_GPIO);
    }
}

/* --------------------------- Timer callback ------------------------------- */
static void timer_callback(void *userdata)
{
    (void)userdata;

    float temp_c, pressure_pa;

    if (read_temperature(&temp_c) != 0) {
        fprintf(stderr, "Warning: temperature read failed, skipping sample.\n");
        return;
    }

    if (read_pressure(&pressure_pa) != 0) {
        fprintf(stderr, "Warning: pressure read failed, skipping sample.\n");
        return;
    }

    SensorData d;
    d.timestamp   = time(NULL);
    d.temperature = temp_c;
    d.pressure    = pressure_pa;

    buffer_add(&buffer, d);
    buffer_print(&buffer);
    fan_control(temp_c);
}

/* --------------------------- Signal handler ------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* --------------------------- Circular buffer ------------------------------ */
static void buffer_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void buffer_add(CircularBuffer *cb, SensorData d)
{
    cb->data[cb->head] = d;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void buffer_print(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return;

    int idx = (cb->head - cb->count + BUFFER_SIZE) % BUFFER_SIZE;
    printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n",
           (long)cb->data[idx].timestamp,
           cb->data[idx].temperature,
           cb->data[idx].pressure);
}

