#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34
#define BMP180_CMD_PRESSURE1 0x74
#define BMP180_CMD_PRESSURE2 0xB4
#define BMP180_CMD_PRESSURE3 0xF4
#define DEBOUNCE_US 200000
#define LOG_INTERVAL_S 2
#define I2C_BUS "/dev/i2c-1"
#define GPIO_INTERRUPT 27

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_interrupt_tick = 0;
static int i2c_fd = -1;
static FILE *log_file = NULL;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg16u(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration(int fd, bmp180_cal_t *cal) {
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1, &cal->ac1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC2, &cal->ac2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC3, &cal->ac3) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC4, &cal->ac4) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC5, &cal->ac5) < 0) return -1;
    if (i2c_read_reg16u(fd, BMP180_REG_CAL_AC6, &cal->ac6) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B1, &cal->b1) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_B2, &cal->b2) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MB, &cal->mb) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MC, &cal->mc) < 0) return -1;
    if (i2c_read_reg16(fd, BMP180_REG_CAL_MD, &cal->md) < 0) return -1;
    return 0;
}

static int read_raw_temp(int fd, int32_t *ut) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_reg8(fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE0) < 0) return -1;
    gpioDelay(5000);
    uint8_t msb, lsb, xlsb;
    if (i2c_read_reg8(fd, BMP180_REG_MSB, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_LSB, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, BMP180_REG_XLSB, &xlsb) < 0) return -1;
    *up = ((int32_t)msb << 16 | (int32_t)lsb << 8 | (int32_t)xlsb) >> 8;
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *cal) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5, const bmp180_cal_t *cal) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal->ac1) * 4 + x3) << 0) + 2) >> 2;
    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    if (tick - last_interrupt_tick > DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_interrupt_tick = tick;
    }
}

static void cleanup(void) {
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BMP180_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    bmp180_cal_t cal;
    if (read_calibration(i2c_fd, &cal) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_INTERRUPT, PI_INPUT);
    gpioSetPullUpDown(GPIO_INTERRUPT, PI_PUD_UP);
    if (gpioSetISRFuncEx(GPIO_INTERRUPT, FALLING_EDGE, 0, interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set interrupt handler on GPIO%d\n", GPIO_INTERRUPT);
        cleanup();
        return 1;
    }

    printf("BMP180 logging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (logging_enabled) {
            int32_t ut, up, b5, pressure;
            if (read_raw_temp(i2c_fd, &ut) < 0) {
                fprintf(stderr, "I2C error reading temperature: %s\n", strerror(errno));
                gpioDelay(LOG_INTERVAL_S * 1000000);
                continue;
            }
            if (read_raw_pressure(i2c_fd, &up) < 0) {
                fprintf(stderr, "I2C error reading pressure: %s\n", strerror(errno));
                gpioDelay(LOG_INTERVAL_S * 1000000);
                continue;
            }
            b5 = compute_b5(ut, &cal);
            pressure = compute_pressure(up, b5, &cal);

            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (log_file == NULL) {
                log_file = fopen("pressure_log.txt", "a");
                if (log_file == NULL) {
                    fprintf(stderr, "Failed to open pressure_log.txt: %s\n", strerror(errno));
                    gpioDelay(LOG_INTERVAL_S * 1000000);
                    continue;
                }
            }
            fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure / 100.0);
            fflush(log_file);
            printf("%s, %.2f Pa\n", timestamp, pressure / 100.0);
        }
        gpioDelay(LOG_INTERVAL_S * 1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

