/*
 * MAX31855 Thermocouple Reader with PWM Heater Control
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (SPI + hardware PWM)
 *
 * Wiring:
 *   MAX31855 CS  -> GPIO8  (SPI0 CE0)
 *   MAX31855 SCLK-> GPIO11 (SPI0 SCLK)
 *   MAX31855 DO  -> GPIO9  (SPI0 MISO)
 *   MAX31855 VCC -> 3.3 V
 *   MAX31855 GND -> GND
 *   Relay IN    -> GPIO17 (hardware PWM0)
 *   Relay VCC   -> 5 V (or appropriate supply)
 *   Relay GND   -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o heater_control heater_control.c -lpigpio -lrt
 * Run:    sudo ./heater_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED        2000000    /* 2 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define HEATER_GPIO      17         /* Hardware PWM0 */
#define PWM_FREQUENCY    1000       /* 1 kHz */
#define PWM_RANGE        1000       /* 0–1000 duty cycle steps */

#define TARGET_TEMP      25.0f      /* °C */
#define MAX_DUTY_CYCLE   80.0f      /* % */
#define KP               2.0f
#define KI               0.1f
#define DT               1.0f       /* seconds */

#define LOG_FILE         "heater_log.csv"
#define ERROR_TEMP       (-1000.0f)

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;
static int                   g_spi_handle = -1;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  initialize(void);
static void cleanup(void);
static int  read_max31855(float *temperature);
static void set_heater_duty(float duty_cycle);
static void log_data(float temperature, float duty_cycle);
static void log_error(const char *message);
static float calculate_pid(float setpoint, float actual);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Ensure heater is off */
    if (g_spi_handle >= 0) {
        set_heater_duty(0.0f);
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ----------------------------- Initialization ----------------------------- */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    /* Configure heater GPIO for hardware PWM */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Ensure heater starts off */
    set_heater_duty(0.0f);

    /* Open SPI0 CE0 at 2 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d).\n", g_spi_handle);
        gpioTerminate();
        return -1;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature (C),Duty Cycle (%%),Error\n");
        fflush(g_log_fp);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: failed to register SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: failed to register SIGTERM handler");
    }

    return 0;
}

/* --------------------------- MAX31855 Read ------------------------------- */
/*
 * MAX31855 32-bit SPI frame (MSB first):
 *   D[31:18]  Thermocouple temperature (14-bit signed, 0.25 °C / count)
 *   D[17]     Reserved
 *   D[16]     Fault bit (1 = fault)
 *   D[15:4]   Internal reference (12-bit signed, 0.0625 °C / count)
 *   D[3]      Reserved
 *   D[2]      Fault bit (1 = fault)
 *   D[1]      SCV fault (short to VCC)
 *   D[0]      SCG fault (short to GND)
 *
 * Returns 0 on success, -1 on SPI transfer failure, -2 on MAX31855 fault.
 */
static int read_max31855(float *temperature)
{
    if (temperature == NULL) {
        return -1;
    }

    char rx_buf[4] = {0, 0, 0, 0};
    char tx_buf[4] = {0, 0, 0, 0};

    int bytes = spiXfer(g_spi_handle, tx_buf, rx_buf, 4);
    if (bytes != 4) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d).\n", bytes);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx_buf[0] << 24) |
                   ((uint32_t)(uint8_t)rx_buf[1] << 16) |
                   ((uint32_t)(uint8_t)rx_buf[2] <<  8) |
                   ((uint32_t)(uint8_t)rx_buf[3]);

    /* Fault bit (D16) */
    if (raw & 0x00010000) {
        fprintf(stderr, "Error: MAX31855 fault detected (raw=0x%08X).\n", raw);

        if (raw & 0x00000001) {
            fprintf(stderr, "  Fault: SCG (short to GND)\n");
        }
        if (raw & 0x00000002) {
            fprintf(stderr, "  Fault: SCV (short to VCC)\n");
        }
        if (raw & 0x00000004) {
            fprintf(stderr, "  Fault: OC  (open circuit)\n");
        }

        return -2;
    }

    /* Thermocouple temperature: bits D31:18, 14-bit signed, 0.25 °C / count */
    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000) {
        thermocouple_raw |= 0xC000; /* sign-extend */
    }
    *temperature = thermocouple_raw * 0.25f;

    return 0;
}

/* --------------------------- Heater Control ------------------------------ */
static void set_heater_duty(float duty_cycle)
{
    if (duty_cycle < 0.0f) {
        duty_cycle = 0.0f;
    }
    if (duty_cycle > 100.0f) {
        duty_cycle = 100.0f;
    }

    int pwm_value = (int)(duty_cycle * (PWM_RANGE / 100.0f));
    if (gpioPWM(HEATER_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed for GPIO%d.\n", HEATER_GPIO);
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_data(float temperature, float duty_cycle)
{
    if (g_log_fp == NULL) {
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed.\n");
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s,%.2f,%.2f,OK\n", timestamp, temperature, duty_cycle);
    fflush(g_log_fp);
}

static void log_error(const char *message)
{
    if (g_log_fp == NULL) {
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed.\n");
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s,ERROR,%s\n", timestamp, message);
    fflush(g_log_fp);
}

/* ------------------------------- PID ------------------------------------- */
static float calculate_pid(float setpoint, float actual)
{
    static float integral = 0.0f;
    static float previous_error = 0.0f;

    float error = setpoint - actual;

    integral += error * DT;

    /* Anti-windup: clamp integral to prevent excessive heating */
    if (integral > (MAX_DUTY_CYCLE / KP)) {
        integral = MAX_DUTY_CYCLE / KP;
    }
    if (integral < 0.0f) {
        integral = 0.0f;
    }

    float derivative = (error - previous_error) / DT;

    float output = KP * error + KI * integral + KD * derivative;

    previous_error = error;

    if (output < 0.0f) {
        output = 0.0f;
    }
    if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
    }

    return output;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    float integral = 0.0f;
    float previous_error = 0.0f;

    printf("Heater control started. Target: %.1f °C, Max duty: %.0f %%\n",
           TARGET_TEMP, MAX_DUTY_CYCLE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature = ERROR_TEMP;
        int rc = read_max31855(&temperature);

        if (rc == 0) {
            float duty_cycle = calculate_pid(TARGET_TEMP, temperature);
            set_heater_duty(duty_cycle);
            log_data(temperature, duty_cycle);
            printf("T=%.2f °C  Duty=%.2f %%\n", temperature, duty_cycle);
        } else if (rc == -2) {
            /* MAX31855 fault: turn off heater immediately */
            set_heater_duty(0.0f);
            log_error("MAX31855 fault detected");
            fprintf(stderr, "MAX31855 fault detected. Heater disabled.\n");
        } else {
            /* SPI transfer failure: turn off heater for safety */
            set_heater_duty(0.0f);
            log_error("SPI transfer failure");
            fprintf(stderr, "SPI transfer failure. Heater disabled.\n");
        }

        time_sleep(DT);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

