    return 0;
}

/* --------------------------- Heater Control ------------------------------ */
static void set_heater_duty(float duty_cycle)
{
    if (duty_cycle < 0.0f) {
        duty_cycle = 0.0f;
    }
    if (duty_cycle > 100.0f) {
        duty_cycle = 100.0f;
    }

    int pwm_value = (int)(duty_cycle * (PWM_RANGE / 100.0f));
    if (gpioPWM(HEATER_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed for GPIO%d.\n", HEATER_GPIO);
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_data(float temperature, float duty_cycle)
{
    if (g_log_fp == NULL) {
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed.\n");
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s,%.2f,%.2f,OK\n", timestamp, temperature, duty_cycle);
    fflush(g_log_fp);
}

static void log_error(const char *message)
{
    if (g_log_fp == NULL) {
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed.\n");
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s,ERROR,%s\n", timestamp, message);
    fflush(g_log_fp);
}

/* ------------------------------- PID ------------------------------------- */
static float calculate_pid(float setpoint, float actual)
{
    static float integral = 0.0f;
    static float previous_error = 0.0f;

    float error = setpoint - actual;

    integral += error * DT;

    /* Anti-windup: clamp integral to prevent excessive heating */
    if (integral > (MAX_DUTY_CYCLE / KP)) {
        integral = MAX_DUTY_CYCLE / KP;
    }
    if (integral < 0.0f) {
        integral = 0.0f;
    }

    float derivative = (error - previous_error) / DT;

    float output = KP * error + KI * integral + KD * derivative;

    previous_error = error;

    if (output < 0.0f) {
        output = 0.0f;
    }
    if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
    }

    return output;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    float integral = 0.0f;
    float previous_error = 0.0f;

    printf("Heater control started. Target: %.1f °C, Max duty: %.0f %%\n",
           TARGET_TEMP, MAX_DUTY_CYCLE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature = ERROR_TEMP;
        int rc = read_max31855(&temperature);

        if (rc == 0) {
            float duty_cycle = calculate_pid(TARGET_TEMP, temperature);
            set_heater_duty(duty_cycle);
            log_data(temperature, duty_cycle);
            printf("T=%.2f °C  Duty=%.2f %%\n", temperature, duty_cycle);
        } else if (rc == -2) {
            /* MAX31855 fault: turn off heater immediately */
            set_heater_duty(0.0f);
            log_error("MAX31855 fault detected");
            fprintf(stderr, "MAX31855 fault detected. Heater disabled.\n");
        } else {
            /* SPI transfer failure: turn off heater for safety */
            set_heater_duty(0.0f);
            log_error("SPI transfer failure");
            fprintf(stderr, "SPI transfer failure. Heater disabled.\n");
        }

        time_sleep(DT);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

