#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_RANGE  255
#define PWM_DUTY_OFF 255

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_pwm_channel(int pin, int duty)
{
    if (duty < 0 || duty > PWM_RANGE) {
        fprintf(stderr, "Error: invalid PWM duty %d for pin %d\n", duty, pin);
        return -1;
    }
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for pin %d (duty=%d)\n", pin, duty);
        return -1;
    }
    return 0;
}

static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error: failed to parse temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error: read error on %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milli;
}

static void set_led_color(int red, int green, int blue)
{
    if (set_pwm_channel(RED_PIN, red) != 0)
        return;
    if (set_pwm_channel(GREEN_PIN, green) != 0)
        return;
    if (set_pwm_channel(BLUE_PIN, blue) != 0)
        return;
}

static void cleanup_led(void)
{
    set_pwm_channel(RED_PIN, PWM_DUTY_OFF);
    set_pwm_channel(GREEN_PIN, PWM_DUTY_OFF);
    set_pwm_channel(BLUE_PIN, PWM_DUTY_OFF);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", RED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", GREEN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", BLUE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", RED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", GREEN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", BLUE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    cleanup_led();

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Warning: temperature read failed, skipping cycle\n");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        int red, green, blue;
        if (temp < 40000) {
            red = 0; green = 0; blue = PWM_RANGE;
        } else if (temp < 60000) {
            red = 0; green = PWM_RANGE; blue = 0;
        } else {
            red = PWM_RANGE; green = 0; blue = 0;
        }

        set_led_color(red, green, blue);

        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n",
               temp, red, green, blue);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    cleanup_led();
    gpioTerminate();
    return EXIT_SUCCESS;
}

