#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define API_ENDPOINT "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define DHT22_TIMEOUT_US 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int byte_idx = 0;
    uint32_t start_tick, end_tick;

    // Send start signal: pull low for at least 1ms
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(2000); // 2ms low
    gpioWrite(gpio, 1);
    gpioDelay(30);   // 30us high

    // Switch to input and wait for sensor response
    gpioSetMode(gpio, PI_INPUT);

    // Wait for sensor to pull low (response signal)
    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
            fprintf(stderr, "DHT22: Timeout waiting for response low\n");
            return -1;
        }
    }

    // Wait for sensor to pull high (response signal end)
    start_tick = gpioTick();
    while (gpioRead(gpio) == 0) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
            fprintf(stderr, "DHT22: Timeout waiting for response high\n");
            return -1;
        }
    }

    // Wait for sensor to pull low (data start)
    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
            fprintf(stderr, "DHT22: Timeout waiting for data start\n");
            return -1;
        }
    }

    // Read 40 bits
    for (bit_idx = 0; bit_idx < 40; bit_idx++) {
        // Wait for high pulse (start of bit)
        start_tick = gpioTick();
        while (gpioRead(gpio) == 0) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
                fprintf(stderr, "DHT22: Timeout waiting for bit high\n");
                return -1;
            }
        }

        // Measure high pulse duration
        start_tick = gpioTick();
        while (gpioRead(gpio) == 1) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
                fprintf(stderr, "DHT22: Timeout waiting for bit low\n");
                return -1;
            }
        }

        end_tick = gpioTick();
        uint32_t pulse_duration = end_tick - start_tick;

        // Determine bit value: 0 if pulse < 50us, 1 if pulse > 50us
        if (pulse_duration > 50) {
            data[byte_idx] |= (1 << (7 - (bit_idx % 8)));
        }

        if ((bit_idx + 1) % 8 == 0) {
            byte_idx++;
        }
    }

    // Verify checksum
    int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        fprintf(stderr, "DHT22: Checksum mismatch (calc=%d, recv=%d)\n", checksum, data[4]);
        return -1;
    }

    // Convert data
    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int post_data(const char *endpoint, float temperature, float humidity) {
    char json_payload[256];
    snprintf(json_payload, sizeof(json_payload),
             "{\"temperature\": %.2f, \"humidity\": %.2f}",
             temperature, humidity);

    FILE *fp = popen("curl -s -X POST -H \"Content-Type: application/json\" -d '"
                     "{\"temperature\": %.2f, \"humidity\": %.2f}' "
                     "%s", "r", temperature, humidity, endpoint);
    if (fp == NULL) {
        fprintf(stderr, "Failed to execute curl: %s\n", strerror(errno));
        return -1;
    }

    char response[256];
    if (fgets(response, sizeof(response), fp) == NULL) {
        fprintf(stderr, "Failed to read curl response\n");
        pclose(fp);
        return -1;
    }
    pclose(fp);

    // Check for HTTP 200 response
    if (strstr(response, "HTTP/1.1 200 OK") == NULL) {
        fprintf(stderr, "HTTP request failed: %s", response);
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int retries = 0;

    while (!terminate) {
        if (read_dht22(DHT22_GPIO, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (post_data(API_ENDPOINT, temperature, humidity) != 0) {
                fprintf(stderr, "Failed to post data\n");
            }
            retries = 0;
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor\n");
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying in %d ms...\n", RETRY_DELAY_MS);
                gpioDelay(RETRY_DELAY_MS * 1000);
            } else {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
        }

        gpioDelay(2000000); // 2 seconds between readings
    }

    gpioTerminate();
    return 0;
}

