#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_AC1      0xAA
#define BMP180_REG_CAL_AC2      0xAC
#define BMP180_REG_CAL_AC3      0xAE
#define BMP180_REG_CAL_AC4      0xB0
#define BMP180_REG_CAL_AC5      0xB2
#define BMP180_REG_CAL_AC6      0xB4
#define BMP180_REG_CAL_B1       0xB6
#define BMP180_REG_CAL_B2       0xB8
#define BMP180_REG_CAL_MB       0xBA
#define BMP180_REG_CAL_MC       0xBC
#define BMP180_REG_CAL_MD       0xBE

#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE_OSS3 0xF4

#define BUTTON_GPIO             4
#define DEBOUNCE_US             200000   /* 200 ms */
#define LOG_INTERVAL_S          2
#define CONVERSION_DELAY_US     26000    /* 26 ms for OSS=3 */
#define LOG_FILE                "pressure_log.txt"

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_logging_enabled = 0;
static volatile uint32_t     g_last_interrupt_tick = 0;
static int                    g_i2c_handle = -1;

/* Calibration coefficients (signed/unsigned 16-bit) */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    if (i2cWriteByte(handle, reg) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP180 calibration                                                  */
/* ------------------------------------------------------------------ */
static int read_calibration_data(int handle)
{
    uint8_t buf[22];

    if (i2c_read_reg(handle, BMP180_REG_CAL_AC1, buf, sizeof(buf)) != 0) {
        fprintf(stderr, "Error: failed to read BMP180 calibration data\n");
        return -1;
    }

    ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1  = (int16_t)((buf[12] << 8) | buf[13]);
    b2  = (int16_t)((buf[14] << 8) | buf[15]);
    mb  = (int16_t)((buf[16] << 8) | buf[17]);
    mc  = (int16_t)((buf[18] << 8) | buf[19]);
    md  = (int16_t)((buf[20] << 8) | buf[21]);

    /* Sanity-check: AC1 should not be 0 or 0xFFFF on a real sensor */
    if (ac1 == 0 || ac1 == (int16_t)0xFFFF) {
        fprintf(stderr, "Error: invalid calibration data (AC1=0x%04X)\n",
                (unsigned)ac1);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP180 temperature (returns temperature in 0.1 °C)                 */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, int32_t *temperature)
{
    uint8_t buf[2];

    if (i2c_write_reg(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0)
        return -1;

    gpioDelay(5000); /* 4.5 ms max conversion time */

    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 2) != 0)
        return -1;

    int32_t ut = (int32_t)((buf[0] << 8) | buf[1]);

    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    *temperature = (b5 + 8) >> 4; /* 0.1 °C */
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP180 pressure (OSS=3)                                             */
/* ------------------------------------------------------------------ */
static int read_pressure(int handle, int32_t *pressure)
{
    uint8_t buf[3];

    if (i2c_write_reg(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS3) != 0)
        return -1;

    gpioDelay(CONVERSION_DELAY_US);

    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 3) != 0)
        return -1;

    int32_t up = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    up >>= 8; /* OSS=3 -> shift right 8 */

    int32_t x1 = ((int32_t)b2 * ((up - (int32_t)ac6) * (int32_t)ac5)) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 3) + 2) >> 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 3);

    int32_t p;
    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    *pressure = p; /* Pa */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_pressure(int32_t pressure_pa)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f hPa\n", ts, pressure_pa / 100.0);
    } else {
        fprintf(fp, "(unknown time), %.2f hPa\n", pressure_pa / 100.0);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Button interrupt handler                                            */
/* ------------------------------------------------------------------ */
static void button_interrupt_handler(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level != 0) /* only act on falling edge */
        return;

    /* Debounce using pigpio tick (microseconds, wraps every ~71.6 min) */
    uint32_t diff = tick - g_last_interrupt_tick;
    if (diff < DEBOUNCE_US)
        return;
    g_last_interrupt_tick = tick;

    g_logging_enabled = !g_logging_enabled;
    printf("Logging %s\n", g_logging_enabled ? "enabled" : "disabled");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at BMP180 address */
    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read calibration data */
    if (read_calibration_data(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: BMP180 not detected or calibration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure button GPIO */
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    /* Register interrupt handler for falling edge */
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0,
                         button_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: failed to set ISR for button GPIO\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("BMP180 pressure logger started. Press button (GPIO 4) to toggle logging.\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        if (g_logging_enabled) {
            int32_t temperature, pressure;

            if (read_temperature(g_i2c_handle, &temperature) != 0) {
                fprintf(stderr, "Warning: temperature read failed\n");
            } else if (read_pressure(g_i2c_handle, &pressure) != 0) {
                fprintf(stderr, "Warning: pressure read failed\n");
            } else {
                log_pressure(pressure);
            }
        }
        sleep(LOG_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

