        fprintf(stderr, "Error opening %s: %s\n", CPU_TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", CPU_TEMP_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    *temp_out = (float)temp_milli / 1000.0f;
    return 0;
}

static int read_fan_state(int *state_out) {
    FILE *fp = fopen(FAN_STATE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }

    int state;
    if (fscanf(fp, "%d", &state) != 1) {
        fprintf(stderr, "Error reading fan state from %s\n", FAN_STATE_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    *state_out = state;
    return 0;
}

static int read_fan_max_state(int *max_state_out) {
    FILE *fp = fopen(FAN_MAX_STATE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_MAX_STATE_FILE, strerror(errno));
        return -1;
    }

    int max_state;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading fan max state from %s\n", FAN_MAX_STATE_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    *max_state_out = max_state;
    return 0;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state to %s\n", FAN_STATE_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s for logging: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int calculate_fan_speed(float cpu_temp) {
    if (cpu_temp < 45.0f) {
        return 0;
    } else if (cpu_temp < 55.0f) {
        return 1;
    } else if (cpu_temp < 65.0f) {
        return 2;
    } else {
        return 3;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int current_fan_state = -1;
    int max_fan_state = -1;

    if (read_fan_max_state(&max_fan_state) != 0) {
        fprintf(stderr, "Failed to read fan max state. Exiting.\n");
        return EXIT_FAILURE;
    }

    if (max_fan_state < 0) {
        fprintf(stderr, "Invalid fan max state: %d. Exiting.\n", max_fan_state);
        return EXIT_FAILURE;
    }

    if (read_fan_state(&current_fan_state) != 0) {
        fprintf(stderr, "Failed to read initial fan state. Exiting.\n");
        return EXIT_FAILURE;
    }

    if (current_fan_state < 0 || current_fan_state > max_fan_state) {
        fprintf(stderr, "Invalid initial fan state: %d. Exiting.\n", current_fan_state);
        return EXIT_FAILURE;
    }

    printf("Fan control program started. Initial fan state: %d\n", current_fan_state);

    while (program_running) {
        float cpu_temp;
        if (read_cpu_temp(&cpu_temp) != 0) {
            fprintf(stderr, "Error reading CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int fan_speed = calculate_fan_speed(cpu_temp);

        if (fan_speed < 0 || fan_speed > max_fan_state) {
            fprintf(stderr, "Invalid fan speed calculated: %d. Using max state: %d\n", fan_speed, max_fan_state);
            fan_speed = max_fan_state;
        }

        if (fan_speed != current_fan_state) {
            if (write_fan_state(fan_speed) == 0) {
                current_fan_state = fan_speed;
                char log_message[128];
                snprintf(log_message, sizeof(log_message), "Fan speed set to %d (CPU Temp: %.2f°C)", fan_speed, cpu_temp);
                if (log_event(log_message) != 0) {
                    fprintf(stderr, "Error logging fan speed change.\n");
                }
            } else {
                fprintf(stderr, "Error setting fan speed to %d. Retrying in %d seconds.\n", fan_speed, POLL_INTERVAL_SEC);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down fan control program...\n");

    if (write_fan_state(0) != 0) {
        fprintf(stderr, "Error setting fan speed to 0 during shutdown.\n");
    }

    if (log_event("Fan control program stopped") != 0) {
        fprintf(stderr, "Error logging shutdown event.\n");
    }

    printf("Fan control program stopped.\n");
    return EXIT_SUCCESS;
}

