/*
 * PID temperature controller for Raspberry Pi Zero W
 *
 * Hardware:
 *   - MAX31855 thermocouple amplifier on SPI0 (CLK=GPIO11, CS=GPIO8/CE0, DO=GPIO9)
 *   - Resistive heater on GPIO18 (hardware PWM, 1 kHz, 0-100 % duty)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o heater_pid heater_pid.c -lpigpio -lrt
 * Run:
 *   sudo ./heater_pid
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define HEATER_GPIO          18          /* BCM pin for heater PWM */
#define SPI_CHANNEL          0           /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED            500000      /* 500 kHz */
#define SPI_FLAGS            0           /* Mode 0, active-low CS handled by pigpio */

#define PWM_FREQUENCY        1000        /* 1 kHz */
#define PWM_RANGE            100         /* 0-100 % duty */

#define TARGET_TEMPERATURE   50.0f       /* °C */
#define LOG_FILE             "heater_log.txt"

/* PID gains */
#define KP                   1.0f
#define KI                   0.1f
#define KD                   0.01f

/* Safety limits */
#define MAX_TEMPERATURE      100.0f
#define MIN_TEMPERATURE      0.0f

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  initialize(void);
static void cleanup(void);
static int  read_max31855(float *temperature);
static void set_heater_pwm(int duty_cycle);
static void log_data(float temperature, int duty_cycle, float pid_output);
static void log_error(const char *message);
static void failsafe(float temperature);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Initialization ----------------------------- */
static int initialize(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    /* Configure heater GPIO for hardware PWM */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }
    set_heater_pwm(0);  /* Heater off at startup */

    /* Open SPI bus for MAX31855 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz).\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return -1;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Temperature (C),PWM Duty (%),PID Output\n");
        fflush(g_log_file);
    }

    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Disable heater */
    set_heater_pwm(0);

    /* Close SPI */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Close log file */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ----------------------------- MAX31855 read ----------------------------- */
/*
 * MAX31855 4-byte SPI frame (MSB first):
 *   D[31:18]  Thermocouple temperature (14-bit signed, 0.25 °C / count)
 *   D[17]     Reserved
 *   D[16]     Fault bit (1 = fault)
 *   D[15:4]   Internal reference (12-bit signed, 0.0625 °C / count)
 *   D[3]      Reserved
 *   D[2]      SCV fault (short to VCC)
 *   D[1]      SCG fault (short to GND)
 *   D[0]      OC  fault (open circuit)
 */
static int read_max31855(float *temperature)
{
    char rx[4] = {0, 0, 0, 0};

    /*
     * spiXfer returns the number of bytes transferred on success,
     * or a negative pigpio error code on failure.
     */
    int bytes = spiXfer(g_spi_handle, rx, rx, 4);
    if (bytes != 4) {
        fprintf(stderr, "Error: spiXfer returned %d (expected 4).\n", bytes);
        return -1;
    }

    /* Check fault bit (D[16]) */
    if (rx[3] & 0x01) {
        if (rx[3] & 0x04) {
            log_error("MAX31855 fault: short to VCC");
        } else if (rx[3] & 0x02) {
            log_error("MAX31855 fault: short to GND");
        } else if (rx[3] & 0x01) {
            log_error("MAX31855 fault: open circuit");
        } else {
            log_error("MAX31855 fault: unknown");
        }
        return -1;
    }

    /* Assemble 14-bit signed thermocouple value */
    int16_t raw = ((int16_t)(rx[0] << 8) | (uint8_t)rx[1]) >> 2;
    if (raw & 0x2000) {
        raw |= 0xC000;  /* Sign-extend */
    }

    *temperature = (float)raw * 0.25f;
    return 0;
}

/* ----------------------------- Heater PWM -------------------------------- */
static void set_heater_pwm(int duty_cycle)
{
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (gpioPWM(HEATER_GPIO, duty_cycle) < 0) {
        fprintf(stderr, "Warning: gpioPWM failed on GPIO%d.\n", HEATER_GPIO);
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(float temperature, int duty_cycle, float pid_output)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];

    if (t == NULL) {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp) - 1);
        timestamp[sizeof(timestamp) - 1] = '\0';
    } else {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_file, "%s,%.2f,%d,%.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(g_log_file);
}

static void log_error(const char *message)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char timestamp[32];

    if (t == NULL) {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp) - 1);
        timestamp[sizeof(timestamp) - 1] = '\0';
    } else {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(stderr, "%s ERROR: %s\n", timestamp, message);
    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s ERROR: %s\n", timestamp, message);
        fflush(g_log_file);
    }
}

/* ----------------------------- Failsafe ---------------------------------- */
static void failsafe(float temperature)
{
    if (temperature > MAX_TEMPERATURE) {
        log_error("Temperature exceeds maximum safe value");
        set_heater_pwm(0);
    } else if (temperature < MIN_TEMPERATURE) {
        log_error("Temperature below minimum safe value");
        set_heater_pwm(0);
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize hardware */
    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    /* PID state */
    float integral = 0.0f;
    float previous_error = 0.0f;

    printf("PID heater controller started. Target: %.1f °C. Press Ctrl+C to exit.\n",
           TARGET_TEMPERATURE);

    while (g_running) {
        float temperature;

        if (read_max31855(&temperature) != 0) {
            /* Sensor read failed — disable heater for safety */
            set_heater_pwm(0);
            integral = 0.0f;
            previous_error = 0.0f;
            sleep(1);
            continue;
        }

        /* Failsafe */
        failsafe(temperature);

        /* PID calculation */
        float error = TARGET_TEMPERATURE - temperature;
        integral += error;
        float derivative = error - previous_error;
        float output = KP * error + KI * integral + KD * derivative;

        /* Clamp output to PWM range */
        int duty_cycle = (int)(output + 0.5f);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        set_heater_pwm(duty_cycle);
        log_data(temperature, duty_cycle, output);

        previous_error = error;
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

