static void failsafe(float temperature)
{
    if (temperature > MAX_TEMPERATURE) {
        log_error("Temperature exceeds maximum safe value");
        set_heater_pwm(0);
    } else if (temperature < MIN_TEMPERATURE) {
        log_error("Temperature below minimum safe value");
        set_heater_pwm(0);
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize hardware */
    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    /* PID state */
    float integral = 0.0f;
    float previous_error = 0.0f;

    printf("PID heater controller started. Target: %.1f °C. Press Ctrl+C to exit.\n",
           TARGET_TEMPERATURE);

    while (g_running) {
        float temperature;

        if (read_max31855(&temperature) != 0) {
            /* Sensor read failed — disable heater for safety */
            set_heater_pwm(0);
            integral = 0.0f;
            previous_error = 0.0f;
            sleep(1);
            continue;
        }

        /* Failsafe */
        failsafe(temperature);

        /* PID calculation */
        float error = TARGET_TEMPERATURE - temperature;
        integral += error;
        float derivative = error - previous_error;
        float output = KP * error + KI * integral + KD * derivative;

        /* Clamp output to PWM range */
        int duty_cycle = (int)(output + 0.5f);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        set_heater_pwm(duty_cycle);
        log_data(temperature, duty_cycle, output);

        previous_error = error;
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

