#define TEMP_LOW 40.0
#define TEMP_HIGH 70.0
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temperature(float *temperature) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature value\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    *temperature = (float)temp_milli / 1000.0;
    return 0;
}

static int calculate_pwm_duty_cycle(float temperature) {
    if (temperature <= TEMP_LOW) {
        return 0;
    } else if (temperature >= TEMP_HIGH) {
        return 100;
    } else {
        return (int)(((temperature - TEMP_LOW) / (TEMP_HIGH - TEMP_LOW)) * 100.0);
    }
}

static int log_data(float temperature, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

