        perror("Error creating log file");
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(fp, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    fclose(fp);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_cpu_temperature(&temperature) != 0) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int duty_cycle = calculate_pwm_duty_cycle(temperature);

        if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty_cycle);
