    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to turn off fan during shutdown.\n");
    }

    gpioTerminate();

    printf("Fan control stopped.\n");

    return EXIT_SUCCESS;
}

