#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x20
#define SENSOR2_ADDR   0x21
#define LOG_FILE       "flow_log.txt"
#define POLL_INTERVAL  1.0
#define MAX_RETRIES    3
#define READ_LEN       3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8 polynomial 0x31, init 0xFF (datasheet) */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read flow rate from one SLF3S-1300F sensor.
 * Returns 0 on success (flow_rate set), -1 on persistent failure.
 */
static int read_flow_rate(int handle, float *flow_rate)
{
    uint8_t buf[READ_LEN];
    int16_t raw;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int bytes_read = i2cReadDevice(handle, (char *)buf, READ_LEN);
        if (bytes_read == READ_LEN) {
            if (sensirion_crc8(buf, 2) != buf[2]) {
                fprintf(stderr, "CRC mismatch on handle %d (attempt %d)\n",
                        handle, attempt + 1);
                continue;
            }
            raw = (int16_t)((buf[0] << 8) | buf[1]);
            *flow_rate = (float)raw / 100.0f;
            return 0;
        }
        fprintf(stderr, "I2C read error on handle %d (attempt %d): %d\n",
                handle, attempt + 1, bytes_read);
        time_sleep(0.01);
    }
    return -1;
}

static void log_flow_data(float flow1, float flow2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, flow1, flow2);
    } else {
        fprintf(fp, "(unknown time),%.2f,%.2f\n", flow1, flow2);
    }

    if (fclose(fp) != 0)
        perror("fclose(" LOG_FILE ")");
}

static void cleanup(void)
{
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n",
                SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n",
                SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flow sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = read_flow_rate(g_i2c_handle1, &flow1);
        int ok2 = read_flow_rate(g_i2c_handle2, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            log_flow_data(flow1, flow2);
            printf("Flow1: %.2f L/min, Flow2: %.2f L/min\n", flow1, flow2);
        } else {
            fprintf(stderr, "Sensor read failed; skipping log entry.\n");
        }

        time_sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

