/*
 * ADPD144RI Red/IR Photometric Sensor Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADPD144RI SDA -> GPIO2 (I2C bus 1 SDA)
 *   ADPD144RI SCL -> GPIO3 (I2C bus 1 SCL)
 *   ADPD144RI VDD -> 3.3 V
 *   ADPD144RI GND -> GND
 *   LED anode    -> GPIO17 (via 330 Ω resistor)
 *   LED cathode  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o adpd144ri_logger adpd144ri_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./adpd144ri_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define ADPD144RI_ADDR      0x28          /* ADPD144RI default I2C address */
#define LED_GPIO            17
#define IR_THRESHOLD        2000
#define SAMPLE_PERIOD_US    100000        /* 100 ms */
#define LOG_FILE            "adpd144ri_log.txt"

/* ADPD144RI register addresses (from datasheet) */
#define REG_MODE            0x00
#define REG_RED_DATA        0x04
#define REG_IR_DATA         0x08

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers -------------------------------- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(fd, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data_buf[2];

    if (i2cWriteDevice(fd, reg_buf, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) for read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(fd, data_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* ADPD144RI sends MSB first */
    *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* --------------------------- Sensor init -------------------------------- */
static int adpd144ri_init(int fd)
{
    /*
     * Put the sensor into standby mode first so configuration changes
     * take effect before entering continuous mode.
     */
    if (i2c_write_reg(fd, REG_MODE, 0x00) != 0)
        return -1;

    /*
     * Minimal configuration: enable both red and IR channels,
     * continuous mode, no averaging.
     *
     * MODE register (0x00):
     *   [7:6] CH_EN   = 0b11  -> enable red and IR channels
     *   [5:4] AVG     = 0b00  -> no averaging
     *   [3:2] RES     = 0b00  -> 12-bit resolution
     *   [1:0] MODE    = 0b01  -> continuous mode
     *   => 0b110001 = 0x31
     */
    if (i2c_write_reg(fd, REG_MODE, 0x31) != 0)
        return -1;

    /* Allow time for the first conversion to complete */
    gpioDelay(10000); /* 10 ms */
    return 0;
}

/* --------------------------- Logging ------------------------------------ */
static int log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u\n", timestamp, red, ir) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
        /* Non-fatal: data is still in the buffer */
    }

    return 0;
}

/* --------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put sensor in standby mode before closing */
        (void)i2c_write_reg(g_i2c_fd, REG_MODE, 0x00);
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure LED is off */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    g_i2c_fd = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, ADPD144RI_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adpd144ri_init(g_i2c_fd) != 0) {
        fprintf(stderr, "[FATAL] ADPD144RI initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "[FATAL] fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,red,ir\n");
        fflush(g_log_fp);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("ADPD144RI logger started. Logging to %s every 100 ms. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        uint16_t red_value = 0, ir_value = 0;

        if (i2c_read_reg16(g_i2c_fd, REG_RED_DATA, &red_value) != 0) {
            fprintf(stderr, "[ERROR] Failed to read red data; continuing\n");
        } else if (i2c_read_reg16(g_i2c_fd, REG_IR_DATA, &ir_value) != 0) {
            fprintf(stderr, "[ERROR] Failed to read IR data; continuing\n");
        } else {
            if (log_data(g_log_fp, red_value, ir_value) != 0) {
                fprintf(stderr, "[ERROR] Logging failed; continuing\n");
            }

            if (ir_value > IR_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

