/*
 * Raspberry Pi Zero W – SLF3S-4000B Liquid Flow Sensor Monitor
 *
 * Wiring:
 *   SLF3S-4000B SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SLF3S-4000B SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SLF3S-4000B VDD  -> 3.3 V
 *   SLF3S-4000B GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x20
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_PERIOD  1000000   /* microseconds (1 second) */

/* Sensirion CRC-8 polynomial: 0x31, initial value: 0xFF */
#define CRC8_POLY      0x31
#define CRC8_INIT      0xFF

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion style)                                              */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "[ERROR] open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read 3 bytes from the SLF3S-4000B:
 *   [MSB, LSB, CRC]
 * Returns 0 on success, -1 on error.
 */
static int read_flow_rate(int fd, float *flow_rate)
{
    uint8_t buf[3];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[ERROR] read() returned %zd: %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* Validate CRC */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch (calc=0x%02X recv=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    /* Convert raw 16-bit signed value to flow rate (uL/min) */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    g_log_fp = fopen(path, "a");
    if (!g_log_fp) {
        fprintf(stderr, "[ERROR] fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }
    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,flow_rate_uL_min\n");
        fflush(g_log_fp);
    }
    return 0;
}

static void log_data(float flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "[ERROR] localtime_r(): %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, flow_rate) < 0) {
        fprintf(stderr, "[ERROR] fprintf(): %s\n", strerror(errno));
        return;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "[WARN] fflush(): %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = i2c_open(I2C_BUS, SLF3S_ADDR);
    if (g_i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (log_open(LOG_FILE) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring SLF3S-4000B flow sensor on %s (addr 0x%02X)...\n",
           I2C_BUS, SLF3S_ADDR);
    printf("Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD / 1000);

    /* Main sampling loop */
    while (g_running) {
        float flow_rate;

        if (read_flow_rate(g_i2c_fd, &flow_rate) == 0) {
            log_data(flow_rate);
            printf("Flow rate: %.2f uL/min\n", flow_rate);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

