/*
 * Raspberry Pi Zero W – Honeywell MICS-VZ-89TE VOC Sensor Logger
 *
 * Wiring:
 *   MICS-VZ-89TE VCC  -> Pi 3V3  (Pin 1)
 *   MICS-VZ-89TE GND  -> Pi GND  (Pin 9)
 *   MICS-VZ-89TE SDA  -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *   MICS-VZ-89TE SCL  -> Pi GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o air_quality air_quality.c -lpigpio -lrt
 * Run:
 *   sudo ./air_quality
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define I2C_ADDR            0x61          /* MICS-VZ-89TE default I2C address */
#define LOG_FILE            "air_quality_log.csv"
#define SAMPLE_INTERVAL_S   5

/* MICS-VZ-89TE register addresses (16-bit, big-endian on the bus) */
#define REG_STATUS          0x0000
#define REG_TVOC_MSB        0x0002
#define REG_TVOC_LSB        0x0003
#define REG_ECO2_MSB        0x0004
#define REG_ECO2_LSB        0x0005
#define REG_CONFIG          0x0006
#define REG_RESET           0x0007

/* STATUS register bits */
#define STATUS_DATA_READY   0x0001

/* CONFIG register bits */
#define CONFIG_MODE_CONT    0x0001        /* Continuous measurement mode */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  i2c_write_reg16(int handle, uint16_t reg, uint16_t value);
static int  i2c_read_reg16(int handle, uint16_t reg, uint16_t *value);
static int  read_sensor_data(int handle, uint16_t *tvoc_ppb, uint16_t *eco2_ppm);
static int  calculate_iaq_index(uint16_t tvoc_ppb, uint16_t eco2_ppm);
static int  log_data(FILE *fp, uint16_t iaq, uint16_t tvoc_ppb, uint16_t eco2_ppm);
static void cleanup(void);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C register helpers ------------------------- */

/* Write a 16-bit value to a 16-bit register address (big-endian on the bus). */
static int i2c_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (char)((reg >> 8) & 0xFF);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)((value >> 8) & 0xFF);
    buf[3] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from a 16-bit register address (big-endian on the bus). */
static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char reg_buf[2];
    char data_buf[2];

    reg_buf[0] = (char)((reg >> 8) & 0xFF);
    reg_buf[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select) failed for reg 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed for reg 0x%04X\n", reg);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* --------------------------- Sensor read & IAQ --------------------------- */

/*
 * Read TVOC (ppb) and eCO2 (ppm) from the MICS-VZ-89TE.
 * Returns 0 on success, -1 on I2C error, -2 if data is not ready.
 */
static int read_sensor_data(int handle, uint16_t *tvoc_ppb, uint16_t *eco2_ppm)
{
    uint16_t status;

    if (i2c_read_reg16(handle, REG_STATUS, &status) != 0)
        return -1;

    if ((status & STATUS_DATA_READY) == 0)
        return -2;                       /* Data not ready yet */

    if (i2c_read_reg16(handle, REG_TVOC_MSB, tvoc_ppb) != 0)
        return -1;
    if (i2c_read_reg16(handle, REG_ECO2_MSB, eco2_ppm) != 0)
        return -1;

    return 0;
}

/*
 * Simple placeholder IAQ index calculation.
 * Replace with a real calibration curve once the sensor is calibrated.
 */
static int calculate_iaq_index(uint16_t tvoc_ppb, uint16_t eco2_ppm)
{
    (void)tvoc_ppb;
    (void)eco2_ppm;
    return 50;
}

/* ------------------------------- Logging --------------------------------- */

static int log_data(FILE *fp, uint16_t iaq, uint16_t tvoc_ppb, uint16_t eco2_ppm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%u,%u,%u\n", timestamp, iaq, tvoc_ppb, eco2_ppm) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    uint16_t tvoc_ppb = 0, eco2_ppm = 0;
    int      iaq;
    int      rc;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,IAQ,TVOC_ppb,eCO2_ppm\n");
        fflush(g_log_file);
    }

    /* --- Configure sensor: continuous measurement mode --- */
    if (i2c_write_reg16(g_i2c_handle, REG_CONFIG, CONFIG_MODE_CONT) != 0) {
        fprintf(stderr, "[FATAL] Failed to configure MICS-VZ-89TE\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("MICS-VZ-89TE logger started. Logging to '%s' every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        rc = read_sensor_data(g_i2c_handle, &tvoc_ppb, &eco2_ppm);

        if (rc == 0) {
            iaq = calculate_iaq_index(tvoc_ppb, eco2_ppm);
            if (log_data(g_log_file, iaq, tvoc_ppb, eco2_ppm) != 0) {
                fprintf(stderr, "[ERROR] Logging failed; continuing.\n");
            }
            printf("IAQ: %d, TVOC: %u ppb, eCO2: %u ppm\n", iaq, tvoc_ppb, eco2_ppm);
        } else if (rc == -1) {
            fprintf(stderr, "[ERROR] I2C communication failure; continuing.\n");
        } else {
            /* rc == -2: data not ready yet – just wait */
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

