    printf("Tamper detection started on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    struct timespec last_alert_time;
    clock_gettime(CLOCK_MONOTONIC, &last_alert_time);

    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        if (value == 1) {
            /* Sensor is touched (HIGH) */
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            double elapsed = elapsed_seconds(&last_alert_time, &now);
            if (elapsed < 0.0) {
