/*
 * Tamper detection using a SainSmart TTP223B capacitive touch sensor.
 *
 * Wiring:
 *   TTP223B VCC  -> 3.3 V (pin 1)
 *   TTP223B GND  -> GND  (pin 9)
 *   TTP223B OUT  -> GPIO17 (pin 11, BCM 17)
 *
 * The TTP223B OUT line is HIGH while touched and LOW when released.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tamper_detect tamper_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"   /* BCM GPIO controller on Pi 5 */
#define GPIO_LINE_OFFSET 17            /* BCM 17 */
#define CONSUMER_NAME    "ttp223_tamper"

#define POLL_INTERVAL_MS 100
#define ALERT_THRESHOLD_S 5

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Sleep for the given number of milliseconds, interruptible by signals.
 * Returns 0 on success, -1 on error (errno preserved).
 */
static int sleep_ms(unsigned int ms)
{
    struct timespec req = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    struct timespec rem;

    while (nanosleep(&req, &rem) == -1) {
        if (errno != EINTR) {
            return -1;
        }
        if (!g_running) {
            return -1;
        }
        req = rem;
    }
    return 0;
}

/*
 * Compute the elapsed time between two CLOCK_MONOTONIC timestamps.
 * Returns the difference in seconds, or a negative value on error.
 */
static double elapsed_seconds(const struct timespec *start,
                              const struct timespec *end)
{
    if (start == NULL || end == NULL) {
        return -1.0;
    }
    return (double)(end->tv_sec  - start->tv_sec)
         + (double)(end->tv_nsec - start->tv_nsec) / 1.0e9;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() == -1) {
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request the line as input with the consumer label */
    if (gpiod_line_request_input(line, CONSUMER_NAME) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Tamper detection started on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    struct timespec last_alert_time;
    clock_gettime(CLOCK_MONOTONIC, &last_alert_time);

    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        if (value == 1) {
            /* Sensor is touched (HIGH) */
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);

            double elapsed = elapsed_seconds(&last_alert_time, &now);
            if (elapsed < 0.0) {
                fprintf(stderr, "Error computing elapsed time: %s\n",
                        strerror(errno));
                goto cleanup;
            }

            if (elapsed >= (double)ALERT_THRESHOLD_S) {
                printf("Intrusion alert! Sensor touched for > %d seconds.\n",
                       ALERT_THRESHOLD_S);
                fflush(stdout);
                last_alert_time = now;
            }
        }

        if (sleep_ms(POLL_INTERVAL_MS) == -1) {
            if (errno == EINTR) {
                /* Signal received — check g_running to exit cleanly */
                if (!g_running) {
                    break;
                }
                continue;
            }
            fprintf(stderr, "Error during sleep: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

