#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define BITS_PER_SAMPLE 16
#define BUFFER_SIZE 4096

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2s(int *fd) {
    *fd = open(I2S_DEVICE, O_RDONLY);
    if (*fd < 0) {
        fprintf(stderr, "Error opening I2S device %s: %s\n", I2S_DEVICE, strerror(errno));
        return -1;
    }

    int format = AFMT_S16_LE;
    if (ioctl(*fd, SNDCTL_DSP_SETFMT, &format) == -1) {
        fprintf(stderr, "Error setting I2S format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    int channels = NUM_CHANNELS;
    if (ioctl(*fd, SNDCTL_DSP_CHANNELS, &channels) == -1) {
        fprintf(stderr, "Error setting I2S channels: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(*fd, SNDCTL_DSP_SPEED, &rate) == -1) {
        fprintf(stderr, "Error setting I2S sample rate: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_LINE);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line, "i2s_mic_select", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

static int select_left_channel(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int select_right_channel(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_audio_data(int fd, int16_t *buffer, size_t size) {
    ssize_t bytes_read = read(fd, buffer, size * sizeof(int16_t));
    if (bytes_read == -1) {
        fprintf(stderr, "Error reading audio data: %s\n", strerror(errno));
        return -1;
    }
    if (bytes_read == 0) {
        fprintf(stderr, "End of audio stream reached.\n");
        return -1;
    }
    return 0;
}

static int write_audio_data(const char *filename, const int16_t *buffer, size_t size) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t elements_written = fwrite(buffer, sizeof(int16_t), size, fp);
    if (elements_written != size) {
        fprintf(stderr, "Error writing audio data to file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int i2s_fd = -1;
    struct gpiod_chip *gpio_chip = NULL;
    struct gpiod_line *gpio_line = NULL;
    int16_t *audio_buffer = NULL;
    int ret_code = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    audio_buffer = (int16_t *)malloc(BUFFER_SIZE * sizeof(int16_t));
    if (!audio_buffer) {
        fprintf(stderr, "Error allocating memory for audio buffer: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2s(&i2s_fd) != 0) {
        goto cleanup;
    }

    if (init_gpio(&gpio_chip, &gpio_line) != 0) {
        goto cleanup;
    }

    if (select_left_channel(gpio_line) != 0) {
        goto cleanup;
    }

    printf("Capturing audio from left channel...\n");
    if (write_audio_data("audio_capture.pcm", audio_buffer, BUFFER_SIZE) != 0) {
        goto cleanup;
    }

    while (running) {
        if (read_audio_data(i2s_fd, audio_buffer, BUFFER_SIZE) != 0) {
            break;
        }

        if (write_audio_data("audio_capture.pcm", audio_buffer, BUFFER_SIZE) != 0) {
            break;
        }
    }

    ret_code = EXIT_SUCCESS;

cleanup:
    if (i2s_fd >= 0) {
        close(i2s_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (audio_buffer) {
        free(audio_buffer);
    }

    printf("Audio capture stopped.\n");
    return ret_code;
}

