/*
 * Flame sensor monitor with PWM fan control on Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - SainSmart IR Flame Sensor Module (LM393 comparator, IR photodiode)
 *     DO  -> GPIO4  (BCM)
 *     VCC -> 3.3 V
 *     GND -> GND
 *   - 4-wire PC fan module driven via hardware PWM on GPIO18 (BCM)
 *     IN1 -> GPIO18 (BCM)
 *     IN2 -> GND
 *     VCC -> 5 V (external supply recommended; 3.3 V is acceptable if
 *              the fan module has its own 5 V supply)
 *     GND -> GND
 *
 * Behavior:
 *   Polls GPIO4 every 50 ms.  On a LOW reading (flame detected) the fan
 *   is driven at 100 Hz for 50 ms, then stopped.  A timestamped event
 *   is appended to flame_log.txt.  SIGINT / SIGTERM cleanly stop the
 *   fan, release GPIO resources, and exit.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lpigpio -lrt
 *   Run as root (pigpio requires root for hardware PWM on GPIO18).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN          18

#define PWM_FREQUENCY    100          /* Hz */
#define PWM_DUTY_CYCLE   128          /* 50 % of 255 */
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_US 50000        /* 50 ms */
#define SENSOR_TIMEOUT_S 5

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log_file, "%s: %s\n", ts, event);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                FLAME_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n",
                FAN_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure fan is off at startup */
    if (gpioPWM(FAN_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM on GPIO%d.\n",
                FAN_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Stop fan and release PWM */
    gpioPWM(FAN_PIN, 0);
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Fan control                                                         */
/* ------------------------------------------------------------------ */
static int start_fan(void)
{
    if (gpioPWM(FAN_PIN, PWM_DUTY_CYCLE) != 0) {
        fprintf(stderr, "Error: failed to start PWM on GPIO%d.\n",
                FAN_PIN);
        return -1;
    }
    return 0;
}

static void stop_fan(void)
{
    gpioPWM(FAN_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open log file in append mode */
    g_log_file = fopen("flame_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening flame_log.txt");
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

