/*
 * AWR1642 mmWave radar SPI frame capture for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   AWR1642 SPI0 MOSI  -> GPIO10 (BCM)
 *   AWR1642 SPI0 MISO  -> GPIO9  (BCM)
 *   AWR1642 SPI0 SCLK  -> GPIO11 (BCM)
 *   AWR1642 SPI0 CS    -> GPIO8  (BCM)
 *   AWR1642 Gpio23    -> GPIO23 (BCM)  (Hardware frame trigger)
 *   AWR1642 Gpio24    -> GPIO24 (BCM)  (Data ready interrupt)
 *
 * Build: gcc -O2 -Wall -o radar_capture radar_capture.c -lpigpio -lrt
 * Run:   sudo ./radar_capture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL        0          /* CE0 / GPIO8 */
#define SPI_SPEED          1000000    /* 1 MHz */
#define SPI_MODE           0          /* SPI mode 0 (CPOL=0, CPHA=0) */
#define SPI_BITS           8          /* 8-bit words */

#define FRAME_TRIGGER_PIN  23         /* BCM 23 - hardware frame trigger */
#define DATA_READY_PIN     24         /* BCM 24 - data ready interrupt */

#define LOG_FILE_NAME      "radar_data.bin"
#define MAGIC_NUMBER       4144       /* TI mmWave SDK magic number */
#define FRAME_PERIOD_US    100000     /* 100 ms */
#define HEATMAP_BYTES      32768      /* 64 chirps * 256 samples * 2 bytes */

/* ----------------------------- Data Structures ----------------------------- */
typedef struct {
    uint32_t magic_number;
    uint8_t  timestamp[8];
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t num_chirps;
    uint32_t num_samples;
} __attribute__((packed)) radar_config_t;

typedef struct {
    uint8_t  timestamp[8];
    uint32_t frame_number;
} __attribute__((packed)) frame_header_t;

/* ----------------------------- Globals ----------------------------------- */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  initialize_spi(void);
static int  initialize_gpio(void);
static int  configure_sensor(void);
static int  read_frame(uint8_t *buffer, int len);
static int  log_frame(const uint8_t *buffer, int len);
static void cleanup(void);

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ----------------------------- SPI Initialization -------------------------- */
static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n",
                SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

/* ----------------------------- GPIO Initialization ------------------------- */
static int initialize_gpio(void) {
    if (gpioSetMode(FRAME_TRIGGER_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", FRAME_TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", DATA_READY_PIN);
        return -1;
    }
    /* Enable internal pull-downs so the lines are defined when idle */
    if (gpioSetPullUpDown(FRAME_TRIGGER_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error setting pull-down on GPIO %d\n", FRAME_TRIGGER_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error setting pull-down on GPIO %d\n", DATA_READY_PIN);
        return -1;
    }
    return 0;
}

/* ----------------------------- Sensor Configuration ----------------------- */
static int configure_sensor(void) {
    /*
     * AWR1642 configuration via SPI is not part of the pigpio SPI API.
     * For a full implementation, use the TI mmWave SDK CLI or the
     * mmWave SDK C/C++ API.  This function is a placeholder that
     * demonstrates the required configuration structure.
     */
    radar_config_t config;
    config.magic_number    = MAGIC_NUMBER;
    config.start_frequency = 77000000;  /* 77 GHz */
    config.end_frequency   = 79000000;  /* 79 GHz */
    config.num_chirps      = 64;
    config.num_samples     = 256;

    /*
     * In a real implementation, this would be a full-duplex SPI transfer
     * of the configuration struct to the AWR1642.  For brevity, we
     * simulate the transfer by writing the magic number to the log file.
     */
    if (fwrite(&config, sizeof(config), 1, log_file) != 1) {
        fprintf(stderr, "Error writing configuration to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

/* ----------------------------- Frame Read --------------------------------- */
static int read_frame(uint8_t *buffer, int len) {
    /*
     * AWR1642 range-Doppler heatmap data is typically streamed via SPI.
     * This function simulates a full-duplex transfer of len bytes.
     * In a real implementation, the AWR1642 would assert CS, send the
     * command to read the heatmap, then clock out the data.
     */
    if (spiXfer(spi_handle, (char *)buffer, (char *)buffer, len) != len) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }
    return 0;
}

/* ----------------------------- Frame Logging ------------------------------ */
static int log_frame(const uint8_t *buffer, int len) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    frame_header_t header;
    memcpy(header.timestamp, &ts, sizeof(ts));
    header.frame_number = 0;  /* Placeholder; real implementation would increment */

    if (fwrite(&header, sizeof(header), 1, log_file) != 1) {
        fprintf(stderr, "Error writing frame header\n");
        return -1;
    }
    if (fwrite(buffer, 1, len, log_file) != (size_t)len) {
        fprintf(stderr, "Error writing frame data\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main --------------------------------------- */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE_NAME, "wb");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure sensor */
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Radar capture started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        /*
         * AWR1642 range-Doppler heatmap data is typically streamed via SPI.
         * This implementation simulates a full-duplex transfer of HEATMAP_BYTES.
         */
        uint8_t *buffer = malloc(HEATMAP_BYTES);
        if (buffer == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        if (read_frame(buffer, HEATMAP_BYTES) == 0) {
            if (log_frame(buffer, HEATMAP_BYTES) != 0) {
                fprintf(stderr, "Frame logging failed\n");
            }
        } else {
            fprintf(stderr, "Frame read failed\n");
        }

        free(buffer);

        /* Wait for next frame period */
        gpioDelay(FRAME_PERIOD_US);
    }

    printf("\nRadar capture stopped.\n");
    cleanup();
    return EXIT_SUCCESS;
}

