        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE_NAME, "wb");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure sensor */
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Radar capture started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        /*
         * AWR1642 range-Doppler heatmap data is typically streamed via SPI.
         * This implementation simulates a full-duplex transfer of HEATMAP_BYTES.
         */
        uint8_t *buffer = malloc(HEATMAP_BYTES);
        if (buffer == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        if (read_frame(buffer, HEATMAP_BYTES) == 0) {
            if (log_frame(buffer, HEATMAP_BYTES) != 0) {
                fprintf(stderr, "Frame logging failed\n");
            }
        } else {
            fprintf(stderr, "Frame read failed\n");
        }

        free(buffer);

        /* Wait for next frame period */
        gpioDelay(FRAME_PERIOD_US);
    }

    printf("\nRadar capture stopped.\n");
    cleanup();
    return EXIT_SUCCESS;
}

