/*
 * KY-026 Flame Sensor Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (Pin 1)
 *   KY-026 GND  -> GND  (Pin 9)
 *   KY-026 OUT  -> GPIO20 (BCM 20, Pin 38)
 *
 * Behavior:
 *   Polls GPIO20 every 100 ms.  On a state change, appends an ISO-8601
 *   UTC timestamp and the new state ("FLAME_DETECTED" or "FLAME_CLEARED")
 *   to flame_log.txt.  Handles SIGINT/SIGTERM for graceful shutdown.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flame_logger flame_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 20          /* BCM 20 */
#define LOG_FILE         "flame_log.txt"
#define POLL_INTERVAL_US 100000      /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_utc;

    if (time(&rawtime) == (time_t)-1) {
        perror("time()");
        return -1;
    }

    if (gmtime_r(&rawtime, &tm_utc) == NULL) {
        perror("gmtime_r()");
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed: buffer too small\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_flame_event(FILE *fp, const char *timestamp, int flame_detected)
{
    const char *state_str = flame_detected ? "FLAME_DETECTED" : "FLAME_CLEARED";

    if (fprintf(fp, "%s - %s\n", timestamp, state_str) < 0) {
        perror("fprintf()");
        return -1;
    }

    if (fflush(fp) == EOF) {
        perror("fflush()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int prev_state = -1;          /* unknown initial state */
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    if (install_signal_handlers() != 0)
        goto cleanup;

    /* ---- Open log file ---- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(" GPIO_CHIP_NAME ")");
        goto cleanup;
    }

    /* ---- Get GPIO line ---- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line()");
        goto cleanup;
    }

    /* ---- Request line as input ---- */
    if (gpiod_line_request_input(line, "ky026-flame-sensor") < 0) {
        perror("gpiod_line_request_input()");
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO%d.  Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value()");
            goto cleanup;
        }

        /* KY-026 OUT is active-high: 1 = flame detected */
        int flame_detected = (val == 1);

        if (flame_detected != prev_state) {
            char ts[32];
            if (get_iso8601_timestamp(ts, sizeof(ts)) == 0) {
                if (log_flame_event(log_fp, ts, flame_detected) != 0)
                    goto cleanup;
            }
            prev_state = flame_detected;
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);
    if (log_fp != NULL)
        fclose(log_fp);

    return ret;
}

