/*
 * OPT3001 Ambient Light Sensor Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3001 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   OPT3001 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   OPT3001 VDD  -> 3.3 V
 *   OPT3001 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o opt3001_logger opt3001_logger.c -lm
 *
 * Run:
 *   ./opt3001_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

/* ---- OPT3001 constants (from TI datasheet) ---- */
#define OPT3001_I2C_ADDR        0x44
#define OPT3001_REG_RESULT      0x00
#define OPT3001_REG_CONFIG      0x01

/*
 * Config register (16-bit, big-endian on the bus):
 *   [15:12] Range number (0x0 = auto, 0x1 = 4096 lux, 0x2 = 2048 lux, ...)
 *   [11:10] Conversion time (0x0 = 0.5 ms, 0x1 = 10 ms, 0x2 = 80 ms, 0x3 = 160 ms)
 *   [9]     Flag bit (0 = no flag)
 *   [8]     Latch (0 = no latch)
 *   [7:6]   Mode (0x0 = continuous)
 *   [5:4]   Polarity (0x0 = active low)
 *   [3:0]   Mask exponent (0x0 = no mask)
 */
#define OPT3001_CFG_AUTO_RANGE  0x0000   /* auto-range, 0.5 ms conversion */
#define OPT3001_CFG_CONTINUOUS 0x0000   /* continuous mode */

/* Conversion time for 0.5 ms is ~100 ms; use 150 ms to be safe */
#define CONVERSION_DELAY_US     150000
#define SAMPLE_INTERVAL_US     100000  /* 100 ms between samples */
#define MAX_RETRIES            3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an OPT3001 register (big-endian on the bus). */
static int opt3001_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an OPT3001 register (big-endian on the bus). */
static int opt3001_read_reg(int handle, uint8_t reg, uint16_t *value)
{
    char reg_buf[1] = { (char)reg };
    char data_buf[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) for read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the OPT3001 for continuous conversion, auto-range.       */
static int opt3001_configure(int handle)
{
    uint16_t config = OPT3001_CFG_AUTO_RANGE | OPT3001_CFG_CONTINUOUS;

    if (opt3001_write_reg(handle, OPT3001_REG_CONFIG, config) != 0) {
        fprintf(stderr, "[ERROR] Failed to write OPT3001 config register.\n");
        return -1;
    }

    /* Allow the first conversion to complete (0.5 ms conversion time). */
    gpioDelay(CONVERSION_DELAY_US);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read lux from the OPT3001. Returns 0 on success, -1 on failure.     */
static int opt3001_read_lux(int handle, float *lux_out)
{
    uint16_t raw;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (opt3001_read_reg(handle, OPT3001_REG_RESULT, &raw) == 0) {
            break;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(10000); /* 10 ms backoff before retry */
        }
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "[ERROR] OPT3001 read failed after %d retries.\n",
                MAX_RETRIES);
        return -1;
    }

    /*
     * Result register (16-bit):
     *   [15:12] Exponent (0x0 = 0.01 lux, 0x1 = 0.0001 lux, ...)
     *   [11:0]  Mantissa
     */
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;

    *lux_out = (float)mantissa * powf(10.0f, (float)exponent - 12.0f);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped lux reading to the log file.                  */
static int log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed.\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "[ERROR] fprintf() to log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[WARN] fflush() failed: %s\n", strerror(errno));
        /* Non-fatal: data is in the buffer */
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the OPT3001 address */
    g_i2c_handle = i2cOpen(1, OPT3001_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                OPT3001_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence by reading the config register */
    uint16_t cfg_check;
    if (opt3001_read_reg(g_i2c_handle, OPT3001_REG_CONFIG, &cfg_check) != 0) {
        fprintf(stderr, "[FATAL] OPT3001 not responding at address 0x%02X.\n",
                OPT3001_I2C_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure the sensor */
    if (opt3001_configure(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] OPT3001 configuration failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    g_log_file = fopen("light_data.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open light_data.txt: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("OPT3001 logger started. Logging to light_data.txt. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float lux;

        if (opt3001_read_lux(g_i2c_handle, &lux) == 0) {
            if (log_data(g_log_file, lux) != 0) {
                fprintf(stderr, "[WARN] Logging failed for this sample.\n");
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        uint32_t remaining = SAMPLE_INTERVAL_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = (remaining > 10000) ? 10000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

