/*
 * Flame detection sensor reader for Raspberry Pi 3 Model B+
 * Sensor : SainSmart IR Flame Detection Module (DOUT -> GPIO17, active-low)
 * Library: libgpiod v2 (modern GPIO character-device API)
 *
 * Build  : gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 * Run    : sudo ./flame_detect   (root needed for /dev/gpiochip0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17 */
#define POLL_INTERVAL_S  1

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return;
    }
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("%s", buf);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_request_config req_cfg;
    struct gpiod_line_settings *settings = NULL;
    int ret;

    /* ---- Signal handlers ---- */
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get the line ---- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* ---- Request line as input with pull-up ---- */
    memset(&req_cfg, 0, sizeof(req_cfg));
    req_cfg.consumer = "flame-detect";
    req_cfg.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Failed to allocate line settings: %s\n",
                strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-up bias: %s\n",
                strerror(errno));
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(line, &req_cfg, settings);
    if (ret != 0) {
        fprintf(stderr, "Failed to request line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_line_settings_free(settings);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_settings_free(settings);
    settings = NULL;

    printf("Flame detection started on GPIO%d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        print_timestamp();
        printf(" Flame Detected: %s\n", value == 0 ? "YES" : "NO");
        fflush(stdout);

        sleep(POLL_INTERVAL_S);
    }

    /* ---- Cleanup ---- */
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

