#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <stdbool.h>

#include <ttp226.h>

#define NUM_CHANNELS 8
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long ms = ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;
    printf("[+%ld ms] ", ms);
}

int main(void)
{
    struct ttp226_chip *chip = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize the TTP226 driver library */
    chip = ttp226_chip_open();
    if (chip == NULL) {
        fprintf(stderr, "Error: ttp226_chip_open() failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure the eight sensor output pins as inputs with pull-down resistors */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        ret = ttp226_channel_configure(chip, i, TTP226_CHANNEL_INPUT);
        if (ret != 0) {
            fprintf(stderr, "Error: ttp226_channel_configure(channel %d) failed: %s\n",
                    i, strerror(errno));
            ttp226_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        print_timestamp();

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = ttp226_channel_read(chip, i);
            if (value < 0) {
                fprintf(stderr, "Error: ttp226_channel_read(channel %d) failed: %s\n",
                        i, strerror(errno));
                ttp226_chip_close(chip);
                return EXIT_FAILURE;
            }
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");
        fflush(stdout);

        /* Sleep for the sampling interval, but wake early if a signal arrives */
        for (int remaining = SAMPLE_INTERVAL_US; remaining > 0 && g_running; ) {
            remaining = usleep(remaining);
        }
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    ttp226_chip_close(chip);
    printf("Done.\n");
    return EXIT_SUCCESS;
}

