code:
/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   Sensor CH1 -> GPIO 2  (physical pin 3)
 *   Sensor CH2 -> GPIO 3  (physical pin 5)
 *   Sensor CH3 -> GPIO 4  (physical pin 7)
 *   Sensor CH4 -> GPIO 17 (physical pin 11)
 *   Sensor CH5 -> GPIO 27 (physical pin 13)
 *   Sensor CH6 -> GPIO 22 (physical pin 15)
 *   Sensor CH7 -> GPIO 10 (physical pin 19)
 *   Sensor CH8 -> GPIO 9  (physical pin 21)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int channel_pins[NUM_CHANNELS] = {
    2,  3,  4, 17, 27, 22, 10,  9
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the default gpiochip (gpiochip0 on Pi 4) --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure each line as input with bias disabled --- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Error: failed to allocate line settings: %s\n",
                strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_DISABLED);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Error: failed to allocate line config: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, channel_pins,
                                            NUM_CHANNELS, settings) != 0) {
        fprintf(stderr, "Error: failed to add line settings: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- Request the lines --- */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Error: failed to allocate request config: %s\n",
                strerror(errno));
        goto cleanup;
    }

    gpiod_request_config_set_consumer(req_cfg, "ttp226-reader");

    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Error: failed to request GPIO lines: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    printf("Timestamp,CH1,CH2,CH3,CH4,CH5,CH6,CH7,CH8\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (program_running) {
        int values[NUM_CHANNELS];
        char timestamp[32];

        if (gpiod_line_request_get_values(request, values) != 0) {
            fprintf(stderr, "Error: failed to read GPIO values: %s\n",
                    strerror(errno));
            break;
        }

        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
               timestamp,
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL) {
        gpiod_line_request_release(request);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

