/*
 * Omron D7E-1 tilt sensor reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   D7E-1 VCC  -> 3.3 V (pin 1)
 *   D7E-1 GND  -> GND  (pin 9)
 *   D7E-1 OUT  -> GPIO4 (pin 7, BCM 4)
 *
 * The internal pull-up resistor is enabled so the pin reads HIGH when the
 * sensor is not tilted and LOW when tilted.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tilt_sensor tilt_sensor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 4          /* BCM 4 */
#define POLL_INTERVAL_US 100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;
    int prev_value = -1;   /* force initial print */

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM 4 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input with internal pull-up */
    ret = gpiod_line_request_input_flags(line, "tilt-sensor",
                                        GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret != 0) {
        perror("gpiod_line_request_input_flags");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO%d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (value != prev_value) {
            printf("%s\n", value == 0 ? "Tilted" : "Not Tilted");
            fflush(stdout);
            prev_value = value;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

