#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Si1145 I2C address (ADDR pin tied to GND) */
#define SI1145_ADDR 0x60

/* Si1145 register addresses */
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_REV_ID 0x01
#define SI1145_REG_SEQ_ID 0x02
#define SI1145_REG_INT_CFG 0x03
#define SI1145_REG_IRQ_ENABLE 0x04
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UVINDEX0 0x2C
#define SI1145_REG_UVINDEX1 0x2D
#define SI1145_REG_COMMAND 0x18

/* Si1145 command codes */
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_PSALS_FORCE 0x07

/* Expected part ID for Si1145 */
#define SI1145_PART_ID 0x45

/* Global variables for signal handling and cleanup */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Function prototypes */
static int si1145_write_reg(int handle, uint8_t reg, uint8_t value);
static int si1145_read_reg(int handle, uint8_t reg, uint8_t *value);
static int si1145_init(int handle);
static int si1145_read_uv_index(int handle, float *uv_index);
static int si1145_read_als_visible(int handle, uint16_t *als_visible);
static int log_data(FILE *fp, float uv_index, uint16_t als_visible);
static void signal_handler(int signal);
static void cleanup(void);

/* Write a single byte to a Si1145 register */
static int si1145_write_reg(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %s\n",
                value, reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from a Si1145 register */
static int si1145_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

/* Initialize the Si1145 sensor */
static int si1145_init(int handle) {
    uint8_t part_id;

    /* Verify sensor presence by reading PART_ID */
    if (si1145_read_reg(handle, SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID. Sensor may be absent or bus error.\n");
        return -1;
    }

    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X). Wrong sensor?\n",
                part_id, SI1145_PART_ID);
        return -1;
    }

    printf("Si1145 detected (PART_ID = 0x%02X)\n", part_id);

    /* Reset the sensor */
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset Si1145.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for reset to complete */

    /* Write HW_KEY to enable the device */
    if (si1145_write_reg(handle, SI1145_REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "Failed to write HW_KEY.\n");
        return -1;
    }

    /* Set measurement rate to 0 (manual mode) */
    if (si1145_write_reg(handle, SI1145_REG_MEAS_RATE0, 0x00) != 0) {
        fprintf(stderr, "Failed to set MEAS_RATE0.\n");
        return -1;
    }
    if (si1145_write_reg(handle, SI1145_REG_MEAS_RATE1, 0x00) != 0) {
        fprintf(stderr, "Failed to set MEAS_RATE1.\n");
        return -1;
    }

    /* Clear any pending interrupts */
    if (si1145_write_reg(handle, SI1145_REG_IRQ_ENABLE, 0x00) != 0) {
        fprintf(stderr, "Failed to clear IRQ_ENABLE.\n");
        return -1;
    }

    /* Set interrupt configuration (no interrupts) */
    if (si1145_write_reg(handle, SI1145_REG_INT_CFG, 0x00) != 0) {
        fprintf(stderr, "Failed to set INT_CFG.\n");
        return -1;
    }

    return 0;
}

/* Read UV index from the Si1145 sensor */
static int si1145_read_uv_index(int handle, float *uv_index) {
    uint8_t uv_data0, uv_data1;

    /* Trigger a UV index measurement */
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PSALS_FORCE) != 0) {
        fprintf(stderr, "Failed to trigger UV index measurement.\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms delay for measurement to complete */

    /* Read UV index data */
    if (si1145_read_reg(handle, SI1145_REG_UVINDEX0, &uv_data0) != 0) {
        fprintf(stderr, "Failed to read UVINDEX0.\n");
        return -1;
    }
    if (si1145_read_reg(handle, SI1145_REG_UVINDEX1, &uv_data1) != 0) {
        fprintf(stderr, "Failed to read UVINDEX1.\n");
        return -1;
    }

    *uv_index = (float)((uv_data1 << 8) | uv_data0) / 100.0f;

    return 0;
}

/* Read visible ambient light from the Si1145 sensor */
static int si1145_read_als_visible(int handle, uint16_t *als_visible) {
    uint8_t als_vis_data0, als_vis_data1;

    /* Trigger an ALS visible light measurement */
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PSALS_FORCE) != 0) {
        fprintf(stderr, "Failed to trigger ALS visible light measurement.\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms delay for measurement to complete */

    /* Read ALS visible light data */
    if (si1145_read_reg(handle, SI1145_REG_ALS_VIS_DATA0, &als_vis_data0) != 0) {
        fprintf(stderr, "Failed to read ALS_VIS_DATA0.\n");
        return -1;
    }
    if (si1145_read_reg(handle, SI1145_REG_ALS_VIS_DATA1, &als_vis_data1) != 0) {
        fprintf(stderr, "Failed to read ALS_VIS_DATA1.\n");
        return -1;
    }

    *als_visible = (uint16_t)((als_vis_data1 << 8) | als_vis_data0);

    return 0;
}

/* Log data to a CSV file */
static int log_data(FILE *fp, float uv_index, uint16_t als_visible) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%u\n", timestamp, uv_index, als_visible) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    float uv_index;
    uint16_t als_visible;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x60 */
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %s\n",
                SI1145_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si1145 sensor */
    if (si1145_init(i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialization failed. Check wiring and sensor presence.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is newly created */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
        fflush(log_file);
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (running) {
        /* Read UV index */
        if (si1145_read_uv_index(i2c_handle, &uv_index) != 0) {
            fprintf(stderr, "Error reading UV index. Retrying in 1 second.\n");
            gpioDelay(1000000);
            continue;
        }

        /* Read visible ambient light */
        if (si1145_read_als_visible(i2c_handle, &als_visible) != 0) {
            fprintf(stderr, "Error reading ALS visible light. Retrying in 1 second.\n");
            gpioDelay(1000000);
            continue;
        }

        /* Log data to the console */
        printf("UV Index: %.2f, ALS Visible: %u\n", uv_index, als_visible);

        /* Log data to the CSV file */
        if (log_data(log_file, uv_index, als_visible) != 0) {
            fprintf(stderr, "Error logging data. Continuing...\n");
        }

        /* Wait for 1 second */
        gpioDelay(1000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

