#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS          "/dev/i2c-1"
#define SENSOR1_ADDR     0x20
#define SENSOR2_ADDR     0x21
#define ALARM_GPIO       17
#define FLOW_THRESHOLD   0.5f
#define LOG_FILE         "flow_log.txt"
#define SAMPLE_INTERVAL  1
#define MEASURE_DELAY_US 100000
#define CRC8_POLYNOMIAL  0x31
#define CRC8_INIT        0xFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLYNOMIAL);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t addr, const uint8_t *cmd, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", addr, strerror(errno));
        return -1;
    }
    ssize_t n = write(fd, cmd, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C write to 0x%02X failed: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t addr, uint8_t *buf, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", addr, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from 0x%02X failed: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, uint8_t addr, float *flow_rate)
{
    uint8_t cmd[2] = {0x36, 0x08};
    uint8_t buf[3];

    if (i2c_write_cmd(fd, addr, cmd, sizeof(cmd)) < 0)
        return -1;

    gpioDelay(MEASURE_DELAY_US);

    if (i2c_read_data(fd, addr, buf, sizeof(buf)) < 0)
        return -1;

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data from 0x%02X\n", addr);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / 100.0f;
    return 0;
}

static void log_data(FILE *fp, float flow1, float flow2, float avg, int alarm_state)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Avg: %.2f ml/min, Alarm: %s\n",
            ts, flow1, flow2, avg, alarm_state ? "ON" : "OFF");
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", ALARM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int valid1 = 0, valid2 = 0;

        if (read_flow_rate(g_i2c_fd, SENSOR1_ADDR, &flow1) == 0)
            valid1 = 1;
        if (read_flow_rate(g_i2c_fd, SENSOR2_ADDR, &flow2) == 0)
            valid2 = 1;

        float avg = 0.0f;
        int count = 0;
        if (valid1) { avg += flow1; count++; }
        if (valid2) { avg += flow2; count++; }
        if (count > 0)
            avg /= (float)count;

        int alarm_state = (count > 0 && avg < FLOW_THRESHOLD) ? 1 : 0;
        gpioWrite(ALARM_GPIO, alarm_state);

        log_data(g_log_fp, flow1, flow2, avg, alarm_state);

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    gpioWrite(ALARM_GPIO, 0);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_log_fp) fclose(g_log_fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

