/*
 * KY-033 Obstacle Avoidance Sensor Module — Circular Buffer Logger
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: KY-033 (digital output on GPIO4, BCM 7)
 * Logic:  LOW  => obstacle detected (line pulled LOW)
 *         HIGH => clear (line pulled HIGH)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ky033_log ky033_log.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN      4          /* BCM 7 */
#define BUFFER_SIZE     100
#define SAMPLE_PERIOD_US 50000     /* 50 ms */

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */

typedef struct {
    time_t timestamp;
    bool   obstacle;          /* true => obstacle detected (LOW) */
} SensorReading;

static SensorReading buffer[BUFFER_SIZE];
static int           head = 0;
static int           count = 0;   /* number of valid entries */

static void add_reading(time_t ts, bool obstacle)
{
    buffer[head].timestamp = ts;
    buffer[head].obstacle  = obstacle;
    head = (head + 1) % BUFFER_SIZE;
    if (count < BUFFER_SIZE)
        count++;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-033 Obstacle Avoidance Sensor Logger\n");
    printf("Sensor pin : BCM %d\n", SENSOR_PIN);
    printf("Buffer size: %d entries\n", BUFFER_SIZE);
    printf("Press Ctrl+C to exit and dump the buffer.\n\n");
    fflush(stdout);

    /* ---- main loop ---- */
    while (g_running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
