/*
 * fan_health.c — Omron D7S vibration sensor logger for Raspberry Pi 5 (64-bit Bookworm)
 *
 * Wiring:
 *   D7S SDA  -> GPIO2 (BCM 2, physical pin 3)
 *   D7S SCL  -> GPIO3 (BCM 3, physical pin 5)
 *   D7S VDD  -> 3.3 V (physical pin 1)
 *   D7S GND  -> GND  (physical pin 6)
 *
 * I2C bus: /dev/i2c-1  (BCM GPIO2=SDA, BCM GPIO3=SCL)
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 * Run:    ./fan_health   (Ctrl-C to stop)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- D7S constants (verified against the datasheet) ---- */
#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x50          /* 7-bit I2C address (SA0 tied to GND) */

#define REG_MODE       0x00          /* Mode register (write) */
#define REG_X_LSB      0x02          /* X-axis acceleration (read) */
#define REG_Y_LSB      0x04          /* Y-axis acceleration (read) */
#define REG_Z_LSB      0x06          /* Z-axis acceleration (read) */

#define MODE_ACTIVE    0x01          /* Bit 0 = 1 -> sensor active */
#define MODE_STANDBY   0x00          /* Bit 0 = 0 -> sensor standby */

#define CSV_FILENAME   "fan_health.csv"
#define SAMPLE_PERIOD_US 500000      /* 500 ms */
#define ACTIVE_TIMEOUT_S 1          /* 1 s wait for sensor to become active */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int d7s_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[ERROR] write(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register. Returns 0 on success, -1 on error. */
static int d7s_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "[ERROR] write(reg=0x%02X) for read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "[ERROR] read(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian acceleration sample. Returns 0 on success, -1 on error. */
static int d7s_read_axis(int fd, uint8_t reg_lsb, int16_t *out)
{
    uint8_t lo, hi;
    if (d7s_read_reg8(fd, reg_lsb, &lo) != 0)
        return -1;
    if (d7s_read_reg8(fd, reg_lsb + 1, &hi) != 0)
        return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "[ERROR] open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/* ------------------------------------------------------------------ */
static int init_sensor(int fd)
{
    /* Put sensor into standby first so a mode write is guaranteed to take. */
    if (d7s_write_reg8(fd, REG_MODE, MODE_STANDBY) != 0)
        return -1;
    usleep(10000);  /* 10 ms settle */

    /* Switch to active mode. */
    if (d7s_write_reg8(fd, REG_MODE, MODE_ACTIVE) != 0)
        return -1;
    usleep(10000);  /* 10 ms settle */

    return 0;
}

/* ------------------------------------------------------------------ */
static int wait_sensor_active(int fd)
{
    for (int i = 0; i < ACTIVE_TIMEOUT_S * 10; i++) {
        uint8_t mode;
        if (d7s_read_reg8(fd, REG_MODE, &mode) != 0)
            return -1;
        if (mode & MODE_ACTIVE)
            return 0;
        usleep(100000);  /* 100 ms */
    }
    fprintf(stderr, "[ERROR] Sensor did not become active within %d s.\n",
            ACTIVE_TIMEOUT_S);
    return -1;
}

/* ------------------------------------------------------------------ */
static int open_csv(void)
{
    int need_header = (access(CSV_FILENAME, F_OK) != 0);
    FILE *f = fopen(CSV_FILENAME, "a");
    if (!f) {
        fprintf(stderr, "[ERROR] fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        return -1;
    }
    if (need_header)
        fprintf(f, "timestamp,x,y,z\n");
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_sample(FILE *f, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[WARN] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(f, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(f);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = init_i2c();
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    if (init_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "[ERROR] Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (wait_sensor_active(g_i2c_fd) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (open_csv() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "[ERROR] fopen(%s) for append failed: %s\n",
                CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("D7S vibration logger started. Logging to %s. Press Ctrl-C to stop.\n",
           CSV_FILENAME);

    while (g_running) {
        int16_t x, y, z;
        if (d7s_read_axis(g_i2c_fd, REG_X_LSB, &x) != 0 ||
            d7s_read_axis(g_i2c_fd, REG_Y_LSB, &y) != 0 ||
            d7s_read_axis(g_i2c_fd, REG_Z_LSB, &z) != 0) {
            fprintf(stderr, "[WARN] Read error — will retry next cycle.\n");
        } else {
            log_sample(g_csv, x, y, z);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

