        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nObstacle avoidance system stopped.\n");
    return EXIT_SUCCESS;
}

