/*
 * TMAG5170‑Q1 3D Hall-Effect Sensor Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TMAG5170 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   TMAG5170 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   TMAG5170 VDD  -> 3.3 V (pin 1)
 *   TMAG5170 GND  -> GND  (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tmag5170_logger tmag5170_logger.c -lm
 *
 * Run:
 *   ./tmag5170_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- TMAG5170 I2C configuration ---- */
#define I2C_BUS        1
#define I2C_ADDR       0x28          /* TMAG5170 default 7-bit I2C address */

/* ---- TMAG5170 register addresses ---- */
#define REG_DEVICE_ID  0x00
#define REG_X_CH_RESULT 0x01
#define REG_Y_CH_RESULT 0x03
#define REG_Z_CH_RESULT 0x05
#define REG_CONFIG     0x07
#define REG_STATUS     0x08

/* ---- TMAG5170 configuration values ---- */
#define CONFIG_CONTINUOUS_MODE 0x01
#define CONFIG_X_AXIS_EN      0x02
#define CONFIG_Y_AXIS_EN      0x04
#define CONFIG_Z_AXIS_EN      0x08
#define CONFIG_50MT_RANGE     0x00

/* ---- Expected device ID ---- */
#define EXPECTED_DEVICE_ID 0x5170

/* ---- Sampling interval (microseconds) ---- */
#define SAMPLE_INTERVAL_US 100000

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a TMAG5170 register                         */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int tmag_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a TMAG5170 register                         */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int tmag_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian result register pair (X, Y, or Z)           */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int tmag_read_axis(uint8_t reg, int16_t *out)
{
    uint8_t lo, hi;
    if (tmag_read_reg(reg, &lo) < 0)
        return -1;
    if (tmag_read_reg(reg + 1, &hi) < 0)
        return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the TMAG5170 sensor                                     */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int tmag_init(void)
{
    uint8_t device_id = 0;

    /* Verify device identity */
    if (tmag_read_reg(REG_DEVICE_ID, &device_id) < 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVICE_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "[ERROR] Unexpected DEVICE_ID: 0x%04X (expected 0x%04X).\n",
                device_id, EXPECTED_DEVICE_ID);
        return -1;
    }
    printf("[INFO] TMAG5170 detected (DEVICE_ID=0x%04X).\n", device_id);

    /*
     * Configuration register (0x07):
     *   Bit 0  = CONTINUOUS_MODE (1 = continuous)
     *   Bits 1:2 = X_AXIS_EN, Y_AXIS_EN, Z_AXIS_EN
     *   Bits 3:4 = RANGE (00 = 50 mT)
     *   Bit 5   = reserved
     *   Bit 6   = reserved
     *   Bit 7   = reserved
     */
    uint8_t config = CONFIG_CONTINUOUS_MODE | CONFIG_X_AXIS_EN |
                     CONFIG_Y_AXIS_EN | CONFIG_Z_AXIS_EN | CONFIG_50MT_RANGE;

    if (tmag_write_reg(REG_CONFIG, config) < 0)
        return -1;

    printf("[INFO] TMAG5170 configured: continuous mode, X/Y/Z axes enabled, 50 mT range.\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all three axes and convert to milli-Tesla                     */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int tmag_read_all(float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (tmag_read_axis(REG_X_CH_RESULT, &raw_x) < 0)
        return -1;
    if (tmag_read_axis(REG_Y_CH_RESULT, &raw_y) < 0)
        return -1;
    if (tmag_read_axis(REG_Z_CH_RESULT, &raw_z) < 0)
        return -1;

    /*
     * 50 mT range: 1 LSB = 0.001 T = 1 mT.
     * raw_x, raw_y, raw_z are signed 16-bit values.
     */
    *x = (float)raw_x * 0.001f;
    *y = (float)raw_y * 0.001f;
    *z = (float)raw_z * 0.001f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                    */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int log_data(float x, float y, float z)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed.\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
        /* Non-fatal: data is in the buffer */
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (tmag_init() < 0) {
        fprintf(stderr, "[FATAL] TMAG5170 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode); write header if file is empty */
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open magnetic_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,x_mT,y_mT,z_mT\n");
        fflush(log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("[INFO] Logging TMAG5170 data to magnetic_log.csv (Ctrl-C to stop).\n");

    /* Main sampling loop */
    while (!terminate) {
        float x, y, z;

        if (tmag_read_all(&x, &y, &z) == 0) {
            if (log_data(x, y, z) < 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep 100 ms (interruptible by signals) */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

