        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_PIN);
        log_event("ERROR: Failed to set GPIO23 as input");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR_PIN);
        log_event("ERROR: Failed to set pull-down on GPIO23");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN);
    fflush(stdout);

    while (running) {
        check_water_level();
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

