/*
 * MLX90217 Hall-effect RPM monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MLX90217 VCC  -> 3.3 V (pin 1)
 *   MLX90217 GND  -> GND  (pin 9)
 *   MLX90217 OUT  -> BCM GPIO4 (pin 7)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rpm_monitor rpm_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./rpm_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdatomic.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN          4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE          "rpm_log.txt"
#define SAMPLE_PERIOD_US  1000000    /* 1 second in microseconds */

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;
static atomic_uint_fast32_t g_pulse_count = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio thread)                        */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    atomic_fetch_add(&g_pulse_count, 1);
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t     rawtime;
    struct tm  tm_info;

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(buf, len, "1970-01-01 00:00:00");
    }
}

static void log_rpm(float rpm)
{
    char ts[32];

    get_timestamp(ts, sizeof(ts));

    if (fprintf(g_log_fp, "%s %.2f\n", ts, rpm) < 0) {
        perror("fprintf to log file failed");
    }
    if (fflush(g_log_fp) != 0) {
        perror("fflush failed");
    }
    printf("%s %.2f\n", ts, rpm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pin ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed.\n", GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(%d) failed.\n", GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90217 RPM monitor started on BCM GPIO%d.\n", GPIO_PIN);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);
    fflush(stdout);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /*
         * Sleep for the sample period.  gpioDelay is a busy-wait that
         * returns early if a signal arrives.
         */
        gpioDelay(SAMPLE_PERIOD_US);

        if (!g_running) {
            break;
        }

        /* Atomically read and reset the pulse count */
        uint32_t pulses = atomic_exchange(&g_pulse_count, 0);

        /*
         * RPM = (pulses / sample_period_s) * 60
         *     = (pulses / 1e6) * 60
         */
        float rpm = (float)pulses * 60.0f / 1000000.0f;

        log_rpm(rpm);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);   /* unregister callback */
    cleanup();
    return EXIT_SUCCESS;
}

