/*
 * TTP223B capacitive touch sensor -> LED control on Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   TTP223B VCC  -> 3.3 V (pin 1)
 *   TTP223B GND  -> GND  (pin 9)
 *   TTP223B OUT  -> GPIO23 (pin 16, BCM 23)
 *   LED anode    -> GPIO18 (pin 12, BCM 18) via ~330 Ω resistor
 *   LED cathode  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_led touch_led.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN  23          /* BCM 23, physical pin 16 */
#define LED_PIN     18          /* BCM 18, physical pin 12 */
#define POLL_MS     50          /* polling interval */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Starting touch-sensor LED controller (GPIO23 -> GPIO18)");

    if (install_signal_handlers() != 0)
        goto cleanup;

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (sensor_line == NULL) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request sensor line as input. */
    if (gpiod_line_request_input(sensor_line, "touch_led") < 0) {
        syslog(LOG_ERR, "Failed to request GPIO %d as input: %s", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request LED line as output, initial value LOW (off). */
    if (gpiod_line_request_output(led_line, "touch_led", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO %d as output: %s", LED_PIN, strerror(errno));
        goto cleanup;
    }

    syslog(LOG_INFO, "Monitoring TTP223B on GPIO%d; LED on GPIO%d", SENSOR_PIN, LED_PIN);

    while (g_running) {
        int val = gpiod_line_get_value(sensor_line);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read sensor GPIO %d: %s", SENSOR_PIN, strerror(errno));
            break;
        }

        if (val == 1) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to turn LED on: %s", strerror(errno));
                break;
            }
