/*
 * TTP223B capacitive touch sensor – rising-edge LED toggle on Raspberry Pi 3 B+
 *
 * Wiring:
 *   TTP223B VCC  -> 3.3 V (pin 1)
 *   TTP223B GND  -> GND  (pin 9)
 *   TTP223B OUT  -> GPIO17 (pin 11)  [rising edge = touch detected]
 *   LED anode    -> GPIO18 (pin 12)  through ~330 Ω resistor
 *   LED cathode  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_led touch_led.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define TOUCH_PIN  17          /* GPIO17 – TTP223B OUT */
#define LED_PIN    18          /* GPIO18 – LED anode   */
#define DEBOUNCE_MS 50

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto out;

    /* Open the default gpiochip (gpiochip0 on Pi 3 B+). */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto out;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (touch_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                TOUCH_PIN, strerror(errno));
        goto out;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                LED_PIN, strerror(errno));
        goto out;
    }

    /* Request the touch line as input with rising-edge events. */
    if (gpiod_line_request_rising_edge_events(touch_line, "ttp223b-touch") < 0) {
        fprintf(stderr, "Failed to request rising-edge events on GPIO %d: %s\n",
                TOUCH_PIN, strerror(errno));
        goto out;
    }

    /* Request the LED line as output, initial value LOW. */
    if (gpiod_line_request_output(led_line, "ttp223b-led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                LED_PIN, strerror(errno));
        goto out;
    }

    printf("TTP223B touch sensor ready. Touch GPIO%d to toggle LED on GPIO%d.\n",
           TOUCH_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int led_state = 0;

    while (g_running) {
        /* Block up to 1 s waiting for a rising-edge event. */
        int ev = gpiod_line_event_wait(touch_line, &(struct timespec){1, 0});
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            goto out;
        }
        if (ev == 0)
            continue;  /* timeout, loop and re-check g_running */

        /* Read the event to confirm it is a rising edge. */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            goto out;
        }
        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE)
            continue;

        /* Debounce: ignore further events for DEBOUNCE_MS. */
        sleep_ms(DEBOUNCE_MS);

        /* Toggle LED. */
        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
            goto out;
        }

        printf("Touch detected – LED %s\n", led_state ? "ON" : "OFF");
        fflush(stdout);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

out:
    /* Ensure LED is off before releasing resources. */
    if (led_line != NULL)
        (void)gpiod_line_set_value(led_line, 0);

    if (touch_line != NULL)
        gpiod_line_release(touch_line);
    if (led_line != NULL)
        gpiod_line_release(led_line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

