#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN    27
#define LED_2_PIN    22

#define BUFFER_SIZE 100
#define DEBOUNCE_US  50000   /* 50 ms */

typedef struct {
    int  sensor_pin;
    time_t timestamp;
    int  state;          /* 0 = released, 1 = touched */
} sensor_event_t;

static sensor_event_t event_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int overflow_count = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_2_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-downs so the inputs read LOW when the sensor is open. */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d.\n", SENSOR_1_PIN);
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d.\n", SENSOR_2_PIN);
    }

    /* Ensure LEDs are off at startup. */
    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d to LOW.\n", LED_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d to LOW.\n", LED_2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort LED off and pigpio termination. */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

static void log_event(int sensor_pin, int state)
{
    event_buffer[buffer_index].sensor_pin = sensor_pin;
    event_buffer[buffer_index].timestamp  = time(NULL);
    event_buffer[buffer_index].state      = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        overflow_count++;
    }
}

static void print_log_buffer(void)
{
    printf("\n--- Event Log ---\n");
    printf("Overflow count: %d\n", overflow_count);
    printf("Index | Pin | Timestamp | State\n");
    printf("-------------------------------\n");

    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        printf("%5d | %3d | %10ld | %5s\n",
               i,
               event_buffer[idx].sensor_pin,
               (long)event_buffer[idx].timestamp,
               event_buffer[idx].state ? "TOUCH" : "RELEASE");
    }
    printf("-------------------------------\n");
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", SENSOR_1_PIN);
        } else {
            if (gpioWrite(LED_1_PIN, s1) != 0) {
                fprintf(stderr, "Warning: gpioWrite failed on GPIO%d.\n", LED_1_PIN);
            }
            log_event(SENSOR_1_PIN, s1);
        }

        if (s2 < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", SENSOR_2_PIN);
        } else {
            if (gpioWrite(LED_2_PIN, s2) != 0) {
                fprintf(stderr, "Warning: gpioWrite failed on GPIO%d.\n", LED_2_PIN);
            }
            log_event(SENSOR_2_PIN, s2);
        }

        gpioDelay(DEBOUNCE_US);
    }

    printf("\nShutting down...\n");
    print_log_buffer();
    cleanup_gpio();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

