    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort LED off and pigpio termination. */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

static void log_event(int sensor_pin, int state)
{
    event_buffer[buffer_index].sensor_pin = sensor_pin;
    event_buffer[buffer_index].timestamp  = time(NULL);
    event_buffer[buffer_index].state      = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        overflow_count++;
    }
}

static void print_log_buffer(void)
{
    printf("\n--- Event Log ---\n");
    printf("Overflow count: %d\n", overflow_count);
    printf("Index | Pin | Timestamp | State\n");
    printf("-------------------------------\n");

    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        printf("%5d | %3d | %10ld | %5s\n",
               i,
               event_buffer[idx].sensor_pin,
               (long)event_buffer[idx].timestamp,
               event_buffer[idx].state ? "TOUCH" : "RELEASE");
    }
    printf("-------------------------------\n");
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", SENSOR_1_PIN);
        } else {
            if (gpioWrite(LED_1_PIN, s1) != 0) {
                fprintf(stderr, "Warning: gpioWrite failed on GPIO%d.\n", LED_1_PIN);
            }
            log_event(SENSOR_1_PIN, s1);
        }

        if (s2 < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", SENSOR_2_PIN);
        } else {
            if (gpioWrite(LED_2_PIN, s2) != 0) {
                fprintf(stderr, "Warning: gpioWrite failed on GPIO%d.\n", LED_2_PIN);
            }
            log_event(SENSOR_2_PIN, s2);
        }

        gpioDelay(DEBOUNCE_US);
    }

    printf("\nShutting down...\n");
    print_log_buffer();
    cleanup_gpio();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

