            fprintf(stderr, "Error: Failed to read GPIO%d\n", RAIN_SENSOR_PIN);
            break;
        }

        if (current_state != last_state) {
            if (current_state == 0) {
                if (log_event("Rain Detected") != 0) {
                    fprintf(stderr, "Error: Failed to log rain event\n");
                }
            } else {
                if (log_event("No Rain") != 0) {
                    fprintf(stderr, "Error: Failed to log no-rain event\n");
                }
            }
            last_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error: Failed to close log file\n");
        }
        log_file = NULL;
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

