#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define DEBOUNCE_US 5000
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(FILE *fp, int s1, int s2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d\n", timestamp, s1, s2) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int calculate_rpm(int s1, int s2, int prev_s1, int prev_s2, uint32_t now_us, uint32_t *last_change_us) {
    int transitions = 0;

    if (s1 != prev_s1) {
        transitions++;
        *last_change_us = now_us;
    }
    if (s2 != prev_s2) {
        transitions++;
        *last_change_us = now_us;
    }

    if (transitions == 0) {
        return 0;
    }

    uint32_t elapsed = now_us - *last_change_us;
    if (elapsed == 0) {
        return 0;
    }

    double time_sec = (double)elapsed / 1000000.0;
    double rpm = (double)transitions / time_sec * 60.0;

    return (int)rpm;
}

int main(void) {
    FILE *fp = NULL;
    int prev_s1 = -1, prev_s2 = -1;
    uint32_t last_change_us = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as input\n", SENSOR1_PIN);
        goto cleanup_gpio;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as input\n", SENSOR2_PIN);
        goto cleanup_gpio;
    }

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup_gpio;
    }

    printf("Monitoring shaft RPM. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpioRead(SENSOR1_PIN);
        int s2 = gpioRead(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading GPIO pins\n");
            break;
        }

        uint32_t now_us = gpioTick();

        if (s1 != prev_s1 || s2 != prev_s2) {
            if (log_data(fp, s1, s2) != 0) {
                break;
            }
            prev_s1 = s1;
            prev_s2 = s2;
        }

        int rpm = calculate_rpm(s1, s2, prev_s1, prev_s2, now_us, &last_change_us);
        printf("RPM: %d\n", rpm);

        gpioDelay(100000);
    }

    ret = EXIT_SUCCESS;

cleanup_gpio:
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return ret;
}

