#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x50
#define LOG_FILE "biometric_log.txt"

#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_HW_KEY 0x07
#define SI1182_REG_MEAS_RATE0 0x08
#define SI1182_REG_MEAS_RATE1 0x09
#define SI1182_REG_ALS_VIS_DATA0 0x22
#define SI1182_REG_ALS_VIS_DATA1 0x23
#define SI1182_REG_ALS_IR_DATA0 0x24
#define SI1182_REG_ALS_IR_DATA1 0x25
#define SI1182_REG_PS1_DATA0 0x26
#define SI1182_REG_PS1_DATA1 0x27
#define SI1182_REG_PS2_DATA0 0x28
#define SI1182_REG_PS2_DATA1 0x29
#define SI1182_REG_PS3_DATA0 0x2A
#define SI1182_REG_PS3_DATA1 0x2B
#define SI1182_REG_COMMAND 0x30

#define SI1182_CMD_RESET 0x01
#define SI1182_CMD_ALS_FORCE 0x06
#define SI1182_CMD_PS_FORCE 0x05
#define SI1182_CMD_PSALS_FORCE 0x07

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_word(uint8_t reg_low) {
    int low = read_reg(reg_low);
    if (low < 0) return -1;
    int high = read_reg(reg_low + 1);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static int init_si1182(void) {
    if (write_reg(SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (write_reg(SI1182_REG_HW_KEY, 0x17) < 0) return -1;
    if (write_reg(SI1182_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_reg(SI1182_REG_MEAS_RATE1, 0x00) < 0) return -1;

    return 0;
}

static int read_sensor_data(int *heart_rate, int *spo2) {
    if (write_reg(SI1182_REG_COMMAND, SI1182_CMD_PSALS_FORCE) < 0) return -1;
    gpioDelay(10000);

    int hr = read_word(SI1182_REG_ALS_VIS_DATA0);
    int sp = read_word(SI1182_REG_ALS_IR_DATA0);

    if (hr < 0 || sp < 0) return -1;

    *heart_rate = hr;
    *spo2 = sp;
    return 0;
}

static void log_data(int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1182() < 0) {
        fprintf(stderr, "Si1182 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int heart_rate, spo2;
    while (!terminate) {
        if (read_sensor_data(&heart_rate, &spo2) == 0) {
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        sleep(1);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

