#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27

#define TILT_THRESHOLD_SEC 2
#define POLL_INTERVAL_US   100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
    }

    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", ALARM_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO%d\n", SENSOR_1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO%d\n", SENSOR_2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize alarm pin LOW\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(ALARM_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    int alarm_active = 0;
    time_t tilt_start_time = 0;
    int tilt_active = 0;

    while (running) {
        int sensor1_value = gpioRead(SENSOR_1_PIN);
        int sensor2_value = gpioRead(SENSOR_2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error: Failed to read sensor GPIOs\n");
            break;
        }

        int tilt_detected = (sensor1_value == 1 || sensor2_value == 1);

        if (tilt_detected && !tilt_active) {
            tilt_active = 1;
            tilt_start_time = time(NULL);
            if (log_event("Tilt detected") != 0) {
                fprintf(stderr, "Warning: Failed to log tilt start event\n");
            }
        } else if (!tilt_detected && tilt_active) {
            tilt_active = 0;
            if (log_event("Tilt recovered") != 0) {
                fprintf(stderr, "Warning: Failed to log tilt end event\n");
            }
        }

        if (tilt_active) {
            time_t current_time = time(NULL);
            if (difftime(current_time, tilt_start_time) >= TILT_THRESHOLD_SEC) {
                if (!alarm_active) {
                    if (gpioWrite(ALARM_PIN, 1) == 0) {
                        alarm_active = 1;
                        if (log_event("Alarm activated") != 0) {
                            fprintf(stderr, "Warning: Failed to log alarm activation event\n");
                        }
                    } else {
                        fprintf(stderr, "Error: Failed to activate alarm\n");
                    }
                }
            } else {
                if (alarm_active) {
                    if (gpioWrite(ALARM_PIN, 0) == 0) {
                        alarm_active = 0;
                        if (log_event("Alarm deactivated") != 0) {
                            fprintf(stderr, "Warning: Failed to log alarm deactivation event\n");
                        }
                    } else {
                        fprintf(stderr, "Error: Failed to deactivate alarm\n");
                    }
                }
            }
        } else {
            if (alarm_active) {
                if (gpioWrite(ALARM_PIN, 0) == 0) {
                    alarm_active = 0;
                    if (log_event("Alarm deactivated") != 0) {
                        fprintf(stderr, "Warning: Failed to log alarm deactivation event\n");
                    }
                } else {
                    fprintf(stderr, "Error: Failed to deactivate alarm\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("Error closing log file");
        }
        log_file = NULL;
    }

    cleanup_gpio();

    printf("Bridge integrity monitoring stopped.\n");
    return EXIT_SUCCESS;
}

