/*
 * Raspberry Pi 3 Model B+ — Omron D7S-A0011 seismic sensor monitor
 *
 * Wiring:
 *   D7S SDA  -> GPIO2 (BCM)
 *   D7S SCL  -> GPIO3 (BCM)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *   Alert LED -> GPIO17 (BCM), via 330 Ω resistor to GND
 *
 * Build:
 *   gcc -O2 -Wall -o seismic seismic.c -lthe driver library -lm -lrt
 *
 * Run:
 *   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Configuration ---- */
#define I2C_BUS          "/dev/i2c-1"
#define D7S_I2C_ADDR     0x20          /* D7S-A0011 default I2C address */
#define ALERT_LED_PIN    17            /* BCM GPIO17 */
#define THRESHOLD        500.0f        /* Euclidean magnitude threshold */
#define POLL_INTERVAL_US 100000        /* 100 ms */
#define ALERT_DURATION_S 1             /* Alert LED on-time */
#define MAX_RETRIES      3
#define LOG_FILE         "seismic_events.log"

/* ---- D7S register map (from datasheet) ---- */
#define REG_CTRL1        0x00
#define REG_CTRL2        0x01
#define REG_CTRL3        0x02
#define REG_STATUS       0x03
#define REG_X_CH_OUT_L   0x04
#define REG_X_CH_OUT_H   0x05
#define REG_Y_CH_OUT_L   0x06
#define REG_Y_CH_OUT_H   0x07
#define REG_Z_CH_OUT_L   0x08
#define REG_Z_CH_OUT_H   0x09

/* CTRL1: ODR=100 Hz (0x00), power-down bit (bit 0) = 0 -> active */
#define CTRL1_ACTIVE     0x00

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void msleep(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register; returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register; returns 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair; returns 0 on success, -1 on error. */
static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) != 0)
        return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) != 0)
        return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_d7s(int fd)
{
    uint8_t status;

    /* Verify sensor presence by reading STATUS register */
    if (i2c_read_reg8(fd, REG_STATUS, &status) != 0) {
        fprintf(stderr, "Cannot read STATUS register — sensor absent or bus error.\n");
        return -1;
    }

    /* Clear power-down bit in CTRL1 to activate the device */
    if (i2c_write_reg8(fd, REG_CTRL1, CTRL1_ACTIVE) != 0) {
        fprintf(stderr, "Failed to activate D7S sensor.\n");
        return -1;
    }

    /* Allow time for the first conversion to complete */
    msleep(10);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_d7s_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    int ok = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_reg16(fd, REG_X_CH_OUT_L, x) == 0 &&
            i2c_read_reg16(fd, REG_Y_CH_OUT_L, y) == 0 &&
            i2c_read_reg16(fd, REG_Z_CH_OUT_L, z) == 0) {
            ok = 1;
            break;
        }
        fprintf(stderr, "Read attempt %d/%d failed.\n", attempt + 1, MAX_RETRIES);
        msleep(10);
    }

    if (!ok) {
        fprintf(stderr, "Failed to read D7S data after %d attempts.\n", MAX_RETRIES);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    return sqrtf((float)x * x + (float)y * y + (float)z * z);
}

/* ------------------------------------------------------------------ */
static void log_event(FILE *fp, float magnitude)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    fprintf(fp, "%s, Magnitude: %.2f\n", ts, magnitude);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put sensor back into power-down mode for safety */
        (void)i2c_write_reg8(g_i2c_fd, REG_CTRL1, 0x01);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                D7S_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_d7s(g_i2c_fd) != 0) {
        fprintf(stderr, "D7S initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int16_t x, y, z;

        if (read_d7s_data(g_i2c_fd, &x, &y, &z) != 0) {
            /* I2C error — back off briefly and retry */
            msleep(POLL_INTERVAL_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > THRESHOLD) {
            printf("Earthquake detected! Magnitude: %.2f\n", magnitude);
            log_event(g_log, magnitude);

            /* Alert LED on */
            if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
                fprintf(stderr, "I2C slave re-acquire failed: %s\n", strerror(errno));
            } else {
                gpioWrite(ALERT_LED_PIN, 1);
                msleep(ALERT_DURATION_S * 1000);
                gpioWrite(ALERT_LED_PIN, 0);
            }
        }

        msleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

