#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define SENSOR_4_PIN 22
#define LED_PIN      18
#define POLL_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    int sensor_pins[4] = {SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN, SENSOR_4_PIN};
    int i;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    for (i = 0; i < 4; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        /* Enable internal pull-up resistors so the line is defined when the
           sensor is disconnected (HIGH = no object, LOW = object detected) */
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Warning: failed to set pull-up on GPIO %d.\n", sensor_pins[i]);
        }
    }

    /* Configure LED pin as output and ensure it starts OFF */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO %d to LOW.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection system started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (running) {
        int obstacle_detected = 0;

        for (i = 0; i < 4; i++) {
            int level = gpioRead(sensor_pins[i]);
            if (level < 0) {
                fprintf(stderr, "Warning: gpioRead failed on GPIO %d.\n", sensor_pins[i]);
                continue;
            }
            /* Active-low sensor: 0 = object detected, 1 = no object */
            if (level == 0) {
                obstacle_detected = 1;
                break;
            }
        }

        if (gpioWrite(LED_PIN, obstacle_detected ? 1 : 0) != 0) {
            fprintf(stderr, "Warning: gpioWrite failed on GPIO %d.\n", LED_PIN);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

