 *
 * Monitors five Keyes KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27
 * (physical pins 3, 5, 7, 11, 13) and logs confirmed transitions to
 * /var/log/flame_events.log with syslog(LOG_USER, "flame_monitor").
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <fcntl.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define LOG_BUF_SIZE     256

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, int pin, int flame_detected)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(%s, LOCK_EX): %s", LOG_FILE, strerror(errno));
        fclose(fp);
        return;
    }

    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (gmtime_r(&now, &tm_utc) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    } else {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - %s\n",
                ts, sensor_id, pin, flame_detected ? "Flame Detected" : "No Flame") < 0) {
        syslog(LOG_ERR, "fprintf(%s): %s", LOG_FILE, strerror(errno));
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush(%s): %s", LOG_FILE, strerror(errno));
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock(%s, LOCK_UN): %s", LOG_FILE, strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose(%s): %s", LOG_FILE, strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Sensor state tracking                                               */
/* ------------------------------------------------------------------ */
typedef struct {
    int  id;
    int  pin;
    int  last_state;   /* 0 = no flame, 1 = flame */
    int  initialized;
} sensor_state_t;

static sensor_state_t sensors[NUM_SENSORS];

static void init_sensors(void)
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].id          = i + 1;
        sensors[i].pin         = sensor_pins[i];
        sensors[i].last_state  = 0;
        sensors[i].initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        goto cleanup;
    }

    /* ---- Open syslog ---- */
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting flame sensor monitoring on BCM GPIO %u, %u, %u, %u, %u",
           sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(\"gpiochip0\"): %s", strerror(errno));
        goto cleanup;
    }

    /* ---- Request each line as input ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        sensors[i].initialized = 1;
        sensors[i].last_state  = gpiod_line_get_value(lines[i]);
        if (sensors[i].last_state < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value(%u) initial: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    init_sensors();

    syslog(LOG_INFO, "Monitoring started. Press Ctrl+C to exit.");

    /* ---- Main polling loop ---- */
    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (!sensors[i].initialized) {
                continue;
            }

            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u): %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            /* Detect HIGH -> LOW transition (flame detected) */
            if (val == 0 && sensors[i].last_state == 1) {
                /* Debounce: re-read after DEBOUNCE_MS */
                usleep(DEBOUNCE_MS * 1000);

                int confirmed = gpiod_line_get_value(lines[i]);
                if (confirmed < 0) {
                    syslog(LOG_ERR, "gpiod_line_get_value(%u) debounce: %s",
                           sensor_pins[i], strerror(errno));
                    continue;
                }

                if (confirmed == 0) {
                    log_event(sensors[i].id, sensors[i].pin, 1);
                    syslog(LOG_INFO, "Flame detected on sensor %d (GPIO %d)",
                           sensors[i].id, sensors[i].pin);
                }
            }

            sensors[i].last_state = val;
        }

        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down.");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release lines ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    /* ---- Close chip ---- */
    if (chip) {
        gpiod_chip_close(chip);
    }

    /* ---- Close syslog ---- */
    closelog();

    return ret;
