/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring (TTP226 OUT0..OUT7 -> BCM GPIO):
 *   OUT0 -> GPIO 5
 *   OUT1 -> GPIO 6
 *   OUT2 -> GPIO 13
 *   OUT3 -> GPIO 19
 *   OUT4 -> GPIO 26
 *   OUT5 -> GPIO 12
 *   OUT6 -> GPIO 16
 *   OUT7 -> GPIO 20
 *
 * Build:  gcc -Wall -Wextra -O2 -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int sensor_pins[NUM_CHANNELS] = {
    5,  6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("[%s] ", buf);
    } else {
        printf("[unknown-time] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line_request *request = NULL;
    int prev_states[NUM_CHANNELS];
    int ret;
    int i;

    /* Initialize prev_states to -1 so we always print on first read */
    for (i = 0; i < NUM_CHANNELS; i++)
        prev_states[i] = -1;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize the line bulk */
    gpiod_line_bulk_init(&lines);

    /* Get each GPIO line and add it to the bulk */
    for (i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Error: failed to get GPIO line %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    /* Request the lines as inputs */
    request = gpiod_chip_request_lines(chip, NULL, &lines);
    if (request == NULL) {
        fprintf(stderr, "Error: failed to request GPIO lines: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");
    printf("Pins: BCM GPIO %u, %u, %u, %u, %u, %u, %u, %u\n",
           sensor_pins[0], sensor_pins[1], sensor_pins[2], sensor_pins[3],
           sensor_pins[4], sensor_pins[5], sensor_pins[6], sensor_pins[7]);

    /* Main polling loop */
    while (program_running) {
        int values[NUM_CHANNELS];

        ret = gpiod_line_request_get_values(request, values);
        if (ret < 0) {
            fprintf(stderr, "Error: failed to read GPIO values: %s\n",
                    strerror(errno));
            goto cleanup;
        }

        for (i = 0; i < NUM_CHANNELS; i++) {
            if (values[i] != prev_states[i]) {
                print_timestamp();
                printf("Sensor %d (BCM GPIO %u): %s\n",
                       i, sensor_pins[i],
                       values[i] ? "touched" : "released");
                fflush(stdout);
                prev_states[i] = values[i];
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL)
        gpiod_line_request_release(request);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

