code:
/*
 * Adaptive Grow Light System for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - VEML7700 lux sensor on I2C bus 1, address 0x48
 *   - Grow light LED on GPIO18 (BCM) with hardware PWM at 1000 Hz
 *
 * Behavior:
 *   - Samples ambient light every 1 second
 *   - Maps lux to brightness:
 *       lux < 100  -> 100%
 *       lux < 500  -> 75%
 *       lux < 1000 -> 50%
 *       lux >= 1000 -> 25%
 *   - Logs to grow_log.txt with ISO-8601 timestamps
 *   - Graceful shutdown on SIGINT/SIGTERM
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define VEML7700_ADDR       0x48
#define LED_GPIO            18
#define PWM_FREQUENCY       1000          /* Hz */
#define PWM_RANGE           100           /* Duty cycle resolution */
#define SAMPLE_INTERVAL_US  1000000       /* 1 second */
#define LOG_FILE            "grow_log.txt"

/* VEML7700 register addresses */
#define VEML7700_REG_CONF   0x00
#define VEML7700_REG_ALS    0x04

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_lux(float *lux_out);
static int  map_lux_to_brightness(float lux);
static int  set_led_brightness(int brightness);
static int  log_data(float lux, int brightness, int error_code);
static void cleanup(void);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C init --------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, VEML7700_ADDR, strerror(errno));
        return -1;
    }

    /*
     * VEML7700 configuration register (0x00):
     *   ALS_SD = 0 (power on)
     *   ALS_IT = 000 (100 ms integration time)
     *   ALS_PERS = 00 (1 sample)
     *   ALS_INT_EN = 0 (no interrupt)
     *   ALS_INT_SEL = 00 (no interrupt)
     *   ALS_TRIG = 00 (no trigger)
     *   ALS_GAIN = 00 (1x gain)
     *   ALS_AF = 0 (no auto-gain)
     * => 0x0000
     */
    if (i2cWriteWordData(g_i2c_handle, VEML7700_REG_CONF, 0x0000) < 0) {
        fprintf(stderr, "Error writing VEML7700 config: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Allow integration time to elapse before first reading */
    gpioDelay(150000); /* 150 ms */
    return 0;
}

/* ------------------------------- GPIO init -------------------------------- */
static int init_gpio(void)
{
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d as output: %s\n",
                LED_GPIO, strerror(errno));
        return -1;
    }

    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO%d: %s\n",
                LED_GPIO, strerror(errno));
        return -1;
    }

    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO%d: %s\n",
                LED_GPIO, strerror(errno));
        return -1;
    }

    /* Start with LED off */
    if (gpioPWM(LED_GPIO, 0) < 0) {
        fprintf(stderr, "Error initializing PWM on GPIO%d: %s\n",
                LED_GPIO, strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------- Read lux --------------------------------- */
static int read_lux(float *lux_out)
{
    if (lux_out == NULL) {
        return -1;
    }

    int raw = i2cReadWordData(g_i2c_handle, VEML7700_REG_ALS);
    if (raw < 0) {
        fprintf(stderr, "Error reading VEML7700 ALS register: %s\n",
                strerror(errno));
        return -1;
    }

    /*
     * VEML7700 returns 16-bit data.
     * Resolution: 0.01 lux per count at 1x gain.
     */
    *lux_out = (float)raw * 0.01f;
    return 0;
}

/* --------------------------- Map lux to brightness ------------------------ */
static int map_lux_to_brightness(float lux)
{
    if (lux < 100.0f) {
        return 100;
