static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_lux(float *lux_out);
static int  map_lux_to_brightness(float lux);
static int  set_led_brightness(int brightness);
static int  log_data(float lux, int brightness, int error_code);
static void cleanup(void);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C init --------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, VEML7700_ADDR, strerror(errno));
        return -1;
    }

    /*
     * VEML7700 configuration register (0x00):
     *   ALS_SD = 0 (power on)
     *   ALS_IT = 000 (100 ms integration time)
     *   ALS_PERS = 00 (1 sample)
     *   ALS_INT_EN = 0 (no interrupt)
     *   ALS_INT_SEL = 00 (no interrupt)
     *   ALS_TRIG = 00 (no trigger)
     *   ALS_GAIN = 00 (1x gain)
     *   ALS_AF = 0 (no auto-gain)
     * => 0x0000
     */
    if (i2cWriteWordData(g_i2c_handle, VEML7700_REG_CONF, 0x0000) < 0) {
        fprintf(stderr, "Error writing VEML7700 config: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Allow integration time to elapse before first reading */
    gpioDelay(150000); /* 150 ms */
    return 0;
}

/* ------------------------------- GPIO init -------------------------------- */
static int init_gpio(void)
{
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d as output: %s\n",
                LED_GPIO, strerror(errno));
        return -1;
    }

    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO%d: %s\n",
                LED_GPIO, strerror(errno));
        return -1;
    }

    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO%d: %s\n",
                LED_GPIO, strerror(errno));
        return -1;
    }

    /* Start with LED off */
    if (gpioPWM(LED_GPIO, 0) < 0) {
        fprintf(stderr, "Error initializing PWM on GPIO%d: %s\n",
                LED_GPIO, strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------- Read lux --------------------------------- */
static int read_lux(float *lux_out)
{
    if (lux_out == NULL) {
        return -1;
    }

    int raw = i2cReadWordData(g_i2c_handle, VEML7700_REG_ALS);
    if (raw < 0) {
        fprintf(stderr, "Error reading VEML7700 ALS register: %s\n",
                strerror(errno));
        return -1;
    }

    /*
     * VEML7700 returns 16-bit data.
     * Resolution: 0.01 lux per count at 1x gain.
     */
    *lux_out = (float)raw * 0.01f;
    return 0;
}

/* --------------------------- Map lux to brightness ------------------------ */
static int map_lux_to_brightness(float lux)
{
    if (lux < 100.0f) {
        return 100;
    } else if (lux < 500.0f) {
        return 75;
    } else if (lux < 1000.0f) {
        return 50;
    } else {
        return 25;
    }
}

/* --------------------------- Set LED brightness -------------------------- */
static int set_led_brightness(int brightness)
{
    if (brightness < 0)   brightness = 0;
    if (brightness > 100) brightness = 100;

    int duty = (brightness * PWM_RANGE) / 100;
    if (gpioPWM(LED_GPIO, duty) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle on GPIO%d: %s\n",
                LED_GPIO, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------- Log data --------------------------------- */
static int log_data(float lux, int brightness, int error_code)
{
    if (g_log_file == NULL) {
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, Lux: %.2f, Brightness: %d, Error: %d\n",
                timestamp, lux, brightness, error_code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    /* Turn off LED */
    if (g_i2c_handle >= 0) {
        gpioPWM(LED_GPIO, 0);
    }

    /* Close I2C bus */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    /* Close log file */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        i2cClose(g_i2c_handle);
