#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define LED_PIN      17
#define LOG_FILE     "touch_log.txt"
#define POLL_DELAY_US 50000  /* 50 ms */

static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_touch_event(int channel)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s – Channel %d Touched\n", timestamp, channel) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure channel pins as inputs with pull-down resistors --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "gpioSetMode(pin %d) failed\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(channel_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "gpioSetPullUpDown(pin %d) failed\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Configure LED pin as output, initially off --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(pin %d) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(pin %d, 0) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    int prev_touched = 0;  /* bitmask of currently touched channels */

    while (running) {
        int touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (gpioRead(channel_pins[i]) == 1) {
                touched |= (1 << i);
            }
        }

        /* Log only on rising edge (debounced) */
        int new_touched = touched & ~prev_touched;
        if (new_touched) {
            for (int i = 0; i < NUM_CHANNELS; i++) {
                if (new_touched & (1 << i)) {
                    if (log_touch_event(i + 1) != 0) {
                        fprintf(stderr, "Warning: failed to log touch event for channel %d\n", i + 1);
                    }
                }
            }
        }

        /* Control LED */
        if (touched) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "gpioWrite(pin %d, 1) failed\n", LED_PIN);
            }
        } else {
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "gpioWrite(pin %d, 0) failed\n", LED_PIN);
            }
        }

        prev_touched = touched;
        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

