 *   OPT3001 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   OPT3001 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   OPT3001 VDD  -> 3.3 V
 *   OPT3001 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_monitor light_monitor.c -li2c
 *
 * Run:
 *   ./light_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- OPT3001 register definitions (from TI datasheet) ---- */
#define OPT3001_REG_RESULT      0x00
#define OPT3001_REG_CONFIG      0x01

/*
 * Configuration register (16-bit, little-endian on the bus):
 *   [15:12] Range number (0x00 = auto-range, 0x01 = 4096 lux, 0x02 = 2048 lux,
 *               0x03 = 1024 lux, 0x04 = 512 lux, 0x05 = 256 lux, 0x06 = 128 lux,
 *               0x07 = 64 lux, 0x08 = 32 lux, 0x09 = 16 lux, 0x0A = 8 lux,
 *               0x0B = 4 lux, 0x0C = 2 lux, 0x0D = 1 lux, 0x0E = 0.5 lux,
 *               0x0F = 0.25 lux)
 *   [11:9]  Conversion time (0x00 = 0.5 ms, 0x01 = 10 ms, 0x02 = 180 ms,
 *                          0x03 = 750 ms, 0x04 = 1300 ms, 0x05 = 100 ms,
 *                          0x06 = 300 ms, 0x07 = 600 ms)
 *   [8]     Flag bit (0 = no flag, 1 = flag present)
 *   [7:6]   Latch (0x00 = no latch, 0x01 = latch until read, 0x02 = latch
 *                 on conversion, 0x03 = reserved)
 *   [5:4]   Polarity (0x00 = active low, 0x01 = active high)
 *   [3:0]   Mask exponent (0x00 = 0, 0x01 = 1, 0x02 = 2, 0x03 = 3, 0x04 = 4,
 *                        0x05 = 5, 0x06 = 6, 0x07 = 7, 0x08 = 8, 0x09 = 9,
 *                        0x0A = 10, 0x0B = 11, 0x0C = 12, 0x0D = 13,
 *                        0x0E = 14, 0x0F = 15)
 *
 * For this application we use range 0x00 (auto-range), conversion time
 * 0x00 (0.5 ms), latch 0x00 (no latch), polarity 0x00 (active low), and
 * mask exponent 0x00 (0).  This gives a 0.5 ms conversion time and
 * auto-range resolution.
 */
#define OPT3001_CONFIG_VALUE    0x0000

/* ---- Globals for signal-handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an OPT3001 register (little-endian on bus)  */
/* ------------------------------------------------------------------ */
static int opt3001_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value & 0xFF);          /* LSB first */
    buf[2] = (uint8_t)((value >> 8) & 0xFF);  /* MSB second */

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an OPT3001 register (little-endian on bus) */
/* ------------------------------------------------------------------ */
static int opt3001_read_reg(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* OPT3001 returns data in big-endian format */
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the OPT3001 sensor                                      */
/* ------------------------------------------------------------------ */
static int opt3001_init(int fd)
{
    if (opt3001_write_reg(fd, OPT3001_REG_CONFIG, OPT3001_CONFIG_VALUE) != 0) {
        fprintf(stderr, "Failed to write OPT3001 configuration.\n");
        return -1;
    }

    /* Allow the first conversion to complete (0.5 ms) */
    usleep(1000);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read ambient light level in lux                                     */
/* ------------------------------------------------------------------ */
static int opt3001_read_lux(int fd, float *lux_out)
{
    uint16_t raw;
    uint16_t exponent;
    uint16_t mantissa;

    if (opt3001_read_reg(fd, OPT3001_REG_RESULT, &raw) != 0) {
        return -1;
    }

    /*
     * Result register layout (16-bit, big-endian):
     *   [15:12] Exponent (0x00 = 0, 0x01 = 0.01, 0x02 = 0.02, ..., 0x0F = 0.95)
     *   [11:0]  Mantissa (0x000 to 0x0FFF)
     */
    exponent = (raw >> 12) & 0x0F;
    mantissa = raw & 0x0FFF;

    *lux_out = (float)mantissa * (0.01f * (float)(1 << exponent));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Format current timestamp as YYYY-MM-DD HH:MM:SS                     */
/* ------------------------------------------------------------------ */
static void format_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

/* ------------------------------------------------------------------ */
/* Log a light reading to file and stdout                              */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const char *timestamp, float lux)
{
    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    printf("%s, %.2f\n", timestamp, lux);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    char timestamp[32];

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address 0x44 (OPT3001 default) */
    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x44) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus address 0x44: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (opt3001_init(g_i2c_fd) != 0) {
        fprintf(stderr, "OPT3001 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen("light_data.txt", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open light_data.txt: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Light Monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float lux;

        if (opt3001_read_lux(g_i2c_fd, &lux) == 0) {
            format_timestamp(timestamp, sizeof(timestamp));
            if (log_data(g_log_fp, timestamp, lux) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        /* Wait 1 second between readings (OPT3001 conversion time is 0.5 ms) */
        sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

