    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", FLAME_SENSOR_PIN);
            log_event("Error reading flame sensor");
        } else if (sensor_value == 0) {
            printf("Flame detected!\n");
            log_event("Flame detected");

            if (gpioWrite(ALERT_PIN, 1) != 0) {
                fprintf(stderr, "Error activating alert pin\n");
                log_event("Error activating alert pin");
            } else {
                gpioDelay(ALERT_DURATION_US);
                if (gpioWrite(ALERT_PIN, 0) != 0) {
                    fprintf(stderr, "Error deactivating alert pin\n");
                    log_event("Error deactivating alert pin");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    cleanup_gpio();

    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

