static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_touch_event(FILE *fp, const char *event_type)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

