        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor logging started on GPIO%d. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN);

    while (g_running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);

        if (current_state < 0) {
            fprintf(stderr, "gpioRead failed for pin %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (first_read) {
            last_state = current_state;
            first_read = 0;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_US);
            current_state = gpioRead(TOUCH_SENSOR_PIN);
            if (current_state < 0) {
                fprintf(stderr, "gpioRead failed for pin %d during debounce\n",
                        TOUCH_SENSOR_PIN);
                break;
            }

            if (current_state == last_state) {
                if (current_state == 1) {
                    if (log_touch_event(fp, "Touch Detected") != 0) {
                        fprintf(stderr, "Failed to log touch detection\n");
                        break;
                    }
                } else {
                    if (log_touch_event(fp, "Touch Released") != 0) {
                        fprintf(stderr, "Failed to log touch release\n");
                        break;
                    }
                }
                last_state = current_state;
            }
        }

        gpioDelay(1000); /* 1 ms poll interval */
    }

    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();

    printf("\nTouch sensor logging stopped.\n");
    return EXIT_SUCCESS;
}

