/*
 * SLF3S-1300F Liquid Flow Sensor Monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   SLF3S-1300F VDD  -> 3.3 V (Pin 1)
 *   SLF3S-1300F GND  -> GND  (Pin 9)
 *   SLF3S-1300F SDA  -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SLF3S-1300F SCL  -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o cooling_monitor cooling_monitor.c
 *
 * Run:
 *   ./cooling_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x20
#define LOG_FILE       "cooling_log.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MEAS_DELAY_MS  2          /* ms to wait after issuing command */
#define MAX_RETRIES    3
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f

/* SLF3S-1300F command: read flow rate with CRC */
static const uint8_t CMD_READ_FLOW[2] = {0x36, 0x2F};

/* CRC-8 parameters used by Sensirion: polynomial 0x31, init 0xFF */
#define CRC8_POLY      0x31
#define CRC8_INIT      0xFF

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion style)                                              */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    ssize_t n = write(fd, cmd, len);
    if (n < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C write short: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and fills *flow_rate.
 * Returns -1 on any I2C or CRC error.
 */
static int read_flow_rate(int fd, float *flow_rate)
{
    uint8_t buf[3];

    if (i2c_write_cmd(fd, CMD_READ_FLOW, sizeof(CMD_READ_FLOW)) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    /* Validate CRC over the two data bytes */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / 100.0f;   /* SLF3S-1300F: 0.01 ml/min per LSB */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    int need_header = (access(path, F_OK) != 0);

    g_log_fp = fopen(path, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    if (need_header)
        fprintf(g_log_fp, "Timestamp,Flow Rate (ml/min),Status\n");
    return 0;
}

static void log_data(float flow_rate, const char *status)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (!g_log_fp)
        return;

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_fp, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (log_open(LOG_FILE) < 0)
        return EXIT_FAILURE;

    g_i2c_fd = i2c_open(I2C_BUS, SLF3S_ADDR);
    if (g_i2c_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring SLF3S-1300F on %s @ 0x%02X. Press Ctrl+C to stop.\n",
           I2C_BUS, SLF3S_ADDR);

    while (g_running) {
        float flow_rate = 0.0f;
        int   ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_flow_rate(g_i2c_fd, &flow_rate) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed; re-initializing I2C.\n",
                    attempt + 1, MAX_RETRIES);
            close(g_i2c_fd);
            g_i2c_fd = -1;
            usleep(100000);   /* 100 ms back-off */
            g_i2c_fd = i2c_open(I2C_BUS, SLF3S_ADDR);
            if (g_i2c_fd < 0) {
                fprintf(stderr, "I2C re-init failed; will retry next cycle.\n");
                break;
            }
        }

        if (ok) {
            if (flow_rate >= FLOW_MIN && flow_rate <= FLOW_MAX)
                log_data(flow_rate, "OK");
            else
                log_data(flow_rate, "INVALID");
        } else {
            log_data(0.0f, "ERROR");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

