    *flow_rate = (float)raw / 100.0f;   /* SLF3S-1300F: 0.01 ml/min per LSB */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    int need_header = (access(path, F_OK) != 0);

    g_log_fp = fopen(path, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    if (need_header)
        fprintf(g_log_fp, "Timestamp,Flow Rate (ml/min),Status\n");
    return 0;
}

static void log_data(float flow_rate, const char *status)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (!g_log_fp)
        return;

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_fp, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (log_open(LOG_FILE) < 0)
        return EXIT_FAILURE;

    g_i2c_fd = i2c_open(I2C_BUS, SLF3S_ADDR);
    if (g_i2c_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring SLF3S-1300F on %s @ 0x%02X. Press Ctrl+C to stop.\n",
           I2C_BUS, SLF3S_ADDR);

    while (g_running) {
        float flow_rate = 0.0f;
        int   ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_flow_rate(g_i2c_fd, &flow_rate) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed; re-initializing I2C.\n",
                    attempt + 1, MAX_RETRIES);
            close(g_i2c_fd);
            g_i2c_fd = -1;
            usleep(100000);   /* 100 ms back-off */
            g_i2c_fd = i2c_open(I2C_BUS, SLF3S_ADDR);
            if (g_i2c_fd < 0) {
                fprintf(stderr, "I2C re-init failed; will retry next cycle.\n");
                break;
            }
        }

        if (ok) {
            if (flow_rate >= FLOW_MIN && flow_rate <= FLOW_MAX)
                log_data(flow_rate, "OK");
            else
                log_data(flow_rate, "INVALID");
        } else {
            log_data(0.0f, "ERROR");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

