/*
 * KY-033 Obstacle Avoidance Sensor Logger
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: 3 × KY-033 (digital output, reflective IR)
 *   Left   -> GPIO17 (BCM)
 *   Middle -> GPIO27 (BCM)
 *   Right  -> GPIO22 (BCM)
 * Log:    path_log.csv  (timestamp,left,middle,right)
 *
 * Build:  gcc -O2 -Wall -Wextra -o path_logger path_logger.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>

#define LOG_FILE        "path_log.csv"
#define SAMPLE_PERIOD_US 50000   /* 50 ms */

static const unsigned int sensor_pins[3] = { 17, 27, 22 };
static const char *sensor_names[3] = { "left", "middle", "right" };

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 timestamp into buf (size >= 25).                 */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1)
        return -1;

    if (localtime_r(&rawtime, &tm_info) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row:  timestamp,left,middle,right                     */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, const char *ts, int left, int middle, int right)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, left, middle, right) < 0)
        return -1;

    if (fflush(fp) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = { NULL, NULL, NULL };
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the default GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire each sensor line as input ---- */
    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line(%u): %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ky033-logger") < 0) {
            fprintf(stderr, "gpiod_line_request_input(%u): %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- Open log file ---- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,left,middle,right\n") < 0 ||
            fflush(fp) != 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("Logging KY-033 sensors to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        char ts[32];
        int vals[3];

        if (get_timestamp(ts, sizeof(ts)) != 0) {
            fprintf(stderr, "get_timestamp: %s\n", strerror(errno));
            goto cleanup;
        }

        for (int i = 0; i < 3; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "gpiod_line_get_value(%s): %s\n",
                        sensor_names[i], strerror(errno));
                goto cleanup;
            }
            vals[i] = v;
        }

        if (log_data(fp, ts, vals[0], vals[1], vals[2]) != 0) {
            fprintf(stderr, "log_data: %s\n", strerror(errno));
            goto cleanup;
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release lines ---- */
    for (int i = 0; i < 3; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }

    /* ---- Close chip ---- */
    if (chip != NULL)
        gpiod_chip_close(chip);

    /* ---- Close log file ---- */
    if (fp != NULL) {
        if (fclose(fp) != 0)
            fprintf(stderr, "fclose: %s\n", strerror(errno));
    }

    return ret;
}

