#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_SENSOR_GPIO 4
#define GPIO_CHIP_NAME "gpiochip4"
#define LOG_FILE "flame_events.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s: %s\n", timestamp, message);
    } else {
        fprintf(fp, "(timestamp error): %s\n", message);
    }

    fclose(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", FLAME_SENSOR_GPIO, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_falling_edge_events(line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request falling edge events on GPIO %d: %s\n", FLAME_SENSOR_GPIO, strerror(errno));
        goto cleanup_chip;
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n", FLAME_SENSOR_GPIO);

    while (program_running) {
        int event = gpiod_line_event_wait(line, &(struct timespec){0, POLL_TIMEOUT_MS * 1000000L});

        if (event < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }

        if (event == 0) {
            continue;
        }

        struct gpiod_line_event event_data;
        if (gpiod_line_event_read(line, &event_data) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            continue;
        }

        if (event_data.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            printf("Flame detected!\n");
            log_event("Flame detected!");
        }
    }

    ret = EXIT_SUCCESS;

cleanup_chip:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

