/*
 * touch_lamp.c — Raspberry Pi 5 touch-activated lamp simulator
 *
 * TTP223 capacitive touch sensor (active-high) on BCM 23, LED on BCM 24.
 * Polls rising-edge events on the sensor line with a 1-second timeout,
 * toggles the LED, and logs each event with an ISO-8601 timestamp to
 * touch_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_lamp touch_lamp.c -lgpiod
 * Run:    sudo ./touch_lamp   (root needed for /dev/gpiochip4 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"
#define TOUCH_PIN        23          /* BCM 23 — TTP223 OUT */
#define LED_PIN          24          /* BCM 24 — LED anode   */
#define LOG_FILE         "touch_log.txt"
#define POLL_TIMEOUT_MS  1000        /* 1-second event poll window */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 timestamp into buf (size >= 25).                 */
static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1)
        return -1;

    if (localtime_r(&rawtime, &tm_info) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a single log line to the log file.                          */
static int log_event(FILE *fp, const char *ts, int led_state)
{
    if (fprintf(fp, "%s - Touch detected, LED state: %s\n",
                ts, led_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
