/*
 * Flame detection safety system for Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 digital flame sensor (DO active-low)
 *   DO  -> GPIO17 (BCM, physical pin 11)
 * Buzzer: active buzzer control line
 *   +   -> GPIO18 (BCM, physical pin 12) via suitable driver
 *   -   -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>

#include <gpiod.h>

#define FLAME_SENSOR_PIN  17          /* BCM 17, physical pin 11 */
#define BUZZER_PIN        18          /* BCM 18, physical pin 12 */
#define LOG_FILE          "alert_log.txt"
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_MS 2000
#define SLICE_MS          100

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;
static struct gpiod_chip    *g_chip    = NULL;
static struct gpiod_line    *g_flame   = NULL;
static struct gpiod_line    *g_buzzer  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log_fp)
        return;

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s: %s\n", ts, msg) < 0)
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));

    if (fflush(g_log_fp) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int safe_set_value(struct gpiod_line *line, int val)
{
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "gpiod_line_set_value(%d) failed: %s\n",
                val, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void)
{
    if (g_buzzer) {
        (void)gpiod_line_set_value(g_buzzer, 0);
        gpiod_line_release(g_buzzer);
        g_buzzer = NULL;
    }
    if (g_flame) {
        gpiod_line_release(g_flame);
        g_flame = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Get lines ---- */
    g_flame = gpiod_chip_get_line(g_chip, FLAME_SENSOR_PIN);
    if (!g_flame) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                FLAME_SENSOR_PIN, strerror(errno));
        cleanup_gpio();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    g_buzzer = gpiod_chip_get_line(g_chip, BUZZER_PIN);
    if (!g_buzzer) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                BUZZER_PIN, strerror(errno));
        cleanup_gpio();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Request lines ---- */
    if (gpiod_line_request_input(g_flame, "flame_sensor") < 0) {
        fprintf(stderr, "gpiod_line_request_input(flame) failed: %s\n",
                strerror(errno));
        cleanup_gpio();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_buzzer, "buzzer", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(buzzer) failed: %s\n",
                strerror(errno));
        cleanup_gpio();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Initial state ---- */
    int prev_flame = gpiod_line_get_value(g_flame);
    if (prev_flame < 0) {
        fprintf(stderr, "initial gpiod_line_get_value(flame) failed: %s\n",
                strerror(errno));
        cleanup_gpio();
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    log_event("System started");

    /* ---- Main loop ---- */
    while (g_running) {
        int cur = gpiod_line_get_value(g_flame);
        if (cur < 0) {
            fprintf(stderr, "gpiod_line_get_value(flame) failed: %s\n",
                    strerror(errno));
            break;
        }

        /* HIGH -> LOW transition: flame just appeared */
        if (prev_flame == 1 && cur == 0) {
            log_event("FLAME DETECTED");

            if (safe_set_value(g_buzzer, 1) < 0)
                break;

            /*
             * Break the 2-second buzzer on into 100 ms slices so
             * we can respond promptly to shutdown signals.
             */
            for (int elapsed = 0; elapsed < BUZZER_DURATION_MS && g_running;
                 elapsed += SLICE_MS) {
                usleep(SLICE_MS * 1000);
            }

            if (safe_set_value(g_buzzer, 0) < 0)
                break;
        }

        prev_flame = cur;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* ---- Cleanup ---- */
    log_event("System stopped");
    cleanup_gpio();

    if (g_log_fp) {
        if (fclose(g_log_fp) != 0)
            fprintf(stderr, "fclose(log) failed: %s\n", strerror(errno));
        g_log_fp = NULL;
    }

    return EXIT_SUCCESS;
}

