/*
 * TTP223B capacitive touch sensor → LED toggle logger
 * Board:  Raspberry Pi Zero W
 * Sensor: SainSmart TTP223B (digital output, 3.3 V logic)
 *   VCC  -> 3.3 V (pin 1)
 *   GND  -> GND  (pin 9)
 *   OUT  -> GPIO4 (pin 7, BCM 4)
 * LED:   330 Ω resistor between GPIO17 (pin 11, BCM 17) and GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_logger touch_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN          17
#define DEBOUNCE_MS      200
#define POLL_DELAY_US    10000   /* 10 ms */
#define LOG_FILE         "touch_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t     rawtime;
    struct tm  tm_utc;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (gmtime_r(&rawtime, &tm_utc) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_touch_event(void)
{
    char ts[32];

    if (get_iso8601_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Warning: failed to generate timestamp: %s\n",
                strerror(errno));
        return -1;
    }

    if (fprintf(g_log_fp, "%s\n", ts) < 0) {
        fprintf(stderr, "Warning: failed to write to log file: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    printf("Touch detected at %s\n", ts);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int      last_state = 1;   /* assume released (HIGH) at startup */
    uint32_t last_event_tick = 0;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(TOUCH_SENSOR_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(LED_PIN, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Touch logger started.  Sensor=GPIO%d  LED=GPIO%d  Log=%s\n",
           TOUCH_SENSOR_PIN, LED_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        int level = gpioRead(TOUCH_SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead(TOUCH_SENSOR_PIN) failed\n");
            break;
        }

        /* Rising edge: LOW → HIGH */
        if (level == 0 && last_state == 1) {
            uint32_t now = gpioTick();
            if (now - last_event_tick >= (uint32_t)(DEBOUNCE_MS * 1000)) {
                if (gpioWrite(LED_PIN, !gpioRead(LED_PIN)) != 0) {
                    fprintf(stderr, "Error: gpioWrite(LED_PIN) failed\n");
                    break;
                }
                if (log_touch_event() != 0) {
                    /* Non-fatal: continue running */
                }
                last_event_tick = now;
            }
        }

        last_state = level;
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

