/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring
 *   Sensor 1 OUT -> GPIO4  (BCM)
 *   Sensor 2 OUT -> GPIO17 (BCM)
 *   Sensor 3 OUT -> GPIO27 (BCM)
 *   VCC          -> 3.3 V
 *   GND          -> GND
 *
 * The TMAG5110A1 has an open-drain output:
 *   - Magnet present  -> OUT low  (logic 0)
 *   - Magnet removed  -> OUT high (logic 1)
 *
 * Behavior
 *   Polls each sensor every 100 ms.  On the first read the initial state
 *   is recorded without generating a false transition.  Each state change
 *   is logged to magnet_log.txt with an ISO-8601 timestamp.
 *
 * Build
 *   gcc -Wall -Wextra -O2 -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 *   Run as root (pigpio requires root for hardware access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27

#define LOG_FILE_NAME "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* ------------------------------------------------------------------ */
/* Globals for signal-handler cleanup                                  */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; cleanup happens in main()           */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 timestamp into buf (size >= 25)                   */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo);
    } else {
        snprintf(buf, len, "UNKNOWN");
    }
}

/* ------------------------------------------------------------------ */
/* Append a state change line to the log file                          */
/* ------------------------------------------------------------------ */
static void log_state_change(int sensor_id, int state)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (fprintf(g_log_file, "%s - Sensor %d: %s\n",
                ts, sensor_id, state ? "MAGNET_PRESENT" : "MAGNET_REMOVED") < 0) {
        perror("fprintf to log file failed");
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1 on success, -1 on error           */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed (pigpio error %d)\n",
                pin, level);
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Configure a GPIO pin as input with internal pull-up                */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int configure_input_with_pullup(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int pins[3] = { SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN };
    int prev_state[3] = { -1, -1, -1 };   /* unknown initial state */
    int first_read[3] = { 1, 1, 1 };
    int rc = EXIT_SUCCESS;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins ---- */
    for (int i = 0; i < 3; i++) {
        if (configure_input_with_pullup(pins[i]) != 0) {
            rc = EXIT_FAILURE;
            goto cleanup_gpio;
        }
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        rc = EXIT_FAILURE;
        goto cleanup_gpio;
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO%d, GPIO%d, GPIO%d.\n",
           SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN);
    printf("Logging state changes to %s. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    /* ---- Main polling loop ---- */
    while (g_running) {
        for (int i = 0; i < 3; i++) {
            int level = read_sensor(pins[i]);
            if (level < 0) {
                /* Sensor read error — skip this cycle */
                continue;
            }

            if (first_read[i]) {
                /* Record initial state without logging a transition */
                prev_state[i] = level;
                first_read[i] = 0;
            } else if (level != prev_state[i]) {
                log_state_change(i + 1, level);
                prev_state[i] = level;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");

cleanup_gpio:
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    return rc;
}

