    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins ---- */
    for (int i = 0; i < 3; i++) {
        if (configure_input_with_pullup(pins[i]) != 0) {
            rc = EXIT_FAILURE;
            goto cleanup_gpio;
        }
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        rc = EXIT_FAILURE;
        goto cleanup_gpio;
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO%d, GPIO%d, GPIO%d.\n",
           SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN);
    printf("Logging state changes to %s. Press Ctrl+C to exit.\n",
           LOG_FILE_NAME);

    /* ---- Main polling loop ---- */
    while (g_running) {
        for (int i = 0; i < 3; i++) {
            int level = read_sensor(pins[i]);
            if (level < 0) {
                /* Sensor read error — skip this cycle */
                continue;
            }

            if (first_read[i]) {
                /* Record initial state without logging a transition */
                prev_state[i] = level;
                first_read[i] = 0;
            } else if (level != prev_state[i]) {
                log_state_change(i + 1, level);
                prev_state[i] = level;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");

cleanup_gpio:
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    return rc;
}

