/*
 * Si1182‑A‑GM heart-rate monitor for Raspberry Pi 4 Model B
 *
 * Reads the Si1182 once per second, applies a five-sample moving-average
 * filter, validates the filtered BPM (30–220), and logs
 * "YYYY-MM-DD HH:MM:SS,BPM" to heart_rate.csv.
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO 2 (pin 3, I2C bus 1)
 *   Si1182 SCL  -> GPIO 3 (pin 5, I2C bus 1)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o heart_rate heart_rate.c -lpigpio -lrt
 * Run:    sudo ./heart_rate
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1182 register map (subset) ---- */
#define SI1182_I2C_ADDR          0x50
#define SI1182_REG_PART_ID       0x00
#define SI1182_REG_HW_REV        0x01
#define SI1182_REG_SEQ_ID        0x02
#define SI1182_REG_INT_CFG       0x03
#define SI1182_REG_IRQ_ENABLE    0x04
#define SI1182_REG_IRQ_STATUS    0x05
#define SI1182_REG_MEAS_RATE0    0x08
#define SI1182_REG_MEAS_RATE1    0x09
#define SI1182_REG_ALS_RATE0     0x0A
#define SI1182_REG_ALS_RATE1     0x0B
#define SI1182_REG_PS_RATE0      0x0C
#define SI1182_REG_PS_RATE1      0x0D
#define SI1182_REG_PS_LED21      0x0F
#define SI1182_REG_PS1_DATA0     0x10
#define SI1182_REG_PS1_DATA1     0x11
#define SI1182_REG_ALS_VIS_DATA0 0x22
#define SI1182_REG_ALS_VIS_DATA1 0x23
#define SI1182_REG_ALS_IR_DATA0  0x24
#define SI1182_REG_ALS_IR_DATA1  0x25
#define SI1182_REG_HR_DATA0      0x26
#define SI1182_REG_HR_DATA1      0x27
#define SI1182_REG_HR_CONF       0x28
#define SI1182_REG_PARAM_WR      0x17
#define SI1182_REG_COMMAND       0x18

/* Si1182 command codes */
#define SI1182_CMD_RESET         0x01
#define SI1182_CMD_PARAM_QUERY   0x80
#define SI1182_CMD_PARAM_SET     0xA0
#define SI1182_CMD_PSALS_AUTO    0x0F

/* Expected PART_ID and HW_REV for Si1182-A-GM */
#define SI1182_PART_ID_EXPECTED  0x82
#define SI1182_HW_REV_EXPECTED   0x00

/* HR_CONF: enable HR measurement, 100 ms sample window */
#define SI1182_HR_CONF_VAL       0x01

/* HR_DATA0 (LSB) and HR_DATA1 (MSB) hold the 16-bit heart-rate value */

/* Moving-average filter window size */
#define MOVING_AVG_WINDOW_SIZE   5

/* BPM validation range */
#define MIN_BPM                  30
#define MAX_BPM                  220

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS                  1

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US       1000000

/* ---- Globals for signal-handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- Function prototypes ---- */
static int  si1182_write_reg(int handle, uint8_t reg, uint8_t value);
static int  si1182_read_reg(int handle, uint8_t reg, uint8_t *value);
static int  si1182_param_set(int handle, uint8_t param, uint8_t value);
static int  si1182_init(int handle);
static int  si1182_read_heart_rate(int handle, uint16_t *heart_rate);
static int  moving_average_filter(const uint16_t *data, int size, uint16_t *out);
static int  validate_heart_rate(uint16_t heart_rate);
static int  log_heart_rate(FILE *fp, uint16_t heart_rate);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1182 register                                */
/* ------------------------------------------------------------------ */
static int si1182_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1182 register                               */
/* ------------------------------------------------------------------ */
static int si1182_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Set a parameter via the PARAM_SET command                           */
/* ------------------------------------------------------------------ */
static int si1182_param_set(int handle, uint8_t param, uint8_t value)
{
    if (si1182_write_reg(handle, SI1182_REG_PARAM_WR, value) < 0)
        return -1;
    if (si1182_write_reg(handle, SI1182_REG_COMMAND,
                         SI1182_CMD_PARAM_SET | (param & 0x1F)) < 0)
        return -1;
    /* Small delay so the command is processed */
    gpioDelay(1000);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1182 sensor                                        */
/* ------------------------------------------------------------------ */
static int si1182_init(int handle)
{
    uint8_t part_id = 0, hw_rev = 0;

    /* 1. Verify sensor identity */
    if (si1182_read_reg(handle, SI1182_REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID: 0x%02X (expected 0x%02X). "
                        "Sensor not present or wrong device.\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }

    if (si1182_read_reg(handle, SI1182_REG_HW_REV, &hw_rev) < 0)
        return -1;
    if (hw_rev != SI1182_HW_REV_EXPECTED) {
        fprintf(stderr, "[WARN] Unexpected HW_REV: 0x%02X (expected 0x%02X). "
                        "Continuing anyway.\n",
                hw_rev, SI1182_HW_REV_EXPECTED);
    }

    /* 2. Reset the device */
    if (si1182_write_reg(handle, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms reset settling time */

    /* 3. Configure measurement rates (100 ms measurement window) */
    if (si1182_write_reg(handle, SI1182_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_ALS_RATE0, 0x00)  < 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_ALS_RATE1, 0x00)  < 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_RATE0, 0x00)   < 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_RATE1, 0x00)   < 0) return -1;

    /* 4. Configure PS LED current (LED1 = 22.4 mA, LED2 = 22.4 mA) */
    if (si1182_write_reg(handle, SI1182_REG_PS_LED21, 0x77) < 0) return -1;

    /* 5. Start autonomous PS+ALS measurement */
    if (si1182_write_reg(handle, SI1182_REG_COMMAND, SI1182_CMD_PSALS_AUTO) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit heart-rate value from HR_DATA0/HR_DATA1             */
/* ------------------------------------------------------------------ */
static int si1182_read_heart_rate(int handle, uint16_t *heart_rate)
{
    uint8_t lo = 0, hi = 0;

    if (si1182_read_reg(handle, SI1182_REG_HR_DATA0, &lo) < 0)
        return -1;
    if (si1182_read_reg(handle, SI1182_REG_HR_DATA1, &hi) < 0)
        return -1;

    *heart_rate = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Apply a moving-average filter to a window of heart-rate samples     */
/* ------------------------------------------------------------------ */
static int moving_average_filter(const uint16_t *data, int size, uint16_t *out)
{
    if (size <= 0 || out == NULL)
        return -1;

    uint32_t sum = 0;
    for (int i = 0; i < size; i++)
        sum += data[i];

    *out = (uint16_t)(sum / size);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Validate a heart-rate reading against the BPM range                 */
/* ------------------------------------------------------------------ */
static int validate_heart_rate(uint16_t heart_rate)
{
    return (heart_rate >= MIN_BPM && heart_rate <= MAX_BPM);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped BPM reading to the CSV log file                 */
/* ------------------------------------------------------------------ */
static int log_heart_rate(FILE *fp, uint16_t heart_rate)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, heart_rate) < 0) {
        fprintf(stderr, "[ERROR] fprintf() to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush() on log file failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Release all resources                                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t heart_rate_raw = 0;
    uint16_t heart_rate_filtered = 0;
    uint16_t heart_rate_history[MOVING_AVG_WINDOW_SIZE];
    int      history_index = 0;
    int      history_count = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1182_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1182_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si1182 sensor */
    if (si1182_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si1182 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    g_log_file = fopen("heart_rate.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open heart_rate.csv for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("Si1182 heart-rate monitor started.\n");
    printf("Logging to heart_rate.csv. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        /* Read the raw heart-rate value */
        if (si1182_read_heart_rate(g_i2c_handle, &heart_rate_raw) < 0) {
            fprintf(stderr, "[WARN] I2C read error; retrying next cycle.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Store the raw reading in the history buffer */
        heart_rate_history[history_index] = heart_rate_raw;
        history_index = (history_index + 1) % MOVING_AVG_WINDOW_SIZE;
        if (history_count < MOVING_AVG_WINDOW_SIZE)
            history_count++;

        /* Apply the moving-average filter */
        if (moving_average_filter(heart_rate_history, history_count,
                                  &heart_rate_filtered) < 0) {
            fprintf(stderr, "[WARN] Moving-average filter failed.\n");
            heart_rate_filtered = heart_rate_raw;
        }

        /* Validate the filtered heart-rate reading */
        if (validate_heart_rate(heart_rate_filtered)) {
            /* Log the heart-rate reading to the CSV file */
            if (log_heart_rate(g_log_file, heart_rate_filtered) < 0) {
                fprintf(stderr, "[WARN] Failed to log heart-rate reading.\n");
            }
        } else {
            fprintf(stderr, "[WARN] Invalid heart-rate reading: %u BPM. "
                            "Skipping logging.\n", heart_rate_filtered);
        }

        /* Wait for the next sampling interval */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

