/* ------------------------------------------------------------------ */
/* Apply a moving-average filter to a window of heart-rate samples     */
/* ------------------------------------------------------------------ */
static int moving_average_filter(const uint16_t *data, int size, uint16_t *out)
{
    if (size <= 0 || out == NULL)
        return -1;

    uint32_t sum = 0;
    for (int i = 0; i < size; i++)
        sum += data[i];

    *out = (uint16_t)(sum / size);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Validate a heart-rate reading against the BPM range                 */
/* ------------------------------------------------------------------ */
static int validate_heart_rate(uint16_t heart_rate)
{
    return (heart_rate >= MIN_BPM && heart_rate <= MAX_BPM);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped BPM reading to the CSV log file                 */
/* ------------------------------------------------------------------ */
static int log_heart_rate(FILE *fp, uint16_t heart_rate)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, heart_rate) < 0) {
        fprintf(stderr, "[ERROR] fprintf() to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush() on log file failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Release all resources                                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t heart_rate_raw = 0;
    uint16_t heart_rate_filtered = 0;
    uint16_t heart_rate_history[MOVING_AVG_WINDOW_SIZE];
    int      history_index = 0;
    int      history_count = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1182_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1182_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si1182 sensor */
    if (si1182_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si1182 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    g_log_file = fopen("heart_rate.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open heart_rate.csv for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("Si1182 heart-rate monitor started.\n");
    printf("Logging to heart_rate.csv. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        /* Read the raw heart-rate value */
        if (si1182_read_heart_rate(g_i2c_handle, &heart_rate_raw) < 0) {
            fprintf(stderr, "[WARN] I2C read error; retrying next cycle.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Store the raw reading in the history buffer */
        heart_rate_history[history_index] = heart_rate_raw;
        history_index = (history_index + 1) % MOVING_AVG_WINDOW_SIZE;
        if (history_count < MOVING_AVG_WINDOW_SIZE)
            history_count++;

        /* Apply the moving-average filter */
        if (moving_average_filter(heart_rate_history, history_count,
                                  &heart_rate_filtered) < 0) {
            fprintf(stderr, "[WARN] Moving-average filter failed.\n");
            heart_rate_filtered = heart_rate_raw;
        }

        /* Validate the filtered heart-rate reading */
        if (validate_heart_rate(heart_rate_filtered)) {
            /* Log the heart-rate reading to the CSV file */
            if (log_heart_rate(g_log_file, heart_rate_filtered) < 0) {
                fprintf(stderr, "[WARN] Failed to log heart-rate reading.\n");
            }
        } else {
            fprintf(stderr, "[WARN] Invalid heart-rate reading: %u BPM. "
                            "Skipping logging.\n", heart_rate_filtered);
        }

        /* Wait for the next sampling interval */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

