/*
 * KY-026 Flame Sensor Monitor — Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   KY-026 VCC  -> 3.3 V (pin 1)
 *   KY-026 GND  -> GND  (pin 9)
 *   KY-026 DO   -> GPIO17 (pin 11, BCM 17)
 *
 * The KY-026 digital output is active-low: LOW  = flame detected
 *                                        HIGH = no flame
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17, physical pin 11 */
#define LOG_FILE         "flame_log.txt"
#define POLL_INTERVAL_US 100000      /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_flame_event(FILE *log_fp)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    if (fprintf(log_fp, "%s - FLAME DETECTED\n", timestamp) < 0) {
        perror("fprintf(log_fp)");
        return -1;
    }

    if (fflush(log_fp) == EOF) {
        perror("fflush(log_fp)");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    if (install_signal_handlers() != 0)
        goto cleanup;

    /* ---- Open log file ---- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(" GPIO_CHIP_NAME ")");
        goto cleanup;
    }

    /* ---- Get GPIO line ---- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* ---- Request line as input with internal pull-up ---- */
    if (gpiod_line_request_input_flags(line, "ky026-flame",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags");
        goto cleanup;
    }

    printf("Flame sensor monitoring started on GPIO%d.\n", GPIO_LINE_OFFSET);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    int prev_value = 1;   /* assume no flame at startup (HIGH) */

    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        /* Falling edge: HIGH -> LOW (flame detected) */
        if (prev_value == 1 && value == 0) {
            printf("FLAME DETECTED\n");
            if (log_flame_event(log_fp) != 0) {
                fprintf(stderr, "Warning: failed to log flame event.\n");
            }
        }

        prev_value = value;
        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);
    if (log_fp != NULL)
        fclose(log_fp);

    return ret;
}

