 *   On a rising edge (idle 0 V -> touched 3.3 V) increments the counter
 *   (wraps 0..255) and drives the eight output pins.
 *   Logs each event to touch_log.txt with an ISO-8601 UTC timestamp.
 *   Handles SIGINT / SIGTERM for graceful shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 10
#define STABILIZE_MS 200

/* BCM pin numbers for the TTP226 OUT lines */
static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};

/* BCM pin numbers for the 8-bit counter output lines (bit 0 on 17, bit 7 on 24) */
static const unsigned int counter_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Write a single bit to a GPIO line.
 * Returns 0 on success, -1 on error.
 */
static int write_bit(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: gpiod_line_set_value failed on line %u: %s\n",
                gpiod_line_offset(line), strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Write the eight counter bits to the output lines.
 * Returns 0 on success, -1 on error.
 */
static int write_counter(struct gpiod_line *lines[NUM_CHANNELS], int counter)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (write_bit(lines[i], (counter >> i) & 1) < 0)
            return -1;
    }
    return 0;
}

/*
 * Log a touch event to touch_log.txt and stdout.
 * Returns 0 on success, -1 on error.
 */
static int log_touch_event(int channel, int counter)
{
    FILE *fp = fopen("touch_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Warning: time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "Warning: gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "Warning: strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter) < 0) {
        fprintf(stderr, "Warning: fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose on log failed: %s\n", strerror(errno));
        return -1;
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter);
    fflush(stdout);
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_lines[NUM_CHANNELS];
    struct gpiod_line *counter_lines[NUM_CHANNELS];
    int counter = 0;
    int prev_touched[NUM_CHANNELS] = {0};
    int ret = EXIT_FAILURE;

    /* Initialize all line pointers to NULL for safe cleanup */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        touch_lines[i] = NULL;
        counter_lines[i] = NULL;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open the default gpiochip (gpiochip0 on Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Get the touch sensor input lines */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        touch_lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (!touch_lines[i]) {
            fprintf(stderr, "Error: gpiod_chip_get_line failed for touch pin %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Get the counter output lines */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, counter_pins[i]);
        if (!counter_lines[i]) {
            fprintf(stderr, "Error: gpiod_chip_get_line failed for counter pin %u: %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request all touch lines as inputs */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input(touch_lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "Error: gpiod_line_request_input failed for touch pin %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request all counter lines as outputs, initial value 0 */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_output(counter_lines[i], "ttp226-counter", 0) < 0) {
            fprintf(stderr, "Error: gpiod_line_request_output failed for counter pin %u: %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Write the initial counter value to the output lines */
    if (write_counter(counter_lines, counter) < 0) {
        fprintf(stderr, "Error: initial write_counter failed\n");
        goto cleanup;
    }

    printf("Touch sensor counter started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Allow the sensor to settle after power-on */
    usleep(STABILIZE_MS * 1000);

    /* Main polling loop */
    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(touch_lines[i]);
            if (val < 0) {
                fprintf(stderr, "Warning: gpiod_line_get_value failed for touch pin %u: %s\n",
                        touch_pins[i], strerror(errno));
                continue;
            }

            /* Detect rising edge: idle 0 -> touched 1 */
            if (val == 1 && prev_touched[i] == 0) {
                counter = (counter + 1) & 0xFF;

                if (write_counter(counter_lines, counter) < 0) {
                    fprintf(stderr, "Warning: write_counter failed for channel %d\n", i + 1);
                }

                if (log_touch_event(i + 1, counter) < 0) {
                    fprintf(stderr, "Warning: log_touch_event failed for channel %d\n", i + 1);
                }
            }

            prev_touched[i] = val;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Reset all output lines to 0 */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (counter_lines[i]) {
            gpiod_line_set_value(counter_lines[i], 0);
            gpiod_line_release(counter_lines[i]);
        }
        if (touch_lines[i])
            gpiod_line_release(touch_lines[i]);
    }

    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

