    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, s1, s2, s3, s4) < 0) {
        fprintf(stderr, "Error: fprintf to CSV failed.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on CSV file.\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        perror("Error opening CSV file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
            fprintf(stderr, "Error: failed to write CSV header.\n");
            fclose(fp);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "Warning: fflush failed after header.\n");
        }
    }

    printf("Monitoring KY-033 sensors on GPIO17,18,27,22. Press Ctrl+C to stop.\n");

    while (program_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);
        int s4 = read_sensor(SENSOR4_PIN);

        if (log_data(fp, s1, s2, s3, s4) != 0) {
            fprintf(stderr, "Error: failed to log data.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    if (fclose(fp) != 0) {
        perror("Warning: fclose failed");
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

