#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_INTERVAL_US 100000   /* 100 ms */
#define DEBOUNCE_US 50000         /* 50 ms  */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_number)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s, Sensor %d tilted\n",
                timestamp, sensor_number) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;
    int prev_state1 = 1;   /* assume inactive (pull-up) at startup */
    int prev_state2 = 1;
    uint32_t last_change1 = 0;
    uint32_t last_change2 = 0;

    /* ---- pigpio init ---- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure sensor lines ---- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", SENSOR_1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", SENSOR_2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-up so an unconnected sensor reads high. */
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO%d\n", SENSOR_1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO%d\n", SENSOR_2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started.  GPIO%d & GPIO%d.  Ctrl+C to exit.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);

    /* ---- main polling loop ---- */
    while (g_running) {
        int val1 = gpioRead(SENSOR_1_GPIO);
        int val2 = gpioRead(SENSOR_2_GPIO);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "gpioRead error (s1=%d, s2=%d)\n", val1, val2);
            /* Brief pause before retrying to avoid log flooding. */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint32_t now = gpioTick();

        /* Sensor 1: detect falling edge (active-low) */
        if (val1 == 0 && prev_state1 == 1) {
            if ((now - last_change1) > DEBOUNCE_US) {
                log_event(1);
                last_change1 = now;
            }
        }
        prev_state1 = val1;

        /* Sensor 2: detect falling edge (active-low) */
        if (val2 == 0 && prev_state2 == 1) {
            if ((now - last_change2) > DEBOUNCE_US) {
                log_event(2);
                last_change2 = now;
            }
        }
        prev_state2 = val2;

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

