        fprintf(stderr, "pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- configure sensor lines ---- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", SENSOR_1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", SENSOR_2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-up so an unconnected sensor reads high. */
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO%d\n", SENSOR_1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO%d\n", SENSOR_2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started.  GPIO%d & GPIO%d.  Ctrl+C to exit.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO);

    /* ---- main polling loop ---- */
    while (g_running) {
        int val1 = gpioRead(SENSOR_1_GPIO);
        int val2 = gpioRead(SENSOR_2_GPIO);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "gpioRead error (s1=%d, s2=%d)\n", val1, val2);
            /* Brief pause before retrying to avoid log flooding. */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint32_t now = gpioTick();

        /* Sensor 1: detect falling edge (active-low) */
        if (val1 == 0 && prev_state1 == 1) {
            if ((now - last_change1) > DEBOUNCE_US) {
                log_event(1);
                last_change1 = now;
            }
        }
        prev_state1 = val1;

        /* Sensor 2: detect falling edge (active-low) */
        if (val2 == 0 && prev_state2 == 1) {
            if ((now - last_change2) > DEBOUNCE_US) {
                log_event(2);
                last_change2 = now;
            }
        }
        prev_state2 = val2;

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

