        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead failed (s1=%d, s2=%d)\n", s1, s2);
            break;
        }

        int led_state = (s1 == 0 && s2 == 0) ? 1 : 0;

        if (gpioWrite(LED_PIN, led_state) != 0) {
            fprintf(stderr, "gpioWrite(LED_PIN) failed\n");
            break;
        }

        if (log_data(s1, s2, led_state) != 0) {
            fprintf(stderr, "Logging failed\n");
            break;
        }

        gpioDelay(POLL_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup_all:
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
cleanup_gpio:
    /* Ensure LED is off before terminating */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return ret;
}

