#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MIC_GPIO      4
#define LED_GPIO      17
#define SAMPLE_PERIOD_US 125   /* 8 kHz polling */
#define LED_ON_US     100000  /* 100 ms LED on-time */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only sets a flag.              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Print a millisecond-precision timestamp to stdout.                  */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }

    char buf[40];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("%s.%03ld\n", buf, ts.tv_nsec / 1000000L);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install SIGINT handler (async-signal-safe) ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(MIC_GPIO=%d, PI_INPUT) failed\n", MIC_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(LED_GPIO=%d, PI_OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is OFF at start */
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite(LED_GPIO=%d, 0) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound-peak detection started.\n");
    printf("  Microphone : GPIO%d (BCM, physical pin 7)\n", MIC_GPIO);
    printf("  LED        : GPIO%d (BCM, physical pin 11)\n", LED_GPIO);
    printf("  Sampling   : ~8 kHz, LED on 100 ms per peak\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int level = gpioRead(MIC_GPIO);
        if (level < 0) {
            fprintf(stderr, "gpioRead(MIC_GPIO=%d) failed\n", MIC_GPIO);
            break;
        }

        if (level == 1) {
            print_timestamp();

            /* Turn LED on */
            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "gpioWrite(LED_GPIO=%d, 1) failed\n", LED_GPIO);
                break;
            }

            /* Keep LED on for 100 ms (interruptible by signal) */
            uint32_t elapsed = 0;
            while (g_running && elapsed < LED_ON_US) {
                gpioDelay(1000);  /* 1 ms slices */
                elapsed += 1000;
            }

            /* Turn LED off */
            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "gpioWrite(LED_GPIO=%d, 0) failed\n", LED_GPIO);
                break;
            }
        }

        /* Sleep for the remainder of the 125 us period */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Clean shutdown ---- */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

