/*
 * Si1175 ALS Reader for Raspberry Pi 4 Model B
 *
 * Reads the Si1175 ALS_VIS_DATA0 (LSB) and ALS_VIS_DATA1 (MSB) registers
 * every 100 ms and logs the 16-bit raw value to the console.
 *
 * Wiring:
 *   Si1175 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   Si1175 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   Si1175 VDD -> 3.3 V
 *   Si1175 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o si1175_als si1175_als.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./si1175_als
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1175 I2C configuration ---- */
#define I2C_BUS        1
#define SI1175_ADDR    0x44          /* Si1175 default I2C address (ADDR pin tied to GND) */

/* ---- Si1175 register addresses ---- */
#define REG_PART_ID    0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23

/* ---- Expected PART_ID for Si1175 ---- */
#define SI1175_PART_ID 0x75

/* ---- Timing ---- */
#define SAMPLE_PERIOD_US 100000   /* 100 ms */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a Si1175 register                           */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int si1175_read_byte(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers    */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int si1175_read_word(int handle, uint8_t reg_lsb, uint8_t reg_msb, uint16_t *out)
{
    uint8_t lsb, msb;

    if (si1175_read_byte(handle, reg_lsb, &lsb) != 0)
        return -1;
    if (si1175_read_byte(handle, reg_msb, &msb) != 0)
        return -1;

    *out = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1175 sensor                                       */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int si1175_init(int handle)
{
    uint8_t part_id;

    /* Verify sensor presence by reading PART_ID */
    if (si1175_read_byte(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID — sensor may be absent or bus error.\n");
        return -1;
    }

    if (part_id != SI1175_PART_ID) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID: 0x%02X (expected 0x%02X). "
                        "Wrong sensor or wrong address?\n",
                        part_id, SI1175_PART_ID);
        return -1;
    }

    printf("[INFO] Si1175 detected (PART_ID = 0x%02X).\n", part_id);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — close I2C handle and terminate pigpio              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to Si1175 */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1175_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si1175_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si1175 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Reading ALS_VIS every %d ms. Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_US / 1000);

    /* Main sampling loop */
    while (g_running) {
        uint16_t als_raw;

        if (si1175_read_word(g_i2c_handle, REG_ALS_VIS_DATA0, REG_ALS_VIS_DATA1, &als_raw) == 0) {
            printf("ALS_VIS: %u\n", als_raw);
        } else {
            fprintf(stderr, "[WARN] Failed to read ALS data — continuing.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_PERIOD_US / 10);
        }
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

