#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN   2
#define MIDDLE_SENSOR_PIN 3
#define RIGHT_SENSOR_PIN  4
#define POLL_INTERVAL_MS  100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *middle_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get each GPIO line individually */
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    if (left_line == NULL) {
        perror("gpiod_chip_get_line (left)");
        goto cleanup;
    }

    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    if (middle_line == NULL) {
        perror("gpiod_chip_get_line (middle)");
        goto cleanup;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (right_line == NULL) {
        perror("gpiod_chip_get_line (right)");
        goto cleanup;
    }

    /* Request each line as input */
    if (gpiod_line_request_input(left_line, "3-way-tracking-left") < 0) {
        perror("gpiod_line_request_input (left)");
        goto cleanup;
    }

    if (gpiod_line_request_input(middle_line, "3-way-tracking-middle") < 0) {
        perror("gpiod_line_request_input (middle)");
        goto cleanup;
    }

    if (gpiod_line_request_input(right_line, "3-way-tracking-right") < 0) {
        perror("gpiod_line_request_input (right)");
        goto cleanup;
    }

    printf("3-Way Tracking Sensor Polling Started (L:GPIO2, M:GPIO3, R:GPIO4)\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int left_val, middle_val, right_val;

        left_val = gpiod_line_get_value(left_line);
        if (left_val < 0) {
            perror("gpiod_line_get_value (left)");
            goto cleanup;
        }

        middle_val = gpiod_line_get_value(middle_line);
        if (middle_val < 0) {
            perror("gpiod_line_get_value (middle)");
            goto cleanup;
        }

        right_val = gpiod_line_get_value(right_line);
        if (right_val < 0) {
            perror("gpiod_line_get_value (right)");
            goto cleanup;
        }

        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines individually (safe to call even if request failed) */
    if (left_line != NULL)
        gpiod_line_release(left_line);
    if (middle_line != NULL)
        gpiod_line_release(middle_line);
    if (right_line != NULL)
        gpiod_line_release(right_line);

    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");

    return ret;
}

