#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define FADE_STEPS    50
#define FADE_DELAY_US (5000000 / FADE_STEPS)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void set_led_color(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN,   red)   < 0) syslog(LOG_ERR, "gpioPWM(RED) failed");
    if (gpioPWM(GREEN_PIN, green) < 0) syslog(LOG_ERR, "gpioPWM(GREEN) failed");
    if (gpioPWM(BLUE_PIN,  blue)  < 0) syslog(LOG_ERR, "gpioPWM(BLUE) failed");
}

static void turn_off_led(void)
{
    set_led_color(0, 0, 0);
}

static void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b)
{
    if (s <= 0.0f) {
        *r = *g = *b = (int)(v * 255.0f);
        return;
    }

    float hh = h;
    if (hh >= 360.0f) hh -= 360.0f;
    if (hh < 0.0f)   hh += 360.0f;

    hh /= 60.0f;
    int i = (int)hh;
    float ff = hh - i;
    float p = v * (1.0f - s);
    float q = v * (1.0f - (s * ff));
    float t = v * (1.0f - (s * (1.0f - ff)));

    switch (i) {
        case 0:  *r = (int)(v * 255.0f); *g = (int)(t * 255.0f); *b = (int)(p * 255.0f); break;
        case 1:  *r = (int)(q * 255.0f); *g = (int)(v * 255.0f); *b = (int)(p * 255.0f); break;
        case 2:  *r = (int)(p * 255.0f); *g = (int)(v * 255.0f); *b = (int)(t * 255.0f); break;
        case 3:  *r = (int)(p * 255.0f); *g = (int)(q * 255.0f); *b = (int)(v * 255.0f); break;
        case 4:  *r = (int)(t * 255.0f); *g = (int)(p * 255.0f); *b = (int)(v * 255.0f); break;
        default: *r = (int)(v * 255.0f); *g = (int)(p * 255.0f); *b = (int)(q * 255.0f); break;
    }
}

static void fade_to_color(int target_red, int target_green, int target_blue)
{
    int current_red, current_green, current_blue;
    int red_step, green_step, blue_step;

    set_led_color(0, 0, 0);
    gpioDelay(100000);

    if (gpioRead(RED_PIN)   < 0) current_red   = 0; else current_red   = gpioGetPWMdutycycle(RED_PIN);
    if (gpioRead(GREEN_PIN) < 0) current_green = 0; else current_green = gpioGetPWMdutycycle(GREEN_PIN);
    if (gpioRead(BLUE_PIN)  < 0) current_blue  = 0; else current_blue  = gpioGetPWMdutycycle(BLUE_PIN);

    red_step   = (target_red   - current_red)   / FADE_STEPS;
    green_step = (target_green - current_green) / FADE_STEPS;
    blue_step  = (target_blue  - current_blue)  / FADE_STEPS;

    for (int i = 0; i < FADE_STEPS && g_running; i++) {
        current_red   += red_step;
        current_green += green_step;
        current_blue  += blue_step;

        if (current_red   < 0)   current_red   = 0;
        if (current_green < 0)   current_green = 0;
        if (current_blue  < 0)   current_blue  = 0;
        if (current_red   > 255) current_red   = 255;
        if (current_green > 255) current_green = 255;
        if (current_blue  > 255) current_blue  = 255;

        set_led_color(current_red, current_green, current_blue);
        gpioDelay(FADE_DELAY_US);
    }

    set_led_color(target_red, target_green, target_blue);
}

int main(void)
{
    openlog("rgb_led_fader", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(RED) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(GREEN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(BLUE) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency(RED) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency(GREEN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency(BLUE) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange(RED) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange(GREEN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange(BLUE) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        float hue = (float)(rand() % 360);
        float saturation = 1.0f;
        float value = 1.0f;

        int red, green, blue;
        hsv_to_rgb(hue, saturation, value, &red, &green, &blue);

        fade_to_color(red, green, blue);

        if (g_running) {
            gpioDelay(5000000);
        }
    }

    turn_off_led();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

