#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29

#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA   0x94
#define TCS34725_RDATA   0x96
#define TCS34725_GDATA   0x98
#define TCS34725_BDATA   0x9A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

#define RED_THRESHOLD 200
#define LED_GPIO      17

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[1] << 8 | buf[0];
    return 0;
}

static int tcs34725_init(int fd) {
    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    gpioDelay(3000);

    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_CONTROL, 0x00) < 0) return -1;

    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    gpioDelay(3000);

    return 0;
}

static int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_reg16(fd, TCS34725_CDATA, clear) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_RDATA, red)   < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_GDATA, green) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_BDATA, blue)  < 0) return -1;
    return 0;
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        i2c_write_reg8(g_i2c_fd, TCS34725_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n", TCS34725_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(g_i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TCS34725 initialized. Reading data every 200ms...\n");

    while (g_running) {
        uint16_t clear, red, green, blue;

        if (tcs34725_read_data(g_i2c_fd, &clear, &red, &green, &blue) < 0) {
            fprintf(stderr, "Read error, attempting re-initialization...\n");
            if (tcs34725_init(g_i2c_fd) < 0) {
                fprintf(stderr, "Re-initialization failed, exiting.\n");
                break;
            }
            gpioDelay(200000);
            continue;
        }

        printf("Clear: %5u, Red: %5u, Green: %5u, Blue: %5u\n", clear, red, green, blue);

        if (red > RED_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(200000);
    }

    gpioWrite(LED_GPIO, 0);
    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

