    return 0;
}

/* ---- WS2812B via hardware PWM (libpwm) ---- */

static int pwm_setup(void)
{
    int fd = open("/dev/pwmchip0", O_RDWR);
    if (fd < 0) {
        perror("open /dev/pwmchip0");
        return -1;
    }

    struct pwm_export_args exp = { .channel = PWM_CHANNEL };
    if (ioctl(fd, PWM_IOCTL_EXPORT, &exp) < 0) {
        perror("PWM_IOCTL_EXPORT");
        close(fd);
        return -1;
    }

    struct pwm_period_args per = {
        .channel = PWM_CHANNEL,
        .period  = PWM_PERIOD_NS,
    };
    if (ioctl(fd, PWM_IOCTL_SET_PERIOD, &per) < 0) {
        perror("PWM_IOCTL_SET_PERIOD");
        ioctl(fd, PWM_IOCTL_UNEXPORT, &exp);
        close(fd);
        return -1;
    }

    struct pwm_duty_cycle_args duty = {
        .channel = PWM_CHANNEL,
        .duty_cycle = 0,
    };
    if (ioctl(fd, PWM_IOCTL_SET_DUTY_CYCLE, &duty) < 0) {
        perror("PWM_IOCTL_SET_DUTY_CYCLE");
        ioctl(fd, PWM_IOCTL_UNEXPORT, &exp);
        close(fd);
        return -1;
    }

    struct pwm_enable_args en = { .channel = PWM_CHANNEL, .enable = 1 };
    if (ioctl(fd, PWM_IOCTL_ENABLE, &en) < 0) {
        perror("PWM_IOCTL_ENABLE");
        ioctl(fd, PWM_IOCTL_UNEXPORT, &exp);
        close(fd);
        return -1;
    }

    return fd;
}

static void pwm_set_duty(int fd, uint32_t duty_ns)
{
    struct pwm_duty_cycle_args duty = {
        .channel = PWM_CHANNEL,
        .duty_cycle = duty_ns,
    };
    ioctl(fd, PWM_IOCTL_SET_DUTY_CYCLE, &duty);
}

static void pwm_teardown(int fd)
{
    struct pwm_enable_args en = { .channel = PWM_CHANNEL, .enable = 0 };
    ioctl(fd, PWM_IOCTL_ENABLE, &en);
    struct pwm_unexport_args unexp = { .channel = PWM_CHANNEL };
    ioctl(fd, PWM_IOCTL_UNEXPORT, &unexp);
    close(fd);
}

/* ---- WS2812B bitstream generation ---- */

static void ws2812b_send_byte(int fd, uint8_t byte)
{
    for (int i = 7; i >= 0; i--) {
        uint32_t duty = (byte >> i) & 1 ? 1000 : 300;
        pwm_set_duty(fd, duty);
        usleep(1);
    }
}

static void ws2812b_send_leds(int fd, const uint8_t *grb, int num_leds)
{
    for (int i = 0; i < num_leds; i++) {
        ws2812b_send_byte(fd, grb[i * 3 + 1]); /* G */
        ws2812b_send_byte(fd, grb[i * 3 + 0]); /* R */
        ws2812b_send_byte(fd, grb[i * 3 + 2]); /* B */
    }
}

/* ---- Lux -> brightness mapping ---- */

static void map_lux_to_leds(float lux, uint8_t *grb, int num_leds)
{
    float log_lux = log10f(lux + 1.0f);
    float norm = log_lux / log10f(1000.0f);
    if (norm < 0.0f) norm = 0.0f;
    if (norm > 1.0f) norm = 1.0f;

    float brightness = norm * 255.0f;

    for (int i = 0; i < num_leds; i++) {
        uint8_t val = (uint8_t)brightness;
        grb[i * 3 + 0] = val; /* R */
        grb[i * 3 + 1] = val; /* G */
        grb[i * 3 + 2] = val; /* B */
    }
}

/* ---- Main ---- */

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int pwm_fd = pwm_setup();
    if (pwm_fd < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t *grb = malloc(NUM_LEDS * 3);
    if (!grb) {
        perror("malloc");
        pwm_teardown(pwm_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("BH1750 light sensor -> WS2812B LED strip running. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        bool ok = false;

        for (int attempt = 0; attempt < 3 && g_running; attempt++) {
            if (bh1750_read_lux(i2c_fd, &lux) == 0) {
                ok = true;
                break;
            }
            fprintf(stderr, "BH1750 read attempt %d failed, retrying...\n", attempt + 1);
            usleep(100000);
        }

        if (!ok) {
            fprintf(stderr, "BH1750 read failed after retries, skipping cycle.\n");
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        map_lux_to_leds(lux, grb, NUM_LEDS);
        ws2812b_send_leds(pwm_fd, grb, NUM_LEDS);

        printf("Lux: %.2f  ->  LEDs: %s\n", lux,
               lux < 100.0f ? "OFF" : "ON");

        usleep(LOOP_DELAY_MS * 1000);
    }

    /* ---- Graceful shutdown ---- */
    memset(grb, 0, NUM_LEDS * 3);
    ws2812b_send_leds(pwm_fd, grb, NUM_LEDS);
    free(grb);
    pwm_teardown(pwm_fd);
    close(i2c_fd);

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

