/*
 * Raspberry Pi Zero W — BH1750 ambient light sensor → APA102 LED strip brightness
 *
 * Wiring:
 *   BH1750 SDA  → GPIO2  (pin 3, I2C bus 1)
 *   BH1750 SCL  → GPIO3  (pin 5, I2C bus 1)
 *   BH1750 VCC  → 3.3 V
 *   BH1750 GND  → GND
 *   APA102 DIN  → GPIO10 (pin 19, SPI0 MISO)
 *   APA102 VCC  → 5 V
 *   APA102 GND  → GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o light_led light_led.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_PWR_ON  0x01
#define BH1750_CONT_HRES 0x10   /* 1 lux resolution, ~120 ms conversion */

#define SPI_BUS        "/dev/spidev0.0"
#define SPI_SPEED_HZ   1000000U
#define SPI_BITS       8
#define SPI_DELAY_US   0

#define NUM_LEDS       10
#define BRIGHTNESS_MAX 31

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* BH1750                                                               */
/* ------------------------------------------------------------------ */

static int bh1750_init(int fd)
{
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0)
        return -1;
    usleep(10000);  /* power-on settle */
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0)
        return -1;

    usleep(120000);  /* 120 ms conversion time */

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* APA102                                                               */
/* ------------------------------------------------------------------ */

static int apa102_init(int fd)
{
    uint8_t zero = 0x00;
    ssize_t n;

    /* Start frame: 4 × 0x00 */
    n = write(fd, &zero, 4);
    if (n < 0 || n != 4) {
        fprintf(stderr, "SPI start frame failed: %s\n", strerror(errno));
        return -1;
    }

    /* End frame: 4 × 0xFF */
    n = write(fd, &zero, 4);
    if (n < 0 || n != 4) {
        fprintf(stderr, "SPI end frame failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int apa102_set_brightness(int fd, uint8_t brightness)
{
    if (brightness > BRIGHTNESS_MAX)
        brightness = BRIGHTNESS_MAX;

    uint8_t frame[4 * NUM_LEDS];
    memset(frame, 0x00, sizeof(frame));

    /*
     * APA102 frame layout (32 bits per LED):
     *   byte 0: 0xE0  global start
     *   byte 1: 0x00  brightness (0x00 = off, 0x1F = full)
     *   byte 2: 0x00  blue
     *   byte 3: 0x00  green
     *   byte 4: 0x00  red
     */
    for (int i = 0; i < NUM_LEDS; i++) {
        frame[4 * i + 0] = 0xE0;
        frame[4 * i + 1] = brightness;
        frame[4 * i + 2] = 0x00;  /* blue */
        frame[4 * i + 3] = 0x00;  /* green */
        frame[4 * i + 4] = 0x00;  /* red */
    }

    ssize_t n = write(fd, frame, sizeof(frame));
    if (n < 0 || (size_t)n != sizeof(frame)) {
        fprintf(stderr, "SPI write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                 */
/* ------------------------------------------------------------------ */

int main(void)
{
    int i2c_fd = -1;
    int spi_fd = -1;
    int rc = EXIT_FAILURE;

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open I2C bus ---- */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    /* ---- open SPI bus ---- */
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_BUS, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- init sensors ---- */
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 not responding at 0x%02X\n", BH1750_ADDR);
        goto cleanup;
    }

    if (apa102_init(spi_fd) < 0) {
        fprintf(stderr, "APA102 init failed\n");
        goto cleanup;
    }

    printf("Light sensor → LED strip control started.\n");
    printf("Press Ctrl+C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error; turning off LEDs.\n");
            apa102_set_brightness(spi_fd, 0);
            usleep(100000);
            continue;
        }

        /* Map 0–1000 lux → 0–31 brightness */
        uint8_t brightness = (uint8_t)((lux / 1000.0f) * BRIGHTNESS_MAX);
        if (brightness > BRIGHTNESS_MAX)
            brightness = BRIGHTNESS_MAX;

        if (apa102_set_brightness(spi_fd, brightness) < 0) {
            fprintf(stderr, "LED write error; continuing.\n");
        }

        printf("Lux: %.2f  Brightness: %u\n", lux, brightness);
        usleep(500000);  /* 0.5 s loop period */
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    apa102_set_brightness(spi_fd, 0);
    rc = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0)
        close(spi_fd);
    if (i2c_fd >= 0)
        close(i2c_fd);
    return rc;
}

