/*
 * Raspberry Pi 3 Model B+ — BH1750 ambient-light sensor → APA102 LED strip brightness
 *
 * Hardware:
 *   - 1× BH1750 on I2C bus 1, addresses 0x23 (ADDR pin low) or 0x5C (ADDR pin high)
 *   - 1× APA102 RGB LED strip (SPI mode 0, 12 LEDs)
 *     MOSI → GPIO10 (BCM), SCLK → GPIO11 (BCM), VCC → 5 V, GND → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_strip light_strip.c -lgpiod -lpigpio -lrt
 * Run:
 *   sudo ./light_strip
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define BH1750_ADDR_1        0x23
#define BH1750_ADDR_2        0x5C
#define NUM_SENSORS          3
#define SPI_CHANNEL          0          /* CE0 on GPIO8 */
#define SPI_SPEED            1000000    /* 1 MHz */
#define SPI_FLAGS            0          /* Mode 0, active-low CE */
#define NUM_LEDS             12
#define BH1750_CONV_MS       180        /* max conversion time */
#define LOOP_DELAY_US        100000     /* 100 ms */
#define FADE_STEP_MS         5          /* 5 ms per fade step */
#define FADE_STEPS           (500 / FADE_STEP_MS)
#define FADE_DELAY_US        (FADE_STEP_MS * 1000)

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handles[NUM_SENSORS];
static int      g_spi_handle = -1;
static int      g_pigpio_initialized = 0;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- BH1750 helpers ------------------------------ */

/*
 * Open the BH1750 at the given address.
 * Returns a valid pigpio handle (>= 0) or -1 on failure.
 */
static int bh1750_open(int bus, int addr)
{
    int h = i2cOpen(bus, addr, 0);
    if (h < 0) {
        fprintf(stderr, "[BH1750 0x%02X] i2cOpen failed: %s\n",
                addr, strerror(errno));
        return -1;
    }
    return h;
}

/*
 * Trigger a one-time high-resolution measurement and read the two-byte
 * result.  Returns the lux value (>= 0) on success, or -1 on error.
 */
static int bh1750_read_lux(int handle)
{
    /*
     * Command byte 0x10: one-time high-resolution mode, no wait state.
     * Conversion time is ~120 ms (max 180 ms).
     */
    if (i2cWriteByte(handle, 0x10) < 0) {
        fprintf(stderr, "[BH1750] i2cWriteByte failed: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(BH1750_CONV_MS * 1000);

    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "[BH1750] i2cReadDevice returned %d: %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return (int)raw;
}

/* --------------------------- APA102 helpers ------------------------------ */

/*
 * Send a full frame of `num_leds` RGB triplets (4 bytes each) to the APA102.
 * Each triplet is: [0xE0, B, G, R].  Global brightness is 0x0F (max).
 */
static void apa102_send_frame(int handle, const uint8_t *colors, int num_leds)
{
    if (num_leds <= 0)
        return;

    /* Start frame: 4× 0x00 */
    uint8_t start[4] = {0x00, 0x00, 0x00, 0x00};
    if (spiWrite(handle, (char *)start, 4) < 0) {
        fprintf(stderr, "[APA102] spiWrite start failed: %s\n", strerror(errno));
        return;
    }

    /* LED data: 4 bytes per LED, global brightness 0x0F */
    uint8_t led[4];
    led[0] = 0xE0;  /* global brightness + start frame */
    led[1] = colors[1];  /* blue  */
    led[2] = colors[2];  /* green */
    led[3] = colors[3];  /* red   */

    for (int i = 0; i < num_leds; i++) {
        if (spiWrite(handle, (char *)led, 4) < 0) {
            fprintf(stderr, "[APA102] spiWrite LED %d failed: %s\n",
                    i, strerror(errno));
            return;
        }
    }

    /* End frame: 4× 0xFF */
    uint8_t end[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    if (spiWrite(handle, (char *)end, 4) < 0) {
        fprintf(stderr, "[APA102] spiWrite end failed: %s\n", strerror(errno));
    }
}

/* --------------------------- Fade logic --------------------------------- */

/*
 * Smoothly fade the strip from its current brightness to `target` over
 * FADE_STEPS steps, each FADE_STEP_MS long.
 */
static void apa102_fade(int handle, int target, int num_leds)
{
    static uint8_t current[4] = {0x00, 0x00, 0x00, 0x00};
    static bool    initialized = false;

    if (!initialized) {
        current[1] = current[2] = current[3] = 0x00;
        initialized = true;
    }

    int cur_b = current[1];  /* blue channel is brightness proxy */

    if (cur_b == target)
        return;

    int step = (target > cur_b) ? 1 : -1;
    int steps_remaining = abs(target - cur_b);

    if (steps_remaining > FADE_STEPS)
        steps_remaining = FADE_STEPS;

    for (int i = 0; i < steps_remaining && g_running; i++) {
        cur_b += step;
        current[1] = (uint8_t)cur_b;
        current[2] = (uint8_t)cur_b;
        current[3] = (uint8_t)cur_b;
        apa102_send_frame(handle, current, num_leds);
        gpioDelay(FADE_DELAY_US);
    }
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    /* Turn off LED strip */
    if (g_spi_handle >= 0) {
        uint8_t off[4] = {0x00, 0x00, 0x00, 0x00};
        for (int i = 0; i < NUM_LEDS; i++)
            spiWrite(g_spi_handle, (char *)off, 4);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Close I2C handles */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_i2c_handles[i] >= 0) {
            i2cClose(g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }

    if (g_pigpio_initialized) {
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_initialized = 1;

    /* Open SPI for APA102 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open I2C handles for BH1750 sensors */
    int addrs[NUM_SENSORS] = {BH1750_ADDR_1, BH1750_ADDR_2, 0x00};
    for (int i = 0; i < NUM_SENSORS; i++) {
        g_i2c_handles[i] = bh1750_open(I2C_BUS, addrs[i]);
        if (g_i2c_handles[i] < 0) {
            fprintf(stderr, "Warning: BH1750 at 0x%02X not found; "
                            "sensor %d will be skipped.\n",
                            addrs[i], i + 1);
        }
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Light-controlled LED strip running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int valid_readings = 0;
        long sum = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (g_i2c_handles[i] < 0)
                continue;

            int lux = bh1750_read_lux(g_i2c_handles[i]);
            if (lux >= 0) {
                sum += lux;
                valid_readings++;
            } else {
                fprintf(stderr, "Warning: BH1750 sensor %d read failed; "
                                "will retry next cycle.\n", i + 1);
            }
        }

        if (valid_readings == 0) {
            fprintf(stderr, "Error: no valid BH1750 readings; "
                            "check wiring and I2C addresses.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double avg = (double)sum / valid_readings;

        /*
         * Map lux to brightness: 0 lux → 0, 10000 lux → 255.
         * Clamp to [0, 255].
         */
        int brightness = (int)(avg / 100.0);
        if (brightness < 0)   brightness = 0;
        if (brightness > 255) brightness = 255;

        printf("Average lux: %.2f  →  brightness: %d\n", avg, brightness);

        apa102_fade(g_spi_handle, brightness, NUM_LEDS);

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

