#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VEML7700_ADDR  0x48

#define REG_CONFIG     0x00
#define REG_ALS_WH     0x01
#define REG_ALS_WL     0x02
#define REG_ALS_DATA   0x04

#define GPIO_LED       18
#define NUM_LEDS       8

#define I2C_RETRIES    3
#define I2C_RETRY_DELAY_MS 100
#define LOOP_DELAY_MS  200

#define GAMMA_TABLE_SIZE 256

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3] = { reg, (uint8_t)(value >> 8), (uint8_t)(value & 0xFF) };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* VEML7700                                                             */
/* ------------------------------------------------------------------ */
static int veml7700_init(int fd)
{
    /*
     * CONFIG register (0x00):
     *   ALS_SD = 0 (power on)
     *   ALS_INT_EN = 0 (no interrupt)
     *   ALS_PERS = 000 (1 sample)
     *   ALS_IT = 0000 (100 ms)
     *   ALS_GAIN = 00 (1x)
     *   ALS_AF = 0 (no auto-gain)
     *   ALS_TRIG = 0 (no trigger)
     * => 0x0000
     */
    return i2c_write_reg16(fd, REG_CONFIG, 0x0000);
}

static int veml7700_read_lux(int fd, float *lux_out)
{
    uint16_t als_data;
    if (i2c_read_reg16(fd, REG_ALS_DATA, &als_data) != 0)
        return -1;

    /*
     * VEML7700 resolution: 0.01 lux per count (16-bit).
     * Conversion factor: 1 / 100 = 0.01
     */
    *lux_out = (float)als_data * 0.01f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gamma correction                                                    */
/* ------------------------------------------------------------------ */
static void gamma_correct(float lux, uint8_t *r, uint8_t *g, uint8_t *b)
{
    float gamma = 2.2f;
    float inv_gamma = 1.0f / gamma;

    float v = lux / 1000.0f;
    if (v < 0.0f) v = 0.0f;
    if (v > 1.0f) v = 1.0f;

    float c = powf(v, inv_gamma);

    uint8_t c8 = (uint8_t)(c * 255.0f);
    *r = c8;
    *g = c8;
    *b = c8;
}

/* ------------------------------------------------------------------ */
/* WS2812B bit-banging (simple, no external driver)                     */
/* ------------------------------------------------------------------ */
static void ws2812b_send(const uint8_t *data, int len)
{
    /*
     * WS2812B timing:
     *   T0H = 0.35 us, T0L = 0.8 us  -> 0 bit
     *   T1H = 0.7 us,  T1L = 0.6 us  -> 1 bit
     *
     * We use a simple software loop with busy-wait delays.
     * On a Raspberry Pi 5 the core clock is 250 MHz, so a 1 us delay
     * is achieved by calling usleep(1).  We use a 10 us delay for
     * the longer 0.8 us / 0.6 us slots.
     */
    for (int i = 0; i < len; i++) {
        uint8_t byte = data[i];
        for (int bit = 7; bit >= 0; bit--) {
            if (byte & (1 << bit)) {
                /* T1H: 7 us (10 us round up) */
                usleep(10);
                /* T1L: 6 us */
                usleep(6);
            } else {
                /* T0H: 3.5 us (10 us round up) */
                usleep(10);
                /* T0L: 8 us */
                usleep(8);
            }
        }
    }
}

static void ws2812b_set_all(uint8_t r, uint8_t g, uint8_t b)
{
    uint8_t data[NUM_LEDS * 3];
    for (int i = 0; i < NUM_LEDS; i++) {
        data[i * 3 + 0] = g;
        data[i * 3 + 1] = r;
        data[i * 3 + 2] = b;
    }
    ws2812b_send(data, sizeof(data));
}

static void ws2812b_off(void)
{
    ws2812b_set_all(0, 0, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    ws2812b_off();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
