    }

    printf("VEML7700 initialized. Reading ambient light and controlling LEDs...\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        bool read_ok = false;

        for (int attempt = 0; attempt < I2C_RETRIES && g_running; attempt++) {
            if (veml7700_read_lux(g_i2c_fd, &lux) == 0) {
                read_ok = true;
                break;
            }
            if (attempt < I2C_RETRIES - 1)
                usleep(I2C_RETRY_DELAY_MS * 1000);
        }

        if (!read_ok) {
            fprintf(stderr, "Failed to read VEML7700 after %d attempts. "
                            "Retrying in %d ms...\n",
                    I2C_RETRIES, LOOP_DELAY_MS);
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        uint8_t r, g, b;
        gamma_correct(lux, &r, &g, &b);

        ws2812b_set_all(r, g, b);

