/*
 * KY-026 Flame Sensor Monitor with Self-Test and Error Recovery
 * Board:  Raspberry Pi 5
 * Library: pigpio (modern GPIO API, no wiringPi)
 *
 * Wiring:
 *   KY-026 DO  -> BCM GPIO4  (physical pin 7)
 *   Buzzer    -> BCM GPIO17 (physical pin 11)
 *   LED       -> BCM GPIO18 (physical pin 12)
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN       17
#define LED_PIN          18

#define STARTUP_BLINK_MS   500
#define STARTUP_READ_MS    100
#define STARTUP_READS      5
#define MAIN_POLL_MS       50
#define ERROR_BLINK_MS     100
#define ERROR_BLINK_CYCLES 5
#define ERROR_BUZZER_MS    200
#define ERROR_BUZZER_REPEATS 3

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
    }
    return v;
}

static void blink_led(unsigned pin, unsigned ms_on, unsigned ms_off, unsigned cycles)
{
    for (unsigned i = 0; i < cycles && g_running; i++) {
        safe_write(pin, 1);
        gpioDelay(ms_on * 1000);
        safe_write(pin, 0);
        gpioDelay(ms_off * 1000);
    }
}

static void buzzer_pattern(unsigned pin, unsigned ms_on, unsigned ms_off, unsigned repeats)
{
    for (unsigned r = 0; r < repeats && g_running; r++) {
        safe_write(pin, 1);
        gpioDelay(ms_on * 1000);
        safe_write(pin, 0);
        gpioDelay(ms_off * 1000);
    }
}

static int startup_self_test(void)
{
    log_event("Starting startup self-test...");

    /* Ensure outputs are off before starting */
    safe_write(BUZZER_PIN, 0);
    safe_write(LED_PIN, 0);

    /* Blink LED twice while reading flame sensor */
    for (int i = 0; i < 2 && g_running; i++) {
        blink_led(LED_PIN, STARTUP_BLINK_MS, STARTUP_BLINK_MS, 1);
        gpioDelay(500 * 1000);
    }
    if (!g_running) return -1;

    log_event("Reading flame sensor during self-test...");

    int low_count = 0;
    for (int i = 0; i < STARTUP_READS && g_running; i++) {
        int v = safe_read(FLAME_SENSOR_PIN);
        if (v < 0) return -1;
        if (v == 0) low_count++;
        gpioDelay(STARTUP_READ_MS * 1000);
    }

    if (low_count == STARTUP_READS) {
        log_event("ERROR: Flame detected on all startup reads (persistent LOW).");
        blink_led(LED_PIN, ERROR_BLINK_MS, ERROR_BLINK_MS, ERROR_BLINK_CYCLES);
        buzzer_pattern(BUZZER_PIN, ERROR_BUZZER_MS, ERROR_BUZZER_MS, ERROR_BUZZER_REPEATS);
        return -1;
    }

    log_event("Startup self-test complete.");
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO lines */
    if (safe_set_mode(FLAME_SENSOR_PIN, PI_INPUT) != 0) goto fail;
    if (safe_set_mode(BUZZER_PIN, PI_OUTPUT) != 0) goto fail;
    if (safe_set_mode(LED_PIN, PI_OUTPUT) != 0) goto fail;

    /* Ensure outputs start off */
    safe_write(BUZZER_PIN, 0);
    safe_write(LED_PIN, 0);

    /* Run startup self-test */
    if (startup_self_test() != 0) {
        log_event("Startup self-test failed. Exiting.");
        goto cleanup;
    }

    log_event("Monitoring flame sensor (polling every 50 ms)...");

    bool flame_active = false;

    while (g_running) {
        int v = safe_read(FLAME_SENSOR_PIN);
        if (v < 0) {
            log_event("Error reading flame sensor. Exiting.");
            break;
        }

        if (v == 0) {
            if (!flame_active) {
                log_event("Flame detected!");
                safe_write(BUZZER_PIN, 1);
                safe_write(LED_PIN, 1);
                flame_active = true;
            }
        } else {
            if (flame_active) {
                log_event("Flame cleared.");
                safe_write(BUZZER_PIN, 0);
                safe_write(LED_PIN, 0);
                flame_active = false;
            }
        }

        gpioDelay(MAIN_POLL_MS * 1000);
    }

    log_event("Shutting down gracefully...");

cleanup:
    safe_write(BUZZER_PIN, 0);
    safe_write(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;

fail:
    gpioTerminate();
    return EXIT_FAILURE;
}

