#define BH1750_ADDR    0x23
#define BH1750_CMD_PWR  0x01
#define BH1750_CMD_CONT 0x10
#define BH1750_CMD_OT   0x20
#define BH1750_CMD_RES  0x15
#define GPIO_CHIP      "gpiochip4"
#define GPIO_LED       17
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *out) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: expected 2 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_CMD_PWR) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_CMD_OT) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_CMD_RES) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_CMD_CONT) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    if (i2c_write_byte(fd, BH1750_CMD_CONT) < 0) return -1;
    usleep(180000);
    uint16_t raw;
    if (i2c_read_word(fd, &raw) < 0) return -1;
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void buffer_add(float *buf, int *idx, float val) {
    buf[*idx] = val;
    *idx = (*idx + 1) % BUFFER_SIZE;
}

static float buffer_avg(const float *buf, int count) {
    if (count <= 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < count; i++) sum += buf[i];
    return sum / (float)count;
}

static void led_set_freq(struct gpiod_line *line, float lux) {
    float freq = 0.5f + (lux / 1000.0f) * 4.5f;
    if (freq < 0.5f) freq = 0.5f;
    if (freq > 5.0f) freq = 5.0f;
    int period_us = (int)(1000000.0f / freq);
    int half_us = period_us / 2;
    while (running) {
        if (gpiod_line_set_value(line, 1) < 0) break;
        usleep(half_us);
        if (gpiod_line_set_value(line, 0) < 0) break;
        usleep(half_us);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led, "bh1750_led", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    float lux_buf[BUFFER_SIZE];
    int buf_idx = 0;
    int buf_count = 0;

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying next cycle\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }
        buffer_add(lux_buf, &buf_idx, lux);
        if (buf_count < BUFFER_SIZE) buf_count++;
        float avg = buffer_avg(lux_buf, buf_count);
        printf("Lux: %.2f, Avg: %.2f\n", lux, avg);
        led_set_freq(led, avg);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

