#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DATA_PIN    17
#define CLOCK_PIN   18
#define LATCH_PIN   27

/* Segment patterns for digits 0-9 (common cathode, active-high) */
static const unsigned char digit_patterns[10] = {
    0x3F, /* 0: a b c d e f */
    0x06, /* 1:     b     */
    0x5B, /* 2: a   c   f */
    0x4F, /* 3: a   c   e f */
    0x66, /* 4:   b   d   e */
    0x6D, /* 5: a   c   d e */
    0x7D, /* 6: a   c d e f */
    0x07, /* 7: a b c */
    0x7F, /* 8: a b c d e f */
    0x6F  /* 9: a b c d e */
};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Shift out `data` bits MSB first, clocking each bit through the 74HC595.
 * The latch pin is asserted (pulled low) at the start of the transfer,
 * then deasserted (pulled high) at the end.
 *
 * pigpio's gpioWrite is used for each pin; gpioDelay is used for timing.
 */
static void shift_out(unsigned char data)
{
    gpioWrite(LATCH_PIN, 0);
    gpioDelay(1); /* latch low >= 1 us */

    for (int i = 7; i >= 0; i--) {
        gpioWrite(DATA_PIN, (data >> i) & 1);
        gpioDelay(1); /* data setup >= 1 us */
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1); /* clock high >= 1 us */
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1); /* clock low >= 1 us */
    }

    gpioWrite(LATCH_PIN, 1);
    gpioDelay(1); /* latch high >= 1 us */
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs */
    if (gpioSetMode(DATA_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set DATA_PIN (GPIO%d) as output.\n", DATA_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set CLOCK_PIN (GPIO%d) as output.\n", CLOCK_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LATCH_PIN (GPIO%d) as output.\n", LATCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure all outputs start low */
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    /* Display digit '5' for 500 ms, then blink it repeatedly */
    while (running) {
        shift_out(digit_patterns[5]);
        gpioDelay(500000); /* 500 ms */

        if (!running)
            break;

        shift_out(0x00); /* blank display */
        gpioDelay(500000); /* 500 ms */
    }

    /* Clean shutdown: blank display and release GPIO resources */
    shift_out(0x00);
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

