        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (LED)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (BUTTON)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the button line as input with pull-up and falling-edge event detection */
    ret = gpiod_line_request_input_flags(button_line, "blink_button",
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP |
                                          GPIOD_LINE_REQUEST_FLAG_EVENT_FALLING_EDGE);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags (BUTTON)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Blinking LED on GPIO%d every %d ms. Press the button on GPIO%d to stop.\n",
           LED_PIN, BLINK_PERIOD_MS, BUTTON_PIN);
    fflush(stdout);

    /* Main loop: blink LED while waiting for button press */
    while (running) {
        /* Turn LED on */
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED on)");
            break;
        }

        /* Wait for button press with timeout */
        ret = gpiod_line_event_wait(button_line, &(struct timespec){0, POLL_TIMEOUT_MS * 1000000L});
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            /* Timeout — blink the other half of the period */
            usleep(BLINK_PERIOD_MS * 1000);
            continue;
        }

        /* Button event detected — read it to clear the event */
        struct gpiod_line_event event;
        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        /* Turn LED off */
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LED off)");
            break;
        }

        printf("Button pressed! Stopping blinking.\n");
        fflush(stdout);
        break;
    }

    /* Clean up: turn LED off, release lines, close chip */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

