    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_line_release(btn_line);
    gpiod_chip_close(chip);

    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

