#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RED_PIN    24
#define GREEN_PIN  23
#define BLUE_PIN   18

#define PWM_PERIOD_US  10000   /* 10 ms -> 100 Hz */
#define PWM_STEP_US    100     /* 100 us steps -> 1000 steps per cycle */
#define LOOP_DELAY_US  100000  /* 100 ms between colour changes */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Busy-wait software PWM: drive a GPIO line high for `on_us` microseconds,
 * then low for `off_us` microseconds.  Uses clock_nanosleep for sub-millisecond
 * precision; falls back to usleep if clock_nanosleep is unavailable.
 */
static void pwm_write(int pin, int on_us, int off_us)
{
    if (on_us > 0) {
        if (gpioWrite(pin, 1) < 0) {
            fprintf(stderr, "gpioWrite(pin=%d, 1) failed: %s\n",
                    pin, strerror(errno));
            return;
        }
        if (on_us >= 1000) {
            usleep(on_us);
        } else {
            struct timespec req = {
                .tv_sec  = 0,
                .tv_nsec = (long)on_us * 1000L
            };
            while (nanosleep(&req, &req) == -1 && errno == EINTR) {
                /* Retry if interrupted by signal */
            }
        }
    }

    if (off_us > 0) {
        if (gpioWrite(pin, 0) < 0) {
            fprintf(stderr, "gpioWrite(pin=%d, 0) failed: %s\n",
                    pin, strerror(errno));
            return;
        }
        if (off_us >= 1000) {
            usleep(off_us);
        } else {
            struct timespec req = {
                .tv_sec  = 0,
                .tv_nsec = (long)off_us * 1000L
            };
            while (nanosleep(&req, &req) == -1 && errno == EINTR) {
                /* Retry if interrupted by signal */
            }
        }
    }
}

/*
 * Generate a random intensity value (0-100).
 */
static int random_intensity(void)
{
    return rand() % 101;
}

int main(void)
{
    int pins[3] = {RED_PIN, GREEN_PIN, BLUE_PIN};

    /* Seed the PRNG */
    srand((unsigned int)time(NULL));

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure all three PWM pins as outputs */
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "gpioSetMode(pin=%d, PI_OUTPUT) failed: %s\n",
                    pins[i], strerror(errno));
            gpioTerminate();
            return EXIT_FAILURE;
        }
        /* Start with LED off */
        if (gpioWrite(pins[i], 0) < 0) {
            fprintf(stderr, "gpioWrite(pin=%d, 0) initial failed: %s\n",
                    pins[i], strerror(errno));
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("RGB LED control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int red   = random_intensity();
        int green = random_intensity();
        int blue  = random_intensity();

        /*
         * Drive each channel for PWM_PERIOD_US, stepping PWM_STEP_US
         * at a time.  Each step is a single call to pwm_write().
         */
        for (int step = 0; step < 1000 && g_running; step++) {
            int on_us  = (step < red)   ? PWM_STEP_US : 0;
            int off_us = (step >= red)  ? PWM_STEP_US : 0;
            pwm_write(RED_PIN, on_us, off_us);

            on_us  = (step < green) ? PWM_STEP_US : 0;
            off_us = (step >= green) ? PWM_STEP_US : 0;
            pwm_write(GREEN_PIN, on_us, off_us);

            on_us  = (step < blue)  ? PWM_STEP_US : 0;
            off_us = (step >= blue) ? PWM_STEP_US : 0;
            pwm_write(BLUE_PIN, on_us, off_us);
        }

        /* Wait 100 ms before next colour change */
        if (g_running) {
            struct timespec req = {
                .tv_sec  = 0,
                .tv_nsec = LOOP_DELAY_US * 1000L
            };
            while (nanosleep(&req, &req) == -1 && errno == EINTR) {
                /* Retry if interrupted by signal */
            }
        }
    }

    /* Clean shutdown: turn off all LEDs and terminate pigpio */
    for (int i = 0; i < 3; i++) {
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();

    printf("\nRGB LED control stopped.\n");
    return EXIT_SUCCESS;
}

