            pwm_write(GREEN_PIN, on_us, off_us);

            on_us  = (step < blue)  ? PWM_STEP_US : 0;
            off_us = (step >= blue) ? PWM_STEP_US : 0;
            pwm_write(BLUE_PIN, on_us, off_us);
        }

        /* Wait 100 ms before next colour change */
        if (g_running) {
            struct timespec req = {
                .tv_sec  = 0,
                .tv_nsec = LOOP_DELAY_US * 1000L
            };
            while (nanosleep(&req, &req) == -1 && errno == EINTR) {
                /* Retry if interrupted by signal */
            }
        }
    }

    /* Clean shutdown: turn off all LEDs and terminate pigpio */
    for (int i = 0; i < 3; i++) {
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();

    printf("\nRGB LED control stopped.\n");
    return EXIT_SUCCESS;
}

