/*
 * Impact detection using an Adafruit LSM303DLHC accelerometer on Raspberry Pi Zero W.
 *
 * Wiring:
 *   LSM303DLHC SDA -> GPIO2 (I2C bus 1 SDA)
 *   LSM303DLHC SCL -> GPIO3 (I2C bus 1 SCL)
 *   LSM303DLHC VCC -> 3.3 V
 *   LSM303DLHC GND -> GND
 *   Impact LED/buzzer -> GPIO17 (BCM) via suitable driver circuit
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o impact_detect impact_detect.c -lm -lpigpio -lrt
 * Run:
 *   sudo ./impact_detect [-t threshold_g]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- LSM303DLHC constants (from datasheet) ---- */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_CTRL_REG1_A 0x20
#define LSM303_OUT_X_L_A 0x28
#define LSM303_OUT_X_H_A 0x29
#define LSM303_OUT_Y_L_A 0x2A
#define LSM303_OUT_Y_H_A 0x2B
#define LSM303_OUT_Z_L_A 0x2C
#define LSM303_OUT_Z_H_A 0x2D

/* ---- Application constants ---- */
#define I2C_BUS 1
#define IMPACT_GPIO 17
#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "impact_log.txt"
#define POLL_DELAY_US 100000  /* 10 Hz */
#define IMPACT_PULSE_US 50000 /* 50 ms */

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    /* Ensure GPIO is left in a safe state */
    gpioWrite(IMPACT_GPIO, 0);
    gpioSetMode(IMPACT_GPIO, PI_INPUT);
    gpioTerminate();
}

/* ---- Read 6 bytes of accelerometer data ---- */
static int read_accelerometer(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];

    /*
     * LSM303DLHC auto-increments register addresses when reading multiple bytes.
     * Write the starting register address, then read 6 bytes.
     */
    if (i2cWriteByte(i2c_handle, LSM303_OUT_X_L_A | 0x80) < 0) {
        fprintf(stderr, "Error: failed to set accelerometer register pointer\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes from accelerometer\n");
        return -1;
    }

    *x = (int16_t)((uint16_t)buf[1] << 8 | (uint8_t)buf[0]);
    *y = (int16_t)((uint16_t)buf[3] << 8 | (uint8_t)buf[2]);
    *z = (int16_t)((uint16_t)buf[5] << 8 | (uint8_t)buf[4]);
    return 0;
}

/* ---- Compute G-force magnitude ---- */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    /*
     * Sensitivity: 1 mg/LSB at default full-scale ±2 g.
     * Convert to G: divide raw value by 1000.
     */
    float x_g = (float)x / 1000.0f;
    float y_g = (float)y / 1000.0f;
    float z_g = (float)z / 1000.0f;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

/* ---- Trigger impact interrupt ---- */
static void trigger_impact(void)
{
    if (gpioWrite(IMPACT_GPIO, 1) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO %d HIGH\n", IMPACT_GPIO);
        return;
    }
    gpioDelay(IMPACT_PULSE_US);
    if (gpioWrite(IMPACT_GPIO, 0) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO %d LOW\n", IMPACT_GPIO);
    }
}

/* ---- Log impact data to file ---- */
static void log_impact(float magnitude)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Magnitude: %.3f G\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, magnitude);
    } else {
        fprintf(fp, "[timestamp error], Magnitude: %.3f G\n", magnitude);
    }

    fclose(fp);
}

/* ---- Main ---- */
int main(int argc, char *argv[])
{
    float threshold = DEFAULT_THRESHOLD;

    /* Parse command-line arguments */
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Error: threshold must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to LSM303DLHC */
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, LSM303_ACCEL_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure accelerometer: enable all axes, 100 Hz data rate */
    if (i2cWriteByteData(i2c_handle, LSM303_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error: failed to configure accelerometer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as output and ensure it starts LOW */
    if (gpioSetMode(IMPACT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", IMPACT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(IMPACT_GPIO, 0);

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: failed to register signal handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Threshold: %.2f G. Press Ctrl+C to exit.\n",
           threshold);

    /* Main polling loop */
    while (!terminate) {
        int16_t x, y, z;

        if (read_accelerometer(&x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);

            if (magnitude > threshold) {
                printf("Impact detected! Magnitude: %.3f G\n", magnitude);
                trigger_impact();
                log_impact(magnitude);
            }
        } else {
            fprintf(stderr, "Warning: accelerometer read failed, retrying...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

