code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADPD188BI I2C address (7-bit) */
#define ADPD188BI_ADDR 0x29

/* ADPD188BI register addresses */
#define ADPD188BI_REG_ALS_LSB 0x00
#define ADPD188BI_REG_ALS_MSB 0x01
#define ADPD188BI_REG_RED_LSB 0x02
#define ADPD188BI_REG_RED_MSB 0x03
#define ADPD188BI_REG_GREEN_LSB 0x04
#define ADPD188BI_REG_GREEN_MSB 0x05
#define ADPD188BI_REG_BLUE_LSB 0x06
#define ADPD188BI_REG_BLUE_MSB 0x07

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 18

/* PWM range (0-255) */
#define PWM_RANGE 255

/* PWM frequency (Hz) */
#define PWM_FREQUENCY 1000

/* I2C bus number */
#define I2C_BUS 1

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 500000

/* Retry delay in microseconds */
#define RETRY_DELAY_US 100000

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Function to read a 16-bit register from the ADPD188BI */
static int read_register16(int handle, uint8_t reg_lsb, uint16_t *value) {
    int lsb, msb;

    lsb = i2cReadByteData(handle, reg_lsb);
    if (lsb < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg_lsb, strerror(errno));
        return -1;
    }

    msb = i2cReadByteData(handle, reg_lsb + 1);
    if (msb < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg_lsb + 1, strerror(errno));
        return -1;
    }

    *value = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* Function to write a 16-bit register to the ADPD188BI */
static int write_register16(int handle, uint8_t reg_lsb, uint16_t value) {
    int lsb, msb;

    lsb = value & 0xFF;
    msb = (value >> 8) & 0xFF;

    if (i2cWriteByteData(handle, reg_lsb, lsb) < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg_lsb, strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(handle, reg_lsb + 1, msb) < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg_lsb + 1, strerror(errno));
        return -1;
    }

    return 0;
}

/* Function to initialize the ADPD188BI sensor */
static int initialize_sensor(int handle) {
    /*
     * Example initialization sequence for the ADPD188BI.
     * This is a simplified placeholder; the actual initialization
     * sequence depends on the specific sensor configuration.
     */
    if (write_register16(handle, ADPD188BI_REG_ALS_LSB, 0x0001) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        return -1;
    }

    return 0;
}

/* Function to read sensor data */
static int read_sensor_data(int handle, uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_register16(handle, ADPD188BI_REG_ALS_LSB, als) < 0) return -1;
    if (read_register16(handle, ADPD188BI_REG_RED_LSB, red) < 0) return -1;
    if (read_register16(handle, ADPD188BI_REG_GREEN_LSB, green) < 0) return -1;
    if (read_register16(handle, ADPD188BI_REG_BLUE_LSB, blue) < 0) return -1;

    return 0;
}

/* Function to log data to a CSV file */
static int log_data(FILE *fp, uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(fp);
    return 0;
}

/* Function to control the LED brightness based on ambient light */
static void control_led(uint16_t als) {
    /*
     * Simple linear mapping:
     *   ALS = 0 -> LED off
     *   ALS = 65535 -> LED full brightness
     */
    int brightness = (int)(((float)als / 65535.0f) * PWM_RANGE);
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;

    gpioPWM(LED_PIN, brightness);
}

int main() {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, ADPD188BI_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin for hardware PWM */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPWMrange(LED_PIN, PWM_RANGE);
    gpioSetPWMfrequency(LED_PIN, PWM_FREQUENCY);

    /* Open log file */
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header to log file if it's a new file */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    /* Set up signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        uint16_t als, red, green, blue;

        if (read_sensor_data(i2c_handle, &als, &red, &green, &blue) == 0) {
            if (log_data(log_file, als, red, green, blue) == 0) {
                control_led(als);
            } else {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying in 100ms...\n");
            gpioDelay(RETRY_DELAY_US);
