/*
 * FXOS8700CQ Impact Detector for Raspberry Pi Zero W
 *
 * Reads acceleration data from the Adafruit FXOS8700CQ over I2C bus 1
 * at 200 Hz, computes the magnitude of the acceleration vector, and
 * logs impact events to impact_log.txt when the magnitude exceeds
 * a configurable threshold.
 *
 * Wiring:
 *   FXOS8700CQ SDA -> GPIO 2 (pin 3)
 *   FXOS8700CQ SCL -> GPIO 3 (pin 5)
 *   FXOS8700CQ VDD -> 3.3 V
 *   FXOS8700CQ GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o impact_detector impact_detector.c -lpigpio -lrt -lm
 * Run:
 *   sudo ./impact_detector
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700CQ I2C configuration ---- */
#define I2C_BUS              1
#define FXOS8700_ADDR        0x1D   /* SA0 tied to GND */

/* FXOS8700CQ register addresses */
#define FXOS8700_REG_STATUS  0x00
#define FXOS8700_REG_OUT_X_MSB 0x01
#define FXOS8700_REG_WHO_AM_I 0x0D
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E
#define FXOS8700_REG_CTRL_REG1 0x2A
#define FXOS8700_REG_CTRL_REG2 0x2B

/* Expected device ID */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* ---- Application configuration ---- */
#define IMPACT_THRESHOLD     1.0f   /* g */
#define SAMPLE_PERIOD_US     50000  /* 50 ms -> 200 Hz */
#define LOG_FILE             "impact_log.txt"

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an 8-bit register                            */
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register                            */
/* ------------------------------------------------------------------ */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X, Y, Z, X_MSB, Y_MSB, Z_MSB)    */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, FXOS8700_REG_OUT_X_MSB, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData failed: expected 6 bytes, got %d\n", rc);
        return -1;
    }

    /* FXOS8700CQ outputs X_MSB first, then X_LSB, then Y_MSB, etc. */
    *x = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *y = (int16_t)(((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3]);
    *z = (int16_t)(((uint16_t)(uint8_t)buf[4] << 8) | (uint8_t)buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute acceleration magnitude in g                                  */
/* ------------------------------------------------------------------ */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    /* ±2 g range: 16384 LSB/g */
    const float scale = 1.0f / 16384.0f;
    float fx = (float)x * scale;
    float fy = (float)y * scale;
    float fz = (float)z * scale;
    return sqrtf(fx * fx + fy * fy + fz * fz);
}

/* ------------------------------------------------------------------ */
/* Append an impact event to the log file                              */
/* ------------------------------------------------------------------ */
static int log_impact(int16_t x, int16_t y, int16_t z, float magnitude)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the FXOS8700CQ sensor                                    */
/* ------------------------------------------------------------------ */
static int initialize_sensor(int handle)
{
    uint8_t who_am_i = 0;
    if (read_register(handle, FXOS8700_REG_WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "[ERROR] WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode */
    if (write_register(handle, FXOS8700_REG_CTRL_REG1, 0x00) != 0) {
        return -1;
    }

    /* ±2 g range */
    if (write_register(handle, FXOS8700_REG_XYZ_DATA_CFG, 0x00) != 0) {
        return -1;
    }

    /* 200 Hz ODR, active mode */
    if (write_register(handle, FXOS8700_REG_CTRL_REG1, 0x0D) != 0) {
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, FXOS8700_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("Impact detection started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        int16_t x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                if (log_impact(x, y, z, magnitude) != 0) {
                    fprintf(stderr, "[WARN] Failed to log impact event\n");
                }
            }
        } else {
            fprintf(stderr, "[WARN] Failed to read acceleration data\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

