/*
 * GY-50 L3G4200D Gyroscope Calibration & Logging
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: GY-50 L3G4200D at address 0x69
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_log gyro_log.c
 * Run:    ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- L3G4200D constants ---- */
#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D

/* CTRL_REG1: ODR=100 Hz (0x0F), all axes enabled */
#define CTRL_REG1_VAL  0x0F
/* CTRL_REG4: FS=245 dps (0x00), little-endian (0x00) */
#define CTRL_REG4_VAL  0x00

#define SAMPLE_PERIOD_US 50000   /* 20 Hz */
#define CALIB_SAMPLES    100
#define ALERT_THRESHOLD  50.0f   /* dps */
#define LOG_FILE         "gyro_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Little-endian: low byte at buf[0], high byte at buf[1] */
    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

/* ---- Gyroscope initialization ---- */
static int gyro_init(int fd)
{
    uint8_t who;

    /* Verify sensor identity */
    if (i2c_read_reg8(fd, WHO_AM_I, &who) != 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 100 Hz, all axes enabled */
    if (i2c_write_reg8(fd, CTRL_REG1, CTRL_REG1_VAL) != 0)
        return -1;

    /* CTRL_REG4: FS=245 dps, little-endian */
    if (i2c_write_reg8(fd, CTRL_REG4, CTRL_REG4_VAL) != 0)
        return -1;

    return 0;
}

/* ---- Calibration ---- */
static int gyro_calibrate(int fd, float *x_off, float *y_off, float *z_off)
{
    int16_t x_sum = 0, y_sum = 0, z_sum = 0;
    int16_t x, y, z;
    int i;

    printf("Calibrating gyroscope (%d samples)...\n", CALIB_SAMPLES);

    for (i = 0; i < CALIB_SAMPLES; i++) {
        if (i2c_read_reg16(fd, OUT_X_L, &x) != 0 ||
            i2c_read_reg16(fd, OUT_Y_L, &y) != 0 ||
            i2c_read_reg16(fd, OUT_Z_L, &z) != 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            return -1;
        }
        x_sum += x;
        y_sum += y;
        z_sum += z;
        usleep(1000);  /* 1 ms between samples */
    }

    *x_off = (float)x_sum / CALIB_SAMPLES;
    *y_off = (float)y_sum / CALIB_SAMPLES;
    *z_off = (float)z_sum / CALIB_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n",
           *x_off, *y_off, *z_off);
    return 0;
}

/* ---- Read raw gyro data ---- */
static int gyro_read_raw(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    return i2c_read_reg16(fd, OUT_X_L, x) ||
           i2c_read_reg16(fd, OUT_Y_L, y) ||
           i2c_read_reg16(fd, OUT_Z_L, z);
}

/* ---- Apply calibration ---- */
static void gyro_apply_offsets(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                               float x_off, float y_off, float z_off,
                               float *cal_x, float *cal_y, float *cal_z)
{
    *cal_x = (float)raw_x - x_off;
    *cal_y = (float)raw_y - y_off;
    *cal_z = (float)raw_z - z_off;
}

/* ---- Log data to file ---- */
static int log_data(FILE *fp, float cal_x, float cal_y, float cal_z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, cal_x, cal_y, cal_z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Check for alert condition ---- */
static void check_alert(float cal_x, float cal_y, float cal_z)
{
    if (fabsf(cal_x) > ALERT_THRESHOLD ||
        fabsf(cal_y) > ALERT_THRESHOLD ||
        fabsf(cal_z) > ALERT_THRESHOLD) {
        fprintf(stderr, "ALERT: Gyro out of range! "
                        "X=%.2f Y=%.2f Z=%.2f dps\n",
                cal_x, cal_y, cal_z);
        if (g_log_fp) {
            fprintf(g_log_fp, "ALERT: Gyro out of range! "
                              "X=%.2f Y=%.2f Z=%.2f dps\n",
                    cal_x, cal_y, cal_z);
            fflush(g_log_fp);
        }
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;
    int16_t raw_x, raw_y, raw_z;
    float cal_x, cal_y, cal_z;

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                GYRO_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (gyro_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Calibrate gyroscope */
    if (gyro_calibrate(g_i2c_fd, &x_off, &y_off, &z_off) != 0) {
        fprintf(stderr, "Gyroscope calibration failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging gyro data to %s at 20 Hz. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* Main loop */
    while (g_running) {
        if (gyro_read_raw(g_i2c_fd, &raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "Read error; continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        gyro_apply_offsets(raw_x, raw_y, raw_z, x_off, y_off, z_off,
                           &cal_x, &cal_y, &cal_z);

        if (log_data(g_log_fp, cal_x, cal_y, cal_z) != 0) {
            fprintf(stderr, "Logging error; continuing.\n");
        }

        check_alert(cal_x, cal_y, cal_z);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

