/*
 * ADXL345 accelerometer reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   LED anode    -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o accel_log accel_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDR        0x53
#define ADXL345_REG_DEVID   0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0  0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_DATA_FORMAT 0x31

#define ADXL345_DEVID_EXPECTED 0xE5
#define ADXL345_POWER_CTL_MEASURE 0x08

/* Full-resolution, ±2 g, 4 mg/LSB => 1 g = 256 LSB */
#define ADXL345_SCALE_FACTOR 256.0f

/* ---- Application constants ---- */
#define I2C_BUS             1
#define LED_GPIO            17
#define ACCEL_THRESHOLD_G   2.0f
#define SAMPLE_PERIOD_US    100000  /* 100 ms */
#define LOG_FILE            "accel_log.txt"

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;
static volatile sig_atomic_t g_terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register; returns 0 on success, -1 on err */
static int adxl_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register; returns 0 on success, -1 on err */
static int adxl_read_reg(uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X, Y, Z) in full-resolution mode */
static int adxl_read_accel(float *x, float *y, float *z)
{
    uint8_t buf[6];

    int rc = i2cReadI2CBlockData(g_i2c_handle, ADXL345_REG_DATAX0, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData failed (rc=%d): %s\n",
                rc, rc < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* ADXL345 outputs little-endian two's-complement */
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / ADXL345_SCALE_FACTOR;
    *y = (float)raw_y / ADXL345_SCALE_FACTOR;
    *z = (float)raw_z / ADXL345_SCALE_FACTOR;
    return 0;
}

/* ------------------------------------------------------------------ */
static int initialize_adxl345(void)
{
    uint8_t devid = 0;

    if (adxl_read_reg(ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVID — sensor absent or bus error.\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "[ERROR] DEVID mismatch: got 0x%02X, expected 0x%02X.\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }
    printf("[INFO] ADXL345 detected (DEVID=0x%02X).\n", devid);

    /* Standby first so configuration changes take effect */
    if (adxl_write_reg(ADXL345_REG_POWER_CTL, 0x00) != 0)
        return -1;

    /*
     * DATA_FORMAT: 0x0B = full resolution, ±2 g, right-justified off.
     *   Bit 3 = FULL_RES (1)
     *   Bits[1:0] = range (00 = ±2 g)
     */
    if (adxl_write_reg(ADXL345_REG_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /*
     * BW_RATE: 0x0A = 100 Hz output data rate (ODR).
     *   Bits[3:0] = rate (0xA = 100 Hz)
     */
    if (adxl_write_reg(ADXL345_REG_BW_RATE, 0x0A) != 0)
        return -1;

    /* Enter measurement mode */
    if (adxl_write_reg(ADXL345_REG_POWER_CTL, ADXL345_POWER_CTL_MEASURE) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(float x, float y, float z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "1970-01-01 00:00:00", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_file, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus to ADXL345 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, ADXL345_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (initialize_adxl345() != 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x_g,y_g,z_g\n");
        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed: %s\n", strerror(errno));
    }

    printf("[INFO] Logging to '%s' at 10 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    /* Main sampling loop */
    while (!g_terminate) {
        float x, y, z;

        if (adxl_read_accel(&x, &y, &z) == 0) {
            log_data(x, y, z);

            bool exceeded = (fabsf(x) > ACCEL_THRESHOLD_G) ||
                            (fabsf(y) > ACCEL_THRESHOLD_G) ||
                            (fabsf(z) > ACCEL_THRESHOLD_G);
            gpioWrite(LED_GPIO, exceeded ? 1 : 0);
        } else {
            /* On read failure, ensure LED is off and keep going */
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

