/*
 * compass.c — LSM303DLHC accelerometer/magnetometer compass for Raspberry Pi Zero W
 *
 * Build:  gcc -O2 -Wall -Wextra -o compass compass.c -lm
 * Run:    ./compass
 *
 * Wiring:
 *   LSM303DLHC SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   LSM303DLHC SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   LSM303DLHC VDD  -> 3.3 V
 *   LSM303DLHC GND  -> GND
 *
 * The LSM303DLHC is a 3-axis accelerometer and 3-axis magnetometer in one package.
 * The accelerometer is configured in high-resolution mode (+/- 2 g full scale).
 * The magnetometer is configured in high-resolution mode (+/- 4 gauss full scale).
 *
 * The program samples every 100 ms, computes a tilt-compensated heading, and
 * logs timestamp, heading, acceleration (g), and magnetic field (gauss) to
 * compass_log.txt.  On SIGINT or SIGTERM the program exits cleanly.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* ---- LSM303DLHC register addresses ---- */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_CTRL_REG4_A 0x23
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_ACCEL_OUT_X_H_A   0x29
#define LSM303_ACCEL_OUT_Y_L_A   0x2A
#define LSM303_ACCEL_OUT_Y_H_A   0x2B
#define LSM303_ACCEL_OUT_Z_L_A   0x2C
#define LSM303_ACCEL_OUT_Z_H_A   0x2D

#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03
#define LSM303_MAG_OUT_X_L_M     0x04
#define LSM303_MAG_OUT_Z_H_M     0x05
#define LSM303_MAG_OUT_Z_L_M     0x06
#define LSM303_MAG_OUT_Y_H_M     0x07
#define LSM303_MAG_OUT_Y_L_M     0x08

/* ---- Sensitivity constants (from datasheet) ---- */
#define ACCEL_SENSITIVITY 0.000061f   /* g/LSB at +/- 2 g, high-res */
#define MAG_SENSITIVITY   0.00014f    /* gauss/LSB at +/- 4 gauss */

/* ---- Globals for cleanup ---- */
static int g_accel_handle = -1;
static int g_mag_handle   = -1;
static volatile sig_atomic_t g_terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an 8-bit register                           */
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register                            */
/* ------------------------------------------------------------------ */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 6-byte block of accelerometer data (X, Y, Z low/high)        */
/* ------------------------------------------------------------------ */
static int read_accelerometer(int handle, float *x, float *y, float *z)
{
    char buffer[6];
    int rc = i2cReadI2CBlockData(handle, LSM303_ACCEL_OUT_X_L_A | 0x80, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(accel) failed: got %d bytes, expected 6\n", rc);
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 6-byte block of magnetometer data (X, Z, Y low/high)        */
/* ------------------------------------------------------------------ */
static int read_magnetometer(int handle, float *x, float *y, float *z)
{
    char buffer[6];
    int rc = i2cReadI2CBlockData(handle, LSM303_MAG_OUT_X_H_M, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(mag) failed: got %d bytes, expected 6\n", rc);
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[0] << 8) | (uint8_t)buffer[1]);
    int16_t raw_z = (int16_t)((buffer[2] << 8) | (uint8_t)buffer[3]);
    int16_t raw_y = (int16_t)((buffer[4] << 8) | (uint8_t)buffer[5]);

    *x = (float)raw_x * MAG_SENSITIVITY;
    *y = (float)raw_y * MAG_SENSITIVITY;
    *z = (float)raw_z * MAG_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute tilt-compensated heading (degrees)                          */
/* ------------------------------------------------------------------ */
static float calculate_heading(float ax, float ay, float az,
                              float mx, float my, float mz)
{
    float pitch = atan2f(ax, sqrtf(ay * ay + az * az));
    float roll  = atan2f(-ay, az);

    float cos_roll = cosf(roll);
    float sin_roll = sinf(roll);
    float cos_pitch = cosf(pitch);
    float sin_pitch = sinf(pitch);

    float mx_comp = mx * cos_pitch + mz * sin_pitch;
    float my_comp = mx * sin_roll * sin_pitch + my * cos_roll - mz * sin_roll * cos_pitch;

    float heading = atan2f(my_comp, mx_comp) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row to the log file                                  */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float heading, float ax, float ay, float az,
                    float mx, float my, float mz)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                timestamp, heading, ax, ay, az, mx, my, mz) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — close I2C handles and terminate pigpio             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_accel_handle >= 0) {
        i2cClose(g_accel_handle);
        g_accel_handle = -1;
    }
    if (g_mag_handle >= 0) {
        i2cClose(g_mag_handle);
        g_mag_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C handles ---- */
    g_accel_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (g_accel_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(accel, 0x%02X) failed: %d\n",
                LSM303_ACCEL_ADDR, g_accel_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_mag_handle = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (g_mag_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(mag, 0x%02X) failed: %d\n",
                LSM303_MAG_ADDR, g_mag_handle);
        i2cClose(g_accel_handle);
        g_accel_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure accelerometer: 119 Hz ODR, high-res, +/- 2 g ---- */
    if (write_register(g_accel_handle, LSM303_ACCEL_CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "[FATAL] Accelerometer configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure magnetometer: temp sensor enabled, 80 Hz ODR ---- */
    if (write_register(g_mag_handle, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "[FATAL] Magnetometer configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; continuing without signal handling\n");
    }

    /* ---- Open log file (append mode) ---- */
    FILE *fp = fopen("compass_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "[FATAL] Cannot open compass_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,heading_deg,accel_x_g,accel_y_g,accel_z_g,mag_x_g,mag_y_g,mag_z_g\n");
        fflush(fp);
    }

    printf("LSM303DLHC compass running. Logging to compass_log.txt. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (!g_terminate) {
        float ax, ay, az, mx, my, mz;

        if (read_accelerometer(g_accel_handle, &ax, &ay, &az) < 0) {
            fprintf(stderr, "[WARN] Accelerometer read failed; skipping sample\n");
            gpioDelay(100000);
            continue;
        }

        if (read_magnetometer(g_mag_handle, &mx, &my, &mz) < 0) {
            fprintf(stderr, "[WARN] Magnetometer read failed; skipping sample\n");
            gpioDelay(100000);
            continue;
        }

        float heading = calculate_heading(ax, ay, az, mx, my, mz);

        if (log_data(fp, heading, ax, ay, az, mx, my, mz) < 0) {
            fprintf(stderr, "[WARN] Logging failed; continuing\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    fclose(fp);
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

