/*
 * VL6180X Time-of-Flight distance logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL6180X SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   VL6180X SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   VL6180X VDD  -> 3.3 V
 *   VL6180X GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl6180x_logger vl6180x_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ---- VL6180X register map (subset) ---- */
#define VL6180X_REG_IDENTIFICATION_MODEL_ID      0x000
#define VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET    0x016
#define VL6180X_REG_SYSRANGE_START               0x018
#define VL6180X_REG_RESULT_RANGE_VAL            0x062
#define VL6180X_REG_RESULT_INTERRUPT_STATUS     0x04F
#define VL6180X_REG_SYSTEM_INTERRUPT_CLEAR      0x015

#define VL6180X_MODEL_ID                         0xB4
#define VL6180X_DEFAULT_I2C_ADDR                0x29

#define I2C_BUS                                  1
#define LOG_FILE                                 "distance_log.txt"
#define SAMPLE_PERIOD_US                         100000   /* 100 ms */
#define DOOR_THRESHOLD_MM                       100
#define MAX_CONSECUTIVE_ERRORS                  10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* VL6180X sensor initialization                                        */
/* ------------------------------------------------------------------ */
static int vl6180x_init(int handle)
{
    /* Mandatory initialization sequence (from ST datasheet) */
    if (i2c_write_byte(handle, 0x0207, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, 0x0208, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, 0x0096, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, 0x0097, 0xfd) < 0) return -1;
    if (i2c_write_byte(handle, 0x00e3, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, 0x00e4, 0x04) < 0) return -1;
    if (i2c_write_byte(handle, 0x00e5, 0x02) < 0) return -1;
    if (i2c_write_byte(handle, 0x00e6, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, 0x00e7, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, 0x00f5, 0x02) < 0) return -1;
    if (i2c_write_byte(handle, 0x00d9, 0x05) < 0) return -1;
    if (i2c_write_byte(handle, 0x00db, 0xce) < 0) return -1;
    if (i2c_write_byte(handle, 0x00dc, 0x03) < 0) return -1;
    if (i2c_write_byte(handle, 0x00dd, 0xf8) < 0) return -1;
    if (i2c_write_byte(handle, 0x009f, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, 0x00a3, 0x3c) < 0) return -1;
    if (i2c_write_byte(handle, 0x00b7, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, 0x00bb, 0x3c) < 0) return -1;
    if (i2c_write_byte(handle, 0x00b2, 0x09) < 0) return -1;
    if (i2c_write_byte(handle, 0x00ca, 0x09) < 0) return -1;
    if (i2c_write_byte(handle, 0x0198, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, 0x01b0, 0x17) < 0) return -1;
    if (i2c_write_byte(handle, 0x01ad, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, 0x00ff, 0x05) < 0) return -1;
    if (i2c_write_byte(handle, 0x0100, 0x05) < 0) return -1;
    if (i2c_write_byte(handle, 0x0199, 0x05) < 0) return -1;
    if (i2c_write_byte(handle, 0x01a6, 0x1b) < 0) return -1;
    if (i2c_write_byte(handle, 0x01ac, 0x3e) < 0) return -1;
    if (i2c_write_byte(handle, 0x01a7, 0x1f) < 0) return -1;
    if (i2c_write_byte(handle, 0x0030, 0x00) < 0) return -1;

    /* Clear any pending interrupt */
    if (i2c_write_byte(handle, VL6180X_REG_SYSTEM_INTERRUPT_CLEAR, 0x07) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int vl6180x_read_distance(int handle)
{
    /* Start a single-shot range measurement */
