#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x40
#define SENSOR2_ADDR   0x41
#define SAMPLE_PERIOD_US 10000   /* 10 ms */
#define LOG_FILE       "audio_log.dat"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle1 = -1;
static int  g_i2c_handle2 = -1;
static FILE *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe subset only                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit signed sample from an IMP23ABSU sensor                 */
/* Returns 0 on success, -1 on I2C error                               */
/* ------------------------------------------------------------------ */
static int read_sensor(int handle, int16_t *sample)
{
    char buf[2];

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read error on handle %d: %s\n",
                handle, strerror(errno));
        return -1;
    }

    /* IMP23ABSU outputs MSB first */
    *sample = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                       (uint16_t)(uint8_t)buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute TDOA in microseconds between two samples                    */
/* ------------------------------------------------------------------ */
static long long compute_tdoa(const struct timespec *t1,
                              const struct timespec *t2)
{
    long long diff_ns = (long long)(t2->tv_sec - t1->tv_sec) * 1000000000LL +
                        (long long)(t2->tv_nsec - t1->tv_nsec);
    return diff_ns;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row                                                  */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp,
                    const struct timespec *ts,
                    int16_t s1, int16_t s2, long long tdoa)
{
    if (fprintf(fp, "%ld,%09ld,%d,%d,%lld\n",
                (long)ts->tv_sec, ts->tv_nsec, s1, s2, tdoa) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct timespec ts1, ts2;
    int16_t s1, s2;
    long long tdoa;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C handles ---- */
    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                SENSOR2_ADDR, strerror(errno));
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "sec,nsec,sensor1,sensor2,tdoa\n");
        fflush(g_log_file);
    }

    printf("Sampling IMP23ABSU sensors at 10 ms intervals. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        if (clock_gettime(CLOCK_REALTIME, &ts1) != 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            break;
        }

        if (read_sensor(g_i2c_handle1, &s1) != 0) {
            fprintf(stderr, "Sensor 1 read failed; skipping sample.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (read_sensor(g_i2c_handle2, &s2) != 0) {
            fprintf(stderr, "Sensor 2 read failed; skipping sample.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts2) != 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            break;
        }

        tdoa = compute_tdoa(&ts1, &ts2);

        if (log_data(g_log_file, &ts1, s1, s2, tdoa) != 0) {
            fprintf(stderr, "Logging failed; aborting.\n");
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

