#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A SPI register addresses (7-bit, left-justified in 16-bit word) */
#define ADIS16488_REG_GLOB_CMD   0x04
#define ADIS16488_REG_SMPL_PRD   0x36
#define ADIS16488_REG_XGYRO_OUT  0x06
#define ADIS16488_REG_YGYRO_OUT  0x08
#define ADIS16488_REG_ZGYRO_OUT  0x0A
#define ADIS16488_REG_XACCL_OUT  0x0C
#define ADIS16488_REG_YACCL_OUT  0x0E
#define ADIS16488_REG_ZACCL_OUT  0x10

/* Sensitivity values (from ADIS16488A datasheet) */
#define GYRO_SENSITIVITY  0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000     /* 1 MHz */
#define SPI_FLAGS   0x03        /* mode 3: CPOL=1, CPHA=1 */

/* Timing */
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define STALL_TIME_US    40       /* ADIS16488A stall time */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on normal exit and on every error path      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16488A                            */
/* Returns 0 on success, -1 on SPI transfer error, -2 on invalid data   */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];

    /* ADIS16488A read: MSB=0, 7-bit register address, then dummy byte */
    tx[0] = (char)(reg & 0x7F);
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer error reading register 0x%02X\n", reg);
        return -1;
    }

    /* Data is returned on the subsequent 16-bit transfer */
    char tx2[2] = {0x00, 0x00};
    char rx2[2] = {0};

    if (spiXfer(spi_handle, tx2, rx2, 2) != 2) {
        fprintf(stderr, "SPI transfer error reading data for register 0x%02X\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx2[0] << 8) | (uint8_t)rx2[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all six sensor axes                                            */
/* Returns 0 on success, -1 on any read failure                         */
/* ------------------------------------------------------------------ */
static int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z)
{
    int16_t raw_gx, raw_gy, raw_gz, raw_ax, raw_ay, raw_az;

    if (read_register(ADIS16488_REG_XGYRO_OUT, &raw_gx) != 0) return -1;
    if (read_register(ADIS16488_REG_YGYRO_OUT, &raw_gy) != 0) return -1;
    if (read_register(ADIS16488_REG_ZGYRO_OUT, &raw_gz) != 0) return -1;
    if (read_register(ADIS16488_REG_XACCL_OUT, &raw_ax) != 0) return -1;
    if (read_register(ADIS16488_REG_YACCL_OUT, &raw_ay) != 0) return -1;
    if (read_register(ADIS16488_REG_ZACCL_OUT, &raw_az) != 0) return -1;

    *gyro_x = (float)raw_gx * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_gy * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_gz * GYRO_SENSITIVITY;
    *accel_x = (float)raw_ax * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_ay * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_az * ACCEL_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to CSV                                                */
/* ------------------------------------------------------------------ */
static void log_data(float gyro_x, float gyro_y, float gyro_z,
                     float accel_x, float accel_y, float accel_z)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, ts.tv_nsec / 1000000,
            gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz, flags 0x%02X): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file for appending */
    fp = fopen("imu_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening imu_data.csv for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
        fflush(fp);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Register cleanup for normal exit and all error paths */
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "Warning: could not register atexit cleanup\n");
    }

    printf("ADIS16488A IMU logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (running) {
        float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        if (read_imu_data(&gyro_x, &gyro_y, &gyro_z,
                          &accel_x, &accel_y, &accel_z) == 0) {
            log_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Error reading IMU data, skipping sample\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(SAMPLE_PERIOD_US / 10);
        }
    }

    printf("\nShutting down gracefully...\n");
    return EXIT_SUCCESS;
}

