/*
 * ADIS16448 IMU SPI reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16448 CS  -> GPIO8  (BCM)
 *   ADIS16448 SCLK-> GPIO11 (BCM)
 *   ADIS16448 DOUT-> GPIO9  (BCM)
 *   ADIS16448 DIN -> GPIO10 (BCM)
 *   ADIS16448 VDD -> 3.3 V
 *   ADIS16448 GND -> GND
 *
 * Build: gcc -O2 -Wall -o adis16448 adis16448.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ---- ADIS16448 register addresses (single-register read protocol) ---- */
#define ADIS16448_REG_SMPL_PRD   0x04
#define ADIS16448_REG_XGYRO_OUT  0x06
#define ADIS16448_REG_YGYRO_OUT  0x08
#define ADIS16448_REG_ZGYRO_OUT  0x0A
#define ADIS16448_REG_XACCL_OUT  0x0C
#define ADIS16448_REG_YACCL_OUT  0x0E
#define ADIS16448_REG_ZACCL_OUT  0x10

/* ---- Scaling factors ---- */
#define GYRO_SCALE  0.02f   /* dps/LSB */
#define ACCL_SCALE  0.00025f /* g/LSB  */

/* ---- SPI configuration ---- */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8U
#define SPI_MODE        SPI_MODE_3
#define SPI_DELAY_USECS 0

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single 16-bit register from the ADIS16448 using the
 * single-register read protocol: send (reg | 0x80) in the first
 * 16-bit SPI cycle, then clock out the 16-bit response in the second
 * cycle.  Returns 0 on success and stores the 16-bit value in *out;
 * returns -1 on error.
 */
static int adis16448_read_reg(int fd, uint8_t reg, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };
    struct spi_ioc_transfer tr;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
