#define ADIS16448_REG_YGYRO_OUT  0x08
#define ADIS16448_REG_ZGYRO_OUT  0x0A
#define ADIS16448_REG_XACCL_OUT  0x0C
#define ADIS16448_REG_YACCL_OUT  0x0E
#define ADIS16448_REG_ZACCL_OUT  0x10

/* Scaling factors (from ADIS16448 datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCL_SCALE  0.00025f /* g per LSB */

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_FLAGS   0       /* Mode 0, active-low CE */

/* Global SPI handle for signal handler cleanup */
static int spi_handle = -1;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Read a 16-bit register from the ADIS16448 via SPI */
static int read_register(int handle, uint8_t reg_addr, int16_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    /* ADIS16448 read command: bit 15 = 1, bits 14:0 = register address */
    tx_buf[0] = (char)(reg_addr | 0x80);
    tx_buf[1] = 0x00;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    /* Small stall to allow the ADIS16448 to prepare the data */
    gpioDelay(40); /* 40 microseconds */

    /* Dummy transfer to clock out the 16-bit data */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X (dummy)\n", reg_addr);
        return -1;
    }

    /* Data is left-justified in 16-bit frame; shift right 4 bits */
    *value = (int16_t)(((uint16_t)(uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]) >> 4;
    return 0;
}

