    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (1) {
        int16_t gyro_x, gyro_y, gyro_z;
        int16_t accel_x, accel_y, accel_z;

        /* Read gyroscope data */
        if (read_register(spi_handle, ADIS16448_REG_XGYRO_OUT, &gyro_x) != 0 ||
