        float gyro_x_dps = gyro_x * GYRO_SCALE;
        float gyro_y_dps = gyro_y * GYRO_SCALE;
        float gyro_z_dps = gyro_z * GYRO_SCALE;

        float accel_x_g = accel_x * ACCL_SCALE;
        float accel_y_g = accel_y * ACCL_SCALE;
        float accel_z_g = accel_z * ACCL_SCALE;

        /* Print the data to the console */
        printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f deg/sec | Accel: X=%.4f, Y=%.4f, Z=%.4f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps,
               accel_x_g, accel_y_g, accel_z_g);

        /* Delay for 100 milliseconds */
        gpioDelay(100000); /* 100,000 microseconds */
    }

    /* Cleanup (should not normally reach here due to signal handler) */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

