 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6886_ADDR   0x68

/* MPU-6886 register addresses */
#define REG_SMPLRT_DIV  0x19
#define REG_CONFIG      0x1A
#define REG_GYRO_CONFIG 0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_ACCEL_XOUT_H 0x3B
#define REG_GYRO_XOUT_H  0x43

#define SAMPLE_PERIOD_US 50000  /* 50 ms */
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register; returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Read N bytes starting from an 8-bit register; returns 0 on success, -1 on error. */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    /* Write the register pointer */
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }

    /* Read the data bytes */
    n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (read %zd of %zu bytes)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian register pair.
 * Returns 0 on success and stores the signed value in *out; -1 on error.
 */
static int i2c_read_reg16_s(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (i2c_read_burst(fd, reg, buf, sizeof(buf)) != 0)
        return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* Initialize the MPU-6886: wake up, set sample rate, configure sensors. */
static int mpu6886_init(int fd)
{
    /* Wake up: clear sleep bit (bit 6) in PWR_MGMT_1 */
    if (i2c_write_reg8(fd, 0x6B, 0x00) != 0)
        return -1;
    usleep(100000);  /* allow oscillator to stabilize */

    /* Sample rate divider: 0x07 -> 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg8(fd, REG_SMPLRT_DIV, 0x07) != 0)
        return -1;

    /* DLPF_CFG = 0x00 -> bandwidth 260 Hz, delay 0.98 ms */
    if (i2c_write_reg8(fd, REG_CONFIG, 0x00) != 0)
        return -1;

    /* Gyro full-scale range: ±250 °/s (FS_SEL = 0) */
    if (i2c_write_reg8(fd, REG_GYRO_CONFIG, 0x00) != 0)
        return -1;

    /* Accel full-scale range: ±2 g (AFS_SEL = 0) */
    if (i2c_write_reg8(fd, REG_ACCEL_CONFIG, 0x00) != 0)
        return -1;

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the I2C slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus address 0x%02X: %s\n",
                MPU6886_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize the MPU-6886 */
    if (mpu6886_init(fd) != 0) {
        fprintf(stderr, "MPU-6886 initialization failed (sensor absent or bus error).\n");
        goto cleanup;
    }

    printf("MPU-6886 initialized on %s at address 0x%02X.\n", I2C_BUS, MPU6886_ADDR);
    printf("Accel (X/Y/Z) [raw], Gyro (X/Y/Z) [raw]\n");
    fflush(stdout);

    /* Main sampling loop */
    while (g_running) {
        int16_t ax = 0, ay = 0, az = 0;
        int16_t gx = 0, gy = 0, gz = 0;
        bool ok = false;

        /* Retry loop for transient I2C errors */
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (i2c_read_reg16_s(fd, REG_ACCEL_XOUT_H, &ax) == 0 &&
                i2c_read_reg16_s(fd, REG_ACCEL_XOUT_H + 2, &ay) == 0 &&
                i2c_read_reg16_s(fd, REG_ACCEL_XOUT_H + 4, &az) == 0 &&
                i2c_read_reg16_s(fd, REG_GYRO_XOUT_H, &gx) == 0 &&
                i2c_read_reg16_s(fd, REG_GYRO_XOUT_H + 2, &gy) == 0 &&
                i2c_read_reg16_s(fd, REG_GYRO_XOUT_H + 4, &gz) == 0) {
                ok = true;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed; retrying...\n",
                    attempt + 1, MAX_RETRIES);
            usleep(10000);  /* 10 ms backoff */
        }

        if (ok) {
            printf("%6d %6d %6d  %6d %6d %6d\n",
                   ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d attempts.\n", MAX_RETRIES);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

