/*
 * ADXL345 Impact Detector for Raspberry Pi Zero W
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (I2C bus 1 SDA)
 *   ADXL345 SCL -> GPIO3 (I2C bus 1 SCL)
 *   ADXL345 VCC -> 3.3 V
 *   ADXL345 GND -> GND
 *   LED anode  -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode-> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o impact_detector impact_detector.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDR        0x53
#define ADXL345_REG_DEVID   0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0  0x32
#define ADXL345_DEVID_VAL   0xE5
#define ADXL345_SCALE_FACTOR 256.0f   /* LSB/g for ±2 g full-resolution */

/* ---- Application constants ---- */
#define I2C_BUS             1
#define LED_GPIO            17
#define IMPACT_THRESHOLD_G  2.5f
#define POLL_DELAY_US       10000    /* 10 ms */
#define LED_ON_TIME_US      500000   /* 500 ms */
#define LOG_FILE            "impact_log.txt"

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an ADXL345 register; returns 0 on success,   */
/* -1 on error.                                                         */
/* ------------------------------------------------------------------ */
static int adxl345_read_reg(uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an ADXL345 register; returns 0 on success,    */
/* -1 on error.                                                         */
/* ------------------------------------------------------------------ */
static int adxl345_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X, Y, Z) in full-resolution mode. */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adxl345_read_acceleration(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int rc = i2cReadI2CBlockData(g_i2c_handle, ADXL345_REG_DATAX0, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData failed: expected 6 bytes, got %d\n", rc);
        return -1;
    }

    *x = (int16_t)(((uint8_t)buf[1] << 8) | (uint8_t)buf[0]);
    *y = (int16_t)(((uint8_t)buf[3] << 8) | (uint8_t)buf[2]);
    *z = (int16_t)(((uint8_t)buf[5] << 8) | (uint8_t)buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw 16-bit two's-complement data to g-force.                */
/* ------------------------------------------------------------------ */
static float raw_to_g(int16_t raw)
{
    return (float)raw / ADXL345_SCALE_FACTOR;
}

/* ------------------------------------------------------------------ */
/* Compute the magnitude of the acceleration vector.                   */
/* ------------------------------------------------------------------ */
static float magnitude_g(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Log an impact event to the file and stdout.                         */
/* ------------------------------------------------------------------ */
static void log_impact(float mag, float x, float y, float z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_file, "%s, Magnitude: %.2f g, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
            ts, mag, x, y, z);
    fflush(g_log_file);

    printf("%s, Magnitude: %.2f g, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
           ts, mag, x, y, z);
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADXL345_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify device identity ---- */
    uint8_t devid = 0;
    if (adxl345_read_reg(ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "[FATAL] Cannot read DEVID register — sensor absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "[FATAL] DEVID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_VAL);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("[INFO] ADXL345 detected (DEVID=0x%02X)\n", devid);

    /* ---- Standby mode before configuring ---- */
    if (adxl345_write_reg(ADXL345_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "[FATAL] Failed to enter standby mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(1000); /* 1 ms settle */

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction");
    }

    printf("[INFO] Impact detection started. Threshold: %.1f g. Press Ctrl+C to exit.\n",
           IMPACT_THRESHOLD_G);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (adxl345_read_acceleration(&raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "[WARN] I2C read error — continuing\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float x = raw_to_g(raw_x);
        float y = raw_to_g(raw_y);
        float z = raw_to_g(raw_z);
        float mag = magnitude_g(x, y, z);

        if (mag > IMPACT_THRESHOLD_G) {
            printf("[ALERT] Impact detected! Magnitude: %.2f g\n", mag);

            if (gpioWrite(LED_GPIO, 1) < 0) {
                fprintf(stderr, "[WARN] gpioWrite(%d, 1) failed\n", LED_GPIO);
            }
            log_impact(mag, x, y, z);

            /* Keep LED on for 500 ms, checking for shutdown signal */
            uint32_t elapsed = 0;
            while (g_running && elapsed < LED_ON_TIME_US) {
                gpioDelay(10000); /* 10 ms slices */
                elapsed += 10000;
            }
            if (gpioWrite(LED_GPIO, 0) < 0) {
                fprintf(stderr, "[WARN] gpioWrite(%d, 0) failed\n", LED_GPIO);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

