/*
 * GY-45 MMA8451Q Impact Detector for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MMA8451Q SDA -> GPIO2 (I2C bus 1 SDA)
 *   MMA8451Q SCL -> GPIO3 (I2C bus 1 SCL)
 *   MMA8451Q VDD -> 3.3 V
 *   MMA8451Q GND -> GND
 *   LED anode   -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode -> GND
 *
 * Build: gcc -O2 -Wall -o impact_detector impact_detector.c -lpigpio -lrt
 * Run:   sudo ./impact_detector
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- MMA8451Q constants ---- */
#define I2C_BUS        1
#define I2C_ADDR       0x1D          /* SA0 tied to GND */

#define REG_STATUS     0x00
#define REG_OUT_X_MSB  0x01
#define REG_OUT_X_LSB  0x02
#define REG_OUT_Y_MSB  0x03
#define REG_OUT_Y_LSB  0x04
#define REG_OUT_Z_MSB  0x05
#define REG_OUT_Z_LSB  0x06
#define REG_WHO_AM_I   0x0D
#define REG_XYZ_DATA_CFG 0x0E
#define REG_CTRL_REG1  0x2A
#define REG_CTRL_REG2  0x2B

#define WHO_AM_I_VAL   0x1A          /* expected for MMA8451Q */

/* ---- Application constants ---- */
#define LED_GPIO       17
#define IMPACT_THRESHOLD_G 2.0f
#define POLL_DELAY_US  100000        /* 100 ms */
#define LED_ON_US      500000        /* 500 ms */
#define LOG_FILE       "impact_log.txt"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an MMA8451Q register; returns 0 on success, -1 on err */
static int mma_write_reg(uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(g_i2c_handle, reg, value) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an MMA8451Q register; returns byte or -1 on err   */
static int mma_read_reg(uint8_t reg)
{
    int v = i2cReadByteData(g_i2c_handle, reg);
    if (v < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed\n", reg);
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (X, Y, Z) in one burst            */
static int mma_read_xyz(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int n = i2cReadI2CBlockData(g_i2c_handle, REG_OUT_X_MSB, buf, 6);
    if (n != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData returned %d (expected 6)\n", n);
        return -1;
    }
    *x = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *y = (int16_t)(((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3]);
    *z = (int16_t)(((uint16_t)(uint8_t)buf[4] << 8) | (uint8_t)buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MMA8451Q: verify identity, configure range, enable   */
static int mma_init(void)
{
