/*
 * ADXL345 Free-Fall Detector for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (physical pin 3,  I2C bus 1)
 *   ADXL345 SCL  -> GPIO3  (physical pin 5,  I2C bus 1)
 *   ADXL345 INT1 -> GPIO17 (physical pin 11, BCM 17)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall freefall.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_I2C_BUS        "/dev/i2c-1"
#define ADXL345_I2C_ADDR       0x53
#define ADXL345_DEVID          0x00
#define ADXL345_DEVID_VAL      0xE5
#define ADXL345_POWER_CTL      0x2D
#define ADXL345_INT_ENABLE     0x2E
#define ADXL345_INT_MAP        0x2F
#define ADXL345_INT_SOURCE     0x30
#define ADXL345_DATA_FORMAT    0x31
#define ADXL345_DATAX0         0x32
#define ADXL345_BW_RATE        0x2C
#define ADXL345_FREEFALL_TH    0x28
#define ADXL345_FREEFALL_DUR   0x29

/* ---- GPIO / interrupt ---- */
#define GPIO_INT_PIN           17
#define GPIO_INT_EVENT_FILE    "/dev/gpiochip4"   /* BCM 17 on Pi 4 */

/* ---- Free-fall parameters ---- */
#define FREEFALL_THRESHOLD_G   0.2f
#define FREEFALL_DURATION_MS   200

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US       10000   /* 10 ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static int      g_gpio_fd  = -1;
static FILE    *g_log_fp   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL345                                                             */
/* ------------------------------------------------------------------ */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (i2c_read_block(fd, ADXL345_DEVID, &devid, 1) != 0)
        return -1;
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }

    /* Standby first so configuration changes take effect */
    if (i2c_write_byte(fd, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Data format: full resolution, +/-2g, right-justified */
    if (i2c_write_byte(fd, ADXL345_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* Bandwidth rate: 100 Hz */
    if (i2c_write_byte(fd, ADXL345_BW_RATE, 0x0A) != 0)
        return -1;

    /* Free-fall threshold: 200 mg (0.2 g) */
    if (i2c_write_byte(fd, ADXL345_FREEFALL_TH, 0x05) != 0)
        return -1;

    /* Free-fall duration: 200 ms (0x14) */
    if (i2c_write_byte(fd, ADXL345_FREEFALL_DUR, 0x14) != 0)
        return -1;

    /* Map all interrupts to INT1 */
    if (i2c_write_byte(fd, ADXL345_INT_MAP, 0x00) != 0)
        return -1;

    /* Enable free-fall interrupt */
    if (i2c_write_byte(fd, ADXL345_INT_ENABLE, 0x10) != 0)
        return -1;

    /* Enter measurement mode */
    if (i2c_write_byte(fd, ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

static int adxl345_read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_block(fd, ADXL345_DATAX0, buf, 6) != 0)
        return -1;

    raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* +/-2g range, 4 mg/LSB => 1/256 g/LSB */
    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO                                                                */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(GPIO_INT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_INT_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down so the line is defined when the
       ADXL345 is not driving it (free-fall inactive). */
    if (gpioSetPullUpDown(GPIO_INT_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", GPIO_INT_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_init(void)
{
    g_log_fp = fopen("freefall_log.csv", "w");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open freefall_log.csv: %s\n", strerror(errno));
        return -1;
    }
    fprintf(g_log_fp, "timestamp,x_g,y_g,z_g\n");
    fflush(g_log_fp);
    return 0;
}

static void log_sample(float x, float y, float z)
{
    struct timespec ts;
    struct tm tm_info;
    char tbuf[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s.%03ld,%.3f,%.3f,%.3f\n",
            tbuf, ts.tv_nsec / 1000000L, x, y, z);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable interrupts first (best-effort) */
    if (g_i2c_fd >= 0) {
        (void)i2c_write_byte(g_i2c_fd, ADXL345_INT_ENABLE, 0x00);
        (void)i2c_write_byte(g_i2c_fd, ADXL345_POWER_CTL, 0x00);
    }

    if (g_gpio_fd >= 0) {
        close(g_gpio_fd);
        g_gpio_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    struct timespec sleep_ts = { 0, SAMPLE_PERIOD_US * 1000L };
    int freefall_active = 0;
    uint32_t freefall_start_ms = 0;
    uint32_t now_ms;
    struct timespec now_ts;

    /* Signal handlers */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(ADXL345_I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", ADXL345_I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADXL345_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (gpio_init() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO event file for edge detection */
    g_gpio_fd = open(GPIO_INT_EVENT_FILE, O_RDONLY);
    if (g_gpio_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_INT_EVENT_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize logging */
    if (log_init() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 free-fall detector running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint8_t buf[32];
        ssize_t n = read(g_gpio_fd, buf, sizeof(buf));

        if (n < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "GPIO read error: %s\n", strerror(errno));
            break;
        }
        if (n == 0)
            continue;  /* timeout, no event */

        /* Free-fall interrupt detected */
        uint8_t int_src = 0;
        if (i2c_read_block(g_i2c_fd, ADXL345_INT_SOURCE, &int_src, 1) != 0) {
            fprintf(stderr, "Failed to read INT_SOURCE\n");
            break;
        }
        if (!(int_src & 0x10))
            continue;  /* spurious event */

        /* Clear the interrupt so the next one can fire */
        (void)i2c_write_byte(g_i2c_fd, ADXL345_INT_SOURCE, 0x10);

        /* Free-fall just started */
        if (!freefall_active) {
            freefall_active = 1;
            clock_gettime(CLOCK_MONOTONIC, &now_ts);
            freefall_start_ms = (uint32_t)(now_ts.tv_sec * 1000U +
                                            now_ts.tv_nsec / 1000000U);
            printf("Free-fall detected!\n");
        }

        /* Sample acceleration while free-fall is active */
        float x, y, z;
        if (adxl345_read_acceleration(g_i2c_fd, &x, &y, &z) == 0) {
            log_sample(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        /* Check free-fall duration */
        clock_gettime(CLOCK_MONOTONIC, &now_ts);
        now_ms = (uint32_t)(now_ts.tv_sec * 1000U + now_ts.tv_nsec / 1000000U);
        if (freefall_active && (now_ms - freefall_start_ms) >= FREEFALL_DURATION_MS) {
            freefall_active = 0;
            printf("Free-fall duration exceeded. Free-fall ended.\n");
        }

        nanosleep(&sleep_ts, NULL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

