/*
 * LSM6DSR Fall Detection Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   LSM6DSR SDA -> GPIO2 (BCM)
 *   LSM6DSR SCL -> GPIO3 (BCM)
 *   LSM6DSR VDD -> 3.3 V
 *   LSM6DSR GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lsm6dsr_fall lsm6dsr_fall.c -lm
 *
 * Run:
 *   ./lsm6dsr_fall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM6DSR I2C address ---- */
#define LSM6DSR_ADDR 0x6A

/* ---- LSM6DSR register addresses ---- */
#define WHO_AM_I_REG      0x0F
#define WHO_AM_I_VAL      0x69
#define CTRL1_XL          0x10
#define CTRL2_G           0x11
#define OUTX_L_G          0x22
#define OUTX_L_XL         0x28

/* ---- Sensitivities ---- */
#define ACCEL_SENSITIVITY 0.000061f   /* ±2 g  -> 0.61 mg/LSB */
#define GYRO_SENSITIVITY  0.00875f    /* ±250 dps -> 8.75 mdps/LSB */

/* ---- Fall detection thresholds ---- */
#define ACCEL_THRESHOLD_LOW  0.2f   /* g */
#define ACCEL_THRESHOLD_HIGH 2.5f   /* g */
#define DETECTION_WINDOW_MS  1000   /* ms */

/* ---- Output data rate ---- */
#define ODR_HZ 104

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int init_lsm6dsr(int fd)
{
    uint8_t whoami = 0;
    if (i2c_read_burst(fd, WHO_AM_I_REG, &whoami, 1) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                whoami, WHO_AM_I_VAL);
        return -1;
    }

    /*
     * CTRL1_XL: ODR_XL = 104 Hz (0b0101), FS_XL = ±2 g (0b00)
     *   -> 0b0101_0000 = 0x50
     */
    if (i2c_write_reg8(fd, CTRL1_XL, 0x50) != 0)
        return -1;

    /*
     * CTRL2_G: ODR_G = 104 Hz (0b0101), FS_G = ±250 dps (0b00)
     *   -> 0b0101_0000 = 0x50
     */
    if (i2c_write_reg8(fd, CTRL2_G, 0x50) != 0)
        return -1;

    return 0;
}

/* ---- Read accelerometer (g) ---- */
static int read_accel(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, OUTX_L_XL, raw, 6) != 0)
        return -1;

    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);

    *x = (float)rx * ACCEL_SENSITIVITY;
    *y = (float)ry * ACCEL_SENSITIVITY;
    *z = (float)rz * ACCEL_SENSITIVITY;
    return 0;
}

/* ---- Read gyroscope (dps) ---- */
static int read_gyro(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, OUTX_L_G, raw, 6) != 0)
        return -1;

    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);

    *x = (float)rx * GYRO_SENSITIVITY;
    *y = (float)ry * GYRO_SENSITIVITY;
    *z = (float)rz * GYRO_SENSITIVITY;
    return 0;
}

/* ---- Log one sample ---- */
static void log_sample(FILE *fp, float ax, float ay, float az,
                       float gx, float gy, float gz)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            tbuf, ts.tv_nsec / 1000000L,
            ax, ay, az, gx, gy, gz);
    fflush(fp);
}

/* ---- Fall detection state machine ---- */
static void detect_fall(float ax, float ay, float az, float dt_s)
{
    static enum { IDLE, FREEFALL, IMPACT } state = IDLE;
    static struct timespec impact_time;

    switch (state) {
    case IDLE:
        if (sqrtf(ax * ax + ay * ay + az * az) < ACCEL_THRESHOLD_LOW) {
            state = FREEFALL;
            printf("[FALL] Freefall detected.\n");
        }
        break;

    case FREEFALL:
        if (sqrtf(ax * ax + ay * ay + az * az) > ACCEL_THRESHOLD_HIGH) {
            state = IMPACT;
            clock_gettime(CLOCK_REALTIME, &impact_time);
            printf("[FALL] Impact detected.\n");
        }
        break;

    case IMPACT: {
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        long elapsed_ms = (now.tv_sec - impact_time.tv_sec) * 1000L +
                          (now.tv_nsec - impact_time.tv_nsec) / 1000000L;
        if (elapsed_ms > DETECTION_WINDOW_MS) {
            state = IDLE;
            printf("[FALL] Fall confirmed.\n");
        }
        break;
    }
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM6DSR_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_lsm6dsr(g_i2c_fd) != 0) {
        fprintf(stderr, "LSM6DSR initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("motion_log.txt", "a");
    if (!g_log_file) {
        perror("fopen motion_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,accel_x_g,accel_y_g,accel_z_g,gyro_x_dps,gyro_y_dps,gyro_z_dps\n");
        fflush(g_log_file);
    }

    printf("LSM6DSR fall detection started. Logging to motion_log.txt (Ctrl+C to stop).\n");

    /* Main sampling loop */
    struct timespec sleep_ts = { 0, 1000000000L / ODR_HZ }; /* 10 ms */
    struct timespec next_sample;
    clock_gettime(CLOCK_MONOTONIC, &next_sample);

    while (g_running) {
        float ax, ay, az, gx, gy, gz;

        if (read_accel(g_i2c_fd, &ax, &ay, &az) != 0) {
            fprintf(stderr, "Accelerometer read error — continuing.\n");
            nanosleep(&sleep_ts, NULL);
            continue;
        }

        if (read_gyro(g_i2c_fd, &gx, &gy, &gz) != 0) {
            fprintf(stderr, "Gyroscope read error — continuing.\n");
            nanosleep(&sleep_ts, NULL);
            continue;
        }

        log_sample(g_log_file, ax, ay, az, gx, gy, gz);
        detect_fall(ax, ay, az, 1.0f / ODR_HZ);

        next_sample.tv_nsec += sleep_ts.tv_nsec;
        if (next_sample.tv_nsec >= 1000000000L) {
            next_sample.tv_nsec -= 1000000000L;
            next_sample.tv_sec++;
        }
        clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &next_sample, NULL);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

