/*
 * ADIS16266 Gyroscope SPI Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADIS16266 SCLK-> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADIS16266 DOUT-> GPIO9  (BCM 9, SPI0 MISO)
 *   ADIS16266 DIN -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADIS16266 VDD -> 3.3 V
 *   ADIS16266 GND -> GND
 *
 * SPI: channel 0, CE0, 1 MHz, mode 3 (CPOL=1, CPHA=1)
 *
 * Build: gcc -O2 -Wall -o gyro_log gyro_log.c -lpigpio -lrt
 * Run:   sudo ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16266 register definitions ---- */
#define ADIS16266_REG_WHO_AM_I   0x00
#define ADIS16266_REG_SMPL_PRD   0x36
#define ADIS16266_REG_GLOB_CMD   0x68
#define ADIS16266_REG_XGYRO_OUT  0x04
#define ADIS16266_REG_YGYRO_OUT  0x06
#define ADIS16266_REG_ZGYRO_OUT  0x08

#define ADIS16266_WHO_AM_I_VAL   0x4026
#define ADIS16266_GLOB_CMD_RESET 0x0001

/* ---- SPI configuration ---- */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0x03     /* mode 3: CPOL=1, CPHA=1 */

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US 10000  /* 10 ms */

/* ---- Globals for cleanup ---- */
static int  spi_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16266.
 *
 * ADIS16266 SPI protocol (2-byte transfer per register):
 *   tx[0] = (reg | 0x80)  -> read command
 *   tx[1] = 0x00         -> dummy (clocks out low byte)
 *   rx[0] = don't care
 *   rx[1] = low byte of register
 *
 * Returns 0 on success and stores the 16-bit value in *out;
 * returns -1 on SPI transfer failure.
 */
static int adis16266_read_reg(uint8_t reg, uint16_t *out)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    *out = (uint16_t)((rx[1] << 8) | (rx[0] & 0xFF));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADIS16266 register.
 *
 * ADIS16266 SPI protocol (2-byte transfer per register):
 *   tx[0] = (reg & 0x7F)  -> write command
 *   tx[1] = high byte of value
 *   rx[0] = don't care
 *   rx[1] = don't care
 *
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int adis16266_write_reg(uint8_t reg, uint16_t value)
{
    char tx[2] = { (char)(reg & 0x7F), (char)(value >> 8) };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int initialize_gyro(void)
{
    uint16_t who_am_i = 0;

    /* Verify device identity */
    if (adis16266_read_reg(ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who_am_i, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }

    printf("ADIS16266 detected (WHO_AM_I = 0x%04X)\n", who_am_i);

    /* Reset device */
    if (adis16266_write_reg(ADIS16266_REG_GLOB_CMD, ADIS16266_GLOB_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset ADIS16266\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms settle after reset */

    /* Set sample period to 10 ms (0x000A -> 10 ms / 1 ms = 10) */
    if (adis16266_write_reg(ADIS16266_REG_SMPL_PRD, 0x000A) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_gyro_data(float *x, float *y, float *z)
{
    uint16_t raw_x, raw_y, raw_z;

    if (adis16266_read_reg(ADIS16266_REG_XGYRO_OUT, &raw_x) != 0) return -1;
    if (adis16266_read_reg(ADIS16266_REG_YGYRO_OUT, &raw_y) != 0) return -1;
    if (adis16266_read_reg(ADIS16266_REG_ZGYRO_OUT, &raw_z) != 0) return -1;

    /* ADIS16266 scale factor: 0.0305 deg/sec/LSB */
    *x = (float)raw_x * 0.0305f;
    *y = (float)raw_y * 0.0305f;
    *z = (float)raw_z * 0.0305f;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(float x, float y, float z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    float x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz, flags 0x%02X): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (initialize_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once and write header */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        perror("Error opening gyro_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,X_deg_s,Y_deg_s,Z_deg_s\n");
    fflush(log_file);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging gyro data to gyro_log.csv (Ctrl+C to stop)\n");

    /* Main sampling loop */
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

