#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- L3G4200D register definitions ---- */
#define L3G4200D_ADDR        0x69
#define L3G4200D_WHO_AM_I    0x0F
#define L3G4200D_WHO_AM_I_VAL 0xD3
#define L3G4200D_CTRL_REG1   0x20
#define L3G4200D_CTRL_REG4   0x23
#define L3G4200D_OUT_X_L     0x28
#define L3G4200D_OUT_X_H     0x29
#define L3G4200D_OUT_Y_L     0x2A
#define L3G4200D_OUT_Y_H     0x2B
#define L3G4200D_OUT_Z_L     0x2C
#define L3G4200D_OUT_Z_H     0x2D

/* Sensitivity: 8.75 mdps/LSB => 1/114.285 dps/LSB */
#define L3G4200D_SENSITIVITY 114.285f

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Write a single byte to a register with retry ---- */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < 3; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, 3, strerror(errno));
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

/* ---- Read a single byte from a register ---- */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ---- Read a 6-byte block of gyro data ---- */
static int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buffer[6];

    int rc = i2cReadI2CBlockData(handle, L3G4200D_OUT_X_L | 0x80, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: I2C block read failed (got %d bytes, expected 6): %s\n",
                rc, strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);
    return 0;
}

/* ---- Initialize the L3G4200D ---- */
static int initialize_gyro(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify sensor identity */
    if (read_register(handle, L3G4200D_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Cannot read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != L3G4200D_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who_am_i, L3G4200D_WHO_AM_I_VAL);
        return -1;
    }
    printf("L3G4200D detected (WHO_AM_I = 0x%02X).\n", who_am_i);

    /* CTRL_REG1: 100 Hz ODR, normal mode, all axes enabled */
    if (write_register(handle, L3G4200D_CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1.\n");
        return -1;
    }

    /* CTRL_REG4: FS = ±250 dps (default), continuous update */
    if (write_register(handle, L3G4200D_CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

/* ---- Log a data record with nanosecond timestamp ---- */
static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%09ld", ts.tv_nsec);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);
}

/* ---- Cleanup resources ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the L3G4200D address */
    i2c_handle = i2cOpen(1, L3G4200D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d): %s\n",
                i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the gyroscope */
    if (initialize_gyro(i2c_handle) != 0) {
