#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x50          /* D7S-0001 default 7-bit address */
#define CSV_FILE       "vibration_log.csv"
#define SAMPLE_PERIOD  100000        /* microseconds (100 ms) */

/*
 * D7S-0001 acceleration register map (example — adjust per datasheet).
 * The sensor returns 16-bit big-endian values.  A documented error value
 * (0x8000) indicates a sensor-absent or bus-error condition.
 */
#define REG_X_MSB      0x00
#define REG_X_LSB      0x01
#define REG_Y_MSB      0x02
#define REG_Y_LSB      0x03
#define REG_Z_MSB      0x04
#define REG_Z_LSB      0x05
#define ERROR_VALUE    0x8000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read a 16-bit big-endian register pair from the D7S.
 * Returns 0 on success and stores the value in *out;
 * returns -1 on I2C error or sensor-absent condition.
 */
static int read_axis(int fd, uint8_t msb_reg, int16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &msb_reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n",
                msb_reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                msb_reg, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    if (raw == ERROR_VALUE) {
        fprintf(stderr, "Sensor absent or bus error at reg 0x%02X\n", msb_reg);
        return -1;
    }

    *out = (int16_t)raw;
    return 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) == -1) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Open CSV file (append mode) --- */
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write header if file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush(header) failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("Logging vibration data to %s (Ctrl+C to stop)...\n", CSV_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t x = 0, y = 0, z = 0;
        int ok = 1;

        if (read_axis(fd, REG_X_MSB, &x) != 0) ok = 0;
        if (read_axis(fd, REG_Y_MSB, &y) != 0) ok = 0;
        if (read_axis(fd, REG_Z_MSB, &z) != 0) ok = 0;

        if (!ok) {
            /* Skip this sample; error already printed to stderr */
            usleep(SAMPLE_PERIOD);
            continue;
        }

        char ts[32];
        if (get_timestamp(ts, sizeof(ts)) != 0) {
            fprintf(stderr, "Skipping sample due to timestamp error\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
            fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
            goto cleanup;
        }

        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush(data) failed: %s\n", strerror(errno));
