#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x2A
#define CTRL_REG1      0x2A
#define OUT_X_MSB      0x01
#define STATUS         0x00
#define TILT_THRESHOLD 45.0
#define LOG_FILE       "fall_log.txt"
#define POLL_DELAY_US  10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read (reg 0x%02X, len %zu) failed: %s\n", reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    uint8_t ctrl1 = 0;
    if (i2c_read_reg8(fd, CTRL_REG1, &ctrl1) != 0) {
        return -1;
    }
    ctrl1 &= ~(0x01); /* Standby mode */
    if (i2c_write_reg8(fd, CTRL_REG1, ctrl1) != 0) {
        return -1;
    }

    /* Data rate = 100 Hz (0x00), Active mode (0x01) */
    if (i2c_write_reg8(fd, CTRL_REG1, 0x01) != 0) {
        return -1;
    }

    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t status = 0;
    if (i2c_read_reg8(fd, STATUS, &status) != 0) {
        return -1;
    }
    if ((status & 0x08) == 0) {
        return 1; /* Data not ready yet */
    }

    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_MSB, buf, 6) != 0) {
        return -1;
    }

    *x = (int16_t)(((uint16_t)buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)(((uint16_t)buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)(((uint16_t)buf[4] << 8) | buf[5]) >> 4;

    return 0;
}

static double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double x_d = (double)x;
    double y_d = (double)y;
    double z_d = (double)z;
    double norm = sqrt(x_d * x_d + y_d * y_d + z_d * z_d);
    if (norm < 1.0) {
        return 0.0;
    }
    double x_n = x_d / norm;
    double y_n = y_d / norm;
    double z_n = z_d / norm;
    double tilt = atan2(sqrt(x_n * x_n + y_n * y_n), z_n) * 180.0 / M_PI;
    return tilt;
}

static void log_fall(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", ts, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
