        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("MMA8452Q initialized. Logging falls to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        int16_t x = 0, y = 0, z = 0;
        int rc = read_accel(g_i2c_fd, &x, &y, &z);
        if (rc == 0) {
            double tilt = calculate_tilt(x, y, z);
            if (tilt > TILT_THRESHOLD) {
                log_fall(g_log_fp, x, y, z);
                printf("Fall detected! Tilt: %.2f degrees\n", tilt);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error reading accelerometer data.\n");
        }
        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

