/*
 * LIS3MDL Magnetometer Metal Detector Logger
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL), address 0x1C
 * Output: magnetic_log.txt  (X,Y,Z mG, one line per sample)
 * Alert:  stderr when |sqrt(X²+Y²+Z²)| > 800 mG
 *
 * Build:  gcc -O2 -Wall -Wextra -o lis3mdl_log lis3mdl_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LIS3MDL constants (datasheet rev 0.9) ---- */
#define LIS3MDL_ADDR        0x1C
#define LIS3MDL_REG_CTRL_REG1 0x20
#define LIS3MDL_REG_CTRL_REG2 0x21
#define LIS3MDL_REG_CTRL_REG3 0x22
#define LIS3MDL_REG_CTRL_REG4 0x23
#define LIS3MDL_REG_OUT_X_L  0x28
#define LIS3MDL_REG_OUT_X_H  0x29
#define LIS3MDL_REG_OUT_Y_L  0x2A
#define LIS3MDL_REG_OUT_Y_H  0x2B
#define LIS3MDL_REG_OUT_Z_L  0x2C
#define LIS3MDL_REG_OUT_Z_H  0x2D

/* CTRL_REG1: temp sensor off, OM=±4 gauss, DO=10 Hz, fast mode off */
#define CTRL_REG1_VAL       0x70
/* CTRL_REG2: FS=±4 gauss, REBOOT=0, SOFT_RST=0 */
#define CTRL_REG2_VAL       0x00
/* CTRL_REG3: MD=continuous, LIR=0, SIM=0 */
#define CTRL_REG3_VAL       0x00
/* CTRL_REG4: ZOM=high performance, BLE=0, ZEN=1, YEN=1, XEN=1 */
#define CTRL_REG4_VAL       0x0C

/* Sensitivity: 0.146 mG/LSB at ±4 gauss */
#define SENSITIVITY_MG_LSB  0.146f

/* Alert threshold in mG */
#define ALERT_THRESHOLD_MG  800.0f

/* Calibration constants (replace with your own) */
#define X_OFFSET_MG         0.0f
#define Y_OFFSET_MG         0.0f
#define Z_OFFSET_MG         0.0f
#define X_SCALE_MG          1.0f
#define Y_SCALE_MG          1.0f
#define Z_SCALE_MG          1.0f

/* I2C bus on Raspberry Pi 3 B+ */
#define I2C_BUS             "/dev/i2c-1"

/* Sampling interval in microseconds (10 Hz) */
#define SAMPLE_PERIOD_US    100000

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, val, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int lis3mdl_init(int fd)
{
    if (i2c_write_reg8(fd, LIS3MDL_REG_CTRL_REG1, CTRL_REG1_VAL) != 0)
        return -1;
    if (i2c_write_reg8(fd, LIS3MDL_REG_CTRL_REG2, CTRL_REG2_VAL) != 0)
        return -1;
    if (i2c_write_reg8(fd, LIS3MDL_REG_CTRL_REG3, CTRL_REG3_VAL) != 0)
        return -1;
    if (i2c_write_reg8(fd, LIS3MDL_REG_CTRL_REG4, CTRL_REG4_VAL) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_reg8(fd, LIS3MDL_REG_OUT_X_L, &xl) != 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_REG_OUT_X_H, &xh) != 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_REG_OUT_Y_L, &yl) != 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_REG_OUT_Y_H, &yh) != 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_REG_OUT_Z_L, &zl) != 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_REG_OUT_Z_H, &zh) != 0) return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    *x = ((float)raw_x * SENSITIVITY_MG_LSB) + X_OFFSET_MG;
    *y = ((float)raw_y * SENSITIVITY_MG_LSB) + Y_OFFSET_MG;
    *z = ((float)raw_z * SENSITIVITY_MG_LSB) + Z_OFFSET_MG;

    *x *= X_SCALE_MG;
    *y *= Y_SCALE_MG;
    *z *= Z_SCALE_MG;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void check_alert(float x, float y, float z)
{
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > ALERT_THRESHOLD_MG) {
        fprintf(stderr,
                "ALERT: Metal detected! |B| = %.2f mG (X=%.2f Y=%.2f Z=%.2f)\n",
                mag, x, y, z);
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LIS3MDL_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor with retries */
    int init_ok = 0;
    for (int attempt = 1; attempt <= 3 && !init_ok; attempt++) {
        if (lis3mdl_init(g_i2c_fd) == 0) {
            init_ok = 1;
        } else {
            fprintf(stderr, "LIS3MDL init attempt %d/3 failed.\n", attempt);
            if (attempt < 3)
                usleep(100000);
        }
    }
    if (!init_ok) {
        fprintf(stderr, "LIS3MDL initialization failed after 3 attempts.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    g_log_fp = fopen("magnetic_log.txt", "w");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open magnetic_log.txt: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LIS3MDL metal detector logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
            check_alert(x, y, z);
        } else {
            fprintf(stderr, "Read error — continuing.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

