/*
 * ADXL354B Vibration Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL354B CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADXL354B SDO -> GPIO9  (BCM 9, SPI0 MISO)
 *   ADXL354B SDA -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADXL354B SCL -> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADXL354B VDD -> 3.3 V
 *   ADXL354B GND -> GND
 *
 * Build: gcc -O2 -Wall -o adxl354b_logger adxl354b_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ---- ADXL354B Register Definitions (from datasheet) ---- */
#define ADXL354B_REG_DEVID_AD   0x00
#define ADXL354B_REG_PARTID     0x02
#define ADXL354B_REG_XDATA_H    0x08
#define ADXL354B_REG_XDATA_L    0x09
#define ADXL354B_REG_XDATA_XL   0x0A
#define ADXL354B_REG_YDATA_H    0x0B
#define ADXL354B_REG_YDATA_L    0x0C
#define ADXL354B_REG_YDATA_XL   0x0D
#define ADXL354B_REG_ZDATA_H    0x0E
#define ADXL354B_REG_ZDATA_L    0x0F
#define ADXL354B_REG_ZDATA_XL   0x10
#define ADXL354B_REG_STATUS     0x18
#define ADXL354B_REG_POWER_CTL  0x2D
#define ADXL354B_REG_RESET      0x1F

#define ADXL354B_PARTID_VAL     0xAD
#define ADXL354B_STATUS_STABLE  0x01
#define ADXL354B_POWER_CTL_RUN  0x02
#define ADXL354B_RESET_VAL      0x52

/* ---- SPI Configuration ---- */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

/* ---- Timing ---- */
#define SAMPLE_PERIOD_US 100000U   /* 100 ms */
#define RETRY_DELAY_US   10000U    /* 10 ms  */
#define MAX_RETRIES      3

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Write a single byte to an ADXL354B register.
 *   tx[0] = register address (bit7=0 for write)
 *   tx[1] = data byte
 *   rx[1] = echoed data (optional)
 */
static int spi_write_reg(uint8_t reg, uint8_t value)
{
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an ADXL354B register.
 *   tx[0] = register address (bit7=1 for read)
 *   tx[1] = dummy (0x00)
 *   rx[1] = register value
 */
static int spi_read_reg(uint8_t reg, uint8_t *value)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = rx[1];
    return 0;
}

/*
 * Read a 20-bit signed acceleration value from the three consecutive
 * high-, low-, and extended-low data registers.
 *   tx[0] = register address (bit7=1 for read, bit6=1 for multi-byte)
 *   tx[1..3] = dummy (0x00)
 *   rx[1..3] = 20-bit data (MSB in rx[1], LSB in rx[3])
 */
static int spi_read_accel(uint8_t reg_h, int32_t *out)
{
    uint8_t tx[4] = { (uint8_t)(reg_h | 0xC0), 0x00, 0x00, 0x00 };
    uint8_t rx[4] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 4,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI multi-byte read from reg 0x%02X failed: %s\n",
                reg_h, strerror(errno));
        return -1;
    }

    /* 20-bit data: rx[1] high nibble + rx[2] 8 bits + rx[3] low 4 bits */
    uint32_t raw = ((uint32_t)(rx[1] & 0x0F) << 16) |
                   ((uint32_t)rx[2] << 8)        |
                   ((uint32_t)rx[3]);

    /* Sign-extend from 20 bits to 32 bits */
    if (raw & 0x80000) {
        raw |= 0xFFF00000;
    }

    *out = (int32_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL354B initialization                                             */
/* ------------------------------------------------------------------ */
static int adxl354b_init(void)
{
    uint8_t partid = 0;

    /* 1. Software reset */
    if (spi_write_reg(ADXL354B_REG_RESET, ADXL354B_RESET_VAL) < 0) {
        return -1;
    }
    usleep(1000);  /* 1 ms settle after reset */

    /* 2. Clear RUN bit to put device in standby */
    if (spi_write_reg(ADXL354B_REG_POWER_CTL, 0x00) < 0) {
        return -1;
    }
    usleep(1000);  /* 1 ms settle */

    /* 3. Wait for STABLE bit in STATUS to confirm sensor is ready */
    for (int i = 0; i < 100; i++) {
        if (spi_read_reg(ADXL354B_REG_STATUS, &partid) < 0) {
            return -1;
        }
        if (partid & ADXL354B_STATUS_STABLE) {
            break;
        }
        usleep(1000);  /* 1 ms */
    }
    if (!(partid & ADXL354B_STATUS_STABLE)) {
        fprintf(stderr, "ADXL354B not stable after reset (STATUS=0x%02X)\n",
                partid);
        return -1;
    }

    /* 4. Verify PARTID */
    if (spi_read_reg(ADXL354B_REG_PARTID, &partid) < 0) {
        return -1;
    }
    if (partid != ADXL354B_PARTID_VAL) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n",
                partid, ADXL354B_PARTID_VAL);
        return -1;
    }
    printf("ADXL354B detected (PARTID=0x%02X)\n", partid);

    /* 5. Set RUN bit to start measurements */
    if (spi_write_reg(ADXL354B_REG_POWER_CTL, ADXL354B_POWER_CTL_RUN) < 0) {
        return -1;
    }
    usleep(1000);  /* 1 ms settle */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Data logging                                                        */
/* ------------------------------------------------------------------ */
static int log_data(int32_t x, int32_t y, int32_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s, X: %d, Y: %d, Z: %d\n",
                timestamp, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        /* Put sensor in standby before closing */
        (void)spi_write_reg(ADXL354B_REG_POWER_CTL, 0x00);
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL354B */
    if (adxl354b_init() < 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen("vibration_log.txt", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open vibration_log.txt: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging vibration data to vibration_log.txt (Ctrl+C to stop)\n");

    /* Main sampling loop */
    while (g_running) {
        int32_t x = 0, y = 0, z = 0;
        int ok = 1;

        /* Read X axis with retry */
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (spi_read_accel(ADXL354B_REG_XDATA_H, &x) == 0) {
                break;
            }
            usleep(RETRY_DELAY_US);
        }
        if (attempt >= MAX_RETRIES) {
            fprintf(stderr, "X read failed after %d retries\n", MAX_RETRIES);
            ok = 0;
        }

        /* Read Y axis with retry */
        for (int attempt = 0; attempt < MAX_RETRIES && g_running && ok; attempt++) {
            if (spi_read_accel(ADXL354B_REG_YDATA_H, &y) == 0) {
                break;
            }
            usleep(RETRY_DELAY_US);
        }
        if (attempt >= MAX_RETRIES) {
            fprintf(stderr, "Y read failed after %d retries\n", MAX_RETRIES);
            ok = 0;
        }

        /* Read Z axis with retry */
        for (int attempt = 0; attempt < MAX_RETRIES && g_running && ok; attempt++) {
            if (spi_read_accel(ADXL354B_REG_ZDATA_H, &z) == 0) {
                break;
            }
            usleep(RETRY_DELAY_US);
        }
        if (attempt >= MAX_RETRIES) {
            fprintf(stderr, "Z read failed after %d retries\n", MAX_RETRIES);
            ok = 0;
        }

        if (ok) {
            if (log_data(x, y, z) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        }

        /* Sleep for the remainder of the sample period */
        if (g_running) {
            usleep(SAMPLE_PERIOD_US);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

