#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16362 Register Addresses (16-bit, MSB set for read) */
#define ADIS16362_REG_XGYRO_OUT  0x04
#define ADIS16362_REG_YGYRO_OUT  0x06
#define ADIS16362_REG_ZGYRO_OUT  0x08
#define ADIS16362_REG_XACCL_OUT  0x0A
#define ADIS16362_REG_YACCL_OUT  0x0C
#define ADIS16362_REG_ZACCL_OUT  0x0E

/* Scaling factors */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCEL_SCALE 0.0025f /* g per LSB */

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0x03    /* Mode 3: CPOL=1, CPHA=1 */

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 10000 /* 10 ms -> ~100 Hz */

/* Global resources for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from the ADIS16362 via SPI */
static int read_register(int handle, uint8_t reg_addr, int16_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    /* ADIS16362 read: send address with MSB set, then dummy byte */
    tx_buf[0] = (char)(reg_addr | 0x80);
    tx_buf[1] = 0x00;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    /* Small delay to allow clock to settle after address phase */
    gpioDelay(1);

    /* Read the data on the next 16-bit transfer */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for data read from register 0x%02X\n", reg_addr);
        return -1;
    }

    /* Data is returned in big-endian format */
    *value = (int16_t)(((uint16_t)(uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

/* Read all six IMU axes */
static int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;

    if (read_register(handle, ADIS16362_REG_XGYRO_OUT, &raw_gyro_x) != 0) return -1;
    if (read_register(handle, ADIS16362_REG_YGYRO_OUT, &raw_gyro_y) != 0) return -1;
    if (read_register(handle, ADIS16362_REG_ZGYRO_OUT, &raw_gyro_z) != 0) return -1;
    if (read_register(handle, ADIS16362_REG_XACCL_OUT, &raw_accel_x) != 0) return -1;
    if (read_register(handle, ADIS16362_REG_YACCL_OUT, &raw_accel_y) != 0) return -1;
    if (read_register(handle, ADIS16362_REG_ZACCL_OUT, &raw_accel_z) != 0) return -1;

    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    *accel_x = (float)raw_accel_x * ACCEL_SCALE;
    *accel_y = (float)raw_accel_y * ACCEL_SCALE;
    *accel_z = (float)raw_accel_z * ACCEL_SCALE;

    return 0;
}

/* Log one data record to the CSV file */
static int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z,
                    float accel_x, float accel_y, float accel_z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                (long)ts.tv_sec, ts.tv_nsec,
                gyro_x, gyro_y, gyro_z,
                accel_x, accel_y, accel_z) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        if (read_imu_data(spi_handle, &gyro_x, &gyro_y, &gyro_z,
                         &accel_x, &accel_y, &accel_z) == 0) {
            if (log_data(log_file, gyro_x, gyro_y, gyro_z,
                         accel_x, accel_y, accel_z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "IMU read failed, skipping sample...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

