/*
 * KY-032 IR Obstacle Avoidance Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: 2 × Keyes KY-032 (active-low digital output)
 *   Sensor 1 -> GPIO17 (physical pin 11)
 *   Sensor 2 -> GPIO27 (physical pin 13)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ky032_reader ky032_reader.c -lgpiod
 * Run:    sudo ./ky032_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define SENSOR_1_OFFSET 17
#define SENSOR_2_OFFSET 27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("[%s] ", buf);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Get the two GPIO lines --- */
    line1 = gpiod_chip_get_line(chip, SENSOR_1_OFFSET);
    if (line1 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                SENSOR_1_OFFSET, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR_2_OFFSET);
    if (line2 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                SENSOR_2_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* --- Request both lines as inputs --- */
    ret = gpiod_line_request_input(line1, "ky032-sensor1");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                SENSOR_1_OFFSET, strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_request_input(line2, "ky032-sensor2");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                SENSOR_2_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("KY-032 obstacle avoidance reader started.\n");
    printf("  Sensor 1 -> GPIO%d\n", SENSOR_1_OFFSET);
    printf("  Sensor 2 -> GPIO%d\n", SENSOR_2_OFFSET);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int val1, val2;

        /*
         * gpiod_line_get_value returns 0 or 1 on success, or -1 on error.
         * Active-low sensors read LOW (0) when an obstacle is detected.
         */
        val1 = gpiod_line_get_value(line1);
        val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            log_timestamp();
            fprintf(stderr, "Error reading GPIO lines: %s\n",
                    strerror(errno));
        } else {
            log_timestamp();
            printf("Sensor 1: %s  Sensor 2: %s\n",
                   (val1 == 0) ? "OBSTACLE" : "clear",
                   (val2 == 0) ? "OBSTACLE" : "clear");
        }

        /* Sleep 100 ms; interruptible by signals */
        struct timespec ts = {
            .tv_sec  = POLL_INTERVAL_MS / 1000,
            .tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L
        };
        nanosleep(&ts, NULL);
    }

    printf("\nShutting down cleanly...\n");

cleanup:
    /* Release lines and close chip on every exit path */
    if (line1 != NULL)
        gpiod_line_release(line1);
    if (line2 != NULL)
        gpiod_line_release(line2);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

