#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8U
#define SPI_MODE        SPI_MODE_3
#define SPI_DELAY_US    0U

#define ADIS16266_REG_XGYRO_OUT  0x04
#define ADIS16266_REG_YGYRO_OUT  0x06
#define ADIS16266_REG_ZGYRO_OUT  0x08
#define ADIS16266_REG_SMPL_PRD   0x36
#define ADIS16266_REG_GLOB_CMD   0x68

#define ADIS16266_GLOB_CMD_RESET  0x0001
#define ADIS16266_GLOB_CMD_NULL   0x0000

#define ADIS16266_SCALE_FACTOR   0.02f   /* deg/sec per LSB */
#define SAMPLE_PERIOD_MS        100

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * ADIS16266 two-transfer read protocol:
 *   tx[0] = (reg | 0x80)  (MSB = 1 for read)
 *   tx[1] = 0x00          (dummy, clocks out low byte)
 *   rx[0] = don't care
 *   rx[1] = low byte of register data
 *   rx[2] = high byte of register data
 */
static int adis16266_read_register(int fd, uint8_t reg, uint16_t *value)
{
    if (value == NULL) {
        return -1;
    }

    uint8_t tx[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE (read reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = (uint16_t)((rx[2] << 8) | rx[1]);
    return 0;
}

static int adis16266_write_register(int fd, uint8_t reg, uint16_t value)
{
    uint8_t tx[3] = { (uint8_t)(reg & 0x7F), (uint8_t)(value & 0xFF),
                     (uint8_t)((value >> 8) & 0xFF) };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE (write reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int adis16266_init(int fd)
{
    /* Software reset */
    if (adis16266_write_register(fd, ADIS16266_REG_GLOB_CMD,
                                ADIS16266_GLOB_CMD_RESET) < 0) {
        fprintf(stderr, "ADIS16266 reset failed\n");
        return -1;
    }
    usleep(10000);  /* 10 ms settle after reset */

    /* Clear any stale command */
    if (adis16266_write_register(fd, ADIS16266_REG_GLOB_CMD,
                                ADIS16266_GLOB_CMD_NULL) < 0) {
        fprintf(stderr, "ADIS16266 clear command failed\n");
        return -1;
    }

    /*
     * Set sample period to 100 ms (0x0064).
     * ADIS16266 internal clock is 500 kHz; SMPL_PRD = 100 ms / 2 us = 50000.
     */
    if (adis16266_write_register(fd, ADIS16266_REG_SMPL_PRD, 0x0064) < 0) {
        fprintf(stderr, "ADIS16266 set sample period failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                    */
/* ------------------------------------------------------------------ */
static int adis16266_read_gyro_data(int fd, float *x, float *y, float *z)
{
    uint16_t raw_x, raw_y, raw_z;

    if (adis16266_read_register(fd, ADIS16266_REG_XGYRO_OUT, &raw_x) < 0)
        return -1;
    if (adis16266_read_register(fd, ADIS16266_REG_YGYRO_OUT, &raw_y) < 0)
        return -1;
    if (adis16266_read_register(fd, ADIS16266_REG_ZGYRO_OUT, &raw_z) < 0)
        return -1;

    /*
     * ADIS16266 gyro outputs are 16-bit two's-complement.
     * The scale factor is 0.02 deg/sec per LSB.
     */
    *x = (float)((int16_t)raw_x) * ADIS16266_SCALE_FACTOR;
    *y = (float)((int16_t)raw_y) * ADIS16266_SCALE_FACTOR;
    *z = (float)((int16_t)raw_z) * ADIS16266_SCALE_FACTOR;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    if (adis16266_init(g_spi_fd) < 0) {
        fprintf(stderr, "ADIS16266 initialization failed (sensor absent or bus error)\n");
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    printf("ADIS16266 initialized. Reading gyroscope data every %d ms...\n",
           SAMPLE_PERIOD_MS);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float x, y, z;

        if (adis16266_read_gyro_data(g_spi_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
            usleep(SAMPLE_PERIOD_MS * 1000U);
            continue;
        }

        printf("X: %+.2f deg/s, Y: %+.2f deg/s, Z: %+.2f deg/s\n", x, y, z);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_MS * 1000U);
    }

    printf("\nExiting gracefully...\n");

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    return EXIT_SUCCESS;
}

