/*
 * LSM6DSR IMU reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL), Address: 0x6A
 * Sensors: accelerometer (X/Y/Z), gyroscope (X/Y/Z)
 * Output: six 16-bit signed values per line, separated by spaces
 * Build: gcc -O2 -Wall -o lsm6dsr lsm6dsr.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM6DSR constants ---- */
#define LSM6DSR_ADDR        0x6A
#define WHO_AM_I_REG        0x0F
#define WHO_AM_I_VAL        0x69

#define CTRL1_XL            0x10
#define CTRL2_G             0x11
#define CTRL3_C             0x12
#define CTRL4_C             0x13
#define CTRL5_C             0x14
#define CTRL6_C             0x15
#define CTRL7_G             0x16
#define CTRL8_XL            0x17
#define CTRL9_XL            0x18
#define CTRL10_C            0x19

#define OUTX_L_G            0x22
#define OUTX_H_G            0x23
#define OUTY_L_G            0x24
#define OUTY_H_G            0x25
#define OUTZ_L_G            0x26
#define OUTZ_H_G            0x27
#define OUTX_L_XL           0x28
#define OUTX_H_XL           0x29
#define OUTY_L_XL           0x2A
#define OUTY_H_XL           0x2B
#define OUTZ_L_XL           0x2C
#define OUTZ_H_XL           0x2D

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C set register pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read data */
    ssize_t n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from 0x%02X failed: %s (got %zd of %zu)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int16_t le16_to_s16(const uint8_t *p)
{
    return (int16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
}

/* ------------------------------------------------------------------ */
static int init_imu(int fd)
{
    uint8_t whoami = 0;

    /* Verify device identity */
    if (i2c_read_burst(fd, WHO_AM_I_REG, &whoami, 1) != 0)
        return -1;
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, WHO_AM_I_VAL);
        return -1;
    }

    /*
     * CTRL1_XL: ODR_XL = 1000 Hz (0x60), FS_XL = +/- 2 g (0x00)
     * CTRL2_G:  ODR_G  = 1000 Hz (0x60), FS_G  = +/- 245 dps (0x00)
     * CTRL3_C:  BDU = 1 (bit 3), IF_INC = 1 (bit 2)
     * CTRL4_C:  BLE = 0 (bit 6), FS_125 = 0 (bit 3)
     * CTRL5_C:  DEC_FIFO_XL = 00 (no decimation)
     * CTRL6_C:  ODR_XL_G = 1000 Hz (0x60)
     * CTRL7_G:  FS_G = +/- 245 dps (0x00)
     * CTRL8_XL: BDU = 1 (bit 3), IF_INC = 1 (bit 2)
     * CTRL9_XL: XL_OM = 00 (ultra-high perf), XL_HM = 0 (normal mode)
     * CTRL10_C: GYRO_HM = 0 (normal mode)
     */
    if (i2c_write_reg(fd, CTRL1_XL, 0x60) != 0) return -1;
    if (i2c_write_reg(fd, CTRL2_G,  0x60) != 0) return -1;
    if (i2c_write_reg(fd, CTRL3_C,  0x08) != 0) return -1;
    if (i2c_write_reg(fd, CTRL4_C,  0x00) != 0) return -1;
    if (i2c_write_reg(fd, CTRL5_C,  0x00) != 0) return -1;
    if (i2c_write_reg(fd, CTRL6_C,  0x60) != 0) return -1;
    if (i2c_write_reg(fd, CTRL7_G,  0x00) != 0) return -1;
    if (i2c_write_reg(fd, CTRL8_XL, 0x08) != 0) return -1;
    if (i2c_write_reg(fd, CTRL9_XL, 0x00) != 0) return -1;
    if (i2c_write_reg(fd, CTRL10_C, 0x00) != 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_imu(int fd, int16_t *ax, int16_t *ay, int16_t *az,
                    int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[12];

    /*
     * Burst read 12 bytes starting at OUTX_L_G:
     *   0x22 OUTX_L_G  0x23 OUTX_H_G  0x24 OUTY_L_G  0x25 OUTY_H_G
     *   0x26 OUTZ_L_G  0x27 OUTZ_H_G  0x28 OUTX_L_XL 0x29 OUTX_H_XL
     *   0x2A OUTY_L_XL 0x2B OUTY_H_XL 0x2C OUTZ_L_XL 0x2D OUTZ_H_XL
     */
    if (i2c_read_burst(fd, OUTX_L_G, buf, sizeof(buf)) != 0)
        return -1;

    *gx = le16_to_s16(&buf[0]);
    *gy = le16_to_s16(&buf[2]);
    *gz = le16_to_s16(&buf[4]);
    *ax = le16_to_s16(&buf[6]);
    *ay = le16_to_s16(&buf[8]);
    *az = le16_to_s16(&buf[10]);

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the LSM6DSR slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM6DSR_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LSM6DSR_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize the IMU */
    if (init_imu(g_i2c_fd) != 0) {
        fprintf(stderr, "IMU initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialized. Sampling every 100 ms. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_imu(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("%d %d %d %d %d %d\n", ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read IMU data.\n");
            break;
        }

        /* Sleep 100 ms; use nanosleep for signal-safe interruption */
        struct timespec ts = { 0, 100 * 1000 * 1000 };
        while (nanosleep(&ts, &ts) != 0 && errno == EINTR) {
            if (!g_running)
                break;
        }
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

