    *gy = le16_to_s16(&buf[2]);
    *gz = le16_to_s16(&buf[4]);
    *ax = le16_to_s16(&buf[6]);
    *ay = le16_to_s16(&buf[8]);
    *az = le16_to_s16(&buf[10]);

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the LSM6DSR slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM6DSR_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LSM6DSR_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize the IMU */
    if (init_imu(g_i2c_fd) != 0) {
        fprintf(stderr, "IMU initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialized. Sampling every 100 ms. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (read_imu(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("%d %d %d %d %d %d\n", ax, ay, az, gx, gy, gz);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read IMU data.\n");
            break;
        }

        /* Sleep 100 ms; use nanosleep for signal-safe interruption */
        struct timespec ts = { 0, 100 * 1000 * 1000 };
        while (nanosleep(&ts, &ts) != 0 && errno == EINTR) {
            if (!g_running)
                break;
        }
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

