/*
 * FXOS8700 I2C reader for Raspberry Pi 4 Model B
 * Bus: I2C-1 (SDA=GPIO2, SCL=GPIO3, BCM), Address: 0x1D
 *
 * Reads a 12-byte block: 6 bytes accel (14-bit left-aligned) + 6 bytes mag (16-bit).
 * Prints raw X/Y/Z values for accel and mag, retrying on transient errors.
 *
 * Build: gcc -O2 -Wall -o fxos8700 fxos8700.c -lpigpio -lrt
 * Run:   sudo ./fxos8700
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700 constants ---- */
#define FXOS8700_ADDR        0x1D
#define FXOS8700_REG_STATUS  0x00
#define FXOS8700_REG_OUT_X_MSB 0x01
#define FXOS8700_REG_WHOAMI   0x0D
#define FXOS8700_WHOAMI_VAL   0xC7
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E
#define FXOS8700_REG_CTRL_REG1 0x2A
#define FXOS8700_REG_CTRL_REG2 0x2B
#define FXOS8700_REG_M_CTRL_REG1 0x5B
#define FXOS8700_REG_M_CTRL_REG2 0x5C

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read a single byte from a register ---- */
static int read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* ---- Write a single byte to a register ---- */
static int write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

/* ---- Read a block of bytes starting at a register ---- */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: got %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ---- Initialize FXOS8700 ---- */
static int init_fxos8700(int handle)
{
    uint8_t whoami = 0;

    /* Verify device identity */
    if (read_reg(handle, FXOS8700_REG_WHOAMI, &whoami) != 0) {
        fprintf(stderr, "[ERROR] Cannot read WHOAMI register.\n");
        return -1;
    }
    if (whoami != FXOS8700_WHOAMI_VAL) {
        fprintf(stderr, "[ERROR] WHOAMI mismatch: got 0x%02X, expected 0x%02X.\n",
                whoami, FXOS8700_WHOAMI_VAL);
        return -1;
    }

    /* Standby mode before configuration */
    if (write_reg(handle, FXOS8700_REG_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Set accelerometer range to +/- 2g (FS=00) */
    if (write_reg(handle, FXOS8700_REG_XYZ_DATA_CFG, 0x00) != 0)
        return -1;

    /* Magnetometer: OSR=00 (high performance), auto-reset, ultra-high perf */
    if (write_reg(handle, FXOS8700_REG_M_CTRL_REG1, 0x1F) != 0)
        return -1;

    /* Magnetometer: auto-sleep, 100 Hz ODR */
    if (write_reg(handle, FXOS8700_REG_M_CTRL_REG2, 0x20) != 0)
        return -1;

    /* Active mode, 100 Hz ODR */
    if (write_reg(handle, FXOS8700_REG_CTRL_REG1, 0x0D) != 0)
        return -1;

    return 0;
}

/* ---- Convert 14-bit left-aligned accel data to raw signed 16-bit ---- */
static int16_t convert_accel_14bit(uint8_t msb, uint8_t lsb)
{
    int16_t raw = (int16_t)((msb << 8) | lsb);
    /* Sign-extend from 14 bits to 16 bits */
    if (raw & 0x2000)
        raw |= 0xC000;
    return raw;
}

/* ---- Convert 16-bit magnetometer data to raw signed 16-bit ---- */
static int16_t convert_mag_16bit(uint8_t msb, uint8_t lsb)
{
    return (int16_t)((msb << 8) | lsb);
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700 address */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                FXOS8700_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_fxos8700(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] FXOS8700 initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("FXOS8700 initialized. Reading every 100 ms (Ctrl+C to stop)...\n");

    /* Main loop */
    while (g_running) {
        uint8_t data[12];

        /* Read 12 bytes: 6 accel + 6 mag */
        if (read_block(g_i2c_handle, FXOS8700_REG_OUT_X_MSB, data, sizeof(data)) != 0) {
            /* Transient read error — back off and retry */
            gpioDelay(100000); /* 100 ms */
            continue;
        }

        /* Extract accelerometer (14-bit left-aligned, 6 bytes) */
        int16_t ax = convert_accel_14bit(data[0], data[1]);
        int16_t ay = convert_accel_14bit(data[2], data[3]);
        int16_t az = convert_accel_14bit(data[4], data[5]);

        /* Extract magnetometer (16-bit, 6 bytes) */
        int16_t mx = convert_mag_16bit(data[6], data[7]);
        int16_t my = convert_mag_16bit(data[8], data[9]);
        int16_t mz = convert_mag_16bit(data[10], data[11]);

        printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Mag: X=%6d  Y=%6d  Z=%6d\n",
               ax, ay, az, mx, my, mz);

        gpioDelay(100000); /* 100 ms */
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        /* Put sensor in standby before closing */
        (void)write_reg(g_i2c_handle, FXOS8700_REG_CTRL_REG1, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

