/*
 * ADXL345 Tilt Monitor for Raspberry Pi 5
 * Reads acceleration data from an ADXL345 over I2C, evaluates the tilt angle,
 * and logs timestamped tilt events to /var/log/tilt_events.log.
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO 2 (I2C1 SDA)
 *   ADXL345 SCL -> GPIO 3 (I2C1 SCL)
 *   ADXL345 VCC -> 3.3 V
 *   ADXL345 GND -> GND
 *
 * Build: gcc -O2 -Wall -o tilt_monitor tilt_monitor.c -lm -lpigpio -lrt
 * Run:   sudo ./tilt_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS pin tied to GND) */
#define ADXL345_ADDR 0x53

/* ADXL345 registers */
#define ADXL345_REG_DEVID       0x00
#define ADXL345_REG_POWER_CTL   0x2D
#define ADXL345_REG_DATAX0      0x32
#define ADXL345_REG_BW_RATE     0x2C
#define ADXL345_REG_DATA_FORMAT 0x31

/* Expected device ID */
#define ADXL345_DEVID_EXPECTED 0xE5

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 30.0

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Structure to hold acceleration data */
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

/* Function prototypes */
static int initialize_i2c(void);
static int read_acceleration_data(accelerometer_data_t *data);
static double calculate_tilt_angle(const accelerometer_data_t *data);
static void log_tilt_event(double tilt_angle);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* Initializes the I2C interface */
static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0); /* Bus 1, address 0x53, no flags */
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X: %d\n",
                ADXL345_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    /* Verify device identity */
    int devid = i2cReadByteData(i2c_handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: Failed to read DEVID register: %d\n", devid);
        cleanup();
        return -1;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "Error: ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_EXPECTED);
        cleanup();
        return -1;
    }

    /* Configure ADXL345: Standby mode */
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set ADXL345 to standby mode\n");
        cleanup();
        return -1;
    }

    /* Set data rate to 100 Hz (0x0A) */
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error: Failed to set ADXL345 data rate\n");
        cleanup();
        return -1;
    }

    /* Set data format: Full resolution, +/- 2g range (0x08) */
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to set ADXL345 data format\n");
        cleanup();
        return -1;
    }

    /* Enable measurement mode */
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to set ADXL345 to measurement mode\n");
        cleanup();
        return -1;
    }

    return 0;
}

/* Reads raw acceleration data from the ADXL345 */
static int read_acceleration_data(accelerometer_data_t *data) {
    char buffer[6];

    /* Read 6 bytes starting from DATAX0 (0x32) */
    int bytes_read = i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error: Failed to read acceleration data (read %d bytes)\n", bytes_read);
        return -1;
    }

    /* Combine high and low bytes (little-endian) */
    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

/* Calculates the tilt angle from the acceleration data */
static double calculate_tilt_angle(const accelerometer_data_t *data) {
    double x = (double)data->x;
    double y = (double)data->y;
    double z = (double)data->z;

    /* Calculate the magnitude of the acceleration vector */
    double magnitude = sqrt(x * x + y * y + z * z);

    /* Normalize the acceleration vector */
    if (magnitude > 0.0) {
        x /= magnitude;
        y /= magnitude;
        z /= magnitude;
    }

    /* Calculate the tilt angle (in degrees) */
    double tilt_angle = atan2(y, sqrt(x * x + z * z)) * 180.0 / M_PI;

    return tilt_angle;
}

/* Logs a tilt event to the log file */
static void log_tilt_event(double tilt_angle) {
    FILE *fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Tilt angle: %.2f degrees\n", timestamp, tilt_angle);
    fclose(fp);
}

int main(void) {
    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
