#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN        17
#define WINDOW_SECONDS  5
#define SAMPLE_US       1000   /* 1 ms */
#define PAUSE_US        1000000 /* 1 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int parse_threshold(const char *arg, int *out)
{
    char *endptr = NULL;
    errno = 0;
    long val = strtol(arg, &endptr, 10);

    if (errno != 0 || endptr == arg || *endptr != '\0') {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return -1;
    }
    if (val <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return -1;
    }
    *out = (int)val;
    return 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r()");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }
    printf("[%s] ", buf);
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  <threshold>  Minimum number of high readings per 5-second window.\n");
        return EXIT_FAILURE;
    }

    int threshold;
    if (parse_threshold(argv[1], &threshold) != 0) {
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d (BCM) for %d-second windows.\n",
           GPIO_PIN, WINDOW_SECONDS);
    printf("Threshold: %d high readings per window. Press Ctrl+C to exit.\n",
           threshold);
    fflush(stdout);

    while (g_running) {
        int high_count = 0;
        int sample_count = 0;

        /*
         * Break the 5-second window into 1-ms slices so we can respond
         * promptly to signals.
         */
        for (int i = 0; i < WINDOW_SECONDS * 1000 && g_running; i++) {
            int level = gpioRead(GPIO_PIN);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead(%d) failed.\n", GPIO_PIN);
                break;
            }
            if (level == 1) {
                high_count++;
            }
            sample_count++;
            gpioDelay(SAMPLE_US);
        }

        if (!g_running) {
            break;
        }

        print_timestamp();

        if (high_count > threshold) {
            printf("ALERT: %d high readings (%d samples) exceeds threshold %d\n",
                   high_count, sample_count, threshold);
        } else {
            printf("Status: %d high readings (%d samples) below threshold %d\n",
                   high_count, sample_count, threshold);
        }
        fflush(stdout);

        /*
         * Sleep in 100 ms slices so we can respond promptly to signals.
         */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(PAUSE_US / 10);
        }
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

