#define DOOR_A_PIN 17
#define DOOR_B_PIN 27
#define UNLOCK_DURATION_SEC 5
#define CODE_LENGTH 6
#define LOG_FILE "access_log.txt"
#define CHIP_NAME "gpiochip4"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int generate_code(void) {
    return (rand() % 900000) + 100000;
}

static int log_access(int code) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%06d\n", timestamp, code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int unlock_door(struct gpiod_line *line, int duration_sec) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error unlocking door (GPIO%d): %s\n",
                gpiod_line_offset(line), strerror(errno));
        return -1;
    }

    sleep(duration_sec);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error locking door (GPIO%d): %s\n",
                gpiod_line_offset(line), strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *door_a_line = NULL;
    struct gpiod_line *door_b_line = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(door_a_line, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(door_b_line, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int code = generate_code();
        printf("Enter access code (6 digits): ");
        fflush(stdout);

        char input[CODE_LENGTH + 1];
        if (!fgets(input, sizeof(input), stdin)) {
            if (feof(stdin)) {
                printf("\nEOF received, exiting.\n");
                break;
            }
            fprintf(stderr, "Error reading input: %s\n", strerror(errno));
            continue;
        }

        input[strcspn(input, "\n")] = '\0';

        if (strlen(input) != CODE_LENGTH) {
            fprintf(stderr, "Invalid code length. Please enter %d digits.\n", CODE_LENGTH);
            continue;
        }

        char *endptr = NULL;
        long entered_code = strtol(input, &endptr, 10);
        if (*endptr != '\0' || entered_code < 100000 || entered_code > 999999) {
            fprintf(stderr, "Invalid code. Please enter a 6-digit number.\n");
            continue;
        }

        if (entered_code == code) {
            printf("Access granted!\n");
            if (log_access(code) < 0) {
                fprintf(stderr, "Warning: Failed to log access.\n");
            }

            if (unlock_door(door_a_line, UNLOCK_DURATION_SEC) < 0) {
                fprintf(stderr, "Warning: Failed to unlock Door A.\n");
            }
            if (unlock_door(door_b_line, UNLOCK_DURATION_SEC) < 0) {
                fprintf(stderr, "Warning: Failed to unlock Door B.\n");
            }
        } else {
            printf("Access denied!\n");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (door_a_line) {
        gpiod_line_set_value(door_a_line, 0);
        gpiod_line_release(door_a_line);
    }
    if (door_b_line) {
        gpiod_line_set_value(door_b_line, 0);
        gpiod_line_release(door_b_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Door access control system stopped.\n");
    return ret;
}

