#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_CONVERSION_TIME_MS 180
#define LOG_FILE "light_log.txt"
#define SAMPLE_INTERVAL_MS 5000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    char buf[2];
    int result;

    result = i2cWriteDevice(handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device (handle %d): %s\n", handle, strerror(errno));
        return -1;
    }

    gpioDelay(BH1750_CONVERSION_TIME_MS * 1000);

    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device (handle %d): expected 2 bytes, got %d: %s\n", handle, result, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X on bus 1: %s\n", BH1750_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BH1750 light sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            if (log_data(LOG_FILE, lux) != 0) {
                fprintf(stderr, "Error logging data.\n");
            } else {
                printf("Lux: %.2f\n", lux);
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in %d ms...\n", SAMPLE_INTERVAL_MS);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

