static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to MPR121 register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, buf, 1) != 0) {
        fprintf(stderr, "Error selecting MPR121 register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error reading MPR121 register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)buf[0];
    return 0;
}

