#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LSM303_ADDR    0x1E
#define CTRL_REG1_M    0x20
#define CTRL_REG2_M    0x21
#define CTRL_REG3_M    0x22
#define OUT_X_H_M      0x29
#define LED_GPIO       17
#define PWM_FREQ       1000
#define PWM_RANGE      255
#define SAMPLE_US      100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_magnetometer(int fd) {
    if (i2c_write_reg(fd, CTRL_REG1_M, 0x10) < 0) return -1;  /* temp sensor off, ODR 15 Hz */
    if (i2c_write_reg(fd, CTRL_REG2_M, 0x00) < 0) return -1;  /* +/- 4 gauss full scale */
    if (i2c_write_reg(fd, CTRL_REG3_M, 0x00) < 0) return -1;  /* continuous conversion */
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_H_M, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static float calc_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrtf((float)x * x + (float)y * y + (float)z * z);
}

static int set_led_brightness(int gpio, float mag) {
    int val = (int)(mag * 255.0f / 6000.0f);
    if (val < 0) val = 0;
    if (val > 255) val = 255;
    if (gpioPWM(gpio, val) < 0) {
        fprintf(stderr, "gpioPWM failed on GPIO%d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    char dev_path[32];
    snprintf(dev_path, sizeof(dev_path), "/dev/i2c-%d", I2C_BUS);
    g_i2c_fd = open(dev_path, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", dev_path, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LSM303_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("magnetometer_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Magnetometer data acquisition started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float mag = calc_magnitude(x, y, z);
        if (set_led_brightness(LED_GPIO, mag) < 0) {
            fprintf(stderr, "LED PWM error\n");
        }

        time_t now = time(NULL);
        struct tm tm_info;
        localtime_r(&now, &tm_info);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(g_log_fp, "%s, X=%d, Y=%d, Z=%d, Mag=%.2f\n", ts, x, y, z, mag);
        fflush(g_log_fp);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

