/*
 * HMC5883L magnetometer reader with hard-iron offset compensation.
 *
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Device: HMC5883L (7-bit address 0x1E)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hmc5883l hmc5883l.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- HMC5883L constants ---- */
#define HMC5883L_ADDR        0x1E
#define HMC5883L_CONFIG_A    0x00
#define HMC5883L_CONFIG_B    0x01
#define HMC5883L_MODE        0x02
#define HMC5883L_DATA_X_MSB  0x03

#define HMC5883L_MODE_CONT   0x00   /* continuous measurement, 15 Hz */
#define HMC5883L_GAIN_130    0x20   /* gain = 1.3 Gauss */

#define SAMPLE_PERIOD_US    500000 /* 500 ms */
#define NUM_SAMPLES         100

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an HMC5883L register; returns 0 on success, -1 on  */
/* failure.                                                           */
/* ------------------------------------------------------------------ */
static int hmc_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read N bytes starting at an HMC5883L register; returns 0 on success, */
/* -1 on failure.                                                      */
/* ------------------------------------------------------------------ */
static int hmc_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %s\n",
                reg, len, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Initialise the HMC5883L: configure gain and mode, then verify the   */
/* device identity by reading the CONFIG_A register.                  */
/* ------------------------------------------------------------------ */
static int hmc5883l_init(int handle)
{
    /* Gain = 1.3 Gauss, continuous measurement mode */
    if (hmc_write_reg(handle, HMC5883L_CONFIG_A, HMC5883L_GAIN_130) < 0)
        return -1;

    /* 75 Hz output rate, normal measurement bias */
    if (hmc_write_reg(handle, HMC5883L_CONFIG_B, 0x00) < 0)
        return -1;

    /* Continuous measurement mode */
    if (hmc_write_reg(handle, HMC5883L_MODE, HMC5883L_MODE_CONT) < 0)
        return -1;

    /* Verify device identity by reading CONFIG_A back */
    int cfg = i2cReadByteData(handle, HMC5883L_CONFIG_A);
    if (cfg < 0) {
        fprintf(stderr, "[ERROR] HMC5883L not responding on bus: %s\n", strerror(errno));
        return -1;
    }
    if ((cfg & 0x0F) != (HMC5883L_GAIN_130 & 0x0F)) {
        fprintf(stderr, "[ERROR] HMC5883L gain mismatch (got 0x%02X, expected 0x%02X)\n",
                cfg & 0x0F, HMC5883L_GAIN_130 & 0x0F);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one raw sample from the HMC5883L.                              */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int hmc5883l_read_raw(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    if (hmc_read_block(handle, HMC5883L_DATA_X_MSB, buf, sizeof(buf)) < 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute the running average of the last NUM_SAMPLES samples.        */
/* ------------------------------------------------------------------ */
static void compute_average(const int16_t *x, const int16_t *y, const int16_t *z,
                            int n, int16_t *avg_x, int16_t *avg_y, int16_t *avg_z)
{
    double sx = 0.0, sy = 0.0, sz = 0.0;
    for (int i = 0; i < n; i++) {
        sx += x[i];
        sy += y[i];
        sz += z[i];
    }
    *avg_x = (int16_t)(sx / n);
    *avg_y = (int16_t)(sy / n);
    *avg_z = (int16_t)(sz / n);
}

/* ------------------------------------------------------------------ */
/* Apply hard-iron offsets to a raw reading.                            */
/* ------------------------------------------------------------------ */
static void apply_offsets(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                          int16_t off_x, int16_t off_y, int16_t off_z,
                          int16_t *cor_x, int16_t *cor_y, int16_t *cor_z)
{
    *cor_x = raw_x - off_x;
    *cor_y = raw_y - off_y;
    *cor_z = raw_z - off_z;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t raw_x[NUM_SAMPLES], raw_y[NUM_SAMPLES], raw_z[NUM_SAMPLES];
    int16_t avg_x = 0, avg_y = 0, avg_z = 0;
    int     sample_count = 0;
    int     exit_code = EXIT_SUCCESS;

    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at HMC5883L address ---- */
    g_i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                HMC5883L_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise magnetometer ---- */
    if (hmc5883l_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[ERROR] HMC5883L initialisation failed\n");
        exit_code = EXIT_FAILURE;
        goto cleanup;
    }

    printf("HMC5883L initialised. Sampling every %d ms. Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_US / 1000);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t rx, ry, rz;

        if (hmc5883l_read_raw(g_i2c_handle, &rx, &ry, &rz) < 0) {
            /* I2C read error already reported; continue sampling */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        raw_x[sample_count] = rx;
        raw_y[sample_count] = ry;
        raw_z[sample_count] = rz;

        sample_count++;

        if (sample_count >= NUM_SAMPLES) {
            compute_average(raw_x, raw_y, raw_z, NUM_SAMPLES, &avg_x, &avg_y, &avg_z);
            sample_count = 0;
        }

        int16_t cx, cy, cz;
        apply_offsets(rx, ry, rz, avg_x, avg_y, avg_z, &cx, &cy, &cz);

        printf("X: %6d  Y: %6d  Z: %6d  |  Offsets: X=%4d  Y=%4d  Z=%4d\n",
               cx, cy, cz, avg_x, avg_y, avg_z);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");

cleanup:
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return exit_code;
}

