/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W
 *
 * Reads tri-axial acceleration at ~10 ms intervals, stores the last 64
 * samples in a circular buffer, and dumps the last 10 samples on a rising
 * edge of the INT1 (BCM GPIO 23, physical pin 16) interrupt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 *
 * Wiring:
 *   LSM303D SDA  -> GPIO 2  (physical pin 3)
 *   LSM303D SCL  -> GPIO 3  (physical pin 5)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 *   LSM303D INT1 -> GPIO 23 (physical pin 16)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D register definitions (from datasheet) ---- */
#define LSM303D_ADDR_ACCEL 0x19
#define LSM303D_ADDR_MAG   0x1E

#define LSM303D_WHO_AM_I_A 0x0F
#define LSM303D_WHO_AM_I_A_VAL 0x49

#define LSM303D_CTRL_REG1_A 0x20
#define LSM303D_CTRL_REG4_A 0x23
#define LSM303D_OUT_X_L_A   0x28

#define LSM303D_CTRL_REG1_M 0x20
#define LSM303D_CTRL_REG2_M 0x21
#define LSM303D_CTRL_REG3_M 0x22
#define LSM303D_CTRL_REG4_M 0x23
#define LSM303D_OUT_X_L_M   0x28

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1 = NULL;

/* ---- Circular buffer ---- */
#define BUFFER_SIZE 64
typedef struct {
    struct timespec ts;
    int16_t x, y, z;
} accel_sample_t;

static accel_sample_t g_buffer[BUFFER_SIZE];
static int g_buf_head = 0;
static int g_buf_count = 0;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Accelerometer init ---- */
static int accel_init(int fd)
{
    uint8_t who;
    if (i2c_read_reg(fd, LSM303D_WHO_AM_I_A, &who) != 0)
        return -1;
    if (who != LSM303D_WHO_AM_I_A_VAL) {
        fprintf(stderr, "Accel WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM303D_WHO_AM_I_A_VAL);
        return -1;
    }

    /* CTRL_REG1_A: 100 Hz ODR, all axes enabled */
    if (i2c_write_reg(fd, LSM303D_CTRL_REG1_A, 0x57) != 0)
        return -1;

    /* CTRL_REG4_A: FS = +/- 2g, high-resolution mode */
    if (i2c_write_reg(fd, LSM303D_CTRL_REG4_A, 0x08) != 0)
        return -1;

    return 0;
}

/* ---- Read acceleration (mg per LSB) ---- */
static int accel_read(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, LSM303D_OUT_X_L_A | 0x80, buf, 6) != 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_add(const struct timespec *ts, int16_t x, int16_t y, int16_t z)
{
    g_buffer[g_buf_head].ts = *ts;
    g_buffer[g_buf_head].x = x;
    g_buffer[g_buf_head].y = y;
    g_buffer[g_buf_head].z = z;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

static void buffer_dump_last10(void)
{
    int start = (g_buf_count < 10) ? 0 : (g_buf_head - 10 + BUFFER_SIZE) % BUFFER_SIZE;
    int count = (g_buf_count < 10) ? g_buf_count : 10;

    printf("\n--- Last %d Acceleration Samples ---\n", count);
    for (int i = 0; i < count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char tbuf[32];
        struct tm tm;
        localtime_r(&g_buffer[idx].ts.tv_sec, &tm);
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
        printf("[%s.%03ld] X=%6d Y=%6d Z=%6d\n",
               tbuf, g_buffer[idx].ts.tv_nsec / 1000000L,
               g_buffer[idx].x, g_buffer[idx].y, g_buffer[idx].z);
    }
    fflush(stdout);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_int1) {
        gpiod_line_release(g_int1);
        g_int1 = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer before closing */
        (void)i2c_write_reg(g_i2c_fd, LSM303D_CTRL_REG1_A, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 (GPIO2/3 on Pi Zero W) */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR_ACCEL) < 0) {
        perror("ioctl I2C_SLAVE accel");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize accelerometer */
    if (accel_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Accelerometer initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }

    g_int1 = gpiod_chip_get_line(g_chip, 23);
    if (!g_int1) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_int1, "lsm303d_mon") < 0) {
        perror("gpiod_line_request_rising_edge_events");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303D monitor started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        int16_t x, y, z;
        struct timespec ts;

        if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
            perror("clock_gettime");
            usleep(10000);
            continue;
        }

        if (accel_read(g_i2c_fd, &x, &y, &z) == 0) {
            buffer_add(&ts, x, y, z);
        } else {
            fprintf(stderr, "Warning: accelerometer read failed, skipping sample.\n");
        }

        /* Check for INT1 event */
        struct timespec ts_wait = { 0, 10000000 }; /* 10 ms */
        int ev = gpiod_line_event_wait(g_int1, &ts_wait);
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            perror("gpiod_line_event_wait");
            continue;
        }
        if (ev == 1) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(g_int1, &event) == 0) {
                if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    buffer_dump_last10();
                }
            }
        }

        usleep(10000); /* 10 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

