#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS       500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_solenoid(int pin, int state)
{
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", pin, state);
        return -1;
    }
    return 0;
}

static int sleep_ms(unsigned int ms)
{
    struct timespec ts;
    ts.tv_sec  = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    while (nanosleep(&ts, &ts) != 0) {
        if (errno != EINTR) {
            perror("nanosleep");
            return -1;
        }
        if (!g_running) {
            return 0;
        }
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure both solenoids are OFF at startup */
    if (set_solenoid(SOLENOID_1_PIN, 0) != 0 ||
        set_solenoid(SOLENOID_2_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int active_pin = SOLENOID_1_PIN;

    while (g_running) {
        if (set_solenoid(active_pin, 1) != 0) {
            break;
        }

        if (sleep_ms(DELAY_MS) != 0) {
            break;
        }

        if (set_solenoid(active_pin, 0) != 0) {
            break;
        }

        active_pin = (active_pin == SOLENOID_1_PIN) ? SOLENOID_2_PIN : SOLENOID_1_PIN;
    }

    /* Clean shutdown: de-energize both solenoids */
    set_solenoid(SOLENOID_1_PIN, 0);
    set_solenoid(SOLENOID_2_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

