/*
 * Dual-factor door-lock authentication for Raspberry Pi 4 Model B.
 *
 * Two 12 V electromagnetic door locks are driven by two active-HIGH relays
 * on GPIO17 (BCM) and GPIO27 (BCM).  Two 9600 8N1 UART ports read 6-digit
 * codes from /dev/serial0 and /dev/serial1.  Codes must match both ports
 * and the constant "123456" to unlock the door for 2 s.
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define UART_PORT_1      "/dev/serial0"
#define UART_PORT_2      "/dev/serial1"
#define BAUD_RATE        9600
#define CODE_LENGTH      6
#define EXPECTED_CODE    "123456"
#define UNLOCK_DURATION  2          /* seconds */
#define READ_TIMEOUT_SEC 5          /* per-port read timeout */
#define POLL_INTERVAL_US 10000      /* 10 ms main-loop sleep */

#define GPIO_CHIP_NAME   "gpiochip4" /* BCM GPIO controller on Pi 4 */
#define LOCK_1_PIN       17
#define LOCK_2_PIN       27

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Sleep for `duration_sec` seconds, interruptible by signals.
 * Returns 0 on success, -1 on signal.
 */
static int sleep_interruptible(unsigned int duration_sec)
{
    while (duration_sec > 0 && g_running) {
        unsigned int chunk = (duration_sec > 10) ? 10 : duration_sec;
        sleep(chunk);
        duration_sec -= chunk;
    }
    return g_running ? 0 : -1;
}

/*
 * Constant-time string comparison (no timing side-channels).
 * Returns 0 if equal, non-zero otherwise.
 */
static int const_time_strcmp(const char *a, const char *b)
{
    size_t len = strlen(a);
    if (len != strlen(b))
        return 1;
    int diff = 0;
    for (size_t i = 0; i < len; i++)
        diff |= (int)((unsigned char)a[i] ^ (unsigned char)b[i]);
    return diff;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lock1 = NULL;
    struct gpiod_line *lock2 = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    lock1 = gpiod_chip_get_line(chip, LOCK_1_PIN);
    if (!lock1) {
        perror("gpiod_chip_get_line(lock1)");
        goto cleanup;
    }

    lock2 = gpiod_chip_get_line(chip, LOCK_2_PIN);
    if (!lock2) {
        perror("gpiod_chip_get_line(lock2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW (locked). */
    if (gpiod_line_request_output(lock1, "door_lock", 0) < 0) {
        perror("gpiod_line_request_output(lock1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(lock2, "door_lock", 0) < 0) {
        perror("gpiod_line_request_output(lock2)");
        goto cleanup;
    }

    printf("Door lock system started.  GPIO%d=lock1, GPIO%d=lock2.\n",
           LOCK_1_PIN, LOCK_2_PIN);
    printf("Expected code: %s\n", EXPECTED_CODE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    char code1[CODE_LENGTH + 1] = {0};
    char code2[CODE_LENGTH + 1] = {0};
    size_t idx1 = 0, idx2 = 0;
    bool code1_ready = false, code2_ready = false;

    while (g_running) {
        /* ---- Port 1 ---- */
        char ch;
        ssize_t n = gpiod_line_read(lock1, &ch);
        if (n < 0) {
            perror("gpiod_line_read(lock1)");
            goto cleanup;
        }
        if (n == 1) {
            if (ch >= '0' && ch <= '9') {
                if (idx1 < CODE_LENGTH)
                    code1[idx1++] = ch;
            } else {
                code1[0] = '\0';
                idx1 = 0;
            }
            if (idx1 == CODE_LENGTH) {
                code1_ready = true;
                code1[CODE_LENGTH] = '\0';
            }
        }

        /* ---- Port 2 ---- */
        n = gpiod_line_read(lock2, &ch);
        if (n < 0) {
            perror("gpiod_line_read(lock2)");
            goto cleanup;
        }
        if (n == 1) {
            if (ch >= '0' && ch <= '9') {
                if (idx2 < CODE_LENGTH)
                    code2[idx2++] = ch;
            } else {
                code2[0] = '\0';
                idx2 = 0;
            }
            if (idx2 == CODE_LENGTH) {
                code2_ready = true;
                code2[CODE_LENGTH] = '\0';
            }
        }

        /* ---- Check for both codes ---- */
        if (code1_ready && code2_ready) {
            printf("Code1: %s  Code2: %s\n", code1, code2);

            if (const_time_strcmp(code1, code2) != 0) {
                fprintf(stderr, "ERROR: Codes do not match.\n");
            } else if (const_time_strcmp(code1, EXPECTED_CODE) != 0) {
