 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define UART_PORT_1      "/dev/serial0"
#define UART_PORT_2      "/dev/serial1"
#define BAUD_RATE        9600
#define CODE_LENGTH      6
#define EXPECTED_CODE    "123456"
#define UNLOCK_DURATION  2          /* seconds */
#define READ_TIMEOUT_SEC 5          /* per-port read timeout */
#define POLL_INTERVAL_US 10000      /* 10 ms main-loop sleep */

#define GPIO_CHIP_NAME   "gpiochip4" /* BCM GPIO controller on Pi 4 */
#define LOCK_1_PIN       17
#define LOCK_2_PIN       27

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Sleep for `duration_sec` seconds, interruptible by signals.
 * Returns 0 on success, -1 on signal.
 */
static int sleep_interruptible(unsigned int duration_sec)
{
    while (duration_sec > 0 && g_running) {
        unsigned int chunk = (duration_sec > 10) ? 10 : duration_sec;
        sleep(chunk);
        duration_sec -= chunk;
    }
    return g_running ? 0 : -1;
}

/*
 * Constant-time string comparison (no timing side-channels).
 * Returns 0 if equal, non-zero otherwise.
 */
static int const_time_strcmp(const char *a, const char *b)
{
    size_t len = strlen(a);
    if (len != strlen(b))
        return 1;
    int diff = 0;
    for (size_t i = 0; i < len; i++)
        diff |= (int)((unsigned char)a[i] ^ (unsigned char)b[i]);
    return diff;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lock1 = NULL;
    struct gpiod_line *lock2 = NULL;
    int ret = EXIT_FAILURE;

