    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    lock1 = gpiod_chip_get_line(chip, LOCK_1_PIN);
    if (!lock1) {
        perror("gpiod_chip_get_line(lock1)");
        goto cleanup;
    }

