                       UNLOCK_DURATION);
                fflush(stdout);

                if (gpiod_line_set_value(lock1, 1) < 0) {
                    perror("gpiod_line_set_value(lock1 HIGH)");
                    goto cleanup;
                }
                if (gpiod_line_set_value(lock2, 1) < 0) {
                    perror("gpiod_line_set_value(lock2 HIGH)");
                    goto cleanup;
                }

                if (sleep_interruptible(UNLOCK_DURATION) < 0) {
                    fprintf(stderr, "Interrupted during unlock.\n");
                }

                if (gpiod_line_set_value(lock1, 0) < 0) {
                    perror("gpiod_line_set_value(lock1 LOW)");
                    goto cleanup;
                }
                if (gpiod_line_set_value(lock2, 0) < 0) {
                    perror("gpiod_line_set_value(lock2 LOW)");
                    goto cleanup;
                }

                printf("Door locked.\n");
                fflush(stdout);
            }

