/*
 * PIR-triggered door strike controller for Raspberry Pi 4 Model B.
 *
 * Hardware:
 *   - HC-SR501 PIR sensor  -> GPIO4  (physical pin 7)
 *   - Door strike relay    -> GPIO17 (physical pin 11)
 *
 * Behavior:
 *   Polls the PIR every 50 ms.  When a motion event (HIGH) is detected:
 *     - Logs a syslog INFO entry.
 *     - Activates the relay for 1 s.
 *     - Logs a syslog INFO entry.
 *     - De-energizes the relay.
 *   If the PIR stays HIGH for > 10 s:
 *     - Logs a syslog WARNING entry.
 *     - De-energizes the relay.
 *     - Logs a syslog CRITICAL entry.
 *     - Shuts down the system.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o pir_strike pir_strike.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN          4
#define RELAY_PIN        17
#define POLL_INTERVAL_US 50000   /* 50 ms */
#define RELAY_HOLD_US    1000000 /* 1 s   */
#define FAILSAFE_TIMEOUT 10      /* seconds */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
}

static void sleep_us(unsigned int us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Open syslog ---- */
    openlog("pir_strike", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        goto cleanup;
    }

    /* ---- Open the default gpiochip (gpiochip4 on Pi 4/5) ---- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(\"gpiochip4\"): %s", strerror(errno));
        goto cleanup;
    }

    /* ---- Get the PIR line ---- */
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (pir_line == NULL) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d): %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Get the relay line ---- */
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (relay_line == NULL) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d): %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request PIR as input ---- */
    if (gpiod_line_request_input(pir_line, "pir_strike") < 0) {
        syslog(LOG_ERR, "gpiod_line_request_input(%d): %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request relay as output, initial value LOW ---- */
    if (gpiod_line_request_output(relay_line, "pir_strike", 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_request_output(%d): %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    log_event(LOG_INFO, "PIR-strike controller started.");

    time_t last_motion_time = 0;
    int relay_active = 0;

    while (g_running) {
        int pir_val = gpiod_line_get_value(pir_line);
        if (pir_val < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value(%d): %s", PIR_PIN, strerror(errno));
            sleep_us(POLL_INTERVAL_US);
            continue;
        }

        if (pir_val == 1) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                syslog(LOG_ERR, "time(): %s", strerror(errno));
            } else {
                if (last_motion_time == 0) {
                    last_motion_time = now;
                    log_event(LOG_INFO, "Motion detected on PIR sensor.");
                } else if (difftime(now, last_motion_time) >= FAILSAFE_TIMEOUT) {
                    if (!relay_active) {
                        log_event(LOG_WARNING, "Failsafe triggered: PIR HIGH for > 10 s.");
                        if (gpiod_line_set_value(relay_line, 1) < 0) {
                            syslog(LOG_ERR, "gpiod_line_set_value(%d, 1): %s", RELAY_PIN, strerror(errno));
                        } else {
                            relay_active = 1;
                            log_event(LOG_INFO, "Relay activated (failsafe).");
                        }
                    }
                    /* De-energize relay after failsafe hold */
                    if (relay_active) {
                        if (gpiod_line_set_value(relay_line, 0) < 0) {
                            syslog(LOG_ERR, "gpiod_line_set_value(%d, 0): %s", RELAY_PIN, strerror(errno));
                        } else {
                            relay_active = 0;
                            log_event(LOG_INFO, "Relay de-activated (failsafe).");
                        }
                    }
                    log_event(LOG_CRIT, "System shutting down due to PIR malfunction.");
                    sync();
                    closelog();
                    if (relay_line) {
                        gpiod_line_set_value(relay_line, 0);
                        gpiod_line_release(relay_line);
                    }
                    if (pir_line) {
                        gpiod_line_release(pir_line);
                    }
                    if (chip) {
                        gpiod_chip_close(chip);
                    }
                    _exit(EXIT_FAILURE);
                }
            }
        } else {
            last_motion_time = 0;
        }

        if (pir_val == 1 && !relay_active) {
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                syslog(LOG_ERR, "gpiod_line_set_value(%d, 1): %s", RELAY_PIN, strerror(errno));
            } else {
                relay_active = 1;
                log_event(LOG_INFO, "Relay activated.");
            }
        }

        if (relay_active) {
            sleep_us(RELAY_HOLD_US);
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                syslog(LOG_ERR, "gpiod_line_set_value(%d, 0): %s", RELAY_PIN, strerror(errno));
            } else {
                relay_active = 0;
                log_event(LOG_INFO, "Relay de-activated.");
            }
        }

        sleep_us(POLL_INTERVAL_US);
    }

    log_event(LOG_INFO, "Shutting down gracefully.");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

