                log_event(LOG_INFO, "Relay de-activated.");
            }
        }

        sleep_us(POLL_INTERVAL_US);
    }

    log_event(LOG_INFO, "Shutting down gracefully.");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

