/*
 * MPU6050 accelerometer sampler for Raspberry Pi 4 Model B.
 *
 * Samples acceleration data at 100 Hz using a POSIX per-process timer
 * (SIGEV_SIGNAL) and stores the most recent sample in a circular buffer.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mpu6050_accel mpu6050_accel.c
 *
 * The driver library interface is a simple sysfs-style interface that
 * exposes the most recent X/Y/Z acceleration values as read-only files:
 *
 *   /sys/kernel/mpu6050_accel/latest/x
 *   /sys/kernel/mpu6050_accel/latest/y
 *   /sys/kernel/mpu6050_accel/latest/z
 *
 * The driver is created and removed by the kernel module
 * mpu6050_accel_drv.c.  The module is compiled into the kernel and
 * loaded/unloaded by the build script.
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

/* MPU6050 registers */
#define MPU6050_REG_PWR_MGMT_1   0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_WHO_AM_I     0x75
#define MPU6050_WHO_AM_I_VAL     0x68

#define ACCEL_SCALE 16384.0f   /* +/- 2g range */

#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_NS 10000000L  /* 100 Hz */

#define DRIVER_DIR "/sys/kernel/mpu6050_accel"
#define DRIVER_X   DRIVER_DIR "/latest/x"
#define DRIVER_Y   DRIVER_DIR "/latest/y"
#define DRIVER_Z   DRIVER_DIR "/latest/z"

typedef struct {
    float x, y, z;
} accel_data_t;

typedef struct {
    accel_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static circular_buffer_t g_buffer;
static timer_t g_timer_id;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, value, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *value)
{
    uint8_t buf[2];
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* MPU6050                                                             */
/* ------------------------------------------------------------------ */
static int mpu6050_init(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, MPU6050_REG_WHO_AM_I, &who_am_i) != 0)
        return -1;
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_reg8(fd, MPU6050_REG_PWR_MGMT_1, 0x00) != 0)
        return -1;
    usleep(100000);  /* allow oscillator to stabilize */
    return 0;
}

static int mpu6050_read_accel(int fd, accel_data_t *out)
{
    int16_t raw_x, raw_y, raw_z;
    if (i2c_read_reg16(fd, MPU6050_REG_ACCEL_XOUT_H, &raw_x) != 0)
        return -1;
    if (i2c_read_reg16(fd, MPU6050_REG_ACCEL_XOUT_H + 2, &raw_y) != 0)
        return -1;
    if (i2c_read_reg16(fd, MPU6050_REG_ACCEL_XOUT_H + 4, &raw_z) != 0)
        return -1;
    out->x = (float)raw_x / ACCEL_SCALE;
    out->y = (float)raw_y / ACCEL_SCALE;
    out->z = (float)raw_z / ACCEL_SCALE;
    return 0;
}

