#define DRIVER_Z   DRIVER_DIR "/latest/z"

typedef struct {
    float x, y, z;
} accel_data_t;

typedef struct {
    accel_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static circular_buffer_t g_buffer;
