    if (mknod(DRIVER_Z, S_IRUSR | S_IWUSR, 0) == -1 && errno != EEXIST) {
        fprintf(stderr, "mknod(%s) failed: %s\n", DRIVER_Z, strerror(errno));
        return -1;
    }
    return 0;
}

