#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define RELAY1_INTERVAL 2
#define RELAY2_INTERVAL 3
#define RELAY3_INTERVAL 5
#define RELAY4_INTERVAL 7

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%u to mode %u\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: failed to write GPIO%u to level %u\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_toggle(unsigned pin) {
    int current = gpioRead(pin);
    if (current < 0) {
        fprintf(stderr, "Error: failed to read GPIO%u\n", pin);
        return -1;
    }
    return safe_write(pin, current == 0 ? 1 : 0);
}

static int safe_off(unsigned pin) {
    return safe_write(pin, 0);
}

static void cleanup(void) {
    safe_off(RELAY1_PIN);
    safe_off(RELAY2_PIN);
    safe_off(RELAY3_PIN);
    safe_off(RELAY4_PIN);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY4_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (safe_off(RELAY1_PIN) != 0 || safe_off(RELAY2_PIN) != 0 ||
        safe_off(RELAY3_PIN) != 0 || safe_off(RELAY4_PIN) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct timespec next_toggle[4];
    for (int i = 0; i < 4; i++) {
        next_toggle[i].tv_sec = 0;
        next_toggle[i].tv_nsec = 0;
    }

    while (running) {
        struct timespec now;
        if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
            perror("clock_gettime");
            break;
        }

        for (int i = 0; i < 4; i++) {
            if (next_toggle[i].tv_sec == 0 && next_toggle[i].tv_nsec == 0) {
                next_toggle[i].tv_sec = now.tv_sec + (i + 2);
                next_toggle[i].tv_nsec = now.tv_nsec;
            } else if (now.tv_sec > next_toggle[i].tv_sec ||
                       (now.tv_sec == next_toggle[i].tv_sec && now.tv_nsec >= next_toggle[i].tv_nsec)) {
                int pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
                if (safe_toggle(pins[i]) != 0) {
                    break;
                }
                next_toggle[i].tv_sec += (i + 2);
            }
        }

        if (running) {
            struct timespec sleep_until;
            sleep_until.tv_sec = next_toggle[0].tv_sec;
            sleep_until.tv_nsec = next_toggle[0].tv_nsec;
            for (int i = 1; i < 4; i++) {
                if (next_toggle[i].tv_sec < sleep_until.tv_sec ||
                    (next_toggle[i].tv_sec == sleep_until.tv_sec && next_toggle[i].tv_nsec < sleep_until.tv_nsec)) {
                    sleep_until = next_toggle[i];
                }
            }
            struct timespec remaining;
            if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
                perror("clock_gettime");
                break;
            }
            remaining.tv_sec = sleep_until.tv_sec - now.tv_sec;
            remaining.tv_nsec = sleep_until.tv_nsec - now.tv_nsec;
            if (remaining.tv_nsec < 0) {
                remaining.tv_sec--;
                remaining.tv_nsec += 1000000000L;
            }
            if (remaining.tv_sec > 0 || remaining.tv_nsec > 0) {
                nanosleep(&remaining, NULL);
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

