/*
 * MH-Z19B CO2 Monitor for Raspberry Pi 3 Model B+
 *
 * Reads CO2 concentration over UART (/dev/serial0, 9600 baud, 8N1)
 * using the provided driver API (libthe_driver).  Logs JSON to
 * co2_log.json and errors to co2_error.log.
 *
 * Build:  gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lthe_driver -lrt
 * Run:    sudo ./co2_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <the_driver.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define SAMPLE_INTERVAL  5          /* seconds between readings */
#define RESPONSE_TIMEOUT 1          /* seconds to wait for full response */
#define RESPONSE_SIZE    9          /* bytes: command(2) + status(1) + ppm(2) + checksum(1) */
#define READ_CHUNK       1024       /* buffer for partial reads */
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp  = NULL;
static FILE *g_err_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    if (!g_err_fp)
        return;

    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm_buf;
    struct tm *tm = localtime_r(&tv.tv_sec, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(g_err_fp, "%s.%06ldZ ERROR: %s (errno=%d: %s)\n",
            ts, (long)tv.tv_usec, msg, errno, strerror(errno));
    fflush(g_err_fp);
}

/* ------------------------------------------------------------------ */
/* UART helpers                                                        */
/* ------------------------------------------------------------------ */
static int uart_open(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        log_error("open() failed");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        log_error("tcgetattr() failed");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag  = (tty.c_cflag & ~CSIZE) | CS8;   /* 8 data bits */
    tty.c_cflag |= (CLOCAL | CREAD);               /* ignore modem control, enable receiver */
    tty.c_cflag &= ~(PARENB | PARODD);             /* no parity */
    tty.c_cflag &= ~CSTOPB;                        /* 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;                       /* no hardware flow control */

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 1;   /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        log_error("tcsetattr() failed");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/*
 * Read exactly `n` bytes from the UART within `timeout` seconds.
 * Returns 0 on success, -1 on timeout or error.
 */
static int uart_read_exact(int fd, uint8_t *buf, size_t n, int timeout)
{
    size_t got = 0;
    struct timeval start, now;
    gettimeofday(&start, NULL);

    while (got < n) {
        if (!g_running)
            return -1;

        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);

        struct timeval tv;
        tv.tv_sec  = timeout;
        tv.tv_usec = 0;

        int rv = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (rv < 0) {
            if (errno == EINTR)
                continue;
            log_error("select() failed");
            return -1;
        }
        if (rv == 0) {
            log_error("UART read timeout");
            return -1;
        }

        ssize_t r = read(fd, buf + got, n - got);
        if (r < 0) {
            if (errno == EINTR)
                continue;
            log_error("read() failed");
            return -1;
        }
        if (r == 0) {
            log_error("UART closed unexpectedly");
            return -1;
        }

        got += (size_t)r;
        gettimeofday(&now, NULL);
        if ((now.tv_sec - start.tv_sec) > timeout) {
            log_error("UART read timeout");
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MH-Z19B driver                                                      */
/* ------------------------------------------------------------------ */
static int mhz19_read_ppm(int fd, uint16_t *ppm)
{
    uint8_t cmd[2] = {0xFF, 0x01};   /* command: read ppm */
    uint8_t resp[RESPONSE_SIZE];

    ssize_t w = write(fd, cmd, sizeof(cmd));
    if (w != (ssize_t)sizeof(cmd)) {
        log_error("write() failed to send command");
        return -1;
    }

    if (uart_read_exact(fd, resp, sizeof(resp), RESPONSE_TIMEOUT) != 0)
        return -1;

    /* Validate response: first 2 bytes must match command */
    if (resp[0] != 0xFF || resp[1] != 0x86) {
        log_error("MH-Z19B: unexpected response header");
        return -1;
    }

    /* Status byte: 0x00 = OK, 0x01 = command error, 0x02 = checksum error */
    if (resp[2] != 0x00) {
        char msg[64];
        snprintf(msg, sizeof(msg), "MH-Z19B status error: 0x%02X", resp[2]);
        log_error(msg);
        return -1;
    }

    /* PPM: bytes 3-4, big-endian */
    *ppm = ((uint16_t)resp[3] << 8) | resp[4];
    return 0;
}

/* ------------------------------------------------------------------ */
/* JSON logging                                                        */
/* ------------------------------------------------------------------ */
static int log_json(uint16_t ppm, int error)
{
    if (!g_log_fp)
        return -1;

    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm tm_buf;
    struct tm *tm = localtime_r(&tv.tv_sec, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(g_log_fp,
            "{\"timestamp\":\"%s.%06ldZ\",\"ppm\":%u,\"error\":%d}\n",
            ts, (long)tv.tv_usec, ppm, error);
    fflush(g_log_fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open log files */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }
    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("fopen(" ERROR_LOG_FILE ")");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* Open UART */
    g_uart_fd = uart_open(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MH-Z19B CO2 monitor started on %s @ 9600 baud.\n", UART_DEVICE);
    printf("Logging to %s, errors to %s. Press Ctrl+C to stop.\n",
           LOG_FILE, ERROR_LOG_FILE);

    while (g_running) {
        uint16_t ppm = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (mhz19_read_ppm(g_uart_fd, &ppm) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1)
                sleep(1);
        }

        if (ok) {
            if (log_json(ppm, 0) == 0)
                printf("CO2: %u ppm\n", ppm);
        } else {
            log_json(0, 1);
            fprintf(stderr, "Failed to read CO2 after %d attempts.\n", MAX_RETRIES);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

