#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR        0x1E
#define HMC5883L_CONFIG_A    0x00
#define HMC5883L_CONFIG_B    0x01
#define HMC5883L_MODE        0x02
#define HMC5883L_DATA_X_MSB  0x03
#define HMC5883L_DATA_Z_MSB  0x05
#define HMC5883L_DATA_Y_MSB  0x07

#define GPIO_PIN             17
#define BUFFER_SIZE          100
#define TARGET_HEADING       90.0f
#define HEADING_THRESHOLD    10.0f
#define SAMPLE_INTERVAL_US   100000
#define I2C_BUS              1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    float x;
    float y;
} magnetometer_data_t;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_hmc5883l(int handle) {
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to HMC5883L CONFIG_A register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to HMC5883L CONFIG_B register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to HMC5883L MODE register\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer_data(int handle, magnetometer_data_t *data) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    data->x = (float)((int16_t)((buffer[0] << 8) | buffer[1]));
    data->y = (float)((int16_t)((buffer[4] << 8) | buffer[5]));
    return 0;
}

static void apply_hard_iron_compensation(magnetometer_data_t *data, float x_offset, float y_offset) {
    data->x -= x_offset;
    data->y -= y_offset;
}

static float calculate_heading(magnetometer_data_t *data) {
    float heading = atan2f(data->y, data->x) * 180.0f / M_PI;
    if (heading < 0.0f) {
        heading += 360.0f;
    }
    return heading;
}

static void add_to_circular_buffer(circular_buffer_t *buffer, float value) {
    buffer->buffer[buffer->head] = value;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

static float calculate_average(circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

static void control_gpio(int pin, bool activate) {
    gpioWrite(pin, activate ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hmc5883l(i2c_handle) != 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    circular_buffer_t heading_buffer = {0};
    float x_offset = 100.0f;
    float y_offset = -50.0f;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        magnetometer_data_t raw_data;
        if (read_magnetometer_data(i2c_handle, &raw_data) == 0) {
            apply_hard_iron_compensation(&raw_data, x_offset, y_offset);
            float heading = calculate_heading(&raw_data);
            add_to_circular_buffer(&heading_buffer, heading);
            float average_heading = calculate_average(&heading_buffer);
            float deviation = fabsf(average_heading - TARGET_HEADING);
            if (deviation > 180.0f) {
                deviation = 360.0f - deviation;
            }
            control_gpio(GPIO_PIN, deviation > HEADING_THRESHOLD);
        } else {
            fprintf(stderr, "Failed to read magnetometer data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

