#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define BH1750_ADDR             0x23
#define BH1750_CONTINUOUS_HIGH  0x10
#define BH1750_CONV_TIME_MS     120
#define LOG_FILE                "lighting_log.txt"

#define RED_PIN    17
#define GREEN_PIN  27
#define BLUE_PIN   22

#define LUX_THRESHOLD_1 50.0f
#define LUX_THRESHOLD_2 150.0f
#define LUX_THRESHOLD_3 300.0f

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    if (i2c_write_byte(fd, BH1750_CONTINUOUS_HIGH) < 0) {
        return -1;
    }

    usleep(BH1750_CONV_TIME_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relays(struct gpiod_line *red, struct gpiod_line *green, struct gpiod_line *blue, float lux) {
    int red_val = 0, green_val = 0, blue_val = 0;

    if (lux < LUX_THRESHOLD_1) {
        red_val = 1;
    } else if (lux < LUX_THRESHOLD_2) {
        green_val = 1;
    } else if (lux < LUX_THRESHOLD_3) {
        blue_val = 1;
    } else {
        red_val = 1;
        green_val = 1;
        blue_val = 1;
    }

    gpiod_line_set_value(red, red_val);
    gpiod_line_set_value(green, green_val);
    gpiod_line_set_value(blue, blue_val);
}

static void log_data(FILE *fp, float lux, int red, int green, int blue) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Lux: %.2f, RED: %d, GREEN: %d, BLUE: %d\n",
            timestamp, lux, red, green, blue);
    fflush(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        goto cleanup;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "bh1750_relay", 0) < 0 ||
        gpiod_line_request_output(green_line, "bh1750_relay", 0) < 0 ||
        gpiod_line_request_output(blue_line, "bh1750_relay", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        goto cleanup;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Starting lighting control. Press Ctrl+C to exit.\n");

    while (program_running) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed; retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        int red_val = gpiod_line_get_value(red_line);
        int green_val = gpiod_line_get_value(green_line);
        int blue_val = gpiod_line_get_value(blue_line);

        control_relays(red_line, green_line, blue_line, lux);

        log_data(log_fp, lux, red_val, green_val, blue_val);

        printf("Lux: %.2f, RED: %d, GREEN: %d, BLUE: %d\n", lux, red_val, green_val, blue_val);

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);

    printf("Exiting.\n");
    return ret;
}

