#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_gpio_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_gpio_pwm(unsigned gpio, unsigned duty) {
    if (gpioPWM(gpio, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_pwm_frequency(unsigned gpio, unsigned freq) {
    if (gpioSetPWMfrequency(gpio, freq) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u, %u) failed\n", gpio, freq);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_pwm_range(unsigned gpio, unsigned range) {
    if (gpioSetPWMrange(gpio, range) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%u, %u) failed\n", gpio, range);
        return -1;
    }
    return 0;
}

static int motor_stop(void) {
    int rc = 0;
    rc |= safe_gpio_write(MOTOR_A_IN1, 0);
    rc |= safe_gpio_write(MOTOR_A_IN2, 0);
    rc |= safe_gpio_write(MOTOR_B_IN3, 0);
    rc |= safe_gpio_write(MOTOR_B_IN4, 0);
    return rc;
}

static int motor_forward(unsigned motor_in1, unsigned motor_in2, unsigned duty) {
    int rc = 0;
    rc |= safe_gpio_write(motor_in1, 1);
    rc |= safe_gpio_write(motor_in2, 0);
    rc |= safe_gpio_pwm(motor_in2, duty);
    return rc;
}

static int motor_backward(unsigned motor_in1, unsigned motor_in2, unsigned duty) {
    int rc = 0;
    rc |= safe_gpio_write(motor_in1, 0);
    rc |= safe_gpio_write(motor_in2, 1);
    rc |= safe_gpio_pwm(motor_in2, duty);
    return rc;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_motor_a> <distance_motor_b>\n", argv[0]);
        fprintf(stderr, "  distance_motor_a: distance in cm (10-100)\n");
        fprintf(stderr, "  distance_motor_b: distance in cm (10-100)\n");
        return EXIT_FAILURE;
    }

    int distance_a = atoi(argv[1]);
    int distance_b = atoi(argv[2]);

    if (distance_a < 10 || distance_a > 100 || distance_b < 10 || distance_b > 100) {
        fprintf(stderr, "Error: distances must be between 10 and 100 cm\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
