#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define LOG_FILE "solar_tracker.log"
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

int init_mpu6050(int fd) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) == 0) break;
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    if (retries == MAX_RETRIES) return -1;

    retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) == 0) break;
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    if (retries == MAX_RETRIES) return -1;

    retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) == 0) break;
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    if (retries == MAX_RETRIES) return -1;

    return 0;
}

int read_mpu6050(int fd, int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 14) == 0) break;
        retries++;
