#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION_SEC 1800
#define FADE_STEPS 100
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_schedule(const char *filename, int *schedule, int *num_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening schedule file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (count >= 24) {
            fprintf(stderr, "Warning: schedule file has more than 24 entries, ignoring extra lines\n");
            break;
        }

        char *saveptr = NULL;
        char *token = strtok_r(line, ",\n", &saveptr);
        if (!token) {
            fprintf(stderr, "Warning: empty line in schedule file at line %d\n", count + 1);
            continue;
        }

        int hour, minute, second, relay_num, state;
        if (sscanf(token, "%d:%d:%d", &hour, &minute, &second) != 3) {
            fprintf(stderr, "Warning: invalid time format at line %d\n", count + 1);
            continue;
        }

        token = strtok_r(NULL, ",\n", &saveptr);
        if (!token) {
            fprintf(stderr, "Warning: missing relay number at line %d\n", count + 1);
            continue;
        }
        relay_num = atoi(token);
        if (relay_num < 0 || relay_num >= NUM_RELAYS) {
            fprintf(stderr, "Warning: invalid relay number %d at line %d\n", relay_num, count + 1);
            continue;
        }

        token = strtok_r(NULL, ",\n", &saveptr);
        if (!token) {
            fprintf(stderr, "Warning: missing state at line %d\n", count + 1);
            continue;
        }
        if (strcmp(token, "on") == 0) {
            state = 1;
        } else if (strcmp(token, "off") == 0) {
            state = 0;
        } else {
            fprintf(stderr, "Warning: invalid state '%s' at line %d\n", token, count + 1);
            continue;
        }

        schedule[count * 3] = hour;
        schedule[count * 3 + 1] = minute;
        schedule[count * 3 + 2] = second;
        count++;
    }

    fclose(fp);
    *num_entries = count;
    return 0;
}

static int calculate_current_time(int *hour, int *minute, int *second) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    *hour = timeinfo->tm_hour;
    *minute = timeinfo->tm_min;
    *second = timeinfo->tm_sec;
    return 0;
}

static int find_next_schedule_entry(const int *schedule, int num_entries, int current_time, int *next_time, int *relay_num, int *state) {
    int current_hour = current_time / 3600;
    int current_minute = (current_time % 3600) / 60;
    int current_second = current_time % 60;

    for (int i = 0; i < num_entries; i++) {
        int entry_time = schedule[i * 3] * 3600 + schedule[i * 3 + 1] * 60 + schedule[i * 3 + 2];
        if (entry_time >= current_time) {
            *next_time = entry_time;
            *relay_num = schedule[i * 3 + 3];
            *state = schedule[i * 3 + 4];
            return 0;
        }
    }

    *next_time = schedule[0] * 3600 + schedule[1] * 60 + schedule[2];
    *relay_num = schedule[3];
    *state = schedule[4];
    return 0;
}

static int fade_relay(int relay_num, int target_state) {
    int current_state = gpioRead(relay_pins[relay_num]);
    if (current_state < 0) {
        fprintf(stderr, "Error reading relay %d state: %s\n", relay_num, pigpio_error(current_state));
        return -1;
    }

    if (current_state == target_state) {
        return 0;
    }

    int direction = (target_state == 1) ? 1 : -1;
    int steps_per_second = FADE_DURATION_SEC / FADE_STEPS;
    int delay_us = steps_per_second * 1000000 / FADE_STEPS;

    for (int i = 0; i < FADE_STEPS; i++) {
        int duty_cycle = current_state + direction * (i + 1);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

        int result = gpioPWM(relay_pins[relay_num], duty_cycle);
        if (result < 0) {
            fprintf(stderr, "Error setting PWM on relay %d: %s\n", relay_num, pigpio_error(result));
            return -1;
        }

        gpioDelay(delay_us);
    }

    return 0;
}

static void turn_off_all_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(relay_pins[i], 0);
    }
}

int main(void) {
    int schedule[24 * 3];
    int num_entries = 0;

    if (read_schedule(SCHEDULE_FILE, schedule, &num_entries) != 0) {
        return EXIT_FAILURE;
    }

    if (num_entries == 0) {
        fprintf(stderr, "Error: schedule file is empty\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        int result = gpioSetMode(relay_pins[i], PI_OUTPUT);
        if (result < 0) {
            fprintf(stderr, "Error setting GPIO %d as output: %s\n", relay_pins[i], pigpio_error(result));
            gpioTerminate();
            return EXIT_FAILURE;
        }

        result = gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY);
        if (result < 0) {
            fprintf(stderr, "Error setting PWM frequency on GPIO %d: %s\n", relay_pins[i], pigpio_error(result));
            gpioTerminate();
            return EXIT_FAILURE;
        }

        result = gpioSetPWMrange(relay_pins[i], PWM_RANGE);
        if (result < 0) {
            fprintf(stderr, "Error setting PWM range on GPIO %d: %s\n", relay_pins[i], pigpio_error(result));
            gpioTerminate();
            return EXIT_FAILURE;
        }

        result = gpioPWM(relay_pins[i], 0);
        if (result < 0) {
            fprintf(stderr, "Error initializing PWM on GPIO %d: %s\n", relay_pins[i], pigpio_error(result));
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        turn_off_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        turn_off_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int current_time, next_time, relay_num, state;
    if (calculate_current_time(&current_time, NULL, NULL) != 0) {
        turn_off_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (find_next_schedule_entry(schedule, num_entries, current_time, &next_time, &relay_num, &state) != 0) {
        turn_off_all_relays();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting smart home lighting system...\n");

    while (program_running) {
        if (calculate_current_time(&current_time, NULL, NULL) != 0) {
            gpioDelay(1000000);
            continue;
        }

        if (current_time >= next_time) {
            if (fade_relay(relay_num, state) != 0) {
                fprintf(stderr, "Error fading relay %d\n", relay_num);
            }

            if (find_next_schedule_entry(schedule, num_entries, current_time, &next_time, &relay_num, &state) != 0) {
                fprintf(stderr, "Error finding next schedule entry\n");
                break;
            }
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down smart home lighting system...\n");
    turn_off_all_relays();
    gpioTerminate();
    printf("Smart home lighting system shut down.\n");

    return EXIT_SUCCESS;
}

