/*
 * Raspberry Pi Zero W — Rudimentary Theremin
 *
 * Reads distance from an HC-SR04 ultrasonic distance sensor and maps it
 * to a PWM buzzer frequency.
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM)
 *   HC-SR04 ECHO -> GPIO24 (BCM)
 *   Buzzer      -> GPIO18 (BCM, hardware PWM0)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 * Run:
 *   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define TRIGGER_PIN      23          /* BCM 23 — HC-SR04 TRIG */
#define ECHO_PIN         24          /* BCM 24 — HC-SR04 ECHO */
#define BUZZER_PIN       18          /* BCM 18 — Buzzer PWM0 */

#define SPEED_OF_SOUND   34300.0     /* cm/s at ~20 °C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define MIN_FREQUENCY    50.0        /* Hz — buzzer lower limit */
#define MAX_FREQUENCY    2000.0      /* Hz — buzzer upper limit */
#define LOOP_DELAY_US    20000       /* 50 Hz main loop */
#define MEASURE_GAP_US   60000       /* 60 ms between measurements */
#define TRIGGER_PULSE_US 10          /* HC-SR04 trigger pulse width */
#define ECHO_TIMEOUT_US  30000       /* 30 ms max echo wait */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Distance reading ----------------------------- */
/*
 * Returns distance in cm, or -1.0 on timeout / error.
 *
 * HC-SR04 timing (datasheet):
 *   - Trigger pulse: 10 µs high.
 *   - Echo pulse: high duration proportional to distance.
 *   - Timeout: ~30 ms (max range ~5 m).
 */
static float read_distance(void)
{
    uint32_t start_tick, end_tick;
    uint32_t timeout_start;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout (sensor absent?)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * SPEED_OF_SOUND / 2000000.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

/* --------------------------- Frequency mapping ----------------------------- */
static float map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    return MIN_FREQUENCY +
           (distance - MIN_DISTANCE_CM) *
           (MAX_FREQUENCY - MIN_FREQUENCY) /
           (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
}

/* ------------------------------- Buzzer ---------------------------------- */
static void set_buzzer_frequency(float frequency)
{
    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

    /*
     * pigpio hardware PWM on GPIO18 supports a range of 0–255 for duty cycle.
     * For a pure sine wave at a given frequency, a 50% duty cycle is a
     * reasonable starting point.
     */
    int duty = 128;  /* 50 % of 255 */
    int range = 255;

    if (gpioHardwarePWM(BUZZER_PIN, (int)frequency, duty) < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for %.1f Hz\n", frequency);
    }
}

static void silence_buzzer(void)
{
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    silence_buzzer();

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        silence_buzzer();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float distance = read_distance();

        if (distance >= 0.0f) {
            float frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
            printf("Distance: %.2f cm  ->  Frequency: %.1f Hz\n",
                   distance, frequency);
        } else {
            /* On error, silence the buzzer for safety */
            silence_buzzer();
        }

        /* Enforce minimum measurement gap */
        gpioDelay(MEASURE_GAP_US);

        /* Main loop delay */
        gpioDelay(LOOP_DELAY_US);
    }

    /* --------------------------- Graceful shutdown -------------------------- */
    printf("\nShutting down...\n");
    silence_buzzer();
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

