#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN, red) < 0) {
        fprintf(stderr, "Error: Failed to set PWM on RED_PIN\n");
        return -1;
    }
    if (gpioPWM(GREEN_PIN, green) < 0) {
        fprintf(stderr, "Error: Failed to set PWM on GREEN_PIN\n");
        return -1;
    }
    if (gpioPWM(BLUE_PIN, blue) < 0) {
        fprintf(stderr, "Error: Failed to set PWM on BLUE_PIN\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    /* Turn off LED before releasing PWM resources */
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pins as outputs */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set RED_PIN as output\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GREEN_PIN as output\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set BLUE_PIN as output\n");
        cleanup();
        return EXIT_FAILURE;
