/*
 * SW-420 vibration sensor monitor for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SW-420 VCC  -> 3.3 V (pin 1)
 *   SW-420 GND  -> GND  (pin 9)
 *   SW-420 OUT  -> GPIO17 (BCM, pin 11)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vib_monitor vib_monitor.c -lgpiod
 *
 * Run:
 *   ./vib_monitor [poll_timeout_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define GPIO_LINE_OFFSET    17          /* BCM 17, physical pin 11 */
#define WINDOW_SIZE         5
#define EARTHQUAKE_THRESHOLD 3
#define LOG_FILE_NAME       "vibration_events.log"
#define DEFAULT_TIMEOUT_MS  1000
#define TIMESTAMP_LEN       32

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    if (time(&rawtime) == (time_t)-1) {
        perror("time()");
        return -1;
    }
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        perror("localtime_r()");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed: buffer too small\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(FILE *log_fp, int value)
{
    char ts[TIMESTAMP_LEN];

    if (get_iso8601_timestamp(ts, sizeof(ts)) != 0) {
        return -1;
    }

    if (fprintf(log_fp, "%s, %d\n", ts, value) < 0) {
        perror("fprintf(log_fp)");
        return -1;
    }

    if (fflush(log_fp) == EOF) {
        perror("fflush(log_fp)");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int window[WINDOW_SIZE];
    int window_index = 0;
    int window_count = 0;
    int poll_timeout_ms = DEFAULT_TIMEOUT_MS;
    int ret = EXIT_FAILURE;

    /* Parse optional poll timeout argument */
    if (argc > 1) {
        char *endptr = NULL;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || val <= 0 || val > 10000) {
            fprintf(stderr, "Invalid poll timeout '%s'. Using default %d ms.\n",
                    argv[1], DEFAULT_TIMEOUT_MS);
        } else {
            poll_timeout_ms = (int)val;
        }
    }

    /* Initialize sliding window to all zeros */
    memset(window, 0, sizeof(window));

    /* Install signal handlers */
    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    /* Open log file in append mode */
    log_fp = fopen(LOG_FILE_NAME, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        goto cleanup;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(" GPIO_CHIP_NAME ")");
        goto cleanup;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line(" GPIO_CHIP_NAME ", "
               STRINGIFY(GPIO_LINE_OFFSET) ")");
        goto cleanup;
    }

    /* Request line for both rising and falling edge events */
    if (gpiod_line_request_both_edges_events(line, "sw420-vib") < 0) {
        perror("gpiod_line_request_both_edges_events(" GPIO_CHIP_NAME
               ", " STRINGIFY(GPIO_LINE_OFFSET) ")");
        goto cleanup;
    }

    printf("Monitoring SW-420 vibration sensor on GPIO%d (BCM)...\n",
           GPIO_LINE_OFFSET);
    printf("Poll timeout: %d ms | Log file: %s\n",
           poll_timeout_ms, LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* Main event loop */
    while (g_running) {
        struct timespec ts;
        int rv;

        /*
         * gpiod_line_event_wait() returns:
         *   > 0  : event detected
         *   0   : timeout
         *   -1   : error
         */
        ts.tv_sec  = poll_timeout_ms / 1000;
        ts.tv_nsec = (poll_timeout_ms % 1000) * 1000000L;

        rv = gpiod_line_event_wait(line, &ts);
        if (rv < 0) {
            if (errno == EINTR) {
                continue;  /* Signal received — check g_running */
            }
            perror("gpiod_line_event_wait()");
            goto cleanup;
        }
        if (rv == 0) {
            continue;  /* Timeout — no event */
        }

        /* Event detected — read it */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_read()");
            goto cleanup;
        }

        /* Log the raw value */
        if (log_event(log_fp, event.value) != 0) {
            fprintf(stderr, "Warning: failed to log event.\n");
        }

        /* Update sliding window */
        window[window_index] = event.value;
        window_index = (window_index + 1) % WINDOW_SIZE;
        if (window_count < WINDOW_SIZE) {
            window_count++;
        }

        /* Check for earthquake alert */
        int high_count = 0;
        for (int i = 0; i < window_count; i++) {
            if (window[i] == 1) {
                high_count++;
            }
        }
        if (high_count >= EARTHQUAKE_THRESHOLD) {
            char ts[TIMESTAMP_LEN];
            if (get_iso8601_timestamp(ts, sizeof(ts)) == 0) {
                printf("[%s] EARTHQUAKE ALERT: %d HIGH events in window\n",
                       ts, high_count);
            } else {
                printf("[timestamp error] EARTHQUAKE ALERT: %d HIGH events in window\n",
                       high_count);
            }
            fflush(stdout);
        }
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_fp != NULL) {
        if (fclose(log_fp) == EOF) {
            perror("fclose(log_fp)");
            ret = EXIT_FAILURE;
        }
    }
    return ret;
}

