/*
 * LSM303DLHC magnetometer reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303DLHC SDA  -> Pi GPIO2 (physical pin 3)
 *   LSM303DLHC SCL  -> Pi GPIO3 (physical pin 5)
 *   LSM303DLHC VDD  -> 3.3 V
 *   LSM303DLHC GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mag_compass mag_compass.c -lm
 *
 * Run:
 *   ./mag_compass
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM303DLHC constants (from datasheet) ---- */
#define LSM303_MAG_ADDR        0x1E   /* 7-bit I2C address */
#define LSM303_MAG_CRA_REG_M   0x00   /* Temp sensor config */
#define LSM303_MAG_CRB_REG_M   0x01   /* Gain setting */
#define LSM303_MAG_MR_REG_M    0x02   /* Mode register */
#define LSM303_MAG_OUT_X_H_M   0x03   /* X-axis MSB */
#define LSM303_MAG_OUT_X_L_M   0x04   /* X-axis LSB */
#define LSM303_MAG_OUT_Z_H_M   0x05   /* Z-axis MSB */
#define LSM303_MAG_OUT_Z_L_M   0x06   /* Z-axis LSB */
#define LSM303_MAG_OUT_Y_H_M   0x07   /* Y-axis MSB */
#define LSM303_MAG_OUT_Y_L_M   0x08   /* Y-axis LSB */

#define LSM303_MAG_TEMP_SENSITIVITY 0.08f  /* LSB per °C */
#define LSM303_MAG_GAIN_1_3_GA      0x20   /* Gain = 1.3 Ga */
#define LSM303_MAG_MODE_CONTINUOUS  0x00   /* Continuous-conversion mode */

/* ---- Calibration offsets (replace with your own) ---- */
#define X_OFFSET 10.0f
#define Y_OFFSET (-5.0f)
#define Z_OFFSET 20.0f

/* ---- Globals for cleanup ---- */
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;
static volatile sig_atomic_t g_stop = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

/* ---- Write one byte to an 8-bit register ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ---- Read N bytes starting at an 8-bit register ---- */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read data */
    ssize_t n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_burst: read %zu bytes from 0x%02X failed: %s (got %zd)\n",
                len, reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ---- Initialize magnetometer ---- */
static int init_magnetometer(int fd)
{
    /* Temp sensor: continuous conversion, 80 Hz */
    if (i2c_write_reg8(fd, LSM303_MAG_CRA_REG_M, 0x14) < 0)
        return -1;

    /* Gain = 1.3 Ga */
    if (i2c_write_reg8(fd, LSM303_MAG_CRB_REG_M, LSM303_MAG_GAIN_1_3_GA) < 0)
        return -1;

    /* Continuous-conversion mode */
    if (i2c_write_reg8(fd, LSM303_MAG_MR_REG_M, LSM303_MAG_MODE_CONTINUOUS) < 0)
        return -1;

    return 0;
}

/* ---- Read raw magnetometer data ---- */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, LSM303_MAG_OUT_X_H_M, raw, sizeof(raw)) < 0)
        return -1;

    *x = (int16_t)((raw[0] << 8) | raw[1]);
    *z = (int16_t)((raw[2] << 8) | raw[3]);
    *y = (int16_t)((raw[4] << 8) | raw[5]);

    return 0;
}

/* ---- Apply hard-iron calibration ---- */
static void calibrate_magnetometer(int16_t x, int16_t y, int16_t z,
                                  float *cx, float *cy, float *cz)
{
    *cx = (float)x - X_OFFSET;
    *cy = (float)y - Y_OFFSET;
    *cz = (float)z - Z_OFFSET;
}

/* ---- Compute heading in degrees ---- */
static float calculate_heading(float cx, float cy)
{
    float heading = atan2f(cy, cx) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ---- Map heading to compass direction ---- */
static const char *map_heading_to_direction(float heading)
{
    if (heading < 22.5f || heading >= 337.5f) return "N";
    if (heading < 67.5f)  return "NE";
    if (heading < 112.5f) return "E";
    if (heading < 157.5f) return "SE";
    if (heading < 202.5f) return "S";
    if (heading < 247.5f) return "SW";
    if (heading < 292.5f) return "W";
    return "NW";
}

/* ---- Log one sample to CSV ---- */
static int log_data(FILE *fp, float cx, float cy, float cz, float heading)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f, %.2f, %.2f, %.2f\n", ts, cx, cy, cz, heading) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup all resources ---- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire magnetometer slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize magnetometer */
    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize magnetometer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode); write header if file is empty */
    g_log_fp = fopen("mag_log.csv", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(mag_log.csv) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (fflush(g_log_fp) != 0) {
            fprintf(stderr, "fflush header failed: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!g_stop) {
        int16_t x, y, z;
        float cx, cy, cz, heading;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "I2C read error — skipping sample\n");
            sleep(1);
            continue;
        }

        calibrate_magnetometer(x, y, z, &cx, &cy, &cz);
        heading = calculate_heading(cx, cy);

        const char *dir = map_heading_to_direction(heading);

        printf("Heading: %.2f degrees (%s)\n", heading, dir);

        if (log_data(g_log_fp, cx, cy, cz, heading) < 0) {
            fprintf(stderr, "Logging failed — continuing\n");
        }

        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

