    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f, %.2f, %.2f, %.2f\n", ts, cx, cy, cz, heading) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup all resources ---- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire magnetometer slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize magnetometer */
    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize magnetometer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode); write header if file is empty */
    g_log_fp = fopen("mag_log.csv", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(mag_log.csv) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (fflush(g_log_fp) != 0) {
            fprintf(stderr, "fflush header failed: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!g_stop) {
        int16_t x, y, z;
        float cx, cy, cz, heading;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "I2C read error — skipping sample\n");
            sleep(1);
            continue;
        }

        calibrate_magnetometer(x, y, z, &cx, &cy, &cz);
        heading = calculate_heading(cx, cy);

        const char *dir = map_heading_to_direction(heading);

        printf("Heading: %.2f degrees (%s)\n", heading, dir);

        if (log_data(g_log_fp, cx, cy, cz, heading) < 0) {
            fprintf(stderr, "Logging failed — continuing\n");
        }

        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

