/*
 * TTP223 capacitive touch sensor → 5 V relay toggle on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TTP223 VCC  → 3.3 V (pin 1)
 *   TTP223 GND  → GND   (pin 9)
 *   TTP223 OUT  → GPIO4 (pin 7, BCM 4)
 *   Relay IN    → GPIO17 (pin 11, BCM 17)
 *   Relay VCC   → 5 V
 *   Relay GND   → GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_toggle relay_toggle.c -lpigpio -lrt
 * Run:    sudo ./relay_toggle
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN      4
#define RELAY_PIN      17
#define DEBOUNCE_MS    200
#define LOG_FILE       "relay_log.json"

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_relay_state = 0;   /* 0 = OFF, 1 = ON */

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_event(int relay_state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return;
    }

    struct tm tm_buf;
    struct tm *tm = localtime_r(&t, &tm_buf);
    if (!tm) {
        perror("localtime_r()");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp,
            "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n",
            ts, relay_state ? "ON" : "OFF");

    if (fclose(fp) != 0)
        perror("fclose(" LOG_FILE ")");
}

/* ------------------------------------------------------------------ */
/* Relay control                                                      */
/* ------------------------------------------------------------------ */

static int set_relay(int state)
{
    if (gpioWrite(RELAY_PIN, state) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, %d) failed\n", state);
        return -1;
    }
    g_relay_state = state;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Interrupt service routine (ISR)                                    */
/* ------------------------------------------------------------------ */

static void touch_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    static uint32_t last_tick = 0;
    uint32_t elapsed;

    /* pigpio tick wraps every ~71.6 min; handle wrap-around */
    if (tick >= last_tick)
        elapsed = tick - last_tick;
    else
        elapsed = (0xFFFFFFFFu - last_tick) + tick + 1u;

    if (elapsed < (uint32_t)(DEBOUNCE_MS * 1000))
        return;

    last_tick = tick;

    if (level == 1) {
        if (set_relay(g_relay_state ? 0 : 1) == 0)
            log_event(g_relay_state);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure touch pin as input with pull-down --- */
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(TOUCH_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure relay pin as output, ensure relay is OFF --- */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_relay(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register ISR on rising edge --- */
    if (gpioSetISRFuncEx(TOUCH_PIN, RISING_EDGE, 0, touch_isr, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx(TOUCH_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started.\n");
    printf("  Touch  : GPIO%d (BCM)\n", TOUCH_PIN);
    printf("  Relay  : GPIO%d (BCM)\n", RELAY_PIN);
    printf("  Log    : %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop: sleep until signal received --- */
    while (g_running)
        sleep(1);

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");

    /* Force relay OFF */
    if (set_relay(0) != 0)
        fprintf(stderr, "Warning: failed to force relay OFF during shutdown\n");

    /* Append final OFF entry to log */
    log_event(0);

    /* Release ISR */
    gpioSetISRFuncEx(TOUCH_PIN, RISING_EDGE, 0, NULL, NULL);

    /* Terminate pigpio */
    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

