code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define RELAY_GAP 1
#define POLL_INTERVAL 10

#define LOG_FILE "irrigation_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static const int relay_pins[4] = { RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN };

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_irrigation(int relay_number, int moisture_level)
{
    if (!g_log_fp) {
        fprintf(stderr, "Error: log file not open\n");
        return;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s - Relay %d irrigated (Moisture: %d)\n",
                timestamp, relay_number, moisture_level) < 0) {
        fprintf(stderr, "Error: fprintf() to log file failed\n");
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush() on log file failed\n");
    }
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }

        /* Start with relays deactivated (active-low: HIGH = inactive) */
        if (gpioWrite(relay_pins[i], 1) != 0) {
            fprintf(stderr, "Error: gpioWrite(%d, 1) failed\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Deactivate all relays before terminating */
    for (int i = 0; i < 4; i++) {
        gpioWrite(relay_pins[i], 1);
    }
    gpioTerminate();
}

static int simulate_moisture_level(void)
{
    return rand() % 101;
}

static int irrigate_relay(int relay_number, int moisture_level)
{
    int pin = relay_pins[relay_number - 1];

    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", pin);
        return -1;
    }

    log_irrigation(relay_number, moisture_level);

    /* Sleep in 1-second increments so signals are caught promptly */
    for (int i = 0; i < IRRIGATION_DURATION && g_running; i++) {
        sleep(1);
    }

    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 1) failed\n", pin);
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (g_running) {
        int moisture_level = simulate_moisture_level();

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level (%d) below threshold (%d). Starting irrigation.\n",
                   moisture_level, MOISTURE_THRESHOLD);

            for (int i = 0; i < 4 && g_running; i++) {
                if (irrigate_relay(i + 1, moisture_level) != 0) {
                    fprintf(stderr, "Error: irrigation failed on relay %d\n", i + 1);
                }

                if (i < 3 && g_running) {
                    sleep(RELAY_GAP);
                }
            }
        } else {
            printf("Moisture level (%d) above threshold (%d). No irrigation needed.\n",
                   moisture_level, MOISTURE_THRESHOLD);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    cleanup_gpio();

    return EXIT_SUCCESS;
}

