/*
 * Automated Plant Watering System — Raspberry Pi Zero W
 *
 * Two SG90 servos:
 *   Valve  -> GPIO17 (BCM 17, physical pin 11)
 *   Nozzle -> GPIO18 (BCM 18, physical pin 12)
 *
 * Library API calls (pigpio) are used for servo control.
 *
 * Build:  gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define VALVE_PIN          17          /* BCM 17 — valve servo  */
#define NOZZLE_PIN         18          /* BCM 18 — nozzle servo */

#define VALVE_OPEN_PULSE   1500        /* 90 degrees  */
#define VALVE_CLOSE_PULSE  500         /* 0 degrees   */

#define NOZZLE_MIN_PULSE   500         /* 0 degrees   */
#define NOZZLE_MAX_PULSE   2500        /* 180 degrees */

#define MOISTURE_THRESHOLD 50

#define SPRAY_DURATION_S   5
#define HOLD_DURATION_S    5
#define CYCLE_DELAY_S      5

#define MAX_RETRIES        3
#define RETRY_DELAY_US     100000      /* 100 ms */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Servo helpers ------------------------------- */

/*
 * Issue a servo command with retry logic.
 * Returns 0 on success, -1 on failure after MAX_RETRIES.
 */
static int servo_set_pulse(int pin, int pulse_width)
{
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (gpioServo(pin, pulse_width) == 0)
            return 0;

        fprintf(stderr,
                "[WARN] gpioServo(pin=%d, pulse=%d) failed (attempt %d/%d)\n",
                pin, pulse_width, attempt, MAX_RETRIES);

        if (attempt < MAX_RETRIES)
            gpioDelay(RETRY_DELAY_US);
    }

    fprintf(stderr,
            "[ERROR] gpioServo(pin=%d, pulse=%d) failed after %d attempts\n",
            pin, pulse_width, MAX_RETRIES);
    return -1;
}

/*
 * Stop a servo by sending a zero pulse width.
 * Returns 0 on success, -1 on failure.
 */
static int servo_stop(int pin)
{
    return servo_set_pulse(pin, 0);
}

/* --------------------------- Watering logic ------------------------------ */

/*
 * Open the valve to 90 degrees.
 * Returns 0 on success, -1 on failure.
 */
static int open_valve(void)
{
    return servo_set_pulse(VALVE_PIN, VALVE_OPEN_PULSE);
}

/*
 * Close the valve to 0 degrees.
 * Returns 0 on success, -1 on failure.
 */
static int close_valve(void)
{
    return servo_set_pulse(VALVE_PIN, VALVE_CLOSE_PULSE);
}

/*
 * Sweep the nozzle through five angles and spray for SPRAY_DURATION_S.
 * Returns 0 on success, -1 on failure.
 */
static int spray_nozzle(void)
{
    int angles[] = {0, 45, 90, 135, 180};
    int num_angles = (int)(sizeof(angles) / sizeof(angles[0]));

    for (int i = 0; i < num_angles; ++i) {
        int pulse = NOZZLE_MIN_PULSE +
                   (angles[i] * (NOZZLE_MAX_PULSE - NOZZLE_MIN_PULSE)) / 180;

        if (servo_set_pulse(NOZZLE_PIN, pulse) != 0) {
            fprintf(stderr,
                    "[ERROR] Failed to set nozzle angle to %d degrees (pulse %d)\n",
                    angles[i], pulse);
            return -1;
        }

        printf("Nozzle angle: %d degrees (pulse %d us)\n", angles[i], pulse);

        /* Spray for SPRAY_DURATION_S, checking for shutdown signal */
        for (int s = 0; s < SPRAY_DURATION_S && g_running; ++s)
            sleep(1);

        if (!g_running)
            return -1;
    }

    return 0;
}

/*
 * Run a single watering cycle.
 * Returns 0 on success, -1 on failure.
 */
static int run_watering_cycle(void)
{
    int moisture = 20;   /* Simulated soil moisture (0–100) */

    printf("--- Watering cycle started ---\n");
    printf("Simulated soil moisture: %d\n", moisture);

    if (moisture < MOISTURE_THRESHOLD) {
        printf("Moisture below threshold (%d). Opening valve...\n",
               MOISTURE_THRESHOLD);

        if (open_valve() != 0) {
            fprintf(stderr,
                    "[ERROR] Failed to open valve. Aborting watering cycle.\n");
            return -1;
        }

        /* Hold valve open for HOLD_DURATION_S, checking for shutdown */
        for (int s = 0; s < HOLD_DURATION_S && g_running; ++s)
            sleep(1);

        if (!g_running) {
            close_valve();
            return -1;
        }

        printf("Spraying nozzle...\n");
        if (spray_nozzle() != 0) {
            fprintf(stderr,
                    "[ERROR] Nozzle spray failed. Continuing with watering cycle.\n");
        }

        printf("Closing valve...\n");
        if (close_valve() != 0) {
            fprintf(stderr,
                    "[WARN] Failed to close valve. Continuing with watering cycle.\n");
        }
    } else {
        printf("Moisture above threshold (%d). Skipping watering cycle.\n",
               MOISTURE_THRESHOLD);
    }

    printf("--- Watering cycle complete ---\n");
    return 0;
}

/* ------------------------------- Main ------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr,
                "[FATAL] pigpio initialization failed. "
                "Run as root (sudo) and ensure pigpiod is not running.\n");
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    /* --- Main loop --- */
    while (g_running) {
        if (run_watering_cycle() != 0) {
            fprintf(stderr,
                    "[ERROR] Watering cycle failed. Exiting.\n");
            break;
        }

        /* Wait CYCLE_DELAY_S, checking for shutdown */
        for (int s = 0; s < CYCLE_DELAY_S && g_running; ++s)
            sleep(1);
    }

    /* --- Cleanup --- */
    /* Stop both servos first (best-effort) */
    (void)servo_stop(VALVE_PIN);
    (void)servo_stop(NOZZLE_PIN);

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

