/*
 * HC-SR04 Ultrasonic Distance Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5 V  (Pin 2 or 4)
 *   HC-SR04 GND  -> GND (Pin 6)
 *   HC-SR04 TRIG -> GPIO17 (BCM 17, Pin 11)
 *   HC-SR04 ECHO -> GPIO18 (BCM 18, Pin 12) via 5 V -> 3.3 V divider
 *
 * Build: gcc -O2 -Wall -Wextra -o hcsr04_logger hcsr04_logger.c -lpigpio -lrt
 * Run:   sudo ./hcsr04_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define LOG_FILE         "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000   /* 50 ms */
#define SAMPLE_PERIOD_US 1000000 /* 1 s  */
#define MIN_CYCLE_US     60000   /* 60 ms between measurements */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin LOW.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Returns:
 *   > 0  : distance in cm
 *   -1.0 : timeout
 *   -2.0 : read error
 */
static float read_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* --- Wait for echo rising edge --- */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* --- Wait for echo falling edge --- */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    if (start_tick == 0 || end_tick == 0) {
        return -2.0f;
    }

    uint32_t diff = end_tick - start_tick;
    /* distance = (time_us * speed_of_sound_cm_per_us) / 2 */
    return (float)diff * 0.01715f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_distance(float distance)
{
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%.2f\n", distance) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Logging to '%s'.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        trigger_sensor();

        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: sensor read failed (code %.0f).\n", distance);
            if (log_distance(-1.0f) != 0) {
                fprintf(stderr, "Error: failed to log error.\n");
            }
        } else {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Error: failed to log distance.\n");
            }
        }

        /*
         * Sleep for the remainder of the 1 s sample period, but wake
         * early if a signal arrives.
         */
        uint32_t elapsed = gpioTick();
        while (g_running && (int32_t)(gpioTick() - elapsed) < SAMPLE_PERIOD_US) {
            gpioDelay(10000); /* 10 ms */
        }

        /* Enforce a minimum 60 ms cycle gap */
        gpioDelay(MIN_CYCLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

