/*
 * VL53L1X distance sensor reader with relay control on Raspberry Pi 4.
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   VL53L1X SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *   Relay IN    -> GPIO18 (BCM, pin 12)
 *   Relay VCC   -> 5 V
 *   Relay GND   -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_relay vl53l1x_relay.c -lpigpio -lrt
 * Run:
 *   sudo ./vl53l1x_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS          1
#define VL53L1X_ADDR     0x29          /* Default I2C address (ADDR pin tied to GND) */
#define RELAY_GPIO       18            /* BCM pin 18 */
#define DISTANCE_THRESHOLD_CM 50.0f
#define POLL_DELAY_US    100000        /* 100 ms */

/* ---- VL53L1X register addresses (16-bit, big-endian on the bus) ---- */
#define VL53L1X_REG_SOFT_RESET               0x0003
#define VL53L1X_REG_SYSTEM_MODE_START        0x0000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS  0x0044
#define VL53L1X_REG_RESULT_RANGE_STATUS      0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/* Write a 16-bit register address (big-endian) followed by a byte. */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)((reg >> 8) & 0xFF);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Write a 16-bit register address (big-endian) followed by a 16-bit value (big-endian). */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (char)((reg >> 8) & 0xFF);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)((value >> 8) & 0xFF);
    buf[3] = (char)(value & 0xFF);
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register address (big-endian) followed by N bytes. */
static int vl53l1x_read_reg(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (char)((reg >> 8) & 0xFF);
    addr[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                      */
/* ------------------------------------------------------------------ */

/*
 * Initialise the VL53L1X sensor.
 * Returns 0 on success, -1 on failure.
 */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Soft reset write failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Start continuous ranging */
    if (vl53l1x_write_reg8(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x40) < 0) {
        fprintf(stderr, "[ERROR] Failed to start continuous ranging\n");
        return -1;
    }

    return 0;
}

/*
 * Read the distance in mm.
 * Returns 0 on success and stores the distance in *distance_mm,
 * -1 on I2C error, -2 on range-check failure (sensor not ready / out of range).
 */
static int vl53l1x_read_distance_mm(int handle, uint16_t *distance_mm)
{
    uint8_t status;
    uint8_t range_buf[2];

    /* Poll interrupt status register until data is ready */
    for (int i = 0; i < 100; i++) {
        if (vl53l1x_read_reg(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000); /* 1 ms */
        if (i == 99) {
            fprintf(stderr, "[ERROR] VL53L1X data-ready timeout\n");
            return -2;
        }
    }

    /* Read 16-bit range result (big-endian) */
    if (vl53l1x_read_reg(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, range_buf, 2) < 0)
        return -1;

    *distance_mm = ((uint16_t)range_buf[0] << 8) | range_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    /* Ensure relay is off */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO%d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0); /* Start with relay off */

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance reader started. Threshold: %.1f cm. Press Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD_CM);

    /* Main polling loop */
    while (g_running) {
        uint16_t distance_mm;
        int rc = vl53l1x_read_distance_mm(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            float distance_cm = distance_mm / 10.0f;
            printf("Distance: %.2f cm\n", distance_cm);

            if (distance_cm <= DISTANCE_THRESHOLD_CM) {
                gpioWrite(RELAY_GPIO, 1);
            } else {
                gpioWrite(RELAY_GPIO, 0);
            }
        } else if (rc == -1) {
            fprintf(stderr, "[ERROR] I2C read failure\n");
        } else {
            /* rc == -2: range-check failure (sensor not ready) — keep relay as-is */
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

