/*
 * MPU-6050 Gyroscope Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MPU-6050 VCC  -> 3.3 V (Pin 1)
 *   MPU-6050 GND  -> GND  (Pin 9)
 *   MPU-6050 SCL  -> GPIO3 / SCL1 (Pin 5)
 *   MPU-6050 SDA  -> GPIO2 / SDA1 (Pin 3)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mpu6050_gyro mpu6050_gyro.c
 *
 * Run:
 *   ./mpu6050_gyro
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define MPU6050_ADDR        0x68
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_WHO_AM_I   0x75
#define MPU6050_WHO_AM_I_VAL  0x68

#define I2C_BUS             "/dev/i2c-1"
#define SAMPLE_PERIOD_US    100000  /* 100 ms -> ~10 Hz */

/* ---- Globals for signal-handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    /* Set register pointer */
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }

    /* Read data bytes */
    n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (got %zd of %zu bytes)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int mpu6050_init(int fd)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (i2c_read_burst(fd, MPU6050_REG_WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register — sensor absent or bus error.\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_byte(fd, MPU6050_REG_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake MPU-6050.\n");
        return -1;
    }

    /* Allow oscillator to stabilize */
    usleep(100000);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];

    if (i2c_read_burst(fd, MPU6050_REG_GYRO_XOUT_H, raw, sizeof(raw)) != 0)
        return -1;

    *x = (int16_t)((raw[0] << 8) | raw[1]);
    *y = (int16_t)((raw[2] << 8) | raw[3]);
    *z = (int16_t)((raw[4] << 8) | raw[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire I2C slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (mpu6050_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Reading gyroscope data (Ctrl+C to stop)...\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (read_gyro_data(g_i2c_fd, &x, &y, &z) == 0) {
            printf("X: %6d  Y: %6d  Z: %6d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

