/*
 * Automated plant watering system for Raspberry Pi 4 Model B.
 *
 * Four 5 V relay modules are driven on BCM GPIO17, GPIO18, GPIO27, GPIO22
 * (physical pins 11, 12, 13, 15).  Each relay is active-low: a LOW output
 * energises the relay and water flows; a HIGH output de-energises it.
 *
 * The program opens the gpiochip0 device, requests each of the four lines
 * as outputs, sets them HIGH (inactive) at startup, then enters a main
 * loop that activates each relay in turn for 5 s, repeating the whole
 * sequence once every 24 h (86 400 s).  Each full cycle is logged to
 * watering_log.txt with timestamps.  SIGINT / SIGTERM are handled
 * cleanly: all lines are released, the chip is closed, and the program
 * exits.
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS          4
#define RELAY_ON_TIME_SEC   5
#define CYCLE_INTERVAL_SEC  86400   /* 24 hours */
#define LOG_FILE            "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_cycle_start(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static int set_all_relays(struct gpiod_line *lines[], int value)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_set_value(lines[i], value) < 0) {
            fprintf(stderr, "gpiod_line_set_value(%u, %d) failed: %s\n",
                    relay_pins[i], value, strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int activate_relay(struct gpiod_line *line, int pin, int duration_sec)
{
    /* Active-low: LOW energises the relay, water flows. */
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value(%d, 0) failed: %s\n",
                pin, strerror(errno));
        return -1;
    }

    sleep(duration_sec);

    /* De-energise the relay. */
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value(%d, 1) failed: %s\n",
                pin, strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    /* ---- Open the gpiochip0 device ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* ---- Acquire each relay line ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- Request each line as output, default HIGH (inactive) ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "plant-watering", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u) failed: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* ---- Install signal handlers ---- */
    if (install_signal_handlers() < 0)
        goto cleanup;

    printf("Plant watering system started.  Press Ctrl+C to exit.\n");

    /* ---- Main loop: one full 24-hour cycle ---- */
    while (g_running) {
        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            printf("Activating relay on GPIO%u for %d s...\n",
                   relay_pins[i], RELAY_ON_TIME_SEC);

            if (activate_relay(lines[i], relay_pins[i], RELAY_ON_TIME_SEC) < 0)
                goto cleanup;
        }

        if (g_running) {
            if (log_cycle_start() < 0)
                fprintf(stderr, "Warning: failed to log cycle start.\n");

            /* Sleep in 1-second increments so signals are caught promptly. */
            for (int s = 0; s < CYCLE_INTERVAL_SEC && g_running; s++)
                sleep(1);
        }
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release all lines ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);   /* ensure relay is off */
            gpiod_line_release(lines[i]);
        }
    }

    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

