#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY_1_PIN 17
#define RELAY_2_PIN 18
#define RELAY_3_PIN 27
#define RELAY_4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

#define SUNRISE_DURATION_SECONDS 1800
#define STEP_DELAY_SECONDS 1

#define LOG_FILE "smart_lighting.log"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
                tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }

    fclose(fp);
}

static int set_relay_intensity(int pin, int intensity) {
    if (intensity < 0 || intensity > PWM_RANGE) {
        fprintf(stderr, "Invalid intensity %d for pin %d\n", intensity, pin);
        return -1;
    }

    if (gpioPWM(pin, intensity) != 0) {
        fprintf(stderr, "Failed to set PWM on pin %d to %d\n", pin, intensity);
        return -1;
    }

    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        int pin = pins[i];
        if (gpioSetMode(pin, PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pin);
            gpioTerminate();
            return -1;
        }

        if (gpioSetPWMfrequency(pin, PWM_FREQUENCY) != PWM_FREQUENCY) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pin);
            gpioTerminate();
            return -1;
        }

        if (gpioSetPWMrange(pin, PWM_RANGE) != PWM_RANGE) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pin);
            gpioTerminate();
            return -1;
        }

        if (set_relay_intensity(pin, 0) != 0) {
            fprintf(stderr, "Failed to initialize relay intensity on GPIO %d\n", pin);
            gpioTerminate();
            return -1;
        }
    }

    return 0;
}

static void cleanup_gpio(void) {
    int pins[] = {RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        set_relay_intensity(pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_event("Smart lighting system started");

    int total_steps = SUNRISE_DURATION_SECONDS / STEP_DELAY_SECONDS;
    for (int step = 0; step <= total_steps && program_running; step++) {
        int intensity = (int)(((float)step / total_steps) * PWM_RANGE);

        int pins[] = {RELAY_1_PIN, RELAY_2_PIN, RELAY_3_PIN, RELAY_4_PIN};
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
            if (set_relay_intensity(pins[i], intensity) != 0) {
                log_event("Error setting relay intensity");
            }
        }

        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Step %d/%d, Intensity: %d",
                 step, total_steps, intensity);
        log_event(log_message);

        if (step < total_steps) {
            gpioDelay(STEP_DELAY_SECONDS * 1000000);
        }
    }

    if (!program_running) {
        log_event("Smart lighting system interrupted by signal");
    }

    cleanup_gpio();
    log_event("Smart lighting system stopped");

    return EXIT_SUCCESS;
}

