#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_CONFIG       0x1A
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_ACCEL_CONFIG 0x1C
#define MPU6050_REG_GYRO_XOUT_H  0x43
#define MPU6050_REG_PWR_MGMT_1   0x6B

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 17

/* Angular velocity threshold (degrees per second) */
#define ANGULAR_VELOCITY_THRESHOLD 250.0f

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Sampling period in microseconds (50 ms = 20 Hz) */
#define SAMPLE_PERIOD_US 50000

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Maximum consecutive read failures before re-initialization */
#define MAX_READ_FAILURES 3

/* Structure to hold timestamped gyroscope data */
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* I2C handle */
static int i2c_handle = -1;

/* Flag to indicate program termination */
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize the MPU-6050 */
static int init_mpu6050(void) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Failed to set sample rate divider\n");
        return -1;
    }

    /* Set DLPF configuration to 0 (bandwidth 256 Hz, delay 0.98 ms) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set DLPF configuration\n");
        return -1;
    }

    /* Set gyroscope full scale range to +/- 250 deg/s */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set gyroscope range\n");
        return -1;
    }

    /* Disable accelerometer (ACCEL_CONFIG = 0) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to disable accelerometer\n");
        return -1;
    }

    return 0;
}

/* Read raw gyroscope data from the MPU-6050 */
static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];

    /* Read 6 bytes starting from GYRO_XOUT_H (0x43) */
    if (i2cReadI2CBlockData(i2c_handle, MPU6050_REG_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data\n");
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* Convert raw gyroscope data to degrees per second */
static void convert_to_dps(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                           float *x, float *y, float *z) {
    /* Sensitivity for +/- 250 deg/s range: 131 LSB/deg/s */
    const float sensitivity = 131.0f;

    *x = (float)raw_x / sensitivity;
    *y = (float)raw_y / sensitivity;
    *z = (float)raw_z / sensitivity;
}

/* Add data to the circular buffer */
static void add_to_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* Check if any axis exceeds the threshold */
static bool check_threshold(float x, float y, float z) {
    return (fabsf(x) > ANGULAR_VELOCITY_THRESHOLD ||
            fabsf(y) > ANGULAR_VELOCITY_THRESHOLD ||
            fabsf(z) > ANGULAR_VELOCITY_THRESHOLD);
}

int main(void) {
    int16_t raw_x, raw_y, raw_z;
    float x, y, z;
    int consecutive_failures = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); /* Ensure LED is off initially */

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X\n", MPU6050_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 data acquisition started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        /* Read gyroscope data */
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            consecutive_failures = 0;

            /* Convert to degrees per second */
            convert_to_dps(raw_x, raw_y, raw_z, &x, &y, &z);

            /* Add data to the circular buffer */
            add_to_buffer(x, y, z);

            /* Check if threshold is exceeded */
            if (check_threshold(x, y, z)) {
                gpioWrite(LED_PIN, 1); /* Turn LED on */
            } else {
                gpioWrite(LED_PIN, 0); /* Turn LED off */
            }

            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x, y, z);
        } else {
            consecutive_failures++;
            fprintf(stderr, "Warning: Read failure %d/%d\n",
                    consecutive_failures, MAX_READ_FAILURES);

            if (consecutive_failures >= MAX_READ_FAILURES) {
                fprintf(stderr, "Error: Max consecutive read failures reached. Re-initializing I2C.\n");
                i2cClose(i2c_handle);
                i2c_handle = -1;
                gpioDelay(100000); /* 100 ms delay before re-opening */

                i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error: Failed to re-open I2C device\n");
                    terminate = 1;
                } else if (init_mpu6050() != 0) {
                    fprintf(stderr, "Error: MPU-6050 re-initialisation failed\n");
                    i2cClose(i2c_handle);
                    i2c_handle = -1;
                    terminate = 1;
                } else {
                    consecutive_failures = 0;
                }
            }
        }

        gpioDelay(SAMPLE_PERIOD_US); /* Delay for 50 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0); /* Turn off LED */

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    gpioTerminate();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

