#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8
#define LOG_FILE        "gyro_log.txt"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define SAMPLE_PERIOD_US 10000
#define MAX_RETRIES     3

#define MPU9250_REG_PWR_MGMT_1   0x6B
#define MPU9250_REG_GYRO_XOUT_H  0x43
#define MPU9250_REG_GYRO_XOUT_L  0x44
#define MPU9250_REG_GYRO_YOUT_H  0x45
#define MPU9250_REG_GYRO_YOUT_L  0x46
#define MPU9250_REG_GYRO_ZOUT_H  0x47
#define MPU9250_REG_GYRO_ZOUT_L  0x48

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to de-assert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, 2) == 0) {
            *value = rx[1];
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int write_register(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, 2) == 0) {
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx[7] = { (uint8_t)(MPU9250_REG_GYRO_XOUT_H | 0x80 | 0x40), 0, 0, 0, 0, 0, 0 };
    uint8_t rx[7] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, 7) == 0) {
            *x = (int16_t)((rx[2] << 8) | rx[1]);
            *y = (int16_t)((rx[4] << 8) | rx[3]);
            *z = (int16_t)((rx[6] << 8) | rx[5]);
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int log_data(int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    gpio_chip = gpiod_chip_open(GPIO_CHIP);
    if (gpio_chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_LINE_OFFSET);
    if (cs_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250_cs", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", CS_LINE_OFFSET, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    if (write_register(MPU9250_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU9250\n");
        cleanup();
        return 1;
    }

    printf("MPU9250 gyroscope logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data after %d retries\n", MAX_RETRIES);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

