#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI bus 0, CE0 (GPIO8) */
#define SPI_SPEED        3900000    /* 3.9 MHz — well within MPU-6050 spec */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define LED_GPIO         17         /* BCM 17, physical pin 11 */
#define LED_BLINK_US     500000     /* 500 ms on / 500 ms off */

#define GYRO_THRESHOLD   200.0f     /* deg/s */
#define BUFFER_SIZE      64

/* MPU-6050 registers */
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_CONFIG       0x1A
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_ACCEL_CONFIG 0x1C
#define MPU6050_REG_GYRO_XOUT_H  0x43
#define MPU6050_REG_PWR_MGMT_1   0x6B

/* ------------------------------- Globals --------------------------------- */
static int      spi_handle = -1;
static volatile sig_atomic_t running = 1;

/* --------------------------- Circular buffer ----------------------------- */
typedef struct {
    struct timespec timestamp;
    float           x, y, z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int         buffer_head = 0;
static int         buffer_count = 0;

/* --------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* --------------------------- SPI helpers -------------------------------- */
static int spi_write_reg(uint8_t reg, uint8_t value)
{
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int spi_read_burst(uint8_t reg, uint8_t *buf, int len)
{
    char tx[1 + BUFFER_SIZE] = { 0 };
    char rx[1 + BUFFER_SIZE] = { 0 };

    tx[0] = (char)(reg | 0x80);

    if (spiXfer(spi_handle, tx, rx, len + 1) != len + 1) {
        fprintf(stderr, "SPI burst read from reg 0x%02X failed\n", reg);
        return -1;
    }
    memcpy(buf, rx + 1, len);
    return 0;
}

/* --------------------------- MPU-6050 init ------------------------------- */
static int init_mpu6050(void)
{
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (spi_write_reg(MPU6050_REG_PWR_MGMT_1, 0x00) != 0)
        return -1;
    gpioDelay(100000); /* 100 ms settle */

    /* Sample rate divider = 7 → 1 kHz / (1 + 7) = 125 Hz */
    if (spi_write_reg(MPU6050_REG_SMPLRT_DIV, 0x07) != 0)
        return -1;

