    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int spi_read_burst(uint8_t reg, uint8_t *buf, int len)
{
    char tx[1 + BUFFER_SIZE] = { 0 };
    char rx[1 + BUFFER_SIZE] = { 0 };

    tx[0] = (char)(reg | 0x80);

    if (spiXfer(spi_handle, tx, rx, len + 1) != len + 1) {
