#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_CONFIG       0x1A
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_ACCEL_CONFIG 0x1C
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_PWR_MGMT_1   0x6B

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 21

/* Tilt threshold (degrees) */
#define TILT_THRESHOLD 45.0f

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int init_mpu6050(void);
static int read_raw_data(int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz);
static void calculate_tilt(int16_t ax, int16_t ay, int16_t az, int16_t gx, int16_t gy, int16_t gz, float *roll, float *pitch);
static void log_data(float roll, float pitch);
static void control_led(float roll, float pitch);
static void signal_handler(int signal);
static void cleanup(void);

/* Initialize MPU-6050 */
static int init_mpu6050(void) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for oscillator to stabilize */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    /* Set DLPF configuration to 4 (bandwidth 44 Hz, delay 4.9 ms) */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_CONFIG, 0x04) < 0) {
        fprintf(stderr, "Error: Could not set DLPF configuration\n");
        return -1;
    }

    /* Set gyroscope full scale range to +/- 250 degrees/sec */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope range\n");
        return -1;
    }

    /* Set accelerometer full scale range to +/- 2g */
    if (i2cWriteByteData(i2c_handle, MPU6050_REG_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer range\n");
        return -1;
    }

    return 0;
}

/* Read raw accelerometer and gyroscope data */
static int read_raw_data(int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    char buffer[14];

    /* Read 14 bytes starting from ACCEL_XOUT_H (0x3B) */
    if (i2cReadI2CBlockData(i2c_handle, MPU6050_REG_ACCEL_XOUT_H, buffer, 14) != 14) {
        fprintf(stderr, "Error: Could not read raw data from MPU-6050\n");
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    *ax = (int16_t)((buffer[0] << 8) | buffer[1]);
    *ay = (int16_t)((buffer[2] << 8) | buffer[3]);
    *az = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gx = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gy = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gz = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

/* Calculate roll and pitch angles from raw data */
static void calculate_tilt(int16_t ax, int16_t ay, int16_t az, int16_t gx, int16_t gy, int16_t gz, float *roll, float *pitch) {
    /* Convert raw accelerometer data to g's */
    float ax_g = (float)ax / 16384.0f;
    float ay_g = (float)ay / 16384.0f;
    float az_g = (float)az / 16384.0f;

    /* Calculate roll and pitch angles (approximate, assuming no yaw) */
    *roll  = atan2f(ay_g, az_g) * 180.0f / M_PI;
    *pitch = atan2f(-ax_g, sqrtf(ay_g * ay_g + az_g * az_g)) * 180.0f / M_PI;
}

/* Log data to file */
static void log_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open tilt_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(fp);
}

/* Control LED based on tilt threshold */
static void control_led(float roll, float pitch) {
    if (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) {
        gpioWrite(LED_PIN, 1); /* Turn LED on */
    } else {
        gpioWrite(LED_PIN, 0); /* Turn LED off */
    }
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    gpioWrite(LED_PIN, 0); /* Turn off LED */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X\n", MPU6050_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); /* Ensure LED is off initially */

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int16_t ax, ay, az, gx, gy, gz;
    float roll, pitch;

    /* Main loop */
    while (program_running) {
        /* Read raw data */
        if (read_raw_data(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            /* Calculate roll and pitch */
            calculate_tilt(ax, ay, az, gx, gy, gz, &roll, &pitch);

            /* Print roll and pitch to console */
            printf("Roll: %.2f degrees, Pitch: %.2f degrees\n", roll, pitch);

            /* Log data */
            log_data(roll, pitch);

            /* Control LED */
            control_led(roll, pitch);
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data, skipping cycle\n");
        }

        /* Delay for 100 milliseconds */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup and exit */
    cleanup();
    return EXIT_SUCCESS;
}

