#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x60
#define LED_GPIO       17
#define PROX_THRESHOLD 100
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10
#define LOOP_DELAY_MS  100

/* Si1145 register addresses (8-bit) */
#define REG_PART_ID    0x00
#define REG_HW_KEY     0x07
#define REG_MEAS_RATE0 0x08
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0  0x26

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_si1145(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    if (i2c_write_reg8(fd, REG_HW_KEY, 0x17) < 0) return -1;
    if (i2c_write_reg8(fd, REG_MEAS_RATE0, 0x00) < 0) return -1;
    return 0;
}

static int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t als_vis_lo, als_vis_hi, ps1_lo, ps1_hi;

    if (i2c_read_reg8(fd, REG_ALS_VIS_DATA0, &als_vis_lo) < 0) return -1;
    if (i2c_read_reg8(fd, REG_ALS_VIS_DATA0 + 1, &als_vis_hi) < 0) return -1;
    if (i2c_read_reg8(fd, REG_PS1_DATA0, &ps1_lo) < 0) return -1;
    if (i2c_read_reg8(fd, REG_PS1_DATA0 + 1, &ps1_hi) < 0) return -1;

    *ambient_light = (uint16_t)((als_vis_hi << 8) | als_vis_lo);
    *proximity    = (uint16_t)((ps1_hi << 8) | ps1_lo);
    return 0;
}

static int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_si1145(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed.\n");
        cleanup();
        return 1;
    }

    g_log_fp = fopen("biometric_log.txt", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open biometric_log.txt: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    printf("Si1145 initialized. Logging to biometric_log.txt every %d ms.\n", LOOP_DELAY_MS);

    while (g_running) {
        uint16_t ambient_light = 0, proximity = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sensor_data(g_i2c_fd, &ambient_light, &proximity) == 0) {
                success = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (success) {
            if (log_data(g_log_fp, ambient_light, proximity) < 0) {
                fprintf(stderr, "Logging failed.\n");
            }

            if (proximity > PROX_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after %d attempts.\n", MAX_RETRIES);
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    cleanup();
    return 0;
}

