#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXRS290 Register Addresses (from datasheet) */
#define REG_TEMP_OUT   0x04
#define REG_XGYRO_OUT  0x06
#define REG_YGYRO_OUT  0x08
#define REG_ZGYRO_OUT  0x0A
#define REG_SMPLRT_DIV 0x15
#define REG_PWR_MGM    0x3E

/* SPI Configuration */
#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0        /* Mode 0, active-low CE */

/* Sampling Parameters */
#define SAMPLE_DELAY_US 10000   /* 10 ms */
#define MAX_RETRIES     3

/* Global state for cleanup */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a single register from the ADXRS290 via SPI */
static int read_register(uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    /* ADXRS290 read: send register address OR'd with 0x80, then dummy byte */
    tx_buf[0] = (char)(reg | 0x80);
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    *value = (uint8_t)rx_buf[1];
    return 0;
}

/* Write a single register to the ADXRS290 via SPI */
static int write_register(uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    /* ADXRS290 write: send register address AND'd with 0x7F, then data byte */
    tx_buf[0] = (char)(reg & 0x7F);
    tx_buf[1] = (char)value;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

/* Initialize the ADXRS290 gyroscope */
static int initialize_gyroscope(void) {
    /* Wake up the device: clear SLEEP bit in PWR_MGM (0x3E) */
    if (write_register(REG_PWR_MGM, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up ADXRS290\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */

    /* Set sample rate divider to 0 (1 kHz / (1 + 0) = 1 kHz) */
    if (write_register(REG_SMPLRT_DIV, 0x00) != 0) {
        fprintf(stderr, "Failed to set sample rate divider\n");
        return -1;
    }

    return 0;
}

/* Read raw gyroscope data from both axes */
static int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    uint8_t x_low, x_high, y_low, y_high;

    if (read_register(REG_XGYRO_OUT, &x_low) != 0) return -1;
    if (read_register(REG_XGYRO_OUT + 1, &x_high) != 0) return -1;
    if (read_register(REG_YGYRO_OUT, &y_low) != 0) return -1;
    if (read_register(REG_YGYRO_OUT + 1, &y_high) != 0) return -1;

    /* Combine high and low bytes (little-endian) */
    *x_rate = (int16_t)((x_high << 8) | x_low);
    *y_rate = (int16_t)((y_high << 8) | y_low);

    return 0;
}

/* Log data to CSV file */
static int log_data(FILE *fp, int16_t x_rate, int16_t y_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    if (fprintf(fp, "%ld.%06ld,%d,%d\n",
                (long)ts.tv_sec, ts.tv_nsec / 1000,
                x_rate, y_rate) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

