static int reinitialize_spi(void) {
    int retries = 0;

    while (retries < MAX_RETRIES) {
        fprintf(stderr, "Re-initializing SPI (attempt %d/%d)...\n", retries + 1, MAX_RETRIES);

        if (spi_handle >= 0) {
            spiClose(spi_handle);
