        if (spi_handle >= 0) {
            fprintf(stderr, "SPI re-initialized successfully.\n");
            return 0;
        }

        fprintf(stderr, "SPI re-initialization failed.\n");
        retries++;
        gpioDelay(100000); /* 100 ms backoff */
    }

