#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17
#define ALERT_DURATION_US 2000000  /* 2 seconds in microseconds */
#define ALERT_SETTLE_US  100000    /* 100 ms settle after alert */
#define DEBOUNCE_US      50000     /* 50 ms debounce */
#define POLL_DELAY_US    10000     /* 10 ms poll delay */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Log a seismic event with an ISO-8601 timestamp                     */
/* ------------------------------------------------------------------ */
static void log_seismic_event(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s - Seismic event detected!\n", timestamp) < 0) {
            fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        } else {
            fflush(log_file);
        }
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Alert callback — fires on rising edge of alert pin                  */
/* ------------------------------------------------------------------ */
static void alert_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        /* Rising edge — alert pin went HIGH */
        if (gpioWrite(ALERT_PIN, 1) < 0) {
            fprintf(stderr, "Failed to set alert pin HIGH: %s\n",
                    strerror(errno));
        }
        gpioDelay(ALERT_DURATION_US);
        if (gpioWrite(ALERT_PIN, 0) < 0) {
            fprintf(stderr, "Failed to set alert pin LOW: %s\n",
                    strerror(errno));
        }
        gpioDelay(ALERT_SETTLE_US);
    }
}

/* ------------------------------------------------------------------ */
/* Sensor callback — fires on rising or falling edge of a sensor pin   */
/* ------------------------------------------------------------------ */
static void sensor_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    static uint32_t last_tick[2] = {0, 0};
    static int      state[2]     = {0, 0};
    int            idx;

    if (gpio == SENSOR_1_PIN) {
        idx = 0;
    } else if (gpio == SENSOR_2_PIN) {
        idx = 1;
    } else {
        return;
    }

    (void)userdata;

    /* Debounce: ignore edges that arrive too quickly */
    if (tick - last_tick[idx] < DEBOUNCE_US) {
        return;
    }
    last_tick[idx] = tick;

    /* Update internal state */
    state[idx] = level;

    /* Check if both sensors are HIGH */
    if (state[0] == 1 && state[1] == 1) {
        log_seismic_event();
    }
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure GPIO pins                          */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %s\n",
                SENSOR_1_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %s\n",
                SENSOR_2_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %s\n",
                ALERT_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down resistors so the pins read LOW when
       the sensors are open */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d: %s\n",
                SENSOR_1_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d: %s\n",
                SENSOR_2_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }

    /* Ensure alert pin starts LOW */
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize alert pin LOW: %s\n",
                strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Register callbacks for sensor pins                                  */
/* ------------------------------------------------------------------ */
static int register_callbacks(void)
{
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) < 0) {
        fprintf(stderr, "Failed to register callback for GPIO%d: %s\n",
                SENSOR_1_PIN, strerror(errno));
        return -1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) < 0) {
        fprintf(stderr, "Failed to register callback for GPIO%d: %s\n",
                SENSOR_2_PIN, strerror(errno));
        return -1;
    }
    if (gpioSetAlertFuncEx(ALERT_PIN, alert_callback, NULL) < 0) {
        fprintf(stderr, "Failed to register callback for GPIO%d: %s\n",
                ALERT_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Force alert pin LOW */
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to force alert pin LOW during cleanup: %s\n",
                strerror(errno));
    }

    /* Close log file */
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: error closing log file: %s\n",
                    strerror(errno));
        }
        log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open seismic_events.txt: %s\n",
                strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register callbacks */
    if (register_callbacks() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop — sleep until signal received */
    while (running) {
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

