    }
    if (gpioSetAlertFuncEx(ALERT_PIN, alert_callback, NULL) < 0) {
        fprintf(stderr, "Failed to register callback for GPIO%d: %s\n",
                ALERT_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Force alert pin LOW */
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to force alert pin LOW during cleanup: %s\n",
                strerror(errno));
    }

    /* Close log file */
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: error closing log file: %s\n",
                    strerror(errno));
        }
        log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open seismic_events.txt: %s\n",
                strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register callbacks */
    if (register_callbacks() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop — sleep until signal received */
    while (running) {
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

