/*
 * ADXRS290 Gyroscope Reader for Raspberry Pi Zero W
 *
 * Hardware SPI0:
 *   CE0  -> GPIO8  (BCM)
 *   SCLK -> GPIO11 (BCM)
 *   MOSI -> GPIO10 (BCM)
 *   MISO -> GPIO9  (BCM)
 *
 * LED:
 *   GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o adxrs290_reader adxrs290_reader.c -lpigpio -lrt -lpthread
 * Run:
 *   sudo ./adxrs290_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */

#define LED_GPIO         17         /* Warning LED */
#define RATE_THRESHOLD   20.0f      /* deg/s */
#define BUFFER_SIZE      100

/* ADXRS290 register addresses (MSB = 1 for read) */
#define REG_XGYRO_OUT    0x80
#define REG_YGYRO_OUT    0x82
#define REG_ZGYRO_OUT    0x84
#define REG_TEMP_OUT     0x86
#define REG_DIAG_STAT    0x88
#define REG_XGYRO_OFF    0x8A
#define REG_YGYRO_OFF    0x8C
#define REG_ZGYRO_OFF    0x8E
#define REG_TEMP_OFF     0x90
#define REG_GLOB_CMD     0x92
#define REG_SMPL_PRD     0x94
#define REG_ALM_CTRL     0x96
#define REG_ALM_SMPL1    0x98
#define REG_ALM_SMPL2    0x9A
#define REG_ALM_SMPL3    0x9C
#define REG_ALM_SMPL4    0x9E
#define REG_XGYRO_GAIN   0xA0
#define REG_YGYRO_GAIN   0xA2
#define REG_ZGYRO_GAIN   0xA4
#define REG_TEMP_GAIN    0xA6
#define REG_PROD_ID      0xA8
#define REG_XGYRO_LSB    0xAA
#define REG_YGYRO_LSB    0xAC
#define REG_ZGYRO_LSB    0xAE
#define REG_TEMP_LSB     0xB0

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static pthread_mutex_t g_buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

/* --------------------------- Circular Buffer ----------------------------- */
typedef struct {
    struct timespec ts;
    float           rate;
} gyro_data_t;

static gyro_data_t g_buffer[BUFFER_SIZE];
static int         g_buf_head = 0;
static int         g_buf_tail = 0;
static int         g_buf_count = 0;

static void buffer_push(struct timespec ts, float rate)
{
    g_buffer[g_buf_head].ts  = ts;
    g_buffer[g_buf_head].rate = rate;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count == BUFFER_SIZE) {
        g_buf_tail = (g_buf_tail + 1) % BUFFER_SIZE;
    } else {
        g_buf_count++;
    }
}

/* --------------------------- SPI Read Helpers ----------------------------- */
/*
 * ADXRS290 SPI protocol (MSB first):
 *   Byte 0: [R/W=1][ADDR_MSB][ADDR_LSB]
 *   Byte 1: dummy (clocked out to read data)
 *   Byte 2: dummy (clocked out to read data)
 *   Byte 3: dummy (clocked out to read data)
 *
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int spi_read_register(uint8_t reg, uint8_t *data, int len)
{
    if (len < 1 || len > 4) {
        fprintf(stderr, "spi_read_register: invalid length %d\n", len);
        return -1;
    }

    char tx[4] = { (char)(reg | 0x80), 0x00, 0x00, 0x00 };
    char rx[4] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, len);
    if (ret != len) {
        fprintf(stderr, "spi_read_register: spiXfer failed (reg=0x%02X, ret=%d)\n",
                reg, ret);
        return -1;
    }

    memcpy(data, rx + 1, len);
    return 0;
}

/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int spi_write_register(uint8_t reg, uint8_t value)
{
    char tx[4] = { (char)(reg & 0x7F), (char)value, 0x00, 0x00 };
    char rx[4] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "spi_write_register: spiXfer failed (reg=0x%02X, ret=%d)\n",
                reg, ret);
        return -1;
    }
    return 0;
}

/* --------------------------- ADXRS290 Driver ----------------------------- */
static int adxrs290_init(void)
{
    /*
     * Software reset: write 0x00 to GLOB_CMD (0x92).
     * The ADXRS290 will reset and return to standby mode.
     */
    if (spi_write_register(REG_GLOB_CMD, 0x00) != 0) {
        fprintf(stderr, "ADXRS290: failed to reset device\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /*
     * Configure sampling period: 100 Hz (0x0A).
     * SMPL_PRD = (1 / 100 Hz) * 1000000 = 10000.
     */
    if (spi_write_register(REG_SMPL_PRD, 0x0A) != 0) {
        fprintf(stderr, "ADXRS290: failed to set sampling period\n");
        return -1;
    }

    /*
     * Start continuous conversion: write 0x02 to GLOB_CMD.
     * Bit 1 = 1 -> continuous mode.
     */
    if (spi_write_register(REG_GLOB_CMD, 0x02) != 0) {
        fprintf(stderr, "ADXRS290: failed to start continuous conversion\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms for first sample */
    return 0;
}

/*
 * Read X-axis angular rate in deg/s.
 * Returns 0 on success, -1 on SPI read failure.
 */
static int adxrs290_read_rate(float *rate)
{
    uint8_t raw[2];

    if (spi_read_register(REG_XGYRO_OUT, raw, 2) != 0) {
        return -1;
    }

    /*
     * ADXRS290 data format (16-bit, two's complement):
     *   Bits 15..1  = angular rate (LSB = 0.01 deg/s)
     *   Bit  0      = sign bit
     */
    int16_t raw_rate = (int16_t)((raw[0] << 8) | raw[1]);
    *rate = (float)raw_rate * 0.01f;
    return 0;
}

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADXRS290 */
    if (adxrs290_init() != 0) {
        fprintf(stderr, "ADXRS290 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXRS290 reader started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float rate;
        if (adxrs290_read_rate(&rate) != 0) {
            fprintf(stderr, "SPI read error; continuing...\n");
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
            perror("clock_gettime");
            gpioDelay(100000);
            continue;
        }

        pthread_mutex_lock(&g_buffer_mutex);
        buffer_push(ts, rate);
        pthread_mutex_unlock(&g_buffer_mutex);

        /* Threshold check */
        if (rate > RATE_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        printf("X-axis rate: %.2f deg/s\n", rate);
        gpioDelay(10000); /* 10 ms -> 100 Hz sampling */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

