#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27

#define PWM_FREQUENCY 100
#define PWM_RANGE 255

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(LAMP1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", LAMP1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", LAMP2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", LAMP3_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Warning: Failed to set PWM frequency on GPIO%d.\n", LAMP1_PIN);
    }
    if (gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Warning: Failed to set PWM frequency on GPIO%d.\n", LAMP2_PIN);
    }
    if (gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Warning: Failed to set PWM frequency on GPIO%d.\n", LAMP3_PIN);
    }

    if (gpioSetPWMrange(LAMP1_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: Failed to set PWM range on GPIO%d.\n", LAMP1_PIN);
    }
    if (gpioSetPWMrange(LAMP2_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: Failed to set PWM range on GPIO%d.\n", LAMP2_PIN);
    }
    if (gpioSetPWMrange(LAMP3_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: Failed to set PWM range on GPIO%d.\n", LAMP3_PIN);
    }

    return 0;
}

static void set_lamp_brightness(int pin, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(pin, brightness);
}

static void fade_lamp(int pin, int duration_seconds) {
    if (duration_seconds <= 0) {
        set_lamp_brightness(pin, 0);
        return;
    }

    int steps = duration_seconds * PWM_FREQUENCY;
    int delay_us = 1000000 / PWM_FREQUENCY;

    for (int i = 0; i <= steps && program_running; i++) {
        int brightness = (PWM_RANGE * i) / steps;
        set_lamp_brightness(pin, brightness);
        gpioDelay(delay_us);
    }

    set_lamp_brightness(pin, 0);
}

static void turn_off_all_lamps(void) {
    set_lamp_brightness(LAMP1_PIN, 0);
