#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MPR121_ADDR    0x5A
#define RELAY_GPIO     17
#define DEBOUNCE_MS    100
#define POLL_DELAY_US  10000
#define LOG_FILE       "touch_relay.log"

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR           0x5E
#define MPR121_CONFIG1       0x5B
#define MPR121_CONFIG2       0x5C
#define MPR121_MHDR          0x2B
#define MPR121_NHDR          0x2C
#define MPR121_NCLR          0x2D
#define MPR121_FDLR          0x2E
#define MPR121_MHDF          0x2F
#define MPR121_NHDF          0x30
#define MPR121_NCLF          0x31
#define MPR121_FDLF          0x32
#define MPR121_NHDT          0x33
#define MPR121_NCLT          0x34
#define MPR121_FDLT          0x35

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void log_message(const char *msg)
{
    if (!g_log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(g_log_file, "[unknown time] %s\n", msg);
    }
    fflush(g_log_file);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d",
                 reg, value, rc);
        log_message(buf);
    }
    return rc;
}

static int mpr121_read(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C read failed: reg=0x%02X, rc=%d", reg, rc);
        log_message(buf);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int mpr121_init(void)
{
    /* Soft reset: write 0x63 to ECR */
    if (mpr121_write(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000); /* 1 ms */
    if (mpr121_write(MPR121_ECR, 0x63) < 0) return -1;
    gpioDelay(1000); /* 1 ms */

    /* Baseline filtering configuration */
    if (mpr121_write(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDLT, 0x00) < 0) return -1;

    /* Touch / release thresholds for electrodes 0-11 */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write(0x41 + (i * 2), 0x0F) < 0) return -1; /* touch */
        if (mpr121_write(0x42 + (i * 2), 0x0A) < 0) return -1; /* release */
    }

    /* FFI=6 samples, CDC=16 µA, CDT=0.5 µs */
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking, run mode */
    if (mpr121_write(MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status)
{
    uint8_t lo, hi;
    if (mpr121_read(MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (mpr121_read(MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        log_message("Cleanup complete.");
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_message("Failed to open I2C bus 1 at address 0x5A");
        gpioTerminate();
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        log_message("MPR121 initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_message("Failed to set GPIO17 as output");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        log_message("Failed to initialize GPIO17 to LOW");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Touch relay controller started.");

    bool relay_state = false;
    uint32_t last_touch_tick = 0;

    while (g_running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            log_message("Failed to read touch status; retrying...");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (touch_status & (1 << 0)) {
            uint32_t now = gpioTick();
            if (now - last_touch_tick >= DEBOUNCE_MS * 1000) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state ? 1 : 0) < 0) {
                    log_message("Failed to write relay GPIO");
                } else {
                    char msg[128];
                    snprintf(msg, sizeof(msg), "Relay toggled to %s",
                             relay_state ? "ON" : "OFF");
                    log_message(msg);
                }
                last_touch_tick = now;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

