                }
                if (value == 1) {
                    break;
                }
                gpioDelay(POLL_DELAY_US);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup_all:
    cleanup();

cleanup_gpio:
    gpioTerminate();
    return ret;
}

