#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_INTERVAL_MS 1000
#define HALF_INTERVAL_MS (DISPENSE_INTERVAL_MS / 2)
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_dispense(int pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Solenoid: %d, Duration: %d ms\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pin, duration_ms);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

static int dispense_solenoid(int pin, int duration_ms) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error activating solenoid on GPIO %d\n", pin);
        return -1;
    }

    if (log_dispense(pin, duration_ms) != 0) {
        fprintf(stderr, "Error logging dispense event for GPIO %d\n", pin);
        gpioWrite(pin, 0);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid on GPIO %d\n", pin);
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_1_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing GPIO %d to LOW\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_2_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing GPIO %d to LOW\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (dispense_solenoid(SOLENOID_1_PIN, HALF_INTERVAL_MS) != 0) {
            fprintf(stderr, "Error dispensing solenoid 1\n");
            break;
        }

        if (!running) break;

        if (dispense_solenoid(SOLENOID_2_PIN, HALF_INTERVAL_MS) != 0) {
            fprintf(stderr, "Error dispensing solenoid 2\n");
            break;
        }

        if (!running) break;

        gpioDelay(DISPENSE_INTERVAL_MS * 1000);
    }

    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();

    printf("Pneumatic dispensing system stopped.\n");
    return EXIT_SUCCESS;
}

