#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25

#define OBSTACLE_THRESHOLD 20.0
#define MAX_SPEED 255
#define MIN_SPEED -255
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void set_motor_speed(int motor, int speed) {
    if (speed > MAX_SPEED) speed = MAX_SPEED;
    if (speed < MIN_SPEED) speed = MIN_SPEED;

    if (motor == 'A') {
        if (speed > 0) {
            gpioWrite(MOTOR_A_FORWARD, 1);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENA, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 1);
            gpioPWM(ENA, -speed);
        } else {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENA, 0);
        }
    } else if (motor == 'B') {
        if (speed > 0) {
            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENB, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
            gpioPWM(ENB, -speed);
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENB, 0);
        }
    } else {
        fprintf(stderr, "Error: Invalid motor character '%c'\n", motor);
    }
}

float simulate_tilt_error(void) {
    return (float)(rand() % 2001 - 1000) / 100.0;
}

float simulate_distance(void) {
    return (float)(rand() % 39801 + 200) / 100.0;
}

void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        float tilt_error = simulate_tilt_error();
        float distance = simulate_distance();

        int motor_a_speed = (int)(tilt_error * 10.0);
        int motor_b_speed = (int)(tilt_error * 10.0);

        if (distance < OBSTACLE_THRESHOLD) {
            set_motor_speed('A', -128);
            set_motor_speed('B', -128);
        } else {
            set_motor_speed('A', motor_a_speed);
            set_motor_speed('B', motor_b_speed);
        }

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);
        gpioDelay(LOOP_DELAY_US);
    }

    set_motor_speed('A', 0);
    set_motor_speed('B', 0);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    return 0;
}

