#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  /* 50 ms in microseconds */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down so the pin reads LOW when the sensor is open */
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-down on GPIO%d.\n", TOUCH_SENSOR_PIN);
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure relay is OFF (LOW) at startup */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO%d to LOW.\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    /* Ensure relay is OFF before terminating */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int relay_state = 0;

    while (program_running) {
        int touch_detected = gpioRead(TOUCH_SENSOR_PIN);

        if (touch_detected < 0) {
            fprintf(stderr, "Error: Failed to read GPIO%d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_detected == 1) {
            relay_state = !relay_state;

            if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                fprintf(stderr, "Error: Failed to write GPIO%d.\n", RELAY_PIN);
                break;
            }

            printf("Touch detected! Relay toggled to %s.\n", relay_state ? "ON" : "OFF");

            /* Debounce delay */
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        /* Small delay to prevent busy-waiting */
        gpioDelay(1000); /* 1 ms */
    }

    cleanup_gpio();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

