/*
 * Mood light for Raspberry Pi 3 Model B+ using ALSA and software PWM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lm
 * Run:    ./mood_light [sensitivity]
 *
 * Hardware:
 *   Common-cathode RGB LED:
 *     Red   -> GPIO17 (BCM), via 330 Ω resistor
 *     Green -> GPIO18 (BCM), via 330 Ω resistor
 *     Blue  -> GPIO27 (BCM), via 330 Ω resistor
 *     Cathode -> GND
 *
 * ALSA:
 *   Device: "default"
 *   Format: 8000 Hz, 16-bit signed little-endian, mono
 *   Period size: 1024 frames
 *
 * PWM:
 *   Software PWM via the driver library API (libgpiod).
 *   Each channel is driven at 100 Hz with a duty cycle proportional to the
 *   RMS amplitude of the audio buffer.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#include <gpiod.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

/* ----------------------------- Configuration ----------------------------- */

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_FREQUENCY_HZ  100
#define PWM_PERIOD_US    (1000000 / PWM_FREQUENCY_HZ)

#define SAMPLE_RATE_HZ    8000
#define BITS_PER_SAMPLE   16
#define NUM_CHANNELS      1
#define PERIOD_FRAMES     1024
#define BUFFER_SIZE_BYTES (PERIOD_FRAMES * NUM_CHANNELS * (BITS_PER_SAMPLE / 8))

#define SENSITIVITY_DEFAULT 1.0f
#define SENSITIVITY_MIN     0.0f
#define SENSITIVITY_MAX     10.0f

#define LOOP_DELAY_US 10000  /* 10 ms */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;

#ifdef ALSA_AVAILABLE
static snd_pcm_t *g_pcm = NULL;
static snd_pcm_hw_params_t *g_hw_params = NULL;
static snd_pcm_sw_params_t *g_sw_params = NULL;
#endif

static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_red_line = NULL;
static struct gpiod_line *g_green_line = NULL;
static struct gpiod_line *g_blue_line = NULL;

/* --------------------------- Function prototypes ------------------------- */

static void signal_handler(int sig);
static void cleanup(void);

#ifdef ALSA_AVAILABLE
static int init_alsa(void);
static int read_audio_buffer(int16_t *buffer, size_t frames);
static float calculate_rms(const int16_t *buffer, size_t frames);
static void set_led_color(float rms, float sensitivity);
#else
static float calculate_rms_simulated(float phase);
static void set_led_color_simulated(float rms, float sensitivity);
#endif

static void set_pwm_duty_cycle(struct gpiod_line *line, int duty_percent);

/* ------------------------------- Signal ---------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
#ifdef ALSA_AVAILABLE
    if (g_pcm) {
        snd_pcm_drain(g_pcm);
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
    }
    if (g_sw_params) {
        snd_pcm_sw_params_free(g_sw_params);
        g_sw_params = NULL;
    }
    if (g_hw_params) {
        snd_pcm_hw_params_free(g_hw_params);
        g_hw_params = NULL;
    }
#endif

    if (g_red_line) {
        gpiod_line_set_value(g_red_line, 0);
        gpiod_line_release(g_red_line);
        g_red_line = NULL;
    }
    if (g_green_line) {
        gpiod_line_set_value(g_green_line, 0);
        gpiod_line_release(g_green_line);
        g_green_line = NULL;
    }
    if (g_blue_line) {
        gpiod_line_set_value(g_blue_line, 0);
        gpiod_line_release(g_blue_line);
        g_blue_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------- ALSA ------------------------------------ */

#ifdef ALSA_AVAILABLE

static int init_alsa(void)
{
    int err;

    err = snd_pcm_open(&g_pcm, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&g_hw_params);
    err = snd_pcm_hw_params_any(g_pcm, g_hw_params);
    if (err < 0) {
        fprintf(stderr, "Error getting hardware parameters: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_access(g_pcm, g_hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_set_format(g_pcm, g_hw_params, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "Error setting sample format: %s\n", snd_strerror(err));
        return -1;
    }

    unsigned int rate = SAMPLE_RATE_HZ;
    err = snd_pcm_hw_params_set_rate_near(g_pcm, g_hw_params, &rate, 0);
    if (err < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        return -1;
    }
    if (rate != SAMPLE_RATE_HZ) {
        fprintf(stderr, "Warning: requested sample rate %d Hz, got %u Hz\n",
                SAMPLE_RATE_HZ, rate);
    }

    unsigned int channels = NUM_CHANNELS;
    err = snd_pcm_hw_params_set_channels(g_pcm, g_hw_params, channels);
    if (err < 0) {
        fprintf(stderr, "Error setting channel count: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_set_period_size_near(g_pcm, g_hw_params, &PERIOD_FRAMES, 0);

    err = snd_pcm_hw_params(g_pcm, g_hw_params);
    if (err < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_sw_params_alloca(&g_sw_params);
    err = snd_pcm_sw_params_current(g_pcm, g_sw_params);
    if (err < 0) {
        fprintf(stderr, "Error getting software parameters: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_sw_params_set_avail_min(g_pcm, g_sw_params, PERIOD_FRAMES);
    if (err < 0) {
        fprintf(stderr, "Error setting available minimum: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_sw_params_set_start_threshold(g_pcm, g_sw_params, 1);
    if (err < 0) {
        fprintf(stderr, "Error setting start threshold: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_sw_params(g_pcm, g_sw_params);
    if (err < 0) {
        fprintf(stderr, "Error setting software parameters: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_prepare(g_pcm);
    if (err < 0) {
        fprintf(stderr, "Error preparing PCM: %s\n", snd_strerror(err));
        return -1;
    }

    return 0;
}

static int read_audio_buffer(int16_t *buffer, size_t frames)
{
    int err;
    snd_pcm_sframes_t frames_read;

    frames_read = snd_pcm_readi(g_pcm, buffer, frames);
    if (frames_read < 0) {
        if (frames_read == -EPIPE) {
            fprintf(stderr, "Buffer overrun (EPIPE) — recovering...\n");
            snd_pcm_prepare(g_pcm);
        } else if (frames_read == -ESTRPIPE) {
            fprintf(stderr, "Stream suspended (ESTRPIPE) — resuming...\n");
            snd_pcm_resume(g_pcm);
        } else {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror((int)frames_read));
        }
        return -1;
    }
    if ((size_t)frames_read != frames) {
        fprintf(stderr, "Short read: got %zd frames, expected %zu\n",
                frames_read, frames);
        return -1;
    }

    return 0;
}

static float calculate_rms(const int16_t *buffer, size_t frames)
{
    double sum_of_squares = 0.0;
    for (size_t i = 0; i < frames; i++) {
        double sample = (double)buffer[i];
        sum_of_squares += sample * sample;
    }
    return (float)sqrt(sum_of_squares / frames);
}

static void set_led_color(float rms, float sensitivity)
{
    float scaled_rms = rms * sensitivity;

    float red   = scaled_rms;
    float green = scaled_rms * 0.5f;
    float blue  = scaled_rms * 0.25f;

    if (red > 1.0f)   red   = 1.0f;
    if (green > 1.0f) green = 1.0f;
    if (blue > 1.0f)  blue  = 1.0f;

    int red_duty   = (int)(red   * 100.0f);
    int green_duty = (int)(green * 100.0f);
    int blue_duty  = (int)(blue  * 100.0f);

    set_pwm_duty_cycle(g_red_line,   red_duty);
    set_pwm_duty_cycle(g_green_line, green_duty);
    set_pwm_duty_cycle(g_blue_line,  blue_duty);
}

#else

static float calculate_rms_simulated(float phase)
{
    return (float)fabs(sinf(phase));
}

static void set_led_color_simulated(float rms, float sensitivity)
{
    float scaled_rms = rms * sensitivity;

    float red   = scaled_rms;
    float green = scaled_rms * 0.5f;
    float blue  = scaled_rms * 0.25f;

    if (red > 1.0f)   red   = 1.0f;
    if (green > 1.0f) green = 1.0f;
    if (blue > 1.0f)  blue  = 1.0f;

    int red_duty   = (int)(red   * 100.0f);
    int green_duty = (int)(green * 100.0f);
    int blue_duty  = (int)(blue  * 100.0f);

    set_pwm_duty_cycle(g_red_line,   red_duty);
    set_pwm_duty_cycle(g_green_line, green_duty);
    set_pwm_duty_cycle(g_blue_line,  blue_duty);
}

#endif

/* ------------------------------ PWM helper ------------------------------- */

static void set_pwm_duty_cycle(struct gpiod_line *line, int duty_percent)
{
    if (duty_percent < 0)   duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int on_time_us  = (PWM_PERIOD_US * duty_percent) / 100;
    int off_time_us = PWM_PERIOD_US - on_time_us;

    if (on_time_us > 0) {
        gpiod_line_set_value(line, 1);
        usleep(on_time_us);
    }
    if (off_time_us > 0) {
        gpiod_line_set_value(line, 0);
        usleep(off_time_us);
    }
}

/* --------------------------------- Main ---------------------------------- */

int main(int argc, char *argv[])
{
    float sensitivity = SENSITIVITY_DEFAULT;

    if (argc > 1) {
        char *endptr = NULL;
        sensitivity = strtof(argv[1], &endptr);
        if (endptr == argv[1] || *endptr != '\0' || sensitivity < SENSITIVITY_MIN || sensitivity > SENSITIVITY_MAX) {
            fprintf(stderr, "Invalid sensitivity: '%s'. Using default %.2f.\n",
                    argv[1], SENSITIVITY_DEFAULT);
            sensitivity = SENSITIVITY_DEFAULT;
        }
    }

    printf("Mood light started. Sensitivity: %.2f\n", sensitivity);
    printf("Press Ctrl+C to exit.\n");

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup via libgpiod --- */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    g_red_line   = gpiod_chip_get_line(g_chip, RED_PIN);
    g_green_line = gpiod_chip_get_line(g_chip, GREEN_PIN);
    g_blue_line  = gpiod_chip_get_line(g_chip, BLUE_PIN);

    if (!g_red_line || !g_green_line || !g_blue_line) {
        fprintf(stderr, "Failed to get GPIO lines.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(g_red_line,   "mood-light", 0) < 0 ||
        gpiod_line_request_output(g_green_line, "mood-light", 0) < 0 ||
        gpiod_line_request_output(g_blue_line,  "mood-light", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- ALSA init --- */
#ifdef ALSA_AVAILABLE
    if (init_alsa() < 0) {
        fprintf(stderr, "ALSA initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
#endif

    /* --- Main loop --- */
#ifdef ALSA_AVAILABLE
    int16_t *buffer = malloc(BUFFER_SIZE_BYTES);
    if (!buffer) {
        perror("malloc");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (read_audio_buffer(buffer, PERIOD_FRAMES) < 0) {
            usleep(LOOP_DELAY_US);
            continue;
        }
        float rms = calculate_rms(buffer, PERIOD_FRAMES);
        set_led_color(rms, sensitivity);
        usleep(LOOP_DELAY_US);
    }

    free(buffer);
#else
    float phase = 0.0f;
    while (g_running) {
        float rms = calculate_rms_simulated(phase);
        set_led_color_simulated(rms, sensitivity);
        phase += 0.01f;
        usleep(LOOP_DELAY_US);
    }
#endif

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

