#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TCS34725 I2C address (ADDR pin tied to GND) */
#define TCS34725_ADDR 0x29

/* TCS34725 register addresses */
#define TCS34725_ENABLE      0x80
#define TCS34725_ATIME       0x81
#define TCS34725_ID          0x12
#define TCS34725_CDATAL      0x94
#define TCS34725_CDATAH      0x95
#define TCS34725_RDATAL      0x96
#define TCS34725_RDATAH      0x97
#define TCS34725_GDATAL      0x98
#define TCS34725_GDATAH      0x99
#define TCS34725_BDATAL      0x9A
#define TCS34725_BDATAH      0x9B

/* Expected device ID */
#define TCS34725_ID_VALUE    0x44

/* Enable register bits */
#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

/* Integration time: 154 ms (0xFF) */
#define TCS34725_ATIME_154MS 0xFF

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_csv_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; cleanup happens in main()           */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TCS34725 register                               */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TCS34725 register                              */
/* Returns 0 on success and stores value in *out, -1 on failure        */
/* ------------------------------------------------------------------ */
static int tcs34725_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair (low byte at reg, high at reg+1)*/
/* Returns 0 on success and stores value in *out, -1 on failure        */
/* ------------------------------------------------------------------ */
static int tcs34725_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (tcs34725_read_reg(handle, reg, &lo) < 0)
        return -1;
    if (tcs34725_read_reg(handle, reg + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the TCS34725 sensor                                      */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int handle)
{
    uint8_t id = 0;

    /* Verify device identity */
    if (tcs34725_read_reg(handle, TCS34725_ID, &id) < 0)
        return -1;
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "[ERROR] TCS34725 ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (tcs34725_write_reg(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    gpioDelay(3000); /* 3 ms power-on delay */

    /* Enable RGBC ADC */
    if (tcs34725_write_reg(handle, TCS34725_ENABLE,
                           TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    /* Set integration time to 154 ms */
    if (tcs34725_write_reg(handle, TCS34725_ATIME, TCS34725_ATIME_154MS) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all four color channels from the sensor                         */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_read_all(int handle, uint16_t *c, uint16_t *r,
                            uint16_t *g, uint16_t *b)
{
    if (tcs34725_read_reg16(handle, TCS34725_CDATAL, c) < 0) return -1;
    if (tcs34725_read_reg16(handle, TCS34725_RDATAL, r) < 0) return -1;
    if (tcs34725_read_reg16(handle, TCS34725_GDATAL, g) < 0) return -1;
    if (tcs34725_read_reg16(handle, TCS34725_BDATAL, b) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                     */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, time_t ts, uint16_t c, uint16_t r,
                     uint16_t g, uint16_t b)
{
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)ts, c, r, g, b);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv_file != NULL) {
        fclose(g_csv_file);
        g_csv_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at TCS34725 address */
    g_i2c_handle = i2cOpen(1, TCS34725_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                TCS34725_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (tcs34725_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] TCS34725 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV file for appending */
    g_csv_file = fopen("color_data.csv", "a");
    if (g_csv_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open color_data.csv for writing\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_csv_file) == 0) {
        fprintf(g_csv_file, "timestamp,clear,red,green,blue\n");
        fflush(g_csv_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TCS34725 color sensor logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t c, r, g, b;

        if (tcs34725_read_all(g_i2c_handle, &c, &r, &g, &b) < 0) {
            fprintf(stderr, "[WARN] Sensor read failed; logging zeros\n");
            c = r = g = b = 0;
        }

        time_t now = time(NULL);
        log_data(g_csv_file, now, c, r, g, b);

        /* Sleep 500 ms (pigpio gpioDelay takes microseconds) */
        gpioDelay(500000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

