#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 518400

#define PWM_RANGE 100
#define PWM_FREQUENCY 1000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

void cleanup() {
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    gpioSetPWMrange(RELAY1_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY2_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY3_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY4_PIN, PWM_RANGE);

    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        // Sunrise phase
        for (int i = 0; i <= SUNRISE_DURATION && program_running; i++) {
            int duty_cycle = (int)(((float)i / SUNRISE_DURATION) * PWM_RANGE);
            gpioPWM(RELAY1_PIN, duty_cycle);
            gpioPWM(RELAY2_PIN, duty_cycle);
            gpioPWM(RELAY3_PIN, duty_cycle);
            gpioPWM(RELAY4_PIN, duty_cycle);
            time_sleep(1.0);
        }

        // Daytime phase
        for (int i = 0; i <= DAYTIME_DURATION && program_running; i++) {
            gpioPWM(RELAY1_PIN, PWM_RANGE);
            gpioPWM(RELAY2_PIN, PWM_RANGE);
            gpioPWM(RELAY3_PIN, PWM_RANGE);
            gpioPWM(RELAY4_PIN, PWM_RANGE);
            time_sleep(1.0);
        }

        // Sunset phase
        for (int i = 0; i <= SUNSET_DURATION && program_running; i++) {
            int duty_cycle = PWM_RANGE - (int)(((float)i / SUNSET_DURATION) * PWM_RANGE);
            gpioPWM(RELAY1_PIN, duty_cycle);
            gpioPWM(RELAY2_PIN, duty_cycle);
            gpioPWM(RELAY3_PIN, duty_cycle);
            gpioPWM(RELAY4_PIN, duty_cycle);
            time_sleep(1.0);
        }

        // Nighttime phase
        for (int i = 0; i <= NIGHTTIME_DURATION && program_running; i++) {
            gpioPWM(RELAY1_PIN, 0);
            gpioPWM(RELAY2_PIN, 0);
            gpioPWM(RELAY3_PIN, 0);
            gpioPWM(RELAY4_PIN, 0);
            time_sleep(1.0);
        }
    }

    cleanup();
    return 0;
}

