#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define VIDEO_DURATION 5
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define MAX_FILENAME_LEN 128
#define MAX_COMMAND_LEN 512

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int generate_filename(char *buf, size_t len) {
    char timestamp[32];
    if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
        return -1;
    }
    if (snprintf(buf, len, "%s%s.h264", VIDEO_DIR, timestamp) >= (int)len) {
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_video(const char *filename, int duration) {
    char command[MAX_COMMAND_LEN];
    int ret;

    ret = snprintf(command, sizeof(command),
                   "raspivid -o %s -t %d000 -w 640 -h 480 -fps 30",
                   filename, duration);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: Command buffer too small.\n");
        return -1;
    }

    printf("Capturing video for %d seconds to %s\n", duration, filename);
    fflush(stdout);

    ret = system(command);
    if (ret == -1) {
        fprintf(stderr, "Error executing raspivid: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "raspivid failed with status %d\n",
                WIFEXITED(ret) ? WEXITSTATUS(ret) : -1);
        return -1;
    }

    printf("Video capture complete.\n");
    fflush(stdout);
    return 0;
}

int main(void) {
    char timestamp[32];
    char filename[MAX_FILENAME_LEN];
    uint32_t last_trigger_tick = 0;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_PIN);
    fflush(stdout);

    while (program_running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", SENSOR_PIN);
            break;
        }

        if (level == 0) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick >= DEBOUNCE_DELAY_MS * 1000) {
                if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
                    fprintf(stderr, "Error getting timestamp.\n");
                    break;
                }

                if (generate_filename(filename, sizeof(filename)) != 0) {
                    fprintf(stderr, "Error generating filename.\n");
                    break;
                }

                if (log_motion_event(timestamp) != 0) {
                    fprintf(stderr, "Error logging motion event.\n");
                    break;
                }

                if (capture_video(filename, VIDEO_DURATION) != 0) {
                    fprintf(stderr, "Error capturing video.\n");
                    break;
                }

                last_trigger_tick = now;
            }
        }

        gpioDelay(10000);
    }

    printf("\nCleaning up...\n");
    fflush(stdout);

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

