#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 low) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

/* Sensitivity scale factor for ±250 deg/s range */
#define GYRO_SCALE 131.0f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (10 ms = 100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Maximum re-initialization attempts */
#define MAX_REINIT_ATTEMPTS 3

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register pair from the MPU-6050             */
/* Returns 0 on success, -1 on failure                                */
/* ------------------------------------------------------------------ */
static int read_gyro_axis(int handle, uint8_t reg_high, int16_t *out)
{
    char buf[2];

    /* Write the register pointer */
    if (i2cWriteByte(handle, reg_high) < 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg_high, strerror(errno));
        return -1;
    }

    /* Read two bytes (high byte first) */
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg_high, strerror(errno));
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MPU-6050: wake up, verify device ID, configure       */
/* Returns 0 on success, -1 on failure                                */
/* ------------------------------------------------------------------ */
static int init_mpu6050(int handle)
{
    int id;

    /* Wake up the device (clear SLEEP bit in PWR_MGMT_1) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU-6050: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time after wake */

    /* Verify device identity by reading WHO_AM_I register */
    id = i2cReadByteData(handle, 0x75);
    if (id < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x68) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x68)\n", id);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Re-initialize the I2C bus and MPU-6050 after a failure              */
/* Returns 0 on success, -1 on failure                                */
/* ------------------------------------------------------------------ */
static int reinit_mpu6050(void)
{
    int attempt;

    for (attempt = 0; attempt < MAX_REINIT_ATTEMPTS; attempt++) {
        fprintf(stderr, "Re-initializing MPU-6050 (attempt %d/%d)...\n",
                attempt + 1, MAX_REINIT_ATTEMPTS);

        if (g_i2c_handle >= 0) {
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
        }

        gpioDelay(100000); /* 100 ms between attempts */

        g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
        if (g_i2c_handle < 0) {
            fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
            continue;
        }

        if (init_mpu6050(g_i2c_handle) == 0) {
            fprintf(stderr, "MPU-6050 re-initialized successfully.\n");
            return 0;
        }

        fprintf(stderr, "MPU-6050 re-initialization failed.\n");
    }

    fprintf(stderr, "Failed to re-initialize MPU-6050 after %d attempts.\n",
            MAX_REINIT_ATTEMPTS);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Log a sample to the CSV file                                        */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%.3f,%.3f,%.3f\n",
            timestamp, ts.tv_nsec / 1000000L, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t raw_x, raw_y, raw_z;
    float x_degps, y_degps, z_degps;
    int consecutive_failures = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, MPU6050_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050(g_i2c_handle) != 0) {
        fprintf(stderr, "Failed to initialize MPU-6050. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("gyro_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(g_log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "Gyroscope logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        if (read_gyro_axis(g_i2c_handle, GYRO_XOUT_H, &raw_x) == 0 &&
            read_gyro_axis(g_i2c_handle, GYRO_YOUT_H, &raw_y) == 0 &&
            read_gyro_axis(g_i2c_handle, GYRO_ZOUT_H, &raw_z) == 0) {

            /* Convert raw values to degrees per second */
            x_degps = (float)raw_x / GYRO_SCALE;
            y_degps = (float)raw_y / GYRO_SCALE;
            z_degps = (float)raw_z / GYRO_SCALE;

            log_sample(g_log_file, x_degps, y_degps, z_degps);
            consecutive_failures = 0;
        } else {
            consecutive_failures++;
            fprintf(stderr, "Failed to read gyro data (consecutive failures: %d)\n",
                    consecutive_failures);

            if (consecutive_failures >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max consecutive failures reached. Exiting.\n");
                break;
            }

            if (reinit_mpu6050() != 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

