static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d HIGH.\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return rand() % 101;
}

static void control_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d to %d.\n", pin, state);
    }
}

static void log_data(int moisture, const int relay_states[NUM_RELAYS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Moisture: %d, Relay 1: %s, Relay 2: %s, Relay 3: %s, Relay 4: %s\n",
                timestamp, moisture,
                relay_states[0] ? "ON" : "OFF",
                relay_states[1] ? "ON" : "OFF",
                relay_states[2] ? "ON" : "OFF",
                relay_states[3] ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file.\n");
    }
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 1);
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int relay_states[NUM_RELAYS];
    int moisture;

    srand((unsigned int)time(NULL));

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        moisture = read_moisture_sensor();

        for (int i = 0; i < NUM_RELAYS; i++) {
            relay_states[i] = (moisture < DRY_THRESHOLD) ? 0 : 1;
            control_relay(relay_pins[i], relay_states[i]);
        }

        log_data(moisture, relay_states);

        printf("Moisture: %d, Relay 1: %s, Relay 2: %s, Relay 3: %s, Relay 4: %s\n",
               moisture,
               relay_states[0] ? "ON" : "OFF",
               relay_states[1] ? "ON" : "OFF",
               relay_states[2] ? "ON" : "OFF",
               relay_states[3] ? "ON" : "OFF");

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

