/*
 * ADXL345 Free-Fall Detector for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (I2C bus 1 SDA, pin 3)
 *   ADXL345 SCL  -> GPIO3  (I2C bus 1 SCL, pin 5)
 *   ADXL345 VCC  -> 3.3 V (pin 1)
 *   ADXL345 GND  -> GND   (pin 9)
 *   Alarm LED/buzzer anode -> GPIO27 (pin 13) via 330 Ω resistor
 *   Alarm LED/buzzer cathode -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall freefall.c -lpigpio -lrt
 * Run:
 *   sudo ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDR        0x53
#define ADXL345_REG_DEVID   0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0  0x32
#define ADXL345_DEVID_VAL   0xE5
#define ADXL345_SCALE_FACTOR 0.0039  /* g/LSB at ±2 g range */

/* ---- Free-fall detection ---- */
#define FREEFALL_THRESHOLD_G 0.2f
#define FREEFALL_DURATION_S  0.5f
#define FREEFALL_CONFIRM_DELAY_S 0.5f
#define FREEFALL_CONFIRM_DURATION_S 0.5f

/* ---- Alarm ---- */
#define ALARM_GPIO 27
#define ALARM_DURATION_S 5.0f

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an ADXL345 register; returns 0 on success,   */
/* -1 on error.                                                         */
/* ------------------------------------------------------------------ */
static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an ADXL345 register; returns 0 on success,    */
/* -1 on error.                                                         */
/* ------------------------------------------------------------------ */
static int adxl345_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (DATAX0..DATAZ1) and convert to   */
/* g.  Returns 0 on success, -1 on error.                               */
/* ------------------------------------------------------------------ */
static int adxl345_read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];

    /*
     * i2cReadI2CBlockData returns the number of bytes read, or a
     * negative pigpio error code.
     */
    int rc = i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData returned %d (expected 6)\n", rc);
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * ADXL345_SCALE_FACTOR;
    *y = (float)raw_y * ADXL345_SCALE_FACTOR;
    *z = (float)raw_z * ADXL345_SCALE_FACTOR;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Detect a free-fall event: all three axes below threshold for        */
/* FREEFALL_DURATION_S seconds, then re-check after a delay.          */
/* Returns true if confirmed, false otherwise.                         */
/* ------------------------------------------------------------------ */
static bool detect_freefall(int handle)
{
    float x, y, z;

    if (adxl345_read_acceleration(handle, &x, &y, &z) != 0)
        return false;

    if (fabsf(x) > FREEFALL_THRESHOLD_G ||
        fabsf(y) > FREEFALL_THRESHOLD_G ||
        fabsf(z) > FREEFALL_THRESHOLD_G)
        return false;

    /* Free-fall detected — hold for the required duration */
    time_sleep(FREEFALL_DURATION_S);

    if (adxl345_read_acceleration(handle, &x, &y, &z) != 0)
        return false;

    if (fabsf(x) > FREEFALL_THRESHOLD_G ||
        fabsf(y) > FREEFALL_THRESHOLD_G ||
        fabsf(z) > FREEFALL_THRESHOLD_G)
        return false;

    /* Re-check after a delay */
    time_sleep(FREEFALL_CONFIRM_DELAY_S);

    if (adxl345_read_acceleration(handle, &x, &y, &z) != 0)
        return false;

    return (fabsf(x) <= FREEFALL_THRESHOLD_G &&
            fabsf(y) <= FREEFALL_THRESHOLD_G &&
            fabsf(z) <= FREEFALL_THRESHOLD_G);
}

/* ------------------------------------------------------------------ */
/* Log a free-fall event to freefall.log in CSV format.                 */
/* ------------------------------------------------------------------ */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen("freefall.log", "a");
    if (!fp) {
        perror("[ERROR] fopen(freefall.log)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return;
    }

    char ts[64];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Activate the alarm: drive GPIO high for ALARM_DURATION_S seconds.   */
/* ------------------------------------------------------------------ */
static void activate_alarm(void)
{
    if (gpioWrite(ALARM_GPIO, 1) < 0)
        fprintf(stderr, "[WARN] gpioWrite(ALARM_GPIO, 1) failed\n");

    time_sleep(ALARM_DURATION_S);

    if (gpioWrite(ALARM_GPIO, 0) < 0)
        fprintf(stderr, "[WARN] gpioWrite(ALARM_GPIO, 0) failed\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure alarm GPIO ---- */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(ALARM_GPIO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* ---- Open I2C bus 1 at ADXL345 address ---- */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                ADXL345_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify device identity ---- */
    uint8_t devid = 0;
    if (adxl345_read_reg(g_i2c_handle, ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "[FATAL] Cannot read DEVID — sensor absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "[FATAL] DEVID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_VAL);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Standby mode before configuring ---- */
    if (adxl345_write_reg(g_i2c_handle, ADXL345_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "[FATAL] Failed to enter standby mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Set data rate to 100 Hz (0x0A) ---- */
    if (adxl345_write_reg(g_i2c_handle, 0x2C, 0x0A) != 0) {
        fprintf(stderr, "[FATAL] Failed to set data rate\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Set range to ±2 g (0x00) ---- */
    if (adxl345_write_reg(g_i2c_handle, 0x31, 0x00) != 0) {
        fprintf(stderr, "[FATAL] Failed to set range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Enter measurement mode ---- */
    if (adxl345_write_reg(g_i2c_handle, ADXL345_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "[FATAL] Failed to enter measurement mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("ADXL345 free-fall detector running.  Press Ctrl+C to exit.\n");
    printf("Threshold: %.1f g  Duration: %.1f s  Confirm delay: %.1f s\n",
           FREEFALL_THRESHOLD_G, FREEFALL_DURATION_S, FREEFALL_CONFIRM_DELAY_S);

    /* ---- Main polling loop ---- */
    while (g_running) {
        if (detect_freefall(g_i2c_handle)) {
            float x, y, z;
            if (adxl345_read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
                printf("[FREEFALL] x=%.3f g  y=%.3f g  z=%.3f g\n", x, y, z);
                log_freefall(x, y, z);
                activate_alarm();
            } else {
                fprintf(stderr, "[ERROR] Failed to read acceleration during alarm\n");
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

