        return EXIT_FAILURE;
    }

    /* ---- Set range to ±2 g (0x00) ---- */
    if (adxl345_write_reg(g_i2c_handle, 0x31, 0x00) != 0) {
        fprintf(stderr, "[FATAL] Failed to set range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Enter measurement mode ---- */
    if (adxl345_write_reg(g_i2c_handle, ADXL345_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "[FATAL] Failed to enter measurement mode\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("ADXL345 free-fall detector running.  Press Ctrl+C to exit.\n");
    printf("Threshold: %.1f g  Duration: %.1f s  Confirm delay: %.1f s\n",
           FREEFALL_THRESHOLD_G, FREEFALL_DURATION_S, FREEFALL_CONFIRM_DELAY_S);

    /* ---- Main polling loop ---- */
    while (g_running) {
        if (detect_freefall(g_i2c_handle)) {
            float x, y, z;
            if (adxl345_read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
                printf("[FREEFALL] x=%.3f g  y=%.3f g  z=%.3f g\n", x, y, z);
                log_freefall(x, y, z);
                activate_alarm();
            } else {
                fprintf(stderr, "[ERROR] Failed to read acceleration during alarm\n");
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

