/*
 * HC-SR04 Ultrasonic Distance Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO4  (BCM 4)
 *   HC-SR04 ECHO -> GPIO18 (BCM 18)
 *   HC-SR04 VCC  -> 5 V
 *   HC-SR04 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04_logger hcsr04_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./hcsr04_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define TRIGGER_PIN      4
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10
#define MEASURE_PERIOD_US 200000   /* 200 ms between triggers */
#define ECHO_TIMEOUT_US  100000    /* 100 ms max echo wait */
#define MAX_PULSE_US     23200     /* ~4 m round-trip limit */
#define SPEED_OF_SOUND_CM_PER_US 0.0343

#define LOG_FILE_NAME    "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                      */
/* ------------------------------------------------------------------ */

typedef struct {
    uint32_t start_tick;
    uint32_t end_tick;
    bool     got_rising;
    bool     got_falling;
    bool     valid;
} echo_state_t;

static echo_state_t g_echo;
static FILE        *g_log_file = NULL;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t g_terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* pigpio tick helpers (32-bit microsecond counter, wraps every ~71.6 min) */
/* ------------------------------------------------------------------ */

static uint32_t tick_diff(uint32_t start, uint32_t end)
{
    return end - start;  /* unsigned subtraction wraps correctly */
}

/* ------------------------------------------------------------------ */
/* Interrupt callbacks (run in pigpio callback thread)                 */
/* ------------------------------------------------------------------ */

static void echo_rising_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1)
        return;

    pthread_mutex_lock(&g_mutex);
    g_echo.start_tick  = tick;
    g_echo.got_rising  = true;
    g_echo.valid      = false;
    pthread_mutex_unlock(&g_mutex);
}

static void echo_falling_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 0)
        return;

    pthread_mutex_lock(&g_mutex);
    g_echo.end_tick    = tick;
    g_echo.got_falling = true;

    if (g_echo.got_rising) {
        uint32_t pulse_us = tick_diff(g_echo.start_tick, g_echo.end_tick);
        if (pulse_us <= MAX_PULSE_US) {
            g_echo.valid = true;
        } else {
            /* Out of range — treat as noise */
            g_echo.valid = false;
        }
    }
    pthread_mutex_unlock(&g_mutex);
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on the TRIG pin                               */
/* ------------------------------------------------------------------ */

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Read distance in cm; returns -1.0 on error                          */
/* ------------------------------------------------------------------ */

static float read_distance(void)
{
    /* Reset echo state */
    pthread_mutex_lock(&g_mutex);
    g_echo.got_rising  = false;
    g_echo.got_falling = false;
    g_echo.valid      = false;
    pthread_mutex_unlock(&g_mutex);

    trigger_sensor();

    /* Wait for echo with timeout */
    uint32_t waited = 0;
    while (waited < ECHO_TIMEOUT_US) {
        gpioDelay(100);  /* 100 us slices */
        waited += 100;

        pthread_mutex_lock(&g_mutex);
        if (g_echo.got_falling) {
            uint32_t pulse_us = tick_diff(g_echo.start_tick, g_echo.end_tick);
            pthread_mutex_unlock(&g_mutex);
            if (pulse_us > MAX_PULSE_US) {
                return -1.0f;  /* out of range */
            }
            return (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;
        }
        pthread_mutex_unlock(&g_mutex);
    }

    return -1.0f;  /* timeout — no echo received */
}

/* ------------------------------------------------------------------ */
/* Log a reading with nanosecond timestamp                             */
/* ------------------------------------------------------------------ */

static void log_reading(float distance)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    pthread_mutex_lock(&g_mutex);
    uint32_t tick = gpioTick();
    pthread_mutex_unlock(&g_mutex);

    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(g_log_file, "%lld,%.2f,%u\n", timestamp_ns, distance, tick);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Cancel callbacks first so no more interrupts fire */
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetAlertFuncEx(TRIGGER_PIN, NULL, NULL);

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
    pthread_mutex_destroy(&g_mutex);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN (GPIO%d) as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN (GPIO%d) as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* Register interrupt callbacks */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_rising_cb, NULL) != 0) {
        fprintf(stderr, "Error: failed to register rising edge callback on ECHO_PIN.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFuncEx(TRIGGER_PIN, echo_falling_cb, NULL) != 0) {
        fprintf(stderr, "Error: failed to register falling edge callback on TRIGGER_PIN.\n");
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
        gpioSetAlertFuncEx(TRIGGER_PIN, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp_ns,distance_cm,tick\n");
        fflush(g_log_file);
    }

    /* Install signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to stop.\n");
    printf("Logging to: %s\n", LOG_FILE_NAME);

    /* Main measurement loop */
    while (!g_terminate) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: sensor read failed (timeout or out of range).\n");
        } else {
            log_reading(distance);
        }

        /* Wait for next measurement cycle */
        gpioDelay(MEASURE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

