#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x19
#define BUZZER_GPIO 17

#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define STATUS_REG 0x27

#define ACCEL_SCALE 0.001f
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 1.5f
#define BUZZER_DURATION_MS 1000
#define SAMPLE_DELAY_US 10000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int i2c_read_register(int handle, uint8_t reg, uint8_t *value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X): %d, retry %d/%d\n", reg, result, retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(1000);
    }
    return -1;
}

static int i2c_write_register(int handle, uint8_t reg, uint8_t value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %d, retry %d/%d\n", reg, value, result, retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(1000);
    }
    return -1;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t buffer[6];
    if (i2c_read_register(handle, OUT_X_L | 0x80, buffer) != 0) {
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = raw_x * ACCEL_SCALE;
    *y = raw_y * ACCEL_SCALE;
    *z = raw_z * ACCEL_SCALE;
    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void activate_buzzer(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(gpio_pin, 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float freefall_threshold = FREEFALL_THRESHOLD;
    float impact_threshold = IMPACT_THRESHOLD;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
        if (freefall_threshold <= 0.0f) {
            fprintf(stderr, "Invalid freefall threshold: %s\n", argv[1]);
            return 1;
        }
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
        if (impact_threshold <= 0.0f) {
            fprintf(stderr, "Invalid impact threshold: %s\n", argv[2]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", LIS3DH_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2c_write_register(i2c_handle, CTRL_REG1, 0x27) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        cleanup();
        return 1;
    }

    if (i2c_write_register(i2c_handle, CTRL_REG4, 0x08) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4\n");
        cleanup();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Monitoring acceleration (freefall: %.2f g, impact: %.2f g)...\n", freefall_threshold, impact_threshold);

    bool in_freefall = false;

    while (program_running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "Failed to read acceleration after retries\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude < freefall_threshold) {
            if (!in_freefall) {
                printf("Freefall detected!\n");
                in_freefall = true;
            }
        } else if (magnitude > impact_threshold) {
            if (in_freefall) {
                printf("Impact detected!\n");
                activate_buzzer(BUZZER_GPIO, BUZZER_DURATION_MS);
                in_freefall = false;
            }
        } else {
            in_freefall = false;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

