#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define LIS3DH_ADDR_DEFAULT 0x19
#define LIS3DH_ADDR_MIN     0x18
#define LIS3DH_ADDR_MAX     0x1F

#define CTRL_REG1          0x20
#define CTRL_REG4          0x23
#define OUT_X_L            0x28
#define OUT_X_H            0x29
#define OUT_Y_L            0x2A
#define OUT_Y_H            0x2B
#define OUT_Z_L            0x2C
#define OUT_Z_H            0x2D

#define CTRL_REG1_VAL      0x57  /* 100 Hz, normal mode, XYZ axes enabled */
#define CTRL_REG4_VAL      0x08  /* ±2 g, high-resolution, left-justified */

#define LOG_FILE           "/var/log/high_acceleration.log"
#define SAMPLE_PERIOD_US   100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", val, reg);
        return -1;
    }
    return 0;
}

static int read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t xl, xh, yl, yh, zl, zh;

    if (read_reg(handle, OUT_X_L, &xl) < 0) return -1;
    if (read_reg(handle, OUT_X_H, &xh) < 0) return -1;
    if (read_reg(handle, OUT_Y_L, &yl) < 0) return -1;
    if (read_reg(handle, OUT_Y_H, &yh) < 0) return -1;
    if (read_reg(handle, OUT_Z_L, &zl) < 0) return -1;
    if (read_reg(handle, OUT_Z_H, &zh) < 0) return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    /* ±2 g, high-resolution, left-justified: 12-bit two's complement */
    *x = (float)raw_x / 4096.0f;
    *y = (float)raw_y / 4096.0f;
    *z = (float)raw_z / 4096.0f;

    return 0;
}

static void log_acceleration(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f g, Y: %.3f g, Z: %.3f g\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    } else {
        fprintf(fp, "(timestamp error), X: %.3f g, Y: %.3f g, Z: %.3f g\n", x, y, z);
    }

    fclose(fp);
}

static void shutdown_system(void) {
    printf("Shutting down system...\n");
    fflush(stdout);
    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    int i2c_address = LIS3DH_ADDR_DEFAULT;
    float threshold = 2.0f;

    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < LIS3DH_ADDR_MIN || i2c_address > LIS3DH_ADDR_MAX) {
                    fprintf(stderr, "Invalid I2C address: 0x%02X (must be 0x%02X-0x%02X)\n",
                            i2c_address, LIS3DH_ADDR_MIN, LIS3DH_ADDR_MAX);
                    return EXIT_FAILURE;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be greater than 0\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold_g]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_SUCCESS;  /* non-hardware environment */
    }

    g_i2c_handle = i2cOpen(1, i2c_address, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", i2c_address, g_i2c_handle);
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    if (write_reg(g_i2c_handle, CTRL_REG1, CTRL_REG1_VAL) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    if (write_reg(g_i2c_handle, CTRL_REG4, CTRL_REG4_VAL) < 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    printf("Monitoring acceleration (threshold: %.2f g)... Press Ctrl+C to exit.\n", threshold);

    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
