/*
 * Autonomous line-following robot using a SunFounder 3-Way Tracking Sensor.
 *
 * Wiring (BCM numbering):
 *   GPIO4  - Left sensor  (digital output)
 *   GPIO17 - Center sensor (digital output)
 *   GPIO27 - Right sensor  (digital output)
 *   GPIO22 - Alert LED/buzzer (active-high)
 *
 * Behavior:
 *   - Polls sensors every 10 ms.
 *   - Logs last 5 readings into a circular buffer.
 *   - Drives alert HIGH for 2 s when center sensor reads "no line" (logic 1)
 *     for 5 consecutive readings.
 *   - Moves forward when center detects a line (logic 0).
 *   - Turns left when left sensor detects a line.
 *   - Turns right when right sensor detects a line.
 *   - Stops when all sensors read "no line".
 *
 * Build:  gcc -O2 -Wall -Wextra -o line_follower line_follower.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define SENSOR_LEFT   4
#define SENSOR_CENTER 17
#define SENSOR_RIGHT  27
#define ALERT_PIN     22

/* ---- Timing constants (microseconds) ---- */
#define POLL_DELAY_US      10000   /* 10 ms between sensor polls */
#define ALERT_DURATION_US  2000000 /* 2 s alert pulse            */
#define NO_LINE_THRESHOLD  5       /* consecutive readings to trigger alert */

/* ---- Circular buffer size ---- */
#define BUFFER_SIZE 5

/* ---- Sensor reading structure ---- */
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

/* ---- Circular buffer ---- */
static SensorReadings buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* ---- Global flag for graceful shutdown ---- */
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single sensor pin; returns 0 or 1 on success, -1 on error.    */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio_pin)
{
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n",
                gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Log sensor readings into the circular buffer.                       */
/* ------------------------------------------------------------------ */
static void log_sensor_data(int left, int center, int right)
{
    buffer[buffer_index].left   = left;
    buffer[buffer_index].center = center;
    buffer[buffer_index].right  = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* ------------------------------------------------------------------ */
/* Check if the center sensor has detected "no line" (logic 1) for     */
/* NO_LINE_THRESHOLD consecutive readings.                            */
/* ------------------------------------------------------------------ */
static bool check_no_line(void)
{
    for (int i = 0; i < NO_LINE_THRESHOLD; i++) {
        int idx = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        if (buffer[idx].center == 0) {
            return false; /* line detected at some point */
        }
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* Placeholder motor control functions (replace with real PWM/H-bridge) */
/* ------------------------------------------------------------------ */
static void move_forward(void)
{
    printf("Moving forward\n");
}

static void turn_left(void)
{
    printf("Turning left\n");
}

static void turn_right(void)
{
    printf("Turning right\n");
}

static void stop_robot(void)
{
    printf("Stopping\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — release all pigpio resources.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure alert is off before terminating */
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(SENSOR_LEFT,   PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_CENTER, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_RIGHT,  PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure alert pin as output and ensure it starts LOW ---- */
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set alert pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_PIN, 0);

    /* ---- Register signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    /* ---- Main control loop ---- */
    while (program_running) {
        int left   = read_sensor(SENSOR_LEFT);
        int center = read_sensor(SENSOR_CENTER);
        int right  = read_sensor(SENSOR_RIGHT);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Sensor read error — stopping robot\n");
            stop_robot();
            break;
        }

        log_sensor_data(left, center, right);

        /* Check for "no line" condition */
        if (check_no_line()) {
            gpioWrite(ALERT_PIN, 1);
            gpioDelay(ALERT_DURATION_US);
            gpioWrite(ALERT_PIN, 0);
        }

        /* Line detection logic */
        if (center == 0) {
            move_forward();
        } else if (left == 0) {
            turn_left();
        } else if (right == 0) {
            turn_right();
        } else {
            stop_robot();
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

