/*
 * Si7210 Hall-effect sensor monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si7210 SDA  -> GPIO 2 (I2C bus 1 SDA, pin 3)
 *   Si7210 SCL  -> GPIO 3 (I2C bus 1 SCL, pin 5)
 *   Si7210 VDD  -> 3.3 V
 *   Si7210 GND  -> GND
 *   Relay IN    -> GPIO 17 (BCM, active high)
 *   Relay VCC   -> 5 V (external supply recommended)
 *   Relay GND   -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si7210_monitor si7210_monitor.c -lsi7210
 *
 * Run:
 *   sudo ./si7210_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>
#include <si7210.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define SI7210_ADDR         0x48          /* Si7210 default I2C address (ADDR pin tied to GND) */
#define RELAY_GPIO          17            /* BCM GPIO 17 */
#define FIELD_THRESHOLD_MT  5.0f          /* mT */
#define SAMPLE_PERIOD_US    100000        /* 100 ms */
#define REG_POLL_TIMEOUT    50            /* 50 × 100 ms = 5 s */
#define LOG_FILE            "magnetic_events.txt"

/* Si7210 register addresses (from datasheet) */
#define SI7210_REG_DEVICE_ID       0x00
#define SI7210_REG_DEVICE_ID_VAL   0x10
#define SI7210_REG_MEAS_CFG        0x01
#define SI7210_REG_MEAS_CFG_VAL    0x01   /* Start continuous measurement */
#define SI7210_REG_DATA_READY      0x02
#define SI7210_REG_DATA_READY_VAL  0x01
#define SI7210_REG_DATA_LSB        0x03
#define SI7210_REG_DATA_MSB        0x04

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static int      g_relay_state = 0;
static FILE    *g_log_file   = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static void log_event(const char *msg);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_field(float *field_mt);
static void control_relay(int state);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *msg)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (g_log_file) {
        fprintf(g_log_file, "%s: %s\n", ts, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

/* ------------------------------- I2C ------------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, SI7210_ADDR, strerror(errno));
        return -1;
    }

    /* Verify device identity */
    int id = i2cReadByteData(g_i2c_handle, SI7210_REG_DEVICE_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read DEVICE_ID register: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    if (id != SI7210_REG_DEVICE_ID_VAL) {
        fprintf(stderr, "Unexpected DEVICE_ID: 0x%02X (expected 0x%02X)\n",
                id, SI7210_REG_DEVICE_ID_VAL);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Start continuous measurement */
    if (i2cWriteByteData(g_i2c_handle, SI7210_REG_MEAS_CFG, SI7210_REG_MEAS_CFG_VAL) < 0) {
        fprintf(stderr, "Failed to write MEAS_CFG register: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------- GPIO ------------------------------------ */
static int init_gpio(void)
{
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", RELAY_GPIO);
        return -1;
    }
    g_relay_state = 0;
    return 0;
}

/* ----------------------------- Read field -------------------------------- */
static int read_field(float *field_mt)
