    while (poll_count < REG_POLL_TIMEOUT) {
        ready = i2cReadByteData(g_i2c_handle, SI7210_REG_DATA_READY);
        if (ready < 0) {
            fprintf(stderr, "i2cReadByteData(DATA_READY) failed: %s\n", strerror(errno));
            return -1;
        }
        if (ready & SI7210_REG_DATA_READY_VAL)
            break;
        gpioDelay(100000); /* 100 ms */
        poll_count++;
    }

    if (poll_count >= REG_POLL_TIMEOUT) {
        fprintf(stderr, "Timeout waiting for DATA_READY (sensor may be absent or bus error)\n");
        return -1;
