    }

    return 0;
}

/* ----------------------------- Relay control ----------------------------- */
static void control_relay(int state)
{
    if (state != g_relay_state) {
        if (gpioWrite(RELAY_GPIO, state) < 0) {
            fprintf(stderr, "gpioWrite(%d, %d) failed\n", RELAY_GPIO, state);
            return;
        }
        g_relay_state = state;
        log_event(state ? "Relay activated" : "Relay deactivated");
