 *
 * Wiring:
 *   Si7210 SDA  -> GPIO 2 (I2C bus 1 SDA, pin 3)
 *   Si7210 SCL  -> GPIO 3 (I2C bus 1 SCL, pin 5)
 *   Si7210 VDD  -> 3.3 V
 *   Si7210 GND  -> GND
 *   Relay IN    -> GPIO 17 (BCM, active high)
 *   Relay VCC   -> 5 V (external supply recommended)
 *   Relay GND   -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si7210_monitor si7210_monitor.c -lsi7210
 *
 * Run:
 *   sudo ./si7210_monitor
 */

