/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define SI7210_ADDR         0x48          /* Si7210 default I2C address (ADDR pin tied to GND) */
#define RELAY_GPIO          17            /* BCM GPIO 17 */
#define FIELD_THRESHOLD_MT  5.0f          /* mT */
#define SAMPLE_PERIOD_US    100000        /* 100 ms */
#define REG_POLL_TIMEOUT    50            /* 50 × 100 ms = 5 s */
#define LOG_FILE            "magnetic_events.txt"

/* Si7210 register addresses (from datasheet) */
#define SI7210_REG_DEVICE_ID       0x00
#define SI7210_REG_DEVICE_ID_VAL   0x10
#define SI7210_REG_MEAS_CFG        0x01
#define SI7210_REG_MEAS_CFG_VAL    0x01   /* Start continuous measurement */
#define SI7210_REG_DATA_READY      0x02
#define SI7210_REG_DATA_READY_VAL  0x01
#define SI7210_REG_DATA_LSB        0x03
#define SI7210_REG_DATA_MSB        0x04

