static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *msg)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (g_log_file) {
        fprintf(g_log_file, "%s: %s\n", ts, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

/* ------------------------------- I2C ------------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, SI7210_ADDR, strerror(errno));
        return -1;
    }

    /* Verify device identity */
    int id = i2cReadByteData(g_i2c_handle, SI7210_REG_DEVICE_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read DEVICE_ID register: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    if (id != SI7210_REG_DEVICE_ID_VAL) {
        fprintf(stderr, "Unexpected DEVICE_ID: 0x%02X (expected 0x%02X)\n",
                id, SI7210_REG_DEVICE_ID_VAL);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Start continuous measurement */
    if (i2cWriteByteData(g_i2c_handle, SI7210_REG_MEAS_CFG, SI7210_REG_MEAS_CFG_VAL) < 0) {
        fprintf(stderr, "Failed to write MEAS_CFG register: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

