    return 0;
}

/* ----------------------------- Read field -------------------------------- */
static int read_field(float *field_mt)
{
    int ready = 0;
    int poll_count = 0;

    /* Poll DATA_READY bit until it reads 1 (data ready) or timeout */
    while (poll_count < REG_POLL_TIMEOUT) {
        ready = i2cReadByteData(g_i2c_handle, SI7210_REG_DATA_READY);
