        fprintf(stderr, "i2cReadByteData(DATA_LSB) failed: %s\n", strerror(errno));
        return -1;
    }

    int msb = i2cReadByteData(g_i2c_handle, SI7210_REG_DATA_MSB);
    if (msb < 0) {
        fprintf(stderr, "i2cReadByteData(DATA_MSB) failed: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((msb << 8) | lsb);

    /* Convert raw ADC count to mT (per Si7210 datasheet: 1 LSB = 0.000122 mT) */
    *field_mt = (float)raw * 0.000122f;

    /* Clear DATA_READY bit to allow next conversion */
    if (i2cWriteByteData(g_i2c_handle, SI7210_REG_DATA_READY, 0) < 0) {
        fprintf(stderr, "Warning: failed to clear DATA_READY: %s\n", strerror(errno));
        /* Non-fatal: continue monitoring */
    }

    return 0;
}

/* ----------------------------- Relay control ----------------------------- */
static void control_relay(int state)
{
    if (state != g_relay_state) {
        if (gpioWrite(RELAY_GPIO, state) < 0) {
            fprintf(stderr, "gpioWrite(%d, %d) failed\n", RELAY_GPIO, state);
            return;
        }
