#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

static int set_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        log_event("ERROR: Failed to write to GPIO");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (server_fd != -1) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_relay(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket failed");
        cleanup();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Relay control server listening on port %d\n", PORT);
    log_event("Server started");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int new_socket = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (new_socket < 0) {
            if (errno == EINTR && !running) break;
            perror("accept failed");
            continue;
        }

        char buffer[BUFFER_SIZE];
        ssize_t valread = read(new_socket, buffer, BUFFER_SIZE - 1);
        if (valread < 0) {
            perror("read failed");
            close(new_socket);
            continue;
        }
        if (valread == 0) {
            close(new_socket);
            continue;
        }

        buffer[valread] = '\0';
        char *cmd = strtok(buffer, " \r\n");
        if (!cmd) {
            close(new_socket);
            continue;
        }

        int relay_state = -1;
        if (strcmp(cmd, "ON") == 0) {
            relay_state = 1;
        } else if (strcmp(cmd, "OFF") == 0) {
            relay_state = 0;
        }

        if (relay_state != -1) {
            if (set_relay(relay_state) == 0) {
                char log_msg[128];
                snprintf(log_msg, sizeof(log_msg), "Relay set to %s", relay_state ? "ON" : "OFF");
                log_event(log_msg);
            }
        } else {
            log_event("Invalid command received");
        }

        close(new_socket);
    }

    set_relay(0);
    log_event("Server shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

