        char *cmd = strtok(buffer, " \r\n");
        if (!cmd) {
            close(new_socket);
            continue;
        }

        int relay_state = -1;
        if (strcmp(cmd, "ON") == 0) {
            relay_state = 1;
        } else if (strcmp(cmd, "OFF") == 0) {
            relay_state = 0;
        }

        if (relay_state != -1) {
            if (set_relay(relay_state) == 0) {
                char log_msg[128];
                snprintf(log_msg, sizeof(log_msg), "Relay set to %s", relay_state ? "ON" : "OFF");
                log_event(log_msg);
            }
        } else {
            log_event("Invalid command received");
        }

        close(new_socket);
    }

    set_relay(0);
    log_event("Server shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

