/*
 * Raspberry Pi Zero W – Dual SLF3S-1300F Liquid-Flow Monitor
 *
 * Wiring:
 *   Sensor 1 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   Sensor 1 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   Sensor 1 VDD -> 3.3 V
 *   Sensor 1 GND -> GND
 *   Sensor 2 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   Sensor 2 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   Sensor 2 VDD -> 3.3 V
 *   Sensor 2 GND -> GND
 *   Relay IN    -> GPIO 18 (BCM)
 *   Relay VCC   -> 5 V
 *   Relay GND   -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:   sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS             1
#define SENSOR1_ADDR        0x20
#define SENSOR2_ADDR        0x21
#define RELAY_GPIO          18
#define FLOW_THRESHOLD      5.0f
#define POLL_DELAY_US       100000   /* 100 ms */
#define LOG_FILE            "flow_log.txt"

/* SLF3S-1300F start-measurement command (two bytes, no register) */
static const uint8_t CMD_START_MEAS[2] = { 0x36, 0x2F };

/* CRC-8 parameters per Sensirion SLF3S-1300F datasheet */
#define CRC8_POLYNOMIAL     0x31
#define CRC8_INIT           0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion style: poly 0x31, init 0xFF, no final XOR)          */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLYNOMIAL);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and fills *flow_rate_ml_min.
 * Returns -1 on I2C error, -2 on CRC mismatch, -3 on short read.
 */
static int read_flow_rate(int handle, float *flow_rate_ml_min)
{
    uint8_t buf[3];
    int bytes_read;

    /* Send start-measurement command */
    if (i2cWriteDevice(handle, (char *)CMD_START_MEAS, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed on handle %d\n", handle);
        return -1;
    }

    /* Datasheet: conversion time ~45 ms; wait 50 ms to be safe */
    gpioDelay(50000);

    /* Read 3 bytes: MSB, LSB, CRC */
    bytes_read = i2cReadDevice(handle, (char *)buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d bytes (expected 3) on handle %d\n",
                bytes_read, handle);
        return -3;
    }

    /* Validate CRC */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on handle %d (calc=0x%02X recv=0x%02X)\n",
                handle, crc8(buf, 2), buf[2]);
        return -2;
    }

    /* Assemble 16-bit signed raw value (big-endian) */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);

    /* Convert to ml/min: raw / 100 */
    *flow_rate_ml_min = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static int control_relay(int gpio_pin, int state)
{
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, %d) failed\n", gpio_pin, state);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_flow_data(float flow1, float flow2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("[ERROR] clock_gettime");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            timestamp, ts.tv_nsec / 1000000L, flow1, flow2);
    fflush(fp);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioWrite(RELAY_GPIO, 0);   /* ensure relay is off */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C handles for both sensors */
    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);   /* start with relay off */

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction");
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");
    printf("  Sensor 1: I2C bus %d, addr 0x%02X\n", I2C_BUS, SENSOR1_ADDR);
    printf("  Sensor 2: I2C bus %d, addr 0x%02X\n", I2C_BUS, SENSOR2_ADDR);
    printf("  Relay:    GPIO %d (active-high)\n", RELAY_GPIO);
    printf("  Threshold: %.1f ml/min\n", FLOW_THRESHOLD);
    printf("  Log file:  %s\n", LOG_FILE);

    /* Main polling loop */
    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int rc1 = read_flow_rate(g_i2c_handle1, &flow1);
        int rc2 = read_flow_rate(g_i2c_handle2, &flow2);

        if (rc1 != 0 || rc2 != 0) {
            fprintf(stderr, "[WARN] Sensor read error (s1=%d s2=%d); skipping cycle\n", rc1, rc2);
        } else {
            log_flow_data(flow1, flow2);

            if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
                if (control_relay(RELAY_GPIO, 1) != 0) {
                    fprintf(stderr, "[WARN] Failed to energize relay\n");
                }
            } else {
                if (control_relay(RELAY_GPIO, 0) != 0) {
                    fprintf(stderr, "[WARN] Failed to de-energize relay\n");
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

