/*
 * Rain-activated window closer for Raspberry Pi 5
 *
 * Hardware:
 *   - Seeed Studio Rain Sensor v1.0  digital output -> GPIO 17 (BCM)
 *   - L298N driver:
 *       ENA -> GPIO 22 (BCM)
 *       IN1 -> GPIO 23 (BCM)
 *       IN2 -> GPIO 24 (BCM)
 *
 * The sensor DO pin is active-low: 0 = rain, 1 = dry.
 * A rising edge (dry -> wet) triggers a 5-second close-window sequence.
 *
 * Build:  gcc -O2 -Wall -Wextra -o rain_window rain_window.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN  17
#define MOTOR_ENA_PIN    22
#define MOTOR_IN1_PIN    23
#define MOTOR_IN2_PIN    24

#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_HOLD_US     5000000  /* 5 s   */
#define DRY_THRESHOLD     3        /* consecutive dry polls before re-arm */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
    if (priority == LOG_ERR)
        fprintf(stderr, "[ERROR] %s\n", msg);
}

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */
static int motor_set(struct gpiod_line *ena, struct gpiod_line *in1,
                     struct gpiod_line *in2, int ena_val, int in1_val,
                     int in2_val, const char *label)
{
    int rc = 0;

    if (gpiod_line_set_value(ena, ena_val) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "Failed to set %s ENA=%d: %s", label, ena_val, strerror(errno));
        log_event(LOG_ERR, buf);
        rc = -1;
    }
    if (gpiod_line_set_value(in1, in1_val) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "Failed to set %s IN1=%d: %s", label, in1_val, strerror(errno));
        log_event(LOG_ERR, buf);
        rc = -1;
    }
    if (gpiod_line_set_value(in2, in2_val) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "Failed to set %s IN2=%d: %s", label, in2_val, strerror(errno));
        log_event(LOG_ERR, buf);
        rc = -1;
    }
    return rc;
}

static int motor_stop(struct gpiod_line *ena, struct gpiod_line *in1,
                      struct gpiod_line *in2)
{
    return motor_set(ena, in1, in2, 0, 0, 0, "motor");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip,
                    struct gpiod_line *rain,
                    struct gpiod_line *ena,
                    struct gpiod_line *in1,
                    struct gpiod_line *in2)
{
    if (rain) gpiod_line_release(rain);
    if (ena)  gpiod_line_release(ena);
    if (in1)  gpiod_line_release(in1);
    if (in2)  gpiod_line_release(in2);
    if (chip) gpiod_chip_close(chip);
    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain = NULL, *ena = NULL, *in1 = NULL, *in2 = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Open syslog ---- */
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    log_event(LOG_INFO, "Rain-activated window closer starting");

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to open gpiochip4: %s", strerror(errno));
        log_event(LOG_ERR, buf);
        goto out;
    }

    /* ---- Get lines ---- */
    rain = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena  = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    in1  = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2  = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!rain || !ena || !in1 || !in2) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to get GPIO lines: %s", strerror(errno));
        log_event(LOG_ERR, buf);
        goto out;
    }

    /* ---- Request rain line as input with pull-up ---- */
    if (gpiod_line_request_input_flags(rain, "rain_window",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to request rain line: %s", strerror(errno));
        log_event(LOG_ERR, buf);
        goto out;
    }

