/*
 * Rain-activated window closer for Raspberry Pi 5
 *
 * Hardware:
 *   - Seeed Studio Rain Sensor v1.0  digital output -> GPIO 17 (BCM)
 *   - L298N driver:
 *       ENA -> GPIO 22 (BCM)
 *       IN1 -> GPIO 23 (BCM)
 *       IN2 -> GPIO 24 (BCM)
 *
 * The sensor DO pin is active-low: 0 = rain, 1 = dry.
 * A rising edge (dry -> wet) triggers a 5-second close-window sequence.
 *
 * Build:  gcc -O2 -Wall -Wextra -o rain_window rain_window.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN  17
#define MOTOR_ENA_PIN    22
#define MOTOR_IN1_PIN    23
#define MOTOR_IN2_PIN    24

#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_HOLD_US     5000000  /* 5 s   */
#define DRY_THRESHOLD     3        /* consecutive dry polls before re-arm */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
    if (priority == LOG_ERR)
        fprintf(stderr, "[ERROR] %s\n", msg);
}

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */
static int motor_set(struct gpiod_line *ena, struct gpiod_line *in1,
                     struct gpiod_line *in2, int ena_val, int in1_val,
                     int in2_val, const char *label)
{
    int rc = 0;

    if (gpiod_line_set_value(ena, ena_val) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "Failed to set %s ENA=%d: %s", label, ena_val, strerror(errno));
        log_event(LOG_ERR, buf);
        rc = -1;
    }
    if (gpiod_line_set_value(in1, in1_val) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "Failed to set %s IN1=%d: %s", label, in1_val, strerror(errno));
        log_event(LOG_ERR, buf);
        rc = -1;
    }
    if (gpiod_line_set_value(in2, in2_val) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "Failed to set %s IN2=%d: %s", label, in2_val, strerror(errno));
        log_event(LOG_ERR, buf);
        rc = -1;
    }
    return rc;
}

static int motor_stop(struct gpiod_line *ena, struct gpiod_line *in1,
                      struct gpiod_line *in2)
{
    return motor_set(ena, in1, in2, 0, 0, 0, "motor");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip,
                    struct gpiod_line *rain,
                    struct gpiod_line *ena,
                    struct gpiod_line *in1,
                    struct gpiod_line *in2)
{
    if (rain) gpiod_line_release(rain);
    if (ena)  gpiod_line_release(ena);
    if (in1)  gpiod_line_release(in1);
    if (in2)  gpiod_line_release(in2);
    if (chip) gpiod_chip_close(chip);
    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain = NULL, *ena = NULL, *in1 = NULL, *in2 = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Open syslog ---- */
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    log_event(LOG_INFO, "Rain-activated window closer starting");

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to open gpiochip4: %s", strerror(errno));
        log_event(LOG_ERR, buf);
        goto out;
    }

    /* ---- Get lines ---- */
    rain = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena  = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    in1  = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2  = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!rain || !ena || !in1 || !in2) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to get GPIO lines: %s", strerror(errno));
        log_event(LOG_ERR, buf);
        goto out;
    }

    /* ---- Request rain line as input with pull-up ---- */
    if (gpiod_line_request_input_flags(rain, "rain_window",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to request rain line: %s", strerror(errno));
        log_event(LOG_ERR, buf);
        goto out;
    }

    /* ---- Request motor lines as outputs, initial LOW ---- */
    if (gpiod_line_request_output(ena, "rain_window", 0) < 0 ||
        gpiod_line_request_output(in1, "rain_window", 0) < 0 ||
        gpiod_line_request_output(in2, "rain_window", 0) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to request motor lines: %s", strerror(errno));
        log_event(LOG_ERR, buf);
        goto out;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to install signal handlers: %s", strerror(errno));
        log_event(LOG_ERR, buf);
        goto out;
    }

    log_event(LOG_INFO, "Monitoring rain sensor on GPIO 17 (BCM)");

    int dry_count = 0;
    int last_rain = 1;   /* assume dry at startup (pull-up) */

    while (g_running) {
        int val = gpiod_line_get_value(rain);
        if (val < 0) {
            char buf[128];
            snprintf(buf, sizeof(buf), "Failed to read rain sensor: %s", strerror(errno));
            log_event(LOG_ERR, buf);
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* Rising edge: dry -> wet */
        if (val == 0 && last_rain == 1) {
            log_event(LOG_INFO, "Rain detected (rising edge)");

            if (motor_set(ena, in1, in2, 1, 1, 0, "motor") == 0) {
                log_event(LOG_INFO, "Motor started: ENA=1 IN1=1 IN2=0");

                /* Hold motor for 5 s, checking for shutdown every 100 ms */
                for (int i = 0; i < 50 && g_running; i++)
                    usleep(100000);

                if (motor_stop(ena, in1, in2) == 0)
                    log_event(LOG_INFO, "Motor stopped");
                else
                    log_event(LOG_WARNING, "Motor stop failed");
            } else {
                log_event(LOG_WARNING, "Motor start failed");
            }

            /* Reset dry-counter so we don't retrigger immediately */
            dry_count = 0;
        }

        last_rain = val;

        if (val == 1)
            dry_count++;
        else
            dry_count = 0;

        if (dry_count >= DRY_THRESHOLD) {
            log_event(LOG_INFO, "Sensor dry for >= 3 polls; re-arming");
            dry_count = 0;
        }

        usleep(POLL_INTERVAL_US);
    }

    log_event(LOG_INFO, "Shutting down");
    ret = EXIT_SUCCESS;

out:
    cleanup(chip, rain, ena, in1, in2);
    return ret;
}

