#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22
#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define DEBOUNCE_US    200000   /* 200 ms */
#define POLL_DELAY_US  10000    /* 10 ms  */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_call(unsigned gpio, unsigned pulse_us)
{
    if (gpioServo(gpio, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(%u, %u) failed\n", gpio, pulse_us);
        return -1;
    }
    return 0;
}

static void stop_servo(void)
{
    safe_call(SERVO_PIN, 0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", LOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", UNLOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", LOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", UNLOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_call(SERVO_PIN, 0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        stop_servo();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        stop_servo();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");
    printf("Lock button: GPIO %d | Unlock button: GPIO %d | Servo: GPIO %d\n",
           LOCK_BUTTON, UNLOCK_BUTTON, SERVO_PIN);

    while (g_running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Locking door...\n");
            if (safe_call(SERVO_PIN, LOCK_PULSE_US) < 0) {
                stop_servo();
                gpioTerminate();
                return EXIT_FAILURE;
            }
            gpioDelay(DEBOUNCE_US);
            while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                gpioDelay(POLL_DELAY_US);
            }
            gpioDelay(DEBOUNCE_US);
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlocking door...\n");
            if (safe_call(SERVO_PIN, UNLOCK_PULSE_US) < 0) {
                stop_servo();
                gpioTerminate();
                return EXIT_FAILURE;
            }
            gpioDelay(DEBOUNCE_US);
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                gpioDelay(POLL_DELAY_US);
            }
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    stop_servo();
    gpioDelay(50000);   /* 50 ms settle */
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

