#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define PIR_PIN      4
#define LED_PIN      17
#define LOG_FILE     "security_log.txt"
#define POLL_US      100000   /* 100 ms */
#define LED_ON_US    60000000 /* 60 s  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only sets flag                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append one line to the log file; returns 0 on success, -1 on error  */
/* ------------------------------------------------------------------ */
static int log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %s\n", ts, msg) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Turn the floodlight ON; returns 0 on success, -1 on error           */
/* ------------------------------------------------------------------ */
static int led_on(void)
{
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "gpioWrite(LED_PIN, 1) failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Turn the floodlight OFF; returns 0 on success, -1 on error          */
/* ------------------------------------------------------------------ */
static int led_off(void)
{
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(LED_PIN, 0) failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure pins ---- */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(PIR_PIN, PI_INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(LED_PIN, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure floodlight is OFF at start */
    if (led_off() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security system started. PIR=GPIO%d, LED=GPIO%d, log=%s\n",
           PIR_PIN, LED_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    int last_pir = gpioRead(PIR_PIN);
    if (last_pir < 0) {
        fprintf(stderr, "gpioRead(PIR_PIN) initial failed\n");
        led_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main polling loop ---- */
    while (g_running) {
        int pir = gpioRead(PIR_PIN);
        if (pir < 0) {
            fprintf(stderr, "gpioRead(PIR_PIN) failed\n");
            break;
        }

        if (pir == 1 && last_pir == 0) {
            /* Rising edge: motion detected */
            printf("Motion detected!\n");

            if (log_event("Motion detected") != 0) {
                fprintf(stderr, "Failed to log activation event\n");
            }

            if (led_on() != 0) {
                fprintf(stderr, "Failed to turn LED on\n");
                break;
            }

            /* Keep LED on for 60 s, checking for shutdown signal */
            uint32_t elapsed = 0;
            while (g_running && elapsed < LED_ON_US) {
                gpioDelay(POLL_US);
                elapsed += POLL_US;
            }

            if (led_off() != 0) {
                fprintf(stderr, "Failed to turn LED off\n");
                break;
            }

            if (log_event("Motion ended") != 0) {
                fprintf(stderr, "Failed to log deactivation event\n");
            }

            /* Brief cooldown to avoid re-triggering on same event */
            uint32_t cooldown = 0;
            while (g_running && cooldown < POLL_US) {
                gpioDelay(POLL_US);
                cooldown += POLL_US;
            }
        }

        last_pir = pir;
        gpioDelay(POLL_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    led_off();
    gpioTerminate();
    printf("Security system stopped.\n");
    return EXIT_SUCCESS;
}

