/*
 * MPR121 Capacitive Touch Relay Controller for Raspberry Pi 5
 *
 * Hardware:
 *   - MPR121 capacitive touch sensor on I2C bus 1, address 0x5A
 *   - Relay module on GPIO17 (BCM)
 *
 * Behavior:
 *   - Toggles relay on a fresh rising-edge touch of electrode 0.
 *   - 200 ms debounce on electrode 0.
 *   - Clean shutdown: relay OFF, I2C bus closed, resources released.
 *   - Robust error handling for every I2C call.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define MPR121_ADDR          0x5A
#define RELAY_GPIO           17
#define DEBOUNCE_MS          200
#define POLL_DELAY_US        10000   /* 10 ms */

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ECR            0x5E
#define MPR121_SOFTRESET      0x80
#define MPR121_MHDR           0x2B
#define MPR121_NHDR           0x2C
#define MPR121_NCLR           0x2D
#define MPR121_FDLR           0x2E
#define MPR121_MHDF           0x2F
#define MPR121_NHDF           0x30
#define MPR121_NCLF           0x31
#define MPR121_FDLF           0x32
#define MPR121_NHDT           0x33
#define MPR121_NCLT           0x34
#define MPR121_FDLT           0x35
#define MPR121_E0TTH          0x41
#define MPR121_E0RTH          0x42
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_AUTOCONFIG0    0x7B
#define MPR121_AUTOCONFIG1    0x7C
#define MPR121_USL            0x7D
#define MPR121_LSL            0x7E
#define MPR121_TL             0x7F

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  mpr121_write_reg(uint8_t reg, uint8_t value);
static int  mpr121_read_reg(uint8_t reg, uint8_t *value);
static int  mpr121_init(void);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers -------------------------------- */
static int mpr121_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n",
                reg, value, rc);
    }
    return rc;
}

static int mpr121_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* --------------------------- MPR121 init -------------------------------- */
static int mpr121_init(void)
{
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(1000); /* 1 ms settle */

    /* Baseline filtering (rising) */
    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) < 0) return -1;

    /* Baseline filtering (falling) */
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;

    /* Touch / release thresholds for electrode 0 */
    if (mpr121_write_reg(MPR121_E0TTH, 0x0C) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0RTH, 0x0A) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=6 samples, CDC=16 µA, CDT=0.5 µs */
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;

    /* SFI=4 samples, ESI=4 ms */
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Auto-config: enable, 16 µA charge current, 0.5 µs charge time */
    if (mpr121_write_reg(MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTOCONFIG1, 0x00) < 0) return -1;

    /* Upper/lower/target limits for auto-config */
    if (mpr121_write_reg(MPR121_USL, 200) < 0) return -1;
    if (mpr121_write_reg(MPR121_LSL, 130) < 0) return -1;
    if (mpr121_write_reg(MPR121_TL,  180) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write_reg(MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure relay is OFF */
    if (g_i2c_handle >= 0) {
        gpioWrite(RELAY_GPIO, 0);
    }

    /* Close I2C bus */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0); /* Relay OFF at startup */

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay controller running. Touch electrode 0 to toggle relay.\n");
    printf("Press Ctrl+C to exit.\n");

    bool relay_state = false;
    uint32_t last_touch_tick = 0;

    while (g_running) {
        uint8_t touch_status_l = 0;
        uint8_t touch_status_h = 0;

        if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &touch_status_l) < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }
        if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &touch_status_h) < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint16_t touch_status = ((uint16_t)touch_status_h << 8) | touch_status_l;

        if (touch_status & (1 << 0)) {
            uint32_t now = gpioTick();
            if (now - last_touch_tick > DEBOUNCE_MS * 1000) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state ? 1 : 0);
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
                last_touch_tick = now;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

