 * Run:    sudo ./servo_pir
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdarg.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <pigpio.h>

#define SERVO_PIN          17
#define PIR_PIN            4
#define TCP_PORT           5000
#define LOG_FILE           "security.log"
#define SERVO_MIN_PULSE_US 1000   /* 1 ms  -> 0 degrees   */
#define SERVO_MAX_PULSE_US 2000   /* 2 ms  -> 180 degrees */
#define SERVO_FREQ_HZ      50
#define SERVO_RANGE_US     20000  /* 20 ms period          */
#define PWM_DUTY_MAX       1000000
#define PWM_DUTY_MIN       0
#define BUFFER_SIZE        1024
#define POLL_TIMEOUT_MS    1000

static volatile sig_atomic_t g_running = 1;
static int  g_sockfd = -1;
static FILE *g_logfp = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_msg(int priority, const char *fmt, ...)
{
    va_list ap;
    char ts[32];
    time_t now = time(NULL);

    if (now == (time_t)-1) {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    } else {
        struct tm tmv;
        if (localtime_r(&now, &tmv) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
        } else {
            snprintf(ts, sizeof(ts), "UNKNOWN");
        }
    }

    va_start(ap, fmt);
    syslog(priority, "[%s] %s", ts, fmt);
    va_end(ap);

    if (g_logfp) {
        va_start(ap, fmt);
        fprintf(g_logfp, "[%s] %s\n", ts, fmt);
        fflush(g_logfp);
        va_end(ap);
    }
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                       */
/* ------------------------------------------------------------------ */

static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        log_msg(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        log_msg(LOG_ERR, "Failed to set SERVO_PIN %d as output", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        log_msg(LOG_ERR, "Failed to set PIR_PIN %d as input", PIR_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure servo is off before we start PWM */
    if (gpioPWM(SERVO_PIN, 0) != 0) {
        log_msg(LOG_ERR, "Failed to initialise PWM on SERVO_PIN %d", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void gpio_cleanup(void)
{
    /* Stop PWM and release the pin */
    gpioPWM(SERVO_PIN, 0);
    gpioSetMode(SERVO_PIN, PI_INPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioTerminate();
}

/*
 * Generate a software PWM pulse on SERVO_PIN.
 * pigpio's gpioPWM() drives a hardware PWM channel, but we use a
 * software-timed loop to approximate a 50 Hz servo signal.
 *
 * pulse_us: pulse width in microseconds (1000–2000 for 0–180 degrees)
 * Returns 0 on success, -1 on error.
 */
static int servo_set_angle(int pulse_us)
{
    if (pulse_us < SERVO_MIN_PULSE_US || pulse_us > SERVO_MAX_PULSE_US) {
        log_msg(LOG_ERR, "Invalid pulse width %d us (must be %d–%d)",
                pulse_us, SERVO_MIN_PULSE_US, SERVO_MAX_PULSE_US);
        return -1;
    }

    /*
     * pigpio's gpioDelay() is a busy-wait that sleeps for the given
     * microseconds.  We use it to generate a 50 Hz servo waveform.
     *
     * 20 ms period  -> 50 Hz
     * 1000 us pulse -> 0 degrees
     * 2000 us pulse -> 180 degrees
     */
    int on_us  = pulse_us;
    int off_us = SERVO_RANGE_US - pulse_us;

    if (gpioWrite(SERVO_PIN, 1) != 0) {
        log_msg(LOG_ERR, "Failed to set SERVO_PIN high");
        return -1;
    }
    gpioDelay(on_us);

    if (gpioWrite(SERVO_PIN, 0) != 0) {
        log_msg(LOG_ERR, "Failed to set SERVO_PIN low");
        return -1;
    }
    gpioDelay(off_us);

    return 0;
}

/* ------------------------------------------------------------------ */
/* TCP socket                                                         */
/* ------------------------------------------------------------------ */

static int tcp_init(void)
{
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        log_msg(LOG_ERR, "socket() failed: %s", strerror(errno));
        return -1;
    }

    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_msg(LOG_ERR, "setsockopt(SO_REUSEADDR) failed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family      = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port        = htons(TCP_PORT);

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_msg(LOG_ERR, "bind() failed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    if (listen(fd, 3) < 0) {
        log_msg(LOG_ERR, "listen() failed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    log_msg(LOG_INFO, "Listening on TCP port %d", TCP_PORT);
    return fd;
}

static void tcp_cleanup(int fd)
{
    if (fd >= 0) {
        close(fd);
    }
}

/* ------------------------------------------------------------------ */
/* Command parsing                                                    */
/* ------------------------------------------------------------------ */

static void handle_command(const char *cmd)
{
    char buf[BUFFER_SIZE];

    if (strncmp(cmd, "the library's API call ", 22) == 0) {
        char *endptr = NULL;
        long angle = strtol(cmd + 22, &endptr, 10);

        if (endptr == cmd + 22) {
            log_msg(LOG_WARNING, "Invalid angle format: %s", cmd);
            snprintf(buf, sizeof(buf), "Invalid angle format\n");
            send(g_sockfd, buf, strlen(buf), MSG_NOSIGNAL);
            return;
        }

        if (angle < 0 || angle > 180) {
            log_msg(LOG_WARNING, "Angle %ld out of range (0–180)", angle);
            snprintf(buf, sizeof(buf), "Angle out of range (0–180)\n");
            send(g_sockfd, buf, strlen(buf), MSG_NOSIGNAL);
            return;
        }

        int pulse_us = SERVO_MIN_PULSE_US +
                       (int)((long)angle * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) / 180);

        if (servo_set_angle(pulse_us) == 0) {
            log_msg(LOG_INFO, "Servo angle set to %ld degrees (%d us)", angle, pulse_us);
            snprintf(buf, sizeof(buf), "Servo angle set to %ld degrees\n", angle);
            send(g_sockfd, buf, strlen(buf), MSG_NOSIGNAL);
        } else {
            log_msg(LOG_ERR, "Failed to set servo angle");
            snprintf(buf, sizeof(buf), "Failed to set servo angle\n");
            send(g_sockfd, buf, strlen(buf), MSG_NOSIGNAL);
        }
    } else if (strcmp(cmd, "PIR") == 0) {
        int pir = gpioRead(PIR_PIN);
        if (pir < 0) {
            log_msg(LOG_ERR, "Failed to read PIR_PIN %d", PIR_PIN);
            snprintf(buf, sizeof(buf), "PIR:ERROR\n");
            send(g_sockfd, buf, strlen(buf), MSG_NOSIGNAL);
        } else {
            log_msg(LOG_INFO, "PIR sensor reading: %d", pir);
            snprintf(buf, sizeof(buf), "PIR:%d\n", pir);
            send(g_sockfd, buf, strlen(buf), MSG_NOSIGNAL);
        }
    } else {
        log_msg(LOG_WARNING, "Unknown command: %s", cmd);
        snprintf(buf, sizeof(buf), "Unknown command\n");
        send(g_sockfd, buf, strlen(buf), MSG_NOSIGNAL);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    openlog("servo_pir", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_msg(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_msg(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    g_logfp = fopen(LOG_FILE, "a");
    if (!g_logfp) {
        log_msg(LOG_ERR, "Failed to open log file %s: %s", LOG_FILE, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        log_msg(LOG_ERR, "GPIO initialisation failed, exiting");
        fclose(g_logfp);
        closelog();
        return EXIT_FAILURE;
    }

    g_sockfd = tcp_init();
    if (g_sockfd < 0) {
        gpio_cleanup();
        fclose(g_logfp);
        closelog();
        return EXIT_FAILURE;
    }

    log_msg(LOG_INFO, "Servo + PIR controller started");

    while (g_running) {
        struct sockaddr_in caddr;
        socklen_t clen = sizeof(caddr);
        int cfd = accept(g_sockfd, (struct sockaddr *)&caddr, &clen);

        if (cfd < 0) {
            if (errno == EINTR) {
                continue;
            }
            log_msg(LOG_ERR, "accept() failed: %s", strerror(errno));
            continue;
        }

        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &caddr.sin_addr, ip, sizeof(ip));
        log_msg(LOG_INFO, "Connection from %s:%d", ip, ntohs(caddr.sin_port));

        char buf[BUFFER_SIZE];
        ssize_t n;

        while ((n = recv(cfd, buf, sizeof(buf) - 1, 0)) > 0) {
            buf[n] = '\0';

            /* Strip trailing newline/CR */
            for (ssize_t i = n - 1; i >= 0 && (buf[i] == '\n' || buf[i] == '\r'); i--) {
                buf[i] = '\0';
            }

            if (buf[0] != '\0') {
                log_msg(LOG_INFO, "Received command: %s", buf);
                handle_command(buf);
            }
        }

        if (n < 0) {
            log_msg(LOG_ERR, "recv() failed: %s", strerror(errno));
        } else {
            log_msg(LOG_INFO, "Client disconnected");
        }

        close(cfd);
    }

    log_msg(LOG_INFO, "Shutting down");
    tcp_cleanup(g_sockfd);
    gpio_cleanup();

    if (g_logfp) {
        fclose(g_logfp);
    }
    closelog();

    return EXIT_SUCCESS;
}

