/*
 * grow_light.c — Raspberry Pi 3 Model B+
 *
 * Reads ambient light from a BH1750 on I2C1 (GPIO2=SDA, GPIO3=SCL)
 * and drives a relay on GPIO23 (BCM) to activate a grow light when
 * the lux reading falls below 150.  Logs timestamped lux readings
 * to grow_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o grow_light grow_light.c -lpigpio -lrt
 * Run:    sudo ./grow_light
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1          /* /dev/i2c-1 on RPi 3B+ */
#define BH1750_ADDR        0x23       /* ADDR pin tied to GND */
#define BH1750_PWR_ON      0x01       /* Power on */
#define BH1750_RESET       0x07       /* Reset */
#define BH1750_CONT_HIGH   0x10       /* Continuous high-res mode (~120 ms) */
#define BH1750_CONV_MS     120        /* Conversion time for high-res mode */

#define RELAY_GPIO         23         /* BCM 23 — grow light relay */
#define LUX_THRESHOLD      150.0f     /* Activate relay below this */
#define SAMPLE_PERIOD_S    2          /* Seconds between readings */
#define LOG_FILE           "grow_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_lux(float *lux_out);
static void control_relay(int on);
static void log_data(float lux);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C ------------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, BH1750_ADDR, strerror(errno));
        return -1;
    }

    /* Power on the sensor */
    if (i2cWriteByte(g_i2c_handle, BH1750_PWR_ON) < 0) {
        fprintf(stderr, "[ERROR] BH1750 power-on failed: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Reset the sensor to a known state */
    if (i2cWriteByte(g_i2c_handle, BH1750_RESET) < 0) {
        fprintf(stderr, "[WARN] BH1750 reset failed: %s\n", strerror(errno));
    }

    /* Set continuous high-resolution mode */
    if (i2cWriteByte(g_i2c_handle, BH1750_CONT_HIGH) < 0) {
        fprintf(stderr, "[ERROR] BH1750 set mode failed: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------- GPIO ------------------------------------ */
static int init_gpio(void)
{
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, OUTPUT) failed: %s\n",
                RELAY_GPIO, strerror(errno));
        return -1;
    }
    control_relay(0);   /* Start with relay off */
    return 0;
}

/* ------------------------------- Read lux -------------------------------- */
static int read_lux(float *lux_out)
{
    char buf[2];
    int  rc;

    /* Trigger a single measurement */
    rc = i2cWriteByte(g_i2c_handle, BH1750_CONT_HIGH);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] BH1750 trigger failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(BH1750_CONV_MS * 1000);   /* microseconds */

    /* Read 2 bytes of raw data */
    rc = i2cReadDevice(g_i2c_handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[ERROR] BH1750 read failed (rc=%d): %s\n",
                rc, rc < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ----------------------------- Relay control ----------------------------- */
static void control_relay(int on)
{
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed: %s\n",
                RELAY_GPIO, on, strerror(errno));
    }
}

/* ------------------------------- Logging ---------------------------------- */
static void log_data(float lux)
{
    time_t     t;
    struct tm  tm_info;
    char       ts[32];

    t = time(NULL);
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[WARN] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[WARN] strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s, Lux: %.2f\n", ts, lux) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[WARN] fflush log failed: %s\n", strerror(errno));
    }
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    control_relay(0);

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "[FATAL] I2C initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() != 0) {
        fprintf(stderr, "[FATAL] GPIO initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Grow light controller started.  Sampling every %d s.  Ctrl+C to exit.\n",
           SAMPLE_PERIOD_S);

    /* Main loop */
    while (g_running) {
        float lux;

        if (read_lux(&lux) == 0) {
            log_data(lux);

            if (lux < LUX_THRESHOLD) {
                control_relay(1);
                printf("[INFO] Lux %.2f < %.1f — grow light ON\n", lux, LUX_THRESHOLD);
            } else {
                control_relay(0);
                printf("[INFO] Lux %.2f >= %.1f — grow light OFF\n", lux, LUX_THRESHOLD);
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed — will retry next cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            gpioDelay(100000);   /* 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

