/*
 * weight_monitor.c — Raspberry Pi 3 Model B+
 *
 * Monitors a TAL220B load cell via an HX711 amplifier on a bit-banged GPIO
 * bus (DOUT=GPIO23, SCK=GPIO24), drives a solenoid lock on GPIO25, and
 * triggers the lock when the measured weight exceeds a threshold.
 *
 * Build:  gcc -O2 -Wall -Wextra -o weight_monitor weight_monitor.c -lgpiod
 * Run:    sudo ./weight_monitor [--scale <factor>] [--duration <ms>]
 *                            [--threshold <grams>]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <getopt.h>
#include <gpiod.h>

/* ----------------------------- Configuration ----------------------------- */
#define HX711_DOUT_PIN    23          /* GPIO23, physical pin 16 */
#define HX711_SCK_PIN     24          /* GPIO24, physical pin 18 */
#define SOLENOID_PIN      25          /* GPIO25, physical pin 22 */

#define DEFAULT_SCALE_FACTOR   1.0f
#define DEFAULT_THRESHOLD_GRAMS 1000.0f
#define DEFAULT_DURATION_MS     200
#define DEFAULT_POLLING_MS      500
#define DEFAULT_NUM_READINGS    5
#define DEFAULT_MAX_RETRIES     3

#define HX711_SETTLE_US   1000        /* DOUT settles after power-up */
#define HX711_READY_TIMEOUT_US 1000000 /* 1 s timeout waiting for DOUT LOW */
#define HX711_CLOCK_HALF_US  1        /* 1 us half-period */
#define HX711_TARE_SAMPLES  10
#define HX711_READ_SAMPLES  5

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static float g_scale_factor = DEFAULT_SCALE_FACTOR;
static float g_threshold_grams = DEFAULT_THRESHOLD_GRAMS;
static int   g_duration_ms = DEFAULT_DURATION_MS;
static int   g_polling_ms = DEFAULT_POLLING_MS;
static int   g_num_readings = DEFAULT_NUM_READINGS;
static int   g_max_retries = DEFAULT_MAX_RETRIES;

static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_dout = NULL;
static struct gpiod_line  *g_sck  = NULL;
static struct gpiod_line  *g_sol  = NULL;

/* --------------------------- Function prototypes ------------------------- */
static void signal_handler(int sig);
static int  parse_arguments(int argc, char *argv[]);
static int  init_gpio(void);
static void cleanup_gpio(void);
static int  read_hx711(int32_t *out);
static int  tare_hx711(int32_t *offset);
static float calculate_weight(int32_t raw, int32_t offset);
static void activate_solenoid(void);
static void deactivate_solenoid(void);
static void log_message(int priority, const char *msg);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ Argument parser --------------------------- */
static int parse_arguments(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "s:t:d:p:n:r:h")) != -1) {
        switch (opt) {
        case 's': g_scale_factor = (float)atof(optarg); break;
        case 't': g_threshold_grams = (float)atof(optarg); break;
        case 'd': g_duration_ms = atoi(optarg); break;
        case 'p': g_polling_ms = atoi(optarg); break;
        case 'n': g_num_readings = atoi(optarg); break;
        case 'r': g_max_retries = atoi(optarg); break;
        case 'h':
        default:
            fprintf(stderr,
                    "Usage: %s [-s scale] [-t threshold_g] [-d duration_ms]\n"
                    "            [-p polling_ms] [-n num_readings] [-r max_retries]\n",
                    argv[0]);
            return EXIT_FAILURE;
        }
    }
    return EXIT_SUCCESS;
}

/* ------------------------------- GPIO init -------------------------------- */
static int init_gpio(void)
{
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        return -1;
    }

    g_dout = gpiod_chip_get_line(g_chip, HX711_DOUT_PIN);
    g_sck  = gpiod_chip_get_line(g_chip, HX711_SCK_PIN);
    g_sol  = gpiod_chip_get_line(g_chip, SOLENOID_PIN);
    if (!g_dout || !g_sck || !g_sol) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(g_dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(g_sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(g_sol, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- GPIO cleanup ------------------------------- */
static void cleanup_gpio(void)
{
    if (g_sol) {
        gpiod_line_set_value(g_sol, 0);
        gpiod_line_release(g_sol);
        g_sol = NULL;
    }
    if (g_sck) {
        gpiod_line_set_value(g_sck, 0);
        gpiod_line_release(g_sck);
        g_sck = NULL;
    }
    if (g_dout) {
        gpiod_line_release(g_dout);
        g_dout = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------ HX711 read -------------------------------- */
/*
 * Read a 24-bit two's-complement value from the HX711.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 *
 * The HX711 data-ready signal (DOUT) is active LOW.  We wait up to
 * HX711_READY_TIMEOUT_US for DOUT to go LOW, then clock out 24 bits
 * MSB-first, followed by one extra clock pulse to select Channel A gain 128.
 */
static int read_hx711(int32_t *out)
{
    if (!out) return -1;

    /* Wait for DOUT to go LOW (data ready). */
    for (int i = 0; i < HX711_READY_TIMEOUT_US; i++) {
        int val = gpiod_line_get_value(g_dout);
        if (val < 0) {
            syslog(LOG_ERR, "HX711 DOUT read error: %s", strerror(errno));
            return -1;
        }
        if (val == 0) break;
        usleep(1);
    }
    if (gpiod_line_get_value(g_dout) != 0) {
        syslog(LOG_ERR, "HX711 DOUT timeout (sensor not ready)");
        return -1;
    }

    uint32_t raw = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(g_sck, 1) < 0) {
            syslog(LOG_ERR, "HX711 SCK high error: %s", strerror(errno));
            return -1;
        }
        usleep(HX711_CLOCK_HALF_US);

        raw <<= 1;
        int bit = gpiod_line_get_value(g_dout);
        if (bit < 0) {
            syslog(LOG_ERR, "HX711 DOUT read error: %s", strerror(errno));
            return -1;
        }
        if (bit) raw |= 1u;

        if (gpiod_line_set_value(g_sck, 0) < 0) {
            syslog(LOG_ERR, "HX711 SCK low error: %s", strerror(errno));
            return -1;
        }
        usleep(HX711_CLOCK_HALF_US);
    }

    /* 25th clock pulse: Channel A, gain 128. */
    if (gpiod_line_set_value(g_sck, 1) < 0) {
        syslog(LOG_ERR, "HX711 25th SCK high error: %s", strerror(errno));
        return -1;
    }
    usleep(HX711_CLOCK_HALF_US);
    if (gpiod_line_set_value(g_sck, 0) < 0) {
        syslog(LOG_ERR, "HX711 25th SCK low error: %s", strerror(errno));
        return -1;
    }
