/*
 * relay_controller.c — Raspberry Pi 4 Model B
 *
 * Controls a relay module on GPIO17 (BCM 17, physical pin 11) via MQTT.
 * Subscribes to home/lights/control with QoS 0, drives GPIO17 HIGH for "ON"
 * and LOW for "OFF", logs events to syslog, and recovers from transient
 * MQTT errors.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *          -lpigpio -lmosquitto
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS   "localhost"
#define MQTT_BROKER_PORT      1883
#define MQTT_CLIENT_ID       "relay_controller_1"
#define MQTT_TOPIC           "home/lights/control"
#define MQTT_QOS             0
#define MQTT_KEEPALIVE       60
#define MQTT_CLEAN_SESSION   true

#define GPIO_PIN             17
#define GPIO_MODE            PI_OUTPUT
#define GPIO_INIT_STATE      0          /* relay OFF at startup */

#define RECONNECT_DELAY_SEC  5
#define LOOP_DELAY_US        100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int priority, const char *message)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

/* ------------------------------------------------------------------ */
/* GPIO                                                                */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, GPIO_MODE) != 0) {
        log_event(LOG_ERR, "Failed to set GPIO17 as output");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(GPIO_PIN, GPIO_INIT_STATE) != 0) {
        log_event(LOG_ERR, "Failed to initialise GPIO17 to LOW");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void gpio_cleanup(void)
{
    /* Ensure relay is OFF before terminating pigpio */
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;

    if (result == MOSQ_ERR_SUCCESS) {
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg),
                 "Connected to MQTT broker at %s:%d",
                 MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT);
        log_event(LOG_INFO, log_msg);

        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
        if (rc != MOSQ_ERR_SUCCESS) {
            snprintf(log_msg, sizeof(log_msg),
                     "Subscription to %s failed: %s",
                     MQTT_TOPIC, mosquitto_strerror(rc));
            log_event(LOG_ERR, log_msg);
        } else {
            snprintf(log_msg, sizeof(log_msg),
                     "Subscribed to %s (QoS %d)", MQTT_TOPIC, MQTT_QOS);
            log_event(LOG_INFO, log_msg);
        }
    } else {
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg),
                 "MQTT connect failed: %s", mosquitto_connack_string(result));
        log_event(LOG_ERR, log_msg);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;

    if (rc != 0) {
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg),
                 "Unexpected MQTT disconnect: %s",
                 mosquitto_strerror(rc));
        log_event(LOG_ERR, log_msg);
    } else {
        log_event(LOG_INFO, "Disconnected from MQTT broker");
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message == NULL || message->payload == NULL || message->payloadlen <= 0) {
        log_event(LOG_ERR, "Empty MQTT message received");
        return;
    }

    /* Ensure payload is NUL-terminated for safe string operations */
    char payload[32];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload)) {
        len = sizeof(payload) - 1;
    }
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    if (strcmp(payload, "ON") == 0) {
        if (gpioWrite(GPIO_PIN, 1) == 0) {
            log_event(LOG_INFO, "Relay ON (GPIO17 HIGH)");
        } else {
            log_event(LOG_ERR, "Failed to set GPIO17 HIGH");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpioWrite(GPIO_PIN, 0) == 0) {
            log_event(LOG_INFO, "Relay OFF (GPIO17 LOW)");
        } else {
            log_event(LOG_ERR, "Failed to set GPIO17 LOW");
        }
    } else {
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg),
                 "Invalid payload: '%s' (expected ON or OFF)", payload);
        log_event(LOG_ERR, log_msg);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT                                                                */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, MQTT_CLEAN_SESSION, NULL);
    if (g_mosq == NULL) {
        log_event(LOG_ERR, "Failed to create MQTT client");
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_BROKER_ADDRESS,
                              MQTT_BROKER_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg),
                 "MQTT connect failed: %s", mosquitto_strerror(rc));
        log_event(LOG_ERR, log_msg);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

static void mqtt_cleanup(void)
{
    if (g_mosq != NULL) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        return EXIT_FAILURE;
    }

    if (mqtt_init() != 0) {
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    log_event(LOG_INFO, "Relay controller started");

    while (g_running) {
        int rc = mosquitto_loop(g_mosq, -1, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            char log_msg[128];
            snprintf(log_msg, sizeof(log_msg),
                     "MQTT loop error: %s", mosquitto_strerror(rc));
            log_event(LOG_ERR, log_msg);

            /* Attempt to reconnect after delay */
            sleep(RECONNECT_DELAY_SEC);
            if (!g_running) {
                break;
            }

            rc = mosquitto_reconnect(g_mosq);
            if (rc != MOSQ_ERR_SUCCESS) {
                snprintf(log_msg, sizeof(log_msg),
                         "MQTT reconnect failed: %s", mosquitto_strerror(rc));
                log_event(LOG_ERR, log_msg);
            }
        }
        usleep(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    log_event(LOG_INFO, "Shutting down relay controller");
    gpio_cleanup();
    mqtt_cleanup();

    return EXIT_SUCCESS;
}

