code:
/*
 * Closed-loop DC motor speed control for a Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - DRV8833 H-bridge on GPIO 17 (IN1), GPIO 18 (IN2), GPIO 22 (IN3), GPIO 23 (IN4)
 *   - Quadrature encoders on GPIO 4 (A phase A), GPIO 5 (A phase B),
 *                           GPIO 6 (B phase A), GPIO 12 (B phase B)
 *
 * Build: gcc -O2 -Wall -Wextra -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdatomic.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM      17
#define MOTOR_A_DIR      18
#define MOTOR_B_PWM      22
#define MOTOR_B_DIR      23

#define ENCODER_A_A      4
#define ENCODER_A_B      5
#define ENCODER_B_A      6
#define ENCODER_B_B      12

/* ---- Motor parameters ---- */
#define PWM_FREQUENCY    10000   /* 10 kHz */
#define PWM_RANGE        255
#define TICKS_PER_REV    64      /* Quadrature encoder ticks per revolution */
#define STALL_TIMEOUT_S  2       /* Seconds without encoder ticks before warning */
#define TARGET_RPM       50.0f
#define LOOP_DELAY_US    100000  /* 100 ms control loop period */

/* ---- PI controller gains ---- */
#define KP  1.0f
#define KI  0.1f

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;

/* Encoder tick counters (atomic for ISR safety) */
static atomic_int g_enc_a = 0;
static atomic_int g_enc_b = 0;

/* Last encoder readings for stall detection */
static int g_enc_a_prev = 0;
static int g_enc_b_prev = 0;

/* Last control iteration time (microseconds) */
static uint32_t g_last_tick = 0;

/* ---- Function prototypes ---- */
static void signal_handler(int sig);
static int  initialize_gpio(void);
static void cleanup_gpio(void);
static void encoder_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  read_encoder(int a_pin, int b_pin);
static void set_motor_speed(int motor, int pwm_value);
static void stop_motors(void);
static float calculate_rpm(int encoder_value, uint32_t current_tick);
static float calculate_pid(float setpoint, float actual, float *integral, float *previous_error, float dt);
static void log_data(float rpm_a, float rpm_b, int pwm_a, int pwm_b);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- GPIO initialization ---- */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    /* Motor control pins */
    if (gpioSetMode(MOTOR_A_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set motor control pin modes.\n");
        return -1;
    }

    /* PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_A_PWM, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_PWM, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        return -1;
    }

    /* Encoder input pins */
    if (gpioSetMode(ENCODER_A_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_B, PI_INPUT)) {
        fprintf(stderr, "Error: failed to set encoder pin modes.\n");
        return -1;
    }

    /* Enable internal pull-ups on encoder inputs (quadrature encoders typically have open-collector outputs) */
    if (gpioSetPullUpDown(ENCODER_A_A, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_A_B, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_B_A, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_B_B, PI_PUD_UP)) {
        fprintf(stderr, "Error: failed to set pull-up resistors on encoder pins.\n");
        return -1;
    }

    /* Register ISR for encoder A (both edges) */
    if (gpioSetISRFuncEx(ENCODER_A_A, EITHER_EDGE, 0, encoder_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder A (GPIO %d).\n", ENCODER_A_A);
        return -1;
    }

    /* Register ISR for encoder B (both edges) */
    if (gpioSetISRFuncEx(ENCODER_B_A, EITHER_EDGE, 0, encoder_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder B (GPIO %d).\n", ENCODER_B_A);
        return -1;
    }

    return 0;
}

/* ---- Cleanup GPIO resources ---- */
static void cleanup_gpio(void)
{
    /* Stop motors */
    stop_motors();

    /* Disable ISRs */
    gpioSetISRFuncEx(ENCODER_A_A, EITHER_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENCODER_B_A, EITHER_EDGE, 0, NULL, NULL);

    /* Terminate pigpio */
    gpioTerminate();
}

/* ---- Encoder ISR callback ---- */
static void encoder_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)level;
    (void)tick;
    (void)userdata;

    if (gpio == ENCODER_A_A) {
        atomic_fetch_add(&g_enc_a, 1);
    } else if (gpio == ENCODER_B_A) {
        atomic_fetch_add(&g_enc_b, 1);
    }
}

/* ---- Read encoder value (single count per rising edge) ---- */
static int read_encoder(int a_pin, int b_pin)
{
    int a = gpioRead(a_pin);
    int b = gpioRead(b_pin);

    if (a < 0 || b < 0) {
        return 0; /* Return 0 on read error */
    }

    /* Quadrature decoding: A rising edge = +1, B rising edge = -1 */
    int count = 0;
    if (a == 1 && b == 0) {
        count = 1;
    } else if (a == 0 && b == 1) {
        count = -1;
    } else if (a == 1 && b == 1) {
        count = 0; /* Invalid state, ignore */
    } else if (a == 0 && b == 0) {
        count = 0; /* Invalid state, ignore */
    }

    return count;
}

/* ---- Set motor speed (PWM + direction) ---- */
static void set_motor_speed(int motor, int pwm_value)
{
    int pwm_pin, dir_pin;

    if (motor == 1) {
        pwm_pin = MOTOR_A_PWM;
        dir_pin = MOTOR_A_DIR;
    } else if (motor == 2) {
        pwm_pin = MOTOR_B_PWM;
        dir_pin = MOTOR_B_DIR;
    } else {
        fprintf(stderr, "Error: invalid motor number %d.\n", motor);
        return;
    }

    /* Clamp PWM value to valid range */
    if (pwm_value < 0) {
        pwm_value = 0;
    } else if (pwm_value > PWM_RANGE) {
        pwm_value = PWM_RANGE;
    }

    /* Set PWM duty cycle */
    if (gpioPWM(pwm_pin, pwm_value) < 0) {
        fprintf(stderr, "Error: failed to set PWM on pin %d.\n", pwm_pin);
        return;
    }

    /* Set direction: forward when PWM > 0, backward when PWM = 0 */
    if (pwm_value > 0) {
        if (gpioWrite(dir_pin, 1) < 0) {
            fprintf(stderr, "Error: failed to set direction on pin %d.\n", dir_pin);
        }
    } else {
        if (gpioWrite(dir_pin, 0) < 0) {
            fprintf(stderr, "Error: failed to set direction on pin %d.\n", dir_pin);
        }
    }
}

/* ---- Stop both motors ---- */
static void stop_motors(void)
{
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
}

/* ---- Calculate RPM from encoder ticks ---- */
static float calculate_rpm(int encoder_value, uint32_t current_tick)
{
    static uint32_t last_tick = 0;
    static int      last_value = 0;
    float dt;

    if (last_tick == 0) {
        last_tick = current_tick;
        last_value = encoder_value;
        return 0.0f;
    }

    dt = (float)(current_tick - last_tick) / 1000000.0f; /* Convert microseconds to seconds */
    if (dt <= 0.0f) {
        return 0.0f;
    }

    /* Calculate RPM: ticks per revolution * 60 seconds / (ticks per count * time elapsed) */
    float rpm = (float)encoder_value * 60.0f / (float)TICKS_PER_REV / dt;

    /* Handle encoder direction change (negative RPM indicates reverse) */
    if (encoder_value < last_value) {
        rpm = -rpm;
    }

    last_tick = current_tick;
    last_value = encoder_value;

    return rpm;
}

/* ---- Calculate PID output ---- */
static float calculate_pid(float setpoint, float actual, float *integral, float *previous_error, float dt)
{
    float error = setpoint - actual;

    /* Anti-windup: clamp integral term to prevent excessive accumulation */
    *integral += error * dt;
    if (*integral > 100.0f) {
        *integral = 100.0f;
    } else if (*integral < -100.0f) {
        *integral = -100.0f;
    }

    float derivative = (error - *previous_error) / dt;

    float output = KP * error + KI * (*integral) + KP * derivative;

    *previous_error = error;

    return output;
}

/* ---- Log data to console ---- */
static void log_data(float rpm_a, float rpm_b, int pwm_a, int pwm_b)
{
    printf("Motor A: RPM = %.2f, PWM = %d\n", rpm_a, pwm_a);
    printf("Motor B: RPM = %.2f, PWM = %d\n", rpm_b, pwm_b);
    fflush(stdout);
}

/* ---- Main ---- */
int main(void)
{
    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
