#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BH1750_ADDR             0x23
#define BH1750_CONTINUOUS_HIGH  0x10
#define RELAY_GPIO              17
#define DUSK_LUX                50.0f
#define DAWN_LUX                200.0f
#define POLL_INTERVAL_SEC       5
#define BH1750_CONV_TIME_MS     180
#define LOG_FILE_NAME           "chicken_coop_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s: %s\n", ts, msg);
    fflush(g_log_file);
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at addr 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gpio(void)
{
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n",
                RELAY_GPIO, strerror(errno));
        return -1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing GPIO %d to LOW: %s\n",
                RELAY_GPIO, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(float *lux_out)
{
    if (g_i2c_handle < 0) {
        log_message("Error: I2C handle invalid in read_bh1750");
        return -1;
    }

    char cmd = BH1750_CONTINUOUS_HIGH;
    if (i2cWriteDevice(g_i2c_handle, &cmd, 1) != 0) {
        log_message("Error writing BH1750 mode command");
        return -1;
    }

    gpioDelay(BH1750_CONV_TIME_MS * 1000);

    char buf[2];
    int n = i2cReadDevice(g_i2c_handle, buf, 2);
    if (n != 2) {
        log_message("Error reading BH1750 data (sensor absent or bus error)");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int on)
{
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) != 0) {
        log_message("Error writing relay GPIO");
        return;
    }
    log_message(on ? "Relay turned ON" : "Relay turned OFF");
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Program started");

    int relay_on = 0;

    while (g_running) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux = %.2f", lux);
            log_message(msg);

            if (lux < DUSK_LUX && !relay_on) {
                control_relay(1);
                relay_on = 1;
            } else if (lux > DAWN_LUX && relay_on) {
                control_relay(0);
                relay_on = 0;
            }
        } else {
            log_message("Sensor read failed; relay safe-off");
            if (relay_on) {
                control_relay(0);
                relay_on = 0;
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++)
            gpioDelay(1000000);
    }

    log_message("Shutting down");
    control_relay(0);
    cleanup();
    return EXIT_SUCCESS;
}

