#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define LOOP_DELAY_US 10000       /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_relay_state(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("[%s] Relay %s\n", timestamp, state ? "ON" : "OFF");
        fflush(stdout);
    }
}

int main(void)
{
    int relay_state = 0;
    int last_touch_state = 0;
    int first_touch = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise relay state to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_relay_state(0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read touch sensor on GPIO %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_state == 1) {
            if (first_touch || last_touch_state == 0) {
                gpioDelay(DEBOUNCE_DELAY_US);
                touch_state = gpioRead(TOUCH_SENSOR_PIN);
                if (touch_state < 0) {
                    fprintf(stderr, "Error: failed to read touch sensor during debounce\n");
                    break;
                }
                if (touch_state == 1) {
                    relay_state = !relay_state;
                    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                        fprintf(stderr, "Error: failed to write relay state\n");
                        break;
                    }
                    log_relay_state(relay_state);
                    first_touch = 0;
                }
            }
        } else {
            first_touch = 1;
        }

        last_touch_state = touch_state;
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

