/*
 * water_flow.c — Raspberry Pi 5 water-flow monitor with solenoid control.
 *
 * Build:  gcc -O2 -Wall -Wextra -o water_flow water_flow.c -lpigpio -lpthread
 * Run:    sudo ./water_flow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN      17          /* BCM 17, physical pin 11 */
#define SOLENOID_PIN         27          /* BCM 27, physical pin 13 */

#define FLOW_THRESHOLD_HIGH  5.0f        /* LPM — solenoid closes below this */
#define FLOW_THRESHOLD_LOW   4.5f        /* LPM — solenoid opens above this  */
#define DEBOUNCE_US          1000000     /* 1 second ISR debounce window    */
#define SAMPLE_INTERVAL_S    1           /* seconds between readings       */
#define LOG_FILE             "water_flow.log"

/* ------------------------------------------------------------------ */
/* Shared state                                                        */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static pthread_mutex_t       g_pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static FILE *g_log_fp = NULL;

static void log_event(const char *msg)
{
    if (!g_log_fp)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return;

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_fp, "%s: %s\n", ts, msg);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Flow sensor ISR                                                     */
/* ------------------------------------------------------------------ */

static uint32_t g_last_tick = 0;

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1)            /* only rising edges */
        return;

    uint32_t elapsed = tick - g_last_tick;   /* pigpio ticks are uint32_t; wraps correctly */
    if (elapsed < DEBOUNCE_US)
        return;

    g_last_tick = tick;

    if (pthread_mutex_lock(&g_pulse_mutex) != 0)
        return;

    g_pulse_count++;
    pthread_mutex_unlock(&g_pulse_mutex);
}

/* ------------------------------------------------------------------ */
/* Solenoid control                                                    */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_solenoid_state = 1;   /* 1 = open (safe) */

static int set_solenoid(int state)
{
    if (state != 0 && state != 1) {
        log_event("Invalid solenoid state requested");
        return -1;
    }

    if (gpioWrite(SOLENOID_PIN, state) != 0) {
        log_event("Failed to write solenoid pin");
        return -1;
    }

    g_solenoid_state = state;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Ensure solenoid is in a safe state before releasing resources */
    if (g_solenoid_state == 0)
        (void)gpioWrite(SOLENOID_PIN, 1);

    if (g_log_fp) {
        log_event("Program terminated");
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    pthread_mutex_destroy(&g_pulse_mutex);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set flow sensor pin %d as input.\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set solenoid pin %d as output.\n", SOLENOID_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with solenoid open (safe state) */
    if (set_solenoid(1) != 0) {
        fprintf(stderr, "Error: failed to initialise solenoid state.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ISR registration ---- */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on pin %d.\n", FLOW_SENSOR_PIN);
        set_solenoid(1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        set_solenoid(1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers.\n");
    }

    /* ---- Main loop ---- */
    while (g_running) {
        sleep(SAMPLE_INTERVAL_S);

        uint32_t pulses = 0;
        if (pthread_mutex_lock(&g_pulse_mutex) != 0) {
            log_event("Mutex lock failed in main loop");
            continue;
        }
        pulses = g_pulse_count;
        g_pulse_count = 0;
        pthread_mutex_unlock(&g_pulse_mutex);

        /* YF-S201: 1 pulse = 0.01 L */
        float lpm = (float)pulses / 60.0f;

        char msg[128];
        snprintf(msg, sizeof(msg), "Flow: %.2f LPM, Solenoid: %s",
                 lpm, g_solenoid_state ? "OPEN" : "CLOSED");
        log_event(msg);

        /* Hysteresis control */
        if (lpm > FLOW_THRESHOLD_HIGH && g_solenoid_state == 1) {
            if (set_solenoid(0) == 0)
                log_event("Solenoid closed (flow exceeded threshold)");
        } else if (lpm < FLOW_THRESHOLD_LOW && g_solenoid_state == 0) {
            if (set_solenoid(1) == 0)
                log_event("Solenoid opened (flow below threshold)");
        }
    }

    /* ---- Graceful shutdown ---- */
    cleanup();
    return EXIT_SUCCESS;
}

