                fprintf(stderr, "Warning: Invalid servo_min_pulse_width '%s'. Using default.\n", value);
                servo_min_pulse_width = DEFAULT_SERVO_MIN_PULSE_WIDTH;
            }
        } else if (strcmp(key, "servo_max_pulse_width") == 0) {
            servo_max_pulse_width = atoi(value);
