                stabilization_delay_ms = DEFAULT_STABILIZATION_DELAY_MS;
            }
        } else if (strcmp(key, "timeout_attempts") == 0) {
            timeout_attempts = atoi(value);
            if (timeout_attempts <= 0) {
                fprintf(stderr, "Warning: Invalid timeout_attempts '%s'. Using default.\n", value);
                timeout_attempts = DEFAULT_TIMEOUT_ATTEMPTS;
            }
        } else if (strcmp(key, "timeout_delay_us") == 0) {
            timeout_delay_us = atoi(value);
            if (timeout_delay_us <= 0) {
                fprintf(stderr, "Warning: Invalid timeout_delay_us '%s'. Using default.\n", value);
                timeout_delay_us = DEFAULT_TIMEOUT_DELAY_US;
            }
        }
    }

