        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);

        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection accepted from %s:%d\n", client_ip, ntohs(client_addr.sin_port));

        char buffer[1024];
        ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("recv");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        if (bytes_received == 0) {
            printf("Client disconnected.\n");
            close(client_fd);
            client_fd = -1;
            continue;
        }

        buffer[bytes_received] = '\0';
        printf("Received: %s\n", buffer);

        char *endptr;
        double target_weight = strtod(buffer, &endptr);
        if (endptr == buffer || *endptr != '\0') {
            fprintf(stderr, "Error: Invalid target weight format.\n");
            const char *err_msg = "Invalid target weight format.";
            log_dispensing_event(DEFAULT_TARGET_WEIGHT, 0.0, err_msg);
            send(client_fd, err_msg, strlen(err_msg), 0);
            close(client_fd);
            client_fd = -1;
            continue;
        }

        long raw_value;
        if (read_hx711(&raw_value) != 0) {
            fprintf(stderr, "Error: Failed to read HX711 sensor.\n");
            const char *err_msg = "Failed to read HX711 sensor.";
            log_dispensing_event(target_weight, 0.0, err_msg);
            send(client_fd, err_msg, strlen(err_msg), 0);
            close(client_fd);
            client_fd = -1;
            continue;
        }

        double actual_weight = calibrate_hx711(raw_value);
        printf("Raw: %ld, Calibrated: %.2f grams\n", raw_value, actual_weight);

        if (dispense_ingredient(target_weight) != 0) {
            fprintf(stderr, "Error: Failed to dispense ingredient.\n");
            const char *err_msg = "Failed to dispense ingredient.";
            log_dispensing_event(target_weight, actual_weight, err_msg);
            send(client_fd, err_msg, strlen(err_msg), 0);
            close(client_fd);
            client_fd = -1;
            continue;
        }

        char response[256];
        snprintf(response, sizeof(response), "%.2f", actual_weight);
        send(client_fd, response, strlen(response), 0);

        log_dispensing_event(target_weight, actual_weight, NULL);

        close(client_fd);
        client_fd = -1;
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

