/*
 * TTP223 capacitive touch sensor -> 5 V relay toggle on rising edge.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Library: gpiochip (libgpiod)
 *
 * Wiring:
 *   TTP223 VCC  -> 3.3 V (pin 1)
 *   TTP223 GND  -> GND   (pin 9)
 *   TTP223 OUT  -> GPIO4 (pin 7, BCM 4)
 *   Relay IN    -> GPIO17 (pin 11, BCM 17)
 *   Relay VCC   -> 5 V
 *   Relay GND   -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lgpiod
 *
 * Run:
 *   ./touch_relay [-d <milliseconds>]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TOUCH_PIN      4
#define RELAY_PIN      17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_INTERVAL_US  10000   /* 10 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_relay_state(int relay_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("%s Relay: %s\n", timestamp, relay_state ? "ON" : "OFF");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int debounce_ms = DEFAULT_DEBOUNCE_MS;
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
        case 'd':
            debounce_ms = atoi(optarg);
            if (debounce_ms <= 0) {
                fprintf(stderr, "Invalid debounce value: %s\n", optarg);
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3 B+) */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the touch sensor line */
    struct gpiod_line *touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (touch_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                TOUCH_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the relay line */
    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (relay_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the touch line as input */
    if (gpiod_line_request_input(touch_line, "touch_relay") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n",
                TOUCH_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the relay line as output, initial value LOW (relay OFF) */
    if (gpiod_line_request_output(relay_line, "touch_relay", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                RELAY_PIN, strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223 on GPIO %d, relay on GPIO %d. "
           "Debounce: %d ms. Press Ctrl+C to exit.\n",
           TOUCH_PIN, RELAY_PIN, debounce_ms);
    fflush(stdout);

    int relay_state = 0;
    int last_touch_state = 0;
    struct timespec last_change_time = {0, 0};

    while (g_running) {
        int touch_state = gpiod_line_get_value(touch_line);
        if (touch_state < 0) {
            fprintf(stderr, "Failed to read touch sensor: %s\n",
                    strerror(errno));
            break;
        }

        /* Detect rising edge: LOW -> HIGH */
        if (touch_state == 1 && last_touch_state == 0) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
                perror("clock_gettime");
                break;
            }

            long elapsed_ms =
                (now.tv_sec - last_change_time.tv_sec) * 1000L +
                (now.tv_nsec - last_change_time.tv_nsec) / 1000000L;

            if (elapsed_ms >= debounce_ms) {
                relay_state = !relay_state;
                if (gpiod_line_set_value(relay_line, relay_state) < 0) {
                    fprintf(stderr, "Failed to set relay: %s\n",
                            strerror(errno));
                    break;
                }
                log_relay_state(relay_state);
                last_change_time = now;
            }
        }

        last_touch_state = touch_state;
        usleep(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    if (relay_line != NULL) {
        gpiod_line_set_value(relay_line, 0);   /* ensure relay OFF */
        gpiod_line_release(relay_line);
    }
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

