/*
 * servo_adjust.c — Hobby servo angle adjustment on Raspberry Pi 4/5.
 *
 * Build:  gcc -O2 -Wall -Wextra -o servo_adjust servo_adjust.c -lpigpio -lrt
 * Run:    sudo ./servo_adjust
 *
 * Hardware:
 *   - SG90 hobby servo on GPIO18 (BCM 18, physical pin 12)
 *   - 5 V power supply (external, common ground with Pi)
 *
 * PWM:
 *   pigpio hardware PWM on GPIO18 at 50 Hz (20 ms period).
 *   Pulse width 500 us  -> 0 degrees
 *   Pulse width 1500 us -> 90 degrees
 *   Pulse width 2500 us -> 180 degrees
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN          18          /* BCM 18, physical pin 12 */
#define PWM_FREQUENCY      50          /* Hz */
#define PWM_RANGE          20000       /* 20 ms period */
#define MIN_PULSE_WIDTH    500         /* us at 0 degrees   */
#define MAX_PULSE_WIDTH    2500        /* us at 180 degrees */
#define INITIAL_ANGLE      90          /* degrees */
#define ANGLE_STEP         10          /* degrees per keystroke */
#define KEY_PLUS           '+'
#define KEY_MINUS          '-'
#define KEY_QUIT           'q'

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Terminal helpers                                                    */
/* ------------------------------------------------------------------ */
static int set_terminal_raw(void)
{
    struct termios tty;

    if (tcgetattr(STDIN_FILENO, &tty) != 0) {
        perror("tcgetattr");
        return -1;
    }

    tty.c_lflag &= ~(ICANON | ECHO);
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(STDIN_FILENO, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int restore_terminal(void)
{
    struct termios tty;

    if (tcgetattr(STDIN_FILENO, &tty) != 0) {
        perror("tcgetattr (restore)");
        return -1;
    }

    tty.c_lflag |= (ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &tty) != 0) {
        perror("tcsetattr (restore)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */
static int angle_to_pulse_width(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;
    return MIN_PULSE_WIDTH +
           (int)((long)angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180L);
}

static int set_servo_angle(int angle)
{
    int pw = angle_to_pulse_width(angle);

    if (gpioServo(SERVO_PIN, pw) != 0) {
        fprintf(stderr, "gpioServo failed for angle %d (pw=%d us): %s\n",
                angle, pw, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int angle = INITIAL_ANGLE;
    int pw    = angle_to_pulse_width(angle);

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO18 for hardware PWM ---- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d: %s\n",
                SERVO_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for pin %d: %s\n",
                SERVO_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(SERVO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed for pin %d: %s\n",
                SERVO_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with servo at initial angle */
    if (set_servo_angle(angle) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo control ready.  Angle: %3d°  Pulse: %4d us\n", angle, pw);
    printf("Press '+' to increase, '-' to decrease, 'q' to quit.\n");
    fflush(stdout);

    /* ---- Raw terminal mode ---- */
    if (set_terminal_raw() != 0) {
        gpioServo(SERVO_PIN, 0);   /* stop PWM */
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main loop: read one key at a time ---- */
    while (g_running) {
        int c = getchar();

        if (c == EOF) {
            /* Interrupted by signal — loop will exit via g_running */
            break;
        }

        switch (c) {
        case KEY_PLUS:
            angle += ANGLE_STEP;
            if (angle > 180) angle = 180;
            break;

        case KEY_MINUS:
            angle -= ANGLE_STEP;
            if (angle < 0)   angle = 0;
            break;

        case KEY_QUIT:
            g_running = 0;
            break;

        default:
            /* Ignore all other keys */
            continue;
        }

        if (!g_running)
            break;

        pw = angle_to_pulse_width(angle);

        if (set_servo_angle(angle) != 0) {
            /* Non-fatal: continue running, but report the error */
            fprintf(stderr, "Warning: failed to set servo angle %d\n", angle);
        }

        printf("Angle: %3d°  Pulse: %4d us\n", angle, pw);
        fflush(stdout);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");

    /* Stop PWM pulses */
    gpioServo(SERVO_PIN, 0);

    /* Restore terminal settings */
    restore_terminal();

    /* Release pigpio resources */
    gpioTerminate();

    printf("Done.\n");
    return EXIT_SUCCESS;
}

