    printf("Press '+' to increase, '-' to decrease, 'q' to quit.\n");
    fflush(stdout);

    /* ---- Raw terminal mode ---- */
    if (set_terminal_raw() != 0) {
        gpioServo(SERVO_PIN, 0);   /* stop PWM */
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main loop: read one key at a time ---- */
    while (g_running) {
        int c = getchar();

        if (c == EOF) {
            /* Interrupted by signal — loop will exit via g_running */
            break;
        }

        switch (c) {
        case KEY_PLUS:
