/*
 * Conveyor-belt RPM monitor using an A3144 Hall-effect sensor.
 *
 * Hardware:
 *   - Raspberry Pi 3 Model B+
 *   - A3144 Hall-effect sensor on GPIO 17 (BCM 17, physical pin 11)
 *   - Two-pole magnet mounted on the motor shaft
 *   - Internal pull-up enabled (sensor output is open-collector-style)
 *
 * Behavior:
 *   - Rising-edge detection on GPIO 17.
 *   - 2 ms debounce window to reject contact bounce and double-edge noise.
 *   - RPM computed every 5 seconds and logged to motor_rpm.log.
 *   - Clean shutdown on SIGINT / SIGTERM.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motor_rpm motor_rpm.c -lpigpio -lrt
 * Run:
 *   sudo ./motor_rpm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN            17
#define DEBOUNCE_US         2000          /* 2 ms debounce window            */
#define SAMPLE_INTERVAL_S   5             /* RPM logging interval            */
#define LOG_FILE            "motor_rpm.log"

/* ------------------------------------------------------------------ */
/* Shared state between the callback and the main loop                */
/* ------------------------------------------------------------------ */

typedef struct {
    volatile sig_atomic_t running;
    volatile uint32_t      last_tick;   /* pigpio tick of last accepted edge */
    volatile uint32_t      pulse_count; /* pulses since last sample        */
    FILE                 *log_fp;
} AppState;

static AppState g_state = {
    .running     = 1,
    .last_tick   = 0,
    .pulse_count = 0,
    .log_fp      = NULL,
};

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_state.running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio thread)                        */
/* ------------------------------------------------------------------ */

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1) {
        /* Only rising edges count */
        return;
    }

    /* Debounce: ignore edges within DEBOUNCE_US of the last accepted one */
    uint32_t elapsed = tick - g_state.last_tick;   /* pigpio ticks are uint32_t */
    if (elapsed < DEBOUNCE_US) {
        return;
    }
    g_state.last_tick = tick;

    /* Atomically increment the pulse counter */
    g_state.pulse_count++;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Compute the elapsed time between two pigpio ticks (uint32_t wraps
 * every ~71.6 min).  Returns the difference in microseconds.
 */
static uint32_t tick_diff_us(uint32_t start, uint32_t end)
{
    return end - start;   /* unsigned subtraction wraps correctly */
}

/*
 * Write a CSV line with an ISO-8601 timestamp and the current RPM.
 * Returns 0 on success, -1 on failure.
 */
static int log_rpm(FILE *fp, double rpm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO 17 as input with internal pull-up ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_state.log_fp = fopen(LOG_FILE, "a");
    if (g_state.log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(%d) failed\n", GPIO_PIN);
        fclose(g_state.log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring conveyor-belt RPM on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_PIN);

    /* ---- Main sampling loop ---- */
    while (g_state.running) {
        /* Sleep for the sample interval (interruptible by signals) */
        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_S, 0);
        if (!g_state.running) {
            break;
        }

        /* Atomically read and reset the pulse count */
        uint32_t pulses = g_state.pulse_count;
        g_state.pulse_count = 0;

        /* Compute elapsed time since the last sample */
        uint32_t elapsed_us = tick_diff_us(g_state.last_tick, gpioTick());

        /*
         * RPM = (pulses / revolutions) * (60 s / minute) *
         *       (1000000 us / second) / (elapsed_us / 1000000 us)
         *
         * With two-pole magnet on the shaft, one pulse = one revolution.
         */
        double rpm = (double)pulses * 60000000.0 / (double)elapsed_us;

        /* Print to stdout */
        printf("RPM: %.2f\n", rpm);

        /* Log to file */
        if (log_rpm(g_state.log_fp, rpm) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");

    /* Disable the alert callback */
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    /* Close log file */
    if (g_state.log_fp != NULL) {
        if (fclose(g_state.log_fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        g_state.log_fp = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

