#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_DELAY_US    50000   /* 50 ms */
#define HOLD_THRESHOLD_S 10      /* 10 s  */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_gpio_write(unsigned pin, unsigned level)
{
    int rc = gpioWrite(pin, level);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(pin=%u, level=%u) failed: %s\n",
                pin, level, pigpio_error(rc));
    }
    return rc;
}

int main(void)
{
    int rc;

    /* --- Install signal handlers early so cleanup works even if init fails --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "gpioInitialise() failed: %s\n", pigpio_error(rc));
        return EXIT_FAILURE;
    }

    /* --- Configure touch sensor pin as input --- */
    rc = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (rc < 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_SENSOR_PIN=%d) failed: %s\n",
                TOUCH_SENSOR_PIN, pigpio_error(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure relay pin as output and ensure it starts OFF --- */
    rc = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (rc < 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN=%d) failed: %s\n",
                RELAY_PIN, pigpio_error(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = safe_gpio_write(RELAY_PIN, 0);
    if (rc < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor relay control started.\n");
    printf("  Touch sensor : BCM GPIO%d\n", TOUCH_SENSOR_PIN);
    printf("  Relay        : BCM GPIO%d\n", RELAY_PIN);
    printf("  Poll interval: %d ms\n", POLL_DELAY_US / 1000);
    printf("  Hold timeout : %d s\n", HOLD_THRESHOLD_S);
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;
    int touch_active = 0;
    uint32_t touch_start_tick = 0;

    while (g_running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            fprintf(stderr, "gpioRead(TOUCH_SENSOR_PIN=%d) failed: %s\n",
                    TOUCH_SENSOR_PIN, pigpio_error(touch));
            break;
        }

        if (touch == 1) {
            if (!touch_active) {
                touch_active = 1;
                touch_start_tick = gpioTick();
            } else {
                uint32_t elapsed = gpioTick() - touch_start_tick;
                if (elapsed >= (uint32_t)(HOLD_THRESHOLD_S * 1000000)) {
                    printf("Touch held for %d s — forcing relay OFF.\n",
                           HOLD_THRESHOLD_S);
                    rc = safe_gpio_write(RELAY_PIN, 0);
                    if (rc < 0) {
                        break;
                    }
                    relay_state = 0;
                    touch_active = 0;
                    /* Wait for sensor release before re-arming */
                    while (g_running && gpioRead(TOUCH_SENSOR_PIN) == 1) {
                        gpioDelay(POLL_DELAY_US);
                    }
                    continue;
                }
            }
        } else {
            touch_active = 0;
        }

        if (touch == 1 && relay_state == 0) {
            relay_state = 1;
            rc = safe_gpio_write(RELAY_PIN, 1);
            if (rc < 0) {
                break;
            }
            printf("Touch detected — relay ON.\n");
        } else if (touch == 0 && relay_state == 1) {
            relay_state = 0;
            rc = safe_gpio_write(RELAY_PIN, 0);
            if (rc < 0) {
                break;
            }
            printf("Touch released — relay OFF.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    safe_gpio_write(RELAY_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

