            } else {
                uint32_t elapsed = gpioTick() - touch_start_tick;
                if (elapsed >= (uint32_t)(HOLD_THRESHOLD_S * 1000000)) {
                    printf("Touch held for %d s — forcing relay OFF.\n",
                           HOLD_THRESHOLD_S);
                    rc = safe_gpio_write(RELAY_PIN, 0);
                    if (rc < 0) {
                        break;
                    }
                    relay_state = 0;
                    touch_active = 0;
                    /* Wait for sensor release before re-arming */
                    while (g_running && gpioRead(TOUCH_SENSOR_PIN) == 1) {
                        gpioDelay(POLL_DELAY_US);
                    }
                    continue;
                }
            }
        } else {
            touch_active = 0;
        }

        if (touch == 1 && relay_state == 0) {
            relay_state = 1;
            rc = safe_gpio_write(RELAY_PIN, 1);
            if (rc < 0) {
                break;
            }
            printf("Touch detected — relay ON.\n");
        } else if (touch == 0 && relay_state == 1) {
            relay_state = 0;
            rc = safe_gpio_write(RELAY_PIN, 0);
            if (rc < 0) {
                break;
            }
            printf("Touch released — relay OFF.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    safe_gpio_write(RELAY_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

