/*
 * Closed-loop proportional solenoid valve flow control for Raspberry Pi 4.
 *
 * Hardware:
 *   - ASCO RedHat 8210 proportional solenoid valve (PWM-controlled)
 *       PWM signal  -> GPIO 18 (BCM, hardware PWM 0)
 *       Enable/Dir -> GPIO 23 (BCM, active-high)
 *   - YF-S201 flow sensor (digital output, 3.3 V logic)
 *       Signal     -> GPIO 24 (BCM, rising-edge interrupt)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_control flow_control.c -lpigpio -lrt
 * Run:
 *   ./flow_control -t <target_flow_rate_L_min>
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define VALVE_PWM_PIN          18          /* BCM 18 — hardware PWM 0 */
#define VALVE_ENABLE_PIN       23          /* BCM 23 — active-high enable */
#define FLOW_SENSOR_PIN        24          /* BCM 24 — rising-edge interrupt */

#define PWM_FREQUENCY          1000        /* Hz */
#define PWM_RANGE              255         /* 8-bit duty-cycle resolution */
#define SAMPLE_INTERVAL_US     100000      /* 100 ms */
#define LOG_FILE_NAME          "flow_log.csv"

#define KP                     1.0f
#define TARGET_FLOW_RATE_MIN   0.0f
#define TARGET_FLOW_RATE_MAX   100.0f

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static FILE                 *g_log_file = NULL;
static float                 g_target_flow_rate = TARGET_FLOW_RATE_MIN;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  initialize_gpio(void);
static int  initialize_logging(void);
static void cleanup(void);
static void log_data(float flow_rate, int valve_position);
static int  calculate_valve_position(float flow_rate);

/* ------------------------------- ISR ------------------------------------ */
static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_pulse_count++;
}

/* --------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Initialization ----------------------------- */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", VALVE_PWM_PIN);
        return -1;
    }

    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", VALVE_ENABLE_PIN);
        return -1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", FLOW_SENSOR_PIN);
        return -1;
    }

    /* Enable internal pull-down on the flow sensor pin so the line is
       defined when the sensor is disconnected. */
    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO %d.\n",
                FLOW_SENSOR_PIN);
    }

    /* Ensure valve is disabled (low) at startup. */
    if (gpioWrite(VALVE_ENABLE_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d.\n", VALVE_ENABLE_PIN);
        return -1;
    }

    /* Start with PWM duty cycle at 0. */
    if (gpioPWM(VALVE_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM on GPIO %d.\n",
                VALVE_PWM_PIN);
        return -1;
    }

    /* Set PWM frequency and range. */
    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n",
                VALVE_PWM_PIN);
        return -1;
    }

    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n",
                VALVE_PWM_PIN);
        return -1;
    }

    /* Register rising-edge interrupt on the flow sensor pin. */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0,
                         flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n",
                FLOW_SENSOR_PIN);
        return -1;
    }

    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static int initialize_logging(void)
{
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    /* Write CSV header if the file is empty. */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp_ms,flow_rate_L_min,valve_position\n");
        fflush(g_log_file);
    }

    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Disable valve and set PWM duty cycle to 0. */
    if (gpioWrite(VALVE_ENABLE_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to disable valve during cleanup.\n");
    }
    if (gpioPWM(VALVE_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to set PWM to 0 during cleanup.\n");
    }

    /* Close log file. */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Terminate pigpio library. */
    gpioTerminate();
}

/* ----------------------------- Logging data ------------------------------ */
static void log_data(float flow_rate, int valve_position)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    long timestamp_ms = (long)(ts.tv_sec * 1000L + ts.tv_nsec / 1000000L);

    fprintf(g_log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(g_log_file);
}

/* ----------------------- Proportional valve control ---------------------- */
static int calculate_valve_position(float flow_rate)
{
    float error = g_target_flow_rate - flow_rate;
    float valve_position = KP * error;

    if (valve_position < 0.0f) {
        valve_position = 0.0f;
    }
    if (valve_position > (float)PWM_RANGE) {
        valve_position = (float)PWM_RANGE;
    }

    return (int)(valve_position + 0.5f);
}

/* --------------------------------- Main ---------------------------------- */
int main(int argc, char *argv[])
{
    /* Parse command-line argument for target flow rate. */
    if (argc != 3 || strcmp(argv[1], "-t") != 0) {
        fprintf(stderr,
                "Usage: %s -t <target_flow_rate_L_min>\n"
                "  Target flow rate must be between %.1f and %.1f L/min.\n",
                argv[0], TARGET_FLOW_RATE_MIN, TARGET_FLOW_RATE_MAX);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    g_target_flow_rate = strtof(argv[2], &endptr);
    if (endptr == argv[2] || *endptr != '\0' ||
        g_target_flow_rate < TARGET_FLOW_RATE_MIN ||
        g_target_flow_rate > TARGET_FLOW_RATE_MAX) {
        fprintf(stderr,
                "Error: invalid target flow rate '%s'.\n"
                "  Target flow rate must be between %.1f and %.1f L/min.\n",
                argv[2], TARGET_FLOW_RATE_MIN, TARGET_FLOW_RATE_MAX);
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio and GPIO pins. */
    if (initialize_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize logging. */
    if (initialize_logging() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target flow rate: %.2f L/min\n",
           g_target_flow_rate);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE_NAME);

    /* Main control loop. */
    while (g_running) {
        /* Reset pulse count for this sample interval. */
        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;

        /*
         * YF-S201 flow sensor: 1 pulse ≈ 0.01 L/min.
         * Flow rate in L/min = pulses * 0.01.
         */
        float flow_rate = (float)pulses * 0.01f;

        /* Calculate valve position from proportional controller. */
        int valve_position = calculate_valve_position(flow_rate);

        /* Apply PWM duty cycle to valve. */
        if (gpioPWM(VALVE_PWM_PIN, valve_position) != 0) {
            fprintf(stderr, "Warning: failed to set PWM duty cycle.\n");
        }

        /* Log data to file. */
        log_data(flow_rate, valve_position);

        /* Sleep for the sample interval. */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

