/*
 * door_access.c — Two-factor door access control for Raspberry Pi 3 Model B+
 *
 * Locks : YLI YM-180 electromagnetic lock actuators
 *   BCM 17 — Lock 1
 *   BCM 27 — Lock 2
 * Button: active-low, internal pull-up, 50 ms debounce
 *   BCM 22
 * RFID  : SPI0, 100 kHz, 10-byte tag (0x0000000000) = no tag
 *
 * Build: gcc -O2 -Wall -Wextra -o door_access door_access.c -lpigpio -lrt
 * Run  : sudo ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define LOCK_1_PIN          17
#define LOCK_2_PIN          27
#define BUTTON_PIN          22

#define SPI_CHANNEL         0
#define SPI_SPEED           100000          /* 100 kHz */
#define SPI_FLAGS           0               /* Mode 0, active-low CE */

#define DEBOUNCE_US         50000           /* 50 ms */
#define LOCK_HOLD_US        5000000         /* 5 s */
#define POLL_DELAY_US       100000          /* 100 ms */
#define LOG_FILE            "/var/log/door_access.log"

/* Valid 10-byte tag (0x0000000000) */
static const uint8_t VALID_TAG[10] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_fp     = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void log_event(const char *msg);
static void cleanup(void);
static void signal_handler(int sig);
static int  init_gpio(void);
static int  init_spi(void);
static int  read_rfid_tag(uint8_t *tag);
static int  is_valid_tag(const uint8_t *tag);
static int  button_pressed(void);
static int  lock_engage(int pin);
static int  lock_disengage(int pin);
static int  lock_set(int pin, int engaged);

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *msg)
{
    if (!g_log_fp)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(g_log_fp, "%s %s\n", ts, msg);
    fflush(g_log_fp);
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Ensure locks are engaged (HIGH) before releasing resources */
    if (g_spi_handle >= 0) {
        lock_engage(LOCK_1_PIN);
        lock_engage(LOCK_2_PIN);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_fp) {
        log_event("Program terminated");
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- GPIO init -------------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LOCK_1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set lock pin modes\n");
        return -1;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set button pin mode\n");
        return -1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on button pin\n");
        return -1;
    }

    /* Start with locks engaged (HIGH) */
    if (lock_engage(LOCK_1_PIN) < 0 || lock_engage(LOCK_2_PIN) < 0) {
        fprintf(stderr, "Error: failed to initialise lock states\n");
        return -1;
    }

    return 0;
}

/* ------------------------------- SPI init --------------------------------- */
static int init_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        return -1;
    }
    return 0;
}

/* ----------------------------- RFID read --------------------------------- */
/*
 * Read 10 bytes from the RFID reader.
 * Returns 0 on success, -1 on SPI transfer failure, -2 on no tag (all zeros).
 */
static int read_rfid_tag(uint8_t *tag)
{
    if (!tag)
        return -1;

    char rx[10] = {0};
    int  rc;

    /*
     * pigpio's spiXfer uses a single transfer of up to 32 bytes.
     * We send 10 dummy bytes to clock out the 10-byte tag data.
     */
    rc = spiXfer(g_spi_handle, rx, rx, 10);
    if (rc < 0) {
        fprintf(stderr, "Error: spiXfer failed: %d\n", rc);
        return -1;
    }

    /* Check for no tag (all zeros) */
    int all_zero = 1;
    for (int i = 0; i < 10; i++) {
        if (rx[i] != 0x00) {
            all_zero = 0;
            break;
        }
    }
    if (all_zero)
        return -2;

    memcpy(tag, rx, 10);
    return 0;
}

/* ----------------------------- Tag validation ----------------------------- */
static int is_valid_tag(const uint8_t *tag)
{
    if (!tag)
        return 0;
    return memcmp(tag, VALID_TAG, 10) == 0;
}

/* ----------------------------- Button press ------------------------------- */
static int button_pressed(void)
{
    if (gpioRead(BUTTON_PIN) == 0) {
        gpioDelay(DEBOUNCE_US);
        if (gpioRead(BUTTON_PIN) == 0) {
            while (gpioRead(BUTTON_PIN) == 0)
                gpioDelay(POLL_DELAY_US);
            return 1;
        }
    }
    return 0;
}

/* --------------------------- Lock control helpers ------------------------ */
static int lock_engage(int pin)
{
    return lock_set(pin, 1);
}

static int lock_disengage(int pin)
{
    return lock_set(pin, 0);
}

static int lock_set(int pin, int engaged)
{
    int level = engaged ? 1 : 0;
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Open log file first so errors can be recorded */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error installing signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise pigpio and GPIO pins */
    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise SPI */
    if (init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    /* Main access loop */
    while (g_running) {
        uint8_t tag[10];
        int     rc;

        /* Read RFID tag with retry */
        for (int attempt = 0; attempt < 4; attempt++) {
            rc = read_rfid_tag(tag);
            if (rc == 0)
                break;
            if (rc == -2) {
                log_event("No RFID tag detected");
                break;
            }
            /* rc == -1: SPI error — wait and retry */
            gpioDelay(POLL_DELAY_US);
        }

        if (rc == 0) {
            if (is_valid_tag(tag)) {
                log_event("Valid tag detected — disengaging locks");

                if (lock_disengage(LOCK_1_PIN) < 0 || lock_disengage(LOCK_2_PIN) < 0) {
                    log_event("Error: failed to disengage locks");
                } else {
                    /* Hold locks engaged for 5 seconds */
                    uint32_t elapsed = 0;
                    while (g_running && elapsed < LOCK_HOLD_US) {
                        gpioDelay(POLL_DELAY_US);
                        elapsed += POLL_DELAY_US;
                    }

                    /* Re-engage locks */
                    if (lock_engage(LOCK_1_PIN) < 0 || lock_engage(LOCK_2_PIN) < 0) {
                        log_event("Error: failed to re-engage locks");
                    } else {
                        log_event("Locks re-engaged");
                    }
                }
            } else {
                log_event("Invalid tag detected");
            }
        } else if (rc == -2) {
            /* No tag present — nothing to do */
        } else {
            /* SPI read failure — log and continue */
            log_event("Error: SPI read failure");
        }

        /* Check for button press without valid tag */
        if (button_pressed()) {
            log_event("Button pressed without valid tag — disengaging locks");
            lock_disengage(LOCK_1_PIN);
            lock_disengage(LOCK_2_PIN);
            /* Hold for 5 s, checking for shutdown */
            uint32_t elapsed = 0;
            while (g_running && elapsed < LOCK_HOLD_US) {
                gpioDelay(POLL_DELAY_US);
                elapsed += POLL_DELAY_US;
            }
            lock_engage(LOCK_1_PIN);
            lock_engage(LOCK_2_PIN);
            log_event("Locks re-engaged");
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

