#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

/* ---- PID parameters ---- */
#define KP 1.0
#define KI 0.01
#define KD 0.1
#define TARGET_SPEED 60.0
#define SAMPLE_TIME_US 100000  /* 100 ms */
#define PWM_FREQUENCY 100      /* 100 Hz */
#define PWM_RANGE 1000         /* 1000 steps */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static pthread_mutex_t g_enc1_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t g_enc2_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int32_t g_encoder1_count = 0;
static volatile int32_t g_encoder2_count = 0;

/* ---- Function prototypes ---- */
static void signal_handler(int sig);
static int initialize_gpio(void);
static void cleanup_gpio(void);
static void *encoder_thread(void *arg);
static double calculate_pid(double setpoint, double actual_speed);
static void set_motor_speed(int motor_number, double speed);
static void log_data(double speed1, double speed2, double p1, double i1, double d1, double pid1,
                     double p2, double i2, double d2, double pid2);

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- GPIO initialization ---- */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    /* Motor control lines */
    if (gpioSetMode(MOTOR1_ENA, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_ENB, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set motor control line modes.\n");
        return -1;
    }

    /* Encoder A lines (quadrature input, both edges) */
    if (gpioSetMode(ENCODER1_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_A, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set encoder A line modes.\n");
        return -1;
    }
    if (gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP) < 0) {
        fprintf(stderr, "Warning: failed to set pull-up on encoder A lines.\n");
    }
    if (gpioSetAlertFuncEx(ENCODER1_A, encoder_thread, NULL) < 0 ||
        gpioSetAlertFuncEx(ENCODER2_A, encoder_thread, NULL) < 0) {
        fprintf(stderr, "Error: failed to set alert functions on encoder A lines.\n");
        return -1;
    }

    /* Encoder B lines (quadrature input, read direction) */
    if (gpioSetMode(ENCODER1_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_B, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set encoder B line modes.\n");
        return -1;
    }
    if (gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Warning: failed to set pull-up on encoder B lines.\n");
    }

    /* Ensure motors are stopped initially */
    gpioWrite(MOTOR1_ENA, 0);
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR2_ENB, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    return 0;
}

/* ---- GPIO cleanup ---- */
static void cleanup_gpio(void) {
    /* Stop motors */
    gpioWrite(MOTOR1_ENA, 0);
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR2_ENB, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    /* Remove alert functions */
    gpioSetAlertFuncEx(ENCODER1_A, NULL, NULL);
    gpioSetAlertFuncEx(ENCODER2_A, NULL, NULL);

    gpioTerminate();
}

/* ---- Encoder thread (alert callback) ---- */
static void *encoder_thread(void *arg) {
    (void)arg;
    int a_pin = gpioRead(ENCODER1_A);
    int b_pin = gpioRead(ENCODER1_B);
    int prev_a = a_pin;
    int prev_b = b_pin;

    while (g_running) {
        int a = gpioRead(ENCODER1_A);
        int b = gpioRead(ENCODER1_B);

        if (a != prev_a || b != prev_b) {
            int32_t count;
            if (a == prev_a) {
                /* B changed — quadrature decode */
                if (a == b) {
                    count = 1;
                } else {
                    count = -1;
                }
            } else {
                /* A changed — quadrature decode */
                if (a == b) {
                    count = -1;
                } else {
                    count = 1;
                }
            }

            pthread_mutex_lock(&g_enc1_mutex);
            g_encoder1_count += count;
            pthread_mutex_unlock(&g_enc1_mutex);

            prev_a = a;
            prev_b = b;
        }

        gpioDelay(100); /* 100 us poll interval */
    }

    return NULL;
}

/* ---- PID calculation ---- */
static double calculate_pid(double setpoint, double actual_speed) {
    static double integral = 0.0;
    static double previous_error = 0.0;
    double error = setpoint - actual_speed;
    double dt = (double)SAMPLE_TIME_US / 1000000.0;

    integral += error * dt;
    if (integral > 100.0) integral = 100.0;
    if (integral < -100.0) integral = -100.0;

    double derivative = (error - previous_error) / dt;
    double output = KP * error + KI * integral + KD * derivative;

    previous_error = error;
    return output;
}

/* ---- Set motor speed (RPM) ---- */
static void set_motor_speed(int motor_number, double speed) {
    int enable_pin, in1_pin, in2_pin;
    if (motor_number == 1) {
        enable_pin = MOTOR1_ENA;
        in1_pin = MOTOR1_IN1;
        in2_pin = MOTOR1_IN2;
    } else if (motor_number == 2) {
        enable_pin = MOTOR2_ENB;
        in1_pin = MOTOR2_IN3;
        in2_pin = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Error: invalid motor number %d.\n", motor_number);
        return;
    }

    /* Clamp speed to valid range */
    if (speed < 0.0) speed = 0.0;
    if (speed > 100.0) speed = 100.0;

    /* Software PWM: duty cycle proportional to speed */
    int duty_cycle = (int)(speed * (double)PWM_RANGE / 100.0);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (gpioPWM(enable_pin, duty_cycle) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on enable pin %d.\n", enable_pin);
        return;
    }

    /* Direction: forward if speed > 0, backward if speed < 0 */
    if (speed > 0.0) {
        gpioWrite(in1_pin, 1);
        gpioWrite(in2_pin, 0);
    } else if (speed < 0.0) {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 1);
    } else {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 0);
    }
}

/* ---- Log data to CSV ---- */
static void log_data(double speed1, double speed2, double p1, double i1, double d1, double pid1,
                     double p2, double i2, double d2, double pid2) {
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: log file is not open.\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
