#define VALVE2_DURATION_MS 1000
#define VALVE1_PAUSE_SEC 5
#define VALVE2_PAUSE_SEC 10
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        perror("localtime_r");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, event) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static int activate_valve(int gpio, int duration_ms, const char *name) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH (relay ON)\n", gpio);
        return -1;
    }
    char msg[128];
    snprintf(msg, sizeof(msg), "Valve %s activated (GPIO %d HIGH)", name, gpio);
    if (log_event(msg) != 0) {
        fprintf(stderr, "Failed to log activation of Valve %s\n", name);
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW (relay OFF)\n", gpio);
        return -1;
    }
    snprintf(msg, sizeof(msg), "Valve %s deactivated (GPIO %d LOW)", name, gpio);
    if (log_event(msg) != 0) {
        fprintf(stderr, "Failed to log deactivation of Valve %s\n", name);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int gpios[] = {VALVE1_GPIO, VALVE2_GPIO};
    for (size_t i = 0; i < sizeof(gpios) / sizeof(gpios[0]); i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", gpios[i]);
            fclose(log_file);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioWrite(gpios[i], 0) != 0) {
            fprintf(stderr, "Failed to initialize GPIO %d LOW\n", gpios[i]);
            fclose(log_file);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Water distribution system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (activate_valve(VALVE1_GPIO, VALVE1_DURATION_MS, "1") != 0) {
            fprintf(stderr, "Valve 1 activation failed; continuing.\n");
        }
        if (!running) break;
        sleep(VALVE1_PAUSE_SEC);
        if (!running) break;
        if (activate_valve(VALVE2_GPIO, VALVE2_DURATION_MS, "2") != 0) {
            fprintf(stderr, "Valve 2 activation failed; continuing.\n");
        }
        if (!running) break;
        sleep(VALVE2_PAUSE_SEC);
    }

    printf("\nShutting down...\n");
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);
    if (fclose(log_file) != 0) {
        perror("fclose");
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

