    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (mpr121_write_reg(MPR121_E0TTH + (i * 2), 0x0F) < 0) return -1;
        if (mpr121_write_reg(MPR121_E0RTH + (i * 2), 0x0A) < 0) return -1;
    }

    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write_reg(MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

static int mpr121_read_touch_status(uint16_t *touch_status) {
    uint8_t low, high;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_L, &low) < 0) return -1;
    if (mpr121_read_reg(MPR121_TOUCHSTATUS_H, &high) < 0) return -1;
    *touch_status = ((uint16_t)high << 8) | low;
    return 0;
}

static int relay_toggle(void) {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
        fprintf(stderr, "Error writing to relay GPIO\n");
        return -1;
    }
    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting relay GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Error initializing relay GPIO state\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpioDelay(STABILIZATION_DELAY_US);

    while (running) {
        uint16_t touch_status;
        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status\n");
            break;
        }

        if (touch_status > 0) {
            if (relay_toggle() < 0) {
                break;
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

