#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN      17
#define RELAY_PIN    18
#define UNLOCK_MS    500
#define RATE_LIMIT_S 2
#define POLL_MS      50
#define LOG_FILE     "door_events.log"

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_event(const char *event)
{
    if (!log_fp)
        return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000L, event);
    fflush(log_fp);
}

static void unlock_door(void)
{
    log_event("Motion detected, unlocking door");

    if (gpioWrite(RELAY_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to activate relay\n");
        return;
    }

    gpioDelay(UNLOCK_MS * 1000);

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to deactivate relay\n");
    }

    log_event("Door unlocked");
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set PIR pin mode\n");
        goto cleanup;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin mode\n");
        goto cleanup;
    }

    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on PIR pin\n");
        goto cleanup;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay to off\n");
        goto cleanup;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: failed to register SIGINT handler");
        goto cleanup;
    }

    log_event("Program started");

    int last_state = 0;
    time_t last_unlock = 0;

    while (running) {
        int pir_val = gpioRead(PIR_PIN);
        if (pir_val < 0) {
            fprintf(stderr, "Error: failed to read PIR pin\n");
            break;
        }

        if (pir_val == 1 && last_state == 0) {
            time_t now = time(NULL);
            if (difftime(now, last_unlock) >= RATE_LIMIT_S) {
                unlock_door();
                last_unlock = now;
            }
        }

        last_state = pir_val;
        gpioDelay(POLL_MS * 1000);
    }

    log_event("Program terminated");

cleanup:
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

