#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_STEP_DURATION_MS 50
#define MAX_STEP_DURATION_MS 200
#define MIN_PATTERN_STEPS 5
#define MAX_PATTERN_STEPS 15

static volatile sig_atomic_t shutdown_requested = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_requested = 1;
}

static int set_motor_pwm(int gpio, int duty_cycle) {
    if (duty_cycle < MIN_DUTY_CYCLE || duty_cycle > MAX_DUTY_CYCLE) {
        fprintf(stderr, "Error: Invalid duty cycle %d for GPIO %d (must be %d-%d)\n",
                duty_cycle, gpio, MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
        return -1;
    }
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for GPIO %d with duty cycle %d\n",
                gpio, duty_cycle);
        return -1;
    }
    return 0;
}

static int generate_random_step(int *motor1_duty, int *motor2_duty, int *duration_ms) {
    *motor1_duty = rand() % (MAX_DUTY_CYCLE + 1);
    *motor2_duty = rand() % (MAX_DUTY_CYCLE + 1);
    *duration_ms = MIN_STEP_DURATION_MS + (rand() % (MAX_STEP_DURATION_MS - MIN_STEP_DURATION_MS + 1));
    return 0;
}

static int play_pattern(int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        if (shutdown_requested) {
            return -1;
        }
        int motor1_duty, motor2_duty, duration_ms;
        if (generate_random_step(&motor1_duty, &motor2_duty, &duration_ms) != 0) {
            return -1;
        }
        if (set_motor_pwm(MOTOR1_GPIO, motor1_duty) != 0 ||
            set_motor_pwm(MOTOR2_GPIO, motor2_duty) != 0) {
            return -1;
        }
        gpioDelay(duration_ms * 1000);
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (!shutdown_requested) {
        int num_steps = MIN_PATTERN_STEPS + (rand() % (MAX_PATTERN_STEPS - MIN_PATTERN_STEPS + 1));
        if (play_pattern(num_steps) != 0) {
            break;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

