#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN  4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN    27

#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE  "weight_log.txt"

#define DEFAULT_SCALE  1.0f
#define DEFAULT_OFFSET 0.0f

#define WEIGHT_THRESHOLD 10.0f
#define READ_TIMEOUT_US  500000
#define SAMPLE_COUNT     100
#define SAMPLE_DELAY_US  1000
#define LOOP_DELAY_US    500000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *out_value) {
    if (out_value == NULL) return -1;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);

    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    long count = 0;
    int timeout = 0;

    while (gpioRead(data_pin) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > READ_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data pin low\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        count = count << 1;
        if (gpioRead(data_pin)) {
            count++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (count & 0x800000) {
        count |= ~0xFFFFFFL;
    }

    *out_value = count;
    return 0;
}

static float calculate_weight(long raw_value, float scale, float offset) {
    return (float)raw_value * scale + offset;
}

static int load_calibration(const char *filename, float *scale, float *offset) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file '%s'. Using defaults.\n", filename);
        return -1;
    }

    if (fscanf(fp, "%f %f", scale, offset) != 2) {
        fprintf(stderr, "Warning: Invalid calibration data in '%s'. Using defaults.\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int save_calibration(const char *filename, float scale, float offset) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file '%s' for writing.\n", filename);
        return -1;
    }

    if (fprintf(fp, "%.6f %.6f\n", scale, offset) < 0) {
        fprintf(stderr, "Error: Failed to write calibration data to '%s'.\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int log_weight(const char *filename, float weight) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open weight log file '%s'.\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f kg\n", timestamp, weight) < 0) {
        fprintf(stderr, "Error: Failed to write to weight log file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int control_solenoid(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: Failed to write to solenoid pin %d.\n", pin);
        return -1;
    }
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin, float *scale, float *offset) {
    printf("Starting HX711 calibration. Please remove all weight from the load cell.\n");
    printf("Press Enter to continue...");
    fflush(stdout);
    int c = getchar();
    if (c != '\n' && c != EOF) {
        while (getchar() != '\n');
    }

    long sum = 0;
    int valid_readings = 0;

    for (int i = 0; i < SAMPLE_COUNT; i++) {
        long raw_value;
        if (read_hx711(data_pin, clock_pin, &raw_value) == 0) {
            sum += raw_value;
            valid_readings++;
        } else {
            fprintf(stderr, "Warning: HX711 read failed during calibration (%d/%d).\n", i + 1, SAMPLE_COUNT);
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    if (valid_readings == 0) {
        fprintf(stderr, "Error: No valid readings during calibration.\n");
        return -1;
    }

    *offset = (float)sum / valid_readings;
    printf("Calibration complete. Offset: %.2f\n", *offset);

    printf("Starting HX711 weight calibration. Place a known weight on the load cell.\n");
    printf("Enter the known weight in kg: ");
    fflush(stdout);

    float known_weight;
    if (scanf("%f", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight.\n");
        return -1;
    }

    sum = 0;
    valid_readings = 0;

    for (int i = 0; i < SAMPLE_COUNT; i++) {
        long raw_value;
