#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define MOTOR_RUN_TIME_US 5000000
#define SENSOR_CHECK_INTERVAL_US 60000000
#define POST_CLOSE_DELAY_US 60000000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define PWM_DUTY_CYCLE 150

static volatile sig_atomic_t program_running = 1;
static int pigpio_initialized = 0;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    syslog(LOG_INFO, "%s: %s", buf, message);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        return -1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 pin mode");
        return -1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 pin mode");
        return -1;
    }
    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor PWM pin mode");
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_PWM_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range");
        return -1;
    }

    return 0;
}

static void stop_motor(void) {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
}

static int read_rain_sensor(void) {
    int readings[DEBOUNCE_READINGS];
    int low_count = 0;

    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(RAIN_SENSOR_PIN);
        if (readings[i] < 0) {
            syslog(LOG_ERR, "Failed to read rain sensor pin");
            return -1;
        }
        if (readings[i] == 0) {
            low_count++;
        }
        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_DELAY_US);
        }
    }

    return (low_count >= 3) ? 1 : 0;
}

static int control_motor(int duration_us) {
    if (gpioWrite(MOTOR_IN1_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 high");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 low");
        return -1;
    }
    if (gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE) != 0) {
        syslog(LOG_ERR, "Failed to start PWM on motor");
        return -1;
    }

    gpioDelay(duration_us);

    stop_motor();
    return 0;
}

static void cleanup(void) {
    if (pigpio_initialized) {
        stop_motor();
        gpioTerminate();
        pigpio_initialized = 0;
    }
    closelog();
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Window control system started");

    while (program_running) {
        int rain_detected = read_rain_sensor();

        if (rain_detected < 0) {
            syslog(LOG_ERR, "Error reading rain sensor, retrying in 60 seconds");
            gpioDelay(POST_CLOSE_DELAY_US);
            continue;
        }

        if (rain_detected) {
            char log_message_buf[256];
            snprintf(log_message_buf, sizeof(log_message_buf),
                     "Rain detected, closing window for 5 seconds");
            log_message(log_message_buf);

            if (control_motor(MOTOR_RUN_TIME_US) != 0) {
                syslog(LOG_ERR, "Error controlling motor, retrying in 60 seconds");
            } else {
                log_message("Window closed");
            }
        }

        gpioDelay(SENSOR_CHECK_INTERVAL_US);
    }

    log_message("Window control system shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

