#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define HX711_DATA_PIN  4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN    27

#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE         "security.log"

#define WEIGHT_THRESHOLD 5.0f
#define SOLENOID_DURATION_SEC 5
#define SAMPLE_DELAY_US 100000
#define HX711_TIMEOUT_US 100000
#define HX711_SETTLE_US  10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;
static float calibration_factor = 0.0f;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int32_t *out) {
    if (out == NULL) return -1;

    uint32_t start_tick = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if ((gpioTick() - start_tick) > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            return -1;
        }
    }

    uint32_t data = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) data |= 1;
        if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) return -1;
    gpioDelay(1);

    if (data & 0x800000) data |= 0xFF000000;
    *out = (int32_t)data;
    return 0;
}

static int calibrate_hx711(void) {
    float known_weight;
    int32_t raw_value;

    printf("Place a known weight on the load cell and enter its value (kg): ");
    fflush(stdout);
    if (scanf("%f", &known_weight) != 1) {
        fprintf(stderr, "Invalid input. Please enter a valid number.\n");
        return -1;
    }
    if (known_weight <= 0.0f) {
        fprintf(stderr, "Weight must be positive. Please enter a valid number.\n");
        return -1;
    }

    printf("Reading raw value...\n");
    if (read_hx711(&raw_value) != 0) {
        fprintf(stderr, "Failed to read raw value during calibration.\n");
        return -1;
    }

    calibration_factor = (float)raw_value / known_weight;
    printf("Calibration factor: %.2f\n", calibration_factor);

    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error opening calibration file: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(calibration_file, "%.2f", calibration_factor) < 0) {
        fprintf(stderr, "Error writing to calibration file: %s\n", strerror(errno));
        fclose(calibration_file);
        calibration_file = NULL;
        return -1;
    }

    if (fclose(calibration_file) != 0) {
        fprintf(stderr, "Error closing calibration file: %s\n", strerror(errno));
        calibration_file = NULL;
        return -1;
    }
    calibration_file = NULL;

    printf("Calibration complete. Continuing...\n");
    return 0;
}

static float calculate_weight(int32_t raw_value) {
    return (float)raw_value / calibration_factor;
}

static int log_event(float weight) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        return -1;
    }

    struct tm *tstruct = localtime(&now);
    if (tstruct == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return -1;
    }

    char buf[80];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "Error formatting time\n");
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(log_file, "%s, Weight: %.2f kg\n", buf, weight) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        log_file = NULL;
        return -1;
    }
    log_file = NULL;

    return 0;
}

static int control_solenoid(void) {
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        fprintf(stderr, "Error activating solenoid: %s\n", strerror(errno));
        return -1;
    }
    printf("Solenoid activated for %d seconds.\n", SOLENOID_DURATION_SEC);

    for (int i = 0; i < SOLENOID_DURATION_SEC * 10 && running; i++) {
        gpioDelay(100000);
    }

    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Error deactivating solenoid: %s\n", strerror(errno));
        return -1;
    }
    printf("Solenoid deactivated.\n");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting HX711 data pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting HX711 clock pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        fprintf(stderr, "Error initializing solenoid pin state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file != NULL) {
        if (fscanf(calibration_file, "%f", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration factor from file. Calibration required.\n");
            fclose(calibration_file);
            calibration_file = NULL;
        } else {
            printf("Calibration factor loaded: %.2f\n", calibration_factor);
            fclose(calibration_file);
            calibration_file = NULL;
        }
    } else {
        printf("Calibration file not found. Calibration required.\n");
    }

    if (calibration_factor <= 0.0f) {
        if (calibrate_hx711() != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t raw_value;
        if (read_hx711(&raw_value) != 0) {
            fprintf(stderr, "Error reading HX711 value. Retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float weight = calculate_weight(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded!\n");
            if (log_event(weight) != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
            if (control_solenoid() != 0) {
                fprintf(stderr, "Error controlling solenoid.\n");
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (calibration_file != NULL) {
        fclose(calibration_file);
        calibration_file = NULL;
    }

    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

