/*
 * KY-022 IR Obstacle Avoidance -> SRD-05VDC-SL Relay Toggle
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: Keywish KY-022 on GPIO16 (BCM), active-low (LOW = obstacle)
 * Relay:  Songle SRD-05VDC-SL on GPIO20 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_toggle relay_toggle.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN      16
#define RELAY_PIN       20
#define LOG_FILE        "relay_events.log"
#define POLL_INTERVAL_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(FILE *fp, int relay_state)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s - Relay toggled to %s\n",
                timestamp, relay_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *relay_line = NULL;
    FILE *log_fp = NULL;
    int relay_state = 0;
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Get sensor line ---- */
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (sensor_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request sensor line as input ---- */
    if (gpiod_line_request_input(sensor_line, "ky022-sensor") != 0) {
        fprintf(stderr, "gpiod_line_request_input(%d) failed: %s\n",
                SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Get relay line ---- */
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (relay_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request relay line as output, initial value LOW ---- */
    if (gpiod_line_request_output(relay_line, "srd05vdc-relay", 0) != 0) {
        fprintf(stderr, "gpiod_line_request_output(%d) failed: %s\n",
                RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring KY-022 on GPIO%d, relay on GPIO%d. Ctrl+C to exit.\n",
           SENSOR_PIN, RELAY_PIN);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int sensor_val = gpiod_line_get_value(sensor_line);
        if (sensor_val < 0) {
            fprintf(stderr, "gpiod_line_get_value(%d) failed: %s\n",
                    SENSOR_PIN, strerror(errno));
            break;
        }

        /* KY-022 is active-low: LOW means obstacle detected */
        if (sensor_val == 0) {
            relay_state = !relay_state;

            if (gpiod_line_set_value(relay_line, relay_state) != 0) {
                fprintf(stderr, "gpiod_line_set_value(%d) failed: %s\n",
                        RELAY_PIN, strerror(errno));
                break;
            }

            if (log_event(log_fp, relay_state) != 0) {
                fprintf(stderr, "Failed to log relay event.\n");
                break;
            }

            printf("Obstacle detected - relay toggled to %s\n",
                   relay_state ? "ON" : "OFF");
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* ---- Release lines and close chip ---- */
    if (relay_line != NULL) {
        gpiod_line_release(relay_line);
    }
    if (sensor_line != NULL) {
        gpiod_line_release(sensor_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    /* ---- Close log file ---- */
    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
            ret = EXIT_FAILURE;
        }
    }

    printf("\nExiting cleanly.\n");
    return ret;
}

