#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define BUZZER_DURATION_US 2000000  /* 2 seconds in microseconds */
#define POLL_DELAY_US 100000        /* 100 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown on SIGINT / SIGTERM              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped motion event to the log file                  */
/* ------------------------------------------------------------------ */
static void log_motion_event(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
    } else {
        fflush(log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Activate the buzzer for BUZZER_DURATION_US, then turn it off       */
/* ------------------------------------------------------------------ */
static void activate_buzzer(void)
{
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(BUZZER_PIN, 1) failed\n");
        return;
    }

    usleep(BUZZER_DURATION_US);

    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(BUZZER_PIN, 0) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    /* Ensure buzzer is off before releasing pigpio */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure PIR pin as input --- */
    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(PIR_PIN, PI_INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure buzzer pin as output, ensure it starts OFF --- */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(BUZZER_PIN, PI_OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(BUZZER_PIN, 0) initial state failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file in append mode --- */
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening motion_log.txt: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (running) {
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "gpioRead(PIR_PIN) failed\n");
            break;
        }

        if (pir_value == 1) {
            printf("Motion detected!\n");
            log_motion_event();
            activate_buzzer();
        }

        usleep(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

