/*
 * timed_watering.c — Raspberry Pi 3 Model B+
 *
 * Activates a Parker Hannifin Series 9 General Purpose Miniature Solenoid
 * Valve (12 V, 1.6 W) through an external N-channel MOSFET or relay module
 * on GPIO18 (BCM) for a duration read from watering.conf.
 *
 * Build:  gcc -O2 -Wall -Wextra -o timed_watering timed_watering.c -lpigpio -lrt
 * Run:    sudo ./timed_watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define CONFIG_FILE      "watering.conf"
#define GPIO_PIN         18          /* BCM 18 — external MOSFET/relay control */
#define MIN_DURATION_SEC 1
#define MAX_DURATION_SEC 3600
#define POLL_INTERVAL_US 100000      /* 100 ms — pigpio sleep is interruptible */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configuration file parsing                                          */
/* ------------------------------------------------------------------ */
static int read_watering_duration(const char *filename, int *duration_out)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        if (ferror(fp)) {
            fprintf(stderr, "Error reading config file '%s': %s\n",
                    filename, strerror(errno));
        } else {
            fprintf(stderr, "Config file '%s' is empty.\n", filename);
        }
        fclose(fp);
        return -1;
    }

    fclose(fp);

    /* Strip trailing newline */
    line[strcspn(line, "\r\n")] = '\0';

    char *eq = strchr(line, '=');
    if (eq == NULL) {
        fprintf(stderr, "Config file '%s' does not contain a '=' character.\n",
                filename);
        return -1;
    }

    *eq = '\0';
    char *key = line;
    char *value = eq + 1;

    /* Allow whitespace around the key */
    while (*key == ' ' || *key == '\t') key++;
    char *key_end = key + strlen(key);
    while (key_end > key && (key_end[-1] == ' ' || key_end[-1] == '\t'))
        key_end--;
    *key_end = '\0';

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Config file '%s' contains a key other than 'duration'.\n",
                filename);
        return -1;
    }

    errno = 0;
    char *endptr = NULL;
    long val = strtol(value, &endptr, 10);
    if (errno != 0 || endptr == value) {
        fprintf(stderr, "Invalid duration value '%s': %s\n",
                value, strerror(errno));
        return -1;
    }

    if (val < MIN_DURATION_SEC || val > MAX_DURATION_SEC) {
        fprintf(stderr, "Duration %ld seconds out of range [%d, %d].\n",
                val, MIN_DURATION_SEC, MAX_DURATION_SEC);
        return -1;
    }

    *duration_out = (int)val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Parker Hannifin Series 9 valves are active-low: 0 = valve ON, 1 = OFF */
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO %d to LOW.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Ensure valve is off before releasing pigpio resources */
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

static int activate_valve(int duration_sec)
{
    printf("Activating valve for %d seconds...\n", duration_sec);
    fflush(stdout);

    if (gpioWrite(GPIO_PIN, 1) != 0) {
        fprintf(stderr, "Failed to activate valve (set GPIO %d HIGH).\n",
                GPIO_PIN);
        return -1;
    }

    /*
     * Sleep in 100 ms increments so SIGINT/SIGTERM are caught promptly.
     * gpioDelay is interruptible by signals.
     */
    for (int i = 0; i < duration_sec * 10 && g_running; i++) {
        gpioDelay(POLL_INTERVAL_US);
    }

    if (gpioWrite(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Failed to deactivate valve (set GPIO %d LOW).\n",
                GPIO_PIN);
        return -1;
    }

    printf("Valve deactivated.\n");
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int duration = 0;
    if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Watering duration: %d seconds\n", duration);
    fflush(stdout);

    /*
     * Main loop: sleep until a signal arrives, then turn the valve off
     * promptly.  If g_running is 0, the signal was caught during the
     * sleep; if it is 1, we were interrupted by a signal after the
     * sleep but before the valve was activated.
     */
    while (g_running) {
        if (activate_valve(duration) != 0) {
            break;
        }
        if (!g_running) {
            break;
        }
        /*
         * If the loop exits normally, the valve was turned off by
         * activate_valve().  If g_running is 0, the signal was caught
         * during the sleep in activate_valve().
         */
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

