#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN    4
#define MIDDLE_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27

#define MOTOR_LEFT_PIN     22
#define MOTOR_RIGHT_PIN    23
#define MOTOR_LEFT_EN      24
#define MOTOR_RIGHT_EN     25

#define PWM_FREQUENCY      1000
#define PWM_RANGE          255
#define BASE_SPEED         150
#define SAMPLE_DELAY_US    10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }
    return v;
}

static void set_motor_speed(int left, int right) {
    if (gpioPWM(MOTOR_LEFT_PIN, left) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", MOTOR_LEFT_PIN);
    }
    if (gpioPWM(MOTOR_RIGHT_PIN, right) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", MOTOR_RIGHT_PIN);
    }
}

static void stop_motors(void) {
    set_motor_speed(0, 0);
}

static void log_data(int left, int middle, int right, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Left: %d, Middle: %d, Right: %d, Left Speed: %d, Right Speed: %d\n",
            timestamp, left, middle, right, left_speed, right_speed);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting sensor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_LEFT_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_LEFT_EN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_RIGHT_EN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting motor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_LEFT_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_RIGHT_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_LEFT_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_RIGHT_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            stop_motors();
            break;
        }

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (middle == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left == 0) {
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (right == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            left_speed = 0;
            right_speed = 0;
        }

        set_motor_speed(left_speed, right_speed);
        log_data(left, middle, right, left_speed, right_speed);

        gpioDelay(SAMPLE_DELAY_US);
    }

    stop_motors();

    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Line following robot stopped.\n");
    return EXIT_SUCCESS;
}

