#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CMD_CONT_HIGHRES 0x10
#define RELAY_GPIO     23
#define LUX_THRESHOLD  150.0f
#define LOG_FILE       "grow_log.txt"
#define MEASURE_DELAY_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[64];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int bh1750_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    uint8_t cmd = BH1750_CMD_CONT_HIGHRES;
    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Failed to send measurement command: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(float *lux_out) {
    uint8_t buf[2];
    ssize_t n = read(i2c_fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int relay_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return -1;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", RELAY_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(relay_line, "grow_lamp", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", RELAY_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        relay_line = NULL;
        return -1;
    }
    return 0;
}

static void relay_set(int state) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, state);
    }
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (bh1750_init() < 0) {
        log_event("BH1750 initialization failed");
        return 1;
    }
    log_event("BH1750 initialized");

    if (relay_init() < 0) {
        log_event("Relay initialization failed");
        cleanup();
        return 1;
    }
    log_event("Relay initialized");

    int relay_state = 0;
    char log_buf[256];

    while (running) {
        float lux;
        if (bh1750_read_lux(&lux) < 0) {
            log_event("Failed to read lux value");
        } else {
            snprintf(log_buf, sizeof(log_buf), "Lux: %.2f", lux);
            log_event(log_buf);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                relay_set(1);
                relay_state = 1;
                log_event("Relay turned ON");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                relay_set(0);
                relay_state = 0;
                log_event("Relay turned OFF");
            }
        }
        usleep(MEASURE_DELAY_MS * 1000);
    }

    log_event("Shutting down");
    cleanup();
    return 0;
}

