#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_BUTTON_PIN    21
#define UNLOCK_BUTTON_PIN  22
#define SERVO_PIN          18

#define LOCK_PULSE_WIDTH   1000   /* microseconds (0 degrees)   */
#define UNLOCK_PULSE_WIDTH 2000   /* microseconds (180 degrees) */
#define DEBOUNCE_DELAY_US  100000 /* 100 ms                    */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set LOCK_BUTTON_PIN (GPIO%d) as input.\n",
                LOCK_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set UNLOCK_BUTTON_PIN (GPIO%d) as input.\n",
                UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN (GPIO%d) as output.\n",
                SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-up resistors so the buttons read HIGH when not pressed */
    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on LOCK_BUTTON_PIN (GPIO%d).\n",
                LOCK_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on UNLOCK_BUTTON_PIN (GPIO%d).\n",
                UNLOCK_BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure the servo starts in a safe position */
    if (gpioServo(SERVO_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise servo on SERVO_PIN (GPIO%d).\n",
                SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_servo_pulse_width(int pulse_width)
{
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Warning: gpioServo failed for pulse width %d us.\n",
                pulse_width);
    }
}

static void lock_door(void)
{
    set_servo_pulse_width(LOCK_PULSE_WIDTH);
    printf("Door locked.\n");
    fflush(stdout);
}

static void unlock_door(void)
{
    set_servo_pulse_width(UNLOCK_PULSE_WIDTH);
    printf("Door unlocked.\n");
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            lock_door();
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            unlock_door();
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown: stop servo PWM and release pigpio resources */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

