/*
 * Haptic feedback system for Raspberry Pi 4 Model B
 *
 * Two Precision Microdrives 310-101 vibration motors are pulsed sequentially
 * over the GPIO bus using an external driver circuit.
 *
 * Motor 1: GPIO17 (BCM) — 200 ms pulse
 * Motor 2: GPIO27 (BCM) — 300 ms pulse
 *
 * Build: gcc -O2 -Wall -Wextra -o haptic haptic.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

#define MOTOR1_DURATION_MS 200
#define MOTOR2_DURATION_MS 300

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_motor(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int pulse_motor(struct gpiod_line *line, int duration_ms)
{
    if (set_motor(line, 1) < 0)
        return -1;

    usleep(duration_ms * 1000);

    if (set_motor(line, 0) < 0)
        return -1;

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *motor1 = NULL;
    struct gpiod_line *motor2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    motor1 = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1) {
        perror("gpiod_chip_get_line(MOTOR1_PIN)");
        goto cleanup;
    }

    motor2 = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2) {
        perror("gpiod_chip_get_line(MOTOR2_PIN)");
        goto cleanup;
    }

