 *
 * Two Precision Microdrives 310-101 vibration motors are pulsed sequentially
 * over the GPIO bus using an external driver circuit.
 *
 * Motor 1: GPIO17 (BCM) — 200 ms pulse
 * Motor 2: GPIO27 (BCM) — 300 ms pulse
 *
 * Build: gcc -O2 -Wall -Wextra -o haptic haptic.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

#define MOTOR1_DURATION_MS 200
#define MOTOR2_DURATION_MS 300

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_motor(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static int pulse_motor(struct gpiod_line *line, int duration_ms)
{
    if (set_motor(line, 1) < 0)
        return -1;

    usleep(duration_ms * 1000);

    if (set_motor(line, 0) < 0)
        return -1;

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *motor1 = NULL;
    struct gpiod_line *motor2 = NULL;
