    if (!motor2) {
        perror("gpiod_chip_get_line(MOTOR2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor1, "haptic-motor1", 0) < 0) {
        perror("gpiod_line_request_output(motor1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor2, "haptic-motor2", 0) < 0) {
        perror("gpiod_line_request_output(motor2)");
        goto cleanup;
    }

