/*
 * sound_triggered_alarm.c — Raspberry Pi 5
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_triggered_alarm sound_triggered_alarm.c -lzmq -lgpiod
 * Run:    ./sound_triggered_alarm [sound_sensor|alarm_node]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_PIN  17
#define ALARM_LED_PIN     27
#define POLL_INTERVAL_US  10000   /* 10 ms */
#define ALARM_DURATION_S  1
#define ZMQ_ENDPOINT      "tcp://*:5555"
#define ZMQ_LOCAL_ENDPOINT "tcp://localhost:5555"
#define ZMQ_TOPIC         "SOUND_ALERTS"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Sound sensor mode                                                  */
/* ------------------------------------------------------------------ */

static int sound_sensor_mode(struct gpiod_chip *chip, struct gpiod_line *sound_line)
{
    void *context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "zmq_ctx_new failed: %s\n", zmq_strerror(errno));
        return EXIT_FAILURE;
    }

    void *publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        fprintf(stderr, "zmq_socket(PUB) failed: %s\n", zmq_strerror(errno));
        zmq_ctx_destroy(context);
        return EXIT_FAILURE;
    }

    if (zmq_bind(publisher, ZMQ_ENDPOINT) != 0) {
        fprintf(stderr, "zmq_bind(%s) failed: %s\n", ZMQ_ENDPOINT, zmq_strerror(errno));
        zmq_close(publisher);
        zmq_ctx_destroy(context);
        return EXIT_FAILURE;
    }

    printf("Sound sensor mode started. Listening on GPIO%d, publishing alerts on %s\n",
           SOUND_SENSOR_PIN, ZMQ_ENDPOINT);

    while (g_running) {
        int val = gpiod_line_get_value(sound_line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            break;
        }

        /* LM393 digital output is active-low: 0 => sound detected */
        if (val == 0) {
            char message[256];
            int len = snprintf(message, sizeof(message), "%s", ZMQ_TOPIC);
            if (len < 0 || (size_t)len >= sizeof(message)) {
                fprintf(stderr, "Message formatting failed\n");
                break;
            }

            if (zmq_send(publisher, message, (size_t)len, 0) != 0) {
                fprintf(stderr, "zmq_send failed: %s\n", zmq_strerror(errno));
                break;
            }
            printf("Sound detected — alert published\n");
        }

        sleep_ms(POLL_INTERVAL_US);
    }

    zmq_close(publisher);
    zmq_ctx_destroy(context);
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
/* Alarm node mode                                                    */
/* ------------------------------------------------------------------ */

static int alarm_node_mode(struct gpiod_chip *chip, struct gpiod_line *led_line)
{
    void *context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "zmq_ctx_new failed: %s\n", zmq_strerror(errno));
        return EXIT_FAILURE;
    }

    void *subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        fprintf(stderr, "zmq_socket(SUB) failed: %s\n", zmq_strerror(errno));
        zmq_ctx_destroy(context);
        return EXIT_FAILURE;
    }

    if (zmq_connect(subscriber, ZMQ_LOCAL_ENDPOINT) != 0) {
        fprintf(stderr, "zmq_connect(%s) failed: %s\n", ZMQ_LOCAL_ENDPOINT, zmq_strerror(errno));
        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        return EXIT_FAILURE;
    }

    if (zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) != 0) {
        fprintf(stderr, "zmq_setsockopt(SUBSCRIBE) failed: %s\n", zmq_strerror(errno));
        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        return EXIT_FAILURE;
    }

    printf("Alarm node mode started. Subscribing to %s on GPIO%d\n",
           ZMQ_LOCAL_ENDPOINT, ALARM_LED_PIN);

    while (g_running) {
        char buffer[256];
        zmq_msg_t msg;

        if (zmq_msg_init(&msg) != 0) {
            fprintf(stderr, "zmq_msg_init failed: %s\n", zmq_strerror(errno));
            break;
        }

        int rc = zmq_msg_recv(&msg, subscriber, 0);
        if (rc < 0) {
            if (errno == EINTR) {
                zmq_msg_close(&msg);
                continue;
            }
            fprintf(stderr, "zmq_msg_recv failed: %s\n", zmq_strerror(errno));
            zmq_msg_close(&msg);
            break;
        }

        size_t msg_len = zmq_msg_size(&msg);
        if (msg_len >= sizeof(buffer)) {
            msg_len = sizeof(buffer) - 1;
        }
        memcpy(buffer, zmq_msg_data(&msg), msg_len);
        buffer[msg_len] = '\0';

        zmq_msg_close(&msg);

        if (strcmp(buffer, ZMQ_TOPIC) == 0) {
            printf("Alert received — activating alarm\n");

            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Failed to turn LED on: %s\n", strerror(errno));
                break;
            }

            sleep_ms(ALARM_DURATION_S * 1000);

            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to turn LED off: %s\n", strerror(errno));
                break;
            }
        }
    }

    zmq_close(subscriber);
    zmq_ctx_destroy(context);
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s [sound_sensor|alarm_node]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: '%s'. Must be 'sound_sensor' or 'alarm_node'.\n", mode);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (strcmp(mode, "sound_sensor") == 0) {
        if (gpiod_line_request_input(sound_line, "sound_sensor") < 0) {
            fprintf(stderr, "Failed to request GPIO %d as input: %s\n", SOUND_SENSOR_PIN, strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        return sound_sensor_mode(chip, sound_line);
    }

    /* alarm_node */
    if (gpiod_line_request_output(led_line, "alarm_node", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", ALARM_LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    return alarm_node_mode(chip, led_line);
}

