/*
 * NEC IR Decoder for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - TSOP38238 IR receiver on GPIO17 (BCM)
 *   - VCC: 5V, GND: GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ir_decoder ir_decoder.c -lpigpio -lmosquitto -lyaml
 *
 * Run:
 *   sudo ./ir_decoder
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO          17
#define MQTT_HOST        "localhost"
#define MQTT_PORT        1883
#define MQTT_TOPIC       "ir/decoded"
#define MAX_PULSES       100
#define NEC_HDR_MARK     9000
#define NEC_HDR_SPACE    4500
#define NEC_BIT_MARK     560
#define NEC_ONE_SPACE    1690
#define NEC_ZERO_SPACE   560
#define NEC_RPT_SPACE    2250
#define NEC_TOLERANCE    25
#define NEC_EXTENDED     0x00000001

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t g_pulse_widths[MAX_PULSES];
static volatile int g_pulse_count = 0;
static volatile uint32_t g_last_tick = 0;
static struct mosquitto *g_mosq = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level != 0 && level != 1)
        return;

    uint32_t pulse_width = tick - g_last_tick;
    g_last_tick = tick;

    if (g_pulse_count < MAX_PULSES) {
        g_pulse_widths[g_pulse_count++] = pulse_width;
    } else {
        syslog(LOG_ERR, "Pulse buffer overflow, resetting");
        g_pulse_count = 0;
    }
}

static int in_range(uint32_t val, uint32_t target, uint32_t tol)
{
    return (val >= target - tol) && (val <= target + tol);
}

static int decode_nec(const uint32_t *pw, int count, uint32_t *command)
{
    if (count < 68)
        return -1;

    if (!in_range(pw[0], NEC_HDR_MARK, NEC_TOLERANCE))
        return -1;
    if (!in_range(pw[1], NEC_HDR_SPACE, NEC_TOLERANCE))
        return -1;

    uint32_t addr = 0, addr_inv = 0, cmd = 0, cmd_inv = 0;
    int ext = 0;

    for (int i = 0; i < 32; i++) {
        if (!in_range(pw[2 + i * 2], NEC_BIT_MARK, NEC_TOLERANCE))
            return -1;

        if (in_range(pw[3 + i * 2], NEC_ONE_SPACE, NEC_TOLERANCE)) {
            if (i < 16)
                addr |= (1u << i);
            else
                cmd |= (1u << (i - 16));
        } else if (!in_range(pw[3 + i * 2], NEC_ZERO_SPACE, NEC_TOLERANCE)) {
            return -1;
        }
    }

    if (in_range(pw[66], NEC_BIT_MARK, NEC_TOLERANCE)) {
        if (in_range(pw[67], NEC_ONE_SPACE, NEC_TOLERANCE))
            ext = 1;
        else if (!in_range(pw[67], NEC_ZERO_SPACE, NEC_TOLERANCE))
            return -1;
    } else if (!in_range(pw[66], NEC_ZERO_SPACE, NEC_TOLERANCE)) {
        return -1;
    }

    if (ext) {
        for (int i = 0; i < 16; i++) {
            if (!in_range(pw[68 + i * 2], NEC_BIT_MARK, NEC_TOLERANCE))
                return -1;

            if (in_range(pw[69 + i * 2], NEC_ONE_SPACE, NEC_TOLERANCE))
                addr_inv |= (1u << i);
            else if (!in_range(pw[69 + i * 2], NEC_ZERO_SPACE, NEC_TOLERANCE))
                return -1;
        }

        for (int i = 0; i < 16; i++) {
            if (!in_range(pw[84 + i * 2], NEC_BIT_MARK, NEC_TOLERANCE))
                return -1;

            if (in_range(pw[85 + i * 2], NEC_ONE_SPACE, NEC_TOLERANCE))
                cmd_inv |= (1u << i);
            else if (!in_range(pw[85 + i * 2], NEC_ZERO_SPACE, NEC_TOLERANCE))
                return -1;
        }
    }

    uint8_t addr_lo = addr & 0xFF;
    uint8_t addr_hi = (addr >> 8) & 0xFF;
    uint8_t cmd_lo  = cmd & 0xFF;
    uint8_t cmd_hi  = (cmd >> 8) & 0xFF;

    if (ext) {
        uint8_t addr_inv_lo = addr_inv & 0xFF;
        uint8_t addr_inv_hi = (addr_inv >> 8) & 0xFF;
        uint8_t cmd_inv_lo  = cmd_inv & 0xFF;
        uint8_t cmd_inv_hi  = (cmd_inv >> 8) & 0xFF;

        if ((uint8_t)(~addr_lo) != addr_inv_lo ||
            (uint8_t)(~addr_hi) != addr_inv_hi ||
            (uint8_t)(~cmd_lo)  != cmd_inv_lo  ||
            (uint8_t)(~cmd_hi)  != cmd_inv_hi) {
            syslog(LOG_ERR, "NEC checksum failed (extended)");
            return -1;
        }
    } else {
        if ((uint8_t)(~addr_lo) != addr_hi ||
            (uint8_t)(~cmd_lo)  != cmd_hi) {
            syslog(LOG_ERR, "NEC checksum failed (standard)");
            return -1;
        }
    }

    *command = cmd;
    return 0;
}

static void publish_command(uint32_t command)
{
    char payload[64];
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    snprintf(payload, sizeof(payload),
             "{\"timestamp\":\"%s\",\"command\":%u}", ts, command);

