static void ir_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level != 0 && level != 1)
        return;

    uint32_t pulse_width = tick - g_last_tick;
    g_last_tick = tick;

    if (g_pulse_count < MAX_PULSES) {
        g_pulse_widths[g_pulse_count++] = pulse_width;
    } else {
        syslog(LOG_ERR, "Pulse buffer overflow, resetting");
        g_pulse_count = 0;
