#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR_BASE 0x23
#define BH1750_CMD_POWER_ON 0x01
#define BH1750_CMD_CONT_HIGHRES 0x10
#define BH1750_CONV_TIME_MS 180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define LOOP_DELAY_MS 1000

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int bh1750_init(int fd) {
    uint8_t cmd = BH1750_CMD_POWER_ON;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 power-on write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000);
    cmd = BH1750_CMD_CONT_HIGHRES;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 continuous high-res mode failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static float bh1750_read_lux(int fd) {
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read failed (got %zd bytes): %s\n", n, strerror(errno));
        return NAN;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    return (float)raw / 1.2f;
}

static int send_multicast(int sockfd, const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sockfd, data, strlen(data), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int i2c_fds[NUM_SENSORS];
    int sockfd = -1;
    int rc = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) i2c_fds[i] = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "socket creation failed: %s\n", strerror(errno));
        goto cleanup;
    }

    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "setsockopt(IP_MULTICAST_TTL) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = open(I2C_BUS, O_RDWR);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
            goto cleanup;
        }
        if (ioctl(i2c_fds[i], I2C_SLAVE, BH1750_ADDR_BASE + i) < 0) {
            fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                    BH1750_ADDR_BASE + i, strerror(errno));
            goto cleanup;
        }
        if (bh1750_init(i2c_fds[i]) < 0) {
            fprintf(stderr, "BH1750 init failed at sensor %d\n", i + 1);
            goto cleanup;
        }
    }

    while (!terminate) {
        float lux[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (ioctl(i2c_fds[i], I2C_SLAVE, BH1750_ADDR_BASE + i) < 0) {
                fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                        BH1750_ADDR_BASE + i, strerror(errno));
                lux[i] = NAN;
                continue;
            }
            usleep(BH1750_CONV_TIME_MS * 1000);
            lux[i] = bh1750_read_lux(i2c_fds[i]);
        }

        char buffer[256];
        int len = snprintf(buffer, sizeof(buffer), "");
        if (len < 0 || (size_t)len >= sizeof(buffer)) {
            fprintf(stderr, "snprintf failed\n");
            goto cleanup;
        }
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (isnan(lux[i])) {
                len += snprintf(buffer + len, sizeof(buffer) - len,
                                "%d,NaN", i + 1);
            } else {
                len += snprintf(buffer + len, sizeof(buffer) - len,
                                "%d,%.2f", i + 1, lux[i]);
            }
            if (i < NUM_SENSORS - 1) {
                len += snprintf(buffer + len, sizeof(buffer) - len, ";");
            }
        }

        if (send_multicast(sockfd, buffer) < 0) {
            fprintf(stderr, "send_multicast failed\n");
            goto cleanup;
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (sockfd >= 0) close(sockfd);
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) close(i2c_fds[i]);
    }
    return rc;
}

