/*
 * AWM7300V mass airflow sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   AWM7300V SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   AWM7300V SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   AWM7300V VDD  -> 3.3 V
 *   AWM7300V GND  -> GND
 *
 * The AWM7300V is a 14-bit sensor; a zero-length I2C write generates a
 * start condition, the sensor responds with two bytes, the first of which
 * contains the two most-significant bits of the 14-bit flow value, and the
 * second contains the eight least-significant bits.  The 14-bit value is
 * masked from the first two bytes as follows:
 *
 *   flow_raw = ((first_byte & 0x3F) << 8) | second_byte
 *   flow_slpm = flow_raw * 0.001
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x40          /* AWM7300V default I2C address */
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1             /* seconds between samples */
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Issue a zero-length I2C write to generate a start condition and read
 * two bytes from the AWM7300V.  Returns 0 on success and fills *flow_slpm.
 * Returns -1 on persistent failure.
 */
static int read_airflow(int fd, float *flow_slpm)
{
    uint8_t buf[2];
    int     retries = 0;

    while (retries < MAX_RETRIES) {
        ssize_t n = read(fd, buf, sizeof(buf));

        if (n == (ssize_t)sizeof(buf)) {
            uint16_t raw = ((uint16_t)(buf[0] & 0x3F) << 8) | buf[1];
            *flow_slpm = (float)raw * 0.001f;
            return 0;
        }

        if (n < 0) {
            fprintf(stderr, "I2C read error: %s (attempt %d/%d)\n",
                    strerror(errno), retries + 1, MAX_RETRIES);
        } else {
            fprintf(stderr, "I2C short read: got %zd of 2 bytes (attempt %d/%d)\n",
                    n, retries + 1, MAX_RETRIES);
        }

        retries++;
        if (retries < MAX_RETRIES) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, float flow_slpm)
{
    time_t     t;
    struct tm  tm_info;
    char       ts[32];

    t = time(NULL);
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, %.3f SLPM\n", ts, flow_slpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, AWM7300V_ADDR);
    if (g_i2c_fd < 0) {
        /* ENXIO (no sensor at 0x40) is a normal exit path; EIO is a hard error. */
        if (errno == ENXIO) {
            fprintf(stderr, "No AWM7300V sensor found at 0x%02X on %s.\n",
                    AWM7300V_ADDR, I2C_BUS);
            fprintf(stderr, "Check wiring and that the sensor is powered.\n");
        } else {
            fprintf(stderr, "Fatal I2C initialization error.\n");
        }
        return EXIT_FAILURE;
    }

    if (log_open(LOG_FILE) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("AWM7300V airflow logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float flow_slpm;

        if (read_airflow(g_i2c_fd, &flow_slpm) == 0) {
            log_data(g_log_fp, flow_slpm);
            printf("Flow: %.3f SLPM\n", flow_slpm);
        } else {
            fprintf(stderr, "Failed to read airflow after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

