/*
 * AS7341 10-Channel Light/Color Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Reads spectral and lux data from an Adafruit AS7341 sensor on /dev/i2c-1
 * every 5 seconds, appending timestamped CSV lines to spectral_log.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o as7341_reader as7341_reader.c
 * Run:    ./as7341_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- AS7341 register definitions (per Adafruit AS7341 datasheet) ---- */
#define AS7341_I2C_ADDR        0x44
#define AS7341_REG_ENABLE      0x80
#define AS7341_REG_ATIME       0x81
#define AS7341_REG_WTIME       0x83
#define AS7341_REG_ID          0x92
#define AS7341_REG_STATUS      0x93
#define AS7341_REG_CDATAL      0x94
#define AS7341_REG_CDATAH      0x95
#define AS7341_REG_RDATAL      0x96
#define AS7341_REG_RDATAH      0x97
#define AS7341_REG_GDATAL      0x98
#define AS7341_REG_GDATAH      0x99
#define AS7341_REG_BDATAL      0x9A
#define AS7341_REG_BDATAH      0x9B
#define AS7341_REG_F1DATAL     0x9C
#define AS7341_REG_F1DATAH     0x9D
#define AS7341_REG_F2DATAL     0x9E
#define AS7341_REG_F2DATAH     0x9F
#define AS7341_REG_F3DATAL     0xA0
#define AS7341_REG_F3DATAH     0xA1
#define AS7341_REG_F4DATAL     0xA2
#define AS7341_REG_F4DATAH     0xA3
#define AS7341_REG_F5DATAL     0xA4
#define AS7341_REG_F5DATAH     0xA5
#define AS7341_REG_F6DATAL     0xA6
#define AS7341_REG_F6DATAH     0xA7
#define AS7341_REG_F7DATAL     0xA8
#define AS7341_REG_F7DATAH     0xA9
#define AS7341_REG_F8DATAL     0xAA
#define AS7341_REG_F8DATAH     0xAB
#define AS7341_REG_NIRDATAL    0xAC
#define AS7341_REG_NIRDATAH    0xAD
#define AS7341_REG_CFG1        0x8A
#define AS7341_REG_CFG2        0x8B
#define AS7341_REG_CFG3        0x8C
#define AS7341_REG_CFG4        0x8D
#define AS7341_REG_CFG5        0x8E
#define AS7341_REG_CFG6        0x8F

#define AS7341_ENABLE_PON      0x01
#define AS7341_ENABLE_AEN      0x02
#define AS7341_ENABLE_WEN      0x08
#define AS7341_ENABLE_SP_EN    0x10
#define AS7341_ENABLE_GP_EN    0x20
#define AS7341_ENABLE_BD_EN    0x40
#define AS7341_ENABLE_F1_EN    0x80

#define AS7341_STATUS_AVALID   0x01
#define AS7341_STATUS_WVALID   0x02
#define AS7341_STATUS_SPVALID  0x04
#define AS7341_STATUS_GPVALID  0x08
#define AS7341_STATUS_BDVALID  0x10
#define AS7341_STATUS_F1VALID  0x20

#define AS7341_ID_VALUE        0x44

#define LOG_FILE_NAME          "spectral_log.csv"
#define SAMPLE_INTERVAL_SEC    5

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; cleanup happens in main()           */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, value, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_l, uint16_t *value)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg_l, &lo) != 0)
        return -1;
    if (i2c_read_reg8(fd, reg_l + 1, &hi) != 0)
        return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int as7341_init(int fd)
{
    uint8_t id = 0;

    /* Verify device identity */
    if (i2c_read_reg8(fd, AS7341_REG_ID, &id) != 0) {
        fprintf(stderr, "Cannot read AS7341 ID register — sensor absent or bus error.\n");
        return -1;
    }
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "AS7341 ID mismatch: got 0x%02X, expected 0x%02X.\n",
                id, AS7341_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, AS7341_ENABLE_PON) != 0)
        return -1;
    usleep(10000);  /* 10 ms settle after PON */

    /* Set integration time (ATIME) to 2.4 ms (0x00) */
    if (i2c_write_reg8(fd, AS7341_REG_ATIME, 0x00) != 0)
        return -1;

    /* Set wait time (WTIME) to 2.4 ms (0x00) */
    if (i2c_write_reg8(fd, AS7341_REG_WTIME, 0x00) != 0)
        return -1;

    /*
     * CFG6 (0x8F):
     *   SMUX[3:0] = 0x00  -> F1-F8, Clear, NIR channels enabled
     *   S_EN      = 1    -> spectral measurement enabled
     *   G_EN      = 1    -> green channel enabled
     *   B_EN      = 1    -> blue channel enabled
     *   F1_EN     = 1    -> F1 channel enabled
     */
    if (i2c_write_reg8(fd, AS7341_REG_CFG6,
                      AS7341_ENABLE_SP_EN | AS7341_ENABLE_GP_EN |
                      AS7341_ENABLE_BD_EN | AS7341_ENABLE_F1_EN) != 0)
        return -1;

    /*
     * CFG1 (0x8A):
     *   ALS_EN    = 1    -> ALS enabled
     *   ALS_SEL   = 0    -> ALS gain = 1x
     *   ALS_INT   = 0    -> ALS interrupt disabled
     *   ALS_PERS  = 0x00 -> ALS persistence = 1 sample
     */
    if (i2c_write_reg8(fd, AS7341_REG_CFG1, 0x01) != 0)
        return -1;

    /*
     * CFG2 (0x8B):
     *   ALS_PS_EN = 0    -> proximity disabled
     *   ALS_PS_SEL= 0    -> proximity gain = 1x
     *   ALS_PS_INT= 0    -> proximity interrupt disabled
     *   ALS_PS_PERS=0x00 -> proximity persistence = 1 sample
     */
    if (i2c_write_reg8(fd, AS7341_REG_CFG2, 0x00) != 0)
        return -1;

    /*
     * CFG3 (0x8C):
     *   ALS_PS_LED21 = 0  -> LED2 current = 10 mA
     *   ALS_PS_LED3  = 0  -> LED3 current = 10 mA
     *   ALS_PS_LED1  = 0  -> LED1 current = 10 mA
     *   ALS_PS_DRIVE = 0  -> LED drive strength = 100 mA
     */
    if (i2c_write_reg8(fd, AS7341_REG_CFG3, 0x00) != 0)
        return -1;

    /*
     * CFG4 (0x8D):
     *   ALS_PS_LED21_SEL = 0  -> LED21 select = proximity
     *   ALS_PS_LED3_SEL  = 0  -> LED3 select  = proximity
     *   ALS_PS_LED1_SEL  = 0  -> LED1 select  = proximity
     *   ALS_PS_LED_DRIVE = 0  -> LED drive strength = 100 mA
     */
    if (i2c_write_reg8(fd, AS7341_REG_CFG4, 0x00) != 0)
        return -1;

    /*
     * CFG5 (0x8E):
     *   ALS_PS_LED21_CURRENT = 0  -> LED21 current = 10 mA
     *   ALS_PS_LED3_CURRENT  = 0  -> LED3 current  = 10 mA
     *   ALS_PS_LED1_CURRENT  = 0  -> LED1 current  = 10 mA
     *   ALS_PS_DRIVE_CURRENT = 0  -> LED drive strength = 100 mA
     */
    if (i2c_write_reg8(fd, AS7341_REG_CFG5, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                    */
/* ------------------------------------------------------------------ */
static int as7341_read_spectral(int fd, uint16_t *f1, uint16_t *f2,
                                uint16_t *f3, uint16_t *f4,
                                uint16_t *f5, uint16_t *f6,
                                uint16_t *f7, uint16_t *f8,
                                uint16_t *clear, uint16_t *nir)
{
    if (i2c_read_reg16(fd, AS7341_REG_F1DATAL, f1)   != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F2DATAL, f2)   != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F3DATAL, f3)   != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F4DATAL, f4)   != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F5DATAL, f5)   != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F6DATAL, f6)   != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F7DATAL, f7)   != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F8DATAL, f8)   != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_CDATAL,  clear) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_NIRDATAL, nir)  != 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Lux approximation (simplified)                                       */
/* ------------------------------------------------------------------ */
static float calculate_lux(uint16_t clear, uint16_t nir)
{
    /*
     * Simplified lux calculation for the AS7341.
     * The datasheet provides a more accurate formula for the
     * specific LED drive strength and current settings used.
     */
    float ratio = (float)clear / (float)nir;
    if (ratio <= 0.0f)
        return 0.0f;
    if (ratio <= 0.52f)
        return 0.0315f * clear - 0.0534f * clear * ratio;
    if (ratio <= 0.65f)
        return 0.0224f * clear - 0.02916f * clear * ratio;
    if (ratio <= 0.80f)
        return 0.0157f * clear - 0.0180f * clear * ratio;
    if (ratio <= 1.30f)
        return 0.00338f * clear - 0.00267f * clear * ratio;
    return 0.00146f * clear - 0.00115f * clear * ratio;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t f1, uint16_t f2, uint16_t f3,
                     uint16_t f4, uint16_t f5, uint16_t f6,
                     uint16_t f7, uint16_t f8, uint16_t clear,
                     uint16_t nir, float lux)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux);
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Power off the sensor */
        (void)i2c_write_reg8(g_i2c_fd, AS7341_REG_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(/dev/i2c-1)");
        return 1;
    }

    /* Acquire the AS7341 slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_ID_VALUE) < 0) {
        perror("ioctl(I2C_SLAVE, AS7341_ID_VALUE)");
        cleanup();
        return 1;
    }

    /* Initialize the sensor */
    if (as7341_init(g_i2c_fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        cleanup();
        return 1;
    }

    /* Open the log file in append mode */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        cleanup();
        return 1;
    }

    /* Write the CSV header if the file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        fprintf(g_log_fp, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
        fflush(g_log_fp);
    }

    printf("AS7341 spectral sensor logging started.\n");
    printf("Logging to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME, SAMPLE_INTERVAL_SEC);

    /* Main sampling loop */
    while (g_running) {
        uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;

        if (as7341_read_spectral(g_i2c_fd, &f1, &f2, &f3, &f4,
                                  &f5, &f6, &f7, &f8, &clear, &nir) != 0) {
            fprintf(stderr, "Error reading spectral data.\n");
            break;
        }

        float lux = calculate_lux(clear, nir);

        if (log_data(g_log_fp, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux) != 0) {
            fprintf(stderr, "Error logging data.\n");
            break;
        }

        /* Sleep for the sample interval, checking g_running every second */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

