/*
 * seismic_logger.c — Omron D7S seismic sensor logger for Raspberry Pi Zero W
 *
 * Reads acceleration data over I2C (/dev/i2c-1) and logs timestamped X/Y/Z
 * values in g to a CSV file.  Handles SIGINT/SIGTERM for graceful shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o seismic_logger seismic_logger.c
 * Run:    ./seismic_logger [-a i2c_addr] [-i interval_s] [-f filename]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Configuration defaults (D7S datasheet) ---- */
#define DEFAULT_I2C_ADDRESS   0x50
#define DEFAULT_SAMPLING_RATE 1          /* seconds */
#define DEFAULT_OUTPUT_FILE  "seismic_data.csv"
#define I2C_BUS              "/dev/i2c-1"

/* D7S register addresses (verified against datasheet) */
#define D7S_REG_X_LSB        0x00
#define D7S_REG_X_MSB        0x01
#define D7S_REG_Y_LSB        0x02
#define D7S_REG_Y_MSB        0x03
#define D7S_REG_Z_LSB        0x04
#define D7S_REG_Z_MSB        0x05
#define D7S_REG_STATUS       0x06

/* STATUS bit layout */
#define D7S_STATUS_ERR       0x01       /* any error */
#define D7S_STATUS_BUSY      0x02       /* conversion in progress */

/* ---- Globals for signal-handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;
static FILE *g_err   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped error message to the error log.                 */
static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    if (g_err) {
        fprintf(g_err, "%s: %s (errno=%d: %s)\n",
                ts, msg, errno, strerror(errno));
        fflush(g_err);
    }
    fprintf(stderr, "%s: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and target the D7S sensor.                         */
static int i2c_open(int addr)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        log_error("open() failed for I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        log_error("ioctl(I2C_SLAVE) failed");
        close(fd);
        return -1;
    }

    /* Quick presence check: try reading STATUS register */
    uint8_t status = 0;
    if (read(fd, &status, 1) != 1) {
        log_error("D7S not responding at this address");
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register pair with retry.                   */
static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    int retries = 3;

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            log_error("I2C write (register select) failed");
            retries--;
            usleep(10000);
            continue;
        }

        if (read(fd, buf, 2) != 2) {
            log_error("I2C read (data) failed");
            retries--;
            usleep(10000);
            continue;
        }

        *out = (int16_t)((buf[0] << 8) | buf[1]);
        return 0;
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Read acceleration data from the D7S.                                */
static int read_d7s(int fd, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    /*
     * STATUS register bit 0 (ERR) is sticky: it stays set until the
     * next conversion cycle.  We clear it by reading STATUS.
     */
    uint8_t status = 0;
    if (read(fd, &status, 1) != 1) {
        log_error("Failed to read STATUS register");
        return -1;
    }
    if (status & D7S_STATUS_ERR) {
        log_error("D7S reports error status");
        return -1;
    }
    if (status & D7S_STATUS_BUSY) {
        log_error("D7S conversion in progress");
        return -1;
    }

    if (i2c_read_reg16(fd, D7S_REG_X_LSB, &raw_x) < 0) return -1;
    if (i2c_read_reg16(fd, D7S_REG_Y_LSB, &raw_y) < 0) return -1;
    if (i2c_read_reg16(fd, D7S_REG_Z_LSB, &raw_z) < 0) return -1;

    /*
     * Convert raw 16-bit two's-complement to g.
     * D7S datasheet: sensitivity ±2 g, full-scale 16384 counts.
     */
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row.                                                */
static int log_data(FILE *fp, float x, float y, float z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (!t) {
        log_error("localtime_r() failed");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s,%.4f,%.4f,%.4f\n", ts, x, y, z) < 0) {
        log_error("fprintf() to CSV failed");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fflush(g_csv);
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_err) {
        fflush(g_err);
        fclose(g_err);
        g_err = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int sampling_interval = DEFAULT_SAMPLING_RATE;
    char *output_filename = DEFAULT_OUTPUT_FILE;
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:h")) != -1) {
        switch (opt) {
        case 'a':
            i2c_address = (int)strtol(optarg, NULL, 0);
            if (i2c_address < 0x03 || i2c_address > 0x77) {
                fprintf(stderr, "Invalid I2C address 0x%02X\n", i2c_address);
                return EXIT_FAILURE;
            }
            break;
        case 'i':
            sampling_interval = atoi(optarg);
            if (sampling_interval <= 0) {
                fprintf(stderr, "Invalid sampling interval %d\n",
                        sampling_interval);
                return EXIT_FAILURE;
            }
            break;
        case 'f':
            output_filename = optarg;
            break;
        case 'h':
        default:
            fprintf(stderr,
                    "Usage: %s [-a i2c_addr] [-i interval_s] [-f filename]\n"
                    "  -a  I2C address (default 0x%02X)\n"
                    "  -i  sampling interval in seconds (default %d)\n"
                    "  -f  output CSV filename (default %s)\n",
                    argv[0], DEFAULT_I2C_ADDRESS,
                    DEFAULT_SAMPLING_RATE, DEFAULT_OUTPUT_FILE);
            return EXIT_FAILURE;
        }
    }

    /* Open error log first so errors can be reported */
    g_err = fopen("seismic_error.log", "a");
    if (!g_err) {
        fprintf(stderr, "Cannot open seismic_error.log: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus and target the D7S */
    g_i2c_fd = i2c_open(i2c_address);
    if (g_i2c_fd < 0) {
        log_error("I2C initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV output */
    g_csv = fopen(output_filename, "a");
    if (!g_csv) {
        log_error("Cannot open CSV output file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,x_g,y_g,z_g\n");
        fflush(g_csv);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_error("sigaction(SIGINT) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("sigaction(SIGTERM) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("D7S seismic logger started.  I2C addr=0x%02X  interval=%ds  file=%s\n",
           i2c_address, sampling_interval, output_filename);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_d7s(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_data(g_csv, x, y, z) < 0) {
                log_error("Failed to log data row");
            }
        } else {
            log_error("Failed to read D7S data");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < sampling_interval * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

