        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < sampling_interval * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

