code:
/*
 * AWR1642 mmWave radar UART reader for Raspberry Pi 3 Model B+
 *
 * Reads the AWR1642 data stream over /dev/ttyS0 at 921600 baud,
 * synchronizes on the 8-byte little-endian magic word, validates
 * TLV payloads, and logs range/velocity for each detected object
 * to radar_data.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o radar_reader radar_reader.c -lrt
 * Run:    ./radar_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>

#define UART_DEVICE      "/dev/ttyS0"
#define BAUD_RATE        B921600
#define CSV_FILENAME     "radar_data.csv"
#define READ_BUF_SIZE    4096
#define MAGIC_WORD_SIZE  8

/* AWR1642 magic word (8 bytes, little-endian) */
static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {
    0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07
};

/* TLV types (from mmwdemo_output.h) */
#define TLV_TYPE_DETECTED_POINTS 1
#define TLV_TYPE_RANGE_PROFILE   2
#define TLV_TYPE_NOISE_PROFILE   3
#define TLV_TYPE_AZIMUTH_HEATMAP 4
#define TLV_TYPE_RANGE_DOPPLER   5
#define TLV_TYPE_STATS           6
#define TLV_TYPE_DETECTED_POINTS_EXT 7

/* Detected point structure (from mmwdemo_output.h) */
#pragma pack(push, 1)
typedef struct {
    uint16_t rangeIdx;
    uint16_t dopplerIdx;
    uint16_t peakVal;
    uint16_t x;
    uint16_t y;
    uint16_t z;
} __attribute__((packed)) DetectedPoint;
#pragma pack(pop)

/* TLV header (from mmwdemo_output.h) */
#pragma pack(push, 1)
typedef struct {
    uint32_t type;
    uint32_t length;
} __attribute__((packed)) TLVHeader;
#pragma pack(pop)

/* Frame header (from mmwdemo_output.h) */
#pragma pack(push, 1)
typedef struct {
    uint32_t version;
    uint32_t totalPacketLen;
    uint32_t platform;
    uint32_t frameNumber;
    uint32_t timeCpuCycles;
    uint32_t numDetectedObj;
    uint32_t numTLVs;
    uint32_t subFrameNumber;
} __attribute__((packed)) FrameHeader;
#pragma pack(pop)

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_csv_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* UART initialization                                                 */
/* ------------------------------------------------------------------ */
static int init_uart(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag  = (tty.c_cflag & ~CSIZE) | CS8;   /* 8 data bits */
    tty.c_cflag |= (CLOCAL | CREAD);               /* enable receiver */
    tty.c_cflag &= ~(PARENB | PARODD);             /* no parity */
    tty.c_cflag &= ~CSTOPB;                        /* 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;                       /* no hardware flow control */

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;  /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* CSV file initialization                                              */
/* ------------------------------------------------------------------ */
static int init_csv(const char *filename)
{
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error opening CSV file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "timestamp,object_index,range_m,velocity_mps\n") < 0) {
        fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing CSV header: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv_fp) {
        fflush(g_csv_fp);
        fclose(g_csv_fp);
        g_csv_fp = NULL;
    }
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Read exactly n bytes from UART                                       */
/* ------------------------------------------------------------------ */
static int read_exact(int fd, uint8_t *buf, size_t n)
{
    size_t total = 0;
    while (total < n) {
        ssize_t r = read(fd, buf + total, n - total);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "UART read: unexpected EOF (sensor disconnected?)\n");
            return -1;
        }
        total += (size_t)r;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Synchronize on magic word                                           */
/* ------------------------------------------------------------------ */
static int sync_magic_word(int fd)
{
    uint8_t byte;
    size_t matched = 0;

    while (g_running) {
        ssize_t r = read(fd, &byte, 1);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "UART read error during sync: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "UART sync: unexpected EOF\n");
            return -1;
        }

        if (byte == MAGIC_WORD[matched]) {
            matched++;
            if (matched == MAGIC_WORD_SIZE) {
                return 0;  /* success */
            }
        } else {
            matched = 0;
            /*
             * If the first byte doesn't match, check if the second byte
             * matches the first byte of the magic word.
             */
            if (byte == MAGIC_WORD[0]) {
                matched = 1;
            }
        }
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Process one complete frame                                          */
/* ------------------------------------------------------------------ */
static int process_frame(int fd)
{
    FrameHeader hdr;
    if (read_exact(fd, (uint8_t *)&hdr, sizeof(hdr)) != 0)
        return -1;

    /* Validate frame length (sanity check) */
    if (hdr.totalPacketLen < sizeof(hdr) || hdr.totalPacketLen > READ_BUF_SIZE) {
        fprintf(stderr, "Frame length %u out of range\n", hdr.totalPacketLen);
        return -1;
    }

    size_t remaining = hdr.totalPacketLen - sizeof(hdr);
    uint8_t *payload = malloc(remaining);
    if (!payload) {
        fprintf(stderr, "Memory allocation failed for payload\n");
        return -1;
    }

    if (read_exact(fd, payload, remaining) != 0) {
        free(payload);
        return -1;
    }

    size_t offset = 0;
    int    obj_idx = 0;

    for (uint32_t i = 0; i < hdr.numTLVs && offset + sizeof(TLVHeader) <= remaining; i++) {
        TLVHeader tlv;
        memcpy(&tlv, payload + offset, sizeof(tlv));
        offset += sizeof(TLVHeader);

        if (offset + tlv.length > remaining) {
            fprintf(stderr, "TLV length %u exceeds payload\n", tlv.length);
            break;
        }

        if (tlv.type == TLV_TYPE_DETECTED_POINTS) {
            size_t num_points = tlv.length / sizeof(DetectedPoint);
            for (size_t p = 0; p < num_points; p++) {
                DetectedPoint pt;
                memcpy(&pt, payload + offset + p * sizeof(pt), sizeof(pt));

                /*
                 * Range and velocity are derived from the point indices
                 * (simplified linear mapping for demonstration).
                 * A real implementation would use the range/doppler tables
                 * from the chirp configuration.
                 */
                float range_m    = (float)pt.rangeIdx * 0.043f;  /* 4.3 cm per bin */
                float velocity_mps = (float)pt.dopplerIdx * 0.043f; /* 4.3 cm/s per bin */

                time_t now = time(NULL);
                struct tm tm_info;
                char ts[32];
                localtime_r(&now, &tm_info);
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

                if (fprintf(g_csv_fp, "%s,%d,%.3f,%.3f\n", ts, obj_idx, range_m, velocity_mps) < 0) {
                    fprintf(stderr, "Error writing to CSV: %s\n", strerror(errno));
                }
                obj_idx++;
            }
        }

        offset += tlv.length;
    }

    free(payload);

    if (fflush(g_csv_fp) != 0) {
        fprintf(stderr, "Error flushing CSV: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        return EXIT_FAILURE;
    }

    if (init_csv(CSV_FILENAME) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_csv_fp = fopen(CSV_FILENAME, "a");
    if (!g_csv_fp) {
        fprintf(stderr, "Error opening CSV file %s for append: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("AWR1642 radar reader started on %s @ 921600 baud.\n", UART_DEVICE);
    printf("Logging to %s. Press Ctrl+C to stop.\n", CSV_FILENAME);

    while (g_running) {
        if (sync_magic_word(g_uart_fd) != 0) {
            if (g_running) {
                fprintf(stderr, "Failed to synchronize on magic word.\n");
            }
            break;
        }

        if (process_frame(g_uart_fd) != 0) {
            if (g_running) {
                fprintf(stderr, "Frame processing failed.\n");
            }
            break;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

