#define LINE_BUF_SIZE 256
#define READ_TIMEOUT_SEC 2
#define INTER_BYTE_TIMEOUT_SEC 0
#define INTER_BYTE_TIMEOUT_USEC 500000

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_iflag &= ~IGNBRK;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void parse_line(const char *line, time_t *timestamp, float *range) {
    char *endptr;
    errno = 0;
    *timestamp = strtol(line, &endptr, 10);
    if (errno != 0 || endptr == line) {
        fprintf(stderr, "Error parsing timestamp: %s\n", strerror(errno));
        return;
    }

    if (*endptr != ',') {
        fprintf(stderr, "Invalid format: missing comma after timestamp\n");
        return;
    }

    errno = 0;
    *range = strtof(endptr + 1, &endptr);
    if (errno != 0 || endptr == (line + strlen(line))) {
        fprintf(stderr, "Error parsing range: %s\n", strerror(errno));
        return;
    }
}

static void log_detection(time_t timestamp, float range) {
    struct tm *tm_info = localtime(&timestamp);
    if (tm_info == NULL) {
        fprintf(stderr, "Error converting timestamp to local time\n");
        return;
    }

    char time_str[64];
    if (strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    printf("Timestamp: %s, Range: %.2f meters\n", time_str, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (g_uart_fd < 0) {
        return EXIT_FAILURE;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[256];

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = READ_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int ret = select(g_uart_fd + 1, &readfds, NULL, NULL, &timeout);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error in select(): %s\n", strerror(errno));
            break;
        }

        if (ret == 0) {
            fprintf(stderr, "Timeout: no data received from sensor for %d seconds\n", READ_TIMEOUT_SEC);
            continue;
        }

        ssize_t bytes_read = read(g_uart_fd, read_buf, sizeof(read_buf) - 1);
        if (bytes_read < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            break;
        }

        if (bytes_read == 0) {
            fprintf(stderr, "UART closed unexpectedly\n");
            break;
        }

        read_buf[bytes_read] = '\0';

        for (ssize_t i = 0; i < bytes_read; i++) {
            char c = read_buf[i];

            if (c == '\n') {
                if (line_len > 0) {
                    line_buf[line_len] = '\0';
                    time_t timestamp;
                    float range;
                    parse_line(line_buf, &timestamp, &range);
                    log_detection(timestamp, range);
                    line_len = 0;
                }
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line buffer overflow, discarding line\n");
                    line_len = 0;
                }
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

