#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define LEFT_SENSOR_PIN   4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27

#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE   B115200

static volatile sig_atomic_t program_running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART device %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting UART attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting UART attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int send_uart_message(int fd, const char *message) {
    size_t len = strlen(message);
    ssize_t written = write(fd, message, len);
    if (written < 0) {
        fprintf(stderr, "Error writing to UART: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)written != len) {
        fprintf(stderr, "Partial write to UART: %zd of %zu bytes\n", written, len);
        return -1;
    }
    return 0;
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        fprintf(stderr, "UART initialization failed. Exiting.\n");
        return 1;
    }

    printf("KY-033 Tracking Sensor Program\n");
    printf("Left: GPIO4, Middle: GPIO17, Right: GPIO27\n");
    printf("UART: %s at 115200 baud\n", UART_DEVICE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int middle = gpioRead(MIDDLE_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error reading GPIO pins\n");
            break;
        }

        log_sensor_data(left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            if (send_uart_message(uart_fd, "EMERGENCY STOP!\n") != 0) {
                fprintf(stderr, "Failed to send emergency stop message\n");
            }
        }

        usleep(100000);
    }

    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }

    printf("\nProgram terminated.\n");
    return 0;
}
